    let post_f = post_residual as f64;
    if post_f < mean_residual {
        score -= 0.3 * (mean_residual - post_f);
    } else {
        score += 0.3 * (post_f - mean_residual);
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: baseline that keeps it attractive only when fits are bad.
    if bin_residual == bin_capacity {
        score += 20.0;
        // Early in the stream, opening bins is cheap; late, prefer consolidation.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 * progress;
    }

    // Penalize leaving nearly-full bins with unusable slivers (< 10% capacity).
    if post_residual > 0 && post_residual < bin_capacity / 10 {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    if fit_ratio > 0.85 {
        score -= 30.0 * fit_ratio;
    } else if fit_ratio > 0.6 {
        score -= 12.0 * fit_ratio;
    }

    // Dead-space penalty: small post_residual that is too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // sliver of waste
    }

    // Lookahead: if the next item fits exactly in the post residual, reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here; mild penalty proportional to leftover.
            score += 4.0 * (post_residual as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a bin is generally expensive, but worthwhile
    // when current open bins are nearly full and the fit is poor.
    let is_new_bin = bin_residual == bin_capacity && bin_capacity > 0;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let open_pressure = open_bins_count as f64;
        // Base cost of a fresh bin.
        score += 35.0;
        // Later in the stream with few fitting options, new bin becomes more attractive
        // if the best existing fit would leave a lot of dead space.
        let waste_if_here = post_residual as f64; // for new bin this equals capacity - item
        let _ = waste_if_here;
        score -= 10.0 * progress;
        // If many bins are open with low mean residual, packing elsewhere is fine -> keep new bin costly.
        if mean_residual < 25.0 {
            score += 15.0;
        }
        // Discourage hoarding bins early.
        score += 2.0 * open_pressure.sqrt();
        // If the item is large relative to capacity, a fresh bin is a clean placement.
        if item_size as f64 > 0.7 * bin_capacity as f64 {
            score -= 18.0;
        }
    }

    // Slight preference for bins with residual already below mean (consolidate fullness).
    if bin_residual != bin_capacity {
        let diff = bin_residual as f64 - mean_residual;
        score += 0.05 * diff;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Base: post-residual, with smooth polynomial coupling to stream progress.
    // Early on, waste matters less; late, dead space is heavily penalized.
    let mut score = pr * (1.0 + 0.9 * progress * progress);

    // Non-linear coupling: post-residual squared scaled by progress — punishes
    // large leftovers increasingly as the stream matures.
    score += 0.35 * pr_norm * pr_norm * cap * (0.5 + progress);

    // Reward tight fits: interaction of item size with residual.
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fill * fill * (1.0 + progress);

    // Perfect fit bonus (smooth, non-piecewise).
    score -= 6.0 * (-pr as f64).exp();

    // Penalize leaving a residual that is small but unusable: coupling with
    // mean residual and next item lookahead.
    if next_item_size > 0 {
        let gap = (next_item_size as f64 - pr).max(0.0);
        score += 0.25 * gap * (1.0 + progress);
        // Reward residual that exactly accommodates the next item.
        let nr = next_item_size as f64;
        score -= 4.0 * (-((pr - nr) * (pr - nr)) / 50.0).exp();
    } else {
        // Last item: strongly prefer minimal leftover.
        score += 0.5 * pr;
    }

    // Last-chance bin: if this is the only bin that fits, reward using it
    // (smoothly, scaled by how many bins are open).
    if fitting_bins_count == 1 {
        score -= 8.0 + 2.0 * (open_bins_count as f64).ln().max(0.0);
    }

    // New-bin candidate: penalize opening a new bin unless post-residual
    // advantage is large; penalty eases as stream progresses.
    if bin_residual == bin_capacity {
        score += 15.0 * (1.0 - 0.5 * progress) + 0.3 * mean_residual;
    }

    // Mild penalty for spreading across too many open bins with high mean residual.
    score += 0.05 * (open_bins_count as f64) * (mean_residual / cap).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: items come in integer sizes 1..=100,
    // so classify post_residual by its residue class modulo 10 and by its
    // integer-division decade. Low-decade, low-residue leftovers are "dead space".
    let decade = post_residual / 10;
    let residue = post_residual % 10;

    // Penalize leftovers that fall in awkward residue classes (not multiples of 10):
    // these are unlikely to be exactly filled by future integer items.
    if residue != 0 {
        score += (10 - residue) as f64 * 0.6;
    }

    // Very small leftovers (< 10) are nearly unusable dead space.
    if post_residual < 10 && post_residual > 0 {
        score += 40.0;
    }

    // Reward tight fits: post_residual in the low decades means the bin is well packed.
    score -= (bin_capacity as f64 - decade as f64 * 10.0).max(0.0) * 0.0; // no-op guard
    score += decade as f64 * 1.5;

    // Lookahead coupling: if the next item exactly fills the post_residual,
    // strongly reward this bin (perfect chaining).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // Next item fits: reward proportional to how much would remain after it.
            let post2 = post_residual - next_item_size;
            score -= 8.0;
            if post2 % 10 == 0 {
                score -= 6.0;
            }
            score += post2 as f64 * 0.3;
        } else {
            // Next item does not fit here: mild penalty for blocking the chain.
            score += 5.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate (empty bin): make it attractive only when the current item
    // is large and open bins are already crowded; otherwise penalize opening bins.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        if item_size >= 50 || mean_residual < item_size as f64 * 0.5 {
            score -= 4.0 + 10.0 * progress;
        } else {
            score += 30.0;
        }
    }

    // Slight preference for bins whose residual deviates from the mean in a useful
    // (smaller) direction: pack the tightest bins first.
    let dev = mean_residual - bin_residual as f64;
    score += dev * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residual gaps too small for any realistic
    // future item are heavily penalized (super-linear in tightness).
    let gap = post_residual as f64;
    let dead_threshold = 10.0f64; // smallest plausible useful item footprint
    if gap < dead_threshold {
        score += (dead_threshold - gap) * 12.0; // unusable sliver -> strong penalty
    } else if gap < 25.0 {
        score += (25.0 - gap) * 2.5; // awkward mid-gap penalty
    }

    // Reward near-perfect fits (low post_residual relative to bin size).
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= 30.0 * (1.0 - 4.0 * fit_ratio).max(0.0);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: when many bins are open, prefer consolidating into
    // existing bins; when few are open, opening a new bin is cheaper.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * (mean_residual - gap).abs() * 0.3;

    // Lookahead: if next item fits the post-residual exactly, reward this placement.
    if next_item_size > 0 {
        if (post_residual as u32) == next_item_size {
            score -= 25.0;
        } else if post_residual as u32 > next_item_size {
            score -= 8.0;
        } else {
            score += (next_item_size - post_residual as u32) as f64 * 0.5;
        }
    }

    // Slight stream-progression tilt: later in the stream, be greedier about
    // filling existing bins rather than opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 4.0 * (gap / bin_capacity as f64);

    // New-bin candidate: neutral-ish baseline so it's chosen only when all
    // open bins would create dead space or are otherwise unattractive.
    if bin_residual == bin_capacity {
        score = 60.0 + pressure * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core: reward exact 2-step lookahead match (post_residual == next_item_size)
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).unsigned_abs();
        score += diff as f64 * 0.9;

        // Perfect 2-step fill: strong reward
        if diff == 0 {
            score -= 25.0;
        } else if diff <= 10 {
            score -= 8.0 * (1.0 - diff as f64 / 10.0);
        }

        // Penalize leaving residual too small for next item (dead space)
        if post_residual < next_item_size && post_residual > 0 {
            score += (next_item_size - post_residual) as f64 * 0.6;
        }
    } else {
        // Last item: prefer tightest fit
        score += 5.0;
    }

    // Relative to mean residual: prefer bins tighter than average
    score -= (mean_residual - post_residual as f64) * 0.35;

    // Penalize large post residual (wasted space) with mild nonlinearity
    let pr = post_residual as f64;
    score += 0.012 * pr * pr / bin_capacity as f64;

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: penalize mildly so it's chosen only when open bins fit poorly
    if bin_residual == bin_capacity {
        score += 18.0;
        // But if nothing else fits well (large dead-space risk elsewhere), allow opening
        if next_item_size > 0 && item_size >= 60 {
            score -= 6.0;
        }
    }

    // Late in stream: tighten packing, avoid opening new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 4.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (wasting little space).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Penalize large dead space asymmetrically: residuals too small for
    // typical future items are worthless.
    let dead = post_residual as f64;
    if dead < 10.0 {
        score += 0.0; // tiny leftover is fine
    } else if dead < 30.0 {
        score += 0.3 * (30.0 - dead); // moderate leftover mildly penalized
    } else {
        score += 0.15 * dead; // large leftover penalized but less per unit
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
            // extra reward if post-residual matches next item nearly exactly
            let gap = post_residual - next_item_size;
            score -= 10.0 / (1.0 + gap as f64);
        } else {
            score += 6.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: empty bin gets a base cost so it only wins
    // when open bins fit poorly.
    if bin_residual == bin_capacity {
        score += 18.0;
        // cheaper to open new bins early in the stream, expensive late
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 * progress;
        // if many bins already open, discourage spreading items thin
        score += 2.0 * open_bins_count as f64;
        // if next item is large, a fresh bin is more valuable
        if next_item_size > item_size {
            score -= 10.0;
        }
    }

    // Global state coupling: prefer bins whose residual is below the mean
    // (concentrate fullness) when many bins are open.
    let res = bin_residual as f64;
    if open_bins_count > 1 {
        if res < mean_residual {
            score -= 3.0 * (mean_residual - res) / bin_capacity as f64;
        } else {
            score += 3.0 * (res - mean_residual) / bin_capacity as f64;
        }
    }

    // Mild time-horizon term: early in stream, be greedy about tight fits;
    // later, favor consolidation.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * tightness * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = pr;

    // Smooth interaction: residual curvature weighted by progress
    let quad = x * x * (1.0 - x) * cap;
    score += (progress - 0.5) * quad * 0.8;

    // Dead-space penalty grows smoothly with progress
    score += (x * x) * cap * (0.3 + 0.5 * progress);

    // Reward tight fits (small post residual) more strongly later in stream
    score -= (1.0 - x) * (1.0 - x) * (10.0 + 20.0 * progress);

    // Last-chance bin bonus: strongly favor using it
    if fitting_bins_count == 1 {
        score -= 25.0 + 25.0 * progress;
    }

    // Lookahead: bonus if next item fits the post residual
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 8.0 + 12.0 * (1.0 - x);
    }

    // Slight penalty when this bin's residual is far below the mean residual
    score += (mean_residual - pr).max(0.0) * 0.15;

    // Mild penalty for opening new bins as stream progresses
    if bin_residual == bin_capacity {
        score += 5.0 + 30.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals in "usable" bands
    // (multiples of common item sizes 10..20 etc.).
    let pr = post_residual;
    let band = (pr / 10).min(9); // integer division threshold 0..9
    let band_bonus: f64 = match band {
        0 => 0.0,               // near-perfect fit: residual 0..9
        1 => 2.0,               // residual 10..19: fits a min item
        2 => 3.0,               // residual 20..29
        3 => 4.0,
        4 | 5 => 1.5,           // mid leftovers: mediocre
        6 | 7 => -1.0,          // large residual: wasteful use of this bin
        _ => 0.5,
    };
    score -= band_bonus;

    // Modulo coupling: residual divisible by 10 pairs well with typical items
    if pr % 10 == 0 && pr > 0 {
        score -= 2.5;
    }
    if pr % 5 == 0 && pr > 0 {
        score -= 0.8;
    }

    // Lookahead: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 && next_item_size <= pr {
        let slack = pr - next_item_size;
        score -= 6.0 - (slack as f64) * 0.1;
        // harmonic match: next item size in same decade class as residual
        if (next_item_size / 10) == (pr / 10) {
            score -= 2.0;
        }
    } else if next_item_size > pr {
        // next item won't fit here anyway; penalize leaving awkward residue
        score += (pr as f64) * 0.15;
    }

    // Last-chance bin: strongly favor using it to avoid opening a bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // current item is large and no tight fits exist among open bins.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // base penalty discourages proliferation
        score += 12.0;
        // large items pair with fresh bins well
        score -= (item_size as f64) * 0.12;
        // many open bins already: discourage yet another
        score += (open_bins_count as f64) * 0.7;
        // early stream: allow more bins
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= (1.0 - progress) * 4.0;
        // if next item is small, a fresh bin preserves flexibility
        if next_item_size > 0 && next_item_size < 30 {
            score -= 3.0;
        }
    }

    // Prefer bins whose residual is close to item size (tight fit)
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += tightness * 8.0;

    // Slight preference to spread load when mean residual is high
    score -= (bin_residual as f64 - mean_residual) * 0.05;

    // Penalize dead space beyond half capacity
    if pr > bin_capacity / 2 {
        score += (pr - bin_capacity / 2) as f64 * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest
    // plausible future item (<= 10) are pure waste. Quadratic penalty on
    // tiny gaps.
    if post_residual < 10 {
        score += 40.0 + (10 - post_residual) as f64 * 8.0;
    }

    // Reward near-perfect fits strongly (post_residual close to 0 but usable).
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual <= 5 {
        score -= 12.0;
    }

    // Prefer bins whose residual was already tight relative to the mean:
    // placing into a below-mean-residual bin concentrates fill.
    score -= (mean_residual - bin_residual as f64) * 0.35;

    // Open-bin pressure: many open bins -> favor consolidating into
    // existing bins rather than spreading.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: if this is the ONLY bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual,
    // reward creating that opportunity; if next item is large and would
    // not fit, slightly penalize.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size > post_residual {
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // New-bin candidate: only attractive when the item is large relative
    // to capacity or existing bins are very full on average.
    if bin_residual == bin_capacity {
        let fullness = 1.0 - mean_residual / bin_capacity as f64;
        score = 55.0 - fullness * 45.0 + (item_size as f64) * 0.2;
        if fitting_bins_count == 0 {
            score -= 60.0; // no alternative: must open new bin
        }
        if post_residual < 10 {
            score += 30.0; // would create dead space immediately
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer bins whose post_residual is small (tight fit)
    score = post_residual as f64 * 1.0;

    // Strong reward: next item fits EXACTLY into post_residual (perfect 2-step chain)
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            // Next item fits: reward proportional to how little slack remains after both items
            let after_next = (post_residual - next_item_size) as f64;
            score -= 25.0 - after_next * 0.4;
            // Bonus for near-perfect chain (small after_next)
            if after_next <= 5.0 {
                score -= 10.0;
            }
        } else {
            // Next item will NOT fit here: penalize more if post_residual is close but insufficient
            let gap = (next_item_size - post_residual) as f64;
            score += 5.0 + gap.min(20.0) * 0.6;
        }
    }

    // Penalize unusable dead space: post_residual smaller than min plausible item (1..100 unknown, so use relative scale)
    let dead_threshold = bin_capacity as f64 * 0.05;
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += (dead_threshold - post_residual as f64) * 1.5;
    }

    // Compare against mean residual: prefer bins with residual below mean (tighter bins get used first)
    score += (mean_residual - bin_residual as f64) * 0.15;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when current bin would leave large awkward residual
    if bin_residual == bin_capacity {
        // Neutral-ish baseline; make it slightly worse than a good fit but better than terrible fits
        score += 8.0;
        // Opening a new bin is fine early in stream when many items remain
        if total_items > 0 && (step_index as f64) / (total_items as f64) < 0.5 {
            score -= 4.0;
        }
    }

    // Slight preference to spread load when many bins are open and mean residual is high
    if open_bins_count > 4 && mean_residual > bin_capacity as f64 * 0.4 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits with a non-linear penalty on wasted space.
    let waste = post_residual as f64;
    if waste > 0.0 {
        score += (waste * waste) / (bin_capacity as f64);
    } else {
        score -= 25.0; // perfect fit bonus
    }

    // Lookahead coupling: if next item fits into the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + 0.25 * (next_item_size as f64);
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Dead space relative to the lookahead item: penalize proportionally.
        let dead = (next_item_size - post_residual) as f64;
        score += 0.35 * dead.min(50.0);
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New empty bin candidate: penalize opening a new bin, more when alternatives exist.
    if bin_residual == bin_capacity {
        score += 40.0 + 3.0 * (open_bins_count as f64);
        // But if the item is large and next item would fit the fresh bin, soften.
        if item_size > bin_capacity / 2 {
            score -= 15.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
    }

    // Time horizon: early in stream, be more selective (penalize mediocre fits);
    // late in stream, just close bins out.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 6.0 * progress;

    // Global state coupling: if mean residual across open bins is high, prefer
    // consolidating into fuller bins (low residual here).
    score += 0.10 * mean_residual * (1.0 - progress);

    // Prefer bins with less residual overall (fill fuller bins first).
    score += 0.15 * bin_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_ratio = item_size as f64 / cap;
    let next_fit = if next_item_size > 0 { next_item_size as f64 / cap } else { 0.0 };

    let mut score = pr;

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, tight fills are rewarded more aggressively; later, moderate
    // residuals are tolerated to keep bins usable.
    let progress_weight = 1.0 + progress * (1.0 - progress) * 4.0;
    score -= pr * pr / (cap * cap) * 40.0 * progress_weight;

    // Penalize dead space that cannot fit the next item (smooth quadratic).
    if next_item_size > 0 && pr < next_item_size as f64 {
        let gap = next_item_size as f64 - pr;
        score += gap * gap * 0.08;
    } else if next_item_size > 0 {
        // Reward bins whose leftover still accommodates the next item.
        score -= 6.0 * (1.0 - (pr / cap - next_fit).abs());
    }

    // Last-chance bonus: prefer using a bin that would otherwise be wasted.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 - fit_ratio);
    }

    // Mild penalty for opening new bins when many bins are already open
    // and residuals are high (encourage consolidation).
    if bin_residual == bin_capacity {
        let consolidation = mean_residual / cap;
        score += 12.0 * (1.0 - consolidation) * (1.0 - progress);
    }

    // Reward high fill fraction smoothly.
    score -= (fit_ratio * fit_ratio) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: quantize dead space into capacity fractions.
    let cap = bin_capacity as f64;
    let frac = post_residual as f64 / cap;
    // Penalize residuals that fall into "useless" harmonic classes (too small for typical items)
    // Class boundaries via integer division on capacity: 0-10, 11-25, 26-50, 51-75, 76-100
    let class = post_residual / 10; // harmonic class 0..=10
    match class {
        0 => score -= 25.0,          // perfect fit: dead space < 10 is excellent
        1 => score -= 12.0,          // 10..19 still decent
        2 => score += 4.0,           // 20..29 mediocre dead zone
        3 => score += 2.0,           // 30..39
        4 | 5 | 6 | 7 => score -= 3.0, // mid residuals often reusable
        _ => {}                       // large residual, roughly neutral
    }

    // Modulo coupling: residuals congruent to small multiples of 5 waste less space
    // for integer item sizes (many sizes are multiples of 5/10).
    if post_residual % 5 == 0 {
        score -= 2.5;
    }
    if post_residual % 10 == 0 {
        score -= 2.5;
    }

    // Lookahead harmony: does the next item fit into the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // next item fits exactly or nearly: reward harmonic match
            let slack = post_residual - next_item_size;
            if slack == 0 {
                score -= 30.0; // perfect two-step packing
            } else {
                score -= (next_item_size as f64) * 0.35;
                if slack % 5 == 0 { score -= 2.0; }
            }
        } else {
            // next item won't fit here: penalize more if this bin is the item's last chance
            score += 6.0;
        }
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 18.0;
    }

    // New-bin candidate handling: an empty bin should only win when alternatives are poor.
    if bin_residual == bin_capacity {
        // Neutral base for a fresh bin: its post_residual is huge, so base score is already high.
        // Add a mild opening cost that decays as the stream progresses.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 8.0 + 10.0 * (1.0 - progress);
        // If no existing bin fits, opening is fine: fitting_bins_count excludes new bin context,
        // so just keep the penalty moderate.
    }

    // Tightness reward: prefer bins that get "fuller" relative to capacity.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 8.0;

    // Mean residual coupling: if this bin's residual is far below the mean, it is a laggard
    // bin; using it consolidates space.
    let dev = mean_residual - post_residual as f64;
    score += 0.15 * dev; // lower residual than mean -> lower score -> favored

    // Small penalty on spreading across many open bins; encourage consolidation.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
