    // Base: quadratic dead-space penalty (stronger than parent's linear base)
    let mut score = post_norm * post_norm * 55.0 + post_norm * 18.0;

    // Tightness reward, stronger later in the stream
    let tightness = 1.0 - post_norm;
    score -= tightness * tightness * (1.0 + progress) * 35.0;

    // Lookahead: smooth Gaussian kernel rewarding post-residual close to next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post - nxt) / cap;
        score -= (-diff * diff * 450.0).exp() * 20.0 * (1.0 - progress * 0.5);
        if post < nxt {
            score += 5.0; // can't host next item
        }
    }

    // Last-chance bonus: only fitting bin strongly preferred over new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 28.0;
    } else if fitting_bins_count <= 3 && bin_residual < bin_capacity {
        score -= 6.0;
    }

    // New-bin candidate: base cost, cheaper early, expensive when many bins open
    if bin_residual == bin_capacity {
        score += 20.0;
        score += 22.0 * progress;
        score += 2.5 * open_bins_count as f64;
        // fresh bin valuable if next item is large and nothing fits it later
        if next_item_size > item_size {
            score -= 12.0;
        }
        // if few bins fit the current item, opening fresh is less attractive
        if fitting_bins_count >= 1 {
            score += 8.0;
        }
    }

    // Mean-residual coupling: cubic preference for bins below mean fill
    let mean_norm = mean_residual / cap;
    let mean_gap = mean_norm - post_norm;
    score += mean_gap * mean_gap * mean_gap * 18.0 * (0.5 + progress);

    // Mild spread penalty late
    score += (open_bins_count as f64).ln().max(0.0) * progress * 4.0;

    // Favor fuller bins
    score -= (1.0 - bin_residual as f64 / cap) * 10.0;

    score
}

