    // New-bin decision: open only when fragmentation is high and fits are poor.
    if bin_residual == bin_capacity {
        let frag = mean_residual / cap;
        let poor_fit = fitting_bins_count as f64 <= 1.0 + progress * 2.0;
        if poor_fit && frag > 0.24 + progress * 0.2 {
            score -= 9.0 * (1.0 - progress);
