    }
    if gap > 0.10 && gap < 0.22 && next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr > 0.0 && pr < nxt {
            score += (gap - 0.10) * 92.0 * (0.5 + progress);
        }
    }

    // Two-item lookahead: reward residuals that fit next item with tiny slack.
    if next_item_size > 0 && pr >= next_item_size as f64 {
        let pair = (pr - next_item_size as f64) / cap;
        if pair < 0.04 {
