    if gap >= 0.22 && gap < 0.35 && progress > 0.55 {
        score += (gap - 0.22) * 47.0 * (progress - 0.55) * 2.0;
    }

    // Dead-space penalty for large unusable residuals, scaled by stream stage.
    if gap >= 0.35 {
        score += (gap - 0.35) * 55.0 * (0.6 + progress * 0.6);
    }

    // Mild reward when residual still accommodates the mean upcoming demand.
    if next_item_size > 0 && pr > 0.0 {
        let slack = (pr - next_item_size as f64) / cap;
        if slack >= 0.12 && slack <= 0.30 && progress < 0.5 {
            score -= 3.0 * (1.0 - (slack - 0.12) / 0.18);
        }
    }

