    }

    // NEW: harmonic dead-space term — penalize residuals that no plausible
    // future item can use, weighted by how "lonely" the gap is relative to
    // the mean residual (detects stranded space across the stream).
    if gap > 0.05 {
        let stranded = (gap - mean_residual / cap).abs();
