    let mut score = post_residual as f64;

    // Exact fit: perfect closure, heavily rewarded.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Dead-space classes: post_residual in (0,10) is unusable for any item
    // (items >= 1 but smallest practical class is 10 in classic streams; treat
    // tiny residues as near-dead). Penalize proportionally.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 3.0;
    }

    // Harmonic class of post_residual modulo 10: residues that are multiples
    // of 10 are "reachable" by standard item sizes; odd/prime-ish residues
    // waste capacity. Penalize non-multiples of 5.
    let cls = post_residual % 10;
    if cls != 0 {
        score += 8.0;
        if cls == 5 {
            score -= 4.0; // half-class still usable
        }
    }

    // Lookahead: if the next item fits in the post residual, reward keeping
    // this bin usable for it.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= (next_item_size as f64) * 0.8;
            // harmonic match: next item exactly divides residual
            if post_residual % next_item_size.max(1) == 0 {
                score -= 15.0;
            }
        } else {
            // residual too small for next item: potential dead space
            score += (post_residual as f64).min(40.0) * 0.3;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 60.0;
    }

    // New-bin candidate (empty bin): post_residual = capacity - item_size.
    // Prefer opening a new bin only when the fit elsewhere would be terrible
    // (large residual waste). Give it a moderate baseline so tight fits in
    // existing bins still win.
    if bin_residual == bin_capacity {
        // baseline for fresh bin: its residual is large, so it loses unless
        // existing bins have bad fits; add small bonus scaled by stream progress
        score -= 20.0 + (step_index as f64 / (total_items.max(1) as f64)) * 10.0;
    }

    // Prefer bins with residual close to item size (tight fit reward).
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += tightness * 0.15;

    // Mild penalty for proliferating bins when mean residual is high.
    if open_bins_count > 1 && mean_residual > (bin_capacity as f64) * 0.5 {
        score += 5.0;
    }

    score
}

