        score += 6.0 * (1.0 - item_frac);
        if open_bins_count == 0 {
            score -= 20.0; // must open a bin anyway
        }
        // Late in the stream, avoid proliferating bins
        score += 10.0 * progress;
        // If many bins are open with slack, discourage a new one
        if mean_residual > item_size as f64 {
            score += 4.0;
        }
    }

    // Global pressure: when many open bins exist, prefer filling existing ones
    // (reduces bin count); when few bins, mild preference for consolidation too.
