pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early on: mild penalty for waste; late: strong penalty (waste matters more when stream is ending).
    let waste_coupling = post_residual as f64
        * (0.5 + 1.5 * progress * progress)
        * (1.0 + (post_residual as f64 / bin_capacity as f64) * progress);
    score += 0.3 * waste_coupling;

    // Reward perfect fits (post_residual == 0) with strong discount, amplified by progress.
    if post_residual == 0 {
        score -= 40.0 + 60.0 * progress;
    }

    // Reward tight fits: small post_residual relative to item size gets non-linear bonus.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64).powf(2.0);
    score -= 10.0 * tightness * (0.5 + progress);

    // Lookahead: if next item fits exactly in post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 15.0 * (1.0 - gap / bin_capacity as f64).powf(3.0);
    }
    // Penalize if post_residual is a tiny unusable sliver compared to next item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual < 10 {
        score += 8.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // When many bins are open, prefer consolidation into existing bins.
    let open_pressure = (open_bins_count as f64 / (open_bins_count as f64 + 5.0)).powf(2.0);
    score -= 5.0 * open_pressure;

    // Penalize bins whose residual deviates badly from the mean residual (keeps pool homogeneous).
    let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score += 6.0 * dev * dev;

    // New-bin candidate: penalize opening a new bin unless current bin fit is poor.
    if bin_residual == bin_capacity {
        let poor_fit = post_residual as f64 / bin_capacity as f64;
        score += 30.0 - 25.0 * (1.0 - poor_fit).powf(2.0) * (1.0 + progress);
    }

    score
}

