pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that can't fit even the smallest
    // future item (min size 1) are pure waste; residuals below a "useful gap"
    // threshold are heavily penalized.
    let dead_threshold = 12.0f64;
    if post_residual == 0 {
        score -= 30.0; // perfect fit is ideal
    } else if (post_residual as f64) < dead_threshold {
        // unusable sliver: penalize proportionally to how close to zero
        score += (dead_threshold - post_residual as f64) * 4.0;
    } else if (post_residual as f64) >= next_item_size as f64 && next_item_size > 0 {
        // residual can host the lookahead item: reward
        score -= 6.0;
    }

    // Exact-fit lookahead: residual exactly matches next item -> strong reward
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins rather than spreading out.
    score += open_bins_count as f64 * 0.8;

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin wastes the mean residual
    // of all open bins. Penalize the fresh-bin call by the aggregate waste.
    if bin_residual == bin_capacity {
        score += mean_residual * open_bins_count as f64 * 0.5 + 10.0;
        // but if the item barely fits anywhere (tight fit elsewhere), a fresh
        // bin may be fine — soften when item is large relative to capacity.
        let tightness = item_size as f64 / bin_capacity as f64;
        score -= tightness * 8.0;
    }

    // Slight progression term: later in the stream, closing bins tightly
    // matters more (less time to reuse residual space).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: huge reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: can the next item fit in the post residual?
    let next_fits = next_item_size > 0 && post_residual >= next_item_size;
    if next_item_size > 0 {
        if next_fits {
            // Reward proportional to how snugly the next item fits.
            let snug = (post_residual - next_item_size) as f64;
            score -= 50.0 - snug.min(50.0);
            // Chain bonus: next item then leaves room again for something small.
            if post_residual - next_item_size >= 10 {
                score -= 15.0;
            }
        } else if post_residual > 0 {
            // Dead space: next item cannot use what remains — penalize strongly.
            score += 40.0 + (post_residual as f64) * 0.5;
        }
    }

    // Relative-to-mean residual shaping: prefer bins whose post residual
    // sits below the current mean (concentrate space, keep big gaps usable).
    score += (post_residual as f64 - mean_residual) * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate handling: only attractive if it yields a near-perfect
    // fit (large item into fresh bin); otherwise discourage spreading.
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        if fill_ratio > 0.9 {
            score -= 300.0;
        } else {
            score += 30.0 + (1.0 - fill_ratio) * 50.0;
        }
    }

    // Mild late-stream consolidation: prefer reusing bins as stream ends.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 5.0;

    // Slight penalty per open bin to encourage closing bins out.
    score += open_bins_count as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let next = next_item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let post_norm = pr / cap;
    let fit_ratio = item_size as f64 / cap;
    let mut score = post_norm * post_norm * 55.0 + post_norm * 20.0;

    // ---- 2-step lookahead: gaussian coupling on chain tightness ----
    if next > 0.0 {
        let diff = (pr - next) / cap;
        score -= (-diff * diff * 450.0).exp() * 20.0 * (1.0 - progress * 0.5);
        if pr == next {
            score -= 12.0;
        } else if pr < next {
            // Dead space: leftover cannot fit the next item -> penalize gap.
            score += (next - pr) / cap * 30.0 * (1.0 - progress);
        }
        // Near-pair bonus: bin closes almost exactly with next item.
        if pr >= next {
            let pair = (pr - next) / cap;
            if pair < 0.04 {
                score -= 12.0 * (1.0 - pair / 0.04);
            } else if pair < 0.12 {
                score -= 6.0 * (1.0 - (pair - 0.04) / 0.08) * (0.6 + 0.4 * progress);
            }
        }
    }

    // Penalize tiny unusable slivers unless they exactly match the next item.
    if pr > 0.0 && pr < 10.0 && pr != next {
        score += 15.0;
    }

    // ---- Relative-to-mean coupling: favor tighter-than-average bins ----
    let tightness = mean_residual - bin_residual as f64;
    if tightness > 0.0 {
        score -= 0.2 * tightness;
    }

    // ---- New-bin candidate decision ----
    if bin_residual == bin_capacity {
        let frag = mean_residual / cap;
        let poor_fit = fitting_bins_count as f64 <= 1.0 + progress * 2.0;
        if fitting_bins_count <= 1 {
            score -= 6.0;
        } else if poor_fit && frag > 0.248 + progress * 0.2 {
            score -= 8.0 * (1.0 - progress);
        } else {
            score += 30.0 + 0.4 * mean_residual + 0.4 * open_bins_count as f64;
        }
    }

    // Exact / near-exact fit bonuses.
    if pr == 0.0 {
        score -= 15.0;
    } else if post_norm < 0.05 {
        score -= 10.0 * (1.0 - post_norm / 0.05);
    }

    // Grafted: sharp bonus for leaving a tiny gap (<10% of capacity).
    let gap = (bin_residual - item_size) as f64 / cap;
    if gap > 0.0 && gap < 0.10 {
        score -= (0.10 - gap) * 40.0;
    }
    // Mid-gap that next item cannot use: penalize.
    if gap > 0.10 && gap < 0.22 && next > 0.0 && pr > 0.0 && pr < next {
        score += (gap - 0.10) * 90.0 * (0.5 + progress);
    }
    if gap >= 0.22 && gap < 0.35 && progress > 0.55 {
        score += (gap - 0.22) * 45.0 * (progress - 0.55) * 2.0;
    }

    // Reward large items filling bins deeply.
    score -= fit_ratio * fit_ratio * 6.0;

    // Congestion pressure: deprioritize sloppy fits when many bins are open.
    if open_bins_count > 4 {
        score += (open_bins_count as f64 - 4.0) * 0.155 * post_norm;
    }

    // Late-stream consolidation: penalize moderately large residuals late.
    if progress > 0.7 && post_norm > 0.25 {
        score += (post_norm - 0.25) * 6.0 * (progress - 0.7) / 0.3;
    }

    // Last-chance bonus: prefer a bin that would otherwise be wasted.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 - fit_ratio);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
