pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = step_index as f64 / total_items.max(1) as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Lookahead: strongly reward bins whose post-residual still fits the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + 0.25 * post_residual as f64;
    }
    // Penalize post-residuals that are small but unusable (dead space trap).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 6.0 + 0.1 * (next_item_size - post_residual) as f64;
    }

    // Perfect / near-perfect fits get big rewards.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 10 {
        score -= 20.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 15.0;
    }

    // Penalize opening new bins when decent fits exist, more so early on.
    if is_new_bin {
        let pressure = if next_item_size > 0 { mean_residual / (next_item_size as f64) } else { mean_residual };
        score += 30.0 - 10.0 * progress;
        if pressure < 0.5 {
            score += 10.0; // residuals too small on average; new bin reasonable
        }
    } else {
        // Favor bins tighter than the mean residual (best-fit flavor).
        let diff = bin_residual as f64 - mean_residual;
        score += 0.05 * diff;
    }

    // Many open bins: prefer consolidating into existing ones.
    score += 0.05 * open_bins_count as f64 * (if is_new_bin { 1.0 } else { -1.0 });

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // Base: post-residual cost
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early on (progress ~ 0), large residuals are acceptable (bins can still fill).
    // Late (progress ~ 1), residual waste is more costly.
    let pr_norm = pr / cap;
    let coupling = pr_norm * pr_norm * (0.5 + progress) * cap;
    score += 0.8 * coupling;

    // Smooth penalty for leaving residual that cannot fit the next item,
    // scaled by remaining stream length (smoothly decaying urgency).
    if next_item_size > 0 {
        let gap = pr - next_item_size as f64;
        if gap > 0.0 {
            let urgency = (1.0 - progress).powi(2);
            score -= 0.5 * urgency * (1.0 - (gap / cap).powi(2)) * gap / cap * cap;
        } else {
            // Next item fits exactly in the post residual: reward smooth in gap size
            score -= 2.0 * (1.0 - progress) * (next_item_size as f64 / cap);
        }
    }

    // Last-chance bin: strong smooth reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - progress * 0.5);
    }

    // Slight preference for bins below mean residual (balance load), smooth quadratic
    score += 0.3 * (pr - mean_residual) * (pr - mean_residual) / cap;

    // Reward tight fits (small post_residual) with smooth quadratic bonus
    score -= 0.5 * (1.0 - pr_norm).powi(3) * item_size as f64 / cap * cap * 0.1;

    // Penalize new empty bin mildly unless residual landscape is tight
    if bin_residual == bin_capacity {
        let tightness = 1.0 - (mean_residual / cap);
        score += 5.0 + 10.0 * tightness * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
