pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: which capacity fraction band it lands in.
    // Small post_residuals are good (dense packing); large ones waste space.
    let pr = post_residual as f64;
    let frac = pr / cap; // 0..1

    // Integer-division thresholds on post_residual (harmonic bands):
    // band 0: pr < 10  (perfect leftovers)  reward strongly
    // band 1: 10..=25 (usable for small items) mild reward
    // band 2: 26..=49 (dead zone) penalize
    // band 3: >= 50  (half-empty bin) strong penalty
    let band = (post_residual / 10).min(5);
    let band_adjust: f64 = match band {
        0 => -18.0,
        1 => -8.0,
        2 => 6.0,
        3 => 14.0,
        4 => 20.0,
        _ => 24.0,
    };
    score += band_adjust;

    // Non-linear dead-space penalty: quadratic in fraction, tuned so pr=50 costs ~ +25.
    score += 100.0 * frac * frac;

    // Lookahead harmony: if next item fits exactly into the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            // how well the next item harmonizes with the leftover (mod-style closeness)
            let gap = post_residual - next_item_size;
            score -= 12.0 * (1.0 - gap as f64 / cap);
        } else {
            // next item cannot use this leftover: leftover risks becoming dead space
            let unusable = post_residual.min(next_item_size.saturating_sub(1)) as f64;
            score += 4.0 * (unusable / 80.0);
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin, unless the fit is terrible (post_residual large).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 0.5 * (item_size as f64);
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Prefer it only when the item is large and no good harmonics exist.
    if bin_residual == bin_capacity {
        // neutral base for a fresh bin; slight penalty so partial fills win by default
        score += 10.0;
        if item_size >= 60 && next_item_size > 0 && next_item_size + item_size > bin_capacity {
            // item is huge and next item can't pair with it anywhere: fresh bin is fine
            score -= 20.0;
        }
    }

    // Mean residual coupling: when open bins are already quite full on average,
    // filling this one further is valuable; when they're loose, waste matters less.
    score -= 0.15 * (mean_residual - 50.0);

    // Stream progression: late in the stream, avoid creating dead zones (endgame tightening).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 8.0 * progress * frac;

    // Modulo-arithmetic harmonic bonus: post_residual divisible by small classes
    // (5, 10, 20) tends to match common item sizes drawn from quantized distributions.
    if post_residual > 0 {
        if post_residual % 5 == 0 { score -= 3.0; }
        if post_residual % 10 == 0 { score -= 2.0; }
        if post_residual % 20 == 0 { score -= 2.0; }
    }

    // Perfect fit is always best.
    if post_residual == 0 {
        score -= 40.0;
    }

    score
}

