        score -= 1.5 * open_bins_count as f64;
    }

    // Mean residual coupling: prefer bins whose residual is below the mean
    // (filling the emptier-relative bins keeps a portfolio of large residuals).
    if bin_residual != bin_capacity {
        if (bin_residual as f64) < mean_residual {
            score -= 4.0;
        } else {
            score += 3.0;
        }
    }

    // Tight fit reward: ratio-based bonus for small waste relative to item size.
    let waste_ratio = post_residual as f64 / (bin_capacity as f64);
    score += 30.0 * waste_ratio * (1.0 - waste_ratio); // peaks mid-range, mild

    score
}

