            if rem_norm > 0.0 && rem_norm < 0.03 {
                score -= (0.03 - rem_norm) * 10.0 * (0.4 + progress);
            } else if rem_norm > 0.16 {
                score += (rem_norm - 0.16) * 8.0 * (0.5 + progress);
            }
        } else {
