pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Smooth polynomial coupling of post_residual with stream progress
    let progress_poly = progress * progress * (3.0 - 2.0 * progress); // smoothstep
    let coupling = norm_pr * norm_pr * (1.0 + 2.0 * progress_poly);

    let mut score = pr + 20.0 * coupling;

    // Reward tight fits more strongly as stream progresses
    let tightness = 1.0 - norm_pr;
    score -= item_size as f64 * tightness * (0.5 + progress);

    // Penalize dead space relative to next item lookahead
    if next_item_size > 0 {
        let gap = pr - next_item_size as f64;
        if gap > 0.0 {
            score += 0.3 * gap * gap / cap;
        } else {
            score -= 5.0; // next item fits too: strong bonus
        }
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    }

    // Mild penalty for spreading across many open bins late in stream
    score += 0.5 * (open_bins_count as f64).ln().max(0.0) * progress;

    // New-bin candidate: make it attractive only for large items or late stream
    if bin_residual == bin_capacity {
        let new_bin_bias = 10.0 - 15.0 * progress - 0.1 * item_size as f64;
        score += new_bin_bias;
    }

