}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post_residual (tight fit).
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 500.0;
    }

    // Harmonic class of post_residual: residues mod small integers.
    // Residuals that are "usable" by common item sizes get rewards.
    // Items 1..100, so residual r is reusable if r >= 1; but small
    // awkward residues (1..9) are near-dead space -> penalize.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // dead-space penalty for tiny unusable slivers
    }

    // Modulo-class bonus: residual that is a multiple of common granularities
    // (e.g. 10, 20, 25, 50) tends to be reusable by round-sized items.
    let r = post_residual;
    if r % 10 == 0 { score -= 15.0; }
    if r % 25 == 0 { score -= 10.0; }
    if r % 50 == 0 { score -= 10.0; }

    // Lookahead coupling: if next item fits exactly in post_residual,
    // strongly favor this bin (chained perfect fit).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 200.0;
        } else if next_item_size <= post_residual {
            // next item fits: reward proportionally to how well it fills
            let fill_after = (post_residual - next_item_size) as f64;
            score -= 60.0 * (1.0 - fill_after / cap);
        } else {
            // next item won't fit here: mild penalty proportional to gap
            let gap = (next_item_size - post_residual) as f64;
            score += 20.0 * (1.0 - gap / cap);
        }
    }

    // Last-chance logic: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate handling: empty bin gets base score = capacity.
    // Discourage opening a new bin when open bins give a decent fit;
    // encourage it when existing fits are wasteful.
    if bin_residual == bin_capacity {
        // New bin: neutral-ish score, penalized slightly so tight fits win.
        score += 30.0;
        // But if many bins are open with large mean residual, opening a new
        // bin spreads load poorly -> extra penalty.
        score += 0.5 * open_bins_count as f64;
        // If current fit would leave a big residual and next item is large,
        // a fresh bin becomes attractive: reduce new-bin score.
        if next_item_size > 0 && post_residual < next_item_size && post_residual < 30 {
            score -= 80.0;
        }
    } else {
        // Existing bin: reward using bins with low residual relative to mean.
        score -= 10.0 * (1.0 - (bin_residual as f64) / cap);
        // Mild penalty for proliferating bins when fit is loose.
        if pr > 50.0 {
            score += 15.0;
        }
    }

    // Stream progression: later in the stream, consolidate more aggressively
    // (avoid opening bins that will barely be used).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 40.0 * progress;
    } else {
        score -= 20.0 * progress;
    }

    // Mean-residual coupling: prefer bins below mean residual (tighter bins).
    score += 0.3 * (mean_residual - bin_residual as f64);

    score
}

