    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the smallest plausible item are worthless.
    let min_item = 1u32;
    if post_residual > 0 && post_residual < min_item.max(1) {
        score += 1000.0; // unreachable, but kept for safety
    }
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // hard dead space penalty
    } else if post_residual > 0 && post_residual < 20 {
        score += 25.0;
    }

    // Reward tight fits strongly (near-perfect packing).
    if post_residual == 0 {
        score -= 500.0;
    } else {
        let tightness = item_size as f64 / bin_residual as f64;
        score -= 40.0 * tightness * tightness;
