    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Next-item lookahead: favor bins whose leftover can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if post_residual > 0 {
            score += 8.0; // leftover blocks the next item
        }
    }

    // Open-bin pressure: with many open bins, prefer consolidating into existing bins
    // rather than spreading; with few bins, opening a new one is cheaper.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (0.5 + 0.5 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: attractive early / few bins, unattractive when many bins are open.
        score += pressure * 6.0 - 10.0;
