    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: accept only when this bin's fit is poor relative to mean residual.
    if bin_residual == bin_capacity {
        score = 60.0 + mean_residual * 0.3;
        if next_item_size > 0 && next_item_size as f64 >= mean_residual {
            score -= 30.0; // mean residual can serve the next item anyway
