    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a bin is attractive when existing
    // residuals are fragmented (mean residual high) or many bins are open.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        let pressure = (open_bins_count as f64).ln() + 1.0;
        // Prefer new bin when fragmentation is high; penalize early on.
        score = 30.0 + 40.0 * fragmentation - 15.0 * pressure + 20.0 * (1.0 - progress);
