    } else {
        // Prefer bins whose residual deviates from the mean (consolidate extremes).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score -= 2.5 * dev / (bin_capacity as f64);
        // Slight preference for fewer open bins (encourage closing bins).
        score -= 3.0 / (open_bins_count as f64 + 1.0);
        // Late in stream, be greedier about tight fits.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * progress * fit_ratio;
    }

    score
}

