            score += (0.08 - dead) * 16.0 * (1.0 - third * 0.5) * (0.5 + progress);
        }
    }

    // New bin that can host next item too.
    if bin_residual == bin_capacity && next_item_size > 0 && fitting_bins_count <= 3 {
        let nxt = next_item_size as f64;
        if item_size as f64 >= nxt * 0.95 {
            score -= 5.5 * (1.0 - progress * 0.5);
        }
    }

    // NEW: penalize leaving a residual that is slightly larger than the next
    // item but too small to host it again afterwards (dead-end pockets).
    if next_item_size > 0 && pr > 0.0 {
        let nxt = next_item_size as f64;
        let pocket = (pr - nxt) / cap;
        if pocket > 0.03 && pocket < 0.12 {
            score += pocket * 14.0 * (0.5 + progress);
        }
    }

    // NEW: reward bins whose post-residual is an exact multiple of the next
    // item size (chainable placements).
    if next_item_size > 1 && pr > 0.0 {
        let nxt = next_item_size as f64;
        let chains = (pr / nxt).floor();
        if chains >= 1.0 {
            let frac = pr - chains * nxt;
            if frac == 0.0 {
                score -= 6.0 * (0.5 + progress) * (1.0 - (chains / 4.0).min(1.0));
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let post_norm = pr / cap;
    let mut score = post_norm * post_norm * 56.5 + post_norm * 21.8;

    // Lookahead: gaussian reward when post_residual matches next item snugly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (pr - nxt) / cap;
        score -= (-diff * diff * 458.0).exp() * 20.2 * (1.0 - progress * 0.5);
        if pr < nxt {
            score += (nxt - pr) / cap * 30.5 * (1.0 - progress);
        }
    }

    // Near-perfect fills.
    if pr == 0 {
        score -= 15.2;
    } else if post_norm < 0.05 {
        score -= 10.2 * (1.0 - post_norm / 0.05);
    }

    let gap = (bin_residual - item_size) as f64 / cap;
    if gap > 0.0 && gap < 0.10 {
        score -= (0.10 - gap) * 40.5;
    }
    if gap > 0.10 && gap < 0.22 && next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr > 0.0 && pr < nxt {
            score += (gap - 0.10) * 90.5 * (0.5 + progress);
        }
    }
    if gap >= 0.22 && gap < 0.35 && progress > 0.55 {
        score += (gap - 0.22) * 45.5 * (progress - 0.55) * 2.0;
    }

    // Two-step lookahead: penalize dead space after placing next item.
    if next_item_size > 0 && gap > 0.12 {
        let nxt = next_item_size as f64;
        let nxt_gap = (gap * cap - nxt).max(0.0) / cap;
        if nxt_gap < 0.06 {
            score -= 9.0 * (1.0 - nxt_gap / 0.06) * (0.5 + progress);
        }
    }

    if fitting_bins_count > 2 {
        score += gap * 6.5 * ((fitting_bins_count.min(12) as f64 - 2.0) / 10.0);
    }

    // Deviation from mean residual.
    if pr > 0.0 {
        let dev = (mean_residual - pr) / cap;
        if dev > 0.05 {
            score += (dev - 0.05) * 12.0 * (0.4 + progress);
        } else if dev < -0.08 {
            score += (-dev - 0.08) * 6.0 * (1.0 - progress);
        }
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let size_pull = (item_size as f64 / cap) * 14.0;
        if fitting_bins_count <= 2 && gap > 0.0 {
            score -= (18.0 + size_pull) * (1.0 - progress * 0.6);
        } else {
            score += 8.0 + 6.0 * (1.0 - progress);
        }
    }

    // Snug post-residual bonus for next item.
    if next_item_size > 0 && pr > 0.0 {
        let nxt = next_item_size as f64;
        let snug = (pr - nxt) / cap;
        if snug >= 0.0 && snug < 0.04 {
            score -= (0.04 - snug) * 22.0 * (0.6 + progress * 0.6);
        }
    }

    // Consolidation pressure with many open bins.
    if open_bins_count > 8 {
        score += post_norm * 5.0 * ((open_bins_count.min(20) as f64 - 8.0) / 12.0);
    }

    // Remaining-after-next analysis.
    if next_item_size > 0 && pr > next_item_size as f64 {
        let rem_norm = (pr - next_item_size as f64) / cap;
        if rem_norm > 0.0 && rem_norm < 0.03 {
            score -= (0.03 - rem_norm) * 10.0 * (0.4 + progress);
        } else if rem_norm > 0.16 {
            score += (rem_norm - 0.16) * 8.0 * (0.5 + progress);
        }
    }

    // Mid-range residual that next item cannot use.
    if pr > 0.0 && post_norm >= 0.10 && post_norm < 0.20 && next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt > pr {
            score += (nxt - pr) / cap * 26.0 * (0.4 + progress * 0.8);
        }
    }

    // Small leftover relative to item late in stream.
    if pr > 0.0 && pr < (item_size as f64) * 0.5 && progress > 0.3 {
        score += 4.0 * (1.0 - progress);
    }

    // Dead space after next placement.
    if next_item_size > 0 && pr > 0.0 {
        let nxt = next_item_size as f64;
        let dead = (pr - nxt).max(0.0) / cap;
        if dead > 0.0 && dead < 0.08 {
            let third = if dead * cap >= nxt { 1.0 } else { 0.0 };
            score += (0.08 - dead) * 16.0 * (1.0 - third * 0.5) * (0.5 + progress);
        }
    }

    // New bin that can host next item too.
    if bin_residual == bin_capacity && next_item_size > 0 && fitting_bins_count <= 3 {
        let nxt = next_item_size as f64;
        if item_size as f64 >= nxt * 0.95 {
            score -= 5.5 * (1.0 - progress * 0.5);
        }
    }

    // --- Generation 37 mutations ---

    // Fine-tuned snugness: extend gaussian lookahead reward with a sharper
    // second lobe targeting near-exact matches (dead-space killer).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let exact = (pr - nxt) / cap;
        if exact.abs() < 0.015 {
            score -= (0.015 - exact.abs()) * 55.0 * (0.6 + progress * 0.5);
        }
    }

    // Wasted-space ratio: penalize bins whose post-residual is a fraction of
    // the item that no plausible future item can fill (large dead space).
    if pr > 0.0 {
        let waste = pr / cap;
        if waste >= 0.20 && waste < 0.45 {
            score += (waste - 0.20) * 14.0 * (0.5 + progress * 0.7);
        }
    }

    // Pairing lookahead: if the next item exactly fills the post-residual,
    // strongly reward (creates perfect two-item closures).
    if next_item_size > 0 && pr == next_item_size as f64 {
        score -= 12.0 * (1.0 - progress * 0.4);
    }

    // New-bin discipline: when several open bins fit, discourage opening a
    // fresh bin unless the item is large relative to capacity.
    if bin_residual == bin_capacity && fitting_bins_count > 3 {
        let size_frac = item_size as f64 / cap;
        if size_frac < 0.5 {
            score += 10.0 + 14.0 * (1.0 - size_frac) * (1.0 - progress * 0.5);
        }
    }

    // Late-stream compaction: with many open bins, prefer bins whose
    // post-residual stays small so the tail of the stream closes cleanly.
    if open_bins_count > 12 && pr > 0.0 && post_norm < 0.06 {
        score -= (0.06 - post_norm) * 20.0 * ((open_bins_count.min(24) as f64 - 12.0) / 12.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let next = next_item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items.max(1) as f64 } else { 0.0 };
    let post_norm = pr / cap;
    let fit_ratio = item_size as f64 / cap;
    let gap = (bin_residual - item_size) as f64 / cap;
    let mut score = post_norm * post_norm * 56.5 + post_norm * 21.8;

    // ---- Aggressive 2-step lookahead: shape score around the NEXT item ----
    if next > 0.0 {
        if pr == next {
            score -= 45.0;
        } else if pr > next {
            let slack = pr - next;
            let diff = slack / cap;
            score -= 20.0 * (1.0 - diff).max(0.0);
            score -= (-diff * diff * 458.0).exp() * 20.2 * (1.0 - progress * 0.5);
            // Snug remainder after next item lands.
            if diff < 0.04 {
                score -= (0.04 - diff) * 26.0 * (0.6 + progress * 0.6);
            } else if diff > 0.16 {
                score += (diff - 0.16) * 8.0 * (0.5 + progress);
            }
        } else if pr > 0.0 {
            score += (next - pr) / cap * 30.5 * (1.0 - progress);
        }
    }

    // Penalize tiny unusable slivers unless they exactly match the next item.
    if pr > 0.0 && pr < 10.0 && pr != next {
        score += 15.0;
    }

    // ---- Relative-to-mean coupling: favor tighter-than-average bins ----
    if pr > 0.0 {
        let dev = (mean_residual - pr) / cap;
        if dev > 0.05 {
            score += (dev - 0.05) * 12.0 * (0.4 + progress);
        } else if dev < -0.08 {
            score += (-dev - 0.08) * 6.0 * (1.0 - progress);
        }
    }

    // ---- New-bin candidate decision (bin_residual == bin_capacity) ----
    if bin_residual == bin_capacity {
        let others = if fitting_bins_count > 0 { fitting_bins_count - 1 } else { 0 };
        let size_pull = fit_ratio * 14.0;
        if fitting_bins_count <= 2 && gap > 0.0 {
            score -= (18.0 + size_pull) * (1.0 - progress * 0.6);
        } else if others == 0 {
            score -= 5.0;
        } else {
            score += 8.0 + 6.0 * (1.0 - progress);
        }
        // If the next item is nearly as big as this one, opening a fresh bin
        // wastes capacity; discourage it under mild pressure.
        if next > 0.0 && fitting_bins_count <= 3 && item_size as f64 >= next * 0.95 {
            score -= 5.5 * (1.0 - progress * 0.5);
        }
        // NEW: if the fresh bin could hold both current and next items snugly,
        // slightly discourage opening it (prefer consolidating into an open bin
        // whose leftover matches next).
        if next > 0.0 && fitting_bins_count > 0 && item_size as f64 + next <= cap {
            score += 3.0 * (1.0 - progress);
        }
    }

    // Exact / near-exact fit bonuses.
    if pr == 0.0 {
        score -= 15.2;
    } else if post_norm < 0.05 {
        score -= 10.2 * (1.0 - post_norm / 0.05);
    }

    // Sharp bonus for leaving a tiny gap (<10% of capacity).
    if gap > 0.0 && gap < 0.10 {
        score -= (0.10 - gap) * 40.5;
    }
    // Mid-gap dead space: penalize if next item cannot consume the leftover.
    if gap > 0.10 && gap < 0.22 && next > 0.0 && pr > 0.0 && pr < next {
        score += (gap - 0.10) * 90.5 * (0.5 + progress);
    }
    if gap >= 0.22 && gap < 0.35 && progress > 0.55 {
        score += (gap - 0.22) * 45.5 * (progress - 0.55) * 2.0;
    }
    // Next-item chain: leftover after placing next item nearly closes bin.
    if next > 0.0 && gap > 0.12 {
        let nxt_gap = ((gap * cap - next).max(0.0)) / cap;
        if nxt_gap < 0.06 {
            score -= 9.0 * (1.0 - nxt_gap / 0.06) * (0.5 + progress);
        }
    }

    // Reward large items filling bins deeply.
    score -= fit_ratio * fit_ratio * 6.0;

    // Congestion: when many bins compete for this item, penalize sloppy fits.
    if fitting_bins_count > 2 {
        score += gap * 6.5 * ((fitting_bins_count.min(12) as f64 - 2.0) / 10.0);
    }
    if open_bins_count > 8 {
        score += post_norm * 5.0 * ((open_bins_count.min(20) as f64 - 8.0) / 12.0);
    }

    // Late-stream consolidation: penalize moderately large residuals late.
    if progress > 0.7 && post_norm > 0.25 {
        score += (post_norm - 0.25) * 6.0 * (progress - 0.7) / 0.3;
    }

    // Last-chance bonus: prefer a bin that would otherwise be wasted.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 - fit_ratio);
    }

    // Deep fill bonus relative to actual residual.
    let fill_r = item_size as f64 / bin_residual.max(1) as f64;
    if fill_r > 0.90 && bin_residual != bin_capacity {
        score -= (fill_r - 0.90) * 18.0 * (0.6 + progress * 0.5);
    }

    // Dead-space guard: if the remainder after the next item would be a small
    // stranded gap that the next item cannot re-use, penalize it.
    if next > 0.0 && pr > 0.0 {
        let after_next = (pr - next).max(0.0);
        let dead = after_next / cap;
        if dead > 0.0 && dead < 0.08 {
            let reusable = if after_next >= next { 1.0 } else { 0.0 };
            score += (0.08 - dead) * 16.0 * (1.0 - reusable * 0.5) * (0.5 + progress);
        }
    }

    // Mid-residual band: leftover in 10-20% range that next item cannot fit
    // into is likely to strand; penalize.
    if pr > 0.0 && post_norm >= 0.10 && post_norm < 0.20 && next > 0.0 && next > pr {
        score += (next - pr) / cap * 26.0 * (0.4 + progress * 0.8);
    }

    // Half-consumed bins late in the stream: discourage leaving a residual
    // smaller than half the current item (hard to refill).
    if pr > 0.0 && pr < item_size as f64 * 0.5 && progress > 0.3 {
        score += 4.0 * (1.0 - progress);
    }

    // NEW: two-item chain closure — if placing the current item leaves a gap
    // that exactly hosts the next item, this bin closes in two steps; reward.
    if next > 0.0 && gap > 0.0 && (gap * cap - next).abs() < 1.0 {
        score -= 12.0 * (1.0 - progress * 0.4);
    }

    // NEW: residual-strand coupling — if the post residual is smaller than the
    // smallest plausible refill (below 8% of capacity) and doesn't match next,
    // add escalating penalty late in the stream to force tighter choices.
    if pr > 0.0 && post_norm < 0.08 && pr != next && next > 0.0 && next > pr {
        score += (0.08 - post_norm) * 30.0 * (0.3 + progress);
    }

    score
}

