        score -= 15.0;
    } else if post_norm < 0.05 {
        score -= 10.0 * (1.0 - post_norm / 0.05);
    }

    // Grafted: sharp bonus for leaving a tiny gap (<10% of capacity).
    if gap > 0.0 && gap < 0.10 {
        score -= (0.10 - gap) * 40.0;
    }
    // Mid gap band: penalize if next item can't use the leftover.
    if gap >= 0.10 && gap < 0.22 && next > 0.0 && pr > 0.0 && pr < next {
        score += (gap - 0.10) * 90.0 * (0.5 + progress);
    }
    if gap >= 0.22 && gap < 0.35 && progress > 0.55 {
        score += (gap - 0.22) * 45.0 * (progress - 0.55) * 2.0;
    }

    // Two-step lookahead: penalize dead space after next item in large gaps.
    if next > 0.0 && gap > 0.12 {
        let nxt_gap = ((gap * cap - next).max(0.0)) / cap;
        if nxt_gap < 0.06 {
            score -= 9.0 * (1.0 - nxt_gap / 0.06) * (0.5 + progress);
        }
    }

    // Relative-to-mean coupling: favor tighter-than-average bins.
    if pr > 0.0 {
        let dev = (mean_residual - pr) / cap;
        if dev > 0.05 {
            score += (dev - 0.05) * 12.0 * (0.4 + progress);
        } else if dev < -0.08 {
            score += (-dev - 0.08) * 6.0 * (1.0 - progress);
        }
    }

    // Reward large items filling bins deeply.
    score -= fit_ratio * fit_ratio * 6.0;

    // Congestion: penalize sloppy fits when many bins open.
    if fitting_bins_count > 2 {
        score += gap * 6.5 * ((fitting_bins_count.min(12) as f64 - 2.0) / 10.0);
    }
    if open_bins_count > 8 {
        score += post_norm * 5.0 * ((open_bins_count.min(20) as f64 - 8.0) / 12.0);
    }

    // Late-stream consolidation.
    if progress > 0.7 && post_norm > 0.25 {
        score += (post_norm - 0.25) * 6.0 * (progress - 0.7) / 0.3;
    }

    // Last-chance bonus: prefer a bin that would otherwise be wasted.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 - fit_ratio);
    }

    // ---- New-bin candidate decision ----
    if bin_residual == bin_capacity {
        let size_pull = fit_ratio * 14.0;
        if fitting_bins_count == 0 {
            // No other bin can host this item: embrace the new bin.
            score -= (18.0 + size_pull) * (1.0 - progress * 0.6);
        } else if fitting_bins_count <= 2 {
            // Fragmented state early: fresh bin can help compaction.
            score -= (14.0 + size_pull) * (1.0 - progress * 0.6);
            if next > 0.0 && fit_ratio >= next / cap * 0.95 {
                score -= 5.5 * (1.0 - progress * 0.5);
            }
        } else {
            score += 8.0 + 6.0 * (1.0 - progress) + 0.5 * mean_residual;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues divisible by common item sizes
    // (e.g. 10, 20, 25, 50) are "reusable"; odd remainders are dead space.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Reward post-residuals that are harmonic (divisible by small steps 5/10/25)
    if post_residual % 25 == 0 {
        score -= 12.0;
    } else if post_residual % 10 == 0 {
        score -= 8.0;
    } else if post_residual % 5 == 0 {
        score -= 4.0;
    } else {
        score += 6.0; // non-harmonic residue: penalize
    }

    // Perfect fit: zero residual is ideal
    if post_residual == 0 {
        score -= 100.0;
    }

    // Penalize tiny unusable dead space (1..9) more than moderate space
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Coupling with lookahead: if next item fits exactly in post_residual,
    // strongly favor this bin (chain packing).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size < post_residual {
            score -= 5.0 * (next_item_size as f64 / cap);
        } else {
            // next item won't fit here; leftover is more likely dead
            score += 4.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: empty bin has residual == capacity.
    // Prefer new bin when current open bins would leave badly fragmented space,
    // otherwise prefer reusing open bins.
    if bin_residual == bin_capacity {
        // neutral baseline for new bin: slightly above tight fits
        score += 5.0;
        // if many open bins with high mean residual, discourage another bin
        if mean_residual > 0.5 * cap {
            score += 10.0;
        }
        // early stream: encourage filling bins before opening many
        let progress = step_index as f64 / total_items.max(1) as f64;
        if open_bins_count as f64 > 4.0 + 10.0 * progress {
            score += 15.0;
        }
    } else {
        // Favor bins whose residual is close to item size (tight fit)
        let tightness = 1.0 - (item_size as f64 / bin_residual as f64);
        score += 10.0 * tightness * tightness;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
