    if next_item_size > 0 && pr == next_item_size as u32 as f64 {
        score -= 8.0 * (0.6 + progress * 0.5);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Strict dead-space avoidance ---
    // Post-residuals that are too small to hold anything useful (item sizes
    // can be as small as 1, but very small gaps are statistically dead weight)
    // are heavily penalized in a non-linear way.
    let pr = post_residual as f64;
    if pr > 0.0 && pr < 10.0 {
        // Unusable sliver: strong penalty that grows as the gap shrinks.
        score += (10.0 - pr) * (10.0 - pr) * 2.5;
    } else if pr == 0.0 {
        // Perfect fit: big reward.
        score -= 60.0;
    }

    // Reward tight fits generally (small post_residual relative to what was consumed).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 15.0;

    // --- Last-chance pressure ---
    // If this is the ONLY open bin that fits the item, strongly favor using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // --- Open-bin pressure ---
    // More open bins than needed => prefer consolidating into existing bins,
    // especially bins whose residual is close to the mean (typical bins).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let bin_pressure = open_bins_count as f64 * (0.5 + progress);
    score += (bin_residual as f64 - mean_residual).abs() * 0.3;
    score += bin_pressure * 0.15;

    // --- Lookahead coupling ---
    // If the next item fits exactly in the post-residual, reward leaving that gap.
    if next_item_size > 0 {
        let nd = post_residual as i64 - next_item_size as i64;
        if nd == 0 {
            score -= 35.0;
        } else if nd > 0 && nd < 10 {
            // Leaving a gap that only barely fails the next item: mild penalty.
            score += 5.0;
        }
    }

    // --- New-bin candidate handling ---
    // A brand-new empty bin has bin_residual == bin_capacity. It should only win
    // when no open bin offers a decent fit: make it expensive by default.
    if bin_residual == bin_capacity {
        score += 25.0 + pr * 0.5;
        // Early in the stream, opening bins is cheaper (builds a pool).
        score -= (1.0 - progress) * 20.0;
    }

    score
}

