    let tightness = mean_residual - bin_residual as f64;
    if tightness > 0.0 {
        score -= 0.2 * tightness;
    } else if pr > 0.0 {
        let dev = (mean_residual - pr) / cap;
        if dev > 0.05 {
            score += (dev - 0.05) * 12.0 * (0.4 + progress);
        } else if dev < -0.08 {
            score += (-dev - 0.08) * 6.0 * (1.0 - progress);
        }
    }

