    // (fill fuller bins first, keep emptier bins flexible).
    let dev = (bin_residual as f64 - mean_residual) / (bin_capacity as f64);
    score += 10.0 * dev;

    // Late in the stream: consolidate, prefer filling existing bins over opening new.
    let progress = step_index as f64 / (total_items.max(1) as f64);
