        score -= 3.5 * (1.0 - progress / 0.15);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover is divisible into
    // useful capacity fractions (small "coin" sizes) are better donors.
    let post = post_residual;
    if post > 0 {
        // Dead-space penalty grows super-linearly for unusable slivers.
        if post < 10 {
            score += 60.0 - (post as f64) * 5.0; // tiny leftovers are worst
        }
        // Reward post-residuals that are multiples of common item classes
        // (10/20/25/50 fractions of capacity=100).
        let harmonic = (post % 10 == 0) as i32 as f64 * 8.0
            + (post % 20 == 0) as i32 as f64 * 6.0
            + (post % 25 == 0) as i32 as f64 * 5.0
            + (post % 50 == 0) as i32 as f64 * 4.0;
        score -= harmonic;
        // Integer-division threshold: leftover in [20, 50] can host a mid item.
        if post / 20 >= 1 && post <= 50 {
            score -= 5.0;
        }
    } else {
        score -= 25.0; // perfect fit
    }

    // Lookahead coupling: if next item fits exactly in post_residual,
    // strongly favor this bin (chained harmonic match).
    if next_item_size > 0 && post >= next_item_size {
        let slack = (post - next_item_size) as f64;
        score -= 20.0 - slack.min(30.0) * 0.4;
        if post == next_item_size {
            score -= 15.0; // exact two-item chain
        }
    } else if next_item_size > post && post > 0 {
        score += 6.0; // next item won't chain here
    }

    // Last-chance bonus: only one bin can host this item.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New-bin candidate handling: prefer opening a fresh bin when residuals
    // across open bins are already small (mean_residual low => fragmentation).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Open new bin if open bins are nearly full on average.
        score += mean_residual * 0.35 + (open_bins_count as f64) * 0.5 - progress * 10.0;
        // Big items prefer fresh bins.
        if item_size > bin_capacity / 2 {
            score -= 12.0;
        }
    }

    // Mild preference for fuller bins overall.
    score -= (bin_capacity - bin_residual) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let next = next_item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let post_norm = pr / cap;
    let fit_ratio = item_size as f64 / cap;
    let gap = (bin_residual - item_size) as f64 / cap;

    // Core compaction term: quadratic residual pressure (from best lineage).
    let mut score = post_norm * post_norm * 56.5 + post_norm * 21.8;

    // ---- 2-step lookahead: shape score around the NEXT item ----
    if next > 0.0 {
        if pr == next {
            // Perfect 2-chain: bin exactly closed by the next item.
            score -= 45.0;
        } else {
            let diff = (pr - next) / cap;
            // Gaussian reward when post residual matches next item snugly.
            score -= (-diff * diff * 458.0).exp() * 20.2 * (1.0 - progress * 0.5);
            if pr > next {
                // Snug band: next fits leaving almost nothing.
                let snug = diff;
                if snug < 0.04 {
                    score -= (0.04 - snug) * 22.0 * (0.6 + progress * 0.6);
                }
                // Dead space after next placement.
                let dead = (pr - next) / cap;
                if dead > 0.16 {
                    score += (dead - 0.16) * 8.0 * (0.5 + progress);
                } else if dead > 0.08 {
                    score += (dead - 0.08) * 16.0 * 0.5 * (0.5 + progress);
                }
            } else {
                // Next item cannot use the leftover: penalize gap size.
                score += (next - pr) / cap * 30.5 * (1.0 - progress);
            }
        }
    }

    // Penalize tiny unusable slivers unless they exactly match the next item.
    if pr > 0.0 && pr < 10.0 && pr != next {
        score += 15.0;
    }

    // ---- Relative-to-mean coupling: favor tighter-than-average bins ----
    if pr > 0.0 {
        let dev = (mean_residual - pr) / cap;
        if dev > 0.05 {
            score += (dev - 0.05) * 12.0 * (0.4 + progress);
        } else if dev < -0.08 {
            score += (-dev - 0.08) * 6.0 * (1.0 - progress);
        }
    }

    // ---- New-bin candidate decision (bin_residual == bin_capacity) ----
    if bin_residual == bin_capacity {
        let others = if fitting_bins_count > 0 { fitting_bins_count - 1 } else { 0 };
        let size_pull = fit_ratio * 14.0;
        if others == 0 {
            // No other bin can host this item: embrace the new bin.
            score -= (18.0 + size_pull) * (1.0 - progress * 0.6);
        } else if others <= 2 && gap > 0.0 {
            // Few alternatives early: fresh bin can help compaction.
            score -= (18.0 + size_pull) * (1.0 - progress * 0.6);
        } else {
            score += 30.0 + 0.5 * mean_residual + 0.5 * open_bins_count as f64;
        }
        // New bin that can host next item too.
        if next > 0.0 && others <= 3 && item_size as f64 >= next * 0.95 {
            score -= 5.5 * (1.0 - progress * 0.5);
        }
    }

    // Exact / near-exact fit bonuses.
    if pr == 0.0 {
        score -= 15.2;
    } else if post_norm < 0.05 {
        score -= 10.2 * (1.0 - post_norm / 0.05);
    }

    // Sharp bonus for leaving a tiny gap (<10% of capacity).
    if gap > 0.0 && gap < 0.10 {
        score -= (0.10 - gap) * 40.5;
    }
    // Mid gap that next item cannot use.
    if gap > 0.10 && gap < 0.22 && next > 0.0 && pr > 0.0 && pr < next {
        score += (gap - 0.10) * 90.5 * (0.5 + progress);
    }
    if gap >= 0.22 && gap < 0.35 && progress > 0.55 {
        score += (gap - 0.22) * 45.5 * (progress - 0.55) * 2.0;
    }

    // Two-step lookahead: reward bins where the next item nearly closes the bin.
    if next > 0.0 && gap > 0.12 {
        let nxt_gap = ((gap * cap - next).max(0.0)) / cap;
        if nxt_gap < 0.06 {
            score -= 9.0 * (1.0 - nxt_gap / 0.06) * (0.5 + progress);
        }
    }

    // Reward large items filling bins deeply.
    score -= fit_ratio * fit_ratio * 6.0;

    // Congestion pressure: deprioritize sloppy fits when many bins are open.
    if open_bins_count > 8 {
        score += post_norm * 5.0 * ((open_bins_count.min(20) as f64 - 8.0) / 12.0);
    }
    if fitting_bins_count > 2 {
        score += gap * 6.5 * ((fitting_bins_count.min(12) as f64 - 2.0) / 10.0);
    }

    // Late-stream consolidation: penalize moderately large residuals late.
    if progress > 0.7 && post_norm > 0.25 {
        score += (post_norm - 0.25) * 6.0 * (progress - 0.7) / 0.3;
    }

    // Last-chance bonus: prefer a bin that would otherwise be wasted.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 - fit_ratio);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let post_norm = pr / cap;
    let mut score = post_norm * post_norm * 58.0 + post_norm * 22.0;

    // Lookahead: gaussian reward when post_residual matches next item snugly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (pr - nxt) / cap;
        score -= (-diff * diff * 470.0).exp() * 21.0 * (1.0 - progress * 0.5);
        if pr < nxt {
            score += (nxt - pr) / cap * 32.0 * (1.0 - progress);
        }
    }

    // Near-perfect fills.
    if pr == 0 {
        score -= 16.0;
    } else if post_norm < 0.05 {
        score -= 10.5 * (1.0 - post_norm / 0.05);
    }

    let gap = (bin_residual - item_size) as f64 / cap;
    if gap > 0.0 && gap < 0.10 {
        score -= (0.10 - gap) * 42.0;
    }
    if gap > 0.10 && gap < 0.22 && next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr > 0.0 && pr < nxt {
            score += (gap - 0.10) * 92.0 * (0.5 + progress);
        }
    }
    if gap >= 0.22 && gap < 0.35 && progress > 0.55 {
        score += (gap - 0.22) * 46.0 * (progress - 0.55) * 2.0;
    }

    // Two-step lookahead: penalize dead space after placing next item.
    if next_item_size > 0 && gap > 0.12 {
        let nxt = next_item_size as f64;
        let nxt_gap = (gap * cap - nxt).max(0.0) / cap;
        if nxt_gap < 0.06 {
            score -= 9.5 * (1.0 - nxt_gap / 0.06) * (0.5 + progress);
        }
    }

    if fitting_bins_count > 2 {
        score += gap * 6.5 * ((fitting_bins_count.min(12) as f64 - 2.0) / 10.0);
    }

    // Deviation from mean residual.
    if pr > 0.0 {
        let dev = (mean_residual - pr) / cap;
        if dev > 0.05 {
            score += (dev - 0.05) * 12.0 * (0.4 + progress);
        } else if dev < -0.08 {
            score += (-dev - 0.08) * 6.0 * (1.0 - progress);
        }
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let size_pull = (item_size as f64 / cap) * 14.0;
        if fitting_bins_count <= 2 && gap > 0.0 {
            score -= (18.0 + size_pull) * (1.0 - progress * 0.6);
        } else {
            // Slightly stronger resistance to opening bins mid-stream.
            score += 8.5 + 6.5 * (1.0 - progress);
        }
    }

    // Snug post-residual bonus for next item.
    if next_item_size > 0 && pr > 0.0 {
        let nxt = next_item_size as f64;
        let snug = (pr - nxt) / cap;
        if snug >= 0.0 && snug < 0.04 {
            score -= (0.04 - snug) * 23.0 * (0.6 + progress * 0.6);
        }
    }

    // Consolidation pressure with many open bins.
    if open_bins_count > 8 {
        score += post_norm * 5.0 * ((open_bins_count.min(20) as f64 - 8.0) / 12.0);
    }

    // Remaining-after-next analysis.
    if next_item_size > 0 && pr > next_item_size as f64 {
        let rem_norm = (pr - next_item_size as f64) / cap;
        if rem_norm > 0.0 && rem_norm < 0.03 {
            score -= (0.03 - rem_norm) * 10.5 * (0.4 + progress);
        } else if rem_norm > 0.16 {
            score += (rem_norm - 0.16) * 8.5 * (0.5 + progress);
        }
    }

    // Mid-range residual that next item cannot use.
    if pr > 0.0 && post_norm >= 0.10 && post_norm < 0.20 && next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt > pr {
            score += (nxt - pr) / cap * 27.0 * (0.4 + progress * 0.8);
        }
    }

    // Small leftover relative to item late in stream.
    if pr > 0.0 && pr < (item_size as f64) * 0.5 && progress > 0.3 {
        score += 4.0 * (1.0 - progress);
    }

    // Dead space after next placement (tightened band, adaptive weight).
    if next_item_size > 0 && pr > 0.0 {
        let nxt = next_item_size as f64;
        let dead = (pr - nxt).max(0.0) / cap;
        if dead > 0.0 && dead < 0.09 {
            let third = if dead * cap >= nxt { 1.0 } else { 0.0 };
            score += (0.09 - dead) * 17.5 * (1.0 - third * 0.5) * (0.5 + progress);
        }
    }

    // New bin that can host next item too.
    if bin_residual == bin_capacity && next_item_size > 0 && fitting_bins_count <= 3 {
        let nxt = next_item_size as f64;
        if item_size as f64 >= nxt * 0.95 {
            score -= 5.5 * (1.0 - progress * 0.5);
        }
    }

    // NEW: penalize residuals slightly larger than next item that no future
    // small item is likely to fill — dead-space ratio pressure.
    if next_item_size > 0 && pr > next_item_size as f64 {
        let nxt = next_item_size as f64;
        let over = (pr - nxt) / cap;
        if over >= 0.03 && over < 0.12 {
            // Waste that even the next item can't reclaim; stronger mid-stream.
            score += (over - 0.03) * 14.0 * (0.6 + progress * 0.4);
        }
    }

    // NEW: reward bins whose post-residual is an exact small multiple of
    // likely small items (divisibility heuristic for residual reuse).
    if pr > 0.0 && pr < cap * 0.35 {
        let half = pr / 2.0;
        let third = pr / 3.0;
        let tol = cap * 0.02;
        if (next_item_size as f64 - half).abs() < tol
            || (next_item_size as f64 - third).abs() < tol {
            score -= 6.0 * (1.0 - progress * 0.4);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize unusable dead space: gaps too small for the smallest plausible item
    let min_item = 1.0f64.min(bin_capacity as f64);
    if post_residual > 0 && (post_residual as f64) < min_item {
        score += 1000.0;
    }

    // Dead-space curve: residual in the awkward band (1..=20) is nearly unusable
    if post_residual >= 1 && post_residual <= 20 {
        score += (21 - post_residual) as f64 * 2.5;
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 50.0;
    }

    // Open-bins pressure: mildly prefer using existing bins over opening new ones
    score += open_bins_count as f64 * 0.5;

    // New-bin candidate: penalize opening a new bin unless the current bin's
    // post-fit residual would be badly fragmented
    if bin_residual == bin_capacity {
        score += 30.0 + mean_residual * 0.1;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly into the post residual, reward
    if next_item_size > 0 && next_item_size as f64 == post_residual as f64 {
        score -= 25.0;
    }
    // Penalize if next item would be stranded by this placement's residual
    if next_item_size > 0 && (post_residual as f64) > 0.0 && (post_residual as f64) < next_item_size as f64 && post_residual <= 20 {
        score += 15.0;
    }

    // Tightness coupling: prefer bins whose residual is well consumed
    score -= (item_size as f64 / bin_capacity as f64) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: perfect match with next item is gold.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let post = post_residual as f64;

        if post_residual == next_item_size {
            // Bin becomes exactly full after next item -> strong reward.
            score -= 60.0 + next * 0.5;
        } else if post_residual >= next_item_size {
            // Next item fits: reward closeness of post-residual to next size.
            let gap = post - next;
            score -= 20.0 * (1.0 - gap / bin_capacity as f64);
            // Extra bonus if the chain could continue (post_residual - next still usable).
            if post_residual - next_item_size >= 10 {
                score -= 5.0;
            }
        } else {
            // Next item will NOT fit in this bin: penalize by the shortfall.
            let shortfall = next - post;
            score += 10.0 + shortfall as f64 * 0.4;
        }
    } else {
        // Last item: just prefer tightest fit (already encoded in post_residual).
        score -= 5.0;
    }

    // Penalize dead space relative to the fleet's mean residual:
    // leaving more than the mean residual is wasteful.
    let post = post_residual as f64;
    if post > mean_residual {
        score += 0.3 * (post - mean_residual);
    } else {
        score -= 0.15 * (mean_residual - post);
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Mild pressure to fill bins early in the stream (keep many bins open later).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 8.0 * (1.0 - progress) * (post / bin_capacity as f64);

    // Slight preference for bins that are already heavily loaded.
    let load_frac = (bin_capacity as f64 - bin_residual as f64) / bin_capacity as f64;
    score -= 6.0 * load_frac;

    // Guard against favoring the fresh-bin candidate unless it is genuinely better.
    if bin_residual == bin_capacity {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
