    // Mid-residual band: leftover in 10-20% range that next item cannot fit
    // into is likely to strand; penalize.
    if pr > 0.0 && post_norm >= 0.10 && post_norm < 0.20 && next > 0.0 && next > pr {
        score += (next - pr) / cap * 28.0 * (0.4 + progress * 0.8);
    }

    // Half-consumed bins late in the stream: discourage leaving a residual
    // smaller than half the current item (hard to refill).
    if pr > 0.0 && pr < item_size as f64 * 0.5 && progress > 0.3 {
        score += 4.5 * (1.0 - progress);
    }

    // NEW: pair-chain bonus — if the next item would exactly consume the
    // remainder, this bin closes in two placements; strongly reward it.
    if next > 0.0 && pr == 0.0 && gap * cap >= next && (gap * cap - next) < 4.0 {
        score -= 6.0 * (1.0 - progress * 0.4);
    }

    // NEW: penalize residuals that neither this item nor the next can ever
    // split into two useful chunks (dead zone between next and 2*next).
    if pr > 0.0 && next > 0.0 && pr > next && pr < next * 2.0 {
        score += (next * 2.0 - pr) / cap * 5.0 * (0.5 + progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual) more strongly than linear.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 6.0 * tightness * tightness;

    // Perfect-fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual < 10 {
        score -= 10.0;
    }

    // Lookahead coupling: reward if next item fits into the post residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 8.0;
        } else {
            // Penalize leaving dead space the next item cannot use.
            let waste = (post_residual as f64) / (bin_capacity as f64);
            score += 5.0 * waste * waste;
        }
    }

    // Last-chance bonus: this is the only bin that fits the item.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Global state coupling: with many open bins, prefer consolidating
    // into low-residual bins; with few bins, be more permissive.
    let open_pressure = (open_bins_count as f64).ln().max(0.0);
    score += 0.8 * open_pressure * (post_residual as f64) / (bin_capacity as f64);

    // Mean residual deviation: prefer bins whose residual is near/below mean
    // (i.e., already partly filled bins get priority over fresh ones).
    let dev = (bin_residual as f64 - mean_residual) / (bin_capacity as f64);
    score += 4.0 * dev;

    // Time horizon: early in stream, slightly favor opening/using new bins
    // to build diversity; late in stream, favor filling existing bins fully.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 5.0 * progress * tightness;
    score += 3.0 * (1.0 - progress) * (post_residual as f64) / (bin_capacity as f64);

    // Penalize the brand-new empty bin candidate unless nothing fits well.
    if bin_residual == bin_capacity {
        score += 12.0;
        // Exception: large items that would leave big gaps elsewhere anyway.
        if item_size as f64 > 0.7 * bin_capacity as f64 {
            score -= 20.0;
        }
        // Late stream: opening a new bin is cheap since stream is ending.
        if progress > 0.85 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let post_norm = pr / cap;
    let mut score = post_norm * post_norm * 57.0 + post_norm * 21.6;

    // Lookahead: gaussian reward when post_residual matches next item snugly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (pr - nxt) / cap;
        score -= (-diff * diff * 461.0).exp() * 20.6 * (1.0 - progress * 0.5);
        if pr < nxt {
            score += (nxt - pr) / cap * 31.0 * (1.0 - progress);
        }
    }

    // Near-perfect fills.
    if pr == 0 {
        score -= 15.4;
    } else if post_norm < 0.05 {
        score -= 10.4 * (1.0 - post_norm / 0.05);
    }

    let gap = (bin_residual - item_size) as f64 / cap;
    if gap > 0.0 && gap < 0.10 {
        score -= (0.10 - gap) * 41.0;
    }
    if gap > 0.10 && gap < 0.22 && next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr > 0.0 && pr < nxt {
            score += (gap - 0.10) * 92.0 * (0.5 + progress);
        }
    }
    if gap >= 0.22 && gap < 0.35 && progress > 0.55 {
        score += (gap - 0.22) * 46.0 * (progress - 0.55) * 2.0;
    }

    // Two-step lookahead: penalize dead space after placing next item.
    if next_item_size > 0 && gap > 0.12 {
        let nxt = next_item_size as f64;
        let nxt_gap = (gap * cap - nxt).max(0.0) / cap;
        if nxt_gap < 0.06 {
            score -= 9.5 * (1.0 - nxt_gap / 0.06) * (0.5 + progress);
        }
    }

    if fitting_bins_count > 1 {
        score += (fitting_bins_count as f64 - 1.0).min(4.0) * (1.0 - progress) * 0.9;
    }

    // Deviation from mean residual: avoid outliers in residual space.
    if pr > 0.0 {
        let dev = (mean_residual - pr) / cap;
        if dev > 0.05 {
            score += (dev - 0.05) * 12.0 * (0.4 + progress);
        } else if dev < -0.08 {
            score += (-dev - 0.08) * 6.0 * (1.0 - progress);
        }
    }

    // New-bin candidate handling: prefer opening a fresh bin only when no
    // open bin offers a decent fit; otherwise penalize it.
    if bin_residual == bin_capacity {
        let size_pull = (item_size as f64 / cap) * 14.0;
        if fitting_bins_count <= 2 && gap > 0.0 {
            score -= (18.0 + size_pull) * (1.0 - progress * 0.6);
        } else {
            score += 8.0 + 6.0 * (1.0 - progress);
        }
    }

    // Snug post-residual bonus for next item.
    if next_item_size > 0 && pr > 0.0 {
        let nxt = next_item_size as f64;
        let snug = (pr - nxt) / cap;
        if snug >= 0.0 && snug < 0.04 {
            score -= (0.04 - snug) * 22.0 * (0.6 + progress * 0.6);
        }
    }

    // Consolidation pressure with many open bins.
    if open_bins_count > 8 {
        score += post_norm * 5.0 * ((open_bins_count.min(20) as f64 - 8.0) / 12.0);
    }

    // Remaining-after-next analysis.
    if next_item_size > 0 && pr > next_item_size as f64 {
        let rem_norm = (pr - next_item_size as f64) / cap;
        if rem_norm > 0.0 && rem_norm < 0.03 {
            score -= (0.03 - rem_norm) * 10.0 * (0.4 + progress);
        } else if rem_norm > 0.16 {
            score += (rem_norm - 0.16) * 8.0 * (0.5 + progress);
        }
    }

    // Mid-range residual that next item cannot use.
    if pr > 0.0 && post_norm >= 0.10 && post_norm < 0.20 && next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt > pr {
            score += (nxt - pr) / cap * 26.0 * (0.4 + progress * 0.8);
        }
    }

    // Small leftover relative to item late in stream.
    if pr > 0.0 && pr < (item_size as f64) * 0.5 && progress > 0.3 {
        score += 4.0 * (1.0 - progress);
    }

    // Dead space after next placement.
    if next_item_size > 0 && pr > 0.0 {
        let nxt = next_item_size as f64;
        let dead = (pr - nxt).max(0.0) / cap;
        if dead > 0.0 && dead < 0.08 {
            let third = if dead * cap >= nxt { 1.0 } else { 0.0 };
            score += (0.08 - dead) * 16.0 * (1.0 - third * 0.5) * (0.5 + progress);
        }
    }

    // New bin that can host next item too.
    if bin_residual == bin_capacity && next_item_size > 0 && fitting_bins_count <= 3 {
        let nxt = next_item_size as f64;
        if item_size as f64 >= nxt * 0.95 {
            score -= 5.5 * (1.0 - progress * 0.5);
        }
    }

    score
}

