        if item_size as f64 >= nxt * 0.95 {
            score -= 6.0 * (1.0 - progress * 0.5);
        }
    }

    // NEW: prefer bins whose post-residual is a plausible future item size
    // (multiple of small common sizes) — keeps residuals reusable.
    if pr > 0.0 && post_norm < 0.30 {
        let reusable = (pr as i64 % 10 == 0) || (pr as i64 % 5 == 0 && pr < 30.0);
        if reusable {
            score -= 3.0 * (1.0 - post_norm / 0.30) * (0.5 + progress * 0.5);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Smooth polynomial coupling of post_residual with stream progress
    let mut score = pr * (1.0 + 0.6 * progress * norm_pr) + 8.0 * norm_pr * norm_pr * (progress + 0.5);

    // Penalize dead space: quadratic in small residuals
    if pr > 0.0 {
        score += 12.0 * (cap - pr) / cap * (pr / (pr + 6.0));
    }

    // Reward tight fits smoothly
    let tightness = 1.0 - (pr / cap);
    score -= 10.0 * tightness * tightness * (1.0 - progress);

    // Last-chance bonus: only one fitting bin
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - progress);
    }

    // Lookahead: reward if next item fits the post residual
    if next_item_size > 0 {
        if (next_item_size as f64) <= pr {
            score -= 6.0 * (next_item_size as f64 / cap);
        } else {
            score += 4.0 * (1.0 - pr / cap) * (next_item_size as f64 / cap);
        }
    }

    // Mild pressure from many open bins with high mean residual
    score += 0.05 * open_bins_count as f64 * (mean_residual / cap).max(0.0) * progress;

    // New-bin candidate: prefer opening a fresh bin only when residuals are tight
    if bin_residual == bin_capacity {
        score += 5.0 + 10.0 * (1.0 - progress) - 4.0 * (mean_residual / cap);
    }

    score
}

