pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify dead space by capacity fraction.
    let cap = bin_capacity as f64;
    let quarter = bin_capacity / 4;
    let tenth = bin_capacity / 10;

    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 50.0;
    } else {
        // Penalize residuals that are too small to hold the smallest plausible item.
        if post_residual < 10 {
            score += 40.0;
        }
        // Harmonic classes: residuals in [1..10) are dead, [10..25) weak,
        // [25..50) usable for medium items, >=50 keeps flexibility.
        if post_residual < tenth {
            score += 25.0;
        } else if post_residual < quarter {
            score += 10.0;
        } else if post_residual >= bin_capacity / 2 {
            score -= 8.0;
        }
        // Modulo arithmetic: residuals that are multiples of common item sizes
        // (10, 20, 25, 50) are more likely to be filled by future items.
        let pr = post_residual;
        if pr % 10 == 0 || pr % 25 == 0 {
            score -= 6.0;
        }
        // Lookahead: if the next item fits exactly in the post residual, reward strongly.
        if next_item_size > 0 {
            if next_item_size == post_residual {
                score -= 30.0;
            } else if next_item_size < post_residual {
                let after_next = post_residual - next_item_size;
                if after_next < 10 {
                    score -= 12.0; // chain fill nearly completes the bin
                } else {
                    score -= 4.0;
                }
            } else {
                // Next item cannot follow into this bin: penalize if it forces a new bin.
                score += 5.0;
