    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let size_pull = (item_size as f64 / cap) * 14.0;
        if fitting_bins_count <= 2 && gap > 0.0 {
            score -= (18.0 + size_pull) * (1.0 - progress * 0.6);
        } else {
            score += 8.0 + 6.0 * (1.0 - progress);
        }
    }

    // Snug post-residual bonus for next item.
    if next_item_size > 0 && pr > 0.0 {
        let nxt = next_item_size as f64;
        let snug = (pr - nxt) / cap;
        if snug >= 0.0 && snug < 0.04 {
            score -= (0.04 - snug) * 22.0 * (0.6 + progress * 0.6);
        }
    }

    // Consolidation pressure with many open bins.
    if open_bins_count > 8 {
        score += post_norm * 5.0 * ((open_bins_count.min(20) as f64 - 8.0) / 12.0);
    }

    // Remaining-after-next analysis.
    if next_item_size > 0 && pr > next_item_size as f64 {
        let rem_norm = (pr - next_item_size as f64) / cap;
        if rem_norm > 0.0 && rem_norm < 0.03 {
            score -= (0.03 - rem_norm) * 10.0 * (0.4 + progress);
        } else if rem_norm > 0.16 {
            score += (rem_norm - 0.16) * 8.0 * (0.5 + progress);
        }
    }

    // Mid-range residual that next item cannot use.
    if pr > 0.0 && post_norm >= 0.10 && post_norm < 0.20 && next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt > pr {
            score += (nxt - pr) / cap * 26.0 * (0.4 + progress * 0.8);
        }
    }

    // Small leftover relative to item late in stream.
    if pr > 0.0 && pr < (item_size as f64) * 0.5 && progress > 0.3 {
        score += 4.0 * (1.0 - progress);
    }

    // Dead space after next placement.
    if next_item_size > 0 && pr > 0.0 {
        let nxt = next_item_size as f64;
        let dead = (pr - nxt).max(0.0) / cap;
        if dead > 0.0 && dead < 0.08 {
            let third = if dead * cap >= nxt { 1.0 } else { 0.0 };
            score += (0.08 - dead) * 16.0 * (1.0 - third * 0.5) * (0.5 + progress);
        }
    }

    // New bin that can host next item too.
    if bin_residual == bin_capacity && next_item_size > 0 && fitting_bins_count <= 3 {
        let nxt = next_item_size as f64;
        if item_size as f64 >= nxt * 0.95 {
            score -= 5.5 * (1.0 - progress * 0.5);
        }
    }

    // NEW: exact-fit drive — prefer bins whose post-residual is a small integer
    // slice that common item sizes can still consume exactly.
    if pr > 0 && next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr == nxt as f64 {
            score -= 12.0 * (0.6 + progress * 0.5);
        } else if pr > nxt as f64 && (pr - nxt as f64) <= 2.0 {
            score -= 6.5 * (0.5 + progress);
        }
    }

    // NEW: penalize bins whose residual after this placement falls into a
    // "dead band" that few typical item sizes (1..=100) can use usefully
    // (residuals in (50, 60) or (25, 30) leave awkward gaps for next pairs).
    if pr > 0.0 {
        let pn = post_norm;
        if (pn > 0.50 && pn < 0.60) || (pn > 0.25 && pn < 0.30) {
            score += 3.5 * (0.4 + progress * 0.8);
        }
    }

    // NEW: when many bins fit, favor the one that best pairs with next item:
    // reward post-residual divisible-by-pattern compatibility.
    if fitting_bins_count >= 2 && next_item_size > 0 && pr > 0.0 {
        let nxt = next_item_size as f64;
        if pr >= nxt && (pr - nxt) < item_size as f64 {
            score -= 4.0 * (0.5 + progress * 0.5);
        }
    }

    // NEW: late-stream consolidation — as the stream ends, strongly prefer
    // filling existing bins over opening new ones.
    if bin_residual == bin_capacity && progress > 0.6 {
        score += 10.0 * (progress - 0.6) * 2.5;
    }
    if bin_residual != bin_capacity && progress > 0.6 && gap < 0.05 {
        score -= 5.0 * (progress - 0.6) * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (post_residual small relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space: residuals too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= 6.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            score += 4.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // Many open bins: discourage spreading; few open bins: encourage packing.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let crowd = open_bins_count as f64 / (1.0 + progress * 10.0);
    score += 0.8 * crowd;

    // Deviation from mean residual: prefer bins near or below average residual.
    let dev = bin_residual as f64 - mean_residual;
    score += 0.15 * dev;

    // Slight time decay of new-bin attractiveness: later, prefer existing bins.
    if bin_residual == bin_capacity {
        score += 5.0 * (1.0 - progress);
    }

    score
}

