            score -= 100.0; // must open a bin
        } else if fitting_bins_count <= 2 && gap > 0.0 {
            score -= (18.0 + (item_size as f64 / cap) * 14.0) * (1.0 - progress * 0.6);
        } else {
            score = 55.0 + 40.0 * progress - (open_bins_count as f64 / 10.0).min(3.0) * 10.0;
        }
        // New bin that can host next item too.
        if next_item_size > 0 && fitting_bins_count <= 3 {
            let nxt = next_item_size as f64;
            if item_size as f64 >= nxt * 0.95 {
                score -= 5.5 * (1.0 - progress * 0.5);
            }
        }
    }

    // Consolidation pressure with many open bins.
    if open_bins_count > 8 {
        score += post_norm * 5.0 * ((open_bins_count.min(20) as f64 - 8.0) / 12.0);
    }

    // Mild global pressure: prefer packing tight bins when mean residual is high.
    score -= (mean_residual / cap) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let post_norm = pr / cap;
    let mut score = post_norm * post_norm * 58.0 + post_norm * 21.0;

    // Lookahead: gaussian reward when post_residual matches next item snugly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (pr - nxt) / cap;
        score -= (-diff * diff * 470.0).exp() * 21.5 * (1.0 - progress * 0.5);
        if pr < nxt {
            score += (nxt - pr) / cap * 32.0 * (1.0 - progress);
        }
    }

    // Near-perfect fills.
    if pr == 0 {
        score -= 16.0;
    } else if post_norm < 0.05 {
        score -= 10.5 * (1.0 - post_norm / 0.05);
    }

    let gap = (bin_residual - item_size) as f64 / cap;
    if gap > 0.0 && gap < 0.10 {
        score -= (0.10 - gap) * 42.0;
    }
    if gap > 0.10 && gap < 0.22 && next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr > 0.0 && pr < nxt {
            score += (gap - 0.10) * 92.0 * (0.5 + progress);
        }
    }
    if gap >= 0.22 && gap < 0.35 && progress > 0.55 {
        score += (gap - 0.22) * 47.0 * (progress - 0.55) * 2.0;
    }

    // Two-step lookahead: penalize dead space after placing next item.
    if next_item_size > 0 && gap > 0.12 {
        let nxt = next_item_size as f64;
        let nxt_gap = (gap * cap - nxt).max(0.0) / cap;
        if nxt_gap < 0.06 {
            score -= 9.5 * (1.0 - nxt_gap / 0.06) * (0.5 + progress);
        }
    }

    if fitting_bins_count > 2 {
        score += gap * 6.0 * ((fitting_bins_count.min(12) as f64 - 2.0) / 10.0);
    }

    // Deviation from mean residual.
    if pr > 0.0 {
        let dev = (mean_residual - pr) / cap;
        if dev > 0.05 {
            score += (dev - 0.05) * 12.5 * (0.4 + progress);
        } else if dev < -0.08 {
            score += (-dev - 0.08) * 6.5 * (1.0 - progress);
        }
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let size_pull = (item_size as f64 / cap) * 15.0;
        if fitting_bins_count <= 2 && gap > 0.0 {
            score -= (18.5 + size_pull) * (1.0 - progress * 0.6);
        } else {
            score += 8.5 + 6.5 * (1.0 - progress);
        }
    }

    // Snug post-residual bonus for next item.
    if next_item_size > 0 && pr > 0.0 {
        let nxt = next_item_size as f64;
        let snug = (pr - nxt) / cap;
        if snug >= 0.0 && snug < 0.04 {
            score -= (0.04 - snug) * 23.0 * (0.6 + progress * 0.6);
        }
    }

    // Consolidation pressure with many open bins.
    if open_bins_count > 8 {
        score += post_norm * 5.5 * ((open_bins_count.min(20) as f64 - 8.0) / 12.0);
    }

    // Remaining-after-next analysis.
    if next_item_size > 0 && pr > next_item_size as f64 {
        let rem_norm = (pr - next_item_size as f64) / cap;
        if rem_norm > 0.0 && rem_norm < 0.03 {
            score -= (0.03 - rem_norm) * 10.5 * (0.4 + progress);
        } else if rem_norm > 0.16 {
            score += (rem_norm - 0.16) * 8.5 * (0.5 + progress);
        }
    }

    // Mid-range residual that next item cannot use.
    if pr > 0.0 && post_norm >= 0.10 && post_norm < 0.20 && next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt > pr {
            score += (nxt - pr) / cap * 27.0 * (0.4 + progress * 0.8);
        }
    }

    // Small leftover relative to item late in stream.
    if pr > 0.0 && pr < (item_size as f64) * 0.5 && progress > 0.3 {
        score += 4.5 * (1.0 - progress);
    }

    // Dead space after next placement.
    if next_item_size > 0 && pr > 0.0 {
        let nxt = next_item_size as f64;
        let dead = (pr - nxt).max(0.0) / cap;
        if dead > 0.0 && dead < 0.08 {
            let third = if dead * cap >= nxt { 1.0 } else { 0.0 };
            score += (0.08 - dead) * 17.0 * (1.0 - third * 0.5) * (0.5 + progress);
        }
    }

    // New bin that can host next item too.
    if bin_residual == bin_capacity && next_item_size > 0 && fitting_bins_count <= 3 {
        let nxt = next_item_size as f64;
        if item_size as f64 >= nxt * 0.95 {
            score -= 6.0 * (1.0 - progress * 0.5);
        }
    }

    // NEW: exact-fit reward — placing the item leaves zero dead space now.
    if pr == 0 && bin_residual != bin_capacity {
        score -= 6.0 * (1.0 - progress * 0.4);
    }

    // NEW: fit-ratio term — prefer bins where the item consumes most of the gap.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    if fit_ratio > 0.7 && bin_residual != bin_capacity {
        score -= (fit_ratio - 0.7) * 14.0 * (0.6 + progress * 0.5);
    } else if fit_ratio < 0.35 && gap > 0.30 {
        score += (0.35 - fit_ratio) * 9.0 * (0.4 + progress);
    }

    // NEW: when few bins can fit the item, favor the tightest usable bin harder.
    if fitting_bins_count <= 3 && gap > 0.0 {
        score += gap * 10.0 * (1.0 - (fitting_bins_count as f64) / 3.0) * (0.5 + progress * 0.5);
    }

    // NEW: late-stream exactness — near the end, minimize any residual waste harder.
    if progress > 0.75 && pr > 0.0 {
        score += post_norm * 7.0 * ((progress - 0.75) / 0.25);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) nonlinearly.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * fit_ratio * fit_ratio;

    // Reward using nearly the whole bin.
    let fill = item_size as f64 / bin_residual as f64;
    score -= 25.0 * fill * fill;

    // Last-chance bonus: this is the only bin that fits the item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 100.0;
    }

    // New-bin candidate: penalize opening a new bin unless it enables
    // a great future pairing with the lookahead item, or current bins
    // are already tightly packed.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let avg_open = if open_bins_count > 0 { mean_residual } else { bin_capacity as f64 };
        // If lookahead fits exactly into a fresh bin, opening is attractive.
        let pair_bonus = if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            1.0 - (item_size + next_item_size) as f64 / bin_capacity as f64
        } else {
            0.0
        };
        score += 60.0; // base cost of a new bin
        score -= 70.0 * pair_bonus;
        // Late in the stream, prefer consolidating into existing bins.
        score += 30.0 * progress;
        // If open bins are roomy on average, discourage new bins.
        score += (avg_open / bin_capacity as f64) * 20.0;
        // Few fitting bins means we have little choice; soften new-bin cost.
        if fitting_bins_count <= 1 {
            score -= 55.0;
        }
    }

    // Lookahead coupling: penalize leaving residual that neither fits
    // the next item well nor is tiny dead space.
    if next_item_size > 0 && !is_new_bin {
        let gap = post_residual as i64 - next_item_size as i64;
        if gap >= 0 {
            // Next item fits after this placement: reward snug continuation.
            score -= 15.0 * (1.0 - gap as f64 / bin_capacity as f64);
        } else {
            // Dead space relative to lookahead: penalize proportionally.
            score += 8.0 * (-gap) as f64 / bin_capacity as f64;
        }
    }

    // Mild preference to spread across bins when many are open with
    // large residuals (avoid hoarding into one bin).
    if open_bins_count > 2 {
        let roominess = (mean_residual / bin_capacity as f64 - 0.5).max(0.0);
        score += 5.0 * roominess * (bin_residual as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let next = next_item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let post_norm = pr / cap;
    let fit_ratio = item_size as f64 / cap;
    let mut score = post_norm * post_norm * 50.0 + post_norm * 20.0;

    // ---- Aggressive 2-step lookahead: shape score around the NEXT item ----
    if next > 0.0 {
        if pr == next {
            // Perfect 2-chain: this bin will be exactly closed by the next item.
            score -= 45.0 * (1.0 - progress * 0.4);
        } else if pr > next {
            // Bin can still host the next item; gaussian coupling on chain tightness.
            let slack = pr - next;
            let slack_norm = slack / cap;
            score -= 20.0 * (1.0 - slack_norm).max(0.0);
            score -= (-slack_norm * slack_norm * 458.0).exp() * 20.2 * (1.0 - progress * 0.5);
            // Snug bonus: post-residual barely larger than next item.
            if slack_norm < 0.04 {
                score -= (0.04 - slack_norm) * 22.0 * (0.6 + progress * 0.6);
            }
        } else if pr > 0.0 {
            // Dead space: leftover cannot fit the next item -> penalize gap size.
            score += (next - pr) / cap * 30.5 * (1.0 - progress);
        }
    }

    // Penalize tiny unusable slivers unless they exactly match the next item.
    if pr > 0.0 && pr < 10.0 && pr != next {
        score += 15.0;
    }

    // ---- Relative-to-mean coupling: favor tighter-than-average bins ----
    if pr > 0.0 {
        let dev = (mean_residual - pr) / cap;
        if dev > 0.05 {
            score += (dev - 0.05) * 12.0 * (0.4 + progress);
        } else if dev < -0.08 {
            score += (-dev - 0.08) * 6.0 * (1.0 - progress);
        }
    }

    // ---- New-bin candidate decision (bin_residual == bin_capacity) ----
    if bin_residual == bin_capacity {
        let gap = 1.0 - fit_ratio;
        let size_pull = fit_ratio * 14.0;
        if fitting_bins_count <= 2 && gap > 0.0 {
            score -= (18.0 + size_pull) * (1.0 - progress * 0.6);
        } else if fitting_bins_count == 0 {
            score -= 5.0;
        } else {
            score += 8.0 + 6.0 * (1.0 - progress);
        }
        // New bin that can host next item too.
        if next > 0.0 && fitting_bins_count <= 3 && item_size as f64 >= next * 0.95 {
            score -= 5.5 * (1.0 - progress * 0.5);
        }
    }

    // Exact / near-exact fit bonuses.
    if pr == 0.0 {
        score -= 15.0 + 5.0 * progress;
    } else if post_norm < 0.05 {
        score -= 10.0 * (1.0 - post_norm / 0.05);
    }

    // Grafted: sharp bonus for leaving a tiny gap (<10% of capacity).
    let gap_norm = post_norm;
    if gap_norm > 0.0 && gap_norm < 0.10 {
        score -= (0.10 - gap_norm) * 40.0;
    }

    // Two-step dead-space analysis after next placement.
    if next > 0.0 && pr > next {
        let rem_norm = (pr - next) / cap;
        if rem_norm < 0.03 {
            score -= (0.03 - rem_norm) * 10.0 * (0.4 + progress);
        } else if rem_norm > 0.16 {
            score += (rem_norm - 0.16) * 8.0 * (0.5 + progress);
        }
    }

    // Reward large items filling bins deeply.
    score -= fit_ratio * fit_ratio * 6.0;

    // Congestion pressure: deprioritize sloppy fits when many bins are open.
    if open_bins_count > 8 {
        score += post_norm * 5.0 * ((open_bins_count.min(20) as f64 - 8.0) / 12.0);
    }

    // Mid-range dead space penalty, softened if next item can consume it.
    if post_norm > 0.10 && post_norm < 0.20 && next > 0.0 && next > pr {
        score += (next - pr) / cap * 26.0 * (0.4 + progress * 0.8);
    }
    if post_norm > 0.30 && post_norm < 0.60 {
        let mid = 1.0 - ((post_norm - 0.45) / 0.15).abs();
        let mut pen = mid * 4.0 * (0.5 + progress);
        if next > 0.0 && post_norm >= next / cap * 0.8 {
            pen *= 0.4;
        }
        score += pen;
    }

    // Late-stream consolidation: penalize moderately large residuals late.
    if progress > 0.7 && post_norm > 0.25 {
        score += (post_norm - 0.25) * 6.0 * (progress - 0.7) / 0.3;
    }

    // Last-chance bonus: prefer a bin that would otherwise be wasted.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 - fit_ratio);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Base: prefer tight fits (small post_residual), scaled by capacity.
    let mut score = post / cap;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early on: mildly tolerant of leftover space; late: strongly punish it.
    let poly = 1.0 + 3.0 * progress * progress + 2.0 * progress * (1.0 - progress);
    score += poly * (post / cap).powi(2);

    // Penalize dead space unusable by the lookahead item (smooth logistic-ish gate).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let unusable = (nxt - post).max(0.0) / cap;
        score += 2.5 * unusable * unusable * (1.0 + progress);
        // Reward when next item fits exactly into the post residual.
        let fit_gap = (post - nxt) / cap;
        if post >= nxt {
            score -= 1.2 * (1.0 - fit_gap) * (1.0 - fit_gap);
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 3.0 * (1.0 - progress);
        score -= 1.5;
    }

    // Prefer bins with residual below the running mean (consolidate large gaps).
    score += 0.8 * ((bin_residual as f64) - mean_residual) / cap;

    // Mild preference for reusing existing bins over opening new ones.
    if bin_residual == bin_capacity {
        score += 0.6 + 0.5 * progress;
    }

    // Small smooth tie-breaker coupling bin fill with progress.
    score -= 0.3 * progress * (1.0 - (bin_residual as f64) / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let post_norm = pr / cap;
    let gap = (bin_residual - item_size) as f64 / cap;

    // Base: quadratic waste pressure (borrowed from best-known).
    let mut score = post_norm * post_norm * 56.5 + post_norm * 21.8;

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 200.0;
    } else if post_norm < 0.05 {
        score -= 10.2 * (1.0 - post_norm / 0.05);
    }

    // Dead-space class: tiny residuals are almost unusable.
    if post_residual > 0 && post_residual <= 12 {
        score += 25.0 * (13.0 - post_residual as f64);
    }

    // Harmonic divisibility of leftover.
    if post_residual > 0 {
        let p = post_residual;
        if p % 50 == 0 { score -= 18.0; }
        else if p % 25 == 0 { score -= 12.0; }
        else if p % 20 == 0 { score -= 10.0; }
        else if p % 10 == 0 { score -= 8.0; }
        else { score += (p % 5) as f64 * 1.5; }
    }

    // Lookahead: gaussian snug reward for next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (pr - nxt) / cap;
        score -= (-diff * diff * 458.0).exp() * 20.2 * (1.0 - progress * 0.5);
        if pr < nxt {
            score += (nxt - pr) / cap * 30.5 * (1.0 - progress);
        }
        if pr == nxt {
            score -= 40.0;
        }
        // Two-step lookahead: dead space after next placement.
        if gap > 0.12 {
            let nxt_gap = (gap * cap - nxt).max(0.0) / cap;
            if nxt_gap < 0.06 {
                score -= 9.0 * (1.0 - nxt_gap / 0.06) * (0.5 + progress);
            }
        }
        // Snug post-residual bonus.
        if pr > 0.0 {
            let snug = (pr - nxt) / cap;
            if snug >= 0.0 && snug < 0.04 {
                score -= (0.04 - snug) * 22.0 * (0.6 + progress * 0.6);
            }
        }
        // Mid-range residual next item cannot use.
        if pr > 0.0 && post_norm >= 0.10 && post_norm < 0.20 && nxt > pr {
            score += (nxt - pr) / cap * 26.0 * (0.4 + progress * 0.8);
        }
        // Remaining-after-next analysis.
        if pr > nxt {
            let rem_norm = (pr - nxt) / cap;
            if rem_norm < 0.03 {
                score -= (0.03 - rem_norm) * 10.0 * (0.4 + progress);
            } else if rem_norm > 0.16 {
                score += (rem_norm - 0.16) * 8.0 * (0.5 + progress);
            }
        }
    }

    // Gap banding on current fit.
    if gap > 0.0 && gap < 0.10 {
        score -= (0.10 - gap) * 40.5;
    }
    if gap > 0.10 && gap < 0.22 && next_item_size > 0 && pr > 0.0 && pr < next_item_size as f64 {
        score += (gap - 0.10) * 90.5 * (0.5 + progress);
    }
    if gap >= 0.22 && gap < 0.35 && progress > 0.55 {
        score += (gap - 0.22) * 45.5 * (progress - 0.55) * 2.0;
    }

    // Last-chance bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Deviation from mean residual.
    if pr > 0.0 {
        let dev = (mean_residual - pr) / cap;
        if dev > 0.05 {
            score += (dev - 0.05) * 12.0 * (0.4 + progress);
        } else if dev < -0.08 {
            score += (-dev - 0.08) * 6.0 * (1.0 - progress);
        }
    }

    // Consolidation pressure with many open bins.
    if open_bins_count > 8 {
        score += post_norm * 5.0 * ((open_bins_count.min(20) as f64 - 8.0) / 12.0);
    }
    if fitting_bins_count > 2 {
        score += gap * 6.5 * ((fitting_bins_count.min(12) as f64 - 2.0) / 10.0);
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let size_pull = (item_size as f64 / cap) * 14.0;
        if fitting_bins_count <= 2 && gap > 0.0 {
            score -= (18.0 + size_pull) * (1.0 - progress * 0.6);
            if next_item_size > 0 && fitting_bins_count <= 3 && item_size as f64 >= next_item_size as f64 * 0.95 {
                score -= 5.5 * (1.0 - progress * 0.5);
            }
        } else {
            score += 8.0 + 6.0 * (1.0 - progress);
        }
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Small leftover relative to item late in stream.
    if pr > 0.0 && pr < (item_size as f64) * 0.5 && progress > 0.3 {
        score += 4.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: integer division into deciles of capacity
    let class = post_residual / 10;
    let class_penalty = match class {
        0 => -30.0,          // near-perfect fit, dead space < 10
        1 => -18.0,
        2 => -10.0,
        3 => -4.0,
        4 => 0.0,
        5 => 3.0,
        6 => 6.0,
        7 => 9.0,
        8 => 12.0,
        _ => 15.0,           // huge leftover, wasteful
    };
    score += class_penalty;

    // Modulo arithmetic: residuals that are "friendly" multiples (divisible by
    // common small item sizes) are more reusable by future arrivals.
    let pr = post_residual;
    if pr > 0 {
        let friendly = (pr % 10 == 0) as f64 * 6.0
            + (pr % 20 == 0) as f64 * 6.0
            + (pr % 25 == 0) as f64 * 5.0
            + (pr % 5 == 0) as f64 * 2.0;
        score -= friendly;
        // Odd, awkward residuals are hard to fill
        if pr % 2 == 1 { score += 2.5; }
        if pr % 7 == 0 { score -= 1.5; }
    }

    // Exact fit: perfect packing
    if post_residual == 0 { score -= 60.0; }

    // Lookahead: does the next item fit into the post residual?
    if next_item_size > 0 && next_item_size <= pr {
        score -= 12.0;
        // Harmonic match: next item exactly consumes a class boundary
        if pr % next_item_size == 0 { score -= 8.0; }
        // Next item leaves again a small dead space -> chain of good fits
        let npr = pr - next_item_size;
        if npr < 10 { score -= 6.0; }
    } else if next_item_size > pr && next_item_size > 0 {
        // Next item won't fit here; residual becomes dead space for lookahead
        score += 5.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin fit is bad
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(2) as f64);
        // Base cost of a fresh bin
        score += 40.0;
        // Early in stream, new bins are cheaper (more future to fill them)
        score -= 25.0 * (1.0 - progress);
        // If many open bins with slack, avoid another
        if mean_residual > cap * 0.35 { score += 15.0; }
        if open_bins_count > 4 { score += 6.0 * (open_bins_count as f64).sqrt(); }
        // Large items (>= half capacity) justify fresh bins
        if item_size >= bin_capacity / 2 { score -= 20.0; }
    }

    // Prefer tighter bins overall: deviation from mean residual
    score += 0.15 * (bin_residual as f64 - mean_residual).abs();

    // Mild preference for filling bins that are already half-empty
    if bin_residual < bin_capacity / 2 { score -= 4.0; }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
