    let post_norm = pr / cap;
    let mut score = post_norm * post_norm * 58.5 + post_norm * 21.0;

    // Lookahead: gaussian reward when post_residual matches next item snugly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (pr - nxt) / cap;
        score -= (-diff * diff * 480.0).exp() * 21.5 * (1.0 - progress * 0.5);
        if pr < nxt {
            score += (nxt - pr) / cap * 32.0 * (1.0 - progress);
        }
    }

