    if pr == 0 {
        score -= 16.5;
    } else if post_norm < 0.05 {
        score -= 10.8 * (1.0 - post_norm / 0.05);
    }

    let gap = (bin_residual - item_size) as f64 / cap;
    if gap > 0.0 && gap < 0.10 {
        score -= (0.10 - gap) * 42.0;
    }
    if gap > 0.10 && gap < 0.22 && next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr > 0.0 && pr < nxt {
            score += (gap - 0.10) * 94.0 * (0.5 + progress);
        }
    }
    if gap >= 0.22 && gap < 0.35 && progress > 0.55 {
        score += (gap - 0.22) * 47.0 * (progress - 0.55) * 2.0;
    }

    // Two-step lookahead: penalize dead space after placing next item.
    if next_item_size > 0 && gap > 0.12 {
        let nxt = next_item_size as f64;
        let nxt_gap = (gap * cap - nxt).max(0.0) / cap;
        if nxt_gap < 0.06 {
            score -= 9.5 * (1.0 - nxt_gap / 0.06) * (0.5 + progress);
        }
    }

    if fitting_bins_count > 2 {
        score += gap * 6.8 * ((fitting_bins_count.min(12) as f64 - 2.0) / 10.0);
    }

    // Deviation from mean residual.
    if pr > 0.0 {
        let dev = (mean_residual - pr) / cap;
        if dev > 0.05 {
            score += (dev - 0.05) * 12.5 * (0.4 + progress);
        } else if dev < -0.08 {
            score += (-dev - 0.08) * 6.2 * (1.0 - progress);
        }
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let size_pull = (item_size as f64 / cap) * 14.5;
        if fitting_bins_count <= 2 && gap > 0.0 {
            score -= (18.5 + size_pull) * (1.0 - progress * 0.6);
        } else {
            score += 8.5 + 6.2 * (1.0 - progress);
        }
    }

    // Snug post-residual bonus for next item.
    if next_item_size > 0 && pr > 0.0 {
        let nxt = next_item_size as f64;
        let snug = (pr - nxt) / cap;
        if snug >= 0.0 && snug < 0.045 {
            score -= (0.045 - snug) * 23.0 * (0.6 + progress * 0.6);
        }
    }

    // Consolidation pressure with many open bins.
    if open_bins_count > 8 {
        score += post_norm * 5.5 * ((open_bins_count.min(20) as f64 - 8.0) / 12.0);
    }

    // Remaining-after-next analysis.
    if next_item_size > 0 && pr > next_item_size as f64 {
        let rem_norm = (pr - next_item_size as f64) / cap;
        if rem_norm > 0.0 && rem_norm < 0.03 {
            score -= (0.03 - rem_norm) * 10.5 * (0.4 + progress);
        } else if rem_norm > 0.15 {
            score += (rem_norm - 0.15) * 8.5 * (0.5 + progress);
        }
    }

    // Mid-range residual that next item cannot use.
    if pr > 0.0 && post_norm >= 0.10 && post_norm < 0.20 && next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt > pr {
            score += (nxt - pr) / cap * 27.0 * (0.4 + progress * 0.8);
        }
    }

    // Small leftover relative to item late in stream.
    if pr > 0.0 && pr < (item_size as f64) * 0.5 && progress > 0.3 {
        score += 4.2 * (1.0 - progress);
    }

    // Dead space after next placement (refined: scale penalty by whether
    // the dead space could host a following small item).
    if next_item_size > 0 && pr > 0.0 {
        let nxt = next_item_size as f64;
        let dead = (pr - nxt).max(0.0) / cap;
        if dead > 0.0 && dead < 0.08 {
            let third = if dead * cap >= nxt { 1.0 } else { 0.0 };
            score += (0.08 - dead) * 17.0 * (1.0 - third * 0.5) * (0.5 + progress);
        }
    }

    // New bin that can host next item too.
    if bin_residual == bin_capacity && next_item_size > 0 && fitting_bins_count <= 3 {
        let nxt = next_item_size as f64;
        if item_size as f64 >= nxt * 0.95 {
            score -= 6.0 * (1.0 - progress * 0.5);
        }
    }

    // NEW: dead-space ratio coupling — penalize bins whose residual after
    // placement leaves a gap that no plausible small item (<= next size)
    // can fill, stronger late in the stream when consolidation matters.
    if pr > 0.0 && next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr > nxt {
            let unusable = (pr - nxt) / cap;
            if unusable > 0.20 {
                score += (unusable - 0.20) * 11.0 * (0.35 + progress);
            }
        }
    }

