    // post-residual is small but nonzero and next item fits almost exactly,
    // prefer it over near-empty residuals to avoid fragmenting small gaps.
    if pr > 0.0 && next_item_size > 0 && post_norm < 0.06 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            score -= (0.06 - post_norm) * 8.0 * (0.5 + progress * 0.7);
        }
    }

    score
}

