pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: post_residual in a "dead zone" (too small
    // for typical future items) is heavily penalized.
    let dead_threshold = 12.0 + 0.05 * (bin_capacity as f64); // ~17
    if (post_residual as f64) > 0.0 && (post_residual as f64) < dead_threshold {
        score += 3.5 * (dead_threshold - post_residual as f64);
    }

    // Perfect / near-perfect fits get strong reward.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Tightness ratio: favor bins where the item fills a large fraction.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 20.0 * fill_ratio;

    // Open bins pressure: when many bins are open, prefer consolidation
    // (penalize opening/spreading into new bins).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln().max(0.0) * (0.5 + progress);
    score += pressure * (1.0 - fill_ratio).max(0.0) * 10.0;

    // Last chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive if current item is large
    // relative to residuals and mean residual across bins is small.
    if bin_residual == bin_capacity {
        let mean_gap = (mean_residual - item_size as f64).max(0.0);
        score = score * 0.2 + 30.0 + mean_gap * 0.5
            + (open_bins_count as f64) * 0.3;
        // Large items with poor fit everywhere justify a fresh bin.
        if item_size >= 60 && mean_residual < item_size as f64 {
            score -= 20.0;
        }
    }

    // Lookahead: if the next item would fit the post residual, reward it.
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        score -= 8.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // Next item cannot use the gap -> dead space penalty.
        score += 4.0 * (1.0 - (post_residual as f64) / (next_item_size as f64).max(1.0)).max(0.0);
    }

    score
}

