pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size -> strong reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    }

    // Next item fits into post residual: reward proportionally to tightness of 2-step fill.
    if next_item_size > 0 && next_item_size <= post_residual {
        let two_step_fill = (item_size + next_item_size) as f64 / bin_capacity as f64;
        score -= 25.0 * two_step_fill;
    } else if next_item_size > post_residual {
        // Next item cannot follow here: penalize leftover dead space, more so if large.
        let waste = post_residual as f64 / bin_capacity as f64;
        score += 15.0 * waste;
    }

    // Relative to mean residual: prefer bins that end closer to the mean residual
    // (keeps residual distribution balanced), but reward tighter-than-average outcomes.
    let diff = post_residual as f64 - mean_residual;
    score += 0.3 * diff;

    // Last-chance bin: strongly discourage abandoning it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin unless existing residuals are all poor.
    if bin_residual == bin_capacity {
        let base_penalty = 30.0;
        // If average open residual is large, existing bins are fine -> keep penalty high.
        // If mean residual is small, opening a fresh bin is more attractive.
        score = base_penalty + mean_residual - 0.5 * post_residual as f64;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 5.0; // a fresh bin can always host the next item
        }
    }

    // Late in the stream: be more conservative, prefer filling existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

