    }
    if gap > 0.10 && gap < 0.22 && next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr > 0.0 && pr < nxt {
            score += (gap - 0.10) * 90.5 * (0.5 + progress);
        }
