        let nxt = next_item_size as f64;
        let nxt_gap = (gap * cap - nxt).max(0.0) / cap;
        if nxt_gap < 0.05 {
            score -= 11.5 * (1.0 - nxt_gap / 0.05) * (0.5 + progress);
        } else if nxt_gap > 0.20 {
            score += (nxt_gap - 0.20) * 7.5 * (0.4 + progress);
        }
