        let nxt = next_item_size as f64;
        if item_size as f64 >= nxt * 0.95 {
            score -= 5.5 * (1.0 - progress * 0.5);
        }
    }

    // Late-stream: strongly prefer near-zero post residuals to close bins.
    if progress > 0.7 && pr > 0.0 && post_norm < 0.12 {
        score -= (0.12 - post_norm) * 14.0 * (progress - 0.7) * 3.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let r = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_r = r / cap;
    let mut score = r;

    // Base: prefer small post residual, with non-linear sharpening
    score += 40.0 * norm_r * norm_r;

    // Perfect-fit reward (smooth, non-piecewise)
    let perfect = 1.0 - norm_r;
    score -= 60.0 * perfect * perfect * perfect;

    // Late in the stream: be more frugal (penalize wasted residual more)
    score += 30.0 * progress * norm_r;

    // Coupling with mean residual of open bins: if this bin's residual
    // is below the mean, it's a tighter fit -> reward it
    let mean_gap = (mean_residual - r) / cap;
    score -= 20.0 * mean_gap;

    // Last-chance bin bonus: if this is the only fitting bin, strongly favor it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Lookahead: if next item fits exactly in the post-residual, reward;
    // if next item won't fit anywhere, penalize leaving large residuals
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= r {
            let nx_fit = 1.0 - (nx / r);
            score -= 25.0 * nx_fit * nx_fit;
        } else {
            score += 15.0 * (nx - r) / cap;
        }
    }

    // Penalize opening new bins when many open bins exist
    if bin_residual == bin_capacity {
        score += 50.0 + 5.0 * open_bins_count as f64;
        // But late in stream, a fresh bin may be better than a bad fit
        score -= 40.0 * progress;
    }

    // Mild penalty for very tight bins (fragmentation risk with future items)
    score += 10.0 * norm_r * (1.0 - norm_r) * (1.0 - norm_r);

    score
}

