    let progress = step_index as f64 / total_items.max(1) as f64;
    let post_norm = pr / cap;
    let mut score = post_norm * post_norm * 58.0 + post_norm * 21.0;

    // Lookahead: gaussian reward when post_residual matches next item snugly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (pr - nxt) / cap;
        score -= (-diff * diff * 470.0).exp() * 21.0 * (1.0 - progress * 0.5);
        if pr < nxt {
            score += (nxt - pr) / cap * 32.0 * (1.0 - progress);
        }
    }

    // Near-perfect fills.
    if pr == 0 {
        score -= 16.0;
    } else if post_norm < 0.05 {
        score -= 10.5 * (1.0 - post_norm / 0.05);
    }

    let gap = (bin_residual - item_size) as f64 / cap;
    if gap > 0.0 && gap < 0.10 {
        score -= (0.10 - gap) * 42.0;
    }
    if gap > 0.10 && gap < 0.22 && next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr > 0.0 && pr < nxt {
            score += (gap - 0.10) * 92.0 * (0.5 + progress);
        }
    }
    if gap >= 0.22 && gap < 0.35 && progress > 0.55 {
        score += (gap - 0.22) * 47.0 * (progress - 0.55) * 2.0;
    }

    // Two-step lookahead: penalize dead space after placing next item.
    if next_item_size > 0 && gap > 0.12 {
        let nxt = next_item_size as f64;
        let nxt_gap = (gap * cap - nxt).max(0.0) / cap;
        if nxt_gap < 0.06 {
            score -= 9.5 * (1.0 - nxt_gap / 0.06) * (0.5 + progress);
        }
    }

    if fitting_bins_count > 2 {
        score += gap * 6.5 * ((fitting_bins_count.min(12) as f64 - 2.0) / 10.0);
    }

    // Deviation from mean residual.
    if pr > 0.0 {
        let dev = (mean_residual - pr) / cap;
        if dev > 0.05 {
            score += (dev - 0.05) * 12.5 * (0.4 + progress);
        } else if dev < -0.08 {
            score += (-dev - 0.08) * 6.5 * (1.0 - progress);
        }
    }

    // New-bin candidate handling (refined: prefer new bins only when item is
    // large relative to capacity or no decent fit exists).
    if bin_residual == bin_capacity {
        let size_pull = (item_size as f64 / cap) * 15.0;
        if fitting_bins_count <= 2 && gap > 0.0 {
            score -= (19.0 + size_pull) * (1.0 - progress * 0.6);
        } else {
            score += 8.5 + 6.5 * (1.0 - progress);
            // Extra penalty for opening a bin when a snug fit exists elsewhere.
            if fitting_bins_count > 4 && gap < 0.05 {
                score += 6.0;
            }
        }
    }

    // Snug post-residual bonus for next item.
    if next_item_size > 0 && pr > 0.0 {
        let nxt = next_item_size as f64;
        let snug = (pr - nxt) / cap;
        if snug >= 0.0 && snug < 0.04 {
            score -= (0.04 - snug) * 23.0 * (0.6 + progress * 0.6);
        }
    }

    // Consolidation pressure with many open bins.
    if open_bins_count > 8 {
        score += post_norm * 5.5 * ((open_bins_count.min(20) as f64 - 8.0) / 12.0);
    }

    // Remaining-after-next analysis.
    if next_item_size > 0 && pr > next_item_size as f64 {
        let rem_norm = (pr - next_item_size as f64) / cap;
        if rem_norm > 0.0 && rem_norm < 0.03 {
            score -= (0.03 - rem_norm) * 10.5 * (0.4 + progress);
        } else if rem_norm > 0.16 {
            score += (rem_norm - 0.16) * 8.5 * (0.5 + progress);
        }
    }

    // Mid-range residual that next item cannot use.
    if pr > 0.0 && post_norm >= 0.10 && post_norm < 0.20 && next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt > pr {
            score += (nxt - pr) / cap * 27.0 * (0.4 + progress * 0.8);
        }
    }

    // Small leftover relative to item late in stream.
    if pr > 0.0 && pr < (item_size as f64) * 0.5 && progress > 0.3 {
        score += 4.5 * (1.0 - progress);
    }

    // Dead space after next placement.
    if next_item_size > 0 && pr > 0.0 {
        let nxt = next_item_size as f64;
        let dead = (pr - nxt).max(0.0) / cap;
        if dead > 0.0 && dead < 0.08 {
            let third = if dead * cap >= nxt { 1.0 } else { 0.0 };
            score += (0.08 - dead) * 17.0 * (1.0 - third * 0.5) * (0.5 + progress);
        }
    }

    // New bin that can host next item too.
    if bin_residual == bin_capacity && next_item_size > 0 && fitting_bins_count <= 3 {
        let nxt = next_item_size as f64;
        if item_size as f64 >= nxt * 0.95 {
            score -= 6.0 * (1.0 - progress * 0.5);
        }
    }

    // New: penalize placing into bins whose residual leaves a large unusable
    // wedge relative to typical remaining item sizes.
    if pr > 0.0 && next_item_size > 0 && pr < next_item_size as f64 {
        let unusable = (next_item_size as f64 - pr) / cap;
        if unusable > 0.03 && unusable < 0.12 {
            score += (unusable - 0.03) * 14.0 * (0.5 + progress * 0.7);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class logic: partition residual space into capacity-fraction classes.
    // Perfect-fit class (post_residual == 0) is strongly rewarded.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Class the post_residual falls into via integer division on capacity quarters.
    let quarter = bin_capacity / 4; // 25
    let half = bin_capacity / 2;    // 50
    let post = post_residual;
    let item = item_size;

    // Dead-space penalty: post_residual that is small but nonzero is the worst outcome
    // (unusable by typical items 1..100). Reward near-zero and large residuals.
    if post > 0 && post < 10 {
        score += 60.0; // tiny unusable sliver
    }

    // Harmonic classes: residual in [1, quarter), [quarter, half), [half, 3/4), [3/4, C)
    // Small residual classes are risky (few future fits) -> penalize moderately.
    if post > 0 && post < quarter {
        score += 25.0;
    } else if post < half {
        score += 8.0;
    } else if post < 3 * quarter {
        score -= 5.0;
    } else {
        score -= 10.0;
    }

    // Lookahead coupling: does the next item fit exactly into the post_residual?
    if next_item_size > 0 {
        if next_item_size == post {
            score -= 500.0; // perfect chain
        } else if next_item_size <= post {
            // next fits: reward proportional to tightness of the chain
            let tight = (post - next_item_size) as f64;
            score -= 40.0 * (1.0 - tight / bin_capacity as f64);
            // harmonic class of the chained leftover
            let chain_post = post - next_item_size;
            if chain_post > 0 && chain_post < quarter {
                score += 15.0;
            }
        } else {
            // next item will NOT fit here: this placement strands the residual
            score += 20.0;
        }
    }

    // Modulo arithmetic on post_residual vs common item sizes (divisors of 100: 10,20,25,50)
    let divisors = [10u32, 20, 25, 50];
    for d in divisors.iter() {
        if post >= *d && post % d == 0 {
            score -= 12.0; // residual aligns with harmonic grid -> likely reusable
            break;
        }
    }
    // Penalize residuals that are awkward modulo classes (prime-ish gaps)
    if post > 0 && post % 10 != 0 && post % 25 != 0 && post < half {
        score += 10.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
        if post <= quarter {
            score += 40.0; // but not if it creates near-dead space
        }
    }

    // New-bin candidate handling: an empty bin has huge residual; make it a
    // neutral fallback with a mild preference cost so tight fits into open
    // bins win, but very poor fits (large dead space) defer to a new bin.
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 - 30.0;
        // early in the stream, opening bins is cheap/flexible
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 20.0 * (1.0 - progress);
        // if next item is large, a fresh bin is more valuable
        if next_item_size > half {
            score -= 15.0;
        }
    }

    // Global pressure: many open bins with high mean residual -> consolidate,
    // prefer filling existing bins more aggressively.
    let pressure = mean_residual / bin_capacity as f64;
    score -= 15.0 * pressure;
    if open_bins_count > 4 {
        score -= 2.0 * (open_bins_count.min(20) as f64);
    }

    // Item-size coupling: large items should prefer the tightest fit
    if item > half {
        score += (post as f64) * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
