    // Prefer bins whose residual is close to the item (tight fit).
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += 40.0 * tightness;

    // Last chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Open-bin pressure: when many bins are open, avoid opening new ones.
    if bin_residual == bin_capacity {
        score += 30.0 + 5.0 * open_bins_count as f64;
        // But if no existing bin fits well and next item is large, opening is fine.
        if next_item_size > 0 && next_item_size > bin_residual.saturating_sub(item_size) {
            score -= 20.0;
        }
    }

    // Lookahead: if next item fits the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 8.0;
    }

    // Mild preference for fuller bins as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 15.0 * (1.0 - post_residual as f64 / bin_capacity as f64) * progress;

    // Discard bins whose residual deviates far from mean (fragmentation control).
    score += 0.3 * ((bin_residual as f64 - mean_residual).abs());

    score
}

