    }
    // Larger gaps late in the stream are wasteful.
    if gap >= 0.22 && gap < 0.35 && progress > 0.55 {
        score += (gap - 0.22) * 45.0 * (progress - 0.55) * 2.0;
    }

    // Two-step lookahead: penalize dead space after next item placement.
    if next_item_size > 0 && gap > 0.12 {
        let nxt_gap = (gap * cap - next_item_size as f64).max(0.0) / cap;
        if nxt_gap < 0.06 {
            score -= 9.0 * (1.0 - nxt_gap / 0.06) * (0.5 + progress);
        }
    }

    // Last-chance bin: strongly favor the only fitting open bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }
    // Spread pressure when many bins fit.
    if fitting_bins_count > 2 {
        score += gap * 6.5 * ((fitting_bins_count.min(12) as f64 - 2.0) / 10.0);
    }

    // Deviation from mean residual.
    if pr > 0.0 {
        let dev = (mean_residual - pr) / cap;
        if dev > 0.05 {
            score += (dev - 0.05) * 12.0 * (0.4 + progress);
        } else if dev < -0.08 {
            score += (-dev - 0.08) * 6.0 * (1.0 - progress);
        }
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let size_pull = (item_size as f64 / cap) * 14.0;
        if fitting_bins_count <= 2 && gap > 0.0 {
            score -= (18.0 + size_pull) * (1.0 - progress * 0.6);
        } else {
            score += 8.0 + 6.0 * (1.0 - progress);
        }
        // New bin that can host next item too.
        if next_item_size > 0 && fitting_bins_count <= 3 && (item_size as f64) >= (next_item_size as f64) * 0.95 {
            score -= 5.5 * (1.0 - progress * 0.5);
        }
    }

    // Consolidation pressure with many open bins.
    if open_bins_count > 8 {
        score += post_norm * 5.0 * ((open_bins_count.min(20) as f64 - 8.0) / 12.0);
    }

    // Remaining-after-next analysis.
    if next_item_size > 0 && pr > next_item_size as f64 {
        let rem_norm = (pr - next_item_size as f64) / cap;
        if rem_norm < 0.03 {
            score -= (0.03 - rem_norm) * 10.0 * (0.4 + progress);
        } else if rem_norm > 0.16 {
            score += (rem_norm - 0.16) * 8.0 * (0.5 + progress);
        }
    }

    // Small leftover relative to item late in stream.
    if pr > 0.0 && pr < item_size as f64 * 0.5 && progress > 0.3 {
        score += 4.0 * (1.0 - progress);
    }

    // Dead space after next placement, with reuse discount.
    if next_item_size > 0 && pr > 0.0 {
        let dead = (pr - next_item_size as f64).max(0.0) / cap;
        if dead > 0.0 && dead < 0.08 {
            let third = if dead * cap >= next_item_size as f64 { 1.0 } else { 0.0 };
            score += (0.08 - dead) * 16.0 * (1.0 - third * 0.5) * (0.5 + progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual).
    score = post_residual as f64 * (1.0 + 0.01 * (item_size as f64 / bin_capacity as f64));

    // 2-step lookahead: reward exact match of post_residual with next item size.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual as f64 == nxt {
            score -= 60.0; // perfect chain: next item fills this bin exactly
        } else if post_residual >= next_item_size {
            let diff = post_residual as f64 - nxt;
            // reward closeness of next item fit
            score -= 40.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // next item cannot fit here: penalize proportional to wasted potential
            let miss = nxt - post_residual as f64;
            score += 10.0 * (miss / bin_capacity as f64);
        }
    }

    // Compare post_residual against mean residual: avoid creating outlier small residuals
    // that become dead space, unless the bin is nearly full anyway.
    let pr = post_residual as f64;
    if pr < mean_residual {
        score += 0.5 * (mean_residual - pr); // creating below-average residual is dead space
    } else {
        score -= 0.2 * (pr - mean_residual); // keeping residual above average preserves flexibility
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive early in the stream or when no good fit exists.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        // Penalize new bins progressively as stream advances (consolidate late).
        score += 20.0 + 60.0 * progress;
        // If next item is large and would pair well with a fresh bin, soften penalty.
        if next_item_size > 0 && next_item_size as f64 >= 0.5 * bin_capacity as f64 {
            score -= 15.0;
        }
    }

    // Slight penalty when many bins are open: encourage consolidation.
    score += 0.05 * open_bins_count as f64;

    score
}

