    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus: strong reward for zero or tiny post-residual.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 60.0;
    } else {
        // Penalize dead space non-linearly; waste that cannot fit a small item is worse.
        let dead = post_residual as f64;
        score += dead * dead / (bin_capacity as f64);
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 80.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Post-residual too small for next item: penalize proportionally.
            let waste = (next_item_size - post_residual) as f64;
            score += 30.0 * (waste / 100.0).min(1.0);
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 250.0;
    }

    // Global pressure: with many open bins, prefer consolidating into existing ones.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual != bin_capacity {
        score -= 20.0 * pressure / (1.0 + open_bins_count as f64);
    }

    // Mean-residual coupling: bins below mean residual are "fuller" — prefer them.
    let dev = mean_residual - bin_residual as f64;
    score += 0.5 * dev;

    // Time horizon: early in stream, be conservative (slight penalty for tight fits
    // that fragment bins); later, pack aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if progress < 0.3 && post_residual > 0 && post_residual < 10 {
        score += 25.0 * (0.3 - progress);
    } else if progress > 0.7 && post_residual <= 15 {
        score -= 40.0 * (progress - 0.7);
    }

    // New-bin candidate: keep it competitive only when existing fits are poor.
    if bin_residual == bin_capacity {
        // Base cost of opening a bin, softened by stream length and bin count.
        score = 60.0 + 40.0 * (1.0 - progress) - 10.0 * pressure;
        if next_item_size > 0 && next_item_size >= item_size {
            // New bin will hold both current and next item comfortably.
            if bin_capacity - item_size >= next_item_size {
                score -= 70.0;
            }
        }
        if fitting_bins_count == 0 {
            score -= 500.0; // no alternative: must open
        }
    }

    score
}

