    // Smooth dead-space shaping: cubic term rewards leaving "usable" mid-range
    // residual (compatible with typical item sizes) and punishes extremes.
    let mid = 0.5 * cap;
    let dev = (pr - mid) / cap;
    score += 25.0 * dev * dev * dev.abs().sqrt() * (1.0 + t);

    // Reward tight fits (small post-residual) with a smooth saturating bonus.
    score -= 30.0 * (1.0 - x).powi(3) * (0.5 + 0.5 * t);

    // Lookahead coupling: if the next item can use the post-residual, reward it.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let fit_next = if pr as f64 >= nx { 1.0 } else { 0.0 };
        let gap = ((pr as f64 - nx).abs()) / cap;
        score -= 20.0 * fit_next * (1.0 - gap * gap) * (1.0 - 0.5 * t);
        score += 10.0 * (1.0 - fit_next) * (x * x);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0 + 20.0 * t;
    }

    // Slight preference for bins below mean residual (better consolidated fit),
