    let mr = mean_residual;
    score += 0.05 * (open_bins_count as f64).sqrt() * (pr as f64 - mr);

    // New-bin candidate: keep it competitive only when open bins are crowded.
    if bin_residual == bin_capacity {
        let crowding = (open_bins_count as f64) / (1.0 + open_bins_count as f64);
        score += 8.0 * (1.0 - crowding) * (1.0 + t) - 5.0 * crowding;
    }

    score
}

