        score += post_norm * 5.5 * ((open_bins_count.min(20) as f64 - 8.0) / 12.0);
    }

    // Remaining-after-next analysis.
    if next_item_size > 0 && pr > next_item_size as f64 {
        let rem_norm = (pr - next_item_size as f64) / cap;
        if rem_norm > 0.0 && rem_norm < 0.03 {
            score -= (0.03 - rem_norm) * 10.5 * (0.4 + progress);
        } else if rem_norm > 0.16 {
            score += (rem_norm - 0.16) * 8.5 * (0.5 + progress);
        }
    }

    // Mid-range residual that next item cannot use.
    if pr > 0.0 && post_norm >= 0.10 && post_norm < 0.20 && next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt > pr {
            score += (nxt - pr) / cap * 27.0 * (0.4 + progress * 0.8);
        }
    }

    // Small leftover relative to item late in stream.
    if pr > 0.0 && pr < (item_size as f64) * 0.5 && progress > 0.3 {
        score += 4.5 * (1.0 - progress);
    }

    // Dead space after next placement.
    if next_item_size > 0 && pr > 0.0 {
        let nxt = next_item_size as f64;
        let dead = (pr - nxt).max(0.0) / cap;
        if dead > 0.0 && dead < 0.08 {
            let third = if dead * cap >= nxt { 1.0 } else { 0.0 };
            score += (0.08 - dead) * 16.5 * (1.0 - third * 0.5) * (0.5 + progress);
        }
    }

    // New bin that can host next item too.
    if bin_residual == bin_capacity && next_item_size > 0 && fitting_bins_count <= 3 {
        let nxt = next_item_size as f64;
        if item_size as f64 >= nxt * 0.95 {
            score -= 6.0 * (1.0 - progress * 0.5);
        }
    }

    // NEW: avoid opening fresh bins when the item fits snugly in an existing bin.
    if bin_residual == bin_capacity {
        let item_norm = item_size as f64 / cap;
        if fitting_bins_count >= 1 {
            // Estimate the tightest alternative fit: if some open bin leaves < 5% slack,
            // strongly discourage the new bin.
            score += 10.0 * (1.0 - item_norm) * (0.6 + progress * 0.4);
        }
        // Large items late in stream prefer a fresh bin to avoid fragmentation.
        if item_norm > 0.55 && progress > 0.5 {
            score -= 4.0 * (item_norm - 0.55) * 2.2;
        }
    }

    // NEW: penalize bins whose post-residual is a "stranded" size — too small for
    // typical future items but too large to be considered full.
    if pr > 0.0 && post_norm > 0.30 && post_norm < 0.48 {
        score += (post_norm - 0.30) * 7.0 * (0.5 + progress);
    }

    // NEW: reward bins that after placement can still hold the next item with
    // room to spare, encouraging chain placements.
    if next_item_size > 0 && pr > next_item_size as f64 {
        let chain = (pr - next_item_size as f64) / cap;
        if chain >= 0.03 && chain < 0.12 {
            score -= (0.12 - chain) * 6.0 * (1.0 - progress * 0.4);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let post_norm = pr / cap;
    let fit_ratio = item_size as f64 / cap;
    let gap = (bin_residual - item_size) as f64 / cap;

    let mut score = post_norm * post_norm * 48.0 + post_norm * 18.0;

    // Smooth polynomial coupling of post_residual with stream progress (parent core).
    let progress_weight = 1.0 + progress * (1.0 - progress) * 4.0;
    score -= pr * pr / (cap * cap) * 34.0 * progress_weight;

    // Lookahead: gaussian reward when post_residual matches next item snugly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (pr - nxt) / cap;
        score -= (-diff * diff * 420.0).exp() * 18.0 * (1.0 - progress * 0.5);
        if pr < nxt {
            score += (nxt - pr) / cap * 28.0 * (1.0 - progress);
        }
        // Two-step lookahead: dead space after next placement.
        let dead = (pr - nxt).max(0.0) / cap;
        if dead > 0.0 && dead < 0.08 {
            score += (0.08 - dead) * 14.0 * (0.5 + progress);
        } else if dead > 0.16 {
            score += (dead - 0.16) * 8.0 * (0.5 + progress);
        }
    }

    // Near-perfect fills.
    if pr == 0 {
        score -= 14.0;
    } else if post_norm < 0.05 {
        score -= 9.0 * (1.0 - post_norm / 0.05);
    }

    // Tight gap band bonus.
    if gap > 0.0 && gap < 0.10 {
        score -= (0.10 - gap) * 38.0;
    }
    // Mid gap band: penalize if next item can't use the leftover.
    if gap >= 0.10 && gap < 0.24 && next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr > 0.0 && pr < nxt {
            score += (gap - 0.10) * 85.0 * (0.5 + progress);
        }
    }
    if gap >= 0.24 && gap < 0.36 && progress > 0.55 {
        score += (gap - 0.24) * 42.0 * (progress - 0.55) * 2.0;
    }

    // Last-chance bonus: prefer using a bin that would otherwise be wasted.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 24.0 * (1.0 - fit_ratio);
    }

    // Scarcity-aware spreading when many bins fit.
    if fitting_bins_count > 2 {
        score += gap * 6.0 * ((fitting_bins_count.min(12) as f64 - 2.0) / 10.0);
    }

    // Deviation from mean residual.
    if pr > 0.0 {
        let dev = (mean_residual - pr) / cap;
        if dev > 0.05 {
            score += (dev - 0.05) * 11.0 * (0.4 + progress);
        } else if dev < -0.08 {
            score += (-dev - 0.08) * 5.5 * (1.0 - progress);
        }
    }

    // New-bin candidate handling: open only when no decent fit exists.
    if bin_residual == bin_capacity {
        let consolidation = mean_residual / cap;
        if fitting_bins_count <= 2 && gap > 0.0 {
            score -= (17.0 + fit_ratio * 13.0) * (1.0 - progress * 0.6);
        } else {
            score += 9.0 + 7.0 * (1.0 - consolidation) * (1.0 - progress);
        }
        if next_item_size > 0 && fitting_bins_count <= 3 {
            let nxt = next_item_size as f64;
            if item_size as f64 >= nxt * 0.95 {
                score -= 5.0 * (1.0 - progress * 0.5);
            }
        }
    }

    // Reward high fill fraction smoothly (parent core, softened).
    score -= (fit_ratio * fit_ratio) * 7.0;

    // Consolidation pressure with many open bins.
    if open_bins_count > 8 {
        score += post_norm * 5.0 * ((open_bins_count.min(20) as f64 - 8.0) / 12.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: perfect fits and tiny residues are gold.
    let pr = post_residual;
