    } else if pr <= 15 {
        score -= 8.0;
    } else {
        // residue classes by integer division on capacity quarters
        let quarter = bin_capacity / 4;
        let class = pr / quarter.max(1);
        score += class as f64 * 6.0; // larger residue class => worse
    }

    // Dead-space penalty: residue that no plausible item (1..=100) can pair with well.
    if pr > 0 && pr < 10 {
        score += 10.0; // awkward sliver
    }

    // Lookahead coupling: does next item fit into the post-residue?
    if next_item_size > 0 && (pr as u64) >= (next_item_size as u64) {
        let slack = pr - next_item_size;
        score -= 4.0 + (slack as f64).min(20.0) * 0.5; // reward chaining
    } else if next_item_size > 0 {
        score += 3.0; // next item won't fit here
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New-bin candidate handling: empty bin is a blank slate.
    if bin_residual == bin_capacity {
        // Prefer a new bin when current open bins are crowded / bad fits.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let pressure = open_bins_count as f64 * 0.5 + mean_residual / cap * 10.0;
        score = cap * 0.55 + pressure - progress * 5.0;
        if next_item_size > 0 && next_item_size >= bin_residual {
            score -= 5.0; // new bin will surely fit next item
        }
        if fitting_bins_count <= 1 {
            score += 40.0; // don't abandon the last usable bin
        }
        if pr == 0 {
            score += 20.0; // an existing bin achieved a perfect fit; keep it
        }
    }

    // Mild normalization of open-bin sprawl.
    score += open_bins_count as f64 * 0.05;

    score
}

