    // New-bin candidate handling: opening a new bin is only attractive when
    // this bin's fit is poor relative to global mean residual
    if bin_residual == bin_capacity {
        let mean_waste = (mean_residual - item_size as f64).max(0.0);
        // base cost of a fresh bin, discounted early in the stream
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 30.0 + 40.0 * (1.0 - progress);
        // if open bins have lots of room, discourage new bin
