        else if r % 10 == 0 { score -= 8.0; }
        else {
            score += (r % 5) as f64 * 1.5;
        }
    }

    // Lookahead: gaussian reward when next item matches post_residual snugly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (pr - nxt) / cap;
        score -= (-diff * diff * 458.0).exp() * 20.2 * (1.0 - progress * 0.5);
        if pr < nxt {
            score += (nxt - pr) / cap * 30.5 * (1.0 - progress);
        } else {
            let nxt_left = pr - nxt;
            if nxt_left % 10 as f64 == 0.0 { score -= 10.0; }
            else if nxt_left > 12.0 { score -= 4.0; }
            else { score += 6.0; }
        }
    }

    // Gap-based shaping relative to current fit.
    let gap = (bin_residual - item_size) as f64 / cap;
    if gap > 0.0 && gap < 0.10 {
        score -= (0.10 - gap) * 40.5;
    }
    if gap >= 0.22 && gap < 0.35 && progress > 0.55 {
        score += (gap - 0.22) * 45.5 * (progress - 0.55) * 2.0;
    }

    // Two-step lookahead: penalize dead space after placing next item.
    if next_item_size > 0 && gap > 0.12 {
        let nxt_gap = (gap * cap - next_item_size as f64).max(0.0) / cap;
        if nxt_gap < 0.06 {
            score -= 9.0 * (1.0 - nxt_gap / 0.06) * (0.5 + progress);
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Crowding pressure: consolidate when many open bins.
    if fitting_bins_count > 2 {
        score += gap * 6.5 * ((fitting_bins_count.min(12) as f64 - 2.0) / 10.0);
    }
    if open_bins_count > 8 {
        score += post_norm * 5.0 * ((open_bins_count.min(20) as f64 - 8.0) / 12.0);
    }

    // Deviation from mean residual.
    if pr > 0.0 {
        let dev = (mean_residual - pr) / cap;
        if dev > 0.05 {
            score += (dev - 0.05) * 12.0 * (0.4 + progress);
        } else if dev < -0.08 {
            score += (-dev - 0.08) * 6.0 * (1.0 - progress);
        }
    }

    // New-bin candidate handling: only win when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        let size_pull = (item_size as f64 / cap) * 14.0;
        if fitting_bins_count <= 2 && gap > 0.0 {
            score -= (18.0 + size_pull) * (1.0 - progress * 0.6);
        } else {
            score += 8.0 + 6.0 * (1.0 - progress);
        }
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a bin
        }
        // New bin that can host next item too.
        if next_item_size > 0 && fitting_bins_count <= 3 {
            let nxt = next_item_size as f64;
            if item_size as f64 >= nxt * 0.95 {
                score -= 5.5 * (1.0 - progress * 0.5);
            }
        }
    }

    // Global pressure: high mean residual -> pack tighter.
    score -= (mean_residual / cap) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify leftover space into
    // capacity-fraction buckets (1/4, 1/2, 3/4 of capacity).
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;

    // Dead-space penalty: residuals below the smallest plausible item (10)
    // are pure waste; below quarter capacity are hard to reuse.
    if post_residual < 10 {
        score += 40.0;
    } else if post_residual < quarter {
        score += 18.0;
    } else if post_residual < half {
        score += 4.0;
    }

    // Harmonic bonus: residual that is an exact multiple of a class boundary
    // (mod arithmetic on post_residual) pairs well with typical item sizes.
    let pr = post_residual as i64;
    if pr % 10 == 0 {
        score -= 6.0; // divisible by 10 -> likely exact fit with 10-multiple items
    }
    if pr % quarter as i64 == 0 && pr > 0 {
        score -= 3.0; // lands on a harmonic class boundary
    }

    // Lookahead: reward residuals that can host the next item exactly or snugly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0; // perfect chain
        } else if next_item_size <= post_residual {
            let gap = post_residual - next_item_size;
            if gap < 10 {
                score -= 12.0; // near-perfect chain, kills dead space
            } else {
                score -= gap as f64 * 0.15;
            }
        } else {
            score += 5.0; // next item cannot reuse this bin
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: empty bin gets a mild penalty so it is
    // chosen only when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        score += 12.0 + 0.1 * open_bins_count as f64;
    } else {
        // Prefer fuller bins (tighter packing): reward small bin_residual.
        score += (bin_residual as f64) * 0.05;
    }

    // Stream progression: late in the stream, consolidate aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 5.0 * (1.0 - (post_residual as f64 / bin_capacity as f64));

    // Prefer bins below mean residual when they fit tightly (balance spread).
    if (bin_residual as f64) < mean_residual && post_residual > 0 {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let post_norm = pr / cap;
    let mut score = post_norm * post_norm * 56.5 + post_norm * 21.8;

    // Lookahead: gaussian reward when post_residual matches next item snugly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (pr - nxt) / cap;
        score -= (-diff * diff * 458.0).exp() * 20.2 * (1.0 - progress * 0.5);
        if pr < nxt {
            score += (nxt - pr) / cap * 30.5 * (1.0 - progress);
        }
    }

    // Near-perfect fills.
    if pr == 0 {
        score -= 15.2;
    } else if post_norm < 0.05 {
        score -= 10.2 * (1.0 - post_norm / 0.05);
    }

    let gap = (bin_residual - item_size) as f64 / cap;
    if gap > 0.0 && gap < 0.10 {
        score -= (0.10 - gap) * 40.5;
    }
    if gap > 0.10 && gap < 0.22 && next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr > 0.0 && pr < nxt {
            score += (gap - 0.10) * 90.5 * (0.5 + progress);
        }
    }
    if gap >= 0.22 && gap < 0.35 && progress > 0.55 {
        score += (gap - 0.22) * 45.5 * (progress - 0.55) * 2.0;
    }

    // Two-step lookahead: penalize dead space after placing next item.
    if next_item_size > 0 && gap > 0.12 {
        let nxt = next_item_size as f64;
        let nxt_gap = (gap * cap - nxt).max(0.0) / cap;
        if nxt_gap < 0.06 {
            score -= 9.0 * (1.0 - nxt_gap / 0.06) * (0.5 + progress);
        }
    }

    if fitting_bins_count > 2 {
        score += gap * 6.5 * ((fitting_bins_count.min(12) as f64 - 2.0) / 10.0);
    }

    // Deviation from mean residual.
    if pr > 0.0 {
        let dev = (mean_residual - pr) / cap;
        if dev > 0.05 {
            score += (dev - 0.05) * 12.0 * (0.4 + progress);
        } else if dev < -0.08 {
            score += (-dev - 0.08) * 6.0 * (1.0 - progress);
        }
    }

    // New-bin candidate handling (mutated: tighter gating by fitting count and item size).
    if bin_residual == bin_capacity {
        let size_pull = (item_size as f64 / cap) * 14.0;
        if fitting_bins_count <= 2 && gap > 0.0 {
            score -= (18.0 + size_pull) * (1.0 - progress * 0.6);
        } else if fitting_bins_count == 3 && gap > 0.0 && item_size as f64 >= cap * 0.5 {
            score -= 10.0 * (1.0 - progress * 0.5);
        } else {
            score += 8.0 + 6.0 * (1.0 - progress);
        }
        // Discourage new bins late when open bins can still absorb the stream.
        if open_bins_count > 6 && next_item_size > 0 {
            score += (open_bins_count.min(16) as f64 - 6.0) * 1.8;
        }
    }

    // Snug post-residual bonus for next item.
    if next_item_size > 0 && pr > 0.0 {
        let nxt = next_item_size as f64;
        let snug = (pr - nxt) / cap;
        if snug >= 0.0 && snug < 0.04 {
            score -= (0.04 - snug) * 22.0 * (0.6 + progress * 0.6);
        }
    }

    // Consolidation pressure with many open bins.
    if open_bins_count > 8 {
        score += post_norm * 5.0 * ((open_bins_count.min(20) as f64 - 8.0) / 12.0);
    }

    // Remaining-after-next analysis.
    if next_item_size > 0 && pr > next_item_size as f64 {
        let rem_norm = (pr - next_item_size as f64) / cap;
        if rem_norm > 0.0 && rem_norm < 0.03 {
            score -= (0.03 - rem_norm) * 10.0 * (0.4 + progress);
        } else if rem_norm > 0.16 {
            score += (rem_norm - 0.16) * 8.0 * (0.5 + progress);
        }
    }

    // Mid-range residual that next item cannot use.
    if pr > 0.0 && post_norm >= 0.10 && post_norm < 0.20 && next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt > pr {
            score += (nxt - pr) / cap * 26.0 * (0.4 + progress * 0.8);
        }
    }

    // Small leftover relative to item late in stream.
    if pr > 0.0 && pr < (item_size as f64) * 0.5 && progress > 0.3 {
        score += 4.0 * (1.0 - progress);
    }

    // Dead space after next placement.
    if next_item_size > 0 && pr > 0.0 {
        let nxt = next_item_size as f64;
        let dead = (pr - nxt).max(0.0) / cap;
        if dead > 0.0 && dead < 0.08 {
            let third = if dead * cap >= nxt { 1.0 } else { 0.0 };
            score += (0.08 - dead) * 16.0 * (1.0 - third * 0.5) * (0.5 + progress);
        }
    }

    // New bin that can host next item too.
    if bin_residual == bin_capacity && next_item_size > 0 && fitting_bins_count <= 3 {
        let nxt = next_item_size as f64;
        if item_size as f64 >= nxt * 0.95 {
            score -= 5.5 * (1.0 - progress * 0.5);
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits (retained from parent).
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    score
}

