pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are the worst outcome.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Medium dead space is also bad but less so.
    if post_residual >= 10 && post_residual < 20 {
        score += 25.0;
    }

    // Reward perfect and near-perfect fits strongly.
    if post_residual == 0 {
        score -= 80.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    }

    // Last chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: penalize creating more bins when many are open.
    if bin_residual == bin_capacity {
        // New-bin candidate: base penalty that grows with open bins count.
        score += 15.0 + 4.0 * open_bins_count as f64;
        // But if this bin cannot leave a useful gap elsewhere, opening is fine.
        // If next item would fit into the fresh bin nicely, soften slightly.
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 5.0;
        }
        // Early in the stream, opening bins is cheaper.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 10.0 * (1.0 - progress);
    } else {
        // Reusing an open bin reduces bin count pressure: mild reward.
        score -= 3.0;
    }

    // If the next item fits exactly into the resulting residual, reward heavily.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 50.0;
    } else if next_item_size > 0 && post_residual > next_item_size && post_residual - next_item_size < 10 {
        // Would create dead space for the following item.
        score += 15.0;
    }

    // Prefer bins below mean residual (tighter bins get filled first),
    // keeping loose bins available for awkward future items.
    if (bin_residual as f64) > mean_residual {
        score += 5.0;
    } else {
        score -= 5.0;
    }

    score
}

