            score += (rem_norm - 0.16) * 8.5 * (0.5 + progress);
        }
    }

    // Mid-range residual that next item cannot use.
    if pr > 0.0 && post_norm >= 0.10 && post_norm < 0.20 && next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt > pr {
            score += (nxt - pr) / cap * 27.0 * (0.4 + progress * 0.8);
        }
    }

    // Small leftover relative to item late in stream.
    if pr > 0.0 && pr < (item_size as f64) * 0.5 && progress > 0.3 {
        score += 4.5 * (1.0 - progress);
    }

    // Dead space after next placement.
    if next_item_size > 0 && pr > 0.0 {
        let nxt = next_item_size as f64;
        let dead = (pr - nxt).max(0.0) / cap;
        if dead > 0.0 && dead < 0.08 {
            let third = if dead * cap >= nxt { 1.0 } else { 0.0 };
            score += (0.08 - dead) * 17.0 * (1.0 - third * 0.5) * (0.5 + progress);
        }
    }

    // New bin that can host next item too.
    if bin_residual == bin_capacity && next_item_size > 0 && fitting_bins_count <= 3 {
        let nxt = next_item_size as f64;
        if item_size as f64 >= nxt * 0.95 {
            score -= 6.0 * (1.0 - progress * 0.5);
        }
    }

    // Last-chance bin: favor the only fitting open bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 28.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus: item exactly fills the bin.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Aggressive 2-step lookahead: reward if next item fits snugly into post_residual.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = post_residual - next_item_size;
        // Tight pair-fit is very desirable.
        score -= 30.0 - 0.3 * slack as f64;
    } else if next_item_size > 0 && next_item_size == post_residual {
        // Exact pair fit (covered by <= but keep explicit penalty-free case).
        score -= 30.0;
    } else if next_item_size > 0 {
        // Next item won't fit here: penalize dead space that may strand the bin.
        score += 5.0;
    }

    // Penalize post_residual that is too small to be useful for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // Compare against mean residual: prefer bins whose resulting residual
    // is closer to (or below) the average residual, keeping balance.
    let pr = post_residual as f64;
    let dev = (pr - mean_residual).abs();
    score += 0.2 * dev;

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Late in the stream, consolidate rather than open bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual < bin_capacity {
        score -= 10.0 * progress;
    }

    // Slight preference to use already-open bins vs the brand-new empty bin candidate.
    if bin_residual == bin_capacity {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
