    if pr > 0.0 {
        let dev = (mean_residual - pr) / cap;
        if dev > 0.05 {
            score += (dev - 0.05) * 12.5 * (0.4 + progress);
        } else if dev < -0.08 {
            score += (-dev - 0.08) * 6.0 * (1.0 - progress);
        }
    }

    // New-bin candidate handling (refined: open new bins only when nothing fits snugly).
    if bin_residual == bin_capacity {
        let size_pull = (item_size as f64 / cap) * 14.0;
        if fitting_bins_count <= 2 && gap > 0.0 {
            score -= (18.0 + size_pull) * (1.0 - progress * 0.6);
