    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits: reward small post_residual non-linearly.
    score -= 40.0 * (1.0 - (post_residual as f64 / bin_capacity as f64)).powi(4);

    // Penalize dead space that is too small to be useful later (below min item size 1..100 range, use 10 threshold).
    if post_residual < 10 {
        score += 60.0;
    } else if post_residual < 25 {
        score += 25.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0;
        } else if next_item_size <= post_residual {
            score -= 15.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item won't fit here; slight penalty for wasting residual it can't use
            score += 8.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 35.0;
    } else if fitting_bins_count > 1 {
        // among multiple candidates, prefer the fullest bin (smallest residual)
        score += 5.0 * (bin_residual as f64 / bin_capacity as f64).recip() * 0.5;
    }

    // Time horizon: early in the stream, be more willing to open new bins for large items;
    // late in the stream, pack tightly into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 12.0;

    // Global state coupling: if mean residual is high, prefer bins below mean (balance).
    if bin_residual as f64 > mean_residual {
        score += 6.0;
    } else {
        score -= 4.0;
    }

    // Many open bins: discourage opening new ones.
    if bin_residual == bin_capacity {
        score += 30.0 + 4.0 * open_bins_count as f64;
        // But allow new bin if current item is huge and would leave awkward residual elsewhere.
        if item_size > 70 && fitting_bins_count <= 2 {
            score -= 45.0;
        }
    }

    // Mild preference for filling larger bins first when item is large.
    score += 0.05 * item_size as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

