    // Reward using bins with small residual (good fit), smooth quadratic
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 10.0 * fit_ratio * fit_ratio;

    // Penalize dead space that no plausible item can use (smooth saturation)
    let dead = ((pr - next_item_size as f64).max(0.0)) / cap;
    score += 12.0 * dead * dead;

    // Last-chance bin bonus (avoid opening new bin unnecessarily)
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Mild penalty for many open bins relative to progress
    score += 0.5 * (open_bins_count as f64).sqrt() * (1.0 - progress);

    // Smooth mean-residual coupling: prefer bins below mean residual
    score += 0.3 * (mean_residual - pr);

    // New-bin candidate: make it slightly unattractive unless residual waste is huge
    if bin_residual == bin_capacity {
        score += 20.0 - 10.0 * progress;
    }

    // Lookahead: reward leaving room for the next item
    if next_item_size > 0 {
        let gap = pr - next_item_size as f64;
        if gap >= 0.0 {
            score -= 3.0 * (1.0 - gap / cap);
        } else {
            score += 2.0 * (-gap / cap);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let post_norm = pr / cap;
    let mut score = post_norm * post_norm * 58.0 + post_norm * 21.8;

    // Lookahead: gaussian reward when post_residual matches next item snugly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (pr - nxt) / cap;
        score -= (-diff * diff * 480.0).exp() * 20.8 * (1.0 - progress * 0.5);
