    if pr > 0.0 && post_norm < 0.02 {
        score -= (0.02 - post_norm) * 55.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover is a multiple of 10
    // are "reusable" classes; odd/prime-ish remainders are dead space.
    let class = post_residual % 10;
    if class == 0 {
        score -= 12.0;
    } else if class <= 3 {
        score += 6.0 + 2.0 * class as f64;
    } else if class >= 8 {
        score += 4.0;
    }

    // Integer division thresholds: leftover >= 25 is half-slot-ish, keep it.
    if post_residual >= 25 && post_residual <= 50 {
        score -= 8.0;
    }
    if post_residual < 10 {
        score += 15.0; // tiny dead space, penalize
    }

    // Lookahead harmonic match: next item fits exactly into post_residual class
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            let diff = post_residual - next_item_size;
            score -= 10.0 * (1.0 - diff as f64 / 50.0);
        } else {
            score += 3.0; // next item won't fit here anyway
        }
        // modulo pairing: next_item_size and post_residual share a divisor class
        if post_residual % next_item_size.max(1) == 0 {
            score -= 5.0;
        }
    }

    // Last-chance bin before opening a new bin: strong reward.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate: neutral-to-slightly-high baseline; only chosen when
    // open bins are truly bad. Make it depend on stream position.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 60.0 + 20.0 * progress;
        if next_item_size > 0 && next_item_size >= 70 {
            score -= 10.0; // big next item: fresh bin is fine
        }
        return score;
    }

    // Prefer fuller bins relative to mean residual (best-fit flavor).
    score -= (bin_residual as f64 - mean_residual) * 0.3;

    // Tight fit bonus near capacity fractions 3/4 and 9/10.
    let frac = bin_residual as f64 / bin_capacity as f64;
    if (frac - 0.75).abs() < 0.05 || (frac - 0.9).abs() < 0.05 {
        score -= 6.0;
    }

    // Many open bins: discourage fragmenting further.
    score += 0.15 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
