    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let post_norm = pr / cap;
    let mut score = post_norm * post_norm * 50.0 + post_norm * 20.0;

    // Dead-space penalty scaled by progress.
