    if pr > 0.0 && pr < item_size as f64 * 0.5 && progress > 0.3 {
        score += 4.0 * (1.0 - progress);
    }

    // Waste relative to mean residual: above-average leftovers penalized more.
    if pr > 0.0 && mean_residual > 0.0 {
        let waste = post_norm - mean_residual / cap;
        if waste > 0.0 {
            score += waste * 30.0 * (0.4 + progress * 0.6);
        } else {
            score -= (-waste) * 10.0;
        }
    }

    // Item+next pairability bonus: prefer bins where current+next both fit.
    if next > 0.0 && item_size as f64 + next <= cap && fit_ratio > 0.35 && bin_residual != bin_capacity {
        score -= 3.0 * (1.0 - progress);
    }

    score
}

