            score += waste * 30.0 * (0.4 + progress * 0.6);
        } else {
            score -= (-waste) * 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: which capacity fraction band it lands in.
    // Bands: (0], (0,10], (10,20], (20,30], (30,50], (50,100]
    let post = post_residual as f64;
    let band: f64 = if post_residual == 0 {
        0.0 // perfect fill: strongest reward
    } else if post_residual <= 10 {
        1.0
    } else if post_residual <= 20 {
        2.0
    } else if post_residual <= 30 {
        3.0
    } else if post_residual <= 50 {
        4.0
    } else {
        5.0
    };

    // Reward small residuals super-linearly (tight packing).
    score -= (6.0 - band) * (6.0 - band) * 4.0;

    // Modulo-class harmony: residual that is a "nice" divisor-multiple of common
    // item sizes (multiples of 10, 20, 25) is more likely reusable by future items.
    if post_residual > 0 {
        let m10 = post_residual % 10 == 0;
        let m20 = post_residual % 20 == 0;
        let m25 = post_residual % 25 == 0;
        if m10 { score -= 8.0; }
        if m20 { score -= 4.0; }
        if m25 { score -= 4.0; }
    }

    // Lookahead coupling: if the next item fits exactly or harmonically into the
    // post residual, reward heavily; if next item would be blocked, penalize.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if next_item_size <= post_residual {
            score -= 10.0;
            // harmonic exact fit for the lookahead
            if post_residual % next_item_size == 0 {
                score -= 6.0;
            }
            // next item leaves a small class-1 residual too
            let npost = post_residual - next_item_size;
            if npost <= 10 { score -= 6.0; }
        } else {
            // next item blocked by this placement: penalty scaled by how much
            // the residual "wasted" relative to next item's needs
            let gap = nxt - post;
            score += gap * 0.3;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless residual would be a huge dead space).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
        if post_residual > 50 {
            score += 12.0; // but not if it creates a mostly-empty bin
        }
    }

    // New-bin candidate handling: an empty bin has huge residual; make it
    // attractive only when placement here would leave a bad (large, non-harmonic)
    // residual and we have many open bins already.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // base cost of opening a new bin, softened late in the stream or when
        // open bins are congested
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let congestion = (open_bins_count as f64) / 8.0;
        score = cap * 0.9 - progress * 10.0 + congestion * 5.0;
        // if current best real bins would leave awful residuals, new bin wins
        if post == cap {
            let bad_fit_pressure = if mean_residual < 25.0 { 10.0 } else { 0.0 };
            score -= bad_fit_pressure;
        }
    } else {
        // Mild attraction toward bins whose residual is close to the item
        // (fractional slack minimization).
        let slack = (bin_residual - item_size) as f64;
        score += slack * 0.05;
        // prefer bins below mean residual (tighter bins) slightly
        score += (mean_residual - bin_residual as f64) * 0.1;
    }

    // Perfect fill dominance.
    if post_residual == 0 {
        score -= 100.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let post_norm = pr / cap;

    // Base: quadratic preference for tight post-residuals.
    let mut score = post_norm * post_norm * 52.0 + post_norm * 19.0;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 110.0;
    } else if post_residual <= 5 {
        score -= 42.0;
    } else if post_residual <= 9 {
        score -= 18.0 * (1.0 - progress * 0.4);
    }

    // Dead-space class: residuals in (0, 12] are nearly unusable.
    let dead_floor = if next_item_size > 0 { (next_item_size.min(12) as f64).max(6.0) } else { 12.0 };
    if post_residual > 0 && (post_residual as f64) < dead_floor {
        score += 62.0 * (1.0 - progress * 0.3);
    } else if post_residual < 20 {
        score += 25.0;
    }

    // Harmonic divisibility: reusable leftovers rewarded.
    if post_residual > 0 {
        let prr = post_residual;
        if prr % 50 == 0 { score -= 18.0; }
        else if prr % 25 == 0 { score -= 12.0; }
        else if prr % 20 == 0 { score -= 10.0; }
        else if prr % 10 == 0 { score -= 8.0; }
        else { score += (prr % 5) as f64 * 1.5; }
    }

    // Lookahead: next item fits exactly — big reward; near-exact fit via Gaussian.
    if next_item_size > 0 && post_residual >= next_item_size {
        if next_item_size == post_residual {
            score -= 60.0;
        } else {
            let slack = (post_residual - next_item_size) as f64 / cap;
            score -= (-slack * slack * 450.0).exp() * 24.0 * (1.0 - progress * 0.5);
            let nxt_left = post_residual - next_item_size;
            if nxt_left % 10 == 0 { score -= 10.0; }
            else if nxt_left > 12 { score -= 4.0; }
            else { score += 6.0; }
        }
    } else if next_item_size > 0 && post_residual > 0 && post_norm > 0.03 {
        // next item cannot use this leftover; penalize proportionally.
        let dead_ratio = (next_item_size as f64 - pr) / cap;
        score += dead_ratio * 90.0 * (0.6 + progress * 0.6);
        if fitting_bins_count <= 2 {
            score += 18.0 * (1.0 - progress * 0.5);
        }
    }

    // Two-item lookahead chaining: reward exact chain, penalize stranded tiny dead space.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual > 0 {
        let rem = post_residual - next_item_size;
        if rem == 0 {
            score -= 15.0 * (1.0 - progress * 0.4);
        } else if rem < 6 {
            score += 10.0;
        }
    }

    // Gap-based fit quality on bin_residual.
    let gap = (bin_residual - item_size) as f64 / cap;
    if gap > 0.0 && gap < 0.12 {
        score -= (0.12 - gap) * 48.0;
    } else if gap >= 0.12 && gap < 0.22 && fitting_bins_count <= 3 {
        score += (gap - 0.12) * 18.0 * (0.5 + progress * 0.5);
    } else if gap >= 0.22 && gap < 0.30 && fitting_bins_count <= 2 {
        score += (gap - 0.22) * 22.0 * (0.6 + progress * 0.4);
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let size_pull = (item_size as f64 / cap) * 14.0;
        if fitting_bins_count <= 2 {
            score = 55.0 - (18.0 + size_pull) * (1.0 - progress * 0.6);
        } else {
            score = 55.0 + 20.0 + open_bins_count as f64 * (0.5 + 0.5 * progress);
        }
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a bin
        }
        if next_item_size > 0 && fitting_bins_count <= 3 && (item_size as f64) >= next_item_size as f64 * 0.95 {
            score -= 5.5 * (1.0 - progress * 0.5);
        }
        if next_item_size > 0 && fitting_bins_count >= 1 && (item_size as f64) + next_item_size as f64 > cap {
            score += 8.0 * (1.0 - progress * 0.4);
        }
        if (item_size as f64) > cap * 0.5 && progress < 0.5 {
            score -= 6.0 * (1.0 - progress);
        }
        if progress > 0.85 && (item_size as f64) / cap > 0.6 {
            score -= 4.0 * (progress - 0.85) * 20.0;
        }
        if next_item_size > 0 && (item_size as f64) + (next_item_size as f64) <= cap && (item_size as f64) / cap > 0.35 {
            score -= 3.0 * (1.0 - progress);
        }
        // Pair-lookahead: item + next fills a fresh bin exactly.
        if next_item_size > 0 && (item_size + next_item_size) as f64 == cap {
            score -= 30.0 * (1.0 - progress * 0.5);
        }
        // Avoid opening a new bin for a small item when an open bin could host it.
        if (item_size as f64) / cap < 0.35 && fitting_bins_count >= 1 && progress > 0.2 {
            score += 14.0 * (1.0 - progress * 0.4);
        }
        // Pair-lookahead: item + next fits in a fresh bin with reusable remainder.
        if next_item_size > 0 && (item_size as f64) + (next_item_size as f64) <= cap {
            let rem = bin_capacity - item_size - next_item_size;
            if rem % 10 == 0 {
                score -= 12.0 * (1.0 - progress * 0.5);
            } else if rem < 6 {
                score += 8.0;
            }
        }
    }

    // Global pressure: compare post-residual against mean residual.
    if post_residual > 0 && mean_residual > 0.0 {
        let waste = post_norm - (mean_residual / cap);
        if waste > 0.0 {
            score += waste * 30.0 * (0.4 + progress * 0.6);
        } else {
            score -= (-waste) * 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: unusable gaps (too small for any item, min size 1
    // but practically < next_item_size) are the enemy. Penalize residual that cannot
    // accommodate the lookahead item.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // Dead space relative to the next item: waste grows with the gap.
            score += (next_item_size - post_residual) as f64 * 2.0;
        } else {
            // Reward residual that still fits the next item, scaled by tightness.
            let slack = (post_residual - next_item_size) as f64;
            score -= slack * 0.5;
        }
    }

    // Perfect or near-perfect fits get a strong bonus.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: when many bins are open, prefer filling existing ones
    // rather than opening yet another bin.
    score += open_bins_count as f64 * 1.5;

    // New-bin candidate (empty bin): make it attractive only when the current bin
    // would leave a bad fit; base penalty keeps open bins preferred by default.
    if bin_residual == bin_capacity {
        score += 40.0;
        // But if item fills a fresh bin perfectly, that's great.
        if item_size == bin_capacity {
            score -= 60.0;
        }
        // Late in the stream, opening fresh bins is cheaper (less time to accumulate waste).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= progress * 20.0;
    }

    // Coupling with mean residual: if open bins are on average quite full (low mean
    // residual), the stream is compressing well; slightly favor tight placements.
    score -= (mean_residual / bin_capacity as f64) * 5.0;

    // Mild reward for larger item consumption of the bin (tighter packing).
    score -= (item_size as f64 / bin_capacity as f64) * 10.0;

    score
}

