pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: eliminate all dead space.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Lookahead: does the next item fit into the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Great: next item can chain into this bin.
            let tightness = (next_item_size as f64) / (post_residual as f64);
            score -= 200.0 + 300.0 * tightness;
            // Exact chain fit is even better.
            if next_item_size == post_residual {
                score -= 500.0;
            }
        } else if post_residual > 0 {
            // Dead space the next item can't use: penalize proportionally,
            // but small residuals (<10) are naturally unusable, less bad.
            let waste = post_residual as f64;
            let small_dead = if waste < 10.0 { 0.3 } else { 1.0 };
            score += small_dead * (waste / bin_capacity as f64) * 400.0;
        }
    } else {
        // Last item: any residual is pure waste.
        score += (post_residual as f64) * 2.0;
    }

