    // prefer using bins with below-average residual (tight bins),
    // keep large-residual bins for future big items.
    score += (bin_residual as f64 - mean_residual) * 1.5;

    // Penalize opening a new empty bin unless it's genuinely needed
    // (empty-bin candidate has bin_residual == bin_capacity and post_residual large).
