        // New bin baseline: high unless item is large relative to capacity
        // or this is the only option.
        score += 300.0;
        if item_size >= 60 {
            score -= 150.0; // big items are fine to start a fresh bin
        }
        if open_bins_count == 0 {
            score -= 1000.0; // no alternative
        }
        // Late in the stream, prefer closing out existing bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 200.0 * progress;
    }

