        let tightness = 1.0 - (post - next_item_size as f64) / cap;
        score -= 25.0 + 15.0 * tightness;
    } else if next_item_size > 0 {
        // next item won't fit here: penalize dead space proportionally
        let waste = (post - (post % next_item_size.max(1) as f64)) / cap;
        score += 8.0 * waste;
    }

    // Last-chance bin: strongly favor using it over opening a new bin
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Prefer bins tighter than the mean residual (best-fit flavor)
    score += 0.5 * (post - mean_residual);

    // Modulo-arithmetic harmony: post_residual divisible by common small sizes
    if post_residual > 0 {
