        score += 4.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward an exact 2-step match: post_residual equals next item size.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual > next_item_size {
            // Slack after a hypothetical second placement is wasted space.
            let slack = (post_residual - next_item_size) as f64;
            score += 0.5 * slack;
        } else {
            // Next item cannot follow into this bin: dead-space penalty.
            score += 0.25 * (next_item_size - post_residual) as f64;
        }
    }

    // Reward tight fits relative to mean residual across open bins.
    score -= (bin_residual as f64 - mean_residual) * 0.3;

    // Last-chance bin: using it avoids opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Penalize leaving very small unusable fragments (< 10).
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // Perfect closure bonus.
    if post_residual == 0 {
        score -= 10.0;
    }

    // Early in the stream, be more willing to open new bins for good structure.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 5.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Reward tight fits: discount proportional to fill ratio.
    let fill = 1.0 - post / cap;
    score -= 2.5 * fill * fill * cap;

    // Penalize small dead space that is hard to reuse (post_residual < 10).
    if post_residual < 10 {
        score -= 15.0; // actually desirable: near-perfect fit bonus
    } else if post_residual < 25 {
        score += 8.0; // awkward dead zone
    }

    // Lookahead coupling: if next item fits into the post residual, reward.
    if next_item_size > 0 && (post_residual as u64) >= (next_item_size as u64) {
        score -= 12.0 + 0.15 * next_item_size as f64;
    } else if next_item_size > 0 && (post_residual as u64) < (next_item_size as u64) {
        score += 0.10 * (next_item_size as f64 - post);
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless the current item
    // leaves a useful residual or many bins are already open (load balancing).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let waste = item_size as f64 / cap;
        score += 20.0 - 10.0 * waste;
        // As stream progresses / bins accumulate, opening fresh bins is cheaper.
        score -= 8.0 * progress + 0.5 * (open_bins_count as f64).ln().max(0.0);
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // pair large items in fresh bins
        }
    }

    // Mild bonus for bins with residual above mean (keep balanced bins usable).
    if (bin_residual as f64) > mean_residual {
        score += 2.0;
    }

    score
}

