pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let pr = post_residual as f64;
    let p2 = progress * progress;
    let p3 = p2 * progress;
    // Early in the stream, tolerate larger residuals; later, punish them quadratically/cubically.
    score += pr * pr * (0.004 + 0.012 * p2) + pr * pr * pr * (0.00002 * p3);

    // Reward tight fits, more strongly as the stream progresses (smooth cubic ramp).
    let tightness = 1.0 - pr / bin_capacity as f64;
    score -= 25.0 * tightness * (1.0 + 2.0 * p2 + 3.0 * p3);

    // Last-chance bin bonus: strongly favor the only bin that fits, ramping with progress.
    if fitting_bins_count == 1 {
        score -= 40.0 + 60.0 * progress;
    }

    // Discourage opening new bins when many bins are already open and mean residual is large.
    let new_bin = (bin_residual == bin_capacity) as f64;
    let mean_norm = mean_residual / bin_capacity as f64;
    score += new_bin * (30.0 + 25.0 * mean_norm * (1.0 + progress)) / (1.0 + open_bins_count as f64).sqrt();

    // Lookahead: favor bins whose post-residual can host the next item (smooth reward).
    if next_item_size > 0 {
        let fits_next = (post_residual >= next_item_size) as f64;
        let slack = (post_residual as f64 - next_item_size as f64).abs();
        score += fits_next * (0.5 * slack - 20.0 * (1.0 - slack / bin_capacity as f64).abs());
    }

    // Mild penalty for bins far from the mean residual (outlier bins), smoothed by progress.
    score += 3.0 * ((post_residual as f64 - mean_residual) / bin_capacity as f64).abs() * (0.5 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let next = next_item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items.max(1) as f64 } else { 0.0 };
    let post_norm = pr / cap;
    let fit_ratio = item_size as f64 / cap;
    let gap = (bin_residual - item_size) as f64 / cap;
    let mut score = post_norm * post_norm * 52.0 + post_norm * 20.0;

    // ---- Aggressive 2-step lookahead: shape score around the NEXT item ----
    if next > 0.0 {
        if pr == next {
            score -= 50.0;
        } else if pr > next {
            let slack = pr - next;
            let diff = slack / cap;
            score -= 22.0 * (1.0 - diff).max(0.0);
            score -= (-diff * diff * 450.0).exp() * 22.0 * (1.0 - progress * 0.5);
            if diff < 0.04 {
                score -= (0.04 - diff) * 28.0 * (0.6 + progress * 0.6);
            } else if diff > 0.16 {
                score += (diff - 0.16) * 9.0 * (0.5 + progress);
            }
            // NEW: two-next anticipation — if the remainder after `next` can
            // still hold a mid-size item, this bin is extra valuable.
            if diff > 0.25 && next > 0.0 {
                let after = pr - next;
                if after >= next * 0.6 {
                    score -= 6.0 * (1.0 - progress * 0.4);
                }
            }
        } else if pr > 0.0 {
            let dead_ratio = (next - pr) / cap;
            score += dead_ratio * 85.0 * (0.6 + progress * 0.6);
            if fitting_bins_count <= 2 {
                score += 16.0 * (1.0 - progress * 0.5);
            }
        }
    }

    // Dead-floor guard: tiny unusable slivers are stranded capacity.
    if post_residual > 0 {
        let dead_floor = if next_item_size > 0 { (next_item_size.min(12) as f64).max(6.0) } else { 10.0 };
        if pr < dead_floor && pr != next {
            score += 55.0 * (1.0 - progress * 0.3);
        } else if post_residual < 20 && pr != next {
            score += 22.0;
        }
    }

    // ---- Relative-to-mean coupling: favor tighter-than-average bins ----
    if pr > 0.0 && mean_residual > 0.0 {
        let waste = post_norm - mean_residual / cap;
        if waste > 0.0 {
            score += waste * 30.0 * (0.4 + progress * 0.6);
        } else {
            score -= (-waste) * 10.0;
        }
    }

    // ---- New-bin candidate decision (bin_residual == bin_capacity) ----
    if bin_residual == bin_capacity {
        let others = if fitting_bins_count > 0 { fitting_bins_count - 1 } else { 0 };
        let size_pull = fit_ratio * 14.0;
        if fitting_bins_count <= 2 && gap > 0.0 {
            score -= (18.0 + size_pull) * (1.0 - progress * 0.6);
        } else if others == 0 {
            score -= 5.0;
        } else {
            score += 20.0 + open_bins_count as f64 * (0.5 + 0.5 * progress);
        }
        if next > 0.0 && fitting_bins_count <= 3 && item_size as f64 >= next * 0.95 {
            score -= 5.5 * (1.0 - progress * 0.5);
        }
        if next > 0.0 && item_size as f64 + next > cap {
            score += 8.0 * (1.0 - progress * 0.4);
        }
        if fit_ratio > 0.5 && progress < 0.5 {
            score -= 6.0 * (1.0 - progress);
        }
        if next > 0.0 && item_size as f64 + next <= cap && fit_ratio > 0.35 {
            score -= 3.0 * (1.0 - progress);
        }
        // NEW: late-stream — opening a new bin for a big item is fine, but
        // avoid it for small items when open bins are plentiful.
        if progress > 0.6 && fit_ratio < 0.3 && open_bins_count > 4 {
            score += 10.0 * (progress - 0.6) / 0.4;
        }
    }

    // Exact / near-exact fit bonuses.
    if pr == 0.0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 42.0;
    } else if post_residual <= 9 {
        score -= 18.0 * (1.0 - progress * 0.4);
    } else if post_norm < 0.05 {
        score -= 10.2 * (1.0 - post_norm / 0.05);
    }

    // Sharp bonus for leaving a tiny gap (<12% of capacity).
    if gap > 0.0 && gap < 0.12 {
        score -= (0.12 - gap) * 48.0;
    } else if gap >= 0.12 && gap < 0.22 {
        if next > 0.0 && pr > 0.0 && pr < next {
            score += (gap - 0.10) * 90.5 * (0.5 + progress);
        } else if fitting_bins_count <= 3 {
            score += (gap - 0.12) * 18.0 * (0.5 + progress * 0.5);
        }
    }
    if gap >= 0.22 && gap < 0.30 && fitting_bins_count <= 2 {
        score += (gap - 0.22) * 22.0 * (0.6 + progress * 0.4);
    }
    // Next-item chain: leftover after placing next item nearly closes bin.
    if next > 0.0 && gap > 0.12 {
        let nxt_gap = ((gap * cap - next).max(0.0)) / cap;
        if nxt_gap < 0.06 {
            score -= 10.0 * (1.0 - nxt_gap / 0.06) * (0.5 + progress);
        }
    }

    // Reward large items filling bins deeply.
    score -= fit_ratio * fit_ratio * 6.0;

    // Congestion: when many bins compete for this item, penalize sloppy fits.
    if fitting_bins_count > 2 {
        score += gap * 6.5 * ((fitting_bins_count.min(12) as f64 - 2.0) / 10.0);
    }
    if open_bins_count > 8 {
        score += post_norm * 5.0 * ((open_bins_count.min(20) as f64 - 8.0) / 12.0);
    }

    // Late-stream consolidation: penalize moderately large residuals late.
    if progress > 0.7 && post_norm > 0.25 {
        score += (post_norm - 0.25) * 6.0 * (progress - 0.7) / 0.3;
    }

    // Last-chance bonus: prefer a bin that would otherwise be wasted.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 - fit_ratio);
    }

    // Deep fill bonus relative to actual residual.
    let fill_r = item_size as f64 / bin_residual.max(1) as f64;
    if fill_r > 0.90 && bin_residual != bin_capacity {
        score -= (fill_r - 0.90) * 18.0 * (0.6 + progress * 0.5);
    }

    // Dead-space guard: stranded small gap after next item.
    if next > 0.0 && pr > 0.0 {
        let after_next = (pr - next).max(0.0);
        let dead = after_next / cap;
        if dead > 0.0 && dead < 0.08 {
            let reusable = if after_next >= next { 1.0 } else { 0.0 };
            score += (0.08 - dead) * 16.0 * (1.0 - reusable * 0.5) * (0.5 + progress);
        }
    }

    // Half-consumed bins late in the stream.
    if pr > 0.0 && pr < item_size as f64 * 0.5 && progress > 0.3 {
        score += 4.0 * (1.0 - progress);
    }

    // NEW: residual-variance coupling — when residual spread is high, prefer
    // bins whose post-residual stays close to the mean (keeps future fits alive).
    if pr > 0.0 && mean_residual > 0.0 {
        let dev = (post_norm - mean_residual / cap).abs();
        if dev > 0.15 && fitting_bins_count > 3 {
            score += dev * 8.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "clean"
    // capacity fractions are more reusable, so reward them (subtract).
    let frac = post_residual as f64 / bin_capacity as f64;
    let harmonic = (bin_capacity / (post_residual.max(1))) as f64; // integer-division harmonic weight
    score -= 8.0 * harmonic * frac;

    // Modulo classes: post_residual divisible by common item sizes (10/20/25/50)
    // is "harmonic" -> likely perfectly fillable later.
    if post_residual > 0 {
        if post_residual % 50 == 0 { score -= 12.0; }
        else if post_residual % 25 == 0 { score -= 9.0; }
        else if post_residual % 20 == 0 { score -= 7.0; }
        else if post_residual % 10 == 0 { score -= 5.0; }
    }

    // Dead-space penalty: small, non-harmonic leftovers are wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.3;
        } else {
            // next item cannot use this residual: penalize proportionally
            score += (next_item_size - post_residual) as f64 * 0.1;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate: empty bin gets a mild handicap so we prefer reusing
    // decently fitting open bins, but handicap shrinks as stream progresses.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 15.0 * (1.0 - 0.5 * progress);
    }

    // Prefer bins far from the mean residual (better consolidation).
    score -= (post_residual as f64 - mean_residual).abs() * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny leftovers are nearly useless.
    if post_residual > 0 {
        if post_residual <= 10 {
            score += 60.0 - 3.0 * post_residual as f64; // worst dead space
        } else if post_residual < 20 {
            score += 15.0;
        } else {
            score -= 5.0; // large usable residual is fine
        }
    } else {
        // Perfect fit: strong reward.
        score -= 50.0;
    }

    // Reward bins that can also host the lookahead item after placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // Penalize if this placement blocks the next item while other bins could host it.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Pressure from number of open bins: discourage opening new bins when many are open.
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline cost plus open-bin pressure.
        score = 45.0 + 4.0 * open_bins_count as f64;
        // If nothing else fits well, opening a bin is acceptable.
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
        // Late in the stream, prefer consolidating into existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Mild preference for bins with below-average residual (tighter bins fill first).
    if bin_residual < bin_capacity {
        score += 0.05 * (mean_residual - bin_residual as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: item + next item exactly fills the bin.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Next item can also fit into the remaining space: good chaining.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + (post_residual - next_item_size) as f64 * 0.3;
    }

    // Penalize dead space that neither fits the next item nor is tiny.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // Relative to mean residual: prefer bins with less residual than average (tighter packs).
    score += (post_residual as f64 - mean_residual) * 0.4;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Early in the stream, be more willing to open new bins for good fits;
    // later, prefer filling existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize unless post_residual is very small (near-perfect fit).
        score += 20.0 - (100.0 - post_residual.min(100)) as f64 * 0.15 - progress * 10.0;
        if post_residual as f64 <= mean_residual * 0.5 {
            score -= 15.0;
        }
    }

    // Slight bonus for large item fill ratio (tight fit).
    score -= (item_size as f64 / bin_capacity as f64) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core fit quality: reward tight fits (small post_residual relative to capacity).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * tightness * 30.0;

    // Penalize placing small items into bins with large residuals (waste of good space).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 15.0;

    // Lookahead: if the next item also fits in the post residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let combo_waste = (post_residual - next_item_size) as f64;
        score -= 12.0 - combo_waste * 0.08;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here after placement: slight penalty for blocking chains.
        score += 3.0;
    }

    // Last-chance bin: strongly favor using the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: prefer opening a new bin only when the current
    // fit is poor (large post_residual) or when many bins are already open.
    if bin_residual == bin_capacity {
        // Baseline cost of a fresh bin: full capacity minus item.
        score = (bin_capacity - item_size) as f64;
        // If this is a decent fit (item nearly fills a fresh bin), opening is fine.
        score -= (item_size as f64 / bin_capacity as f64) * 20.0;
        // Late in the stream, avoid proliferating bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 10.0;
        // If a last-chance bin exists, discourage opening a new one.
        if fitting_bins_count >= 1 {
            score += 25.0;
        }
    }

    // Global state coupling: many open bins with high mean residual -> consolidate.
    if bin_residual != bin_capacity {
        let consolidation = (mean_residual - post_residual as f64) / bin_capacity as f64;
        score -= consolidation * 8.0;
        // Mild pressure to close bins when too many are open.
        if open_bins_count > 8 {
            score += (open_bins_count as f64 - 8.0) * 0.5;
        }
    }

    // Early stream: be slightly conservative, keep bins flexible for big items.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if progress < 0.25 && post_residual > 0 && post_residual < 10 {
        score -= 5.0; // reward creating near-full bins early
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let post_norm = pr / cap;
    let mut score = post_norm * post_norm * 50.0 + post_norm * 20.0;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 42.0;
    } else if post_residual <= 9 {
        score -= 18.0 * (1.0 - progress * 0.4);
    }

    // Dead-space class: residuals below the next item's likely floor are unusable.
    let dead_floor = if next_item_size > 0 { (next_item_size.min(12) as f64).max(6.0) } else { 10.0 };
    if post_residual > 0 && (post_residual as f64) < dead_floor {
        score += 62.0 * (1.0 - progress * 0.3);
    } else if post_residual < 20 {
        score += 25.0;
    }

    // Harmonic divisibility rewards.
    if post_residual > 0 {
        let p = post_residual;
        if p % 50 == 0 { score -= 18.0; }
        else if p % 25 == 0 { score -= 12.0; }
        else if p % 20 == 0 { score -= 10.0; }
        else if p % 10 == 0 { score -= 8.0; }
        else {
            score += (p % 5) as f64 * 1.5;
        }
    }

    // Lookahead: next item pairs tightly into post_residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64 / cap;
        score -= (-slack * slack * 450.0).exp() * 24.0 * (1.0 - progress * 0.5);
        let nxt_left = post_residual - next_item_size;
        if nxt_left % 10 == 0 { score -= 10.0; }
        else if nxt_left > 12 { score -= 4.0; }
        else { score += 6.0; }
    }

    // Next item cannot use this leftover: dead-space penalty.
    if next_item_size > 0 && pr > 0.0 && (post_residual as u32) < next_item_size && post_norm > 0.03 {
        let dead_ratio = (next_item_size as f64 - pr) / cap;
        score += dead_ratio * 90.0 * (0.6 + progress * 0.6);
    }
    if next_item_size > 0 && post_residual > 0 && (post_residual as u32) < next_item_size && fitting_bins_count <= 2 {
        score += 18.0 * (1.0 - progress * 0.5);
    }

    // Tight-gap bonus.
    let gap = (bin_residual - item_size) as f64 / cap;
    if gap > 0.0 && gap < 0.12 {
        score -= (0.12 - gap) * 48.0;
    } else if gap >= 0.12 && gap < 0.22 {
        if fitting_bins_count <= 3 {
            score += (gap - 0.12) * 18.0 * (0.5 + progress * 0.5);
        }
    }
    if gap >= 0.22 && gap < 0.30 && fitting_bins_count <= 2 {
        score += (gap - 0.22) * 22.0 * (0.6 + progress * 0.4);
    }

    // Last-chance bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let size_pull = (item_size as f64 / cap) * 14.0;
        if fitting_bins_count <= 2 {
            score -= (18.0 + size_pull) * (1.0 - progress * 0.6);
        } else {
            score += 20.0 + open_bins_count as f64 * (0.5 + 0.5 * progress);
        }
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        if next_item_size > 0 && fitting_bins_count <= 3 && (item_size as f64) >= next_item_size as f64 * 0.95 {
            score -= 5.5 * (1.0 - progress * 0.5);
        }
        if next_item_size > 0 && fitting_bins_count >= 1 {
            let nxt = next_item_size as f64;
            if (item_size as f64) + nxt > cap {
                score += 8.0 * (1.0 - progress * 0.4);
            }
        }
        if (item_size as f64) > cap * 0.5 && progress < 0.5 {
            score -= 6.0 * (1.0 - progress);
        }
        if progress > 0.85 && (item_size as f64) / cap > 0.6 {
            score -= 4.0 * (progress - 0.85) * 20.0;
        }
        if next_item_size > 0 && (item_size as f64) + (next_item_size as f64) <= cap && (item_size as f64) / cap > 0.35 {
            score -= 3.0 * (1.0 - progress);
        }
    }

    // Global pressure: high mean residual -> pack tight bins.
    score -= (mean_residual / cap) * 5.0;

    // Waste-relative pressure.
    if post_residual > 0 && mean_residual > 0.0 {
        let waste = (post_residual as f64 / cap) - (mean_residual / cap);
        if waste > 0.0 {
            score += waste * 30.0 * (0.4 + progress * 0.6);
        } else {
            score -= (-waste) * 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early on (progress ~ 0): weight tight fits moderately; later (progress ~ 1):
    // strongly reward small post_residual (tight packing) and penalize large residuals.
    let poly = norm_pr * (1.0 + progress * (norm_pr * 3.0 + 1.0));
    let mut score = poly * (1.0 + 2.0 * progress * progress);

    // Reward bins that will also accommodate the lookahead item smoothly.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 0.35 * (1.0 - progress) * (next_item_size as f64 / cap);
    }

    // Penalize wasteful near-empty residual creation when many bins are open.
    score += 0.1 * (open_bins_count as f64).ln().max(0.0) * norm_pr * norm_pr;

    // Last-chance bin: strong bonus to use it rather than open a new bin.
    if fitting_bins_count == 1 {
        score -= 1.5;
    }

    // New-bin candidate: keep it slightly unattractive unless residuals are large.
    if bin_residual == bin_capacity {
        score += 0.5 + 0.5 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let next = next_item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items.max(1) as f64 } else { 0.0 };
