    let pr = post_residual as f64;
    let post_norm = pr / cap;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_ratio = item_size as f64 / cap;
    let is_new_bin = bin_residual == bin_capacity;
    let nxt = if next_item_size > 0 { next_item_size as f64 } else { 0.0 };

    // Core: strongly minimize post_residual (normalized quadratic + linear).
    let mut score = post_norm * post_norm * 50.0 + post_norm * 20.0;

    // Exact / near-exact fill bonuses.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 42.0;
    } else if post_residual <= 9 {
        score -= 18.0 * (1.0 - progress * 0.4);
    }

    // Penalize tiny unusable residuals (dead space floor).
    let dead_floor = if nxt > 0.0 { nxt.min(12.0).max(6.0) } else { 10.0 };
    if post_residual > 0 && pr < dead_floor {
        score += 62.0 * (1.0 - progress * 0.3);
    } else if post_residual < 20 {
        score += 25.0;
    }

    // Reward bins whose leftover still accommodates the next item with tight slack.
    if nxt > 0.0 && post_residual >= next_item_size {
        let slack = (pr - nxt) / cap;
        score -= (-slack * slack * 450.0).exp() * 24.0 * (1.0 - progress * 0.5);
        if slack >= 0.0 && slack < 0.05 {
            score -= (0.05 - slack) * 40.0 * (0.5 + progress * 0.5);
        }
    } else if nxt > 0.0 && post_residual > 0 && post_norm > 0.03 {
        // Dead space that cannot fit the next item.
        let dead_ratio = (nxt - pr) / cap;
        score += dead_ratio * 90.0 * (0.6 + progress * 0.6);
        if fitting_bins_count <= 2 {
            score += 18.0 * (1.0 - progress * 0.5);
        }
    }

    // Gap-based coupling: prefer near-tight fits, tolerate moderate gaps
    // only when options are scarce.
    let gap = (bin_residual - item_size) as f64 / cap;
    if gap > 0.0 && gap < 0.12 {
        score -= (0.12 - gap) * 48.0;
    } else if gap >= 0.12 && gap < 0.22 && fitting_bins_count <= 3 {
        score += (gap - 0.12) * 18.0 * (0.5 + progress * 0.5);
    } else if gap >= 0.22 && gap < 0.30 && fitting_bins_count <= 2 {
        score += (gap - 0.22) * 22.0 * (0.6 + progress * 0.4);
    }

    // Relative waste vs. mean residual.
    if post_residual > 0 && mean_residual > 0.0 {
        let waste = post_norm - mean_residual / cap;
        if waste > 0.0 {
            score += waste * 30.0 * (0.4 + progress * 0.6);
        } else {
            score -= (-waste) * 10.0;
        }
    }

    // NEW-BIN decision: open a fresh bin only for large items or when open
    // bins would be badly fragmented; otherwise penalize opening.
    if is_new_bin {
        let size_pull = fit_ratio * 14.0;
        if fitting_bins_count <= 2 {
            score -= (18.0 + size_pull) * (1.0 - progress * 0.6);
        } else {
            score += 20.0 + open_bins_count as f64 * (0.5 + 0.5 * progress);
        }
        if nxt > 0.0 && fitting_bins_count <= 3 && fit_ratio >= (nxt / cap) * 0.95 {
            score -= 5.5 * (1.0 - progress * 0.5);
        }
        if nxt > 0.0 && fit_ratio * cap + nxt > cap {
            score += 8.0 * (1.0 - progress * 0.4);
        }
        if fit_ratio > 0.5 && progress < 0.5 {
            score -= 6.0 * (1.0 - progress);
        }
        if progress > 0.85 && fit_ratio > 0.6 {
            score -= (progress - 0.85) * 80.0;
        }
        if nxt > 0.0 && fit_ratio * cap + nxt <= cap && fit_ratio > 0.35 {
            score -= 3.0 * (1.0 - progress);
        }
    }

    // Last-chance bonus: prefer a bin that would otherwise be wasted.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 25.0 * (1.0 - fit_ratio);
    }

    // Reward high fill fraction smoothly.
    score -= fit_ratio * fit_ratio * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let next = next_item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items.max(1) as f64 } else { 0.0 };
    let post_norm = pr / cap;
    let fit_ratio = item_size as f64 / cap;
    let gap = (bin_residual - item_size) as f64 / cap;
    let mut score = post_norm * post_norm * 54.0 + post_norm * 21.0;

    // ---- Aggressive 2-step lookahead: shape score around the NEXT item ----
    if next > 0.0 {
        if pr == next {
            score -= 58.0;
        } else if pr > next {
            let slack = pr - next;
            let diff = slack / cap;
            score -= 24.0 * (1.0 - diff).max(0.0);
            score -= (-diff * diff * 450.0).exp() * 26.0 * (1.0 - progress * 0.5);
            // Snug remainder after next item lands.
            if diff < 0.04 {
                score -= (0.04 - diff) * 32.0 * (0.6 + progress * 0.6);
            } else if diff > 0.16 {
                score += (diff - 0.16) * 9.5 * (0.5 + progress);
            }
        } else if pr > 0.0 {
            let dead_ratio = (next - pr) / cap;
            score += dead_ratio * 92.0 * (0.6 + progress * 0.6);
            if fitting_bins_count <= 2 {
                score += 19.0 * (1.0 - progress * 0.5);
            }
        }
    }

    // Dead-floor guard: tiny unusable slivers are stranded capacity.
    if post_residual > 0 {
        let dead_floor = if next_item_size > 0 { (next_item_size.min(12) as f64).max(6.0) } else { 10.0 };
        if pr < dead_floor && pr != next {
            score += 64.0 * (1.0 - progress * 0.3);
        } else if post_residual < 20 && pr != next {
            score += 26.0;
        }
    }

    // ---- Relative-to-mean coupling: favor tighter-than-average bins ----
    if pr > 0.0 && mean_residual > 0.0 {
        let waste = post_norm - mean_residual / cap;
        if waste > 0.0 {
            score += waste * 32.0 * (0.4 + progress * 0.6);
        } else {
            score -= (-waste) * 11.0;
        }
    }

    // ---- New-bin candidate decision (bin_residual == bin_capacity) ----
    if bin_residual == bin_capacity {
        let others = if fitting_bins_count > 0 { fitting_bins_count - 1 } else { 0 };
        let size_pull = fit_ratio * 14.0;
        if fitting_bins_count <= 2 && gap > 0.0 {
            score -= (18.0 + size_pull) * (1.0 - progress * 0.6);
        } else if others == 0 {
            score -= 5.0;
        } else {
            score += 20.0 + open_bins_count as f64 * (0.5 + 0.5 * progress);
        }
        if next > 0.0 && fitting_bins_count <= 3 && item_size as f64 >= next * 0.95 {
            score -= 5.5 * (1.0 - progress * 0.5);
        }
        if next > 0.0 && item_size as f64 + next > cap {
            score += 8.0 * (1.0 - progress * 0.4);
        }
        if fit_ratio > 0.5 && progress < 0.5 {
            score -= 6.0 * (1.0 - progress);
        }
        if next > 0.0 && item_size as f64 + next <= cap && fit_ratio > 0.35 {
            score -= 3.5 * (1.0 - progress);
        }
        if progress > 0.85 && fit_ratio > 0.6 {
            score -= 4.0 * (progress - 0.85) * 20.0;
        }
        if next > 0.0 && pr > 0.0 {
            let second_slack = (pr - next) / cap;
            if second_slack >= 0.0 && second_slack < 0.05 {
                score -= (0.05 - second_slack) * 42.0 * (0.5 + progress * 0.5);
            }
        }
        if post_norm < 0.02 && fitting_bins_count >= 4 {
            score -= 6.0 * (1.0 - progress);
        }
        // Homogeneous-stream guard: opening a fresh bin for a small item when
        // the next item could pair with it in an existing bin wastes capacity.
        if next > 0.0 && fit_ratio < 0.25 && item_size as f64 + next <= cap && fitting_bins_count >= 3 {
            score += 4.0 * (1.0 - progress * 0.5);
        }
    }

    // Exact / near-exact fit bonuses.
    if pr == 0.0 {
        score -= 102.0;
    } else if post_residual <= 5 {
        score -= 44.0;
    } else if post_residual <= 9 {
        score -= 19.0 * (1.0 - progress * 0.4);
    } else if post_norm < 0.05 {
        score -= 10.5 * (1.0 - post_norm / 0.05);
    }

    // Sharp bonus for leaving a tiny gap (<12% of capacity).
    if gap > 0.0 && gap < 0.12 {
        score -= (0.12 - gap) * 50.0;
    } else if gap >= 0.12 && gap < 0.22 {
        if next > 0.0 && pr > 0.0 && pr < next {
            score += (gap - 0.10) * 92.0 * (0.5 + progress);
        } else if fitting_bins_count <= 3 {
            score += (gap - 0.12) * 18.0 * (0.5 + progress * 0.5);
        }
    }
    if gap >= 0.22 && gap < 0.30 && fitting_bins_count <= 2 {
        score += (gap - 0.22) * 22.0 * (0.6 + progress * 0.4);
    }
    // Next-item chain: leftover after placing next item nearly closes bin.
    if next > 0.0 && gap > 0.12 {
        let nxt_gap = ((gap * cap - next).max(0.0)) / cap;
        if nxt_gap < 0.06 {
            score -= 11.0 * (1.0 - nxt_gap / 0.06) * (0.5 + progress);
        }
    }

    // Reward large items filling bins deeply.
    score -= fit_ratio * fit_ratio * 6.5;

    // Congestion: when many bins compete for this item, penalize sloppy fits.
    if fitting_bins_count > 2 {
        score += gap * 6.5 * ((fitting_bins_count.min(12) as f64 - 2.0) / 10.0);
    }
    if open_bins_count > 8 {
        score += post_norm * 5.5 * ((open_bins_count.min(20) as f64 - 8.0) / 12.0);
    }

    // Late-stream consolidation: penalize moderately large residuals late.
    if progress > 0.7 && post_norm > 0.25 {
        score += (post_norm - 0.25) * 6.5 * (progress - 0.7) / 0.3;
    }

    // Last-chance bonus: prefer a bin that would otherwise be wasted.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 26.0 * (1.0 - fit_ratio);
    }

    // Deep fill bonus relative to actual residual.
    let fill_r = item_size as f64 / bin_residual.max(1) as f64;
    if fill_r > 0.90 && bin_residual != bin_capacity {
        score -= (fill_r - 0.90) * 19.0 * (0.6 + progress * 0.5);
    }

    // Dead-space guard: stranded small gap after next item.
    if next > 0.0 && pr > 0.0 {
        let after_next = (pr - next).max(0.0);
        let dead = after_next / cap;
        if dead > 0.0 && dead < 0.08 {
            let reusable = if after_next >= next { 1.0 } else { 0.0 };
            score += (0.08 - dead) * 17.0 * (1.0 - reusable * 0.5) * (0.5 + progress);
        }
    }

    // Half-consumed bins late in the stream.
    if pr > 0.0 && pr < item_size as f64 * 0.5 && progress > 0.3 {
        score += 4.0 * (1.0 - progress);
    }

    // Mid-range residual tightening with progress-aware scaling.
    if post_residual > 0 && post_norm >= 0.05 && post_norm < 0.15 {
        score += post_norm * 13.0 * (1.0 - progress * 0.4);
    }

    // Two-item pair completion: bin closes exactly after this and the next item.
    if next > 0.0 && post_residual == 0 && (item_size as f64 + next) <= cap {
        score -= 6.0 * (1.0 - progress * 0.5);
    }

    score
}

