pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Harmonic classes: classify post_residual into residue classes mod 10 and mod 25
    let r10 = post_residual % 10;
    let r25 = post_residual % 25;
    // Dead-space penalty: residuals that cannot host typical items (1..100 unknown,
    // but small residues are worst). Penalize low post_residual only mildly (near-full is fine),
    // penalize mid-range awkward residues strongly.
    let frac = post / cap;
    if frac > 0.0 && frac < 0.10 {
        score -= 30.0 * (0.10 - frac) * 10.0; // tight fit is good
    }
    // awkward mid residuals: 10..40 are hard to fill
    if post_residual >= 10 && post_residual <= 40 {
        score += (40 - post_residual) as f64 * 0.8;
    }
    // modulo harmony: residuals divisible by 10 or 25 are more reusable
    if r10 == 0 { score -= 6.0; }
    if r25 == 0 { score -= 6.0; }
    if r10 == 0 && r25 == 0 { score -= 4.0; }
    // ugly residues (prime-ish remainders) get slight penalty
    score += (r10 as f64) * 0.15 + (r25 as f64) * 0.1;

    // Lookahead coupling: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size < post_residual {
            let next_post = post_residual - next_item_size;
            // reward if chain leaves a nice residual
            if next_post % 10 == 0 { score -= 8.0; }
            score -= 5.0 * (1.0 - (next_post as f64) / cap);
        } else {
            // next item won't fit here: slight penalty proportional to wasted potential
            score += 3.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin is wasteful early / when open bins few
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut penalty = 40.0 + 20.0 * (1.0 - progress);
        if open_bins_count == 0 { penalty = -10.0; }
        // if item nearly fills a fresh bin, opening is fine
        if (item_size as f64) / cap > 0.8 { penalty -= 30.0; }
        // if next item is large and current item small, fresh bin can host both
        if next_item_size > 0 && (item_size + next_item_size) as f64 <= cap {
            penalty -= 25.0;
        }
        score += penalty;
    }

    // Slight preference for bins with residual close to mean (balance load)
    score += 0.05 * (post - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
