pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are the worst outcome.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Perfect fit is heavily rewarded.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward leaving a residual that can still host a typical next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 15.0;
    }

    // Pressure from number of open bins: discourage spreading when many bins open.
    score += (open_bins_count as f64) * 0.8;

    // Last-chance bin: strongly prefer using it over opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate: only attractive if item is large relative to capacity
    // or all fits are terrible (large dead space elsewhere).
    if bin_residual == bin_capacity {
        let dead_space_elsewhere = if fitting_bins_count > 0 {
            (bin_residual - item_size).min(bin_capacity) as f64
        } else {
            0.0
        };
        let _ = dead_space_elsewhere;
        // Base cost of a fresh bin rises with stream progress.
        score += 30.0 + (step_index as f64 / total_items.max(1) as f64) * 20.0;
        // Large items justify opening a fresh bin.
        if item_size >= 60 {
            score -= 35.0;
        }
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 10.0;
        }
    }

    // Mild alignment with mean residual: prefer bins whose residual deviates
    // from the mean (keeps residual distribution bimodal: full or roomy).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score -= dev * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let next = next_item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items.max(1) as f64 } else { 0.0 };
    let post_norm = pr / cap;
    let fit_ratio = item_size as f64 / cap;
    let gap = (bin_residual - item_size) as f64 / cap;
    let mut score = post_norm * post_norm * 52.0 + post_norm * 20.0;

    // ---- Aggressive 2-step lookahead: shape score around the NEXT item ----
    if next > 0.0 {
        if pr == next {
            score -= 55.0;
        } else if pr > next {
            let slack = pr - next;
            let diff = slack / cap;
            score -= 22.0 * (1.0 - diff).max(0.0);
            score -= (-diff * diff * 450.0).exp() * 24.0 * (1.0 - progress * 0.5);
            // Snug remainder after next item lands.
            if diff < 0.04 {
                score -= (0.04 - diff) * 30.0 * (0.6 + progress * 0.6);
            } else if diff > 0.16 {
                score += (diff - 0.16) * 9.0 * (0.5 + progress);
            }
        } else if pr > 0.0 {
            let dead_ratio = (next - pr) / cap;
            score += dead_ratio * 90.0 * (0.6 + progress * 0.6);
            if fitting_bins_count <= 2 {
                score += 18.0 * (1.0 - progress * 0.5);
            }
        }
    }

    // Dead-floor guard: tiny unusable slivers are stranded capacity.
    if post_residual > 0 {
        let dead_floor = if next_item_size > 0 { (next_item_size.min(12) as f64).max(6.0) } else { 10.0 };
        if pr < dead_floor && pr != next {
            score += 62.0 * (1.0 - progress * 0.3);
        } else if post_residual < 20 && pr != next {
            score += 25.0;
        }
    }

    // ---- Relative-to-mean coupling: favor tighter-than-average bins ----
    if pr > 0.0 && mean_residual > 0.0 {
        let waste = post_norm - mean_residual / cap;
        if waste > 0.0 {
            score += waste * 30.0 * (0.4 + progress * 0.6);
        } else {
            score -= (-waste) * 10.0;
        }
    }

    // ---- New-bin candidate decision (bin_residual == bin_capacity) ----
    if bin_residual == bin_capacity {
        let others = if fitting_bins_count > 0 { fitting_bins_count - 1 } else { 0 };
        let size_pull = fit_ratio * 14.0;
        if fitting_bins_count <= 2 && gap > 0.0 {
            score -= (18.0 + size_pull) * (1.0 - progress * 0.6);
        } else if others == 0 {
            score -= 5.0;
        } else {
            score += 20.0 + open_bins_count as f64 * (0.5 + 0.5 * progress);
        }
        // If the next item is nearly as big as this one, opening a fresh bin
        // wastes capacity; discourage it under mild pressure.
        if next > 0.0 && fitting_bins_count <= 3 && item_size as f64 >= next * 0.95 {
            score -= 5.5 * (1.0 - progress * 0.5);
        }
        if next > 0.0 && item_size as f64 + next > cap {
            score += 8.0 * (1.0 - progress * 0.4);
        }
        if fit_ratio > 0.5 && progress < 0.5 {
            score -= 6.0 * (1.0 - progress);
        }
        if next > 0.0 && item_size as f64 + next <= cap && fit_ratio > 0.35 {
            score -= 3.0 * (1.0 - progress);
        }
        // Late-stream big items: prefer a fresh bin for large items.
        if progress > 0.85 && fit_ratio > 0.6 {
            score -= 4.0 * (progress - 0.85) * 20.0;
        }
        // Second-step snugness from a fresh bin: item + next leaves tiny gap.
        if next > 0.0 && pr > 0.0 {
            let second_slack = (pr - next) / cap;
            if second_slack >= 0.0 && second_slack < 0.05 {
                score -= (0.05 - second_slack) * 40.0 * (0.5 + progress * 0.5);
            }
        }
        if post_norm < 0.02 && fitting_bins_count >= 4 {
            score -= 6.0 * (1.0 - progress);
        }
    }

    // Exact / near-exact fit bonuses.
    if pr == 0.0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 42.0;
    } else if post_residual <= 9 {
        score -= 18.0 * (1.0 - progress * 0.4);
    } else if post_norm < 0.05 {
        score -= 10.2 * (1.0 - post_norm / 0.05);
    }

    // Sharp bonus for leaving a tiny gap (<12% of capacity).
    if gap > 0.0 && gap < 0.12 {
        score -= (0.12 - gap) * 48.0;
    } else if gap >= 0.12 && gap < 0.22 {
        if next > 0.0 && pr > 0.0 && pr < next {
            score += (gap - 0.10) * 90.5 * (0.5 + progress);
        } else if fitting_bins_count <= 3 {
            score += (gap - 0.12) * 18.0 * (0.5 + progress * 0.5);
        }
    }
    if gap >= 0.22 && gap < 0.30 && fitting_bins_count <= 2 {
        score += (gap - 0.22) * 22.0 * (0.6 + progress * 0.4);
    }
    // Next-item chain: leftover after placing next item nearly closes bin.
    if next > 0.0 && gap > 0.12 {
        let nxt_gap = ((gap * cap - next).max(0.0)) / cap;
        if nxt_gap < 0.06 {
            score -= 10.0 * (1.0 - nxt_gap / 0.06) * (0.5 + progress);
        }
    }

    // Reward large items filling bins deeply.
    score -= fit_ratio * fit_ratio * 6.0;

    // Congestion: when many bins compete for this item, penalize sloppy fits.
    if fitting_bins_count > 2 {
        score += gap * 6.5 * ((fitting_bins_count.min(12) as f64 - 2.0) / 10.0);
    }
    if open_bins_count > 8 {
        score += post_norm * 5.0 * ((open_bins_count.min(20) as f64 - 8.0) / 12.0);
    }

    // Late-stream consolidation: penalize moderately large residuals late.
    if progress > 0.7 && post_norm > 0.25 {
        score += (post_norm - 0.25) * 6.0 * (progress - 0.7) / 0.3;
    }

    // Last-chance bonus: prefer a bin that would otherwise be wasted.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 - fit_ratio);
    }

    // Deep fill bonus relative to actual residual.
    let fill_r = item_size as f64 / bin_residual.max(1) as f64;
    if fill_r > 0.90 && bin_residual != bin_capacity {
        score -= (fill_r - 0.90) * 18.0 * (0.6 + progress * 0.5);
    }

    // Dead-space guard: stranded small gap after next item.
    if next > 0.0 && pr > 0.0 {
        let after_next = (pr - next).max(0.0);
        let dead = after_next / cap;
        if dead > 0.0 && dead < 0.08 {
            let reusable = if after_next >= next { 1.0 } else { 0.0 };
            score += (0.08 - dead) * 16.0 * (1.0 - reusable * 0.5) * (0.5 + progress);
        }
    }

    // Half-consumed bins late in the stream.
    if pr > 0.0 && pr < item_size as f64 * 0.5 && progress > 0.3 {
        score += 4.0 * (1.0 - progress);
    }

    // NEW: residual-variance-aware dead-space coupling — when residual spread is
    // low (stream is homogeneous), tighten mid-range gaps more aggressively.
    if post_residual > 0 && post_norm >= 0.05 && post_norm < 0.15 {
        score += post_norm * 12.0 * (1.0 - progress * 0.4);
    }

    // NEW MUTATION: two-item chain-fill lookahead — reward bins whose residual
    // after this item can host BOTH the next item and a snug remainder,
    // tightening residual distribution (targets dead-space weakness).
    if next > 0.0 && pr >= next {
        let chain_left = pr - next;
        if chain_left > 0.0 && chain_left <= 14.0 {
            score -= (14.0 - chain_left) * 1.6 * (0.7 + progress * 0.5);
        }
        // Bin can absorb item + next exactly: strong compaction signal.
        if chain_left == 0.0 {
            score -= 12.0 * (1.0 - progress * 0.4);
        }
    }
    // NEW MUTATION: mean-residual-aware gap damping — when the average residual
    // is small (stream near saturation), punish mid-size gaps harder to push
    // selection toward the tightest fits and cut wasted bins.
    if gap >= 0.05 && mean_residual > 0.0 && mean_residual / cap < 0.18 {
        score += gap * 14.0 * (1.0 - (mean_residual / cap) / 0.18) * (0.5 + progress * 0.7);
    }
    // NEW MUTATION: congestion-aware new-bin suppression — with many open bins
    // that fit, strongly discourage opening another bin unless the item is huge.
    if bin_residual == bin_capacity && fitting_bins_count > 3 && fit_ratio < 0.7 {
        score += (fitting_bins_count.min(10) as f64 - 3.0) * 9.0 * (1.0 - progress * 0.3);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly fits next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near match: next item fits with small slack.
    else if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - slack / bin_capacity as f64);
    }

    // Penalize post_residual that is too small to hold any plausible future item
    // (dead space below the minimum item size).
    if post_residual < 10 && post_residual > 0 {
        score += 15.0 * (10.0 - post_residual as f64);
    }

    // Reward tight fits: small post_residual relative to bin capacity.
    score -= 30.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Coupling with mean residual: prefer bins whose post_residual tracks the mean,
    // penalize outliers that waste large residual capacity.
    score += 0.35 * (post_residual as f64 - mean_residual).abs();

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate handling: an empty bin is a fallback; make it attractive
    // only when no open bin offers a good fit (post_residual large / dead space risk).
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 45.0;
        // If item would leave a large, awkward residual in existing bins, a fresh
        // bin becomes competitive: the fresh-bin post_residual is (C - item).
        let fresh_post = (bin_capacity - item_size) as f64;
        if next_item_size > 0 && fresh_post >= next_item_size as f64 {
            score -= 15.0;
        }
        // More open bins => higher cost of adding another.
        score += 3.0 * open_bins_count as f64;
    }

    // Slight stream-progression pressure: later in the stream, prefer consolidating
    // into existing bins (packing density matters more).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 10.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (small post residual is good).
    score += 0.5 * (post_residual as f64 / bin_capacity as f64).powf(2.0) * bin_capacity as f64;

    // Dead-space penalty: residuals too small for the smallest plausible item (<=10).
    if post_residual < 10 {
        score += 25.0; // perfect fill, great
        score -= 20.0;
    }

    // Lookahead: penalize if placing here leaves the next item unable to fit.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 8.0 + 0.3 * (next_item_size - post_residual) as f64;
        } else {
            // reward leaving room for the next item
            score -= 4.0 * (1.0 - ((post_residual - next_item_size) as f64 / bin_capacity as f64)).abs().min(1.0);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0 + 0.2 * item_size as f64;
    }

    // New-bin candidate handling: an empty bin should only win when no open bin
    // offers a decent fit. Penalize opening new bins, more so early in the stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let tightness = (item_size as f64 / bin_capacity as f64).powf(2.0);
        score += 30.0 + 20.0 * (1.0 - progress) - 10.0 * tightness;
        if fitting_bins_count == 0 {
            score -= 60.0; // nothing fits elsewhere; new bin is required
        }
    }

    // Global state coupling: when mean residual across open bins is high,
    // prefer consolidating into bins with below-average residual.
    let dev = bin_residual as f64 - mean_residual;
    score -= 0.15 * dev;

    // Mild preference for using more-open bins (avoid bin proliferation),
    // scaled by stream progress.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual < bin_capacity {
        score -= 5.0 * progress;
    }

    // Prefer bins whose residual is close to the item (waste minimization).
    let gap = (bin_residual - item_size) as f64;
    score += 0.05 * gap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 1.02;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let norm_pr = pr / cap;

    // Smooth non-linear coupling of post_residual with stream progress
    let mut score = norm_pr * (1.0 + 0.9 * progress) + 1.7 * norm_pr * norm_pr * (1.0 - progress);

    // Reward tight fits (small post_residual) more strongly as stream advances
    score -= 0.8 * (1.0 - norm_pr).powi(3) * (0.5 + progress);

    // Penalize dead space close to but not equal to zero, smoothly
    score += 0.5 * (norm_pr * (1.0 - norm_pr)).powi(2);

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 3.0;
    }

    // Lookahead: reward bins whose residual will fit the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            score -= 1.2 * (1.0 - pr / cap) * (1.0 - nx / cap);
        } else {
            score += 0.6 * (nx - pr) / cap;
        }
    }

    // Mild penalty for opening a new bin when open bins exist and fit well
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        score += 1.0 + 0.5 * (1.0 - item_size as f64 / cap);
    }

    // Encourage consolidation when many bins are open
    score += 0.3 * (mean_residual - pr) / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
