    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo classes over capacity.
    let r = post_residual;
    let m10 = (r % 10) as f64;
    let m25 = (r % 25) as f64;
    let m50 = (r % 50) as f64;

    // Reward residuals that align to "nice" harmonic classes (multiples of 10/25/50).
    if r > 0 {
        if m10 == 0.0 { score -= 6.0; }
        else { score += m10 * 0.4; }
        if m25 == 0.0 { score -= 4.0; }
        else { score += m25 * 0.15; }
        if m50 == 0.0 { score -= 3.0; }
    }

    // Integer-division thresholds: classify post_residual into usable slots.
    let half = bin_capacity / 2;
    let quarter = bin_capacity / 4;
    if r >= half {
        score -= 8.0; // half-bin or larger leftover remains very reusable
    } else if r >= quarter {
        score -= 2.0;
    } else if r == 0 {
        score -= 15.0; // perfect fit
    } else {
        // small dead space; penalize proportionally
        score += (quarter - r) as f64 * 0.3;
    }

    // Lookahead coupling: does next item fit in the post-residual?
    if next_item_size > 0 && r > 0 {
        if next_item_size <= r {
            score -= 5.0;
            // harmonic match: next item leaves a nice residual too
            let nr = r - next_item_size;
            if nr % 10 == 0 { score -= 3.0; }
        } else {
            score += (next_item_size - r) as f64 * 0.2;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: only attractive when no open bin is decent.
    if bin_residual == bin_capacity {
        let crowding = open_bins_count as f64;
        let spread = (mean_residual - post_residual as f64).abs();
        score = bin_capacity as f64 * 0.95
            + crowding * 0.5
            + spread * 0.3
            - (item_size as f64) * 0.1;
        if fitting_bins_count == 0 { score -= 50.0; }
    } else {
        // Prefer fuller bins: tie-break on tightness of fit.
        let tightness = (bin_residual - item_size) as f64 / bin_capacity as f64;
        score += tightness * 10.0;
    }

    // Mild stream-progress drift toward consolidation late in the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 2.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
