            let second_slack = (pr - nxt) / cap;
            if second_slack >= 0.0 && second_slack < 0.05 {
                score -= (0.05 - second_slack) * 40.0 * (0.5 + progress * 0.5);
            }
        }
        if post_residual > 0 && post_norm < 0.02 && fitting_bins_count >= 4 {
            score -= 6.0 * (1.0 - progress);
        }
    }

    // Global pressure: high mean residual -> pack tight bins.
    score -= (mean_residual / cap) * 5.0;

    // Waste-relative pressure: penalize bins whose post-residual exceeds mean.
    if post_residual > 0 && mean_residual > 0.0 {
        let waste = (post_residual as f64 / cap) - (mean_residual / cap);
        if waste > 0.0 {
            score += waste * 30.0 * (0.4 + progress * 0.6);
        } else {
            score -= (-waste) * 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // for typical items are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 25.0;
    } else if post_residual >= 20 && post_residual < 35 {
        score += 8.0;
    }

    // Reward tight fits (post_residual small relative to bin capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Perfect fit gets a strong bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead: if the next item fits in the post-residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }
    // If next item cannot fit but post_residual is nonzero, mild penalty.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 10.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // and discourage opening new bins.
    score += 3.0 * open_bins_count as f64;

    // New-bin candidate handling: opening a new bin is only attractive when
    // few bins are open or the current bin would leave a bad gap.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let dead_penalty = if post_residual > 0 && post_residual < 20 { 1.0 } else { 0.0 };
        score += 20.0 * open_bins_count as f64
            + 15.0 * (1.0 - progress)
            - 30.0 * dead_penalty;
    }

    // Mild preference toward bins whose residual is already below average
    // (consolidating space into fewer bins).
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let post_norm = pr / cap;
    let mut score = post_norm * post_norm * 50.0 + post_norm * 20.0;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 42.0;
    } else if post_residual <= 9 {
        score -= 18.0 * (1.0 - progress * 0.4);
    }

    // Dead-space class: tiny residuals are almost unusable.
    let dead_floor = if next_item_size > 0 { (next_item_size.min(12) as f64).max(6.0) } else { 10.0 };
    if post_residual > 0 && (post_residual as f64) < dead_floor {
        score += 62.0 * (1.0 - progress * 0.3);
    } else if post_residual < 20 {
        score += 25.0;
    }

    // Harmonic divisibility rewards.
    if post_residual > 0 {
        let p = post_residual;
        if p % 50 == 0 { score -= 18.0; }
        else if p % 25 == 0 { score -= 12.0; }
        else if p % 20 == 0 { score -= 10.0; }
        else if p % 10 == 0 { score -= 8.0; }
        else { score += (p % 5) as f64 * 1.5; }
    }

    // Lookahead: next item fit quality in post_residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64 / cap;
        score -= (-slack * slack * 450.0).exp() * 24.0 * (1.0 - progress * 0.5);
        let nxt_left = post_residual - next_item_size;
        if nxt_left % 10 == 0 { score -= 10.0; }
        else if nxt_left > 12 { score -= 4.0; }
        else { score += 6.0; }
    }
    if next_item_size > 0 && pr > 0.0 && (pr as u32) < next_item_size && post_norm > 0.03 {
        let dead_ratio = (next_item_size as f64 - pr) / cap;
        score += dead_ratio * 90.0 * (0.6 + progress * 0.6);
    }
    if next_item_size > 0 && post_residual > 0 && (post_residual as u32) < next_item_size && fitting_bins_count <= 2 {
        score += 18.0 * (1.0 - progress * 0.5);
    }

    // Tight-gap bonus.
    let gap = (bin_residual - item_size) as f64 / cap;
    if gap > 0.0 && gap < 0.12 {
        score -= (0.12 - gap) * 48.0;
    } else if gap >= 0.12 && gap < 0.22 {
        if fitting_bins_count <= 3 {
            score += (gap - 0.12) * 18.0 * (0.5 + progress * 0.5);
        }
    }
    if gap >= 0.22 && gap < 0.30 && fitting_bins_count <= 2 {
        score += (gap - 0.22) * 22.0 * (0.6 + progress * 0.4);
    }

    // Last-chance bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let size_pull = (item_size as f64 / cap) * 14.0;
        if fitting_bins_count <= 2 {
            score -= (18.0 + size_pull) * (1.0 - progress * 0.6);
        } else {
            score += 20.0 + open_bins_count as f64 * (0.5 + 0.5 * progress);
        }
        if next_item_size > 0 && fitting_bins_count <= 3 && (item_size as f64) >= next_item_size as f64 * 0.95 {
            score -= 5.5 * (1.0 - progress * 0.5);
        }
        if next_item_size > 0 && fitting_bins_count >= 1 {
            let nxt = next_item_size as f64;
            if (item_size as f64) + nxt > cap {
                score += 8.0 * (1.0 - progress * 0.4);
            }
        }
        if (item_size as f64) > cap * 0.5 && progress < 0.5 {
            score -= 6.0 * (1.0 - progress);
        }
        if progress > 0.85 && (item_size as f64) / cap > 0.6 {
            score -= 4.0 * (progress - 0.85) * 20.0;
        }
        if next_item_size > 0 && (item_size as f64) + (next_item_size as f64) <= cap && (item_size as f64) / cap > 0.35 {
            score -= 3.0 * (1.0 - progress);
        }
        if next_item_size > 0 && post_residual > 0 {
            let nxt = next_item_size as f64;
            let second_slack = (pr - nxt) / cap;
            if second_slack >= 0.0 && second_slack < 0.05 {
                score -= (0.05 - second_slack) * 40.0 * (0.5 + progress * 0.5);
            }
        }
        if post_residual > 0 && post_norm < 0.02 && fitting_bins_count >= 4 {
            score -= 6.0 * (1.0 - progress);
        }
    }

    // Global pressure.
    score -= (mean_residual / cap) * 5.0;

    // Waste-relative pressure.
    if post_residual > 0 && mean_residual > 0.0 {
        let waste = (post_residual as f64 / cap) - (mean_residual / cap);
        if waste > 0.0 {
            score += waste * 30.0 * (0.4 + progress * 0.6);
        } else {
            score -= (-waste) * 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fills strongly (non-linear).
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 35.0;
    } else if post_residual <= 10 {
        score -= 18.0;
    }

    // 2-step lookahead: reward residuals that exactly fit the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            if slack <= 10.0 {
                score -= 25.0 - 1.5 * slack;
            } else {
                // Penalize leaving space that neither fits next item nor is tiny.
                score += 0.35 * slack;
            }
        } else {
            // Next item cannot follow into this bin: penalize proportional dead space.
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    }

    // Relative to mean residual: prefer bins that will end up tighter than average.
    score += 0.4 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: make opening a new bin expensive unless the current item
    // is large and the fit in open bins would be terrible.
    if bin_residual == bin_capacity {
        score += 55.0;
        if item_size > 60 {
            score -= 10.0;
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 15.0; // pairing large items together in a fresh bin
        }
    }

    // Late in the stream, consolidate harder.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 8.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Mild penalty for proliferating bins.
    score += 0.05 * open_bins_count as f64;

    score
}

