pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream (0.0 -> 1.0)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Reward tight fits: squared penalty on wasted space
    score += (post_residual as f64 / bin_capacity as f64).powi(2) * 40.0;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead: if the next item can use this bin's post_residual, reward strongly
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Chain fit is excellent: reward proportional to how well next item fits
            let chain_waste = (post_residual - next_item_size) as f64;
            score -= 30.0 - (chain_waste / bin_capacity as f64) * 20.0;
        } else if next_item_size > bin_residual {
            // Next item can't fit here anyway; leaving big post_residual may still help later
            score += (post_residual as f64 / bin_capacity as f64) * 10.0 * progress;
        }
    } else {
        // Last item: maximize fill, minimal penalty
        score -= 20.0;
    }

    // Penalize bins whose residual is far below mean (fragmented bins) mildly
    let residual_diff = post_residual as f64 - mean_residual;
    score += residual_diff * 0.15;

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin wastes capacity of all open bins.
    // Only attractive when no open bin fits or open bins are very fragmented.
    if bin_residual == bin_capacity {
        let no_fit = fitting_bins_count == 0;
        let fragmented = mean_residual > 0.0 && (mean_residual - item_size as f64) < 5.0;
        if no_fit {
            score -= 100.0; // must open new bin
        } else if fragmented && open_bins_count > 3 {
            score -= 5.0; // slightly prefer fresh bin over terrible fits
        } else {
            score += 55.0 + (open_bins_count as f64).ln() * 8.0; // discourage opening new bins
        }
    }

    // Late in stream: consolidate, penalize leaving many small residuals
    score += progress * (open_bins_count as f64) * 0.5;

    // Mild preference for bins with residual close to item_size (snug fit)
    let snug = (bin_residual as f64 - item_size as f64).abs();
    score += snug * 0.1;

    score
}

