pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let next = next_item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items.max(1) as f64 } else { 0.0 };
    let post_norm = pr / cap;
    let fit_ratio = item_size as f64 / cap;
    let gap = (bin_residual - item_size) as f64 / cap;
    let mut score = post_norm * post_norm * 56.5 + post_norm * 21.8;

    // Exact-fill dominance (borrowed from best): closing a bin is king.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 42.0;
    } else if post_residual <= 9 {
        score -= 18.0 * (1.0 - progress * 0.4);
    }

    // Stranded sliver guard with next-item-aware floor.
    let dead_floor = if next_item_size > 0 { (next_item_size.min(12) as f64).max(6.0) } else { 10.0 };
    if post_residual > 0 && pr < dead_floor && pr != next {
        score += 62.0 * (1.0 - progress * 0.3);
    } else if post_residual > 0 && post_residual < 20 {
        score += 25.0;
    }

    // ---- 2-step lookahead around the NEXT item ----
    if next > 0.0 {
        if pr == next {
            score -= 45.0;
        } else if pr > next {
            let slack = pr - next;
            let diff = slack / cap;
            score -= 20.0 * (1.0 - diff).max(0.0);
            score -= (-diff * diff * 450.0).exp() * 24.0 * (1.0 - progress * 0.5);
            if diff < 0.04 {
                score -= (0.04 - diff) * 26.0 * (0.6 + progress * 0.6);
            } else if diff > 0.16 {
                score += (diff - 0.16) * 8.0 * (0.5 + progress);
            }
        } else if pr > 0.0 {
            let dead_ratio = (next - pr) / cap;
            score += dead_ratio * 90.0 * (0.6 + progress * 0.6);
            if fitting_bins_count <= 2 {
                score += 18.0 * (1.0 - progress * 0.5);
            }
        }
        // Two-item chain: after next lands, leftover nearly closes bin.
        if pr > 0.0 && gap > 0.12 {
            let nxt_gap = ((gap * cap - next).max(0.0)) / cap;
            if nxt_gap < 0.06 {
                score -= 9.0 * (1.0 - nxt_gap / 0.06) * (0.5 + progress);
            }
        }
        // Second-slack snug bonus.
        if pr > 0.0 {
            let second_slack = (pr - next) / cap;
            if second_slack >= 0.0 && second_slack < 0.05 {
                score -= (0.05 - second_slack) * 40.0 * (0.5 + progress * 0.5);
            }
        }
    }

    // Relative-to-mean coupling: favor tighter-than-average bins.
    if pr > 0.0 && mean_residual > 0.0 {
        let waste = post_norm - mean_residual / cap;
        if waste > 0.0 {
            score += waste * 30.0 * (0.4 + progress * 0.6);
        } else {
            score -= (-waste) * 10.0;
        }
    }

    // ---- New-bin candidate decision ----
    if bin_residual == bin_capacity {
        let others = if fitting_bins_count > 0 { fitting_bins_count - 1 } else { 0 };
        let size_pull = fit_ratio * 14.0;
        if fitting_bins_count <= 2 && gap > 0.0 {
            score -= (18.0 + size_pull) * (1.0 - progress * 0.6);
        } else if others == 0 {
            score -= 5.0;
        } else {
            score += 20.0 + open_bins_count as f64 * (0.5 + 0.5 * progress);
        }
        if next > 0.0 && fitting_bins_count <= 3 && item_size as f64 >= next * 0.95 {
            score -= 5.5 * (1.0 - progress * 0.5);
        }
        if next > 0.0 && item_size as f64 + next > cap {
            score += 8.0 * (1.0 - progress * 0.4);
        }
        if fit_ratio > 0.5 && progress < 0.5 {
            score -= 6.0 * (1.0 - progress);
        }
        if progress > 0.85 && fit_ratio > 0.6 {
            score -= 4.0 * (progress - 0.85) * 20.0;
        }
        if next > 0.0 && item_size as f64 + next <= cap && fit_ratio > 0.35 {
            score -= 3.0 * (1.0 - progress);
        }
    }

    // Sharp bonus for leaving a tiny gap.
    if gap > 0.0 && gap < 0.12 {
        score -= (0.12 - gap) * 48.0;
    } else if gap >= 0.12 && gap < 0.22 && fitting_bins_count <= 3 {
        score += (gap - 0.12) * 18.0 * (0.5 + progress * 0.5);
    }
    if gap >= 0.22 && gap < 0.30 && fitting_bins_count <= 2 {
        score += (gap - 0.22) * 22.0 * (0.6 + progress * 0.4);
    }

    // Reward large items filling bins deeply.
    score -= fit_ratio * fit_ratio * 6.0;

    // Congestion: many competing bins -> penalize sloppy fits.
    if fitting_bins_count > 2 {
        score += gap * 6.5 * ((fitting_bins_count.min(12) as f64 - 2.0) / 10.0);
    }
    if open_bins_count > 8 {
        score += post_norm * 5.0 * ((open_bins_count.min(20) as f64 - 8.0) / 12.0);
    }

    // Late-stream consolidation.
    if progress > 0.7 && post_norm > 0.25 {
        score += (post_norm - 0.25) * 6.0 * (progress - 0.7) / 0.3;
    }

    // Last-chance bonus.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 - fit_ratio);
    }

    // Deep fill bonus.
    let fill_r = item_size as f64 / bin_residual.max(1) as f64;
    if fill_r > 0.90 && bin_residual != bin_capacity {
        score -= (fill_r - 0.90) * 18.0 * (0.6 + progress * 0.5);
    }

    // Half-consumed bins late: hard-to-refill residual guard.
    if pr > 0.0 && pr < item_size as f64 * 0.5 && progress > 0.3 {
        score += 4.0 * (1.0 - progress);
    }

    // Mid-residual band strand risk.
    if pr > 0.0 && post_norm >= 0.10 && post_norm < 0.20 && next > 0.0 && next > pr {
        score += (next - pr) / cap * 26.0 * (0.4 + progress * 0.8);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let mut score = pr;

    // Early stream: prefer tight fits (low post_residual) more aggressively.
    // Late stream: tolerate residual, favor consolidating bins.
    let progress_weight = 1.0 + 0.6 * t * t;
    score *= progress_weight;

    // Smooth polynomial interaction: penalize medium residuals more than tiny/huge ones,
    // with strength modulated by progress.
    let bump = norm_pr * (1.0 - norm_pr); // peaks at 0.5 residual
    score += 30.0 * bump * (0.5 + t);

    // Cubic coupling: reward near-perfect fits increasingly over time.
    score -= 20.0 * (1.0 - norm_pr).powi(3) * (0.5 + t);

    // Last-chance bin: strong bonus to use it rather than open a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 15.0 + 10.0 * t;
    } else if next_item_size > 0 {
        // Penalize if next item would need this bin's leftover but barely misses.
        let gap = (next_item_size as f64 - pr) / cap;
        score += 10.0 * (1.0 - gap).max(0.0);
    }

    // Mean residual coupling: placing into a bin with residual near the mean is neutral;
    // deviating bins get smoothed preference via quadratic term.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 8.0 * dev * dev * (1.0 - t);

    // Slight preference for bins that are already fairly full (low residual before placement).
    score += 0.15 * (bin_residual as f64) * (1.0 - t);

    // New-bin candidate: mild penalty so it only wins when open bins are truly bad.
    if bin_residual == bin_capacity {
        score += 25.0 - 20.0 * t;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: perfect fits are gold.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 300.0;
    } else if post_residual <= 10 {
        score -= 120.0;
    }

    // Modulo classes: residuals that are multiples of common item granularities
    // (10/20/25/50) are more reusable -> reward them.
    if post_residual > 0 {
        if post_residual % 10 == 0 {
            score -= 25.0;
            if post_residual % 50 == 0 { score -= 30.0; }
            else if post_residual % 25 == 0 { score -= 15.0; }
        }
        // Odd/awkward residuals penalized
        if post_residual % 2 == 1 { score += 8.0; }
        if post_residual < 10 { score += 40.0; } // dead space below min item
    }

    // Lookahead coupling: does post_residual fit next item exactly or well?
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 250.0;
        } else if next_item_size <= post_residual {
            let gap = post_residual - next_item_size;
            if gap <= 10 { score -= 80.0; }
            else { score -= (30.0 - (gap as f64).min(30.0) * 0.5).max(0.0); }
        } else {
            // next item can't use this bin's remainder; penalize small remainders more
            let waste = next_item_size - post_residual;
            score += (waste as f64) * 0.3;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate logic: only attractive when open bins are crowded.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowd = open_bins_count as f64;
        let crowded = mean_residual < item_size as f64 * 1.5;
        // base penalty: prefer existing bins slightly
        score += 15.0;
        if crowded { score -= 60.0; }
        if mean_residual < 10.0 && open_bins_count > 0 { score -= 120.0; }
        // late in stream, consolidation matters more
        score -= progress * 10.0;
        // many open bins with low mean residual -> opening fresh is fine
        if crowd > 4.0 && mean_residual < 20.0 { score -= 40.0; }
    }

    // Prefer tighter fits generally: fraction of capacity wasted
    let waste_frac = post_residual as f64 / cap;
    score += waste_frac * 50.0;

    // Slight preference to balance residual against mean (harmonic spreading)
    score -= (mean_residual - post_residual as f64).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
