    if post_residual > 0 {
        if post_residual < 10 {
            score += 40.0; // unusable tiny gap (items are >=1, but tiny gaps waste space)
        } else if post_residual < 25 {
            score += 18.0; // near-unusable gap
        } else if post_residual < 45 {
            score += 6.0;  // marginal gap
        }
    } else {
        // Perfect fit: strong reward.
        score -= 60.0;
    }

    // Reward using a bin whose residual was close to the item (tight fit).
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score -= 25.0 * (1.0 - tightness).max(0.0) * (bin_residual as f64 / bin_capacity as f64);

    // Open-bins pressure: with many open bins, prefer filling existing ones.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 0.9 * open_bins_count as f64 * (0.4 + 0.6 * progress);

    // Prefer bins with residuals below the mean residual (consolidate small leftovers).
    score += (mean_residual - bin_residual as f64).clamp(-30.0, 30.0) * 0.3;

    // Last-chance bin: strongly favor it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Lookahead: if the next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here; slightly penalize leaving a residual just below next_item_size.
            if post_residual > 0 && post_residual < next_item_size {
                score += 5.0;
            }
        }
    }

    // New-bin candidate: baseline cost of opening a fresh bin, modulated by pressure.
    if bin_residual == bin_capacity {
        score += 55.0 + 2.0 * open_bins_count as f64;
        // If nothing fits well (this call only happens for the fresh bin anyway),
        // a fresh bin is fine when current bins would leave big dead space.
        if post_residual > 0 && post_residual < 10 {
            score -= 10.0;
        }
    }

    score
}

