    }

    // Compare against mean residual: bins already below mean are precious;
    // avoid wasting small residuals on large items.
    if (bin_residual as f64) < mean_residual {
        score += 8.0;
    } else {
        score -= 3.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Penalize opening a new bin unless nothing fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let best_possible = if next_item_size > 0 { next_item_size.min(bin_capacity) } else { 0 };
        let waste = (bin_capacity - item_size) as f64;
        score += 55.0 + waste * 0.3;
        // If an existing bin leaves a residual that matches the next item, avoid new bin.
        if next_item_size > 0 && post_residual >= next_item_size {
            score += 20.0;
        }
        let _ = best_possible;
    }

    // Late in the stream: consolidate harder, discourage new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if is_new_bin {
        score += 30.0 * progress;
    }

    // Many open bins: prefer filling existing ones to reduce spread.
    score += open_bins_count as f64 * if is_new_bin { 2.0 } else { -0.5 };

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize large leftover space (wasted capacity), with diminishing effect.
    let pr = post_residual as f64;
    score += 0.35 * (pr * pr) / cap;

    // Lookahead: if the next item fits exactly into the post-residual, big reward.
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if (ns - pr).abs() < 1.0 {
            score -= 60.0;
        } else if ns <= pr {
            score -= 15.0 * (1.0 - (pr - ns) / cap);
        } else {
            // next item won't fit here; mild penalty proportional to dead space
            score += 8.0 * (ns - pr).min(cap) / cap;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: normally penalize opening a new bin...
    if bin_residual == bin_capacity {
        let mut new_bin_penalty = 45.0 + 2.0 * open_bins_count as f64;
        // ...but if existing fits are poor (high post-residual vs mean residual),
        // opening a fresh bin becomes attractive.
        let poor_fit = pr as f64 - mean_residual;
        if poor_fit > 0.0 {
            new_bin_penalty -= 50.0 * (poor_fit / cap);
        }
        // Early in the stream, keep bins open longer (amortize); late, be flexible.
        let t = step_index as f64 / (total_items.max(1) as f64);
        new_bin_penalty -= 10.0 * t;
        score += new_bin_penalty.max(-30.0);
    } else {
        // Open-bin bonus scaled by how average the bin is (prefer concentrating fill).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score -= 10.0 * (1.0 - dev / cap);
    }

    // Mild pressure to keep total open bins low.
    score += 0.8 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
