        score += 4.0 * (1.0 - progress);
    }

    // Second-slack chain: after next item lands, if the remaining slack is
    // nearly zero, strongly reward (two items close the bin together).
    if next > 0.0 && pr > 0.0 && pr >= next {
        let second_slack = (pr - next) / cap;
        if second_slack < 0.05 {
            score -= (0.05 - second_slack) * 40.0 * (0.5 + progress * 0.5);
        }
    }

    score
}

