    score -= (it / cap) * (it / cap) * 20.0;

    // Lookahead: if next item fits the post-residual, strongly favor this bin.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 15.0 + 10.0 * progress;
