    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless residuals are tight.
    if bin_residual == bin_capacity {
        let mean_tightness = 1.0 - (mean_residual / cap).clamp(0.0, 1.0);
        score += 18.0 - 14.0 * mean_tightness * mean_tightness + 10.0 * progress;
    } else {
