        score += (post_norm - 0.25) * 6.0 * (progress - 0.7) / 0.3;
    }

    // Last-chance bonus: prefer a bin that would otherwise be wasted.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 - fit_ratio);
    }

    // Deep fill bonus.
    let fill_r = item_size as f64 / bin_residual.max(1) as f64;
    if fill_r > 0.90 && bin_residual != bin_capacity {
        score -= (fill_r - 0.90) * 18.0 * (0.6 + progress * 0.5);
    }

    // Dead-space guard after next item.
    if next > 0.0 && pr > 0.0 {
        let after_next = (pr - next).max(0.0);
        let dead = after_next / cap;
        if dead > 0.0 && dead < 0.08 {
            let reusable = if after_next >= next { 1.0 } else { 0.0 };
            score += (0.08 - dead) * 16.0 * (1.0 - reusable * 0.5) * (0.5 + progress);
        }
    }

    // Mid-residual band stranded penalty.
    if pr > 0.0 && post_norm >= 0.10 && post_norm < 0.20 && next > 0.0 && next > pr {
        score += (next - pr) / cap * 26.0 * (0.4 + progress * 0.8);
    }

    // Half-consumed bins late in the stream.
    if pr > 0.0 && pr < item_size as f64 * 0.5 && progress > 0.3 {
        score += 4.0 * (1.0 - progress);
    }

    // Waste-vs-mean term.
    if pr > 0.0 && mean_residual > 0.0 {
        let waste = post_norm - mean_residual / cap;
        if waste > 0.0 {
            score += waste * 30.0 * (0.4 + progress * 0.6);
        } else {
            score -= (-waste) * 10.0;
        }
    }

    // NEW: penalize bins whose post-residual can never host any future item class.
    if pr > 0.0 && next > 0.0 && pr < next && post_norm > 0.02 {
        score += (next - pr) / cap * 20.0 * (0.5 + progress * 0.5);
    }

    // NEW: reward bins that remain exactly reusable by the next item.
    if next > 0.0 && pr > 0.0 && (pr - next) / cap < 0.02 && pr >= next {
        score -= 6.0 * (1.0 - (pr - next) / cap / 0.02) * (0.5 + progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: strongly prefer small post_residual (tight fit)
    let pr = post_residual as f64;
    score += (post_residual as f64 / bin_capacity as f64).powi(3) * 40.0;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 100.0;
    }

    // Harmonic class of post_residual: dead space that cannot host
    // typical items (size >= 10) is wasted. Classify via integer division.
    let dead_class = post_residual / 10; // 0..=10 usable slots
    score += match dead_class {
        0 => -30.0,                      // perfect or near-perfect fill
        1..=3 => 10.0 + (3 - dead_class) as f64 * 2.0, // small awkward gap
        4..=7 => 0.0,                    // moderately usable
        _ => -5.0,                       // large residual, still flexible
    };

    // Modulo-10 residue: residuals that align with the 10-grid fit
    // more future items; penalize off-grid residuals slightly.
    if post_residual % 10 != 0 {
        score += 3.0;
    }

    // Lookahead coupling: does post_residual fit next_item_size?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward leaving room for the next item, scaled by how snug
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / bin_capacity as f64);
            // Harmonic bonus: next item leaves another usable class
            let next_post = post_residual - next_item_size;
            if next_post % 10 == 0 {
                score -= 8.0;
            }
        } else {
            // Bin will be closed anyway; small penalty unless residual tiny
            score += 2.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: only attractive early in the stream or
    // when the item fits poorly everywhere.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let poor_fit = (post_residual as f64) > 0.6 * bin_capacity as f64;
        if poor_fit || open_bins_count == 0 {
            score -= 20.0 + 15.0 * (1.0 - progress);
        } else {
            score += 25.0; // discourage spreading out when fits exist
        }
    }

    // Mild pressure to consolidate when many bins are open relative to mean residual
    if open_bins_count > 4 && (bin_residual as f64) < mean_residual {
        score -= 4.0;
    }

    score
}

