pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: unusable tiny gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 15.0;
    }

    // Reward perfect / near-perfect fits.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // If the next item fits exactly into the post-residual, strongly favor this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack < 5.0 {
            score -= 40.0;
        } else {
            score -= 10.0;
        }
    }
    // Penalize if next item cannot fit in the leftover gap.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 20.0;
    }

    // Last-chance bin before opening a new one: prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: mildly discourage scattering across many bins,
    // but encourage using existing bins over opening new ones.
    if bin_residual < bin_capacity {
        score -= 5.0 + (open_bins_count as f64).sqrt() * 2.0;
    } else {
        // New-bin candidate: accept it only when residual would be very tight
        // or no good fit exists among open bins.
        score += 8.0 + mean_residual * 0.15 + (open_bins_count as f64) * 0.5;
        if post_residual >= 10 {
            score += 12.0; // fresh bin leaves large residual; mildly discourage
        }
    }

    // Stream progression: later in the stream, tighten bins more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual < bin_capacity {
        score -= progress * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 1.04;
