pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item -> huge reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Dead space: post_residual too small for the next item (waste).
    if next_item_size > 0 && post_residual < next_item_size {
        score += 0.5 * (next_item_size - post_residual) as f64;
    }

    // Reward leaving space usable by the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 0.3 * next_item_size as f64;
    }

    // Tight fit reward: small post_residual relative to capacity.
    score -= 0.4 * (bin_capacity - post_residual) as f64 / bin_capacity as f64 * 10.0;

    // Last chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless item fits poorly everywhere.
    if bin_residual == bin_capacity {
        score += 35.0;
        // Allow new bin if this item leaves huge awkward residual in existing bins.
        if item_size <= 10 {
            score -= 20.0;
        }
    }

    // Prefer filling bins below mean residual (larger residual = worse to waste).
    score += 0.2 * (post_residual as f64 - mean_residual);

    // Early in stream: be slightly more willing to open bins for flexibility.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 5.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
