pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post_residual) with a non-linear bonus.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space that cannot fit even the smallest plausible item (1..100 range).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable sliver
    } else if post_residual < 20 {
        score += 8.0;  // near-dead space
    }

    // Lookahead: strongly reward bins whose post_residual fits the next item,
    // especially when the next item exactly or nearly fits.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 14.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item cannot follow into this bin: mild penalty scaled by gap.
            let gap = (next_item_size - post_residual) as f64;
            score += 3.0 + 0.08 * gap;
        }
    }

    // Last-chance bin: if this is the only open bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0 + 0.05 * item_size as f64;
    }

    // New-bin candidate handling: opening a new bin is only attractive when existing
    // bins have poor aggregate fit potential (high mean residual fragmentation) or
    // few open bins exist early in the stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = mean_residual / bin_capacity as f64;
        // Prefer new bin when open bins are fragmented (residuals scattered, none tight)
        // and we are late in the stream; early on, reuse is cheaper.
        let new_bin_bonus = 30.0 * fragmentation * (0.5 + progress)
            - 12.0 * (1.0 - fragmentation)
            - 6.0 * (1.0 - progress);
        score += new_bin_bonus;
        // Never open a new bin for a small item when a decent fit exists elsewhere.
        if item_size < 40 {
            score += 10.0;
        }
    } else {
        // Slight preference for reusing bins with larger residuals when many bins open,
        // to consolidate open bins and allow closing emptier ones.
        score -= 0.02 * bin_residual as f64 / open_bins_count.max(1) as f64;
    }

    // Penalize bins whose residual diverges far from the mean (keeps pool homogeneous,
    // making future fits more predictable).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Time-horizon coupling: as the stream nears its end, prioritize perfect packing
    // (minimize post_residual even harder) since future compensation is impossible.
    let horizon = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * horizon * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let next = next_item_size as f64;
