        score += 4.0 * (1.0 - progress);
    }

    // Waste-vs-mean term.
    if pr > 0.0 && mean_residual > 0.0 {
        let waste = post_norm - mean_residual / cap;
        if waste > 0.0 {
            score += waste * 30.0 * (0.4 + progress * 0.6);
        } else {
            score -= (-waste) * 10.0;
        }
    }

    // Penalize bins whose post-residual can never host any future item class.
    if pr > 0.0 && next > 0.0 && pr < next && post_norm > 0.02 {
        score += (next - pr) / cap * 90.0 * (0.6 + progress * 0.6);
    }

    // Reward bins that remain exactly reusable by the next item.
    if next > 0.0 && pr > 0.0 && (pr - next) / cap < 0.02 && pr >= next {
        score -= 6.0 * (1.0 - (pr - next) / cap / 0.02) * (0.5 + progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64) / (total_items.max(1) as f64);
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let post_norm = post / cap;

    // Base: prefer low post residual, with non-linear polynomial shaping.
    let mut score = post * (1.0 + 0.8 * post_norm * post_norm);

    // Smooth progress coupling: later in stream, waste penalized more.
    score += 12.0 * post_norm * post_norm * progress;

    // Last-chance bonus: strongly favor the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Penalty when few fitting bins (scarcity), scaled by progress.
    if fitting_bins_count > 0 && bin_residual != bin_capacity {
        score -= 6.0 / (fitting_bins_count as f64) * (0.5 + progress);
    }

    // Alignment with mean residual: bins near the mean are "flexible" reserves.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 5.0 * dev * dev;

    // Lookahead: reward if next item fits into post residual (chain packing).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual >= next_item_size {
            score -= 10.0 * (1.0 - (nxt / cap));
        } else {
            score += 4.0 * (nxt / cap);
        }
    }

    // New-bin candidate handling: mild penalty early, growing later,
    // reduced if the item is large (hard to place elsewhere).
    if bin_residual == bin_capacity {
        let large = (item_size as f64) / cap;
        score += 8.0 + 20.0 * progress - 10.0 * large * large;
    }

    // Mild open-bins pressure: many open bins -> prefer filling existing ones.
    score += 0.4 * (open_bins_count as f64).ln().max(0.0) * post_norm;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover: classify post_residual into residue classes mod 10.
    // Leftovers that are multiples of 10 are "harmonic" — highly reusable for items
    // in the 10..80 range, so reward them. Odd/non-aligned leftovers are penalized.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Fraction of capacity left after placement
    let fill_frac = post / cap;

    // Harmonic reward: post_residual divisible by 10 -> strong bonus
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 6.0 + 4.0 * fill_frac;
    } else if post_residual % 5 == 0 && post_residual > 0 {
        score -= 2.5;
    } else {
        // Non-harmonic dead space penalty, worse for small leftovers
        score += (10.0 - (post_residual % 10) as f64) * 0.35;
    }

    // Integer-division threshold on post_residual: leftovers < 10 are dead space
    if post_residual < 10 {
        score += 12.0;
    } else if post_residual < 20 {
        score += 4.0;
    }

    // Lookahead coupling: does the next item fit into the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Harmonic match: next item exactly consumes leftover (mod-10 alignment)
            if next_item_size == post_residual {
                score -= 10.0;
            } else if (post_residual - next_item_size) % 10 == 0 {
                score -= 5.0;
            } else {
                score -= 1.5;
            }
        } else {
            // Next item won't fit here: leftover risks becoming dead space
            score += 2.0 + 0.05 * (next_item_size as f64);
        }
    } else {
        // Last item: prefer tightest fit overall
        score -= 3.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // to avoid opening a new bin (unless residual is tiny/dead).
    if fitting_bins_count == 1 && post_residual >= 10 {
        score -= 7.0;
    }

    // Mean-residual coupling: placing in a bin with residual far from the mean
    // helps rebalance the pool of open bins.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score -= 0.03 * dev;

    // Late in the stream, tighten packing: reward near-full bins more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (cap - post) * 0.05;

    // Mild penalty for spreading across many open bins early on
    score += 0.15 * open_bins_count as f64 * (1.0 - progress);

    // Brand-new empty bin candidate: neutral base, penalized so we only open
    // a new bin when no open bin offers a decent harmonic fit.
    if bin_residual == bin_capacity {
        score += 8.0 + 0.1 * item_size as f64;
        // Opening a new bin is attractive for large items early (better long-term layout)
        if item_size >= 50 && progress < 0.5 {
            score -= 6.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let next = next_item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items.max(1) as f64 } else { 0.0 };
    let post_norm = pr / cap;
    let fit_ratio = item_size as f64 / cap;
    let gap = (bin_residual - item_size) as f64 / cap;
    let mut score = post_norm * post_norm * 58.0 + post_norm * 21.0;

    // ---- Aggressive 2-step lookahead: shape score around the NEXT item ----
    if next > 0.0 {
        if pr == next {
            score -= 48.0;
        } else if pr > next {
            let slack = pr - next;
            let diff = slack / cap;
            score -= 20.0 * (1.0 - diff).max(0.0);
            score -= (-diff * diff * 470.0).exp() * 22.0 * (1.0 - progress * 0.5);
            if diff < 0.04 {
                score -= (0.04 - diff) * 28.0 * (0.6 + progress * 0.6);
            } else if diff > 0.16 {
                score += (diff - 0.16) * 8.0 * (0.5 + progress);
            }
        } else if pr > 0.0 {
            score += (next - pr) / cap * 32.0 * (1.0 - progress);
        }
    }

    // ---- Absolute dead-floor guard: tiny stranded remainders ----
    let dead_floor = if next_item_size > 0 { (next_item_size.min(12) as f64).max(6.0) } else { 10.0 };
    if post_residual > 0 && pr < dead_floor && pr != next {
        score += 64.0 * (1.0 - progress * 0.3);
    } else if post_residual > 0 && post_residual < 20 && pr != next {
        score += 25.0;
    }

    // ---- Relative-to-mean coupling: favor tighter-than-average bins ----
    if pr > 0.0 {
        let dev = (mean_residual - pr) / cap;
        if dev > 0.05 {
            score += (dev - 0.05) * 12.0 * (0.4 + progress);
        } else if dev < -0.08 {
            score += (-dev - 0.08) * 6.0 * (1.0 - progress);
        }
    }

    // ---- New-bin candidate decision ----
    if bin_residual == bin_capacity {
        let others = if fitting_bins_count > 0 { fitting_bins_count - 1 } else { 0 };
        let size_pull = fit_ratio * 14.0;
        if fitting_bins_count <= 2 && gap > 0.0 {
            score -= (18.0 + size_pull) * (1.0 - progress * 0.6);
        } else if others == 0 {
            score -= 5.0;
        } else {
            score += 8.0 + 6.0 * (1.0 - progress);
        }
        if next > 0.0 && fitting_bins_count <= 3 && fit_ratio >= next * 0.95 / cap {
            score -= 5.5 * (1.0 - progress * 0.5);
        }
        if next > 0.0 && fitting_bins_count >= 1 && fit_ratio * cap + next > cap {
            score += 8.0 * (1.0 - progress * 0.4);
        }
        // Pairing bonus: prefer a fresh bin when item+next pair nearly fills it.
        if next > 0.0 && fit_ratio * cap + next <= cap {
            let pair_left = (cap - fit_ratio * cap - next) / cap;
            if pair_left < 0.05 {
                score -= (0.05 - pair_left) * 30.0 * (1.0 - progress * 0.5);
            }
        }
        // MUTATION: open a fresh bin early when current item is huge and would
        // strand a mid-band residual that nothing can reuse.
        if fit_ratio > 0.6 && progress < 0.6 && fitting_bins_count >= 1 {
            score -= 4.0 * (1.0 - progress) * (fit_ratio - 0.6) / 0.4;
        }
    }

    // Exact / near-exact fit bonuses (strengthened).
    if pr == 0.0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 42.0;
    } else if post_residual <= 9 {
        score -= 16.0 * (1.0 - progress * 0.4);
    } else if post_norm < 0.05 {
        score -= 10.2 * (1.0 - post_norm / 0.05);
    }

    // Sharp bonus for leaving a tiny gap (<12% of capacity).
    if gap > 0.0 && gap < 0.12 {
        score -= (0.12 - gap) * 48.0;
    } else if gap >= 0.12 && gap < 0.22 && next > 0.0 && pr > 0.0 && pr < next {
        score += (gap - 0.12) * 90.5 * (0.5 + progress);
    }
    if gap >= 0.22 && gap < 0.35 && progress > 0.55 {
        score += (gap - 0.22) * 45.5 * (progress - 0.55) * 2.0;
    }
    // Next-item chain: leftover after next item nearly closes bin.
    if next > 0.0 && gap > 0.12 {
        let nxt_gap = ((gap * cap - next).max(0.0)) / cap;
        if nxt_gap < 0.06 {
            score -= 9.5 * (1.0 - nxt_gap / 0.06) * (0.5 + progress);
        }
    }

    // Reward large items filling bins deeply.
    score -= fit_ratio * fit_ratio * 6.0;

    // Congestion: many competing bins => penalize sloppy fits.
    if fitting_bins_count > 2 {
        score += gap * 6.5 * ((fitting_bins_count.min(12) as f64 - 2.0) / 10.0);
    }
    if open_bins_count > 8 {
        score += post_norm * 5.0 * ((open_bins_count.min(20) as f64 - 8.0) / 12.0);
    }

    // Late-stream consolidation.
    if progress > 0.7 && post_norm > 0.25 {
        score += (post_norm - 0.25) * 6.0 * (progress - 0.7) / 0.3;
    }

    // Last-chance bonus: prefer a bin that would otherwise be wasted.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 - fit_ratio);
    }

    // Deep fill bonus.
    let fill_r = item_size as f64 / bin_residual.max(1) as f64;
    if fill_r > 0.90 && bin_residual != bin_capacity {
        score -= (fill_r - 0.90) * 18.0 * (0.6 + progress * 0.5);
    }

    // Dead-space guard after next item.
    if next > 0.0 && pr > 0.0 {
        let after_next = (pr - next).max(0.0);
        let dead = after_next / cap;
        if dead > 0.0 && dead < 0.08 {
            let reusable = if after_next >= next { 1.0 } else { 0.0 };
            score += (0.08 - dead) * 16.0 * (1.0 - reusable * 0.5) * (0.5 + progress);
        }
    }

    // Mid-residual band stranded penalty.
    if pr > 0.0 && post_norm >= 0.10 && post_norm < 0.20 && next > 0.0 && next > pr {
        score += (next - pr) / cap * 26.0 * (0.4 + progress * 0.8);
    }

    // Half-consumed bins late in the stream.
    if pr > 0.0 && pr < item_size as f64 * 0.5 && progress > 0.3 {
        score += 4.0 * (1.0 - progress);
    }

    // Waste-vs-mean term.
    if pr > 0.0 && mean_residual > 0.0 {
        let waste = post_norm - mean_residual / cap;
        if waste > 0.0 {
            score += waste * 30.0 * (0.4 + progress * 0.6);
        } else {
            score -= (-waste) * 10.0;
        }
    }

    // Penalize bins whose post-residual can never host any future item class.
    if pr > 0.0 && next > 0.0 && pr < next && post_norm > 0.02 {
        score += (next - pr) / cap * 20.0 * (0.5 + progress * 0.5);
    }

    // Reward bins that remain exactly reusable by the next item.
    if next > 0.0 && pr > 0.0 && (pr - next) / cap < 0.02 && pr >= next {
        score -= 6.0 * (1.0 - (pr - next) / cap / 0.02) * (0.5 + progress);
    }

    // MUTATION: reserve-space guard — if placing the item here leaves a residual
    // that is smaller than next but larger than half of next, the leftover is
    // nearly useless; penalize proportionally to how "stranded" it is.
    if next > 0.0 && pr > 0.0 && pr > next * 0.5 && pr < next {
        score += (pr - next * 0.5) / cap * 22.0 * (0.6 + progress * 0.6);
    }

    // MUTATION: two-item lookahead closure — if item + next exactly consumes
    // the bin (or leaves < 2 units), give a strong compaction bonus.
    if next > 0.0 && item_size as f64 + next <= bin_residual as f64 {
        let after2 = bin_residual as f64 - item_size as f64 - next;
        if after2 < 2.0 {
            score -= 14.0 * (1.0 - progress * 0.4);
        } else if after2 <= 10.0 {
            score -= (10.0 - after2) * 0.9 * (0.5 + progress * 0.5);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let next = next_item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items.max(1) as f64 } else { 0.0 };
    let post_norm = pr / cap;
    let fit_ratio = item_size as f64 / cap;
    let gap = (bin_residual - item_size) as f64 / cap;
    let mut score = post_norm * post_norm * 52.0 + post_norm * 21.0;

    // ---- Strong exact / near-exact closure bonuses (from best lineage) ----
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 42.0;
    } else if post_residual <= 9 {
        score -= 18.0 * (1.0 - progress * 0.4);
    }

    // Sliver guard: residual too small to be useful for typical items.
    let dead_floor = if next_item_size > 0 { (next_item_size.min(12) as f64).max(6.0) } else { 10.0 };
    if post_residual > 0 && pr < dead_floor {
        score += 62.0 * (1.0 - progress * 0.3);
    } else if post_residual > 0 && post_residual < 20 {
        score += 25.0;
    }

    // ---- 2-step lookahead: snug remainder after next item lands ----
    if next > 0.0 && pr >= next {
        let slack = (pr - next) / cap;
        score -= (-slack * slack * 450.0).exp() * 24.0 * (1.0 - progress * 0.5);
        if slack < 0.05 {
            score -= (0.05 - slack) * 40.0 * (0.5 + progress * 0.5);
        }
    }
    // Next item cannot fit into the post residual: dead space penalty.
    if next > 0.0 && pr > 0.0 && (post_residual as u32) < next_item_size && post_norm > 0.03 {
        let dead_ratio = (next - pr) / cap;
        score += dead_ratio * 90.0 * (0.6 + progress * 0.6);
        if fitting_bins_count <= 2 {
            score += 18.0 * (1.0 - progress * 0.5);
        }
    }

    // ---- Relative-to-mean waste coupling ----
    if post_residual > 0 && mean_residual > 0.0 {
        let waste = post_norm - mean_residual / cap;
        if waste > 0.0 {
            score += waste * 30.0 * (0.4 + progress * 0.6);
        } else {
            score -= (-waste) * 10.0;
        }
    }

    // ---- New-bin candidate decision ----
    if bin_residual == bin_capacity {
        let size_pull = fit_ratio * 14.0;
        if fitting_bins_count <= 2 && gap > 0.0 {
            score -= (18.0 + size_pull) * (1.0 - progress * 0.6);
        } else if fitting_bins_count == 0 {
            score -= 5.0;
        } else {
            score += 20.0 + open_bins_count as f64 * (0.5 + 0.5 * progress);
        }
        if next > 0.0 && fitting_bins_count <= 3 && fit_ratio >= next / cap * 0.95 {
            score -= 5.5 * (1.0 - progress * 0.5);
        }
        if next > 0.0 && fit_ratio + next / cap > 1.0 {
            score += 8.0 * (1.0 - progress * 0.4);
        }
        if fit_ratio > 0.5 && progress < 0.5 {
            score -= 6.0 * (1.0 - progress);
        }
        if progress > 0.85 && fit_ratio > 0.6 {
            score -= 4.0 * (progress - 0.85) * 20.0;
        }
        if next > 0.0 && fit_ratio + next / cap <= 1.0 && fit_ratio > 0.35 {
            score -= 3.0 * (1.0 - progress);
        }
    }

    // Sharp bonus for leaving a tiny gap.
    if gap > 0.0 && gap < 0.12 {
        score -= (0.12 - gap) * 48.0;
    } else if gap >= 0.12 && gap < 0.22 && fitting_bins_count <= 3 {
        score += (gap - 0.12) * 18.0 * (0.5 + progress * 0.5);
    }
    if gap >= 0.22 && gap < 0.30 && fitting_bins_count <= 2 {
        score += (gap - 0.22) * 22.0 * (0.6 + progress * 0.4);
    }

    // Deep fill bonus relative to actual residual.
    let fill_r = item_size as f64 / bin_residual.max(1) as f64;
    if fill_r > 0.90 && bin_residual != bin_capacity {
        score -= (fill_r - 0.90) * 18.0 * (0.6 + progress * 0.5);
    }

    // Last-chance bonus: only one fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 - fit_ratio);
    }

    // Congestion: many competing bins -> penalize sloppy fits.
    if fitting_bins_count > 2 {
        score += gap * 6.5 * ((fitting_bins_count.min(12) as f64 - 2.0) / 10.0);
    }
    if open_bins_count > 8 {
        score += post_norm * 5.0 * ((open_bins_count.min(20) as f64 - 8.0) / 12.0);
    }

    // Late-stream consolidation.
    if progress > 0.7 && post_norm > 0.25 {
        score += (post_norm - 0.25) * 6.0 * (progress - 0.7) / 0.3;
    }

    // Near-closed residual with many options: strong preference.
    if post_residual > 0 && post_norm < 0.02 && fitting_bins_count >= 4 {
        score -= 6.0 * (1.0 - progress);
    }

    // Half-consumed bins late: discourage stranding tiny residuals.
    if pr > 0.0 && pr < item_size as f64 * 0.5 && progress > 0.3 {
        score += 4.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // later are penalized super-linearly. Items 1..=100 unknown distribution,
    // so treat gaps < ~25 as near-dead.
    let pr = post_residual as f64;
    if pr > 0.0 {
        if pr < 20.0 {
            score += (20.0 - pr) * (20.0 - pr) * 1.5; // quadratic dead-space penalty
        } else if pr < 35.0 {
            score += (35.0 - pr) * 0.8; // mildly wasteful zone
        }
    }

    // Reward tight fits (post residual near zero is excellent).
    if pr == 0.0 {
        score -= 40.0;
    } else if pr <= 5.0 {
        score -= 25.0;
    }

    // Last-chance pressure: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: discourage opening new bins when many bins are open;
    // encourage consolidation when few are open.
    let obp = open_bins_count as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportionally to open bins and stream progress.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 15.0 + obp * 2.0 + progress * 10.0;
        // If the next item would fit the residual left here, soften slightly.
        if next_item_size > 0 && (next_item_size as f64) <= pr {
            score -= 8.0;
        }
    } else {
        // Reward placing into existing bins, more so when many are open.
        score -= obp * 0.6;
    }

    // Prefer bins whose residual is close to the item (best-fit flavor),
    // and slightly favor bins below mean residual (tighter than average).
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += tightness * 0.15;
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    // Lookahead: if next item fits the post-residual exactly, big bonus.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 35.0;
    } else if next_item_size > 0 && (next_item_size as u32) <= post_residual {
        score -= 10.0;
    } else if next_item_size > 0 {
        // Next item won't fit in the gap -> gap is likely dead space.
        score += pr * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual == next_item_size is ideal.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        score -= 30.0 / (1.0 + diff);
        // Penalize dead space that cannot fit the next item.
        if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.6;
        }
    } else {
        // Last item: just minimize post_residual.
        score -= 10.0;
    }

    // Last-chance bonus: only bin that fits -> strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize mildly so we only open when open fits are bad,
    // but reward it if it can host the next item tightly too.
    if bin_residual == bin_capacity {
        score += 15.0;
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            let ndiff = ((bin_capacity - item_size) as i64 - next_item_size as i64).unsigned_abs() as f64;
            score -= 20.0 / (1.0 + ndiff);
        }
        // Near end of stream, avoid opening new bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    }

    // Prefer filling bins tighter than the mean residual.
    score += 0.3 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: squash post_residual so small leftovers dominate.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += fit_ratio * fit_ratio * 30.0;

    // Lookahead: if the next item fits into the leftover, strongly reward this bin.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0 + (next_item_size as f64 / bin_capacity as f64) * 10.0;
        } else if next_item_size <= bin_residual {
            // Next item fits only before placement — mild penalty for consuming space it could use.
            score += 4.0;
        }
    }

    // Last chance: if this is the only bin that can fit the item, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin when plenty of open bins can still absorb items.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let open_f = open_bins_count as f64;
        // New bins are expensive early; allow more liberally late when stream is nearly done.
        score += 35.0 - 15.0 * progress;
        // If mean residual is large, opening a new bin wastes existing capacity.
        score += mean_residual * 0.15;
        // Many open bins with room: discourage fragmentation.
        if open_f > 3.0 && mean_residual > item_size as f64 {
            score += 10.0;
        }
        // Small item into a fresh bin is wasteful.
        score += (bin_capacity - item_size.min(bin_capacity)) as f64 * 0.2;
    } else {
        // Reward using existing bins, more so when they are relatively full.
        let used_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
        score -= used_ratio * 8.0;
    }

    // Mild penalty for leaving residuals that are too small for the smallest possible item.
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let base = pr as f64;
    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 + 2.0 * progress) * cap;
    let mut score = base + 0.5 * poly;
    // Penalize very tight fits less as stream progresses (dead space matters more early)
    let tightness = 1.0 - norm_pr;
    score -= (1.0 - tightness) * (1.0 - progress) * 10.0;
    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 15.0;
    }
    // Lookahead: reward bins whose post-residual fits the next item
    if next_item_size > 0 && (post_residual as u64) >= (next_item_size as u64) {
        score -= 8.0;
    } else if next_item_size > 0 {
        score += 4.0;
    }
    // Mild penalty relative to mean residual spread
    score += 0.05 * (pr - mean_residual);
    // Slight preference for consolidating into fewer bins early
    score += 0.02 * open_bins_count as f64 * (1.0 - progress);
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo arithmetic on capacity fractions.
    // Residuals that are "harmonic" (multiples of common item sizes) are more reusable.
    let pr = post_residual;
    let harmony = if pr == 0 {
        -30.0 // perfect closure: best possible outcome
    } else {
        let mut h = 0.0;
        for m in [10u32, 20, 25, 50].iter() {
            if pr % m == 0 { h -= 6.0; }
        }
        // small dead space is bad: it wastes capacity with little reuse chance
        if pr < 10 { h += 25.0; }
        else if pr < 20 { h += 8.0; }
        h
    };
    score += harmony;

    // Coupling with lookahead: does next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // reward tight lookahead fit (small slack after next item)
            let post2 = pr - next_item_size;
            score -= 12.0 - (post2 as f64) * 0.15;
            if next_item_size == pr { score -= 10.0; }
        } else {
            // next item won't fit here: penalize proportionally to wasted lookahead
            let gap = (next_item_size - pr) as f64;
            score += gap * 0.12;
            // harmonic exception: if post_residual is a clean class, gap matters less
            if pr % 10 == 0 && pr > 0 { score -= 4.0; }
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin to avoid opening a new one.
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 1 {
        // among many candidates, prefer the tightest fit (post_residual already encodes this)
        score += 1.5 * (fitting_bins_count as f64).ln();
    }

    // Prefer filling bins that are already relatively empty vs. nearly full balance:
    // slight reward for reducing mean residual dispersion.
    let fill_frac = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score += (0.5 - fill_frac).abs() * 4.0;

    // New-bin candidate handling: opening a new bin is only attractive if no open bin
    // gives a good fit, or stream is early with many items to come.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut nb = 20.0; // base cost of opening a bin
        if fitting_bins_count == 0 { nb -= 30.0; } // no alternative
        if next_item_size > 0 && next_item_size >= item_size {
            nb -= 6.0; // roomy bin helps future large items
        }
        if progress < 0.3 { nb -= 5.0; } // early stream: fresh bins amortize
        score += nb.max(-35.0);
    }

    // Mild penalty for hoarding many open bins when mean residual is high.
    if open_bins_count > 3 && mean_residual > 30.0 {
        score += 1.0;
    }

    // Integer-division threshold nudges on post_residual classes.
    let class = pr / 10;
    match class {
        0 => score += 10.0,   // 0..9 unusable crumbs
        1 => score += 3.0,
        2 | 3 => score -= 2.0, // sweet spot: fits medium items
        4..=6 => score -= 1.0,
        _ => score += 0.0,
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are unusable small slivers are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // tiny sliver -> almost certainly wasted space
    } else if post_residual >= 10 && post_residual < 20 {
        score += 25.0; // small gap, rarely reusable given typical item sizes
    } else if post_residual == 0 {
        score -= 40.0; // perfect fit: strongly reward exact closure
    }

    // Reward bins whose residual closely matches the item (tight fit).
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += tightness * 30.0;

    // Last-chance pressure: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: only attractive when it enables a good pairing with the lookahead item,
    // otherwise penalize so existing bins are preferred.
    if bin_residual == bin_capacity {
        score += 20.0 + 0.5 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 45.0; // new bin can host both current and next item
        }
    } else {
        // If the next item fits into the post-residual of this bin, reward the placement.
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 15.0;
        } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            score += 10.0; // dead space relative to the known next demand
        }
    }

    // Open-bin pressure: when many bins are open, prefer consolidating into existing ones.
    score += (open_bins_count as f64).ln().max(0.0) * 4.0;

    // Slight drift: early in the stream be more willing to open bins, later be frugal.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * 5.0;

    // Prefer bins below the mean residual (fills emptier bins first to keep tight bins ready).
    score += (mean_residual - post_residual as f64) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 0.84;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect or near-perfect fits (low post residual).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 300.0;
    } else if post_residual <= 10 {
        score -= 120.0;
    }

    // Aggressive 2-step lookahead: if the next item exactly fills post_residual,
    // this is a chain fit — strongly favor it.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 800.0;
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= (100.0 - slack).max(0.0) * 1.5;
        } else {
            // Next item cannot fit in this bin's residual: mild penalty since
            // residual is likely dead space unless tiny.
            let over = (next_item_size - post_residual) as f64;
            score += over * 0.5;
        }
    }

    // Relative-to-mean-residual term: prefer bins whose residual after placement
    // deviates favorably from the mean residual of open bins.
    score += (post_residual as f64 - mean_residual) * 0.8;

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 500.0;
    }

    // Penalize opening a new bin when a reasonable fit exists in an open bin.
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline cost of consuming fresh capacity.
        score += 150.0;
        // But if the item is large relative to capacity and open bins are crowded,
        // a new bin is attractive.
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        if fill_ratio > 0.7 {
            score -= 200.0;
        }
        if open_bins_count == 0 {
            score -= 400.0;
        }
    }

    // Dead-space penalty: residual too small for the smallest plausible item (1..100
    // unknown distribution) — treat residual < 10 as waste.
    if post_residual > 0 && post_residual < 10 {
        score += 80.0;
    }

    // Late in the stream, consolidation matters more: penalize spreading across bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (post_residual as f64 / bin_capacity as f64) * 50.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let next = next_item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items.max(1) as f64 } else { 0.0 };
    let post_norm = pr / cap;
    let fit_ratio = item_size as f64 / cap;
    let gap = (bin_residual - item_size) as f64 / cap;
    let mut score = post_norm * post_norm * 50.0 + post_norm * 20.0;

    // ---- Strong exact / near-exact fit bonuses (borrowed from best) ----
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 42.0;
    } else if post_residual <= 9 {
        score -= 18.0 * (1.0 - progress * 0.4);
    }

    // Dead-floor sliver guard: tiny leftovers that almost nothing can refill.
    let dead_floor = if next_item_size > 0 { (next_item_size.min(12) as f64).max(6.0) } else { 10.0 };
    if post_residual > 0 && pr < dead_floor && pr != next {
        score += 62.0 * (1.0 - progress * 0.3);
    } else if post_residual > 0 && post_residual < 20 && pr != next {
        score += 25.0;
    }

    // ---- 2-step lookahead: shape score around the NEXT item ----
    if next > 0.0 {
        if pr == next {
            score -= 45.0;
        } else if pr > next {
            let slack = (pr - next) / cap;
            score -= (-slack * slack * 450.0).exp() * 24.0 * (1.0 - progress * 0.5);
            if slack < 0.05 {
                score -= (0.05 - slack) * 40.0 * (0.5 + progress * 0.5);
            } else if slack > 0.16 {
                score += (slack - 0.16) * 8.0 * (0.5 + progress);
            }
        } else if pr > 0.0 {
            let dead_ratio = (next - pr) / cap;
            if post_norm > 0.03 {
                score += dead_ratio * 90.0 * (0.6 + progress * 0.6);
            }
            if fitting_bins_count <= 2 {
                score += 18.0 * (1.0 - progress * 0.5);
            }
        }
    }

    // ---- Relative-to-mean coupling: penalize wastier-than-average bins ----
    if post_residual > 0 && mean_residual > 0.0 {
        let waste = (pr - mean_residual) / cap;
        if waste > 0.0 {
            score += waste * 30.0 * (0.4 + progress * 0.6);
        } else {
            score -= (-waste) * 10.0;
        }
    }

    // ---- New-bin candidate decision ----
    if bin_residual == bin_capacity {
        let size_pull = fit_ratio * 14.0;
        if fitting_bins_count <= 2 && gap > 0.0 {
            score -= (18.0 + size_pull) * (1.0 - progress * 0.6);
        } else if fitting_bins_count == 0 {
            score -= 5.0;
        } else {
            score += 20.0 + open_bins_count as f64 * (0.5 + 0.5 * progress);
        }
        if next > 0.0 && fitting_bins_count <= 3 && fit_ratio >= next * 0.95 {
            score -= 5.5 * (1.0 - progress * 0.5);
        }
        if next > 0.0 && fit_ratio + next > cap {
            score += 8.0 * (1.0 - progress * 0.4);
        }
        if fit_ratio > cap * 0.5 && progress < 0.5 {
            score -= 6.0 * (1.0 - progress);
        }
        if progress > 0.85 && fit_ratio > 0.6 {
            score -= 4.0 * (progress - 0.85) * 20.0;
        }
        if next > 0.0 && fit_ratio + next <= cap && fit_ratio > 0.35 {
            score -= 3.0 * (1.0 - progress);
        }
        if next > 0.0 && post_residual > 0 {
            let second_slack = (pr - next) / cap;
            if second_slack >= 0.0 && second_slack < 0.05 {
                score -= (0.05 - second_slack) * 40.0 * (0.5 + progress * 0.5);
            }
        }
        if post_residual > 0 && post_norm < 0.02 && fitting_bins_count >= 4 {
            score -= 6.0 * (1.0 - progress);
        }
    }

    // Sharp bonus for leaving a tiny gap (<12% of capacity).
    if gap > 0.0 && gap < 0.12 {
        score -= (0.12 - gap) * 48.0;
    } else if gap >= 0.12 && gap < 0.22 {
        if fitting_bins_count <= 3 {
            score += (gap - 0.12) * 18.0 * (0.5 + progress * 0.5);
        }
    } else if gap >= 0.22 && gap < 0.30 && fitting_bins_count <= 2 {
        score += (gap - 0.22) * 22.0 * (0.6 + progress * 0.4);
    }

    // Next-item chain: leftover after next item nearly closes bin.
    if next > 0.0 && gap > 0.12 {
        let nxt_gap = ((gap * cap - next).max(0.0)) / cap;
        if nxt_gap < 0.06 {
            score -= 9.0 * (1.0 - nxt_gap / 0.06) * (0.5 + progress);
        }
    }

    // Reward large items filling bins deeply.
    score -= fit_ratio * fit_ratio * 6.0;

    // Congestion: many competing bins, penalize sloppy fits.
    if fitting_bins_count > 2 {
        score += gap * 6.5 * ((fitting_bins_count.min(12) as f64 - 2.0) / 10.0);
    }
    if open_bins_count > 8 {
        score += post_norm * 5.0 * ((open_bins_count.min(20) as f64 - 8.0) / 12.0);
    }

    // Late-stream consolidation.
    if progress > 0.7 && post_norm > 0.25 {
        score += (post_norm - 0.25) * 6.0 * (progress - 0.7) / 0.3;
    }

    // Last-chance bonus: prefer a bin that would otherwise be wasted.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 - fit_ratio);
    }

    // Deep fill bonus relative to actual residual.
    let fill_r = item_size as f64 / bin_residual.max(1) as f64;
    if fill_r > 0.90 && bin_residual != bin_capacity {
        score -= (fill_r - 0.90) * 18.0 * (0.6 + progress * 0.5);
    }

    // Half-consumed bins late in the stream.
    if pr > 0.0 && pr < item_size as f64 * 0.5 && progress > 0.3 {
        score += 4.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Reward tight fits
    score -= 12.0 * (1.0 - post_residual as f64 / bin_capacity as f64).powi(3);

    // Penalize dead space that cannot fit the next item
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.6;
        } else {
            score -= 2.0;
        }
    } else {
        // Last item: reward any fit strongly
        score -= 10.0;
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Early stream: prefer opening/spreading bins; late stream: pack tightly
    score += t * 8.0 * (post_residual as f64 / bin_capacity as f64);
    score -= (1.0 - t) * 3.0 * (open_bins_count as f64).ln().max(0.0);

    // Penalize bins far from mean residual (fragmentation control)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Prefer using already-open bins over new bins
    if bin_residual == bin_capacity {
        score += 6.0 + 20.0 * t;
    } else {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = pr * (1.0 + 0.6 * progress * progress + 0.3 * progress * norm_pr);

    // Penalize large dead space quadratically, softened early in the stream
    score += 2.5 * norm_pr * norm_pr * (0.5 + 0.5 * progress) * cap;

    // Reward tight fits (small post_residual) more strongly as stream advances
    score -= (1.0 - norm_pr) * (1.0 - norm_pr) * (10.0 + 20.0 * progress);

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: reward leaving room for the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = pr - nxt;
        if gap >= 0.0 {
            score -= 5.0 * (1.0 - (gap / cap).abs());
        } else {
            score += 1.5 * (-gap / cap) * cap * 0.1;
        }
    }

    // Slight preference to consolidate into fewer bins
    score += 0.05 * open_bins_count as f64;

    // New-bin candidate: keep it neutral-to-slightly-high unless residuals are bad
    if bin_residual == bin_capacity {
        score = pr + 8.0 + 10.0 * progress + mean_residual * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 0.94;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-fit residual: treat residual modulo 10 bands
    // (capacity 100 => residual classes 0..9 in units of 10). Low-class residuals
    // (near 0) are "dead space" classes; reward them via a tightness bonus.
    let cls = (post_residual % 10) as f64;
    let decile = (post_residual / 10) as f64;

    // Tightness: reward small post_residual super-linearly.
    score -= (bin_capacity as f64 - post_residual as f64) * 0.35;

    // Perfect fit gets a huge reward.
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    } else if post_residual <= 10 {
        score -= 15.0;
    }

    // Dead-space penalty: residuals in (10, 25) are hard to fill with items >=10.
    if post_residual > 10 && post_residual < 25 {
        score += 25.0 + (25 - post_residual) as f64;
    }

    // Modulo coupling: if post_residual exactly matches next_item_size or a
    // small harmonic multiple, the next item can fill this bin exactly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 120.0;
        } else if post_residual >= next_item_size && post_residual - next_item_size <= 5 {
            score -= 50.0;
        } else if post_residual < next_item_size && post_residual > 0 {
            // Next item can't reuse this bin's leftover; penalize proportional to waste.
            score += 0.5 * (post_residual as f64);
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 80.0;
    }

    // New-bin candidate logic: opening a new bin should only win when the fit
    // into existing bins is poor (large post_residual) or bins are crowded.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin; high, so only chosen for bad fits.
        score += 60.0 + (open_bins_count as f64).sqrt() * 5.0;
        // If the current best possible fit would leave awkward residue, make
        // the new bin more attractive.
        if post_residual == bin_capacity {
            if next_item_size > 0 && next_item_size >= item_size {
                score -= 30.0;
            }
            if mean_residual < item_size as f64 * 1.2 {
                score -= 20.0;
            }
        }
    }

    // Mean-residual anchoring: prefer bins whose residual is near the mean
    // (keeps bin population balanced), penalize outliers.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    // Slight preference to fill older/more-full bins early in the stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * decile * 0.5;

    // Fraction-of-capacity harmonic: reward when item fills an exact fraction
    // (25%, 50%, 75%) of the bin residual.
    if item_size > 0 && bin_residual % item_size == 0 && bin_residual / item_size <= 4 {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps more than large ones.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 8.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Lookahead: reward residuals that can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += (next_item_size as f64 - post_residual as f64) * 0.5;
    }

    // Open-bin pressure: discourage spreading across many bins when a tight fit exists.
    score += open_bins_count as f64 * 0.8;

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when current residuals are large/wasteful.
    if bin_residual == bin_capacity {
        score += 25.0;
        if mean_residual < 15.0 {
            score -= 20.0;
        }
    }

    // Mild stream-progression tightening: waste less as stream advances.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let next = next_item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items.max(1) as f64 } else { 0.0 };
    let post_norm = pr / cap;
    let fit_ratio = item_size as f64 / cap;
    let gap = (bin_residual - item_size) as f64 / cap;
    let mut score = post_norm * post_norm * 54.0 + post_norm * 20.0;

    // ---- 2-step lookahead: shape score around the NEXT item ----
    if next > 0.0 {
        if pr == next {
            score -= 52.0;
        } else if pr > next {
            let slack = pr - next;
            let diff = slack / cap;
            score -= 20.0 * (1.0 - diff).max(0.0);
            score -= (-diff * diff * 470.0).exp() * 24.0 * (1.0 - progress * 0.5);
            if diff < 0.04 {
                score -= (0.04 - diff) * 28.0 * (0.6 + progress * 0.6);
            } else if diff > 0.16 {
                score += (diff - 0.16) * 8.0 * (0.5 + progress);
            }
        } else if pr > 0.0 {
            // dead space: post-residual too small for next item
            let dead_ratio = (next - pr) / cap;
            score += dead_ratio * 90.0 * (0.6 + progress * 0.6);
        }
    }

    // ---- Absolute dead-floor guard: tiny stranded remainders ----
    let dead_floor = if next_item_size > 0 { (next_item_size.min(12) as f64).max(6.0) } else { 10.0 };
    if post_residual > 0 && pr < dead_floor && pr != next {
        score += 64.0 * (1.0 - progress * 0.3);
    } else if post_residual > 0 && post_residual < 20 && pr != next {
        score += 25.0;
    }

    // ---- Relative-to-mean coupling: favor tighter-than-average bins ----
    if pr > 0.0 {
        let dev = (mean_residual - pr) / cap;
        if dev > 0.05 {
            score += (dev - 0.05) * 12.0 * (0.4 + progress);
        } else if dev < -0.08 {
            score += (-dev - 0.08) * 6.0 * (1.0 - progress);
        }
    }

    // ---- New-bin candidate decision ----
    if bin_residual == bin_capacity {
        let others = if fitting_bins_count > 0 { fitting_bins_count - 1 } else { 0 };
        let size_pull = fit_ratio * 14.0;
        if fitting_bins_count <= 2 && gap > 0.0 {
            score -= (18.0 + size_pull) * (1.0 - progress * 0.6);
        } else if others == 0 {
            score -= 5.0;
        } else {
            score += 20.0 + open_bins_count as f64 * (0.5 + 0.5 * progress);
        }
        if next > 0.0 && fitting_bins_count <= 3 && fit_ratio >= next * 0.95 / cap {
            score -= 5.5 * (1.0 - progress * 0.5);
        }
        if next > 0.0 && fitting_bins_count >= 1 && fit_ratio * cap + next > cap {
            score += 8.0 * (1.0 - progress * 0.4);
        }
        // Pairing bonus: prefer a fresh bin when item+next pair nearly fills it.
        if next > 0.0 && fit_ratio * cap + next <= cap {
            let pair_left = (cap - fit_ratio * cap - next) / cap;
            if pair_left < 0.05 {
                score -= (0.05 - pair_left) * 40.0 * (0.5 + progress * 0.5);
            } else if fit_ratio > 0.35 {
                score -= 3.0 * (1.0 - progress);
            }
        }
        if fit_ratio > 0.5 && progress < 0.5 {
            score -= 6.0 * (1.0 - progress);
        }
        if progress > 0.85 && fit_ratio > 0.6 {
            score -= 4.0 * (progress - 0.85) * 20.0;
        }
    }

    // Exact / near-exact fit bonuses.
    if pr == 0.0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 42.0;
    } else if post_residual <= 9 {
        score -= 18.0 * (1.0 - progress * 0.4);
    } else if post_norm < 0.02 && fitting_bins_count >= 4 {
        score -= 6.0 * (1.0 - progress);
    }

    // Sharp bonus for leaving a tiny gap (<12% of capacity).
    if gap > 0.0 && gap < 0.12 {
        score -= (0.12 - gap) * 48.0;
    } else if gap >= 0.12 && gap < 0.22 && next > 0.0 && pr > 0.0 && pr < next {
        score += (gap - 0.12) * 90.5 * (0.5 + progress);
    } else if gap >= 0.12 && gap < 0.22 && fitting_bins_count <= 3 {
        score += (gap - 0.12) * 18.0 * (0.5 + progress * 0.5);
    }
    if gap >= 0.22 && gap < 0.30 && fitting_bins_count <= 2 {
        score += (gap - 0.22) * 22.0 * (0.6 + progress * 0.4);
    }
    // Next-item chain: leftover after next item nearly closes bin.
    if next > 0.0 && gap > 0.12 {
        let nxt_gap = ((gap * cap - next).max(0.0)) / cap;
        if nxt_gap < 0.05 {
            score -= (0.05 - nxt_gap) * 40.0 * (0.5 + progress * 0.5);
        }
    }

    // Reward large items filling bins deeply.
    score -= fit_ratio * fit_ratio * 6.0;

    // Congestion: many competing bins => penalize sloppy fits.
    if fitting_bins_count > 2 {
        score += gap * 6.5 * ((fitting_bins_count.min(12) as f64 - 2.0) / 10.0);
    }
    if open_bins_count > 8 {
        score += post_norm * 5.0 * ((open_bins_count.min(20) as f64 - 8.0) / 12.0);
    }

    // Late-stream consolidation.
    if progress > 0.7 && post_norm > 0.25 {
        score += (post_norm - 0.25) * 6.0 * (progress - 0.7) / 0.3;
    }

    // Last-chance bonus: prefer a bin that would otherwise be wasted.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 - fit_ratio);
    }

    // Deep fill bonus.
    let fill_r = item_size as f64 / bin_residual.max(1) as f64;
    if fill_r > 0.90 && bin_residual != bin_capacity {
        score -= (fill_r - 0.90) * 18.0 * (0.6 + progress * 0.5);
    }

    // Waste-vs-mean term.
    if pr > 0.0 && mean_residual > 0.0 {
        let waste = post_norm - mean_residual / cap;
        if waste > 0.0 {
            score += waste * 30.0 * (0.4 + progress * 0.6);
        } else {
            score -= (-waste) * 10.0;
        }
    }

    // Penalize bins whose post-residual can never host the next item class.
    if pr > 0.0 && next > 0.0 && pr < next && post_norm > 0.03 {
        score += (next - pr) / cap * 20.0 * (0.5 + progress * 0.5);
    }

    // Reward bins that remain exactly reusable by the next item.
    if next > 0.0 && pr > 0.0 && (pr - next) / cap < 0.02 && pr >= next {
        score -= 6.0 * (1.0 - (pr - next) / cap / 0.02) * (0.5 + progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (non-linear).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * tightness * tightness;

    // Exact fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next_item_size.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += 1.2 * diff;
        if post_residual == next_item_size {
            score -= 45.0; // perfect chain placement
        } else if post_residual > next_item_size {
            // next item fits too: good chaining, better when leftover after chain is small
            let chain_residual = post_residual - next_item_size;
            score -= 15.0 * (1.0 - chain_residual as f64 / bin_capacity as f64);
        } else {
            // next item won't fit: penalize proportionally to wasted gap
            score += 0.8 * (next_item_size - post_residual) as f64;
        }
    }

    // Relative to mean residual: prefer bins that are already partially filled.
    score += 0.5 * (mean_residual - bin_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // Penalize opening a new bin when a reasonable fit exists in open bins.
    if bin_residual == bin_capacity {
        score += 30.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0; // a fresh bin still chains well
        }
        if fitting_bins_count == 0 {
            score -= 60.0; // no alternative: new bin is necessary
        }
    }

    // Late-stream pressure: consolidate more aggressively as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (1.0 - tightness);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
