pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream (0.0 .. 1.0)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Tightness of fit: reward small post_residual relative to item size
    let tightness = if item_size > 0 { post_residual as f64 / item_size as f64 } else { post_residual as f64 };
    score += 0.8 * tightness * (item_size as f64);

    // Lookahead: if the next item fits exactly in the post residual, strong reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0; // perfect chain: fill bin completely with next item
        } else if next_item_size <= post_residual {
            // next item fits, but leaves more dead space -> mild reward scaled by fill
            let chained_fill = next_item_size as f64 / post_residual as f64;
            score -= 12.0 * chained_fill;
        } else {
            // next item won't fit here; penalize bins whose residual is awkwardly large
            let gap = (next_item_size - post_residual) as f64;
            score += 0.15 * gap;
        }
    } else {
        // last item: strongly prefer zero residual
        score += 2.0 * post_residual as f64;
    }

    // Last-chance bin: if this is the only bin that can fit the item, favor it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a new bin wastes capacity elsewhere
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin
        let mut new_bin_penalty = 10.0;
        // If other bins can fit the item, opening a new bin is usually bad,
        // unless existing residuals are large (fragmented state) and item is big.
        if fitting_bins_count > 0 {
            let fragmentation = mean_residual / bin_capacity as f64;
            // If mean residual is small, open bins are tight -> new bin ok for big items
            if fragmentation < 0.35 && item_size >= 50 {
                new_bin_penalty -= 8.0;
            } else {
                new_bin_penalty += 20.0;
            }
        }
        // Late in the stream, avoid proliferating bins
        new_bin_penalty += 10.0 * progress;
        // Many open bins -> prefer consolidating
        new_bin_penalty += 0.5 * open_bins_count as f64;
        score += new_bin_penalty;
    } else {
        // Existing bin: reward using bins whose residual is below average (tight bins first)
        let resid_f = bin_residual as f64;
        if resid_f < mean_residual {
            score -= 0.5 * (mean_residual - resid_f);
        } else {
            score += 0.3 * (resid_f - mean_residual);
        }
        // Slight preference for bins that would become very tight
        if post_residual < 10 {
            score -= 8.0; // near-perfect fill
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;

    // Base: prefer tight fits, non-linear penalty on wasted space
    let mut score = pr as f64;
    score += 40.0 * norm_pr * norm_pr * (1.0 + progress);

    // Smooth coupling: tight fit more valuable as stream progresses
    score -= 30.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * progress * (1.0 + norm_item);

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * progress;
    }

    // Lookahead: reward bins whose post-residual can host next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr as u32 >= next_item_size {
            let slack = (pr - next_item_size as u32) as f64;
            score -= 12.0 * (1.0 - slack / cap) * (0.5 + progress);
        } else {
            score += 8.0 * (nxt / cap) * (1.0 - progress);
        }
    }

    // Penalize bins far from mean residual (fragmentation pressure), smoothed
    let dev = (pr - mean_residual) / cap;
    score += 10.0 * dev * dev;

    // Mild preference for consolidating into fewer bins late in stream
    score -= 5.0 * (1.0 - progress) * (open_bins_count as f64 / (open_bins_count as f64 + 5.0));

    // New-bin candidate: neutral-ish, penalize slightly unless current fit is terrible
    if bin_residual == bin_capacity {
        score += 15.0 * (1.0 - norm_item) - 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals that are "reusable"
    // classes (small or divisible by common item sizes), penalize dead zones.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap;

    // Class bonus: residuals that are multiples of 10 or 25 are more likely
    // to be exactly filled later.
    let class_bonus = if post_residual == 0 {
        -40.0 // perfect fill, best outcome
    } else if post_residual % 10 == 0 {
        -8.0
    } else if post_residual % 25 == 0 {
        -6.0
    } else if post_residual % 5 == 0 {
        -3.0
    } else {
        0.0
    };
    score += class_bonus;

    // Dead-space penalty: residuals too small for typical items (1..=100
    // unknown distribution, but tiny slivers are waste) unless zero.
    if post_residual > 0 && post_residual < 5 {
        score += 30.0;
    }

    // Integer-division threshold on post_residual: bucketize into quarters.
    let quarter = post_residual / 25;
    score += match quarter {
        0 => -5.0,          // 0..24: nearly full bin, good
        1 => 0.0,           // 25..49
        2 => 2.0,           // 50..74
        _ => 4.0,           // 75..99: leaves big gap, wasteful use of this bin
    };

    // Lookahead coupling: if next item fits exactly into post_residual,
    // strongly reward; if next item cannot fit, mildly penalize (chain break).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 15.0;
        } else if next_item_size < post_residual {
            let gap = (post_residual - next_item_size) as f64;
            score -= 6.0 * (1.0 - gap / cap);
        } else {
            score += 4.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new
    // bin unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 10.0 + 20.0 * (1.0 - frac);
    }

    // Prefer filling bins whose residual is below the mean (tight packing),
    // penalize using bins with above-mean residual early in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if (bin_residual as f64) < mean_residual {
        score -= 3.0 * (1.0 - progress);
    } else {
        score += 2.0 * (1.0 - progress);
    }

    // New-bin candidate: neutral-ish baseline; open a new bin only when the
    // item is large and would leave an awkward fit elsewhere.
    if bin_residual == bin_capacity {
        let big = item_size as f64 / cap;
        score = 55.0 - 25.0 * big;
        if next_item_size > 0 && next_item_size >= post_residual {
            score -= 10.0; // new bin can host the follow-up too
        }
    }

    // Modulo harmonic on item_size vs residual: exact complement classes.
    if (bin_residual - item_size) % item_size == 0 && item_size > 1 {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
