pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post;

    // Non-linear waste penalty: normalized residual, cubically coupled
    let post_norm = post / cap;
    score += 18.0 * post_norm * post_norm * post_norm;

    // Smooth interaction of residual with stream progress
    score += 10.0 * post_norm * progress;

    // Reward tight fits (small post_residual) more strongly late in stream
    score -= 12.0 * (1.0 - post_norm) * (1.0 - post_norm) * progress;

    // Penalize opening new bins, less so when few bins fit the item
    if bin_residual == bin_capacity {
        score += 60.0 + 25.0 * (1.0 - progress) - 8.0 * (fitting_bins_count as f64);
        // If next item could also use this fresh bin, slightly less penalty
        if next_item_size > 0 && next_item_size as f64 <= post {
            score -= 15.0;
        }
    }

    // Last-chance bonus: strongly prefer the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: reward leaving space usable by next item
    if next_item_size > 0 {
        if post as u32 >= next_item_size {
            score -= 10.0 * (1.0 - (post - next_item_size as f64) / cap);
        } else {
            score += 8.0 * (next_item_size as f64 - post) / cap;
        }
    }

    // Mild preference for bins with residuals near mean (balance)
    score += 0.05 * (post - mean_residual).abs();

    // Slight penalty for many open bins to encourage consolidation
    score += 0.5 * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
