pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover: post_residual mod small moduli
    let pr = post_residual as i64;
    let cap = bin_capacity as i64;

    // Penalize dead space that cannot fit the next item
    if next_item_size > 0 && (next_item_size as i64) > pr {
        score += (next_item_size as f64 - pr as f64) * 1.5;
    } else if next_item_size > 0 {
        score -= 8.0; // next item fits: excellent chaining
    }

    // Modulo-10 classes: leftovers that are multiples of 10 are "harmonic" with typical item sizes
    if pr > 0 && pr % 10 == 0 {
        score -= 6.0;
    }
    // Odd/awkward leftovers are hard to fill later
    if pr > 0 && pr % 2 == 1 {
        score += 3.0;
    }
    // Class of leftover in integer-division bands: tiny leftovers are near-perfect
    let band = pr / 10;
    score += match band {
        0 => -10.0,          // 0 leftover: perfect fit
        1 => -4.0,           // 1..=9: nearly perfect
        2 | 3 => 0.0,
        4 | 5 => 2.0,        // 40..=59: medium waste
        _ => 4.0,            // large waste
    } as f64;

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // New-bin candidate: only attractive when nothing fits well
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Prefer new bin when mean residual of open bins is fragmented
        score = cap as f64 * 0.5 + mean_residual * 0.6 - progress * 5.0;
        if next_item_size > 0 && (next_item_size as i64) <= cap {
            score -= 5.0;
        }
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
    }

    // Slight preference for bins whose residual is far from mean (complementary packing)
    score += ((bin_residual as f64 - mean_residual) * 0.05).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
