pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // later are heavily penalized (non-linearly).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 18.0;
    } else if post_residual >= 20 && post_residual < 35 {
        score += 6.0;
    } else {
        // Larger usable residuals are rewarded.
        score -= 4.0;
    }

    // Perfect fit is extremely attractive.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Pressure term: penalize spreading across many open bins so the
    // heuristic prefers filling existing bins before opening new ones.
    score += open_bins_count as f64 * 0.8;

    // Last-chance bin (only one bin fits the item): strongly favor it to
    // avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item would fit the post-residual, reward this
    // placement (good chaining); otherwise penalize leaving a gap that
    // neither the next item nor typical items can use.
    if next_item_size > 0 {
        if (post_residual as u32) >= next_item_size {
            score -= 10.0;
        } else {
            score += 5.0;
        }
    }

    // Slight preference for tighter-than-average bins.
    score -= (mean_residual - post_residual as f64) * 0.3;

    // New-bin candidate: make it moderately attractive only when existing
    // bins would create bad dead space (large item, tiny residuals around).
    if bin_residual == bin_capacity {
        let bad_gap = post_residual >= 1 && post_residual < 10;
        if bad_gap {
            score -= 20.0; // opening a fresh bin beats creating dead space
        } else {
            score += 15.0 + open_bins_count as f64 * 0.5; // prefer reusing bins
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when next item exactly fills leftover space.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect two-item completion
        } else if next_item_size <= post_residual {
            // next item fits: the smaller the gap after two placements, the better
            let two_step_gap = post_residual - next_item_size;
            score -= 25.0 * (1.0 - two_step_gap as f64 / bin_capacity as f64);
        } else {
            // next item cannot fit here: penalize proportional to leftover dead space
            let overshoot = next_item_size - post_residual;
            score += 10.0 + overshoot as f64 * 0.3;
        }
    }

    // Penalize small unusable residuals (dead space) nonlinearly
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Prefer tight fits: small post_residual relative to capacity
    score += 20.0 * (post_residual as f64 / bin_capacity as f64);

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Compare against mean residual: bins below mean residual are tighter, prefer them
    score += (mean_residual - bin_residual as f64) * 0.25;

    // New-bin candidate handling: only open a new bin if no open bin offers a decent fit
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score += 45.0;
        // more open bins -> opening another is costlier
        score += open_bins_count as f64 * 2.0;
        // early in stream, opening bins is cheaper (spread items)
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 20.0 * progress;
        // if next item is large and would waste this fresh bin, discourage slightly
        if next_item_size > 0 && next_item_size as f64 > 0.8 * bin_capacity as f64 {
            score -= 10.0;
        }
    } else {
        // existing bin: reward filling it well
        let fill_ratio = item_size as f64 / bin_residual as f64;
        score -= 15.0 * fill_ratio;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
