pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item fills most of the space.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fill_ratio * fill_ratio;

    // Penalize small leftover dead space that few future items can use.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when the item fits poorly everywhere
    // or the stream is early and we have few bins.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let poor_fit_elsewhere = fitting_bins_count <= 1 || fill_ratio < 0.5;
        if poor_fit_elsewhere {
            score -= 8.0 + 15.0 * (1.0 - progress);
        } else {
            score += 20.0 + 10.0 * progress;
        }
    }

    // Lookahead coupling: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size <= post_residual {
            let next_fit = next_item_size as f64 / post_residual.max(1) as f64;
            score -= 10.0 * next_fit;
        } else {
            // Next item cannot use this bin's leftover: mild penalty proportional to waste.
            score += 3.0 * (next_item_size as f64 - post_residual as f64).min(20.0) / 20.0;
        }
    }

    // Global state: prefer filling bins when many bins are open (contain sprawl),
    // but allow some slack when mean residual is high (lots of room overall).
    let open_pressure = open_bins_count as f64 / (total_items.max(1) as f64).sqrt();
    score += 5.0 * open_pressure * (1.0 - fill_ratio);

    // Mean-residual coupling: when average residual is low, every unit of leftover matters more.
    score += (post_residual as f64) * (mean_residual / bin_capacity as f64).clamp(0.2, 1.0) * 0.3;

    // Mild preference for keeping scores deterministic and bounded.
    score.clamp(-100.0, 200.0)
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let next = next_item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items.max(1) as f64 } else { 0.0 };
    let post_norm = pr / cap;
    let fit_ratio = item_size as f64 / cap;
    let gap = (bin_residual - item_size) as f64 / cap;
    let mut score = post_norm * post_norm * 54.0 + post_norm * 20.0;

    // ---- 2-step lookahead: shape score around the NEXT item ----
    if next > 0.0 {
        if pr == next {
            score -= 58.0;
        } else if pr > next {
            let slack = pr - next;
            let diff = slack / cap;
            score -= 22.0 * (1.0 - diff).max(0.0);
            score -= (-diff * diff * 500.0).exp() * 26.0 * (1.0 - progress * 0.5);
            if diff < 0.04 {
                score -= (0.04 - diff) * 34.0 * (0.6 + progress * 0.6);
            } else if diff > 0.16 {
                score += (diff - 0.16) * 9.0 * (0.5 + progress);
            }
        } else if pr > 0.0 {
            let dead_ratio = (next - pr) / cap;
            score += dead_ratio * 96.0 * (0.6 + progress * 0.6);
        }
    }

    // ---- Absolute dead-floor guard: tiny stranded remainders ----
    let dead_floor = if next_item_size > 0 { (next_item_size.min(12) as f64).max(6.0) } else { 10.0 };
    if post_residual > 0 && pr < dead_floor && pr != next {
        score += 68.0 * (1.0 - progress * 0.3);
    } else if post_residual > 0 && post_residual < 20 && pr != next {
        score += 25.0;
    }

    // ---- Relative-to-mean coupling ----
    if pr > 0.0 {
        let dev = (mean_residual - pr) / cap;
        if dev > 0.05 {
            score += (dev - 0.05) * 13.0 * (0.4 + progress);
        } else if dev < -0.08 {
            score += (-dev - 0.08) * 6.0 * (1.0 - progress);
        }
    }

    // ---- New-bin candidate decision ----
    if bin_residual == bin_capacity {
        let others = if fitting_bins_count > 0 { fitting_bins_count - 1 } else { 0 };
        let size_pull = fit_ratio * 14.0;
        if fitting_bins_count <= 2 && gap > 0.0 {
            score -= (18.0 + size_pull) * (1.0 - progress * 0.6);
        } else if others == 0 {
            score -= 5.0;
        } else {
            score += 20.0 + open_bins_count as f64 * (0.5 + 0.5 * progress);
        }
        if next > 0.0 && fitting_bins_count <= 3 && fit_ratio >= next * 0.95 / cap {
            score -= 5.5 * (1.0 - progress * 0.5);
        }
        if next > 0.0 && fitting_bins_count >= 1 && fit_ratio * cap + next > cap {
            score += 8.0 * (1.0 - progress * 0.4);
        }
        if next > 0.0 && fit_ratio * cap + next <= cap {
            let pair_left = (cap - fit_ratio * cap - next) / cap;
            if pair_left < 0.05 {
                score -= (0.05 - pair_left) * 46.0 * (0.5 + progress * 0.5);
            } else if fit_ratio > 0.35 {
                score -= 3.0 * (1.0 - progress);
            }
        }
        if fit_ratio > 0.5 && progress < 0.5 {
            score -= 6.0 * (1.0 - progress);
        }
        if progress > 0.85 && fit_ratio > 0.6 {
            score -= 4.0 * (progress - 0.85) * 20.0;
        }
        // New: avoid opening a bin whose leftover after this item can't host next either.
        if next > 0.0 && fit_ratio * cap + next > cap && fitting_bins_count > 2 {
            score += 4.0 * (1.0 - progress);
        }
    }

    // Exact / near-exact fit bonuses.
    if pr == 0.0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 44.0;
    } else if post_residual <= 9 {
        score -= 19.0 * (1.0 - progress * 0.4);
    } else if post_norm < 0.02 && fitting_bins_count >= 4 {
        score -= 6.0 * (1.0 - progress);
    }

    // Sharp bonus for leaving a tiny gap (<12% of capacity).
    if gap > 0.0 && gap < 0.12 {
        score -= (0.12 - gap) * 50.0;
    } else if gap >= 0.12 && gap < 0.22 && next > 0.0 && pr > 0.0 && pr < next {
        score += (gap - 0.12) * 92.0 * (0.5 + progress);
    } else if gap >= 0.12 && gap < 0.22 && fitting_bins_count <= 3 {
        score += (gap - 0.12) * 18.0 * (0.5 + progress * 0.5);
    }
    if gap >= 0.22 && gap < 0.30 && fitting_bins_count <= 2 {
        score += (gap - 0.22) * 22.0 * (0.6 + progress * 0.4);
    }
    // Next-item chain: leftover after next item nearly closes bin.
    if next > 0.0 && gap > 0.12 {
        let nxt_gap = ((gap * cap - next).max(0.0)) / cap;
        if nxt_gap < 0.05 {
            score -= (0.05 - nxt_gap) * 46.0 * (0.5 + progress * 0.5);
        }
    }

    // Reward large items filling bins deeply.
    score -= fit_ratio * fit_ratio * 6.0;

    // Congestion: many competing bins => penalize sloppy fits.
    if fitting_bins_count > 2 {
        score += gap * 6.5 * ((fitting_bins_count.min(12) as f64 - 2.0) / 10.0);
    }
    if open_bins_count > 8 {
        score += post_norm * 5.0 * ((open_bins_count.min(20) as f64 - 8.0) / 12.0);
    }

    // Late-stream consolidation.
    if progress > 0.7 && post_norm > 0.25 {
        score += (post_norm - 0.25) * 6.0 * (progress - 0.7) / 0.3;
    }

    // Last-chance bonus: prefer a bin that would otherwise be wasted.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 - fit_ratio);
    }

    // Deep fill bonus.
    let fill_r = item_size as f64 / bin_residual.max(1) as f64;
    if fill_r > 0.90 && bin_residual != bin_capacity {
        score -= (fill_r - 0.90) * 18.0 * (0.6 + progress * 0.5);
    }

    // Waste-vs-mean term.
    if pr > 0.0 && mean_residual > 0.0 {
        let waste = post_norm - mean_residual / cap;
        if waste > 0.0 {
            score += waste * 30.0 * (0.4 + progress * 0.6);
        } else {
            score -= (-waste) * 10.0;
        }
    }

    // Penalize bins whose post-residual can never host the next item class.
    if pr > 0.0 && next > 0.0 && pr < next && post_norm > 0.03 {
        score += (next - pr) / cap * 22.0 * (0.5 + progress * 0.5);
    }

    // Reward bins that remain exactly reusable by the next item.
    if next > 0.0 && pr > 0.0 && (pr - next) / cap < 0.02 && pr >= next {
        score -= 6.0 * (1.0 - (pr - next) / cap / 0.02) * (0.5 + progress);
    }

    // Periodic divisibility bonus — post-residual is a near-multiple of next item.
    if next > 0.0 && pr > 0.0 && pr >= next {
        let frac = ((pr - next) % next.max(1.0)) / next.max(1.0);
        if frac < 0.08 {
            score -= 11.0 * (1.0 - progress * 0.5);
        }
    }

    // Double-fit bonus — post-residual hosts the next item twice with little slack.
    if next > 0.0 && pr >= next * 2.0 && pr < next * 2.0 + 8.0 {
        score -= 9.0 * (1.0 - progress * 0.4);
    }

    // Last-chance micro-gap bonus.
    if fitting_bins_count == 1 && gap > 0.0 && gap < 0.06 {
        score -= 7.0 * (1.0 - progress * 0.5);
    }

    // Dead-space penalty when few fitting bins and residual too small for next.
    if next > 0.0 && post_residual > 0 && (post_residual as u32) < next_item_size && fitting_bins_count <= 2 {
        score += 18.0 * (1.0 - progress * 0.5);
    }

    // NEW: fine-grained residual shaping — reward post-residuals that form tight
    // arithmetic chains with the next item (post - next - next ≈ 0).
    if next > 0.0 && pr > 0.0 {
        let after2 = pr - next * 2.0;
        if after2 > 0.0 && after2 / cap < 0.03 {
            score -= (0.03 - after2 / cap) * 30.0 * (0.5 + progress * 0.5);
        }
    }

    // NEW: penalize mid-range stranded residuals (0.06–0.15 of capacity) that
    // rarely absorb future items — the main source of dead space.
    if pr > 0.0 && post_norm >= 0.06 && post_norm < 0.15 && next > 0.0 && pr < next * 1.5 {
        score += (0.15 - post_norm) * 14.0 * (0.6 + progress * 0.4);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress in [0,1]
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Smooth non-linear coupling: post_residual penalized more heavily late in the stream
    let tightness = (post_residual as f64 / bin_capacity as f64).powi(2);
    score += tightness * (1.0 + 3.0 * progress) * 20.0;

    // Reward tight fits (small post_residual) with a non-linear bonus
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= (fit_ratio * fit_ratio) * 15.0;

    // Lookahead coupling: if the next item fits the post-residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain_bonus = (next_item_size as f64 / (post_residual as f64 + 1.0)).powi(2);
        score -= 10.0 + 20.0 * chain_bonus * (1.0 - progress);
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Penalize leaving a dead gap that the next item cannot use
        score += (next_item_size as f64 - post_residual as f64).powi(2) / 50.0;
    }

    // Last-chance bin: strongly reward using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Prefer bins whose residual deviates favorably from the mean residual
    let dev = post_residual as f64 - mean_residual;
    score += (dev / bin_capacity as f64) * (1.0 + 2.0 * progress) * 5.0;

    // Mild pressure against proliferating bins when a good fit exists
    score += (open_bins_count as f64).ln() * (fit_ratio - 0.5).abs() * 2.0;

    // New-bin candidate: penalize opening a fresh bin unless existing fits are poor
    if bin_residual == bin_capacity {
        score += 30.0 + 20.0 * (1.0 - fit_ratio);
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    }

    score
}

