        2 => 10.0,                 // 20..29
        3 => 0.0,
        4 => -5.0,
        5 => -10.0,                // 50..59: sweet spot for mid items
        6 => -12.0,
        7 => -10.0,
        8 => -6.0,
        _ => -2.0,                 // near-full residual: fresh-ish bin
    };

    // Reward if next item fits exactly into post_residual (harmonic pairing)
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 300.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 30.0;
    } else if next_item_size > 0 {
        // post_residual cannot host next item: penalize proportionally
        score += (next_item_size - post_residual) as f64 * 0.5;
    }

    // Last-chance bin: strongly favor using it to avoid opening a bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: give it a neutral-ish score so it wins only when
    // open bins would create bad fits. Slight penalty to prefer existing bins.
    if bin_residual == bin_capacity {
        score = 55.0 + 10.0 * (1.0 - progress);
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 15.0; // opening fresh bin helps pair large items
        }
        if open_bins_count == 0 {
            score -= 500.0;
        }
    }

    // Prefer filling bins below mean residual (tighter bins first)
    score -= (mean_residual - post_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = 0.0;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10.0 - post_residual as f64) * 8.0;
    }
    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Open-bin pressure: when many bins are open, prefer consolidating into
    // existing bins rather than spreading items out.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * 6.0;

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: opening a fresh bin wastes the residual of
    // every other open bin; make it unattractive unless the current fit is bad.
    if bin_residual == bin_capacity {
        score += 30.0 + mean_residual * 0.5;
        // If the next item is large, a fresh bin may be valuable.
        if next_item_size > 0 && next_item_size > post_residual {
            score -= 10.0;
        }
    }

    // Prefer bins whose residual is close to the item (tight fit relative measure).
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += tightness * 20.0;

    // Favor bins whose residual is close to the mean residual (keep balance),
    // slightly less so early in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (bin_residual as f64 - mean_residual).abs() * (0.2 + 0.3 * progress);

    // Lookahead: if the next item fits exactly in the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 10 {
        score -= 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let next = next_item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items.max(1) as f64 } else { 0.0 };
    let post_norm = pr / cap;
    let fit_ratio = item_size as f64 / cap;
    let gap = (bin_residual - item_size) as f64 / cap;
    let mut score = post_norm * post_norm * 56.5 + post_norm * 21.8;

    // ---- Aggressive 2-step lookahead: shape score around the NEXT item ----
    if next > 0.0 {
        if pr == next {
            score -= 45.0;
        } else if pr > next {
            let slack = pr - next;
            let diff = slack / cap;
            score -= 20.0 * (1.0 - diff).max(0.0);
            score -= (-diff * diff * 458.0).exp() * 20.2 * (1.0 - progress * 0.5);
            if diff < 0.04 {
                score -= (0.04 - diff) * 26.0 * (0.6 + progress * 0.6);
            } else if diff > 0.16 {
                score += (diff - 0.16) * 8.0 * (0.5 + progress);
            }
        } else if pr > 0.0 {
            score += (next - pr) / cap * 30.5 * (1.0 - progress);
        }
    }

    // ---- Small-strand penalty calibrated to next item size (borrowed idea) ----
    let dead_floor = if next_item_size > 0 { (next_item_size.min(12) as f64).max(6.0) } else { 10.0 };
    if post_residual > 0 && pr < dead_floor && pr != next {
        score += 55.0 * (1.0 - progress * 0.3);
    } else if post_residual > 0 && post_residual < 20 && pr != next {
        score += 22.0;
    }

    // ---- Relative-to-mean coupling: favor tighter-than-average bins ----
    if pr > 0.0 {
        let dev = (mean_residual - pr) / cap;
        if dev > 0.05 {
            score += (dev - 0.05) * 12.0 * (0.4 + progress);
        } else if dev < -0.08 {
            score += (-dev - 0.08) * 6.0 * (1.0 - progress);
        }
    }

    // ---- New-bin candidate decision ----
    if bin_residual == bin_capacity {
        let others = if fitting_bins_count > 0 { fitting_bins_count - 1 } else { 0 };
        let size_pull = fit_ratio * 14.0;
        if fitting_bins_count <= 2 && gap > 0.0 {
            score -= (18.0 + size_pull) * (1.0 - progress * 0.6);
        } else if others == 0 {
            score -= 5.0;
        } else {
            score += 8.0 + 6.0 * (1.0 - progress);
        }
        if next > 0.0 && fitting_bins_count <= 3 && item_size as f64 >= next * 0.95 {
            score -= 5.5 * (1.0 - progress * 0.5);
        }
        if next > 0.0 && (item_size as f64) + next > cap {
            score += 8.0 * (1.0 - progress * 0.4);
        }
        if item_size as f64 > cap * 0.5 && progress < 0.5 {
            score -= 6.0 * (1.0 - progress);
        }
    }

    // Exact / near-exact fit bonuses (strengthened).
    if pr == 0.0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 30.0 * (1.0 - progress * 0.4);
    } else if post_norm < 0.05 {
        score -= 12.0 * (1.0 - post_norm / 0.05);
    }

    // Sharp bonus for leaving a tiny gap (<10% of capacity).
    if gap > 0.0 && gap < 0.10 {
        score -= (0.10 - gap) * 44.0;
    }
    // Mid-gap dead space: penalize if next item cannot consume the leftover.
    if gap > 0.10 && gap < 0.22 && next > 0.0 && pr > 0.0 && pr < next {
        score += (gap - 0.10) * 90.5 * (0.5 + progress);
    }
    if gap >= 0.22 && gap < 0.35 && progress > 0.55 {
        score += (gap - 0.22) * 45.5 * (progress - 0.55) * 2.0;
    }
    // Next-item chain: leftover after next item nearly closes bin.
    if next > 0.0 && gap > 0.12 {
        let nxt_gap = ((gap * cap - next).max(0.0)) / cap;
        if nxt_gap < 0.06 {
            score -= 9.0 * (1.0 - nxt_gap / 0.06) * (0.5 + progress);
        }
    }

    // Reward large items filling bins deeply.
    score -= fit_ratio * fit_ratio * 6.0;

    // Congestion: when many bins compete for this item, penalize sloppy fits.
    if fitting_bins_count > 2 {
        score += gap * 6.5 * ((fitting_bins_count.min(12) as f64 - 2.0) / 10.0);
    }
    if open_bins_count > 8 {
        score += post_norm * 5.0 * ((open_bins_count.min(20) as f64 - 8.0) / 12.0);
    }

    // Late-stream consolidation.
    if progress > 0.7 && post_norm > 0.25 {
        score += (post_norm - 0.25) * 6.0 * (progress - 0.7) / 0.3;
    }

    // Last-chance bonus: prefer a bin that would otherwise be wasted.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 - fit_ratio);
    }

    // Deep fill bonus relative to actual residual.
    let fill_r = item_size as f64 / bin_residual.max(1) as f64;
    if fill_r > 0.90 && bin_residual != bin_capacity {
        score -= (fill_r - 0.90) * 18.0 * (0.6 + progress * 0.5);
    }

    // Dead-space guard: stranded small gap after next item.
    if next > 0.0 && pr > 0.0 {
        let after_next = (pr - next).max(0.0);
        let dead = after_next / cap;
        if dead > 0.0 && dead < 0.08 {
            let reusable = if after_next >= next { 1.0 } else { 0.0 };
            score += (0.08 - dead) * 16.0 * (1.0 - reusable * 0.5) * (0.5 + progress);
        }
    }

    // Mid-residual band: leftover in 10-20% range that next item cannot fit.
    if pr > 0.0 && post_norm >= 0.10 && post_norm < 0.20 && next > 0.0 && next > pr {
        score += (next - pr) / cap * 26.0 * (0.4 + progress * 0.8);
    }

    // Half-consumed bins late in the stream.
    if pr > 0.0 && pr < item_size as f64 * 0.5 && progress > 0.3 {
        score += 4.0 * (1.0 - progress);
    }

    // Modular chain bonus: residual supports repeated next-item fits.
    if next > 0.0 && pr > 0.0 && pr >= next {
        let frac = ((pr - next) % next.max(1.0)) / next.max(1.0);
        if frac < 0.08 {
            score -= 10.0 * (1.0 - progress * 0.5);
        }
    }
    // Two-next-items bonus.
    if next > 0.0 && pr >= next * 2.0 && pr < next * 2.0 + 8.0 {
        score -= 8.0 * (1.0 - progress * 0.4);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong 2-step lookahead: reward exact match of post_residual with next item size
    if next_item_size > 0 {
        let match_gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 40.0 * (1.0 - match_gap / (bin_capacity as f64));
        // Perfect lookahead fit bonus
        if post_residual == next_item_size {
            score -= 60.0;
        }
        // Penalize leaving residual that neither fits next item nor is small
        if post_residual < next_item_size {
            score += 15.0;
        }
    } else {
        // Last item: prefer tightest fit
        score -= 30.0;
    }

    // Penalize large dead space relative to capacity
    let dead_frac = post_residual as f64 / bin_capacity as f64;
    score += 50.0 * dead_frac * dead_frac;

    // Reward bins tighter than mean residual (good packing), penalize loose ones
    score -= 10.0 * (mean_residual - post_residual as f64) / bin_capacity as f64;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: penalize opening a new bin unless it enables a great lookahead fit
    if bin_residual == bin_capacity {
        score += 25.0;
        if next_item_size > 0 && (item_size + next_item_size as u32) <= bin_capacity {
            score -= 55.0; // fresh bin can host item + next item together
        }
        // Late in stream, prefer reusing existing bins
        let progress = step_index as f64 / total_items as f64;
        score += 20.0 * progress;
    }

    // Mild penalty when many bins are open (consolidation pressure)
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
