pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: strong bonus when post_residual is small.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Lookahead: if the residual left after placement can still host the next
    // item, this bin is doubly valuable.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
        // Extra reward when the leftover exactly chains with the next item.
        let leftover_after_next = post_residual - next_item_size;
        if leftover_after_next < 10 {
            score -= 6.0;
        }
    } else if next_item_size > 0 {
        // Penalize leaving residuals that waste space relative to the lookahead.
        let waste = post_residual as f64 / next_item_size as f64;
        if waste > 0.0 && waste < 1.0 {
            score += 8.0 * (1.0 - waste);
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits, avoiding
    // opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Penalize scattering across many open bins when residuals are plentiful.
    let avg_pressure = mean_residual / bin_capacity as f64;
    score += 0.5 * open_bins_count as f64 * (1.0 - avg_pressure);

    // New-bin candidate: only attractive when no open bin fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty for opening a new bin, softened late in the stream
        // and when the item is large (large items are hard to place later).
        let progress = step_index as f64 / total_items.max(1) as f64;
        let large_item_bonus = (item_size as f64 / bin_capacity as f64) * 15.0;
        score += 25.0 - large_item_bonus - 8.0 * progress;
