pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: small remainders are "dead space".
    let class = post_residual / (bin_capacity / 4).max(1);
    score += class as f64 * 6.0;

    // Perfect-fit bonus: exact fill is ideal.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Harmonic pairing: does next item fit the leftover exactly or well?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 55.0;
        } else if next_item_size <= post_residual {
            score -= 12.0;
        } else {
            // next item cannot use this leftover: penalize proportionally
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.4;
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate handling: only open a new bin when all open fits are bad.
    if bin_residual == bin_capacity {
        let bad_fit = fitting_bins_count == 0
            || (next_item_size > 0 && post_residual > 0 && next_item_size > post_residual);
        if bad_fit {
            score -= 35.0;
        } else {
            score += 45.0; // keep using existing bins when they fit reasonably
        }
    }

    // Prefer tighter bins: closeness of fill to capacity.
    let fill = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= fill * 8.0;

    // Late in stream: consolidate more aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 5.0;

    // Mean residual context: if this bin is much tighter than average, favor it.
    score -= (mean_residual - post_residual as f64) * 0.3;

    score
}

