    score -= 20.0 * fill_ratio; // reward tight fits
    score += 10.0 * (post_residual as f64 / bin_capacity as f64); // waste pressure

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, discourage opening another.
    if bin_residual == bin_capacity {
        score += 15.0 + 6.0 * open_bins_count as f64;
        // But if no existing bin fits well, allow new bin.
        if fitting_bins_count == 0 {
            score -= 25.0;
        }
    } else {
        score -= 2.0 * open_bins_count as f64;
    }

    // Coupling with mean residual: prefer bins whose residual is below mean
    // (i.e., fuller bins), keeping emptier bins flexible.
    score += 0.5 * (mean_residual - bin_residual as f64).max(-50.0).min(50.0);

    // Lookahead: if the next item fits exactly in the post residual,
    // reward this placement (chaining fits).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0;
        if post_residual == next_item_size {
            score -= 10.0;
        }
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 5.0; // dead space relative to the upcoming item
    }

    // Late-stream consolidation: as the stream progresses, favor closing
    // out bins rather than spreading across many.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * fill_ratio;

    score
}

