pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual small relative to capacity
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Penalize dead space that no plausible future item can use
    if post_residual > 0 && post_residual < 10 {
        score -= 15.0; // nearly-full bin is great, item is "sealed"
    } else if post_residual < next_item_size as f64 && next_item_size > 0 {
        score += 8.0; // residual too small for lookahead item -> dead space risk
    } else if next_item_size > 0 && post_residual as f64 >= next_item_size as f64 {
        score -= 6.0; // leaves room for the next item: chain fit
    }

    // Exact-ish fit bonus
    if post_residual == 0 {
        score -= 60.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 2 {
        // many alternatives: be picky, penalize mediocre fits
        score += 0.15 * (fitting_bins_count as f64 - 2.0) * (post_residual as f64);
    }

    // New-bin candidate logic: only attractive when open bins fit poorly
    let is_new_bin = bin_residual == bin_capacity && item_size > 0;
    if is_new_bin {
        // base penalty so new bins are used only when needed
        score += 30.0;
        // more open bins with large mean residual -> discourage new bin
        score += 0.5 * open_bins_count as f64;
        score += 0.4 * (mean_residual - post_residual as f64).max(0.0);
        // early in stream, opening bins is cheaper (future has room to fill them)
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 20.0 * (1.0 - progress);
        // if item is large relative to capacity, new bin gives clean fit
        if item_size as f64 > 0.6 * bin_capacity as f64 {
            score -= 15.0;
        }
    } else {
        // existing bins: mild preference for bins with residual close to item
        let gap = (bin_residual as f64 - item_size as f64).abs();
        score += 0.1 * gap;
        // prefer filling bins whose residual is below mean (consolidate waste)
        if (bin_residual as f64) < mean_residual {
            score -= 4.0;
        }
    }

    // Late-stream urgency: close out bins, avoid spreading
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 10.0 * progress * (open_bins_count as f64 / (1.0 + mean_residual / 10.0)).min(10.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
