pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Smooth polynomial coupling of post_residual with stream progress
    let norm_pr = pr / cap;
    let poly = norm_pr * norm_pr * (1.0 - progress) - norm_pr * progress;
    score += 12.0 * poly * cap / 100.0;

    // Reward tight fits smoothly (quadratic in item fraction)
    let fill = item_size as f64 / cap;
    score -= 6.0 * fill * fill;

    // Last-chance bin bonus (smooth sigmoid-like on fitting_bins_count)
    let last_chance = 1.0 / (1.0 + (fitting_bins_count as f64 - 1.0).exp());
    score -= 8.0 * last_chance;

    // Lookahead: penalize residual too small for next item, reward exact match
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        let gap = (pr - ns) / cap;
        if gap < 0.0 {
            score += 5.0 * (-gap) * (1.0 - progress);
        } else {
            score -= 3.0 * gap * gap;
        }
    }

    // Mild pressure against proliferating bins late in the stream
    score += 0.5 * open_bins_count as f64 * progress / (total_items.max(1) as f64).sqrt();

    // Deviation from mean residual penalized smoothly
    score += 0.3 * (pr - mean_residual) * (pr - mean_residual) / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: perfect fits are golden.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Modulo arithmetic on post_residual: residuals that are multiples of
        // common small sizes (5, 10, 20, 25, 50) are more reusable.
        let pr = post_residual;
        let mut bonus = 0.0;
        if pr % 5 == 0 { bonus += 6.0; }
        if pr % 10 == 0 { bonus += 8.0; }
        if pr % 20 == 0 { bonus += 6.0; }
        if pr % 25 == 0 { bonus += 5.0; }
        if pr % 50 == 0 { bonus += 8.0; }
        score -= bonus;

        // Integer division thresholds: small leftovers are dead space.
        if pr <= 5 {
            score += 40.0;
        } else if pr <= 10 {
            score += 25.0;
        } else if pr <= 15 {
            score += 10.0;
        }

        // Lookahead coupling: reward residuals that can host next_item_size exactly.
        if next_item_size > 0 {
            if pr >= next_item_size {
                score -= 12.0;
                if pr == next_item_size { score -= 30.0; }
                if pr % next_item_size == 0 { score -= 10.0; }
            } else {
                // Residual cannot fit next item: penalize proportionally.
                score += (next_item_size - pr) as f64 * 0.3;
            }
        }
    }

    // Capacity fractions: bins that are already fairly full are good targets.
    let fill = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= fill * 8.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 18.0;
    } else if fitting_bins_count > 1 {
        // With alternatives, prefer tighter fits: relative slack penalty.
        score += (bin_residual - item_size) as f64 * 0.05 * (fitting_bins_count as f64).min(4.0);
    }

    // Late in the stream, consolidate aggressively; early, allow spreading.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (mean_residual - post_residual as f64).abs() * 0.1;
    score -= progress * 4.0;

    // New-bin candidate: only attractive when open bins would leave bad waste.
    if bin_residual == bin_capacity {
        let new_bin_score = bin_capacity as f64 - item_size as f64;
        // Base reluctance grows with number of open bins and mean residual.
        let reluctance = 14.0 + open_bins_count as f64 * 1.5 + mean_residual * 0.15;
        score = new_bin_score + reluctance;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
