pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress in [0,1]
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Smooth polynomial coupling of post_residual with progress
    let pr = post_residual as f64;
    let pr_norm = pr / bin_capacity as f64;

    // Early in the stream: prefer tight fits strongly (quadratic penalty on wasted space)
    // Late in the stream: relax slightly to keep bins balanced.
    let tightness = 1.0 + 1.5 * (1.0 - progress) * (1.0 - progress);
    score += tightness * pr_norm * pr_norm * bin_capacity as f64 * 0.5;

    // Cubic interaction: large post_residual is progressively worse as stream advances
    score += 0.3 * pr_norm * pr_norm * pr_norm * bin_capacity as f64 * (0.5 + progress);

    // Reward bins that leave room for the lookahead item (smooth cosine-free polynomial form)
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = (pr - nx).abs();
        let gap_norm = gap / bin_capacity as f64;
        // Penalize mismatch quadratically, scaled by remaining stream
        score += 8.0 * gap_norm * gap_norm * (1.0 + progress);
        // Reward exact-ish match with smooth falloff
        score -= 6.0 * (1.0 - gap_norm) * (1.0 - gap_norm) * (1.0 - gap_norm);
    }

    // Last-chance bin: strong smooth bonus so we don't open a new bin unnecessarily
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 + 0.5 * progress);
    }

    // Encourage filling bins when many are open (smooth saturation via polynomial)
    let open_norm = (open_bins_count as f64) / (open_bins_count as f64 + 4.0);
    score -= 5.0 * open_norm * pr_norm * pr_norm;

    // Balance against mean residual: prefer bins near the mean (quadratic divergence penalty)
    let dev = (pr - mean_residual) / bin_capacity as f64;
    score += 3.0 * dev * dev;

    // Slight reward for high fill ratio (small post_residual relative to capacity)
    score -= 2.0 * (1.0 - pr_norm) * (1.0 - pr_norm);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: harmonic class 0 — overwhelming reward.
    if post_residual == 0 {
        return -1000.0;
    }

    // Harmonic classing of dead space (decades of residual).
    // Larger dead-space classes are penalized super-linearly.
    let residual_class = (post_residual / 10) as f64;
    score += residual_class * residual_class * 0.5;

    // Fractional capacity coupling: bins whose residual is a small
    // fraction of capacity are "harmonically spent" — penalize lightly,
    // bins with large residual fractions keep flexibility.
    let frac = post_residual as f64 / bin_capacity as f64;
    score += (1.0 - frac) * 10.0;

    // Lookahead: if the next item cannot use this post-residual,
    // the leftover is likely permanent dead space.
    if next_item_size > 0 {
        if next_item_size > post_residual {
            score += 15.0 + (next_item_size - post_residual) as f64 * 0.4;
        } else {
            // Next item fits: reward closeness of the chained fit.
            score -= (post_residual - next_item_size) as f64 * 0.5;
            if post_residual == next_item_size {
                score -= 25.0; // chained perfect fit
            }
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a fresh bin when the fleet
    // already has usable residual mass.
    if bin_residual == bin_capacity {
        score += 20.0 + mean_residual * 0.3 + (open_bins_count as f64) * 1.5;
        // Early in the stream, allow new bins more freely.
        if total_items > 0 {
            let progress = step_index as f64 / total_items as f64;
            score -= progress * 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
