pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below the minimum item size (1..10 range
    // guard, but generally small gaps) are wasted capacity.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0; // unusable sliver
    }
    if post_residual == 0 {
        score -= 40.0; // perfect fit
    }

    // Tight-fit reward: fraction of bin used by this placement.
    let tightness = item_size as f64 / bin_capacity as f64;
    score -= 20.0 * tightness;

    // Penalize leaving a gap that exactly blocks typical mid-size items.
    if post_residual >= 10 && post_residual < 20 {
        score += 12.0;
    }

    // Open-bin pressure: discourage spreading across many bins unless the fit is good.
    score += (open_bins_count as f64) * 1.5;

    // Last-chance bin: strongly favor using the only bin that fits, avoiding a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: neutral-ish baseline; only chosen when open bins fit poorly.
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 * 0.6 + (open_bins_count as f64) * 2.0;
        // If no open bin fits, this is forced anyway; if next item is small, keep new bin.
        if next_item_size > 0 && next_item_size as f64 >= mean_residual {
            score -= 10.0;
        }
    }

    // Lookahead: if the next item fits exactly into the post-residual, reward heavily.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 35.0;
    } else if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 {
        score += 8.0; // next item can't use the leftover
    }

    // Mean residual coupling: prefer bins whose residual deviates favorably from mean.
    score -= (bin_residual as f64 - mean_residual) * 0.3;

    // Stream progression: slightly more conservative late in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fill is always best.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward residuals that exactly or nearly
    // match the next item's size, so the next item can also slot in.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post_residual as f64 - nxt).abs();
        if diff == 0.0 {
            score -= 600.0; // exact chain: next item fills this bin perfectly
        } else if post_residual >= next_item_size {
            score -= 250.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // post_residual smaller than next item: dead space unless tiny
            score += 40.0 + 0.5 * diff;
        }
    }

    // Reward tight fits relative to mean residual: bins with small residuals
    // that still fit the item are precious; use them.
    if (post_residual as f64) < mean_residual {
        score -= 30.0;
    } else {
        score += 0.3 * (post_residual as f64 - mean_residual);
    }

    // Last-chance bin: strongly favor using the only bin that fits,
    // otherwise we open a new bin and strand this residual.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 400.0;
    }

    // New-bin candidate: only attractive when no good open option exists
    // (item is large / residuals are fragmented).
    if bin_residual == bin_capacity {
        let openness = open_bins_count as f64;
        let large_item = item_size as f64 / bin_capacity as f64;
        let fragmentation = (mean_residual / bin_capacity as f64) * openness;
        score += 350.0 - 200.0 * large_item - 60.0 * fragmentation;
        // discourage opening new bins early in the stream
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 50.0 * (1.0 - progress);
        // if the next item also fits in a fresh bin alongside this one,
        // a new bin becomes more attractive
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 120.0;
        }
    }

    // Mild penalty for very wasteful placements (large leftover dead space
    // that no typical item can use).
    if post_residual > 0 && post_residual < 10 {
        score -= 80.0; // small unusable slivers are fine if item chain continues
    }
    if post_residual >= 10 && post_residual < item_size.min(20) {
        score += 20.0; // moderately wasteful
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
