    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 18.0 * fit_ratio * fit_ratio;

    // Penalize dead space: small post_residual is good, but zero waste is best.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual < 10 {
        score -= 8.0;
    } else {
        // Dead space penalty grows nonlinearly for large leftover gaps.
        score += 0.12 * post_residual as f64;
    }

    // Lookahead: reward if the next item can fit into the post residual.
    if next_item_size > 0 && next_item_size <= post_residual {
        let chain_quality = next_item_size as f64 / post_residual as f64;
        score -= 12.0 * chain_quality;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Penalize leaving a gap just smaller than the next item (worst case).
        if post_residual > 0 && next_item_size > post_residual && post_residual >= next_item_size.saturating_sub(10) {
            score += 10.0;
        }
    }

    // Last-chance bin: strongly prefer using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin is expensive early, cheaper late.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 - 20.0 * (1.0 - progress);
        // Don't open a new bin if some open bin fits it tightly.
        if fit_ratio > 0.6 && bin_residual != bin_capacity {
            score += 15.0;
        }
    }

    // Global state coupling: many open bins with high mean residual -> prefer reusing bins.
    if open_bins_count > 0 {
