        } else {
            // reward bins that can also fit the lookahead item
            score -= 4.0 * (1.0 - pr / cap) * (pr / cap);
        }
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 10.0;
    } else {
        score += 2.0 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // Mild pressure toward consolidating residuals when many bins are open
    score += 0.05 * (open_bins_count as f64) * (pr / cap);
    // Smooth mean-residual coupling
    score -= 0.02 * (mean_residual - pr);

    // New-bin candidate: only attractive early or when all fits are terrible
    let is_new = (bin_residual == bin_capacity) && (post_residual == bin_capacity);
    if is_new {
        score += 8.0 * (1.0 - t) + 15.0 * t * t;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let next = next_item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items.max(1) as f64 } else { 0.0 };
    let post_norm = pr / cap;
    let fit_ratio = item_size as f64 / cap;
    let gap = (bin_residual - item_size) as f64 / cap;
    let mut score = post_norm * post_norm * 52.0 + post_norm * 20.0;

    // ---- 2-step lookahead: shape score around the NEXT item ----
    if next > 0.0 {
        if pr == next {
            score -= 50.0;
        } else if pr > next {
            let slack = (pr - next) / cap;
            score -= 20.0 * (1.0 - slack).max(0.0);
            score -= (-slack * slack * 460.0).exp() * 24.0 * (1.0 - progress * 0.5);
            if slack < 0.04 {
                score -= (0.04 - slack) * 28.0 * (0.6 + progress * 0.6);
            } else if slack > 0.16 {
                score += (slack - 0.16) * 9.0 * (0.5 + progress);
            }
        } else if pr > 0.0 {
            let dead_ratio = (next - pr) / cap;
            score += dead_ratio * 88.0 * (0.6 + progress * 0.6);
        }
    }

    // Sliver guard: unusable tiny remainders (borrowed dead-floor idea).
    if post_residual > 0 {
        let dead_floor = if next > 0.0 { next.min(12.0).max(6.0) } else { 10.0 };
        if pr < dead_floor && pr != next {
            score += 55.0 * (1.0 - progress * 0.3);
        } else if post_residual < 20 && pr != next {
            score += 22.0;
        }
    }

    // ---- Relative-to-mean coupling: favor tighter-than-average bins ----
    if pr > 0.0 && mean_residual > 0.0 {
        let waste = post_norm - mean_residual / cap;
        if waste > 0.0 {
            score += waste * 30.0 * (0.4 + progress * 0.6);
        } else {
            score -= (-waste) * 10.0;
        }
    }

    // ---- New-bin candidate decision ----
    if bin_residual == bin_capacity {
        let others = if fitting_bins_count > 0 { fitting_bins_count - 1 } else { 0 };
        let size_pull = fit_ratio * 14.0;
        if fitting_bins_count <= 2 && gap > 0.0 {
            score -= (18.0 + size_pull) * (1.0 - progress * 0.6);
        } else if others == 0 {
            score -= 5.0;
        } else {
            score += 20.0 + open_bins_count as f64 * (0.5 + 0.5 * progress);
        }
        if next > 0.0 && fitting_bins_count <= 3 && item_size as f64 >= next * 0.95 {
            score -= 5.5 * (1.0 - progress * 0.5);
        }
        if next > 0.0 && item_size as f64 + next > cap {
            score += 8.0 * (1.0 - progress * 0.4);
        }
        if fit_ratio > 0.5 && progress < 0.5 {
            score -= 6.0 * (1.0 - progress);
        }
    }

    // Exact / near-exact fit bonuses.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 42.0;
    } else if post_residual <= 9 {
        score -= 18.0 * (1.0 - progress * 0.4);
    } else if post_norm < 0.05 {
        score -= 10.2 * (1.0 - post_norm / 0.05);
    }

    // Sharp bonus for leaving a tiny gap (<12% of capacity).
    if gap > 0.0 && gap < 0.12 {
        score -= (0.12 - gap) * 48.0;
        if fitting_bins_count == 1 {
            score -= 7.0 * (1.0 - progress * 0.5);
        }
    } else if gap >= 0.12 && gap < 0.22 {
        if next > 0.0 && pr > 0.0 && pr < next {
            score += (gap - 0.10) * 80.0 * (0.5 + progress);
        } else if fitting_bins_count <= 3 {
            score += (gap - 0.12) * 18.0 * (0.5 + progress * 0.5);
        }
    }
    if gap >= 0.22 && gap < 0.35 && fitting_bins_count <= 2 {
        score += (gap - 0.22) * 22.0 * (0.6 + progress * 0.4);
    }
    // Next-item chain: leftover after next item nearly closes bin.
    if next > 0.0 && gap > 0.12 {
        let nxt_gap = ((gap * cap - next).max(0.0)) / cap;
        if nxt_gap < 0.05 {
            score -= (0.05 - nxt_gap) * 40.0 * (0.5 + progress * 0.5);
        }
    }
    // Double-landing: pr fits next item twice almost exactly.
    if next > 0.0 && pr >= next * 2.0 && pr < next * 2.0 + 8.0 {
        score -= 9.0 * (1.0 - progress * 0.4);
    }

    // Reward large items filling bins deeply.
    score -= fit_ratio * fit_ratio * 6.0;

    // Congestion: many competing bins, penalize sloppy fits.
    if fitting_bins_count > 2 {
        score += gap * 6.5 * ((fitting_bins_count.min(12) as f64 - 2.0) / 10.0);
    }
    if open_bins_count > 8 {
        score += post_norm * 5.0 * ((open_bins_count.min(20) as f64 - 8.0) / 12.0);
    }

    // Late-stream consolidation of large residuals.
    if progress > 0.7 && post_norm > 0.25 {
        score += (post_norm - 0.25) * 6.0 * (progress - 0.7) / 0.3;
    }

    // Last-chance bonus: prefer a bin that would otherwise be wasted.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 - fit_ratio);
    }

    // Deep fill bonus relative to actual residual.
    let fill_r = item_size as f64 / bin_residual.max(1) as f64;
    if fill_r > 0.90 && bin_residual != bin_capacity {
        score -= (fill_r - 0.90) * 18.0 * (0.6 + progress * 0.5);
    }

    // Half-consumed bins late: residual smaller than half the item strands.
    if pr > 0.0 && pr < item_size as f64 * 0.5 && progress > 0.3 && pr != next {
        score += 4.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify leftover space by
    // capacity fractions and modular structure to detect "usable" leftovers.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Class A: post_residual divides capacity nicely (harmonic residual).
    // Leftovers that are exact divisors of capacity are more likely reusable.
    if post_residual > 0 {
        if bin_capacity % post_residual == 0 {
            score -= 12.0;
        }
        // Half / quarter / third fractions of capacity are prime reuse targets.
        let half = bin_capacity / 2;
        let third = bin_capacity / 3;
        let quarter = bin_capacity / 4;
        if post_residual == half { score -= 18.0; }
        else if post_residual == third { score -= 14.0; }
        else if post_residual == quarter { score -= 10.0; }
        // Modular classes: leftovers in low modulo bands pack better with
        // small items (sizes 1..100, many small items exist).
        let m = post_residual % 10;
        if m == 0 { score -= 6.0; }
        else if m <= 3 { score -= 3.0; }
        else if m >= 8 { score += 3.0; }
        // Integer division thresholds: very small dead space is bad.
        if post_residual <= bin_capacity / 10 {
            score += 20.0; // nearly-full bin, residual likely wasted
        } else if post_residual <= bin_capacity / 5 {
            score += 8.0;
        } else if post_residual >= bin_capacity / 2 {
            score -= 8.0; // roomy leftover, flexible
        }
    }

    // Lookahead coupling: if next item fits exactly into post_residual,
    // strongly reward (perfect chain); if next item barely misses, penalize.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            // harmonic fit quality: reward tight fits, penalize sloppy ones
            score -= 15.0 * (1.0 - slack / cap);
            if slack <= 5.0 { score -= 10.0; }
        } else {
            // next item won't fit here; leftover must survive another round
            score += 6.0 + (next_item_size - post_residual) as f64 / cap * 10.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new
    // bin unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 10.0;
        if post_residual <= bin_capacity / 10 {
            score -= 5.0; // filling a bin to near-exactness is great
        }
    }

    // New-bin candidate handling: an empty bin has huge residual; make its
    // score competitive but prefer using open bins with good harmonic fits.
    if bin_residual == bin_capacity {
        // base cost of opening a new bin, moderated by stream position and
        // how many bins are already open (consolidation pressure).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 0.5 * cap + 15.0 * (open_bins_count as f64).sqrt() - 20.0 * progress;
        // If the item is large, a fresh bin is attractive.
        if item_size as f64 > 0.6 * cap { score -= 25.0; }
        // If next item is small, keeping harmonic leftovers matters less.
        if next_item_size > 0 && next_item_size <= 10 { score += 5.0; }
    }

    // Mean-residual coupling: when open bins are collectively roomy,
    // prefer placements that consume the least-flexible bins.
    score -= (mean_residual - pr) * 0.3;

    // Tie-break: slightly prefer earlier (older) bins via open_bins_count.
    score += 0.01 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space penalty: residuals too small for any future item (min size 1..100,
    // but treat tiny gaps < 12 as dead weight) are heavily penalized.
    if post_residual > 0 && post_residual < 12 {
        score += 40.0 + (12 - post_residual) as f64 * 3.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Reward tight fits: post_residual small relative to item size.
    if item_size > 0 {
        score -= (item_size as f64) / (bin_residual.max(1) as f64) * 15.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading; favor filling existing ones.
    let open_pressure = open_bins_count as f64 / (total_items.max(1) as f64).sqrt();
    score += open_pressure * (post_residual as f64 / bin_capacity as f64) * 10.0;

    // New-bin candidate: only attractive when current bin fits are poor
    // (large post_residual relative to mean residual).
    if bin_residual == bin_capacity {
        let waste = post_residual as f64 - mean_residual;
        score += 20.0 + waste * 0.5;
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
        // Early stream: opening bins is cheaper.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= progress * 10.0;
    }

    // Lookahead: if next item fits into post_residual, reward this placement.
    if next_item_size > 0 && (post_residual as u64) >= (next_item_size as u64) {
        score -= 8.0;
    }
    // Penalize if next item would be blocked by a nearly-dead residual.
    if next_item_size > post_residual && post_residual > 0 && post_residual < next_item_size {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
