pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post residual exactly fits next item
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 50.0;
    }

    // Near match: next item fits into post residual (chaining)
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 10.0 + (post_residual - next_item_size) as f64 * 0.3;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // dead space relative to next item
        score += (next_item_size - post_residual) as f64 * 0.4;
    }

    // Prefer bins whose residual deviates below mean (tighter bins get used first)
    score -= (mean_residual - post_residual as f64) * 0.5;

    // Last chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless item is large
    if bin_residual == bin_capacity {
        score += 15.0 - 0.15 * item_size as f64;
    }

    // Mild pressure to consolidate when many bins are open
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let post_norm = pr / cap;
    let gap = (bin_residual as f64 - item_size as f64) / cap;

    // Core: quadratic dead-space cost (from best lineage), replacing linear base.
    let mut score = post_norm * post_norm * 50.0 + post_norm * 20.0;

    // Dead-space floor: residuals too small for the next item are waste.
    let dead_floor = if next_item_size > 0 { (next_item_size.min(12) as f64).max(6.0) } else { 10.0 };
    if post_residual > 0 && (post_residual as f64) < dead_floor {
        score += 62.0 * (1.0 - progress * 0.3);
    } else if post_residual < 20 {
        score += 25.0;
    }

    // Perfect / near-perfect fit rewards.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 42.0;
    } else if post_residual <= 9 {
        score -= 18.0 * (1.0 - progress * 0.4);
    }

    // Lookahead: next item fits the post residual with tight slack.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64 / cap;
        score -= (-slack * slack * 450.0).exp() * 24.0 * (1.0 - progress * 0.5);
    }

    // Tight-gap reward / awkward-gap penalty.
    if gap > 0.0 && gap < 0.12 {
        score -= (0.12 - gap) * 48.0;
    } else if gap >= 0.12 && gap < 0.22 && fitting_bins_count <= 3 {
        score += (gap - 0.12) * 18.0 * (0.5 + progress * 0.5);
    } else if gap >= 0.22 && gap < 0.30 && fitting_bins_count <= 2 {
        score += (gap - 0.22) * 22.0 * (0.6 + progress * 0.4);
    }

    // Post residual that can't hold the next item: penalize proportionally.
    if next_item_size > 0 && pr > 0.0 && (post_residual as u32) < next_item_size && post_norm > 0.03 {
        let dead_ratio = (next_item_size as f64 - pr) / cap;
        score += dead_ratio * 90.0 * (0.6 + progress * 0.6);
    }

    // Relative-waste coupling vs mean residual.
    if post_residual > 0 && mean_residual > 0.0 {
        let waste = post_norm - (mean_residual / cap);
        if waste > 0.0 {
            score += waste * 30.0 * (0.4 + progress * 0.6);
        } else {
            score -= (-waste) * 10.0;
        }
    }

    // Last-chance bin: strongly prefer sole fitting bin over a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0 * (1.0 - progress * 0.5);
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let size_pull = (item_size as f64 / cap) * 14.0;
        if fitting_bins_count <= 2 {
            // Few fitting bins: a fresh bin can be the right consolidation move.
            score -= (18.0 + size_pull) * (1.0 - progress * 0.6);
        } else {
            score += 20.0 + open_bins_count as f64 * (0.5 + 0.5 * progress);
        }
        if next_item_size > 0 && fitting_bins_count <= 3 && (item_size as f64) >= next_item_size as f64 * 0.95 {
            score -= 5.5 * (1.0 - progress * 0.5);
        }
        if next_item_size > 0 && fitting_bins_count >= 1 {
            let nxt = next_item_size as f64;
            if (item_size as f64) + nxt > cap {
                score += 8.0 * (1.0 - progress * 0.4);
            }
        }
        if (item_size as f64) > cap * 0.5 && progress < 0.5 {
            score -= 6.0 * (1.0 - progress);
        }
        if progress > 0.85 && (item_size as f64) / cap > 0.6 {
            score -= 4.0 * (progress - 0.85) * 20.0;
        }
        if next_item_size > 0 && (item_size as f64) + (next_item_size as f64) <= cap && (item_size as f64) / cap > 0.35 {
            score -= 3.0 * (1.0 - progress);
        }
    } else {
        // Reward using existing bins as stream progresses.
        score -= 10.0 * progress;
        if (bin_residual as f64) < mean_residual {
            score -= 5.0;
        }
    }

    // Pairing lookahead: post residual divisible by next item.
    if next_item_size > 0 && post_residual > 0 && (post_residual as u32) >= next_item_size {
        let nxt = next_item_size as f64;
        let frac = ((pr - nxt) % nxt.max(1.0)) / nxt.max(1.0);
        if frac < 0.08 {
            score -= 10.0 * (1.0 - progress * 0.5);
        }
    }

    // Two-of-next-item fit bonus.
    if post_residual > 0 && next_item_size > 0
        && (post_residual as f64) >= (next_item_size as f64) * 2.0
        && (post_residual as f64) < (next_item_size as f64) * 2.0 + 8.0
    {
        score -= 8.0 * (1.0 - progress * 0.4);
    }

    // Mild exploration coupling: item-size vs residual interaction.
    score += 0.05 * ((item_size as f64) - (bin_residual as f64)).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual relative to capacity).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 25.0 * tightness * tightness;

    // Reward near-perfect closure: zero residual is ideal.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 30.0;
    }

    // Penalize dead space that no plausible item (1..100) could use:
    // post_residual < 10 is unusable for standard min item, but tiny leftovers
    // are already rewarded; penalize mid-range waste instead.
    if post_residual >= 10 && post_residual <= 15 {
        score += 12.0; // awkward gap zone
    }

    // Lookahead coupling: favor bins whose post_residual matches next item.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        let match_bonus = 40.0 * (1.0 - gap / bin_capacity as f64).max(0.0);
        score -= match_bonus;
        // If next item fits exactly after placement, big reward.
        if next_item_size == post_residual {
            score -= 45.0;
        }
        // If next item cannot fit in this bin afterward anyway, mild penalty
        // for wasting a good bin on a bad pairing.
        if next_item_size > post_residual {
            score += 6.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new
    // bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0 + 0.15 * item_size as f64;
    }

    // New-bin candidate handling: opening a new bin is penalized, but less so
    // when the item is large (poor fit candidates elsewhere) or many bins are
    // already open and fragmented.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let fragmentation = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
        score += 55.0
            - 0.35 * item_size as f64
            + 10.0 * fragmentation.min(6.0)
            - 15.0 * progress;
        // Opening a new bin for a large item that leaves small residual is fine.
        if item_size >= 70 && post_residual <= 30 {
            score -= 25.0;
        }
    } else {
        // Prefer placing into bins whose residual is close to item size
        // (best-fit style) with a non-linear shaping.
        let slack = (bin_residual - item_size) as f64;
        score += 8.0 * (slack / bin_capacity as f64).sqrt();

        // Prefer using bins with below-mean residual (consolidate emptier
        // space? No — prefer filling bins that are already low to close them).
        let dev = bin_residual as f64 - mean_residual;
        score += 0.05 * dev;
    }

    // Mild time-horizon term: early in stream, be slightly conservative with
    // tight fits to keep flexibility; late, close bins aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * (1.0 - tightness);

    // Small penalty for many open bins to encourage consolidation.
    score += 0.4 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
