pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let p2 = progress * progress;
    let p3 = p2 * progress;

    // Base: post residual, with progress-dependent exponent-like shaping
    let mut score = pr * (0.9 + 0.4 * p2 + 0.3 * p3);

    // Smooth penalty for large residual when early (preserve space), reward tight fits later
    score += 25.0 * norm_pr * norm_pr * (1.0 - progress);
    score -= 20.0 * norm_pr * (1.0 - norm_pr) * (0.5 + progress);

    // Reward using nearly-full bins (small post residual) increasingly over time
    score -= (cap - pr) / cap * 10.0 * (0.3 + p2);

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 {
        score -= 15.0 + 20.0 * progress;
    }

    // Many fitting bins: mild penalty to prefer best-fit discrimination
    if fitting_bins_count > 2 {
        score += 2.0 * (fitting_bins_count as f64 - 2.0).min(5.0) * (1.0 - progress);
    }

    // Lookahead coupling: if next item fits post residual, reward; else penalize
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            score -= 8.0 * (1.0 - nxt / cap) * (0.5 + progress);
        } else {
            score += 6.0 * (nxt - pr) / cap;
        }
    }

    // Penalize bins far from mean residual (prefer homogeneity), smoothly
    score += 0.5 * (pr - mean_residual).abs() / cap;

    // New-bin candidate: keep it competitive only when current bins fit poorly
    if bin_residual == bin_capacity {
        score = 30.0 + 40.0 * norm_pr - 10.0 * progress;
        if fitting_bins_count <= 1 {
            score -= 25.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let next = next_item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items.max(1) as f64 } else { 0.0 };
    let post_norm = pr / cap;
    let fit_ratio = item_size as f64 / cap;
    let gap = (bin_residual - item_size) as f64 / cap;
    let mut score = post_norm * post_norm * 52.0 + post_norm * 20.0;

    // ---- 2-step lookahead: shape score around the NEXT item ----
    if next > 0.0 {
        if pr == next {
            score -= 54.0;
        } else if pr > next {
            let slack = pr - next;
            let diff = slack / cap;
            score -= 20.0 * (1.0 - diff).max(0.0);
            score -= (-diff * diff * 470.0).exp() * 24.0 * (1.0 - progress * 0.5);
            if diff < 0.04 {
                score -= (0.04 - diff) * 30.0 * (0.6 + progress * 0.6);
            } else if diff > 0.16 {
                score += (diff - 0.16) * 8.0 * (0.5 + progress);
            }
        } else if pr > 0.0 {
            let dead_ratio = (next - pr) / cap;
            score += dead_ratio * 92.0 * (0.6 + progress * 0.6);
        }
    }

    // ---- Absolute dead-floor guard: tiny stranded remainders ----
    let dead_floor = if next_item_size > 0 { (next_item_size.min(12) as f64).max(6.0) } else { 10.0 };
    if post_residual > 0 && pr < dead_floor && pr != next {
        score += 64.0 * (1.0 - progress * 0.3);
    } else if post_residual > 0 && post_residual < 20 && pr != next {
        score += 25.0;
    }

    // ---- Relative-to-mean coupling ----
    if pr > 0.0 {
        let dev = (mean_residual - pr) / cap;
        if dev > 0.05 {
            score += (dev - 0.05) * 12.0 * (0.4 + progress);
        } else if dev < -0.08 {
            score += (-dev - 0.08) * 6.0 * (1.0 - progress);
        }
    }

    // ---- New-bin candidate decision ----
    if bin_residual == bin_capacity {
        let others = if fitting_bins_count > 0 { fitting_bins_count - 1 } else { 0 };
        let size_pull = fit_ratio * 14.0;
        if fitting_bins_count <= 2 && gap > 0.0 {
            score -= (18.0 + size_pull) * (1.0 - progress * 0.6);
        } else if others == 0 {
            score -= 5.0;
        } else {
            score += 20.0 + open_bins_count as f64 * (0.5 + 0.5 * progress);
        }
        if next > 0.0 && fitting_bins_count <= 3 && fit_ratio >= next * 0.95 / cap {
            score -= 5.5 * (1.0 - progress * 0.5);
        }
        if next > 0.0 && fitting_bins_count >= 1 && fit_ratio * cap + next > cap {
            score += 8.0 * (1.0 - progress * 0.4);
        }
        if next > 0.0 && fit_ratio * cap + next <= cap {
            let pair_left = (cap - fit_ratio * cap - next) / cap;
            if pair_left < 0.05 {
                score -= (0.05 - pair_left) * 42.0 * (0.5 + progress * 0.5);
            } else if fit_ratio > 0.35 {
                score -= 3.0 * (1.0 - progress);
            }
        }
        if fit_ratio > 0.5 && progress < 0.5 {
            score -= 6.0 * (1.0 - progress);
        }
        if progress > 0.85 && fit_ratio > 0.6 {
            score -= 4.0 * (progress - 0.85) * 20.0;
        }
        // COMBINED: strong pair-closure pull — new bin is attractive only when
        // item+next nearly fill capacity, else lean toward existing bins harder.
        if next > 0.0 && fit_ratio * cap + next > cap * 0.94 && fitting_bins_count > 2 {
            score -= 6.0 * (1.0 - progress * 0.5);
        }
    }

    // Exact / near-exact fit bonuses.
    if pr == 0.0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 42.0;
    } else if post_residual <= 9 {
        score -= 18.0 * (1.0 - progress * 0.4);
    } else if post_norm < 0.02 && fitting_bins_count >= 4 {
        score -= 6.0 * (1.0 - progress);
    }

    // Sharp bonus for leaving a tiny gap (<12% of capacity).
    if gap > 0.0 && gap < 0.12 {
        score -= (0.12 - gap) * 48.0;
    } else if gap >= 0.12 && gap < 0.22 && next > 0.0 && pr > 0.0 && pr < next {
        score += (gap - 0.12) * 90.5 * (0.5 + progress);
    } else if gap >= 0.12 && gap < 0.22 && fitting_bins_count <= 3 {
        score += (gap - 0.12) * 18.0 * (0.5 + progress * 0.5);
    }
    if gap >= 0.22 && gap < 0.30 && fitting_bins_count <= 2 {
        score += (gap - 0.22) * 22.0 * (0.6 + progress * 0.4);
    }
    // Next-item chain: leftover after next item nearly closes bin.
    if next > 0.0 && gap > 0.12 {
        let nxt_gap = ((gap * cap - next).max(0.0)) / cap;
        if nxt_gap < 0.05 {
            score -= (0.05 - nxt_gap) * 42.0 * (0.5 + progress * 0.5);
        }
    }

    // Reward large items filling bins deeply.
    score -= fit_ratio * fit_ratio * 6.0;

    // Congestion: many competing bins => penalize sloppy fits.
    if fitting_bins_count > 2 {
        score += gap * 6.5 * ((fitting_bins_count.min(12) as f64 - 2.0) / 10.0);
    }
    if open_bins_count > 8 {
        score += post_norm * 5.0 * ((open_bins_count.min(20) as f64 - 8.0) / 12.0);
    }

    // Late-stream consolidation.
    if progress > 0.7 && post_norm > 0.25 {
        score += (post_norm - 0.25) * 6.0 * (progress - 0.7) / 0.3;
    }

    // Last-chance bonus: prefer a bin that would otherwise be wasted.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 - fit_ratio);
    }

    // Deep fill bonus.
    let fill_r = item_size as f64 / bin_residual.max(1) as f64;
    if fill_r > 0.90 && bin_residual != bin_capacity {
        score -= (fill_r - 0.90) * 18.0 * (0.6 + progress * 0.5);
    }

    // Waste-vs-mean term.
    if pr > 0.0 && mean_residual > 0.0 {
        let waste = post_norm - mean_residual / cap;
        if waste > 0.0 {
            score += waste * 30.0 * (0.4 + progress * 0.6);
        } else {
            score -= (-waste) * 10.0;
        }
    }

    // Penalize bins whose post-residual can never host the next item class.
    if pr > 0.0 && next > 0.0 && pr < next && post_norm > 0.03 {
        score += (next - pr) / cap * 20.0 * (0.5 + progress * 0.5);
    }

    // Reward bins that remain exactly reusable by the next item.
    if next > 0.0 && pr > 0.0 && (pr - next) / cap < 0.02 && pr >= next {
        score -= 6.0 * (1.0 - (pr - next) / cap / 0.02) * (0.5 + progress);
    }

    // Periodic divisibility bonus — post-residual is a near-multiple of next item.
    if next > 0.0 && pr > 0.0 && pr >= next {
        let frac = ((pr - next) % next.max(1.0)) / next.max(1.0);
        if frac < 0.08 {
            score -= 10.0 * (1.0 - progress * 0.5);
        }
    }

    // Double-fit bonus — post-residual hosts the next item twice with little slack.
    if next > 0.0 && pr >= next * 2.0 && pr < next * 2.0 + 8.0 {
        score -= 8.0 * (1.0 - progress * 0.4);
    }

    // Last-chance micro-gap bonus.
    if fitting_bins_count == 1 && gap > 0.0 && gap < 0.06 {
        score -= 7.0 * (1.0 - progress * 0.5);
    }

    // Dead-space penalty when few fitting bins and residual too small for next.
    if next > 0.0 && post_residual > 0 && (post_residual as u32) < next_item_size && fitting_bins_count <= 2 {
        score += 18.0 * (1.0 - progress * 0.5);
    }

    // COMBINED: chain-closure — residual after placing item can host next item
    // AND the remaining slack can host a small fraction of mean-sized items.
    if next > 0.0 && pr >= next && fitting_bins_count > 1 {
        let chain = pr - next;
        if chain < mean_residual.max(1.0) * 0.35 {
            score -= 5.0 * (1.0 - chain / (mean_residual.max(1.0) * 0.35)) * (0.5 + progress * 0.5);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Harmonic class of the leftover space: bins are grouped by capacity fraction.
    // Leftovers in the "dead zone" (0 < post_residual < 10) are nearly useless.
    let dead_zone_penalty = if post_residual > 0 && post_residual < 10 { 40.0 } else { 0.0 };

    // Modulo arithmetic on post_residual: leftovers that are multiples of common
    // item-size classes (10, 20, 25, 50) are reusable; odd scraps are not.
    let harmony = if post_residual % 50 == 0 {
        -12.0
    } else if post_residual % 25 == 0 {
        -8.0
    } else if post_residual % 10 == 0 {
        -5.0
    } else if post_residual % 5 == 0 {
        -2.0
    } else {
        3.0
    };

    // Integer-division thresholds: which harmonic class of future item could
    // still fit into the post residual?
    let fits_next = (next_item_size > 0 && next_item_size <= post_residual) as f64;
    let lookahead_bonus = -8.0 * fits_next
        - 4.0 * ((next_item_size > 0 && next_item_size <= post_residual / 2) as f64);

    // Perfect fit reward (harmonic class 0 of the capacity).
    let perfect = if post_residual == 0 { -25.0 } else { 0.0 };

    // Last-chance bin: strongly favor using the only bin that fits,
    // otherwise we pay for a fresh bin.
    let last_chance = if fitting_bins_count == 1 && bin_residual != bin_capacity {
        -15.0
    } else if fitting_bins_count == 0 && bin_residual != bin_capacity {
        20.0
    } else {
        0.0
    };

    // New-bin candidate: only attractive when the stream is early (many items
    // remain, worth investing in a fresh bin) and current fit is poor.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let is_new_bin = (bin_residual == bin_capacity) as f64;
    let new_bin_adjust = is_new_bin * (10.0 + 30.0 * (1.0 - progress) * (post_residual as f64 / cap));

    // Prefer bins whose residual is already small relative to the mean
    // (consolidation), penalize scattering into large-residual bins.
    let consolidation = 0.15 * (mean_residual - post);

    // Mild penalty for opening many bins late in the stream.
    let open_pressure = 0.05 * open_bins_count as f64 * is_new_bin;

    let mut score = post
        + dead_zone_penalty
        + harmony
        + lookahead_bonus
        + perfect
        + last_chance
        + new_bin_adjust
        + consolidation
        + open_pressure;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    let pr = post_residual as f64;
    if post_residual > 0 && post_residual <= 12 {
        // unusable gap for typical item sizes -> strong penalty
        score += (13.0 - pr) * 14.0;
    } else if post_residual > 12 && post_residual < 25 {
        // moderately awkward gap
        score += (25.0 - pr) * 3.0;
    }

    // Reward near-perfect fits (post_residual very small is good unless dead space).
    if post_residual == 0 {
        score -= 40.0; // perfect fill
    } else if post_residual <= 12 {
        // already penalized; add slight extra tightness reward
        score -= pr * 0.5;
    }

    // Lookahead coupling: if next item fits the post_residual, this placement is excellent.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 18.0;
        // extra reward for near-exact match with next item
        let slack = (post_residual - next_item_size) as f64;
        score -= (1.0 - slack / 20.0).max(0.0) * 10.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // post_residual too small for next item -> dead space penalty amplified
        score += 8.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bins pressure: discourage spreading when many bins are open;
    // encourage consolidation into mean-residual-deficient bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pressure = open_bins_count as f64 * (0.15 + 0.25 * progress);
    if bin_residual != bin_capacity {
        score += pressure * 0.5;
        // favor bins with residual below mean (denser bins)
        score += (mean_residual - bin_residual as f64) * 0.3;
    }

    // New-bin candidate handling: baseline cost of opening a bin, reduced early
    // in the stream or when no bin offers a decent fit.
    if bin_residual == bin_capacity {
        let decent_fit_exists = fitting_bins_count > 0
            && (bin_capacity as f64 - mean_residual) < 0.0 || fitting_bins_count == 0;
        let mut open_cost = 30.0 + 10.0 * progress;
        if fitting_bins_count == 0 {
            open_cost -= 25.0; // must open a bin
        } else if item_size as f64 > bin_residual as f64 * 0.9 {
            open_cost -= 15.0; // poor fit everywhere -> opening is fine
        }
        if next_item_size > 0 && next_item_size >= 90 {
            open_cost -= 10.0; // reserve current bins for huge next item
        }
        let _ = decent_fit_exists;
        score = open_cost + 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let next = next_item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items.max(1) as f64 } else { 0.0 };
    let post_norm = pr / cap;
    let fit_ratio = item_size as f64 / cap;
    let gap = (bin_residual - item_size) as f64 / cap;
    let mut score = post_norm * post_norm * 52.0 + post_norm * 21.0;

    // ---- 2-step lookahead: shape score around the NEXT item ----
    if next > 0.0 {
        if pr == next {
            score -= 50.0;
        } else if pr > next {
            let slack = pr - next;
            let diff = slack / cap;
            score -= 22.0 * (1.0 - diff).max(0.0);
            score -= (-diff * diff * 460.0).exp() * 24.0 * (1.0 - progress * 0.5);
            if diff < 0.04 {
                score -= (0.04 - diff) * 30.0 * (0.6 + progress * 0.6);
            } else if diff > 0.16 {
                score += (diff - 0.16) * 9.0 * (0.5 + progress);
            }
        } else if pr > 0.0 {
            let dead_ratio = (next - pr) / cap;
            score += dead_ratio * 88.0 * (0.6 + progress * 0.6);
        }
    }

    // Dead-floor: tiny unusable slivers are stranded capacity.
    let dead_floor = if next_item_size > 0 { (next_item_size.min(12) as f64).max(6.0) } else { 10.0 };
    if post_residual > 0 && pr < dead_floor && pr != next {
        score += 58.0 * (1.0 - progress * 0.3);
    } else if post_residual > 0 && post_residual < 20 && pr != next {
        score += 22.0;
    }

    // Exact / near-exact fit bonuses.
    if pr == 0.0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 42.0;
    } else if post_residual <= 9 {
        score -= 18.0 * (1.0 - progress * 0.4);
    } else if post_norm < 0.05 {
        score -= 10.0 * (1.0 - post_norm / 0.05);
    }

    // ---- Relative-to-mean coupling ----
    if pr > 0.0 && mean_residual > 0.0 {
        let waste = (pr - mean_residual) / cap;
        if waste > 0.0 {
            score += waste * 30.0 * (0.4 + progress * 0.6);
        } else {
            score -= (-waste) * 10.0;
        }
    }

    // ---- New-bin candidate decision ----
    if bin_residual == bin_capacity {
        let size_pull = fit_ratio * 14.0;
        if fitting_bins_count <= 2 && gap > 0.0 {
            score -= (18.0 + size_pull) * (1.0 - progress * 0.6);
        } else if fitting_bins_count == 0 {
            score -= 5.0;
        } else {
            score += 20.0 + open_bins_count as f64 * (0.5 + 0.5 * progress);
        }
        if next > 0.0 && fitting_bins_count <= 3 && item_size as f64 >= next * 0.95 {
            score -= 5.5 * (1.0 - progress * 0.5);
        }
        if next > 0.0 && item_size as f64 + next > cap {
            score += 8.0 * (1.0 - progress * 0.4);
        }
        if fit_ratio > 0.5 && progress < 0.5 {
            score -= 6.0 * (1.0 - progress);
        }
        if next > 0.0 && item_size as f64 + next <= cap && fit_ratio > 0.35 {
            score -= 3.0 * (1.0 - progress);
        }
    }

    // Sharp bonus for leaving a tiny gap.
    if gap > 0.0 && gap < 0.12 {
        score -= (0.12 - gap) * 48.0;
    } else if gap >= 0.12 && gap < 0.22 && fitting_bins_count <= 3 {
        score += (gap - 0.12) * 18.0 * (0.5 + progress * 0.5);
    }
    if gap >= 0.22 && gap < 0.30 && fitting_bins_count <= 2 {
        score += (gap - 0.22) * 22.0 * (0.6 + progress * 0.4);
    }

    // Next-item chain: leftover after next item nearly closes bin.
    if next > 0.0 && gap > 0.12 {
        let nxt_gap = ((gap * cap - next).max(0.0)) / cap;
        if nxt_gap < 0.06 {
            score -= 9.0 * (1.0 - nxt_gap / 0.06) * (0.5 + progress);
        }
    }

    // Reward large items filling bins deeply.
    score -= fit_ratio * fit_ratio * 6.0;

    // Congestion.
    if fitting_bins_count > 2 {
        score += gap * 6.5 * ((fitting_bins_count.min(12) as f64 - 2.0) / 10.0);
    }
    if open_bins_count > 8 {
        score += post_norm * 5.0 * ((open_bins_count.min(20) as f64 - 8.0) / 12.0);
    }

    // Late-stream consolidation.
    if progress > 0.7 && post_norm > 0.25 {
        score += (post_norm - 0.25) * 6.0 * (progress - 0.7) / 0.3;
    }

    // Last-chance bonus.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 - fit_ratio);
    }

    // Deep fill bonus.
    let fill_r = item_size as f64 / bin_residual.max(1) as f64;
    if fill_r > 0.90 && bin_residual != bin_capacity {
        score -= (fill_r - 0.90) * 18.0 * (0.6 + progress * 0.5);
    }

    // Dead-space guard after next item.
    if next > 0.0 && pr > 0.0 {
        let after_next = (pr - next).max(0.0);
        let dead = after_next / cap;
        if dead > 0.0 && dead < 0.08 {
            let reusable = if after_next >= next { 1.0 } else { 0.0 };
            score += (0.08 - dead) * 16.0 * (1.0 - reusable * 0.5) * (0.5 + progress);
        }
        // Multi-fit divisibility bonus.
        if pr >= next {
            let frac = ((pr - next) % next.max(1.0)) / next.max(1.0);
            if frac < 0.08 {
                score -= 10.0 * (1.0 - progress * 0.5);
            }
        }
        if pr >= next * 2.0 && pr < next * 2.0 + 8.0 {
            score -= 8.0 * (1.0 - progress * 0.4);
        }
    }

    // Mid-residual strand band.
    if pr > 0.0 && post_norm >= 0.10 && post_norm < 0.20 && next > 0.0 && next > pr {
        score += (next - pr) / cap * 26.0 * (0.4 + progress * 0.8);
    }

    // Half-consumed bins late in the stream.
    if pr > 0.0 && pr < item_size as f64 * 0.5 && progress > 0.3 {
        score += 4.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual equals next item size -> huge reward
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }
    // Post residual can fit next item: reward proportionally to how well
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 50.0 + 25.0 * (post_residual as f64 / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Next item won't fit in the leftover: penalize dead space
        score += 30.0 + 0.5 * (post_residual as f64);
    }

    // Tight fit reward relative to bin capacity
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 20.0 * tightness;

    // Relative to mean residual: leaving less than average is good
    score -= 10.0 * (mean_residual - post_residual as f64) / bin_capacity as f64;

    // Last chance bin: strong reward to use it
