    // Penalize opening a new bin unless nothing else fits well
    if bin_residual == bin_capacity {
        score += 40.0;
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 500.0;
        }
    }

    // Late in stream: prefer packing into existing bins
    let progress = step_index as f64 / total_items as f64;
    score += 30.0 * progress * (bin_residual == bin_capacity) as i32 as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
