        score -= 8.0 * (1.0 - progress * 0.4);
    }

    // Last-chance micro-gap bonus.
    if fitting_bins_count == 1 && gap > 0.0 && gap < 0.06 {
        score -= 7.0 * (1.0 - progress * 0.5);
    }

    // Dead-space penalty when few fitting bins and residual too small for next.
    if next > 0.0 && post_residual > 0 && (post_residual as u32) < next_item_size && fitting_bins_count <= 2 {
        score += 18.0 * (1.0 - progress * 0.5);
    }

    // Chain-closure — residual after placing item can host next item with tiny slack.
    if next > 0.0 && pr >= next && fitting_bins_count > 1 {
        let chain = pr - next;
        if chain < mean_residual.max(1.0) * 0.35 {
            score -= 5.0 * (1.0 - chain / (mean_residual.max(1.0) * 0.35)) * (0.5 + progress * 0.5);
        }
    }

    // NEW: triple-chain anticipation — residual after next item can still host a
    // mean-sized sliver, reducing dead space two steps ahead.
    if next > 0.0 && pr >= next && mean_residual > 1.0 {
        let chain2 = pr - next;
        if chain2 >= mean_residual && (chain2 - mean_residual) / cap < 0.03 {
            score -= (0.03 - (chain2 - mean_residual) / cap) * 30.0 * (0.5 + progress * 0.5);
        }
    }

    // NEW: cap-aware harmony — reward when item exactly splits residual in half
    // (both halves remain usable for mid-sized items).
    if bin_residual > 0 {
        let half = bin_residual as f64 / 2.0;
        let dev_half = (item_size as f64 - half).abs() / cap;
        if dev_half < 0.02 && bin_residual != bin_capacity {
            score -= (0.02 - dev_half) * 22.0 * (0.6 + progress * 0.4);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 1.17;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strongest reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: bins whose residual belongs to a
    // "friendly" class (divisible into common small item sizes) are preferred.
    let pr = post_residual;
    let class_bonus: f64 = if pr == 0 {
        0.0
    } else if pr % 50 == 0 {
        -60.0 // residual 50 leaves room for half-capacity items
    } else if pr % 25 == 0 {
        -40.0
    } else if pr % 20 == 0 {
        -35.0
    } else if pr % 10 == 0 {
        -30.0
    } else if pr % 5 == 0 {
        -15.0
    } else if pr < 10 {
        40.0 // tiny dead space: penalize strongly
    } else {
        0.0
    };
    score += class_bonus;

    // Dead-space penalty: residual too small for the minimum plausible item.
    if pr > 0 && pr < 10 {
        score += 80.0;
    }

    // Lookahead coupling: reward residuals that can host the next item exactly,
    // penalize residuals that can host it but leave a bad remainder.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 200.0; // next item closes this bin perfectly
        } else if next_item_size < pr {
            let rem = pr - next_item_size;
            if rem % 10 == 0 {
                score -= 50.0;
            } else if rem < 10 {
                score += 25.0;
            }
        }
        // If next item is large relative to capacity, prefer keeping big
        // residuals free for it.
        if next_item_size >= bin_capacity / 2 && pr >= next_item_size {
            score -= 30.0;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive when
    // the item is large and no open bin fits well.
    if bin_residual == bin_capacity {
        // Base offset so a new bin is worse than any reasonable fit...
        score += 55.0 + mean_residual * 0.15;
        // ...but attractive when item nearly fills a bin (good fresh fit) or
        // when existing bins would leave huge fragmentation.
        let frac = item_size as f64 / bin_capacity as f64;
        if frac > 0.85 {
            score -= 90.0;
        }
        if mean_residual < item_size as f64 {
            score -= 45.0;
        }
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
    }

    // Tightness reward: prefer filling bins that are already mostly full.
    let tightness = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= 25.0 * tightness * tightness;

    // Mild consolidation pressure as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (1.0 - tightness);

    // Slight penalty when many bins are open: encourage closing bins.
    score += open_bins_count as f64 * 0.5 * (1.0 - tightness);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 1.03;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals that are too small for any future item (min size 1..100 unknown,
    // assume items >= 10 typical; small gaps < 12 are near-useless) are heavily penalized.
    if post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 35.0;
    } else if post_residual < 30 {
        score += 12.0;
    }

    // Reward tight fits (post_residual small relative to bin capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 25.0 * tightness * tightness;

    // Last-chance bin: strongly favor using the only bin that fits to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: discourage scattering into many bins when plenty of alternatives fit.
    if fitting_bins_count > 1 && bin_residual != bin_capacity {
        score += 3.0 * (fitting_bins_count as f64 - 1.0).sqrt();
    }

    // Prefer bins with below-mean residual (more filled bins) to consolidate.
    score += 0.4 * (mean_residual - bin_residual as f64);

    // Lookahead coupling: if the next item fits exactly in the post_residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 40.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 8.0;
    }

    // New-bin candidate handling: neutral-ish score that decays with stream progress;
    // early on allow opening bins, later force consolidation into existing bins.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 45.0 + 55.0 * progress + 2.0 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 0.81;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when post_residual exactly matches next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else {
            let gap = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
            score += gap * 0.8;
            // penalize post_residual smaller than next item (dead space relative to lookahead)
            if (post_residual as u32) < next_item_size {
                score += (next_item_size - post_residual) as f64 * 1.5;
            }
        }
    }

    // Deviation from mean residual: prefer bins that tighten spread
    let dev = post_residual as f64 - mean_residual;
    score += dev * 0.3 + (dev * dev) * 0.01;

    // Last-chance bin: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate: penalize opening a new bin, more so if other bins fit
    if bin_residual == bin_capacity {
        score += 200.0 + 50.0 * open_bins_count as f64;
        if fitting_bins_count > 0 {
            score += 100.0;
        }
        // allow opening new bin if lookahead fits poorly elsewhere
        if next_item_size > 0 && post_residual >= item_size + next_item_size.min(bin_capacity - item_size) {
            score -= 150.0;
        }
    }

    // Late-stream tightening: reduce waste more aggressively toward the end
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 1.04;
