}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fits are excellent: reward small post_residual non-linearly.
    if post_residual == 0 {
        score -= 40.0;
    } else {
        let pr = post_residual as f64;
        score += (pr / bin_capacity as f64) * 15.0;
        // Penalize residuals that are unusably small (dead space) for typical items.
        if post_residual < 10 {
            score += 12.0;
        } else if post_residual < 25 {
            score += (25.0 - pr) * 0.35;
        }
    }

    // Exact-fill of residual: perfect packing.
    if post_residual == 0 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // Lookahead coupling: if next item fits in the post-residual, reward;
    // if post-residual is smaller than next item but next fits nowhere else, mild penalty.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if (next_item_size as u32) <= post_residual {
            score -= 10.0 * (1.0 - nx / bin_capacity as f64);
        } else {
            let waste = (next_item_size as u32).saturating_sub(post_residual);
            score += waste as f64 * 0.08;
        }
    }

    // Global state: prefer filling bins when many bins are open (consolidation pressure).
    let open_pressure = (open_bins_count as f64).ln().max(0.0);
    score -= open_pressure * (bin_residual as f64 / bin_capacity as f64) * 4.0;

    // Mean residual deviation: bins far from the mean residual are less attractive
    // unless they fit tightly (keeps a diversified residual pool).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    // Time horizon: early in the stream, be pickier (prefer tight fits, keep space);
    // late in the stream, just close bins out aggressively.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= t * 6.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    score += (1.0 - t) * 2.0;

    // New-bin candidate: only attractive when current bins fit poorly.
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count == 0 { 0.0 } else {
            (fitting_bins_count as f64).recip()
        };
        score = bin_capacity as f64 * 0.55 + desperation * 30.0 - t * 10.0;
        if next_item_size > 0 && next_item_size as u32 <= bin_capacity {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = 0.0;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Base: penalize post_residual, but with non-linear (quadratic) shaping.
    let pr_norm = pr / cap;
    let mut score = pr * (1.0 + 0.8 * pr_norm * pr_norm);

    // Smooth progress coupling: late in the stream, waste is more costly.
    score *= 1.0 + 0.6 * progress * pr_norm;

    // Reward tight fits: subtract a smooth bonus when post_residual is small.
    score -= 30.0 * (1.0 - pr_norm).powf(3.0);

    // Lookahead: if next item fits into post_residual, reward this bin.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 15.0 * (pr - next_item_size as f64) / cap;
    } else if next_item_size > 0 {
        // Next item can't follow here: slight penalty scaled by mismatch.
        score += 5.0 * (next_item_size as f64 - pr) / cap;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Mean residual context: bins deviating below mean residual are tighter; reward them.
    score -= 4.0 * (mean_residual - pr) / cap;

    // New-bin candidate: make it mildly unattractive early, more acceptable late
    // or when few bins fit the item.
    if bin_residual == bin_capacity {
        score += 25.0 * (1.0 - progress) + 10.0 * (fitting_bins_count as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of the post residual: bins whose leftover falls into
    // "reusable" residue classes (small, well-partitioned remainders) get rewarded.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let frac = post / cap; // capacity fraction of leftover

    // Dead-space penalty: leftover that is too small to be useful.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 - frac * 20.0;
    }

    // Harmonic residue classes: leftover congruent to 0 mod 25 or 0 mod 20 is
    // "harmonic" (matches common item-size classes), reward it.
    let r25 = post_residual % 25;
    let r20 = post_residual % 20;
    if post_residual > 0 {
        if r25 == 0 { score -= 12.0; }
        else if r20 == 0 { score -= 8.0; }
        // leftover in mid-range dead zone (10..20) is hard to fill
        if post_residual >= 10 && post_residual < 20 { score += 10.0; }
    }

    // Perfect fit: huge reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Lookahead coupling: does the leftover harmonically match the next item?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // next item fits exactly into a harmonic class of this leftover
            if post_residual % next_item_size.max(1) == 0 {
                score -= 15.0;
            } else {
                score -= 5.0;
            }
        } else {
            // next item cannot use this leftover; penalize proportionally
            score += 8.0 + (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Integer-division threshold on leftover: leftover >= half capacity is
    // versatile, reward; leftover in the awkward upper-middle band is penalized.
    if post_residual >= bin_capacity / 2 {
        score -= 6.0;
    } else if post_residual >= bin_capacity / 3 && post_residual < bin_capacity / 2 {
        score += 4.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when the item is large relative to
    // capacity or all open bins would leave bad residues.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let base = cap * 0.55 - item_size as f64 * 0.4;
        // open new bin more willingly late in the stream when many bins exist
        score = base + open_bins_count as f64 * 0.05 - progress * 5.0;
        if item_size >= 60 { score -= 10.0; }
    }

    // Mild diversity pressure: keep residuals spread around the mean.
    score += (post - mean_residual) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let next = next_item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items.max(1) as f64 } else { 0.0 };
    let post_norm = pr / cap;
    let fit_ratio = item_size as f64 / cap;
    let gap = (bin_residual - item_size) as f64 / cap;
    let mut score = post_norm * post_norm * 52.0 + post_norm * 20.0;

    // ---- 2-step lookahead: shape score around the NEXT item ----
    if next > 0.0 {
        if pr == next {
            score -= 58.0;
        } else if pr > next {
            let slack = pr - next;
            let diff = slack / cap;
            score -= 20.0 * (1.0 - diff).max(0.0);
            score -= (-diff * diff * 470.0).exp() * 24.0 * (1.0 - progress * 0.5);
            if diff < 0.04 {
                score -= (0.04 - diff) * 34.0 * (0.6 + progress * 0.6);
            } else if diff > 0.16 {
                score += (diff - 0.16) * 8.0 * (0.5 + progress);
            }
        } else if pr > 0.0 {
            let dead_ratio = (next - pr) / cap;
            score += dead_ratio * 95.0 * (0.6 + progress * 0.6);
        }
    }

    // ---- Absolute dead-floor guard: tiny stranded remainders ----
    let dead_floor = if next_item_size > 0 { (next_item_size.min(12) as f64).max(6.0) } else { 10.0 };
    if post_residual > 0 && pr < dead_floor && pr != next {
        score += 64.0 * (1.0 - progress * 0.3);
    } else if post_residual > 0 && post_residual < 20 && pr != next {
        score += 25.0;
    }

    // ---- Relative-to-mean coupling ----
    if pr > 0.0 {
        let dev = (mean_residual - pr) / cap;
        if dev > 0.05 {
            score += (dev - 0.05) * 12.0 * (0.4 + progress);
        } else if dev < -0.08 {
            score += (-dev - 0.08) * 6.0 * (1.0 - progress);
        }
    }

    // ---- New-bin candidate decision ----
    if bin_residual == bin_capacity {
        let others = if fitting_bins_count > 0 { fitting_bins_count - 1 } else { 0 };
        let size_pull = fit_ratio * 14.0;
        if fitting_bins_count <= 2 && gap > 0.0 {
            score -= (18.0 + size_pull) * (1.0 - progress * 0.6);
        } else if others == 0 {
            score -= 5.0;
        } else {
            score += 20.0 + open_bins_count as f64 * (0.5 + 0.5 * progress);
        }
        if next > 0.0 && fitting_bins_count <= 3 && fit_ratio >= next * 0.95 / cap {
            score -= 5.5 * (1.0 - progress * 0.5);
        }
        if next > 0.0 && fitting_bins_count >= 1 && fit_ratio * cap + next > cap {
            score += 8.0 * (1.0 - progress * 0.4);
        }
        if next > 0.0 && fit_ratio * cap + next <= cap {
            let pair_left = (cap - fit_ratio * cap - next) / cap;
            if pair_left < 0.05 {
                score -= (0.05 - pair_left) * 46.0 * (0.5 + progress * 0.5);
            } else if fit_ratio > 0.35 {
                score -= 3.0 * (1.0 - progress);
            }
        }
        if fit_ratio > 0.5 && progress < 0.5 {
            score -= 6.0 * (1.0 - progress);
        }
        if progress > 0.85 && fit_ratio > 0.6 {
            score -= 4.0 * (progress - 0.85) * 20.0;
        }
        // Strong pair-closure pull — new bin attractive only when item+next nearly fill capacity.
        if next > 0.0 && fit_ratio * cap + next > cap * 0.94 && fitting_bins_count > 2 {
            score -= 6.0 * (1.0 - progress * 0.5);
        }
        // COMBINED: triple-fit lookahead — new bin that can host next item twice
        // with minimal slack is very attractive (reduces dead space later).
        if next > 0.0 && fit_ratio * cap + next * 2.0 <= cap {
            let tri_left = (cap - fit_ratio * cap - next * 2.0) / cap;
            if tri_left < 0.03 {
                score -= 9.0 * (1.0 - progress * 0.4);
            }
        }
    }

    // Exact / near-exact fit bonuses.
    if pr == 0.0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 42.0;
    } else if post_residual <= 9 {
        score -= 18.0 * (1.0 - progress * 0.4);
    } else if post_norm < 0.02 && fitting_bins_count >= 4 {
        score -= 6.0 * (1.0 - progress);
    }

    // Sharp bonus for leaving a tiny gap (<12% of capacity).
    if gap > 0.0 && gap < 0.12 {
        score -= (0.12 - gap) * 48.0;
    } else if gap >= 0.12 && gap < 0.22 && next > 0.0 && pr > 0.0 && pr < next {
        score += (gap - 0.12) * 90.5 * (0.5 + progress);
    } else if gap >= 0.12 && gap < 0.22 && fitting_bins_count <= 3 {
        score += (gap - 0.12) * 18.0 * (0.5 + progress * 0.5);
    }
    if gap >= 0.22 && gap < 0.30 && fitting_bins_count <= 2 {
        score += (gap - 0.22) * 22.0 * (0.6 + progress * 0.4);
    }
    // Next-item chain: leftover after next item nearly closes bin.
    if next > 0.0 && gap > 0.12 {
        let nxt_gap = ((gap * cap - next).max(0.0)) / cap;
        if nxt_gap < 0.05 {
            score -= (0.05 - nxt_gap) * 42.0 * (0.5 + progress * 0.5);
        }
    }

    // Reward large items filling bins deeply.
    score -= fit_ratio * fit_ratio * 6.0;

    // Congestion: many competing bins => penalize sloppy fits.
    if fitting_bins_count > 2 {
        score += gap * 6.5 * ((fitting_bins_count.min(12) as f64 - 2.0) / 10.0);
    }
    if open_bins_count > 8 {
        score += post_norm * 5.0 * ((open_bins_count.min(20) as f64 - 8.0) / 12.0);
    }

    // Late-stream consolidation.
    if progress > 0.7 && post_norm > 0.25 {
        score += (post_norm - 0.25) * 6.0 * (progress - 0.7) / 0.3;
    }

    // Last-chance bonus: prefer a bin that would otherwise be wasted.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 - fit_ratio);
    }

    // Deep fill bonus.
    let fill_r = item_size as f64 / bin_residual.max(1) as f64;
    if fill_r > 0.90 && bin_residual != bin_capacity {
        score -= (fill_r - 0.90) * 18.0 * (0.6 + progress * 0.5);
    }

    // Waste-vs-mean term.
    if pr > 0.0 && mean_residual > 0.0 {
        let waste = post_norm - mean_residual / cap;
        if waste > 0.0 {
            score += waste * 30.0 * (0.4 + progress * 0.6);
        } else {
            score -= (-waste) * 10.0;
        }
    }

    // Penalize bins whose post-residual can never host the next item class.
    if pr > 0.0 && next > 0.0 && pr < next && post_norm > 0.03 {
        score += (next - pr) / cap * 20.0 * (0.5 + progress * 0.5);
    }

    // Reward bins that remain exactly reusable by the next item.
    if next > 0.0 && pr > 0.0 && (pr - next) / cap < 0.02 && pr >= next {
        score -= 6.0 * (1.0 - (pr - next) / cap / 0.02) * (0.5 + progress);
    }

    // Periodic divisibility bonus — post-residual is a near-multiple of next item.
    if next > 0.0 && pr > 0.0 && pr >= next {
        let frac = ((pr - next) % next.max(1.0)) / next.max(1.0);
        if frac < 0.08 {
            score -= 10.0 * (1.0 - progress * 0.5);
        }
    }

    // Double-fit bonus — post-residual hosts the next item twice with little slack.
    if next > 0.0 && pr >= next * 2.0 && pr < next * 2.0 + 8.0 {
        score -= 8.0 * (1.0 - progress * 0.4);
    }

    // Last-chance micro-gap bonus.
    if fitting_bins_count == 1 && gap > 0.0 && gap < 0.06 {
        score -= 7.0 * (1.0 - progress * 0.5);
    }

    // Dead-space penalty when few fitting bins and residual too small for next.
    if next > 0.0 && post_residual > 0 && (post_residual as u32) < next_item_size && fitting_bins_count <= 2 {
        score += 18.0 * (1.0 - progress * 0.5);
    }

    // COMBINED: chain-closure — residual after placing item can host next item
    // AND the remaining slack can host a small fraction of mean-sized items.
    if next > 0.0 && pr >= next && fitting_bins_count > 1 {
        let chain = pr - next;
        if chain < mean_residual.max(1.0) * 0.35 {
            score -= 5.0 * (1.0 - chain / (mean_residual.max(1.0) * 0.35)) * (0.5 + progress * 0.5);
        }
    }

    // COMBINED: mean-residual divisibility — post-residual close to a multiple of
    // the mean residual implies future small items will tile it cleanly.
    if pr > 0.0 && mean_residual > 2.0 {
        let mfrac = (pr % mean_residual) / mean_residual;
        if mfrac < 0.06 && pr / mean_residual >= 1.0 {
            score -= 4.0 * (1.0 - progress * 0.4);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (< 10, min item size)
    // are pure waste; penalize them heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Gaps too small for the next item are likely dead space too.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 0.5 * (next_item_size - post_residual) as f64;
    }
    // Perfect fit is highly desirable.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward tight fills relative to capacity.
    score -= 0.3 * (item_size as f64 / bin_capacity as f64) * 100.0;

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins; a new empty bin should only win when fits are poor.
    let open_pressure = open_bins_count as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: neutral base plus pressure penalty.
        score = bin_capacity as f64 * 0.9 + 2.0 * open_pressure;
        // If this is the only fitting option, opening a new bin is fine.
        if fitting_bins_count <= 1 {
            score -= 30.0;
        }
    } else {
        // Existing bin: slight reward to counteract open-bin pressure.
        score -= 1.5 * open_pressure;
        // Last-chance bin: strongly favor using it.
        if fitting_bins_count == 1 {
            score -= 25.0;
        }
    }

    // Mean-residual coupling: when average residuals are large, waste is
    // more acceptable; when small, squeeze bins harder.
    score -= 0.2 * (mean_residual - post_residual as f64);

    // Early in the stream, be more willing to open bins (future unknown).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score -= 20.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Base: prefer tight fits (small post_residual).
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: exact match of post_residual with next item
    // is a perfect two-item chain -> strong reward.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += diff * 0.8;
        if post_residual == next_item_size {
            score -= 25.0;
        }
        // If next item cannot fit anywhere else after this placement, prepare room.
        if post_residual < next_item_size && next_item_size <= bin_capacity {
            score += 6.0; // dead space for the lookahead item
        }
    }

    // Relative-to-mean coupling: bins with residual far below mean are already
    // "used up"; placing here keeps clean large residuals elsewhere.
    let rel = post_residual as f64 - mean_residual;
    score += 0.3 * rel;

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin unless current item is
    // large and would leave a nearly useless sliver in every existing bin.
    if bin_residual == bin_capacity {
        score += 15.0;
        if item_size >= 60 || (next_item_size > 0 && post_residual == next_item_size) {
            score -= 18.0; // large item or perfect chain justifies a fresh bin
        }
    }

    // Early in the stream, allow more bins to keep flexibility.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        score -= 5.0 * (1.0 - progress) * (mean_residual / bin_capacity as f64);
    }

    // Slight preference for filling bins with more residual (larger holes first).
    score += 0.05 * bin_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for very tight fits (small post_residual).
    if post_residual == 0 {
        score -= 60.0;
    } else {
        // Non-linear penalty on wasted space, amplified when it can't fit the next item.
        let waste = post_residual as f64;
        score += (waste * waste) / (bin_capacity as f64);
        if next_item_size > 0 && post_residual < next_item_size {
            score += 25.0; // dead space that blocks the lookahead item
        } else if next_item_size > 0 && post_residual >= next_item_size {
            score -= 8.0; // residual remains usable for the next item
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Penalize opening a new bin when there are already many open bins with slack.
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure from open bins.
        score += 40.0 + 6.0 * open_bins_count as f64;
        // Less penalty early in the stream (plenty of future items to fill bins).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 25.0 * (1.0 - progress);
        // If the item is large and mean residual is low, opening fresh is acceptable.
        if item_size as f64 > mean_residual {
            score -= 20.0;
        }
        // If next item is also large, a fresh bin gives flexibility.
        if next_item_size >= item_size {
            score -= 10.0;
        }
    } else {
        // Favor bins whose residual deviates from the mean in a "tight" direction.
        let diff = mean_residual - bin_residual as f64;
        score += 0.15 * diff;
        // Reward filling bins that are already quite full.
        let fill_ratio = 1.0 - (bin_residual as f64 / bin_capacity as f64);
        score -= 15.0 * fill_ratio;
    }

    // Slight preference for keeping bin count low overall.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let next = next_item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items.max(1) as f64 } else { 0.0 };
    let post_norm = pr / cap;
    let fit_ratio = item_size as f64 / cap;
    let gap = (bin_residual - item_size) as f64 / cap;
    let mut score = post_norm * post_norm * 52.0 + post_norm * 20.0;

    // ---- 2-step lookahead: shape score around the NEXT item ----
    if next > 0.0 {
        if pr == next {
            score -= 54.0;
        } else if pr > next {
            let slack = pr - next;
            let diff = slack / cap;
            score -= 20.0 * (1.0 - diff).max(0.0);
            score -= (-diff * diff * 470.0).exp() * 24.0 * (1.0 - progress * 0.5);
            if diff < 0.04 {
                score -= (0.04 - diff) * 30.0 * (0.6 + progress * 0.6);
            } else if diff > 0.16 {
                score += (diff - 0.16) * 8.0 * (0.5 + progress);
            }
        } else if pr > 0.0 {
            let dead_ratio = (next - pr) / cap;
            score += dead_ratio * 92.0 * (0.6 + progress * 0.6);
        }
    }

    // ---- Absolute dead-floor guard: tiny stranded remainders ----
    let dead_floor = if next_item_size > 0 { (next_item_size.min(12) as f64).max(6.0) } else { 10.0 };
    if post_residual > 0 && pr < dead_floor && pr != next {
        score += 64.0 * (1.0 - progress * 0.3);
    } else if post_residual > 0 && post_residual < 20 && pr != next {
        score += 25.0;
    }

    // ---- Relative-to-mean coupling ----
    if pr > 0.0 {
        let dev = (mean_residual - pr) / cap;
        if dev > 0.05 {
            score += (dev - 0.05) * 12.0 * (0.4 + progress);
        } else if dev < -0.08 {
            score += (-dev - 0.08) * 6.0 * (1.0 - progress);
        }
    }

    // ---- New-bin candidate decision ----
    if bin_residual == bin_capacity {
        let others = if fitting_bins_count > 0 { fitting_bins_count - 1 } else { 0 };
        let size_pull = fit_ratio * 14.0;
        if fitting_bins_count <= 2 && gap > 0.0 {
            score -= (18.0 + size_pull) * (1.0 - progress * 0.6);
        } else if others == 0 {
            score -= 5.0;
        } else {
            score += 20.0 + open_bins_count as f64 * (0.5 + 0.5 * progress);
        }
        if next > 0.0 && fitting_bins_count <= 3 && fit_ratio >= next * 0.95 / cap {
            score -= 5.5 * (1.0 - progress * 0.5);
        }
        if next > 0.0 && fitting_bins_count >= 1 && fit_ratio * cap + next > cap {
            score += 8.0 * (1.0 - progress * 0.4);
        }
        if next > 0.0 && fit_ratio * cap + next <= cap {
            let pair_left = (cap - fit_ratio * cap - next) / cap;
            if pair_left < 0.05 {
                score -= (0.05 - pair_left) * 42.0 * (0.5 + progress * 0.5);
            } else if fit_ratio > 0.35 {
                score -= 3.0 * (1.0 - progress);
            }
        }
        if fit_ratio > 0.5 && progress < 0.5 {
            score -= 6.0 * (1.0 - progress);
        }
        if progress > 0.85 && fit_ratio > 0.6 {
            score -= 4.0 * (progress - 0.85) * 20.0;
        }
        // Strong pair-closure pull — new bin attractive only when item+next nearly fill capacity.
        if next > 0.0 && fit_ratio * cap + next > cap * 0.94 && fitting_bins_count > 2 {
            score -= 6.0 * (1.0 - progress * 0.5);
        }
        // MUTATION: resist opening new bins late in the stream when a decent fit exists.
        if progress > 0.6 && fitting_bins_count >= 1 && gap > 0.02 {
            score += (progress - 0.6) * 30.0;
        }
    }

    // Exact / near-exact fit bonuses.
    if pr == 0.0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 42.0;
    } else if post_residual <= 9 {
        score -= 18.0 * (1.0 - progress * 0.4);
    } else if post_norm < 0.02 && fitting_bins_count >= 4 {
        score -= 6.0 * (1.0 - progress);
    }

    // Sharp bonus for leaving a tiny gap (<12% of capacity).
    if gap > 0.0 && gap < 0.12 {
        score -= (0.12 - gap) * 48.0;
    } else if gap >= 0.12 && gap < 0.22 && next > 0.0 && pr > 0.0 && pr < next {
        score += (gap - 0.12) * 90.5 * (0.5 + progress);
    } else if gap >= 0.12 && gap < 0.22 && fitting_bins_count <= 3 {
        score += (gap - 0.12) * 18.0 * (0.5 + progress * 0.5);
    }
    if gap >= 0.22 && gap < 0.30 && fitting_bins_count <= 2 {
        score += (gap - 0.22) * 22.0 * (0.6 + progress * 0.4);
    }
    // Next-item chain: leftover after next item nearly closes bin.
    if next > 0.0 && gap > 0.12 {
        let nxt_gap = ((gap * cap - next).max(0.0)) / cap;
        if nxt_gap < 0.05 {
            score -= (0.05 - nxt_gap) * 42.0 * (0.5 + progress * 0.5);
        }
    }

    // Reward large items filling bins deeply.
    score -= fit_ratio * fit_ratio * 6.0;

    // Congestion: many competing bins => penalize sloppy fits.
    if fitting_bins_count > 2 {
        score += gap * 6.5 * ((fitting_bins_count.min(12) as f64 - 2.0) / 10.0);
    }
    if open_bins_count > 8 {
        score += post_norm * 5.0 * ((open_bins_count.min(20) as f64 - 8.0) / 12.0);
    }

    // Late-stream consolidation.
    if progress > 0.7 && post_norm > 0.25 {
        score += (post_norm - 0.25) * 6.0 * (progress - 0.7) / 0.3;
    }

    // Last-chance bonus: prefer a bin that would otherwise be wasted.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 - fit_ratio);
    }

    // Deep fill bonus.
    let fill_r = item_size as f64 / bin_residual.max(1) as f64;
    if fill_r > 0.90 && bin_residual != bin_capacity {
        score -= (fill_r - 0.90) * 18.0 * (0.6 + progress * 0.5);
    }

    // Waste-vs-mean term.
    if pr > 0.0 && mean_residual > 0.0 {
        let waste = post_norm - mean_residual / cap;
        if waste > 0.0 {
            score += waste * 30.0 * (0.4 + progress * 0.6);
        } else {
            score -= (-waste) * 10.0;
        }
    }

    // Penalize bins whose post-residual can never host the next item class.
    if pr > 0.0 && next > 0.0 && pr < next && post_norm > 0.03 {
        score += (next - pr) / cap * 20.0 * (0.5 + progress * 0.5);
    }

    // Reward bins that remain exactly reusable by the next item.
    if next > 0.0 && pr > 0.0 && (pr - next) / cap < 0.02 && pr >= next {
        score -= 6.0 * (1.0 - (pr - next) / cap / 0.02) * (0.5 + progress);
    }

    // Periodic divisibility bonus — post-residual is a near-multiple of next item.
    if next > 0.0 && pr > 0.0 && pr >= next {
        let frac = ((pr - next) % next.max(1.0)) / next.max(1.0);
        if frac < 0.08 {
            score -= 10.0 * (1.0 - progress * 0.5);
        }
    }

    // Double-fit bonus — post-residual hosts the next item twice with little slack.
    if next > 0.0 && pr >= next * 2.0 && pr < next * 2.0 + 8.0 {
        score -= 8.0 * (1.0 - progress * 0.4);
    }

    // Last-chance micro-gap bonus.
    if fitting_bins_count == 1 && gap > 0.0 && gap < 0.06 {
        score -= 7.0 * (1.0 - progress * 0.5);
    }

    // Dead-space penalty when few fitting bins and residual too small for next.
    if next > 0.0 && post_residual > 0 && (post_residual as u32) < next_item_size && fitting_bins_count <= 2 {
        score += 18.0 * (1.0 - progress * 0.5);
    }

    // Chain-closure — residual after placing item can host next item with little slack.
    if next > 0.0 && pr >= next && fitting_bins_count > 1 {
        let chain = pr - next;
        if chain < mean_residual.max(1.0) * 0.35 {
            score -= 5.0 * (1.0 - chain / (mean_residual.max(1.0) * 0.35)) * (0.5 + progress * 0.5);
        }
    }

    // MUTATION: dead-space ratio penalty — penalize the fraction of the bin left
    // unusable by the next item, scaled by how late we are in the stream.
    if next > 0.0 && pr > 0.0 && pr < next {
        score += (1.0 - pr / next) * 14.0 * (0.4 + progress * 0.8);
    }

    // MUTATION: reward near-perfect fills more aggressively mid-stream.
    if gap > 0.0 && gap < 0.05 && progress > 0.3 {
        score -= (0.05 - gap) * 30.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Base: waste after placement, non-linearly shaped.
    let mut score = pr + 0.35 * (pr * pr) / cap;

    // Tight fits are valuable: reward small post_residual.
    score -= 40.0 * (1.0 - pr / cap).powi(6);

    // Dead-space penalty: residuals too small to be useful later.
    let dead = ((20.0 - pr).max(0.0) / 20.0).powi(2);
    score += 30.0 * dead * (0.5 + 0.5 * progress);

    // Lookahead coupling: prefer bins whose leftover fits the next item.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let fit_next = ((pr - nx).abs() / cap).min(1.0);
        score -= 25.0 * (1.0 - fit_next) * (1.0 - progress);
        // Penalize leaving a gap just below the next item size (worst case).
        let gap = (nx - pr).max(0.0);
        score += 15.0 * (gap / cap) * (1.0 - progress);
    }

    // Last-chance bin: strongly favor using it to avoid opening a bin.
    if fitting_bins_count == 1 {
        score -= 45.0;
    }

    // Many open bins: encourage filling existing ones rather than spreading.
    score += (open_bins_count as f64).ln().max(0.0) * 3.0 * (pr / cap);

    // New-bin candidate: penalize mildly so it's chosen only for poor fits,
    // with penalty easing late in the stream (consolidation phase).
    if bin_residual == bin_capacity {
        score += 60.0 * (1.0 - 0.4 * progress);
    }

    // Mean-residual coupling: if this bin is far from mean, slight penalty.
    score += 0.1 * ((pr - mean_residual) / cap).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues modulo 10 classify
    // how "usable" the leftover space is for typical item sizes.
    let r = post_residual % 10;
    let class_bonus = match r {
        0 => 6.0,          // perfectly aligned leftover (e.g. 100, 50, 30)
        1 | 9 => 2.0,
        2 | 8 => 0.0,
        3 | 7 => -1.5,
        4 | 6 => -3.0,
        _ => -4.5,         // residue 5 pairs well with many sizes
    };
    score += class_bonus;

    // Integer-division tiers on post_residual: small leftovers are dead space.
    let tier = post_residual / 20; // 0..=5
    score += match tier {
        0 => -14.0, // post_residual < 20 : nearly full bin, excellent
        1 => -6.0,
        2 => 0.0,
        3 => 5.0,
        _ => 9.0,   // large leftover: wasted capacity
    };

    // Reward tight fits strongly.
    if post_residual < 10 {
        score -= 18.0;
    } else if post_residual == item_size {
        score -= 12.0; // bin becomes exactly half or symmetric split
    }

    // Lookahead coupling: if the next item fits the post-residual exactly,
    // this placement chains perfectly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain_gap = post_residual - next_item_size;
        if chain_gap == 0 {
            score -= 15.0;
        } else if chain_gap < 10 {
            score -= 7.0;
        } else {
            score += (chain_gap as f64) * 0.05;
        }
    } else if next_item_size > 0 && post_residual > 0 {
        // next item cannot use this leftover at all: mild penalty
        score += 4.0;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0 + (post_residual as f64).min(15.0);
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // current item is large and no open bin fits well.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let pressure = (open_bins_count as f64) * 0.15;
        let big_item = (item_size as f64) > 0.6 * (bin_capacity as f64);
        if big_item && post_residual < 40 && fitting_bins_count == 0 {
            score -= 20.0 * (0.3 + progress); // open fresh bin for big item
        } else {
            score += 12.0 + pressure; // prefer existing bins generally
        }
        // penalize new bin when mean residual across open bins is still large
        score += (mean_residual * 0.1).min(10.0);
    }

    // Mild preference to fill bins below mean residual (balance avoidance of
    // many half-empty bins).
    score -= (mean_residual - post_residual as f64) * 0.08;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A gap is "dead" if it is too small for the smallest plausible item (1..10)
    // and cannot serve the lookahead item either.
    if post_residual > 0 {
        let dead = (post_residual < 10) as f64;
        let serves_lookahead = (next_item_size > 0 && post_residual >= next_item_size) as f64;
        score += dead * (40.0 - 2.0 * post_residual as f64);
        score -= serves_lookahead * 15.0;
        // Perfect fit bonus
        if post_residual == 0 {
            score -= 50.0;
        }
    }

    // Reward tight fits relative to bin residual (high fill ratio).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 20.0;

    // Open-bin pressure: discourage spreading across many bins unless the fit is good.
    score += open_bins_count as f64 * 0.8;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: prefer it only when item is large relative to capacity
    // (opening fresh space for big items) or when open-bin residuals are large.
    if bin_residual == bin_capacity {
        let large_item = (item_size as f64 / bin_capacity as f64) > 0.5;
        if large_item {
            score -= 25.0;
        } else {
            score += 10.0 + mean_residual * 0.1;
        }
    }

    // Slight progression-aware tilt: later in the stream, consolidate harder.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * mean_residual * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let post_norm = post_residual as f64 / cap;
    let mut score = post_norm * post_norm * 50.0 + post_norm * 20.0;

    // Perfect fit: strong reward (subtract).
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 42.0;
    } else if post_residual <= 9 {
        score -= 18.0 * (1.0 - progress * 0.4);
    }

    // Dead-space class: residuals in (0, 12] are almost unusable.
    let dead_floor = if next_item_size > 0 { (next_item_size.min(12) as f64).max(6.0) } else { 10.0 };
    if post_residual > 0 && (post_residual as f64) < dead_floor {
        score += 62.0 * (1.0 - progress * 0.3);
    } else if post_residual < 20 {
        score += 25.0;
    }

    // Harmonic divisibility rewards.
    if post_residual > 0 {
        let pr = post_residual;
        if pr % 50 == 0 { score -= 18.0; }
        else if pr % 25 == 0 { score -= 12.0; }
        else if pr % 20 == 0 { score -= 10.0; }
        else if pr % 10 == 0 { score -= 8.0; }
        else {
            score += (pr % 5) as f64 * 1.5;
        }
    }

    // Lookahead: next item fit quality in post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size < post_residual {
            let nxt_left = post_residual - next_item_size;
            if nxt_left % 10 == 0 {
                score -= 10.0;
            } else if nxt_left > 12 {
                score -= 4.0;
            } else {
                score += 6.0;
            }
            // Tight post-fit: near-exact pairing with next item.
            let slack = (post_residual - next_item_size) as f64 / cap;
            score -= (-slack * slack * 450.0).exp() * 24.0 * (1.0 - progress * 0.5);
            // Two-of-next pairing: residual fits next item twice nearly exactly.
            let prf = post_residual as f64;
            let nxt = next_item_size as f64;
            if prf >= nxt * 2.0 && prf < nxt * 2.0 + 8.0 {
                score -= 8.0 * (1.0 - progress * 0.4);
            }
            let frac = ((prf - nxt) % nxt.max(1.0)) / nxt.max(1.0);
            if frac < 0.08 {
                score -= 10.0 * (1.0 - progress * 0.5);
            }
        } else {
            // next item cannot use this leftover: wasted space penalty
            let dead_ratio = (next_item_size as f64 - post_residual as f64) / cap;
            score += dead_ratio * 90.0 * (0.6 + progress * 0.6);
            if fitting_bins_count <= 2 {
                score += 18.0 * (1.0 - progress * 0.5);
            }
        }
    }

    // Tight-gap bonus: prefer bins where item nearly fills residual.
    let gap = (bin_residual - item_size) as f64 / cap;
    if gap > 0.0 && gap < 0.12 {
        score -= (0.12 - gap) * 48.0;
    } else if gap >= 0.12 && gap < 0.22 {
        if fitting_bins_count <= 3 {
            score += (gap - 0.12) * 18.0 * (0.5 + progress * 0.5);
        }
    }
    if gap >= 0.22 && gap < 0.30 && fitting_bins_count <= 2 {
        score += (gap - 0.22) * 22.0 * (0.6 + progress * 0.4);
    }
    if fitting_bins_count == 1 && gap > 0.0 && gap < 0.06 {
        score -= 7.0 * (1.0 - progress * 0.5);
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let size_pull = (item_size as f64 / cap) * 14.0;
        if fitting_bins_count <= 2 {
            score -= (18.0 + size_pull) * (1.0 - progress * 0.6);
        } else {
            score += 20.0 + open_bins_count as f64 * (0.5 + 0.5 * progress);
        }
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a bin
        }
        // Large item early: worth a fresh bin to keep it isolated.
        if (item_size as f64) > cap * 0.5 && progress < 0.5 {
            score -= 6.0 * (1.0 - progress);
        }
        if progress > 0.85 && (item_size as f64) / cap > 0.6 {
            score -= 4.0 * (progress - 0.85) * 20.0;
        }
        // If next item pairs with current item in a fresh bin, encourage opening.
        if next_item_size > 0 && (item_size as f64) + (next_item_size as f64) <= cap && (item_size as f64) / cap > 0.35 {
            score -= 3.0 * (1.0 - progress);
        }
        if next_item_size > 0 && fitting_bins_count <= 3 && (item_size as f64) >= next_item_size as f64 * 0.95 {
            score -= 5.5 * (1.0 - progress * 0.5);
        }
        if next_item_size > 0 && fitting_bins_count >= 1 {
            let nxt = next_item_size as f64;
            if (item_size as f64) + nxt > cap {
                score += 8.0 * (1.0 - progress * 0.4);
            }
        }
    }

    // Global pressure: high mean residual -> pack tight bins.
    score -= (mean_residual / cap) * 5.0;

    // Waste-relative pressure: penalize bins whose post-residual exceeds mean.
    if post_residual > 0 && mean_residual > 0.0 {
        let waste = post_norm - (mean_residual / cap);
        if waste > 0.0 {
            score += waste * 30.0 * (0.4 + progress * 0.6);
        } else {
            score -= (-waste) * 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) nonlinearly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 35.0;
    } else if post_residual <= 15 {
        score -= 18.0;
    }

    // 2-step lookahead: if the next item fits exactly into the post residual,
    // this is a perfect chain placement.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 50.0;
        } else if post_residual >= next_item_size {
            // next item fits, but leaves further slack; mild reward scaled by tightness
            let slack = (post_residual - next_item_size) as f64;
            if slack <= 10.0 {
                score -= 25.0 - slack * 1.5;
            } else {
                score -= 8.0 - (slack - 10.0).min(40.0) * 0.15;
            }
        } else {
            // next item will NOT fit here: leftover is likely dead space
            let gap = (next_item_size - post_residual) as f64;
            score += gap.min(50.0) * 0.8;
        }
    }

    // Compare against mean residual: bins with less slack than average are
    // good candidates to fill up first (best-fit across open bins).
    score += (bin_residual as f64 - mean_residual) * 0.4;

    // Last chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Penalize opening a new bin when open bins exist that fit decently.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        // new bin is fine if current item is large and post residual useful
        let useful = if next_item_size > 0 && post_residual >= next_item_size { 1.0 } else { 0.0 };
        score += 20.0 - useful * 25.0;
    }

    // Late in the stream, consolidate into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (bin_residual as f64 / bin_capacity as f64) * (10.0 + 20.0 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
