pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual, with non-linear polynomial shaping in progress
    let mut score = pr * (1.0 + 0.5 * progress * progress);

    // Quadratic coupling of normalized post-residual with stream progress
    score += 20.0 * norm_pr * norm_pr * (0.5 + progress);

    // Cubic interaction term: penalize large dead space late in the stream
    score += 15.0 * norm_pr.powi(3) * progress;

    // Reward tight fits (small post residual) more strongly as stream advances
    score -= (1.0 - norm_pr) * (1.0 - norm_pr) * 10.0 * (0.3 + 0.7 * progress);

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 {
        score -= 12.0 + 8.0 * progress;
    }

    // Lookahead: reward bins whose post residual can host the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let slack = (pr - nxt) / cap;
            score -= 8.0 * (1.0 - slack) * (1.0 - slack);
        } else {
            score += 5.0 * (nxt - pr) / cap;
        }
    }

    // Coupling with mean residual: prefer bins deviating below mean residual (tighter bins)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 6.0 * dev * dev * (0.5 + progress);

    // Mild penalty for proliferation of open bins
    score += (open_bins_count as f64).sqrt() * 0.5;

    // New-bin candidate: make it attractive only when item is large relative to typical residual
    if bin_residual == bin_capacity {
        let ratio = item_size as f64 / cap;
        score = pr * (1.0 + progress) - 15.0 * ratio * ratio * (1.0 - progress);
    }

    score
}

