pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover is divisible by common
    // item sizes (10..80 multiples / small residues) are more reusable.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit
    } else {
        // residue classes: leftovers that pair well with typical small items
        let mut harmonic_bonus = 0.0;
        for d in [10u32, 20, 25, 30, 40, 50].iter() {
            if pr % d == 0 {
                harmonic_bonus += 12.0;
            }
        }
        score -= harmonic_bonus;

        // dead space penalty: small unusable leftovers
        if pr < 10 {
            score += 35.0;
        } else if pr < 20 {
            score += 12.0;
        }

        // lookahead: does next_item_size fit into post_residual?
        if next_item_size > 0 {
            if next_item_size <= pr {
                score -= 20.0 + (pr - next_item_size) as f64 * 0.15;
                // harmonic chain: post_residual % next_item_size small leftover
                let chain = pr % next_item_size;
                if chain < 10 {
                    score -= 8.0;
                }
            } else {
                score += 10.0; // next item won't chain here
            }
        } else {
            // last item: prefer filling as much as possible
            score -= 15.0;
        }
    }

    // last-chance bin: strongly favor using it to avoid opening a bin for one item
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // new-bin candidate: penalize opening a new bin unless current fits are poor
    if bin_residual == bin_capacity {
        score += 45.0 + (open_bins_count as f64).sqrt() * 2.0;
        // if item is large relative to capacity and stream is early, opening is okay
        let progress = step_index as f64 / (total_items.max(1) as f64);
        if item_size > bin_capacity / 2 && progress < 0.5 {
            score -= 30.0;
        }
    }

    // tie-break: prefer tighter bins relative to mean residual
    score += (bin_residual as f64 - mean_residual) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
