pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space quality by residue mod 10
    let r = post_residual;
    let harmonic_penalty = match r % 10 {
        0 => -6.0,   // exact multiples of 10 are reusable by typical items
        1 | 9 => 5.0,
        2 | 8 => 3.0,
        3 | 7 => 1.5,
        4 | 6 => 0.5,
        _ => 2.5,    // residue 5
    };
    score += harmonic_penalty;

    // Integer-division thresholds: residuals below 10 are dead space
    if r < 10 {
        score += 25.0;
    } else if r < 20 && r % 10 != 0 {
        score += 8.0;
    }

    // Capacity fraction coupling: reward tight fills
    let fill = (bin_capacity - r) as f64 / bin_capacity as f64;
    score -= 12.0 * fill * fill;

    // Lookahead: bonus if next item fits exactly in post_residual class
    if next_item_size > 0 {
        if next_item_size == r {
            score -= 40.0; // perfect chain
        } else if next_item_size <= r {
            score -= 10.0 * (next_item_size as f64 / r as f64);
            // harmonic match of next item to residual mod 10
            if (next_item_size % 10) == (r % 10) {
                score -= 6.0;
            }
        } else {
            score += 4.0; // next item won't fit here; slight penalty
        }
    }

    // Last-chance bin before opening a new one
    if fitting_bins_count == 1 && r >= item_size {
        score -= 15.0;
    }

    // New-bin candidate: penalize slightly unless current bins are crowded
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowd = mean_residual / bin_capacity as f64;
        score = 55.0 - 30.0 * crowd - 10.0 * progress;
        if fitting_bins_count == 0 {
            score -= 50.0; // no open bin fits: new bin is necessary
        }
    }

    // Mild pressure against bin proliferation
    score += 0.15 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let next = next_item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items.max(1) as f64 } else { 0.0 };
    let post_norm = pr / cap;
    let fit_ratio = item_size as f64 / cap;
    let gap = (bin_residual - item_size) as f64 / cap;
    let mut score = post_norm * post_norm * 56.5 + post_norm * 21.8;

    // ---- Aggressive 2-step lookahead: shape score around the NEXT item ----
    if next > 0.0 {
        if pr == next {
            score -= 45.0;
        } else if pr > next {
            let slack = pr - next;
            let diff = slack / cap;
            score -= 20.0 * (1.0 - diff).max(0.0);
            score -= (-diff * diff * 458.0).exp() * 20.2 * (1.0 - progress * 0.5);
            if diff < 0.04 {
                score -= (0.04 - diff) * 26.0 * (0.6 + progress * 0.6);
            } else if diff > 0.16 {
                score += (diff - 0.16) * 8.0 * (0.5 + progress);
            }
        } else if pr > 0.0 {
            score += (next - pr) / cap * 34.0 * (1.0 - progress);
        }
        // Chain bonus: after next item lands, remainder nearly closes bin.
        if gap > 0.12 {
            let nxt_gap = ((gap * cap - next).max(0.0)) / cap;
            if nxt_gap < 0.06 {
                score -= 9.0 * (1.0 - nxt_gap / 0.06) * (0.5 + progress);
            }
        }
    }

    // ---- Stranded-sliver guard (borrowed dead_floor idea, calibrated) ----
    if pr > 0.0 {
        let dead_floor = if next > 0.0 { next.min(12.0).max(6.0) } else { 10.0 };
        if pr < dead_floor && pr != next {
            score += 62.0 * (1.0 - progress * 0.3);
        } else if pr < 10.0 && pr != next {
            score += 15.0;
        }
        if pr == 0.0 {
            score -= 15.2;
        } else if post_norm < 0.05 {
            score -= 10.2 * (1.0 - post_norm / 0.05);
        }
    }

    // ---- Relative-to-mean coupling: penalize above-average waste ----
    if pr > 0.0 && mean_residual > 0.0 {
        let waste = post_norm - mean_residual / cap;
        if waste > 0.0 {
            score += waste * 30.0 * (0.4 + progress * 0.6);
        } else {
            score -= (-waste) * 10.0;
        }
    }

    // ---- New-bin candidate decision ----
    if bin_residual == bin_capacity {
        let others = if fitting_bins_count > 0 { fitting_bins_count - 1 } else { 0 };
        let size_pull = fit_ratio * 14.0;
        if fitting_bins_count <= 2 && gap > 0.0 {
            score -= (18.0 + size_pull) * (1.0 - progress * 0.6);
        } else if others == 0 {
            score -= 5.0;
        } else {
            score += 8.0 + 6.0 * (1.0 - progress) + open_bins_count as f64 * 0.3 * (0.5 + progress);
        }
