        if next > 0.0 && item_size as f64 + next > cap {
            score += 6.0 * (1.0 - progress * 0.4);
        }
    }

    // Sharp bonus for leaving a tiny gap (<10% of capacity).
    if gap > 0.0 && gap < 0.10 {
        score -= (0.10 - gap) * 40.5;
    }
    if gap >= 0.10 && gap < 0.22 && next > 0.0 && pr > 0.0 && pr < next {
        score += (gap - 0.10) * 90.5 * (0.5 + progress);
    }
    if gap >= 0.22 && gap < 0.35 && progress > 0.55 && fitting_bins_count <= 2 {
        score += (gap - 0.22) * 45.5 * (progress - 0.55) * 2.0;
    }

    // Reward large items filling bins deeply.
    score -= fit_ratio * fit_ratio * 6.0;

    // Congestion: when many bins compete for this item, penalize sloppy fits.
    if fitting_bins_count > 2 {
        score += gap * 6.5 * ((fitting_bins_count.min(12) as f64 - 2.0) / 10.0);
    }
    if open_bins_count > 8 {
        score += post_norm * 5.0 * ((open_bins_count.min(20) as f64 - 8.0) / 12.0);
    }

    // Late-stream consolidation.
    if progress > 0.7 && post_norm > 0.25 {
        score += (post_norm - 0.25) * 6.0 * (progress - 0.7) / 0.3;
    }

    // Last-chance bonus: prefer a bin that would otherwise be wasted.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 - fit_ratio);
    }

    // Deep fill bonus relative to actual residual.
    let fill_r = item_size as f64 / bin_residual.max(1) as f64;
    if fill_r > 0.90 && bin_residual != bin_capacity {
        score -= (fill_r - 0.90) * 18.0 * (0.6 + progress * 0.5);
    }

    // Dead-space guard: remainder after next item is a stranded gap.
    if next > 0.0 && pr > 0.0 {
        let after_next = (pr - next).max(0.0);
        let dead = after_next / cap;
        if dead > 0.0 && dead < 0.08 {
            let reusable = if after_next >= next { 1.0 } else { 0.0 };
            score += (0.08 - dead) * 16.0 * (1.0 - reusable * 0.5) * (0.5 + progress);
        }
        // Two-next fit: pr can host next twice snugly.
        if pr >= next * 2.0 && pr < next * 2.0 + 8.0 {
            score -= 8.0 * (1.0 - progress * 0.4);
        }
    }

    // Mid-residual band: leftover in 10-20% range that next item cannot fit.
    if pr > 0.0 && post_norm >= 0.10 && post_norm < 0.20 && next > 0.0 && next > pr {
        score += (next - pr) / cap * 26.0 * (0.4 + progress * 0.8);
    }

    // Half-consumed bins late in the stream.
    if pr > 0.0 && pr < item_size as f64 * 0.5 && progress > 0.3 {
        score += 4.0 * (1.0 - progress);
    }

    // Exact-fit chain: pr is a multiple of next within small tolerance.
    if next > 0.0 && pr >= next {
        let frac = ((pr - next) % next.max(1.0)) / next.max(1.0);
        if frac < 0.08 {
            score -= 10.0 * (1.0 - progress * 0.5);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let post_norm = pr / cap;
    let mut score = post_norm * post_norm * 50.0 + post_norm * 20.0;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 200.0;
    }

    // Dead-space class: residuals in (0, 12] are almost unusable.
    let dead_floor = if next_item_size > 0 { (next_item_size.min(12) as f64).max(6.0) } else { 10.0 };
    if post_residual > 0 && (post_residual as f64) < dead_floor {
        score += 62.0 * (1.0 - progress * 0.3);
    } else if post_residual > 0 && post_residual < 20 {
        score += 25.0;
    } else if post_residual > 0 && post_residual <= 12 {
        score += 25.0 * (13.0 - post_residual as f64);
    }

    // Harmonic divisibility rewards.
    if post_residual > 0 {
        let r = post_residual;
        if r % 50 == 0 { score -= 18.0; }
        else if r % 25 == 0 { score -= 12.0; }
        else if r % 20 == 0 { score -= 10.0; }
        else if r % 10 == 0 { score -= 8.0; }
        else {
            score += (r % 5) as f64 * 1.5;
        }
    }

    // Lookahead: next item fit quality in post_residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        if next_item_size == post_residual {
            score -= 60.0;
        } else {
            let nxt_left = post_residual - next_item_size;
            if nxt_left % 10 == 0 {
                score -= 10.0;
            } else if nxt_left > 12 {
                score -= 4.0;
            } else {
                score += 6.0;
            }
            let slack = nxt_left as f64 / cap;
            score -= (-slack * slack * 450.0).exp() * 24.0 * (1.0 - progress * 0.5);
            // near-exact multiples of next item
            let nxt = next_item_size as f64;
            let frac = ((pr - nxt) % nxt.max(1.0)) / nxt.max(1.0);
            if frac < 0.08 {
                score -= 10.0 * (1.0 - progress * 0.5);
            }
            if pr >= nxt * 2.0 && pr < nxt * 2.0 + 8.0 {
                score -= 8.0 * (1.0 - progress * 0.4);
            }
        }
    } else if next_item_size > 0 && post_residual > 0 {
        let dead_ratio = (next_item_size as f64 - pr) / cap;
        score += 8.0 + dead_ratio * 90.0 * (0.6 + progress * 0.6);
        if fitting_bins_count <= 2 {
            score += 18.0 * (1.0 - progress * 0.5);
        }
    }

    // Tight-gap bonus: prefer bins where item nearly fills residual.
    let gap = (bin_residual - item_size) as f64 / cap;
    if gap > 0.0 && gap < 0.12 {
        score -= (0.12 - gap) * 48.0;
        if fitting_bins_count == 1 && gap < 0.06 {
            score -= 7.0 * (1.0 - progress * 0.5);
        }
    } else if gap >= 0.12 && gap < 0.22 {
        if fitting_bins_count <= 3 {
            score += (gap - 0.12) * 18.0 * (0.5 + progress * 0.5);
        }
    } else if gap >= 0.22 && gap < 0.30 && fitting_bins_count <= 2 {
        score += (gap - 0.22) * 22.0 * (0.6 + progress * 0.4);
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let size_pull = (item_size as f64 / cap) * 14.0;
        if fitting_bins_count <= 2 {
            score -= (18.0 + size_pull) * (1.0 - progress * 0.6);
        } else {
            score += 20.0 + open_bins_count as f64 * (0.5 + 0.5 * progress);
        }
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a bin
        }
        if next_item_size > 0 && fitting_bins_count <= 3 && (item_size as f64) >= next_item_size as f64 * 0.95 {
            score -= 5.5 * (1.0 - progress * 0.5);
        }
        if next_item_size > 0 && fitting_bins_count >= 1 && (item_size as f64) + (next_item_size as f64) > cap {
            score += 8.0 * (1.0 - progress * 0.4);
        }
        if (item_size as f64) > cap * 0.5 && progress < 0.5 {
            score -= 6.0 * (1.0 - progress);
        }
        if progress > 0.85 && (item_size as f64) / cap > 0.6 {
            score -= 4.0 * (progress - 0.85) * 20.0;
        }
        if next_item_size > 0 && (item_size as f64) + (next_item_size as f64) <= cap && (item_size as f64) / cap > 0.35 {
            score -= 3.0 * (1.0 - progress);
        }
    }

    // Global pressure: high mean residual -> pack tight bins.
    score -= (mean_residual / cap) * 5.0;

    // Waste-relative pressure.
    if post_residual > 0 && mean_residual > 0.0 {
        let waste = post_norm - (mean_residual / cap);
        if waste > 0.0 {
            score += waste * 30.0 * (0.4 + progress * 0.6);
        } else {
            score -= (-waste) * 10.0;
        }
    }

    // Tiny post-residual with many options: mild reward to consolidate.
    if post_residual > 0 && post_norm < 0.02 && fitting_bins_count >= 4 {
        score -= 6.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // later are penalized heavily (typical useful threshold ~ smallest item).
    let dead_threshold = 10.0f64;
    if (post_residual as f64) < dead_threshold {
        // Perfect fill is great; a tiny useless gap is bad.
        if post_residual == 0 {
            score -= 25.0;
        } else {
            score += 30.0 + (dead_threshold - post_residual as f64) * 3.0;
        }
    } else {
        // Mild preference for tighter fits among "usable" residuals.
        score += (post_residual as f64) * 0.15;
    }

    // Reward leaving room for the lookahead item if it fits the post-residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 && next_item_size > 0 && (post_residual as u32) < next_item_size && post_residual > 0 {
        // Penalize blocking the next item with a gap slightly too small.
        score += 5.0;
    }

    // Last-chance bin pressure: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones,
    // encourage filling existing ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 / (1.0 + mean_residual / bin_capacity as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are open and mean
        // residual is large (existing bins still have room).
        score += 15.0 + pressure * 3.0 + mean_residual * 0.1 - progress * 5.0;
    } else {
        score -= pressure * 0.5;
    }

    // Favor bins whose residual deviates from mean in a "completable" way.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score -= dev * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let next = next_item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items.max(1) as f64 } else { 0.0 };
    let post_norm = pr / cap;
    let fit_ratio = item_size as f64 / cap;
    let gap = (bin_residual - item_size) as f64 / cap;
    let mut score = post_norm * post_norm * 52.0 + post_norm * 20.0;

    // ---- Aggressive 2-step lookahead: shape score around the NEXT item ----
    if next > 0.0 {
        if pr == next {
            score -= 50.0;
        } else if pr > next {
            let slack = pr - next;
            let diff = slack / cap;
            score -= 22.0 * (1.0 - diff).max(0.0);
            score -= (-diff * diff * 450.0).exp() * 22.0 * (1.0 - progress * 0.5);
            // Snug remainder after next item lands.
            if diff < 0.04 {
                score -= (0.04 - diff) * 30.0 * (0.6 + progress * 0.6);
            } else if diff > 0.16 {
                score += (diff - 0.16) * 9.0 * (0.5 + progress);
            }
        } else if pr > 0.0 {
            let dead_ratio = (next - pr) / cap;
            score += dead_ratio * 90.0 * (0.5 + progress * 0.6);
        }
    }

    // ---- Hard dead-space floor: tiny stranded remainders are poison ----
    if post_residual > 0 {
        let dead_floor = if next_item_size > 0 { (next_item_size.min(12) as f64).max(6.0) } else { 10.0 };
        if pr < dead_floor && pr != next {
            score += 55.0 * (1.0 - progress * 0.3);
        } else if post_residual < 20 && (next_item_size == 0 || pr < next) {
            score += 22.0;
        }
    }

    // ---- Exact / near-exact fit bonuses (strong, borrowed emphasis) ----
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 && (next_item_size == 0 || pr != next) {
        score -= 40.0 * (1.0 - progress * 0.3);
    } else if post_residual <= 9 && (next_item_size == 0 || pr != next) {
        score -= 16.0 * (1.0 - progress * 0.4);
    }

    // ---- Relative-to-mean coupling: favor tighter-than-average bins ----
    if pr > 0.0 && mean_residual > 0.0 {
        let waste = post_norm - mean_residual / cap;
        if waste > 0.0 {
            score += waste * 30.0 * (0.4 + progress * 0.6);
        } else {
            score -= (-waste) * 10.0;
        }
    }

    // ---- New-bin candidate decision (bin_residual == bin_capacity) ----
    if bin_residual == bin_capacity {
        let others = if fitting_bins_count > 0 { fitting_bins_count - 1 } else { 0 };
        let size_pull = fit_ratio * 14.0;
        if fitting_bins_count <= 2 && gap > 0.0 {
            score -= (18.0 + size_pull) * (1.0 - progress * 0.6);
        } else if others == 0 {
            score -= 5.0;
        } else {
            score += 20.0 + open_bins_count as f64 * (0.5 + 0.5 * progress);
        }
        if next > 0.0 && fitting_bins_count <= 3 && item_size as f64 >= next * 0.95 {
            score -= 5.5 * (1.0 - progress * 0.5);
        }
        if next > 0.0 && fitting_bins_count >= 1 && item_size as f64 + next > cap {
            score += 8.0 * (1.0 - progress * 0.4);
        }
        if item_size as f64 > cap * 0.5 && progress < 0.5 {
            score -= 6.0 * (1.0 - progress);
        }
        if progress > 0.85 && fit_ratio > 0.6 {
            score -= 4.0 * (progress - 0.85) * 20.0;
        }
        if next > 0.0 && item_size as f64 + next <= cap && fit_ratio > 0.35 {
            score -= 3.0 * (1.0 - progress);
        }
    }

    // Sharp bonus for leaving a tiny gap (<12% of capacity).
    if gap > 0.0 && gap < 0.12 {
        score -= (0.12 - gap) * 48.0;
    } else if gap >= 0.12 && gap < 0.22 && fitting_bins_count <= 3 {
        score += (gap - 0.12) * 18.0 * (0.5 + progress * 0.5);
    }
    if gap >= 0.22 && gap < 0.30 && fitting_bins_count <= 2 {
        score += (gap - 0.22) * 22.0 * (0.6 + progress * 0.4);
    }
    // Next-item chain: leftover after placing next item nearly closes bin.
    if next > 0.0 && gap > 0.12 {
        let nxt_gap = ((gap * cap - next).max(0.0)) / cap;
        if nxt_gap < 0.06 {
            score -= 10.0 * (1.0 - nxt_gap / 0.06) * (0.5 + progress);
        }
    }

    // Reward large items filling bins deeply.
    score -= fit_ratio * fit_ratio * 6.0;

    // Congestion: when many bins compete for this item, penalize sloppy fits.
    if fitting_bins_count > 2 {
        score += gap * 6.5 * ((fitting_bins_count.min(12) as f64 - 2.0) / 10.0);
    }
    if open_bins_count > 8 {
        score += post_norm * 5.0 * ((open_bins_count.min(20) as f64 - 8.0) / 12.0);
    }

    // Late-stream consolidation: penalize moderately large residuals late.
    if progress > 0.7 && post_norm > 0.25 {
        score += (post_norm - 0.25) * 6.0 * (progress - 0.7) / 0.3;
    }

    // Last-chance bonus: prefer a bin that would otherwise be wasted.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 - fit_ratio);
        if gap > 0.0 && gap < 0.06 {
            score -= 7.0 * (1.0 - progress * 0.5);
        }
    }

    // Deep fill bonus relative to actual residual.
    let fill_r = item_size as f64 / bin_residual.max(1) as f64;
    if fill_r > 0.90 && bin_residual != bin_capacity {
        score -= (fill_r - 0.90) * 18.0 * (0.6 + progress * 0.5);
    }

    // Dead-space guard: stranded small gap after next item.
    if next > 0.0 && pr > 0.0 {
        let after_next = (pr - next).max(0.0);
        let dead = after_next / cap;
        if dead > 0.0 && dead < 0.08 {
            let reusable = if after_next >= next { 1.0 } else { 0.0 };
            score += (0.08 - dead) * 16.0 * (1.0 - reusable * 0.5) * (0.5 + progress);
        }
        // Near-closure after next item lands.
        if pr >= next_item_size {
            let second_slack = (pr - next) / cap;
            if second_slack < 0.05 {
                score -= (0.05 - second_slack) * 40.0 * (0.5 + progress * 0.5);
            }
            // Modular snugness: remainder is a near-multiple of next item.
            let frac = ((pr - next) % next.max(1.0)) / next.max(1.0);
            if frac < 0.08 {
                score -= 10.0 * (1.0 - progress * 0.5);
            }
        }
        // Two-next-items fit but barely not three.
        if pr >= next * 2.0 && pr < next * 2.0 + 8.0 {
            score -= 8.0 * (1.0 - progress * 0.4);
        }
    }

    // Mid-residual band: leftover in 10-20% range that next item cannot fit
    // into is likely to strand; penalize.
    if pr > 0.0 && post_norm >= 0.10 && post_norm < 0.20 && next > 0.0 && next > pr {
        score += (next - pr) / cap * 26.0 * (0.4 + progress * 0.8);
    }

    // Half-consumed bins late in the stream: discourage leaving a residual
    // smaller than half the current item (hard to refill).
    if pr > 0.0 && pr < item_size as f64 * 0.5 && progress > 0.3 {
        score += 4.0 * (1.0 - progress);
    }

    // Very tight post-fit with several competing bins: reward it mildly.
    if post_residual > 0 && post_norm < 0.02 && fitting_bins_count >= 4 {
        score -= 6.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual) — already captured by starting at post_residual.

    // Aggressive 2-step lookahead: reward when post_residual exactly matches next item size.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (post_residual as f64 - nxt).abs();
        // Perfect chain fit: strong reward.
        if gap == 0.0 {
            score -= 40.0;
        } else {
            // Penalize deviation scaled by distance; dead space below next item is worse.
            if (post_residual as f64) < nxt {
                score += gap * 1.5; // unusable for the next item
            } else {
                score += gap * 0.5; // usable, but slack
            }
        }
        // Extra reward if post_residual can host next item well (>= next size).
        if post_residual as f64 >= nxt && post_residual as f64 - nxt < 10.0 {
            score -= 15.0;
        }
    } else {
        // Last item: any fit is fine; prefer the fullest bin to close it out.
        score -= (item_size as f64) * 0.1;
    }

    // Compare against mean residual: bins with residual far below mean are "tighter",
    // filling them first preserves slack in other bins.
    let resid = bin_residual as f64;
    if resid < mean_residual {
        score -= (mean_residual - resid) * 0.3;
    } else {
        score += (resid - mean_residual) * 0.3;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid fragmentation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize tiny dead space (< 10) that likely nothing can use, unless it's a perfect fill.
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }
    // Perfect closure reward.
    if post_residual == 0 {
        score -= 30.0;
    }

    // New-bin candidate handling: an empty bin has bin_residual == bin_capacity.
    // Only prefer it if the current stream is early (plenty of items remain) AND
    // the item is large relative to capacity (poor fit elsewhere is likely).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let large_item = (item_size as f64) / (bin_capacity as f64) > 0.6;
        if progress < 0.5 && large_item {
            score -= 5.0; // allow opening fresh bins early for big items
        } else {
            score += 15.0; // discourage spreading into new bins otherwise
        }
        // Cap: never let a fresh bin beat a genuinely tight existing fit.
        score += (open_bins_count as f64).sqrt() * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual relative to item size).
    let tightness = post_residual as f64 / (item_size.max(1) as f64);
    score += tightness * 5.0;

    // Penalize dead space: residuals too small for the smallest plausible item.
    if post_residual < 10 && post_residual > 0 {
        score += 40.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if bin_residual >= next_item_size && post_residual < next_item_size {
            // Choosing this bin blocks the next item's fit here; mild penalty.
            score += 6.0;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when current bin wastes a lot.
    if bin_residual == bin_capacity {
        let waste = mean_residual - post_residual as f64;
        if waste > 0.0 {
            score += waste * 0.8;
        }
        // Late in the stream, avoid spawning bins for marginal gains.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 + progress * 20.0;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 5.0; // fresh bin guarantees next fit
        }
    }

    // Many open bins: prefer consolidating into existing space.
    score += open_bins_count as f64 * 0.15;

    // Global residual pressure: if mean residual is large, prefer bins above mean.
    if (bin_residual as f64) > mean_residual {
        score -= 3.0;
    } else {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
