pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for the
    // minimum plausible item are "dead". Penalize them super-linearly.
    let min_item = 1u32;
    if post_residual > 0 && post_residual < min_item.max(1) * 10 {
        score += 40.0 * (1.0 - (post_residual as f64) / 10.0);
    }
    // Perfect fit is heavily rewarded.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Reward leaving a gap that the lookahead item could exactly fill.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 15.0;
    }
    // Penalize if post_residual is just below the next item (near-dead space).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 6.0;
    }

    // Tightness reward: fraction of the bin consumed by this placement.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 10.0 * fill_ratio;

    // Open-bin pressure: discourage scattering when many bins are open;
    // encourage using existing bins rather than opening new ones.
    score += (open_bins_count as f64).ln().max(0.0) * 2.0;

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: make it attractive only when no open bin fits well,
    // i.e. when mean residual is small relative to the item.
    if bin_residual == bin_capacity {
        let tight_open = mean_residual < item_size as f64;
        if tight_open {
            score -= 8.0;
        } else {
            score += 10.0;
        }
    }

    // Mild stream-progression bias: as the stream matures, prefer
    // consolidating into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 5.0 * progress;
    }

    score
}

