pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual)
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio;

    // 2-step lookahead: reward if next item fits the post_residual exactly-ish
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let next_fit = next_item_size as f64 / post_residual.max(1) as f64;
            // perfect chain (post_residual == next_item_size) heavily rewarded
            score -= 25.0 * next_fit * next_fit;
            // penalize leaving awkward residual for the next item
            let leftover = post_residual - next_item_size;
            if leftover > 0 && leftover < 10 {
                score += 12.0; // tiny dead space after next placement
