        score -= 5.0;
    }

    // Compare against mean residual: bins with residual near mean are "normal";
    // penalize picking bins far below mean (wasting a tight bin on loose fit)
    let dev = post_residual as f64 - mean_residual;
    score += 0.10 * dev.abs();

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when no open bin is a good fit
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 20.0;
        } else {
            // discourage opening new bins when fits exist, unless fits are terrible
            let best_possible = item_size as f64;
            let wasted = (bin_capacity as f64 - best_possible) - post_residual as f64;
            score += 15.0 + 0.2 * mean_residual;
            let _ = wasted;
        }
    }

    // Late-stream consolidation: fewer open bins preferred as stream ends
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    // Penalize very small residuals that become dead space
    if post_residual > 0 && post_residual < 10 {
        score += 8.0 * (10 - post_residual) as f64;
    }

    score
}

