pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: shrink score as post_residual approaches 0.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space that is too small for the smallest plausible item (size 1..100 unknown,
    // but small residuals below item_size-ish are wasted): quadratic dead-space penalty.
    if post_residual > 0 {
        let dead = post_residual as f64 / bin_capacity as f64;
        score += 6.0 * dead * dead;
    }

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead: if the next item fits the post residual exactly-ish, reward strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let pair_slack = (post_residual - next_item_size) as f64;
        score -= 14.0 / (1.0 + pair_slack);
    }
    // If next item does NOT fit post residual, mild penalty for stranding space.
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 4.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a new bin is expensive; penalize it
    // unless the item fits badly everywhere (large post_residual relative to capacity).
    if bin_residual == bin_capacity {
        let waste = post_residual as f64 / bin_capacity as f64;
        score += 30.0 - 24.0 * waste * waste;
        if open_bins_count == 0 {
            score -= 40.0; // must open first bin
        }
    }

    // Global state: many open bins with high mean residual -> prefer reusing bins,
    // penalize adding more capacity when existing bins are loose.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let crowded = (open_bins_count as f64 / 10.0).min(3.0);
    score += 2.0 * crowded * (mean_residual / bin_capacity as f64) * (1.0 - 0.5 * progress);

    // Early in stream: mild preference for consolidating (fewer bins); late: keep flexibility.
    score -= 5.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
