pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let nxt = next_item_size as f64;

    // Base: prefer small post residual (tight fit)
    let mut score = post;

    // Non-linear tightness reward: quadratic coupling of fill ratio with progress
    let fill = item / cap;
    score -= 8.0 * fill * fill * (0.5 + progress);

    // Reward exact-ish fits superlinearly
    let tightness = 1.0 - post / cap;
    score -= 4.0 * tightness * tightness * tightness;

    // Lookahead: if next item fits in post residual, reward this placement
    if nxt > 0.0 && nxt <= post {
        let chain = nxt / cap;
        score -= 3.0 * chain * (1.0 + progress);
    } else if nxt > post {
        // Penalize creating residual that cannot chain the next item, weighted by waste
        score += 2.0 * (post / cap) * (1.0 - progress);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 6.0 + 4.0 * progress;
    }

    // New-bin candidate: penalize opening a new bin unless it's early or residuals are badly fragmented
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / cap).clamp(0.0, 1.0);
        let pressure = (open_bins_count as f64).ln().max(0.0);
        score += 10.0 + pressure - 6.0 * fragmentation * (1.0 - progress);
        // Late stream: discourage new bins even more
        score += 8.0 * progress * progress;
    }

    // Mild preference for bins with below-mean residual (consolidate waste)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 2.0 * dev * (0.5 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
