pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: post_residual mod 10.
    // Residuals in friendly classes (0, 10, 20, ...) are reusable by typical
    // item sizes; awkward residuals (1..9) become dead space.
    let class = post_residual % 10;
    let awkward = (class != 0) as f64;
    score += awkward * 6.0;

    // Strong reward for exact fit (perfect packing).
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward small post_residual in a "good" harmonic class (multiple of 10).
    if class == 0 && post_residual > 0 {
        score -= 12.0;
    }

    // Lookahead: if the next item fits exactly into the post residual,
    // strongly prefer this bin (chained perfect fits).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size <= post_residual {
            // next item fits, but check harmonic compatibility of the chain
            let next_leftover = post_residual - next_item_size;
            if next_leftover % 10 == 0 {
                score -= 10.0;
            } else {
                score += 4.0;
            }
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless post_residual would be tiny dead space).
    if fitting_bins_count == 1 {
        score -= 18.0;
        if post_residual < 10 && post_residual > 0 {
            score -= 6.0; // nearly-full bin is fine to exhaust
        }
    }

    // Penalize wasting a large residual on a small item (poor density).
    let density = item_size as f64 / bin_residual as f64;
    if density < 0.4 {
        score += (0.4 - density) * 30.0;
    }

    // New-bin candidate handling: an empty bin gets a mild premium so we only
    // open new bins when open bins offer genuinely bad fits.
    if bin_residual == bin_capacity {
        score += 8.0 + 0.05 * open_bins_count as f64;
    }

    // Late in the stream, prefer consolidating into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 3.0 * awkward;

    // Prefer bins below mean residual (tighter bins first) to preserve
    // flexible large-residual bins for large future items.
    score += 0.05 * (mean_residual - bin_residual as f64).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let next = next_item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items.max(1) as f64 } else { 0.0 };
    let post_norm = pr / cap;
    let fit_ratio = item_size as f64 / cap;
    let gap = (bin_residual - item_size) as f64 / cap;
    let mut score = post_norm * post_norm * 52.0 + post_norm * 20.0;

    // ---- 2-step lookahead: shape score around the NEXT item ----
    if next > 0.0 {
        if pr == next {
            score -= 54.0;
        } else if pr > next {
            let slack = pr - next;
            let diff = slack / cap;
            score -= 20.0 * (1.0 - diff).max(0.0);
            score -= (-diff * diff * 470.0).exp() * 24.0 * (1.0 - progress * 0.5);
            if diff < 0.04 {
                score -= (0.04 - diff) * 30.0 * (0.6 + progress * 0.6);
            } else if diff > 0.16 {
                score += (diff - 0.16) * 8.0 * (0.5 + progress);
            }
        } else if pr > 0.0 {
            let dead_ratio = (next - pr) / cap;
            score += dead_ratio * 92.0 * (0.6 + progress * 0.6);
        }
    }

    // ---- Absolute dead-floor guard: tiny stranded remainders ----
    let dead_floor = if next_item_size > 0 { (next_item_size.min(12) as f64).max(6.0) } else { 10.0 };
    if post_residual > 0 && pr < dead_floor && pr != next {
        score += 64.0 * (1.0 - progress * 0.3);
    } else if post_residual > 0 && post_residual < 20 && pr != next {
        score += 25.0;
    }

    // ---- Relative-to-mean coupling ----
    if pr > 0.0 {
        let dev = (mean_residual - pr) / cap;
        if dev > 0.05 {
            score += (dev - 0.05) * 12.0 * (0.4 + progress);
        } else if dev < -0.08 {
            score += (-dev - 0.08) * 6.0 * (1.0 - progress);
        }
    }

    // ---- New-bin candidate decision ----
    if bin_residual == bin_capacity {
        let others = if fitting_bins_count > 0 { fitting_bins_count - 1 } else { 0 };
        let size_pull = fit_ratio * 14.0;
        if fitting_bins_count <= 2 && gap > 0.0 {
            score -= (18.0 + size_pull) * (1.0 - progress * 0.6);
        } else if others == 0 {
            score -= 5.0;
        } else {
            score += 20.0 + open_bins_count as f64 * (0.5 + 0.5 * progress);
        }
        if next > 0.0 && fitting_bins_count <= 3 && fit_ratio >= next * 0.95 / cap {
            score -= 5.5 * (1.0 - progress * 0.5);
        }
        if next > 0.0 && fitting_bins_count >= 1 && fit_ratio * cap + next > cap {
            score += 8.0 * (1.0 - progress * 0.4);
        }
        if next > 0.0 && fit_ratio * cap + next <= cap {
            let pair_left = (cap - fit_ratio * cap - next) / cap;
            if pair_left < 0.05 {
                score -= (0.05 - pair_left) * 42.0 * (0.5 + progress * 0.5);
            } else if fit_ratio > 0.35 {
                score -= 3.0 * (1.0 - progress);
            }
        }
        if fit_ratio > 0.5 && progress < 0.5 {
            score -= 6.0 * (1.0 - progress);
        }
        if progress > 0.85 && fit_ratio > 0.6 {
            score -= 4.0 * (progress - 0.85) * 20.0;
        }
        // Strong pair-closure pull — new bin attractive only when item+next nearly fill capacity.
        if next > 0.0 && fit_ratio * cap + next > cap * 0.94 && fitting_bins_count > 2 {
            score -= 6.0 * (1.0 - progress * 0.5);
        }
        // Resist opening bins late in the stream unless the item is huge.
        if progress > 0.6 && fit_ratio < 0.45 && others > 0 {
            score += 10.0 * (progress - 0.6) / 0.4;
        }
        // NEW: resist new bins whose future residual would be a dead band for the next item.
        if next > 0.0 && fit_ratio * cap + next <= cap {
            let fut = cap - fit_ratio * cap - next;
            if fut > 0.0 && fut < next && fut < 10.0 {
                score += 9.0 * (1.0 - fut / 10.0) * (0.5 + progress * 0.5);
            }
        }
    }

    // Exact / near-exact fit bonuses.
    if pr == 0.0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 42.0;
    } else if post_residual <= 9 {
        score -= 18.0 * (1.0 - progress * 0.4);
    } else if post_norm < 0.02 && fitting_bins_count >= 4 {
        score -= 6.0 * (1.0 - progress);
    }

    // Sharp bonus for leaving a tiny gap (<12% of capacity).
    if gap > 0.0 && gap < 0.12 {
        score -= (0.12 - gap) * 48.0;
    } else if gap >= 0.12 && gap < 0.22 && next > 0.0 && pr > 0.0 && pr < next {
        score += (gap - 0.12) * 90.5 * (0.5 + progress);
    } else if gap >= 0.12 && gap < 0.22 && fitting_bins_count <= 3 {
        score += (gap - 0.12) * 18.0 * (0.5 + progress * 0.5);
    }
    if gap >= 0.22 && gap < 0.30 && fitting_bins_count <= 2 {
        score += (gap - 0.22) * 22.0 * (0.6 + progress * 0.4);
    }
    // Next-item chain: leftover after next item nearly closes bin.
    if next > 0.0 && gap > 0.12 {
        let nxt_gap = ((gap * cap - next).max(0.0)) / cap;
        if nxt_gap < 0.05 {
            score -= (0.05 - nxt_gap) * 42.0 * (0.5 + progress * 0.5);
        }
    }

    // Reward large items filling bins deeply.
    score -= fit_ratio * fit_ratio * 6.0;

    // Congestion: many competing bins => penalize sloppy fits.
    if fitting_bins_count > 2 {
        score += gap * 6.5 * ((fitting_bins_count.min(12) as f64 - 2.0) / 10.0);
    }
    if open_bins_count > 8 {
        score += post_norm * 5.0 * ((open_bins_count.min(20) as f64 - 8.0) / 12.0);
    }

    // Late-stream consolidation.
    if progress > 0.7 && post_norm > 0.25 {
        score += (post_norm - 0.25) * 6.0 * (progress - 0.7) / 0.3;
    }

    // Last-chance bonus: prefer a bin that would otherwise be wasted.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 - fit_ratio);
    }

    // Deep fill bonus.
    let fill_r = item_size as f64 / bin_residual.max(1) as f64;
    if fill_r > 0.90 && bin_residual != bin_capacity {
        score -= (fill_r - 0.90) * 18.0 * (0.6 + progress * 0.5);
    }

    // Waste-vs-mean term.
    if pr > 0.0 && mean_residual > 0.0 {
        let waste = post_norm - mean_residual / cap;
        if waste > 0.0 {
            score += waste * 30.0 * (0.4 + progress * 0.6);
        } else {
            score -= (-waste) * 10.0;
        }
    }

    // Penalize bins whose post-residual can never host the next item class.
    if pr > 0.0 && next > 0.0 && pr < next && post_norm > 0.03 {
        score += (next - pr) / cap * 20.0 * (0.5 + progress * 0.5);
    }

    // Reward bins that remain exactly reusable by the next item.
    if next > 0.0 && pr > 0.0 && (pr - next) / cap < 0.02 && pr >= next {
        score -= 6.0 * (1.0 - (pr - next) / cap / 0.02) * (0.5 + progress);
    }

    // Periodic divisibility bonus — post-residual is a near-multiple of next item.
    if next > 0.0 && pr > 0.0 && pr >= next {
        let frac = ((pr - next) % next.max(1.0)) / next.max(1.0);
        if frac < 0.08 {
            score -= 10.0 * (1.0 - progress * 0.5);
        }
    }

    // Double-fit bonus — post-residual hosts the next item twice with little slack.
    if next > 0.0 && pr >= next * 2.0 && pr < next * 2.0 + 8.0 {
        score -= 8.0 * (1.0 - progress * 0.4);
    }

    // Last-chance micro-gap bonus.
    if fitting_bins_count == 1 && gap > 0.0 && gap < 0.06 {
        score -= 7.0 * (1.0 - progress * 0.5);
    }

    // Dead-space penalty when few fitting bins and residual too small for next.
    if next > 0.0 && post_residual > 0 && (post_residual as u32) < next_item_size && fitting_bins_count <= 2 {
        score += 18.0 * (1.0 - progress * 0.5);
    }

    // Chain-closure — residual after placing item can host next item with tiny slack.
    if next > 0.0 && pr >= next && fitting_bins_count > 1 {
        let chain = pr - next;
        if chain < mean_residual.max(1.0) * 0.35 {
            score -= 5.0 * (1.0 - chain / (mean_residual.max(1.0) * 0.35)) * (0.5 + progress * 0.5);
        }
    }

    // Mid-band residual vacuum — pull items into bins whose post-residual lands
    // in the 0.03–0.10 band only when the next item can still fit there later.
    if post_norm > 0.03 && post_norm < 0.10 {
        if next > 0.0 && pr >= next {
            score -= 4.0 * (1.0 - progress * 0.5);
        } else {
            score += 6.0 * (0.5 + progress * 0.5);
        }
    }

    // NEW: dead-space ratio coupling — penalize proportionally wasted residual
    // relative to the next item, scaled by stream progress (combats dead space).
    if next > 0.0 && pr > 0.0 && pr < next {
        let waste_ratio = (next - pr) / next;
        score += waste_ratio * 14.0 * (0.4 + progress * 0.6);
    }

    // NEW: exact post-residual == next-item match is the ideal chain — strengthen.
    if next > 0.0 && pr == next {
        score -= 12.0 * (1.0 - progress * 0.3);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: hard penalty for unusable small gaps
    // (gaps below the minimum plausible item size are pure waste).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Penalize moderately small gaps that are unlikely to fit future items.
    if post_residual >= 10 && post_residual < 30 {
        score += 18.0 * (1.0 - (post_residual as f64 - 10.0) / 20.0);
    }

    // Reward exact/near-exact fits strongly.
    if post_residual == 0 {
        score -= 45.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Lookahead coupling: if the next item fits the post-residual exactly-ish,
    // reward this placement (keeps chain packing viable).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size && post_residual - next_item_size < 10 {
            score -= 12.0;
        }
        // If next item cannot fit here anyway, mild reward for keeping residual usable.
        if next_item_size > post_residual && post_residual > 0 && post_residual < 10 {
            score += 10.0;
        }
    }

    // Open-bin pressure: when many bins are open, prefer filling existing ones
    // (penalize the new-bin candidate implicitly via residual==capacity handling,
    // but also add pressure scaled by open bins count to all scores equally is
    // useless; instead penalize leaving large residuals when few bins are open
    // less, and penalize wasteful placement more when many bins are open).
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (0.3 + 0.7 * progress);
    score += pressure * (post_residual as f64 / bin_capacity as f64);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when current bins are tight
    // or the fit would be terrible.
    if bin_residual == bin_capacity {
        // Base handicap so open bins with decent fits win.
        score += 15.0;
        // But if mean residual is small (bins nearly full), a new bin is fine.
        score -= mean_residual.clamp(0.0, bin_capacity as f64) * 0.4;
        // Late in the stream with many open bins, opening a fresh bin is cheaper
        // than forcing a bad fit.
        if progress > 0.5 && open_bins_count > 3 {
            score -= 8.0;
        }
    }

    // Mean-residual alignment: prefer bins whose residual is close to the mean
    // (balanced packing), slightly.
    score += ((bin_residual as f64 - mean_residual) / bin_capacity as f64).abs() * 4.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward exact 2-step lookahead match: post_residual == next_item_size
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post_residual as f64 - nxt).abs();
        if diff == 0.0 {
            score -= 50.0;
        } else if post_residual as u32 >= next_item_size {
            // next item fits: reward closeness of match
            score -= 20.0 * (1.0 - diff / (bin_capacity as f64));
        } else {
            // dead space too small for next item: penalize
            score += 15.0 + diff * 0.3;
        }
    }

    // Favor bins tighter than the mean residual (best-fit flavor)
    score += (mean_residual - post_residual as f64) * 0.4;

    // Last-chance bin before opening a new bin: reward using it
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // New-bin candidate: penalize moderately so it's only chosen when open bins are bad
    if bin_residual == bin_capacity {
        score += 25.0;
        // but if current item is large, new bin is attractive
        score -= item_size as f64 * 0.2;
    }

    // Late in stream: consolidate, avoid leaving many small residuals
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual < 10 {
        score += 10.0 * progress; // tiny dead space penalized more later
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
