pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Lookahead: strongly reward when the next item exactly fills the post residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect two-item pairing
        } else if next_item_size <= post_residual {
            // leftover after next item: penalize by how much dead space remains
            score -= 25.0 + 0.15 * (post_residual - next_item_size) as f64;
        } else {
            // next item can't use this bin's remainder
            score += 10.0 + 0.2 * (next_item_size - post_residual) as f64;
        }
    }

    // Penalize tight fits that leave unusable slivers (1..10 dead space)
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Reward perfect closure
    if post_residual == 0 {
        score -= 20.0;
    }

    // Compare against mean residual: prefer bins with more residual than average
    // (keeps tight bins for small items), but only mildly.
    score += 0.25 * (mean_residual - bin_residual as f64);

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin, especially early in the stream
    // when many open bins still have room. Overridable only by excellent lookahead.
    if bin_residual == bin_capacity {
        score += 45.0 + 5.0 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size <= (bin_capacity - item_size) {
            score -= 35.0; // fresh bin pairs well with the next item
        }
    }

    // Late-stream pressure: consolidate as the stream ends
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (bin_residual - item_size) as f64 / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let next = next_item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items.max(1) as f64 } else { 0.0 };
    let post_norm = pr / cap;
    let fit_ratio = item_size as f64 / cap;
    let gap = (bin_residual - item_size) as f64 / cap;
    let mut score = post_norm * post_norm * 52.0 + post_norm * 20.0;

    // ---- 2-step lookahead: shape score around the NEXT item ----
    if next > 0.0 {
        if pr == next {
            score -= 56.0;
        } else if pr > next {
            let slack = pr - next;
            let diff = slack / cap;
            score -= 20.0 * (1.0 - diff).max(0.0);
            score -= (-diff * diff * 470.0).exp() * 24.0 * (1.0 - progress * 0.5);
            if diff < 0.04 {
                score -= (0.04 - diff) * 32.0 * (0.6 + progress * 0.6);
            } else if diff > 0.16 {
                score += (diff - 0.16) * 9.0 * (0.5 + progress);
            }
        } else if pr > 0.0 {
            let dead_ratio = (next - pr) / cap;
            score += dead_ratio * 92.0 * (0.6 + progress * 0.6);
        }
    }

    // ---- Absolute dead-floor guard: tiny stranded remainders ----
    let dead_floor = if next_item_size > 0 { (next_item_size.min(12) as f64).max(6.0) } else { 10.0 };
    if post_residual > 0 && pr < dead_floor && pr != next {
        score += 64.0 * (1.0 - progress * 0.3);
    } else if post_residual > 0 && post_residual < 20 && pr != next {
        score += 25.0;
    }

    // ---- Relative-to-mean coupling ----
    if pr > 0.0 {
        let dev = (mean_residual - pr) / cap;
        if dev > 0.05 {
            score += (dev - 0.05) * 12.0 * (0.4 + progress);
        } else if dev < -0.08 {
            score += (-dev - 0.08) * 6.0 * (1.0 - progress);
        }
    }

    // ---- New-bin candidate decision ----
    if bin_residual == bin_capacity {
        let others = if fitting_bins_count > 0 { fitting_bins_count - 1 } else { 0 };
        let size_pull = fit_ratio * 14.0;
        if fitting_bins_count <= 2 && gap > 0.0 {
            score -= (18.0 + size_pull) * (1.0 - progress * 0.6);
        } else if others == 0 {
            score -= 5.0;
        } else {
            score += 20.0 + open_bins_count as f64 * (0.5 + 0.5 * progress);
        }
        if next > 0.0 && fitting_bins_count <= 3 && fit_ratio >= next * 0.95 / cap {
            score -= 5.5 * (1.0 - progress * 0.5);
        }
        if next > 0.0 && fitting_bins_count >= 1 && fit_ratio * cap + next > cap {
            score += 8.0 * (1.0 - progress * 0.4);
        }
        if next > 0.0 && fit_ratio * cap + next <= cap {
            let pair_left = (cap - fit_ratio * cap - next) / cap;
            if pair_left < 0.05 {
                score -= (0.05 - pair_left) * 42.0 * (0.5 + progress * 0.5);
            } else if fit_ratio > 0.35 {
                score -= 3.0 * (1.0 - progress);
            }
        }
        if fit_ratio > 0.5 && progress < 0.5 {
            score -= 6.0 * (1.0 - progress);
        }
        if progress > 0.85 && fit_ratio > 0.6 {
            score -= 4.0 * (progress - 0.85) * 20.0;
        }
        // Strong pair-closure pull — new bin attractive only when item+next nearly fill capacity.
        if next > 0.0 && fit_ratio * cap + next > cap * 0.94 && fitting_bins_count > 2 {
            score -= 6.0 * (1.0 - progress * 0.5);
        }
        // Resist opening bins late in the stream unless the item is huge.
        if progress > 0.6 && fit_ratio < 0.45 && others > 0 {
            score += 10.0 * (progress - 0.6) / 0.4;
        }
        // NEW: strong new-bin pull when item nearly fills the empty bin exactly.
        if fit_ratio > 0.92 {
            score -= (fit_ratio - 0.92) * 60.0;
        }
    }

    // Exact / near-exact fit bonuses.
    if pr == 0.0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 42.0;
    } else if post_residual <= 9 {
        score -= 18.0 * (1.0 - progress * 0.4);
    } else if post_norm < 0.02 && fitting_bins_count >= 4 {
        score -= 6.0 * (1.0 - progress);
    }

    // Sharp bonus for leaving a tiny gap (<12% of capacity).
    if gap > 0.0 && gap < 0.12 {
        score -= (0.12 - gap) * 48.0;
    } else if gap >= 0.12 && gap < 0.22 && next > 0.0 && pr > 0.0 && pr < next {
        score += (gap - 0.12) * 90.5 * (0.5 + progress);
    } else if gap >= 0.12 && gap < 0.22 && fitting_bins_count <= 3 {
        score += (gap - 0.12) * 18.0 * (0.5 + progress * 0.5);
    }
    if gap >= 0.22 && gap < 0.30 && fitting_bins_count <= 2 {
        score += (gap - 0.22) * 22.0 * (0.6 + progress * 0.4);
    }
    // Next-item chain: leftover after next item nearly closes bin.
    if next > 0.0 && gap > 0.12 {
        let nxt_gap = ((gap * cap - next).max(0.0)) / cap;
        if nxt_gap < 0.05 {
            score -= (0.05 - nxt_gap) * 42.0 * (0.5 + progress * 0.5);
        }
    }

    // Reward large items filling bins deeply.
    score -= fit_ratio * fit_ratio * 6.0;

    // Congestion: many competing bins => penalize sloppy fits.
    if fitting_bins_count > 2 {
        score += gap * 6.5 * ((fitting_bins_count.min(12) as f64 - 2.0) / 10.0);
    }
    if open_bins_count > 8 {
        score += post_norm * 5.0 * ((open_bins_count.min(20) as f64 - 8.0) / 12.0);
    }

    // Late-stream consolidation.
    if progress > 0.7 && post_norm > 0.25 {
        score += (post_norm - 0.25) * 6.0 * (progress - 0.7) / 0.3;
    }

    // Last-chance bonus: prefer a bin that would otherwise be wasted.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 - fit_ratio);
    }

    // Deep fill bonus.
    let fill_r = item_size as f64 / bin_residual.max(1) as f64;
    if fill_r > 0.90 && bin_residual != bin_capacity {
        score -= (fill_r - 0.90) * 18.0 * (0.6 + progress * 0.5);
    }

    // Waste-vs-mean term.
    if pr > 0.0 && mean_residual > 0.0 {
        let waste = post_norm - mean_residual / cap;
        if waste > 0.0 {
            score += waste * 30.0 * (0.4 + progress * 0.6);
        } else {
            score -= (-waste) * 10.0;
        }
    }

    // Penalize bins whose post-residual can never host the next item class.
    if pr > 0.0 && next > 0.0 && pr < next && post_norm > 0.03 {
        score += (next - pr) / cap * 20.0 * (0.5 + progress * 0.5);
    }

    // Reward bins that remain exactly reusable by the next item.
    if next > 0.0 && pr > 0.0 && (pr - next) / cap < 0.02 && pr >= next {
        score -= 6.0 * (1.0 - (pr - next) / cap / 0.02) * (0.5 + progress);
    }

    // Periodic divisibility bonus — post-residual is a near-multiple of next item.
    if next > 0.0 && pr > 0.0 && pr >= next {
        let frac = ((pr - next) % next.max(1.0)) / next.max(1.0);
        if frac < 0.08 {
            score -= 10.0 * (1.0 - progress * 0.5);
        }
    }

    // Double-fit bonus — post-residual hosts the next item twice with little slack.
    if next > 0.0 && pr >= next * 2.0 && pr < next * 2.0 + 8.0 {
        score -= 8.0 * (1.0 - progress * 0.4);
    }

    // Last-chance micro-gap bonus.
    if fitting_bins_count == 1 && gap > 0.0 && gap < 0.06 {
        score -= 7.0 * (1.0 - progress * 0.5);
    }

    // Dead-space penalty when few fitting bins and residual too small for next.
    if next > 0.0 && post_residual > 0 && (post_residual as u32) < next_item_size && fitting_bins_count <= 2 {
        score += 18.0 * (1.0 - progress * 0.5);
    }

    // Chain-closure — residual after placing item can host next item with minimal slack.
    if next > 0.0 && pr >= next && fitting_bins_count > 1 {
        let chain = pr - next;
        if chain < mean_residual.max(1.0) * 0.35 {
            score -= 5.0 * (1.0 - chain / (mean_residual.max(1.0) * 0.35)) * (0.5 + progress * 0.5);
        }
    }

    // Mid-band residual vacuum — pull items into bins whose post-residual lands
    // in the 0.03–0.10 band only when the next item can still fit there later.
    if post_norm > 0.03 && post_norm < 0.10 {
        if next > 0.0 && pr >= next {
            score -= 4.0 * (1.0 - progress * 0.5);
        } else {
            score += 6.0 * (0.5 + progress * 0.5);
        }
    }

    // NEW: exact-fill chain — post-residual equals next item twice over with tiny slack.
    if next > 0.0 && pr > 0.0 && (pr as u32) % (next as u32).max(1) == 0 && pr <= cap * 0.15 {
        score -= 7.0 * (1.0 - progress * 0.4);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual means less wasted space.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 0.6 * tightness * (item_size as f64);

    // Penalize dead space: post_residual that is small but unusable (< min item size 1..10)
    if post_residual < 10 && post_residual > 0 {
        score += 8.0;
    }

    // Lookahead: penalize if the next item cannot fit in the post residual.
    if next_item_size > 0 {
        if next_item_size > post_residual {
            score += 6.0 + 0.15 * (next_item_size as f64);
        } else {
            // Reward bins that can also host the next item (chaining).
            score -= 0.25 * (1.0 - (post_residual as f64 - next_item_size as f64) / bin_capacity as f64);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Prefer fuller bins relative to the fleet mean residual.
    score += 0.1 * (mean_residual - bin_residual as f64);

    // Penalize opening a new bin when existing bins fit, scaled by how many open bins exist.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 + 20.0 * progress + 0.5 * open_bins_count as f64;
        // If no open bin fits (fitting_bins_count==0 for the new-bin call context), soften.
        if fitting_bins_count == 0 {
            score -= 25.0;
        }
    }

    // Mild global pressure: many open bins -> favor consolidating into existing bins.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;

    // Base: prefer small post_residual, with non-linear (quadratic) tightening.
    let mut score = post * (1.0 + 2.0 * norm_post * (1.0 - progress));

    // Smooth coupling of post_residual with stream progress:
    // late in the stream, dead space matters more.
    score += 30.0 * norm_post * norm_post * progress;

    // Lookahead: penalize residuals that cannot host the next item,
    // reward residuals that can, scaled by how well they match.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual >= next_item_size {
            let fit_quality = 1.0 - ((post - nxt) / cap);
            score -= 12.0 * fit_quality * (1.0 - progress);
        } else {
            let gap = (nxt - post) / cap;
            score += 20.0 * gap * gap;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        let waste = norm_post;
        score -= 25.0 * (1.0 - waste * waste);
    }

    // New-bin candidate handling: make the empty bin unattractive when a
    // reasonable fit exists, but attractive when the best fit would waste a lot.
    if bin_residual == bin_capacity {
        score = cap * 1.5 + 40.0 * norm_post;
        if next_item_size > 0 && item_size as f64 / cap > 0.6 {
            score -= 35.0;
        }
    } else {
        // Mild penalty for spreading across many bins when residuals are fragmented.
        let frag = (mean_residual / cap - 0.5).abs();
        score += 5.0 * frag * frag * (open_bins_count as f64).ln();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual).
    // Harmonic class of the post-residual: classify dead space by modulo classes.
    let pr = post_residual;
    let cap = bin_capacity as f64;

    // Class A: post_residual divisible by 10 -> "clean" residual, more likely
    // to be exactly filled by future items (sizes often align to decade grid).
    let clean = (pr % 10 == 0) as i32;

    // Class B: post_residual in "harmonic sweet spots" that many item sizes
    // can tile: divisible by 5, or by 20, or by 25.
    let sweet = ((pr % 5 == 0) as i32) + ((pr % 20 == 0) as i32) + ((pr % 25 == 0) as i32);

    // Reward harmonic alignment: subtract bonus per harmonic level.
    score -= 6.0 * clean as f64;
    score -= 3.0 * sweet as f64;

    // Penalize "prime-like" dead space: post_residual coprime-ish to common
    // item granularities (not divisible by 2, 3, 5) -> hard to fill later.
    let ugly = ((pr % 2 != 0) as i32) + ((pr % 3 != 0) as i32) + ((pr % 5 != 0) as i32);
    score += 2.5 * ugly as f64;

    // Integer-division threshold: residual buckets via pr / 10.
    let bucket = pr / 10;
    // Buckets 0..2 (tiny dead space) are excellent; large buckets are waste.
    score += match bucket {
        0 => -8.0,
        1 => -4.0,
        2 => 0.0,
        3..=5 => 3.0,
        _ => 6.0,
    } as f64;

    // Lookahead coupling: if next_item_size fits exactly into post_residual,
    // this is a perfect pair — strong reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 15.0;
        } else if pr >= next_item_size {
            let rem2 = pr - next_item_size;
            // Reward if the chain continues harmonically.
            if rem2 % 10 == 0 { score -= 5.0; }
            score += rem2 as f64 * 0.3;
        } else {
            // Next item cannot use this residual at all: penalize proportionally.
            score += (next_item_size as f64) * 0.15;
        }
    }

    // Fraction-of-capacity coupling: residual as fraction of capacity.
    let frac = pr as f64 / cap;
    if frac < 0.05 { score -= 6.0; }        // nearly full bin: great
    else if frac > 0.5 { score += 5.0 * frac; } // half-empty: wasteful placement

    // Last-chance bin: if this is the only fitting bin, strongly prefer using
    // it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: an empty bin has maximal residual; make it
    // unattractive unless existing bins are all poor fits (high mean residual
    // spread or the item is large relative to mean residual).
    if bin_residual == bin_capacity {
        // Baseline penalty for opening a new bin.
        let mut new_bin_score = 55.0;
        // If the item is big (>= 50% capacity), a fresh bin is often good.
        if item_size * 2 >= bin_capacity {
            new_bin_score -= 15.0;
        }
        // If mean residual of open bins is small (bins are tight), new bin helps.
        if mean_residual < item_size as f64 * 1.2 {
            new_bin_score -= 20.0;
        }
        // Late in the stream, avoid bin proliferation.
        let progress = step_index as f64 / total_items.max(1) as f64;
        new_bin_score += 10.0 * progress;
        // Many open bins already: discourage another.
        new_bin_score += open_bins_count as f64 * 1.5;
        score = new_bin_score;
    }

    // Mild global regularization.
    score += 0.01 * (post_residual as f64) * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let next = next_item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items.max(1) as f64 } else { 0.0 };
    let post_norm = pr / cap;
    let fit_ratio = item_size as f64 / cap;
    let gap = (bin_residual - item_size) as f64 / cap;
    let mut score = post_norm * post_norm * 52.0 + post_norm * 20.0;

    // Exact / near-exact fit bonuses (strong, from best-known).
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 42.0;
    } else if post_residual <= 9 {
        score -= 18.0 * (1.0 - progress * 0.4);
    }

    // Small stranded residual floors: anything below the next item's size
    // that is tiny is dead space.
    let dead_floor = if next_item_size > 0 { (next_item_size.min(12) as f64).max(6.0) } else { 10.0 };
    if post_residual > 0 && pr < dead_floor && pr != next {
        score += 62.0 * (1.0 - progress * 0.3);
    } else if post_residual > 0 && post_residual < 20 && pr != next {
        score += 25.0;
    }

    // ---- 2-step lookahead around the NEXT item ----
    if next > 0.0 {
        if pr == next {
            score -= 45.0;
        } else if pr > next {
            let slack = (pr - next) / cap;
            score -= (-slack * slack * 450.0).exp() * 24.0 * (1.0 - progress * 0.5);
            if slack < 0.05 {
                score -= (0.05 - slack) * 40.0 * (0.5 + progress * 0.5);
            } else if slack > 0.16 {
                score += (slack - 0.16) * 8.0 * (0.5 + progress);
            }
            // Repeatability: remainder divisible-ish by next item.
            let nxt = next.max(1.0);
            let frac = ((pr - next) % nxt) / nxt;
            if frac < 0.08 {
                score -= 10.0 * (1.0 - progress * 0.5);
            }
            // Two next-items fit.
            if pr >= next * 2.0 && pr < next * 2.0 + 8.0 {
                score -= 8.0 * (1.0 - progress * 0.4);
            }
        } else {
            // Next item does NOT fit in the remainder: penalize dead space.
            let dead_ratio = (next - pr) / cap;
            if post_norm > 0.03 {
                score += dead_ratio * 90.0 * (0.6 + progress * 0.6);
            }
            if fitting_bins_count <= 2 {
                score += 18.0 * (1.0 - progress * 0.5);
            }
        }
    }

    // ---- Relative-to-mean coupling ----
    if post_residual > 0 && mean_residual > 0.0 {
        let waste = post_norm - mean_residual / cap;
        if waste > 0.0 {
            score += waste * 30.0 * (0.4 + progress * 0.6);
        } else {
            score -= (-waste) * 10.0;
        }
    }

    // ---- New-bin candidate decision ----
    if bin_residual == bin_capacity {
        let size_pull = fit_ratio * 14.0;
        if fitting_bins_count <= 2 {
            score -= (18.0 + size_pull) * (1.0 - progress * 0.6);
        } else {
            score += 20.0 + open_bins_count as f64 * (0.5 + 0.5 * progress);
        }
        if next > 0.0 && fitting_bins_count <= 3 && fit_ratio >= next / cap * 0.95 {
            score -= 5.5 * (1.0 - progress * 0.5);
        }
        if next > 0.0 && fit_ratio + next / cap > 1.0 {
            score += 8.0 * (1.0 - progress * 0.4);
        }
        if fit_ratio > 0.5 && progress < 0.5 {
            score -= 6.0 * (1.0 - progress);
        }
        if progress > 0.85 && fit_ratio > 0.6 {
            score -= 4.0 * (progress - 0.85) * 20.0;
        }
        if next > 0.0 && fit_ratio + next / cap <= 1.0 && fit_ratio > 0.35 {
            score -= 3.0 * (1.0 - progress);
        }
    }

    // Sharp bonus for leaving a tiny gap.
    if gap > 0.0 && gap < 0.12 {
        score -= (0.12 - gap) * 48.0;
    } else if gap >= 0.12 && gap < 0.22 && fitting_bins_count <= 3 {
        score += (gap - 0.12) * 18.0 * (0.5 + progress * 0.5);
    }
    if gap >= 0.22 && gap < 0.30 && fitting_bins_count <= 2 {
        score += (gap - 0.22) * 22.0 * (0.6 + progress * 0.4);
    }

    // Reward large items filling bins deeply.
    score -= fit_ratio * fit_ratio * 6.0;

    // Congestion.
    if fitting_bins_count > 2 {
        score += gap * 6.5 * ((fitting_bins_count.min(12) as f64 - 2.0) / 10.0);
    }
    if open_bins_count > 8 {
        score += post_norm * 5.0 * ((open_bins_count.min(20) as f64 - 8.0) / 12.0);
    }

    // Late-stream consolidation.
    if progress > 0.7 && post_norm > 0.25 {
        score += (post_norm - 0.25) * 6.0 * (progress - 0.7) / 0.3;
    }

    // Last-chance bonus.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 - fit_ratio);
        if gap > 0.0 && gap < 0.06 {
            score -= 7.0 * (1.0 - progress * 0.5);
        }
    }

    // Deep fill bonus.
    let fill_r = item_size as f64 / bin_residual.max(1) as f64;
    if fill_r > 0.90 && bin_residual != bin_capacity {
        score -= (fill_r - 0.90) * 18.0 * (0.6 + progress * 0.5);
    }

    // Nearly-closed bin after next item lands.
    if next > 0.0 && gap > 0.12 {
        let nxt_gap = ((gap * cap - next).max(0.0)) / cap;
        if nxt_gap < 0.06 {
            score -= 9.0 * (1.0 - nxt_gap / 0.06) * (0.5 + progress);
        }
    }

    // Tiny residual near-empty bins with many competitors.
    if post_residual > 0 && post_norm < 0.02 && fitting_bins_count >= 4 {
        score -= 6.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny leftovers are unusable for future items (min size 1..100, but gaps < ~10 rarely help)
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // hard penalty for creating unusable slivers
    }

    // Reward tight fits: exact fill is ideal
    if post_residual == 0 {
        score -= 25.0;
    } else {
        // penalize proportionally wasted fraction relative to capacity
        score += (post_residual as f64 / bin_capacity as f64) * 30.0;
    }

    // Reward bins that can also fit the lookahead item (k=2 lookahead chaining)
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // Penalize if next item would be stranded by this placement's leftover
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: discourage opening new bins when many bins are already open
    if bin_residual == bin_capacity {
        score += 20.0 + 5.0 * open_bins_count as f64;
    } else {
        score -= 3.0 * open_bins_count as f64;
    }

    // Deviation from mean residual: prefer bins that are already partially filled (below-mean residual)
    score += (mean_residual - bin_residual as f64).max(-50.0).min(50.0) * 0.4;

    // Early-stream: be slightly more willing to open fresh bins to build diverse residual pool
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score -= 15.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = bin_residual == bin_capacity;

    // Aggressive 2-step lookahead: reward when next item fits the post residual,
    // with a large bonus for a perfect chain (post_residual == next_item_size).
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack_after_next = post_residual - next_item_size;
        if slack_after_next == 0 {
            score -= 60.0; // perfect two-item chain
        } else {
            // tighter chain = better; scale by lookahead size
            score -= 0.6 * next_item_size as f64 * (1.0 - slack_after_next as f64 / post_residual as f64);
        }
    } else if post_residual > 0 && post_residual < 10 {
        // tiny dead space that almost nothing can use
        score += 12.0;
    }

    // Penalize large leftover only if it's unlikely to be reusable later
    if post_residual > 0 && post_residual < item_size.min(50) && (next_item_size == 0 || next_item_size > post_residual) {
        score += 0.3 * (50 - post_residual) as f64;
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 8.0 + 4.0 * (1.0 - progress);
    }

    // Compare against mean residual: bins tighter than average are more precious.
    if mean_residual > 0.0 {
        let ratio = post_residual as f64 / mean_residual;
        if ratio < 1.0 {
            score -= 3.0 * (1.0 - ratio);
        } else {
            score += 1.5 * (ratio - 1.0).min(2.0);
        }
    }

    // New-bin candidate: prefer existing bins generally, but allow a new bin
    // when the item is large and would leave an awkward residue in any open bin.
    if is_new_bin {
        let awkward = item_size > 50 && item_size % 10 != 0;
        if awkward && open_bins_count > 0 {
            score -= 5.0; // fresh bin may beat poor fits
        } else {
            score += 15.0 + 10.0 * (1.0 - progress); // default: reuse open bins
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 1.10;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize small post_residual relative to capacity.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= 25.0 * (1.0 - fit_ratio).powi(3);

    // Penalize dead space: residuals too small for the smallest plausible item.
    if post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 15.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item exactly-ish.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 18.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here; slight penalty proportional to overflow gap.
            score += 6.0 * (next_item_size - post_residual) as f64 / bin_capacity as f64;
        }
    }

    // Compare against mean residual: prefer bins tighter (more filled) than average.
    score -= 8.0 * (mean_residual - bin_residual as f64) / bin_capacity as f64;

    // Time horizon: early in stream, be more willing to open new bins (spread items);
    // late in stream, consolidate into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: cheap early, expensive late; also cheap when many open bins
        // are fragmented (high mean residual) and item is large.
        let frag = mean_residual / bin_capacity as f64;
        score = 70.0 - 40.0 * (1.0 - progress) + 20.0 * progress - 15.0 * frag
            + 0.5 * item_size as f64 * (1.0 - progress);
        if fitting_bins_count == 1 {
            score += 90.0; // never open a new bin when a unique fitting bin exists
        }
    } else {
        // Existing bin: mild consolidation pressure growing with progress.
        score += 10.0 * progress * (bin_residual as f64 / bin_capacity as f64);
    }

    // Large items: prefer bins where they leave moderate (usable) residue.
    if item_size > 50 {
        score -= 5.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // Tie-break by number of open bins: fewer bins favored slightly (bin-count pressure).
    score += 0.05 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64 / cap;
    let br = bin_residual as f64 / cap;
    let fit = item_size as f64 / cap;

    // Quadratic dead-space penalty, growing with stream progress
    score += 30.0 * progress * pr * pr;

    // Reward tight fits (small post_residual) more strongly as stream advances
    score -= (1.0 - pr) * (1.0 - pr) * (10.0 + 20.0 * progress);

    // Penalize bins whose residual deviates from mean residual (imbalance)
    score += 0.15 * (br * cap - mean_residual) * (br * cap - mean_residual) / cap;

    // Lookahead: reward leaving space for next item, penalize near-miss
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual as f64 >= nxt {
            score -= 8.0 * (1.0 - (post_residual as f64 - nxt) / cap);
        } else if post_residual as f64 > 0.0 {
            score += 6.0 * (nxt - post_residual as f64) / cap;
        }
    }

    // Last-chance bonus: only one fitting bin, avoid opening new bin
    if fitting_bins_count == 1 {
        score -= 12.0 * fit * (0.5 + 0.5 * progress);
    }

    // Crowding penalty: many open bins -> prefer consolidating
    score += 0.5 * open_bins_count as f64 * (1.0 - fit);

    // Smooth new-bin candidate adjustment: empty bin gets moderate default score
    if bin_residual == bin_capacity {
        score += 5.0 + 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 1.02;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: perfect fits (0) strongly rewarded,
    // small dead-space classes (1..=5) heavily penalized.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score += 25.0 * (6 - post_residual) as f64;
    } else if post_residual <= 10 {
        score += 8.0;
    }

    // Modulo-class logic: post_residual divisible by 10 is "reusable"
    // for typical item sizes drawn from 10-multiples / harmonic classes.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 12.0;
    } else if post_residual % 5 == 0 && post_residual > 0 {
        score -= 5.0;
    }

    // Reward leaving room for the lookahead item (exact or class match).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            if slack <= 10 {
                score -= 18.0 - slack as f64;
            }
            // next item itself lands in a harmonic class
            if next_item_size % 10 == 0 {
                score -= 6.0;
            }
        } else {
            // lookahead cannot fit here: slight penalty scaled by how close
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: prefer it only when current bins are crowded
    // (mean residual small) or post fit would be very poor.
    if bin_residual == bin_capacity {
        let pressure = (mean_residual / cap - 0.35).max(0.0);
        score -= 10.0 + 20.0 * pressure;
        // early stream: opening bins is cheap
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 8.0 * (1.0 - progress);
        if post_residual == 0 || item_size == bin_capacity {
            score -= 50.0;
        }
    }

    // Tight-fit bonus: item nearly fills the bin.
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    if fill > 0.8 {
        score -= 10.0 * (fill - 0.8) / 0.2;
    }

    // Mild penalty for spreading across many open bins.
    score += 0.4 * open_bins_count as f64;

    // Integer-division threshold: post_residual in [15, 25) is a bad zone.
    if post_residual / 10 == 1 && post_residual % 10 >= 5 {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let next = next_item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items.max(1) as f64 } else { 0.0 };
    let post_norm = pr / cap;
    let fit_ratio = item_size as f64 / cap;
    let gap = (bin_residual - item_size) as f64 / cap;
    let mut score = post_norm * post_norm * 52.0 + post_norm * 20.0;

    // ---- 2-step lookahead: shape score around the NEXT item ----
    if next > 0.0 {
        if pr == next {
            score -= 58.0;
        } else if pr > next {
            let slack = pr - next;
            let diff = slack / cap;
            // COMBINED: gaussian near-fit pull + linear penalty for larger slack
            score -= 22.0 * (1.0 - diff).max(0.0);
            score -= (-diff * diff * 470.0).exp() * 26.0 * (1.0 - progress * 0.5);
            if diff < 0.04 {
                score -= (0.04 - diff) * 34.0 * (0.6 + progress * 0.6);
            } else if diff > 0.16 {
                score += (diff - 0.16) * 9.0 * (0.5 + progress);
            }
        } else if pr > 0.0 {
            let dead_ratio = (next - pr) / cap;
            score += dead_ratio * 96.0 * (0.6 + progress * 0.6);
        }
    }

    // ---- Absolute dead-floor guard: tiny stranded remainders ----
    let dead_floor = if next_item_size > 0 { (next_item_size.min(12) as f64).max(6.0) } else { 10.0 };
    if post_residual > 0 && pr < dead_floor && pr != next {
        score += 66.0 * (1.0 - progress * 0.3);
    } else if post_residual > 0 && post_residual < 20 && pr != next {
        score += 25.0;
    }

    // ---- Relative-to-mean coupling ----
    if pr > 0.0 {
        let dev = (mean_residual - pr) / cap;
        if dev > 0.05 {
            score += (dev - 0.05) * 12.0 * (0.4 + progress);
        } else if dev < -0.08 {
            score += (-dev - 0.08) * 6.0 * (1.0 - progress);
        }
    }

    // ---- New-bin candidate decision ----
    if bin_residual == bin_capacity {
        let others = if fitting_bins_count > 0 { fitting_bins_count - 1 } else { 0 };
        let size_pull = fit_ratio * 14.0;
        if fitting_bins_count <= 2 && gap > 0.0 {
            score -= (18.0 + size_pull) * (1.0 - progress * 0.6);
        } else if others == 0 {
            score -= 5.0;
        } else {
            score += 20.0 + open_bins_count as f64 * (0.5 + 0.5 * progress);
        }
        if next > 0.0 && fitting_bins_count <= 3 && fit_ratio >= next * 0.95 / cap {
            score -= 5.5 * (1.0 - progress * 0.5);
        }
        if next > 0.0 && fitting_bins_count >= 1 && fit_ratio * cap + next > cap {
            score += 8.0 * (1.0 - progress * 0.4);
        }
        if next > 0.0 && fit_ratio * cap + next <= cap {
            let pair_left = (cap - fit_ratio * cap - next) / cap;
            if pair_left < 0.05 {
                score -= (0.05 - pair_left) * 46.0 * (0.5 + progress * 0.5);
            } else if fit_ratio > 0.35 {
                score -= 3.0 * (1.0 - progress);
            }
        }
        if fit_ratio > 0.5 && progress < 0.5 {
            score -= 6.0 * (1.0 - progress);
        }
        if progress > 0.85 && fit_ratio > 0.6 {
            score -= 4.0 * (progress - 0.85) * 20.0;
        }
        if next > 0.0 && fit_ratio * cap + next > cap * 0.94 && fitting_bins_count > 2 {
            score -= 6.0 * (1.0 - progress * 0.5);
        }
        if progress > 0.6 && fit_ratio < 0.45 && others > 0 {
            score += 10.0 * (progress - 0.6) / 0.4;
        }
    }

    // Exact / near-exact fit bonuses.
    if pr == 0.0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 42.0;
    } else if post_residual <= 9 {
        score -= 18.0 * (1.0 - progress * 0.4);
    } else if post_norm < 0.02 && fitting_bins_count >= 4 {
        score -= 6.0 * (1.0 - progress);
    }

    // Sharp bonus for leaving a tiny gap (<12% of capacity).
    if gap > 0.0 && gap < 0.12 {
        score -= (0.12 - gap) * 48.0;
    } else if gap >= 0.12 && gap < 0.22 && next > 0.0 && pr > 0.0 && pr < next {
        score += (gap - 0.12) * 90.5 * (0.5 + progress);
    } else if gap >= 0.12 && gap < 0.22 && fitting_bins_count <= 3 {
        score += (gap - 0.12) * 18.0 * (0.5 + progress * 0.5);
    }
    if gap >= 0.22 && gap < 0.30 && fitting_bins_count <= 2 {
        score += (gap - 0.22) * 22.0 * (0.6 + progress * 0.4);
    }
    // Next-item chain: leftover after next item nearly closes bin.
    if next > 0.0 && gap > 0.12 {
        let nxt_gap = ((gap * cap - next).max(0.0)) / cap;
        if nxt_gap < 0.05 {
            score -= (0.05 - nxt_gap) * 44.0 * (0.5 + progress * 0.5);
        }
    }

    // Reward large items filling bins deeply.
    score -= fit_ratio * fit_ratio * 6.0;

    // Congestion: many competing bins => penalize sloppy fits.
    if fitting_bins_count > 2 {
        score += gap * 6.5 * ((fitting_bins_count.min(12) as f64 - 2.0) / 10.0);
    }
    if open_bins_count > 8 {
        score += post_norm * 5.0 * ((open_bins_count.min(20) as f64 - 8.0) / 12.0);
    }

    // Late-stream consolidation.
    if progress > 0.7 && post_norm > 0.25 {
        score += (post_norm - 0.25) * 6.0 * (progress - 0.7) / 0.3;
    }

    // Last-chance bonus: prefer a bin that would otherwise be wasted.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 - fit_ratio);
    }

    // Deep fill bonus.
    let fill_r = item_size as f64 / bin_residual.max(1) as f64;
    if fill_r > 0.90 && bin_residual != bin_capacity {
        score -= (fill_r - 0.90) * 18.0 * (0.6 + progress * 0.5);
    }

    // Waste-vs-mean term.
    if pr > 0.0 && mean_residual > 0.0 {
        let waste = post_norm - mean_residual / cap;
        if waste > 0.0 {
            score += waste * 30.0 * (0.4 + progress * 0.6);
        } else {
            score -= (-waste) * 10.0;
        }
    }

    // Penalize bins whose post-residual can never host the next item class.
    if pr > 0.0 && next > 0.0 && pr < next && post_norm > 0.03 {
        score += (next - pr) / cap * 20.0 * (0.5 + progress * 0.5);
    }

    // Reward bins that remain exactly reusable by the next item.
    if next > 0.0 && pr > 0.0 && (pr - next) / cap < 0.02 && pr >= next {
        score -= 6.0 * (1.0 - (pr - next) / cap / 0.02) * (0.5 + progress);
    }

    // Periodic divisibility bonus — post-residual is a near-multiple of next item.
    if next > 0.0 && pr > 0.0 && pr >= next {
        let frac = ((pr - next) % next.max(1.0)) / next.max(1.0);
        if frac < 0.08 {
            score -= 10.0 * (1.0 - progress * 0.5);
        }
    }

    // Double-fit bonus — post-residual hosts the next item twice with little slack.
    if next > 0.0 && pr >= next * 2.0 && pr < next * 2.0 + 8.0 {
        score -= 8.0 * (1.0 - progress * 0.4);
    }

    // Last-chance micro-gap bonus.
    if fitting_bins_count == 1 && gap > 0.0 && gap < 0.06 {
        score -= 7.0 * (1.0 - progress * 0.5);
    }

    // Dead-space penalty when few fitting bins and residual too small for next.
    if next > 0.0 && post_residual > 0 && (post_residual as u32) < next_item_size && fitting_bins_count <= 2 {
        score += 18.0 * (1.0 - progress * 0.5);
    }

    // COMBINED: chain-closure — residual after placing item can host next item
    // AND the remaining slack can host a small fraction of mean-sized items.
    if next > 0.0 && pr >= next && fitting_bins_count > 1 {
        let chain = pr - next;
        if chain < mean_residual.max(1.0) * 0.35 {
            score -= 5.0 * (1.0 - chain / (mean_residual.max(1.0) * 0.35)) * (0.5 + progress * 0.5);
        }
    }

    // COMBINED (new): multi-step divisibility vacuum — prefer post-residuals that
    // can host the next item repeatedly (2x or 3x) with small remainder, reducing
    // dead space across a longer horizon.
    if next > 0.0 && pr > 0.0 && pr >= next {
        for k in 2..=3u32 {
            let mult = next * k as f64;
            if pr >= mult {
                let rem = pr - mult;
                if rem < next * 0.12 {
                    score -= (6.0 + k as f64 * 2.0) * (1.0 - rem / (next * 0.12)) * (0.4 + progress * 0.4);
                }
            }
        }
    }

    // COMBINED (new): dead-space ratio guard — penalize when the wasted fraction
    // of the bin (post_residual relative to capacity) exceeds the mean waste by
    // a growing margin, steering items toward bins that compact tightly.
    if pr > 0.0 && mean_residual > 0.0 {
        let excess = post_norm - (mean_residual / cap) * 1.15;
        if excess > 0.0 {
            score += excess * 22.0 * (0.5 + progress * 0.5);
        }
    }

    // NEW: mid-band residual vacuum — pull items into bins whose post-residual
    // lands in the 0.03–0.10 band only when the next item is small enough to
    // still fit there later, otherwise push such bins away.
    if post_norm > 0.03 && post_norm < 0.10 {
        if next > 0.0 && pr >= next {
            score -= 4.0 * (1.0 - progress * 0.5);
        } else {
            score += 6.0 * (0.5 + progress * 0.5);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Strict dead-space avoidance ---
    // Post-residuals that are too small to fit any plausible future item are "dead space".
    // Penalize them heavily (non-linearly), reward moderately large residuals.
    let dead_threshold = 12.0;
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += (dead_threshold - post_residual as f64) * (dead_threshold - post_residual as f64) * 6.0;
    }
    // Oversized leftover waste: quadratic penalty on wasted capacity beyond half a bin.
    let half = bin_capacity as f64 / 2.0;
    if (post_residual as f64) > half {
        score += (post_residual as f64 - half) * 2.5;
    }

    // --- Tight fit reward ---
    // Reward near-perfect packing (item almost exactly fills the bin).
    let tightness = item_size as f64 / bin_residual as f64;
    if tightness > 0.85 {
        score -= (tightness - 0.85) * 60.0;
    }

    // --- Last-chance bin bonus ---
    // If this is the only bin that can fit the item, strongly prefer using it
    // over opening a new bin (avoid wasting residual capacity).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin is attractive when existing residuals are large but
        // fragmented (item fits poorly in all open bins) and bin count is low.
        // Base cost of opening a bin: modest, so poor fits in existing bins are avoided.
        score += 30.0;
        // If the next item would fit nicely in the fresh residual, make the new bin
        // even more attractive (pairing lookahead).
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 10.0;
        }
        // Under heavy open-bin pressure, opening a new bin is cheap (spreads load).
        score -= (open_bins_count as f64).sqrt() * 3.0;
    } else {
        // --- Open bins pressure ---
        // Penalize placements that leave residuals below the smallest useful item,
        // scaled by how many bins are already open (fragmentation cost grows).
        if post_residual > 0 && post_residual < 10 {
            score += (10 - post_residual) as f64 * (2.0 + open_bins_count as f64 * 0.3);
        }
        // Reward using bins whose residual is close to mean (balanced packing),
        // slightly discouraging extreme residuals when many bins are open.
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += dev * 0.05 * (open_bins_count as f64).ln().max(1.0);
    }

    // --- Lookahead coupling ---
    // If the next item fits exactly in the post-residual, reward heavily.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 25.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item can't follow here: mild penalty proportional to excess.
        score += ((next_item_size - post_residual) as f64) * 0.15;
    }

    // --- Stream progression ---
    // Late in the stream, prefer consolidating into existing bins (fewer bins at end).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.1 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = 0.0;
