pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core: tight fit reward (smaller post_residual is already favored by base term).

    // Aggressive 2-step lookahead: perfect chain if next item exactly fills post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0; // perfect 2-item completion
        } else if next_item_size < post_residual {
            let next_post = post_residual - next_item_size;
            // Reward chains that leave small, still-usable leftovers.
            score -= (10.0 - (next_post as f64 / 10.0)).max(0.0);
            // Penalize leftovers that are too small to be useful for typical items.
            if next_post < 10 {
                score += 8.0;
            }
        } else {
            // Next item cannot follow in this bin: dead space for the lookahead horizon.
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Relative-to-mean coupling: prefer bins tighter than the average open bin.
    score += (mean_residual - bin_residual as f64) * 0.4;

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        score += 30.0 + open_bins_count as f64 * 0.5;
    }

    // Late-stream consolidation: as the stream ends, avoid fragmenting residual space.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: reward small post-residual (tight fit), with non-linear emphasis.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 3.0 * tightness * tightness * (bin_capacity as f64);

    // Penalize dead space: residuals too small for the smallest plausible item.
    if post_residual < 10 {
        score += 25.0;
    } else if post_residual < 20 {
        score += 8.0;
    }

    // Lookahead: if next item fits perfectly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            let waste = post_residual - next_item_size;
            score -= 15.0 * (1.0 - waste as f64 / bin_capacity as f64);
        } else {
            // Next item won't fit here: slight penalty if post residual is stranded.
            score += (post_residual as f64) * 0.05;
        }
    }

    // Last-chance bonus: this is the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: empty bin should only win when fits are poor.
    if bin_residual == bin_capacity {
        // Penalize opening new bins, more so later in the stream.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 20.0 + 30.0 * progress + 2.0 * open_bins_count as f64;
        // But if mean residual across open bins is very low (all bins crowded),
        // opening a fresh bin is less bad.
        score -= 0.3 * mean_residual;
    }

    // Mild reward for using bins with larger residuals when item is large.
    if item_size > bin_capacity / 2 {
        score -= 0.1 * (bin_residual as f64 - item_size as f64).max(0.0);
    }

    // Coupling with global state: prefer balancing residuals toward the mean.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    score
}

