pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fit_norm = pr / cap;

    // Non-linear penalty on residual: smooth polynomial coupling
    let poly = fit_norm * fit_norm * (1.0 + progress) + fit_norm * (1.0 - progress);
    score += 12.0 * poly;

    // Reward tight fits (small post_residual) more strongly as stream progresses
    let tightness = 1.0 - fit_norm;
    score -= 8.0 * tightness * tightness * (0.5 + progress);

    // Last-chance bonus: strongly favor the only bin that fits
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 + progress);
    }

    // Lookahead: reward if next item fits the post-residual
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let slack_after_next = pr - next_item_size as f64;
        score -= 6.0 * (1.0 - slack_after_next / cap);
    } else if next_item_size > 0 {
        score += 3.0 * ((next_item_size as f64 - pr) / cap);
    }

    // Penalize scattering across many open bins relative to mean residual
    score += 0.4 * (open_bins_count as f64).ln().max(0.0) * (pr - mean_residual).abs() / cap;

    // Smoothly discourage opening new bins early, allow late in stream
    score += 4.0 * (1.0 - progress) * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
