    }

    // ---- Absolute dead-floor guard: tiny stranded remainders ----
    let dead_floor = if next_item_size > 0 { (next_item_size.min(12) as f64).max(6.0) } else { 10.0 };
    if post_residual > 0 && pr < dead_floor && pr != next {
        score += 62.0 * (1.0 - progress * 0.3);
    } else if post_residual > 0 && post_residual < 20 && pr != next {
        score += 25.0;
    }

    // ---- Relative-to-mean coupling (softened to reduce dead-space variance) ----
    if pr > 0.0 {
        let dev = (mean_residual - pr) / cap;
        if dev > 0.06 {
            score += (dev - 0.06) * 10.0 * (0.4 + progress);
        } else if dev < -0.10 {
            score += (-dev - 0.10) * 5.0 * (1.0 - progress);
        }
    }

    // ---- New-bin candidate decision ----
    if bin_residual == bin_capacity {
        let others = if fitting_bins_count > 0 { fitting_bins_count - 1 } else { 0 };
        let size_pull = fit_ratio * 14.0;
        if fitting_bins_count <= 2 && gap > 0.0 {
            score -= (18.0 + size_pull) * (1.0 - progress * 0.6);
        } else if others == 0 {
            score -= 5.0;
        } else {
            score += 20.0 + open_bins_count as f64 * (0.5 + 0.5 * progress);
        }
        if next > 0.0 && fitting_bins_count <= 3 && fit_ratio >= next * 0.95 / cap {
            score -= 5.5 * (1.0 - progress * 0.5);
        }
        if next > 0.0 && fitting_bins_count >= 1 && fit_ratio * cap + next > cap {
            score += 8.0 * (1.0 - progress * 0.4);
        }
        if next > 0.0 && fit_ratio * cap + next <= cap {
            let pair_left = (cap - fit_ratio * cap - next) / cap;
            if pair_left < 0.05 {
                score -= (0.05 - pair_left) * 42.0 * (0.5 + progress * 0.5);
            } else if fit_ratio > 0.35 {
                score -= 3.0 * (1.0 - progress);
            }
        }
        if fit_ratio > 0.5 && progress < 0.5 {
            score -= 6.0 * (1.0 - progress);
        }
        if progress > 0.85 && fit_ratio > 0.6 {
            score -= 4.0 * (progress - 0.85) * 20.0;
        }
        // Pair-closure pull: new bin attractive only when item+next nearly fill capacity.
        if next > 0.0 && fit_ratio * cap + next > cap * 0.94 && fitting_bins_count > 2 {
            score -= 6.0 * (1.0 - progress * 0.5);
        }
        // Resist opening bins late in the stream unless the item is huge.
        if progress > 0.6 && fit_ratio < 0.45 && others > 0 {
            score += 10.0 * (progress - 0.6) / 0.4;
        }
    }

    // Exact / near-exact fit bonuses.
    if pr == 0.0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 42.0;
    } else if post_residual <= 9 {
        score -= 18.0 * (1.0 - progress * 0.4);
    } else if post_norm < 0.02 && fitting_bins_count >= 4 {
        score -= 6.0 * (1.0 - progress);
    }

    // Sharp bonus for leaving a tiny gap (<12% of capacity).
    if gap > 0.0 && gap < 0.12 {
        score -= (0.12 - gap) * 48.0;
    } else if gap >= 0.12 && gap < 0.22 && next > 0.0 && pr > 0.0 && pr < next {
        score += (gap - 0.12) * 90.5 * (0.5 + progress);
    } else if gap >= 0.12 && gap < 0.22 && fitting_bins_count <= 3 {
        score += (gap - 0.12) * 18.0 * (0.5 + progress * 0.5);
    }
    if gap >= 0.22 && gap < 0.30 && fitting_bins_count <= 2 {
        score += (gap - 0.22) * 22.0 * (0.6 + progress * 0.4);
    }
    // Next-item chain: leftover after next item nearly closes bin.
    if next > 0.0 && gap > 0.12 {
        let nxt_gap = ((gap * cap - next).max(0.0)) / cap;
        if nxt_gap < 0.05 {
            score -= (0.05 - nxt_gap) * 40.0 * (0.5 + progress * 0.5);
        }
    }

    // Reward large items filling bins deeply.
    score -= fit_ratio * fit_ratio * 6.0;

    // Congestion: many competing bins => penalize sloppy fits.
    if fitting_bins_count > 2 {
        score += gap * 6.5 * ((fitting_bins_count.min(12) as f64 - 2.0) / 10.0);
    }
    if open_bins_count > 8 {
        score += post_norm * 5.0 * ((open_bins_count.min(20) as f64 - 8.0) / 12.0);
    }

    // Late-stream consolidation.
    if progress > 0.7 && post_norm > 0.25 {
        score += (post_norm - 0.25) * 6.0 * (progress - 0.7) / 0.3;
    }

    // Last-chance bonus: prefer a bin that would otherwise be wasted.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 - fit_ratio);
    }

    // Deep fill bonus.
    let fill_r = item_size as f64 / bin_residual.max(1) as f64;
    if fill_r > 0.90 && bin_residual != bin_capacity {
        score -= (fill_r - 0.90) * 18.0 * (0.6 + progress * 0.5);
    }

    // Waste-vs-mean term.
    if pr > 0.0 && mean_residual > 0.0 {
        let waste = post_norm - mean_residual / cap;
        if waste > 0.0 {
            score += waste * 30.0 * (0.4 + progress * 0.6);
        } else {
            score -= (-waste) * 10.0;
        }
    }

    // Penalize bins whose post-residual can never host the next item class.
    if pr > 0.0 && next > 0.0 && pr < next && post_norm > 0.03 {
        score += (next - pr) / cap * 20.0 * (0.5 + progress * 0.5);
    }

    // Reward bins that remain exactly reusable by the next item.
    if next > 0.0 && pr > 0.0 && (pr - next) / cap < 0.02 && pr >= next {
        score -= 6.0 * (1.0 - (pr - next) / cap / 0.02) * (0.5 + progress);
    }

    // Periodic divisibility bonus — post-residual is a near-multiple of next item.
    if next > 0.0 && pr > 0.0 && pr >= next {
        let frac = ((pr - next) % next.max(1.0)) / next.max(1.0);
        if frac < 0.08 {
            score -= 10.0 * (1.0 - progress * 0.5);
        }
    }

    // Double-fit bonus — post-residual hosts the next item twice with little slack.
    if next > 0.0 && pr >= next * 2.0 && pr < next * 2.0 + 8.0 {
        score -= 8.0 * (1.0 - progress * 0.4);
    }

    // Last-chance micro-gap bonus.
    if fitting_bins_count == 1 && gap > 0.0 && gap < 0.06 {
        score -= 7.0 * (1.0 - progress * 0.5);
    }

    // Dead-space penalty when few fitting bins and residual too small for next.
    if next > 0.0 && post_residual > 0 && post_residual < next_item_size && fitting_bins_count <= 2 {
        score += 18.0 * (1.0 - progress * 0.5);
    }

    // Chain-closure: residual after placing item can host next item with little slack.
    if next > 0.0 && pr >= next && fitting_bins_count > 1 {
        let chain = pr - next;
        let chain_ref = mean_residual.max(1.0) * 0.35;
        if chain < chain_ref {
            score -= 5.0 * (1.0 - chain / chain_ref) * (0.5 + progress * 0.5);
        }
    }

    // Mid-band residual vacuum: pull items into bins whose post-residual lands in
    // the 0.03–0.10 band only when the next item can still fit there later.
    if post_norm > 0.03 && post_norm < 0.10 {
        if next > 0.0 && pr >= next {
            score -= 4.0 * (1.0 - progress * 0.5);
        } else {
            score += 6.0 * (0.5 + progress * 0.5);
        }
    }

    // COMBINED: fine-grained residual fitting fused with lookahead — when the item
    // nearly consumes the residual and the leftover stays reusable by the next item,
    // strongly prefer this bin; scale the pull by how close pr is to next.
    if next > 0.0 && pr > 0.0 && pr >= next && fill_r > 0.85 {
        let reuse = (pr - next) / cap;
        if reuse < 0.06 {
            score -= (0.06 - reuse) * 30.0 * (0.5 + progress * 0.5);
            // Extra pull when the next item exactly closes the bin afterwards.
            if reuse == 0.0 {
                score -= 8.0 * (1.0 - progress * 0.4);
            }
        }
    }

    // COMBINED: discourage leaving residuals in the awkward 0.10–0.18 band that
    // rarely hosts upcoming items, but relax when next item could still pair there.
    if post_norm >= 0.10 && post_norm < 0.18 && next > 0.0 && pr < next {
        score += (0.18 - post_norm) * 14.0 * (0.4 + progress * 0.6);
    } else if post_norm >= 0.10 && post_norm < 0.18 && next > 0.0 && pr >= next {
        let two_step = (pr - next) / cap;
        if two_step < 0.03 {
            score -= (0.03 - two_step) * 16.0 * (0.5 + progress * 0.5);
        }
    }

    // COMBINED: residual-band match — when the current residual is a near-multiple
    // of the next item size, filling it exactly leaves a clean zero/next-aligned
    // post-residual; reward proportionally to how tight the match is.
    if next > 0.0 && bin_residual != bin_capacity {
        let k = (bin_residual as f64 / next).floor();
        if k >= 1.0 {
            let band_left = bin_residual as f64 - k * next;
            if band_left <= item_size as f64 {
                let leftover = band_left - item_size as f64;
                if leftover >= 0.0 && leftover < next {
                    score -= (1.0 - leftover / next.max(1.0)) * 9.0 * (0.5 + progress * 0.5);
                }
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer perfect or near-perfect fits.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // 2-step lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Chain fit: bonus proportional to how snugly the next item fits.
            let slack = (post_residual - next_item_size) as f64;
            score -= 150.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Post-residual too small for next item: penalize dead space.
            score += 40.0 + 0.5 * post_residual as f64;
        }
        // Bonus if item + next item nearly fill the bin exactly.
        let two_step = item_size as f64 + next_item_size as f64;
        if (bin_residual as f64 - two_step).abs() <= 3.0 {
            score -= 120.0;
        }
    } else {
        // Last item: just minimize residual.
        score -= 50.0;
    }

    // Relative to mean residual: prefer bins tighter than average.
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Last-chance bin before opening a new bin: use it rather than waste it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 180.0;
    }

    // Penalize opening a new bin when decent existing options exist,
    // but allow it when all fits are poor (large post_residual).
    if bin_residual == bin_capacity {
        if post_residual > 50 {
            score += 60.0;
        } else {
            score += 25.0;
        }
        // New bins are more acceptable early in the stream.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 * progress;
    }

    // Prefer reusing bins among many open bins (reduce bin count).
    score += 0.2 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let post_norm = pr / cap;
    let mut score = post_norm * post_norm * 50.0 + post_norm * 20.0;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 42.0;
    } else if post_residual <= 9 {
        score -= 18.0 * (1.0 - progress * 0.4);
    }

    // Dead-space class: residuals below next item's usable floor are near-worthless.
    let dead_floor = if next_item_size > 0 { (next_item_size.min(12) as f64).max(6.0) } else { 10.0 };
    if post_residual > 0 && (post_residual as f64) < dead_floor {
        score += 62.0 * (1.0 - progress * 0.3);
    } else if post_residual < 20 {
        score += 25.0;
    }

    // Harmonic divisibility rewards.
    if post_residual > 0 {
        let r = post_residual;
        if r % 50 == 0 { score -= 18.0; }
        else if r % 25 == 0 { score -= 12.0; }
        else if r % 20 == 0 { score -= 10.0; }
        else if r % 10 == 0 { score -= 8.0; }
        else { score += (r % 5) as f64 * 1.5; }
    }

    // Lookahead: tight pairing with next item in post residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64 / cap;
        score -= (-slack * slack * 450.0).exp() * 24.0 * (1.0 - progress * 0.5);
        if next_item_size == post_residual {
            score -= 60.0;
        } else {
            let nxt_left = post_residual - next_item_size;
            if nxt_left % 10 == 0 { score -= 10.0; }
            else if nxt_left > 12 { score -= 4.0; }
            else { score += 6.0; }
        }
    }

    // Dead lookahead: next item cannot use leftover.
    if next_item_size > 0 && pr > 0.0 && (pr as u32) < next_item_size && post_norm > 0.03 {
        let dead_ratio = (next_item_size as f64 - pr) / cap;
        score += dead_ratio * 90.0 * (0.6 + progress * 0.6);
    }
    if next_item_size > 0 && post_residual > 0 && (post_residual as u32) < next_item_size && fitting_bins_count <= 2 {
        score += 18.0 * (1.0 - progress * 0.5);
    }

    // Tight-gap bonus.
    let gap = (bin_residual - item_size) as f64 / cap;
    if gap > 0.0 && gap < 0.12 {
        score -= (0.12 - gap) * 48.0;
    } else if gap >= 0.12 && gap < 0.22 && fitting_bins_count <= 3 {
        score += (gap - 0.12) * 18.0 * (0.5 + progress * 0.5);
    } else if gap >= 0.22 && gap < 0.30 && fitting_bins_count <= 2 {
        score += (gap - 0.22) * 22.0 * (0.6 + progress * 0.4);
    }
    if fitting_bins_count == 1 && gap > 0.0 && gap < 0.06 {
        score -= 7.0 * (1.0 - progress * 0.5);
    }

    // Last-chance bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let size_pull = (item_size as f64 / cap) * 14.0;
        if fitting_bins_count <= 2 {
            score -= (18.0 + size_pull) * (1.0 - progress * 0.6);
        } else {
            score += 20.0 + open_bins_count as f64 * (0.5 + 0.5 * progress);
        }
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        if next_item_size > 0 && fitting_bins_count <= 3 && (item_size as f64) >= next_item_size as f64 * 0.95 {
            score -= 5.5 * (1.0 - progress * 0.5);
        }
        if next_item_size > 0 && fitting_bins_count >= 1 {
            let nxt = next_item_size as f64;
            if (item_size as f64) + nxt > cap {
                score += 8.0 * (1.0 - progress * 0.4);
            }
        }
        if (item_size as f64) > cap * 0.5 && progress < 0.5 {
            score -= 6.0 * (1.0 - progress);
        }
        if progress > 0.85 && (item_size as f64) / cap > 0.6 {
            score -= 4.0 * (progress - 0.85) * 20.0;
        }
        if next_item_size > 0 && (item_size as f64) + (next_item_size as f64) <= cap && (item_size as f64) / cap > 0.35 {
            score -= 3.0 * (1.0 - progress);
        }
    }

    // Global pressure.
    score -= (mean_residual / cap) * 5.0;

    // Waste-relative pressure.
    if post_residual > 0 && mean_residual > 0.0 {
        let waste = post_norm - (mean_residual / cap);
        if waste > 0.0 {
            score += waste * 30.0 * (0.4 + progress * 0.6);
        } else {
            score -= (-waste) * 10.0;
        }
    }

    // Tiny-residual reserve: near-empty leftovers worth keeping when many bins open.
    if post_residual > 0 && post_norm < 0.02 && fitting_bins_count >= 4 {
        score -= 6.0 * (1.0 - progress);
    }

    // Two-next-item anticipation: residual fits next item twice.
    if post_residual > 0 && next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt * 2.0 && pr < nxt * 2.0 + 8.0 {
            score -= 8.0 * (1.0 - progress * 0.4);
        }
        if (pr as u32) >= next_item_size {
            let frac = ((pr - nxt) % nxt.max(1.0)) / nxt.max(1.0);
            if frac < 0.08 {
                score -= 10.0 * (1.0 - progress * 0.5);
            }
        }
        let second_slack = (pr - nxt) / cap;
        if second_slack >= 0.0 && second_slack < 0.05 {
            score -= (0.05 - second_slack) * 40.0 * (0.5 + progress * 0.5);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Tightness: reward near-perfect fills strongly (non-linear)
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 8.0 * tightness * tightness;

    // Reward exact/near-exact fits
    if post_residual == 0 {
        score -= 20.0;
    } else if post_residual <= 5 {
        score -= 10.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, strongly favor this bin
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 15.0;
        } else if post_residual > next_item_size {
            // next item still leaves room: mild reward proportional to future tightness
            let future_tight = (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= 5.0 * (1.0 - future_tight);
        } else {
            // next item cannot fit here: penalize slightly
            score += 3.0;
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item, strongly prefer it
    if fitting_bins_count == 1 {
        score -= 12.0;
    } else if fitting_bins_count > 1 {
        // with alternatives, prefer the bin that wastes least
        score += 1.5 * (fitting_bins_count as f64 - 1.0).min(5.0);
    }

    // Penalize bins whose residual is far above mean (fragmented outliers) mildly
    score += 0.05 * ((bin_residual as f64 - mean_residual).abs());

    // Time-horizon coupling: early in the stream, be pickier about dead space;
    // late in the stream, pack aggressively into any fitting bin.
    let dead_space_penalty = (1.0 - progress) * 6.0 * (post_residual as f64 / bin_capacity as f64);
    score += dead_space_penalty;
    score -= progress * 4.0;

    // New-bin candidate handling: opening a new bin should only win when the item
    // fits poorly in existing bins (large post_residual) or there are few options.
    if bin_residual == bin_capacity {
        let base = 30.0;
        let escape = if fitting_bins_count == 0 { -25.0 } else { 0.0 };
        // Early stream: opening bins is cheap; late stream: avoid proliferation
        let horizon = (1.0 - progress) * 10.0;
        score = base - escape + horizon
            + 0.3 * (post_residual as f64)
            - 0.2 * (next_item_size as f64).min(80.0);
        // If next item is large, a fresh bin is more attractive
        if next_item_size >= 60 {
            score -= 8.0;
        }
    }

    // Mild preference to fill already-open bins as count grows
    score += 0.15 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = (1.0 - progress) * norm_pr.powi(2) + progress * norm_pr.powi(3);
    score += 40.0 * poly;

    // Tight-fit reward: small post residual favored more as stream advances
    let tightness = 1.0 - norm_pr;
    score -= (10.0 + 20.0 * progress) * tightness.powi(2);

    // Lookahead: penalize if post residual cannot host next item
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr < ni {
            score += 8.0 * (1.0 - pr / ni.max(1.0)) * (0.5 + progress);
        } else {
            score -= 6.0 * (ni / cap) * (1.0 - (pr - ni).abs() / cap);
        }
    }

    // Last chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (0.5 + progress);
    }

    // Discourage opening new bins when open bins have large mean residual
    if bin_residual == bin_capacity {
        score += 5.0 + 0.05 * open_bins_count as f64 - 0.02 * mean_residual;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let next = next_item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items.max(1) as f64 } else { 0.0 };
    let post_norm = pr / cap;
    let fit_ratio = item_size as f64 / cap;
    let gap = (bin_residual - item_size) as f64 / cap;
    let mut score = post_norm * post_norm * 56.5 + post_norm * 21.8;

    // ---- Aggressive 2-step lookahead: shape score around the NEXT item ----
    if next > 0.0 {
        if pr == next {
            score -= 45.0;
        } else if pr > next {
            let slack = pr - next;
            let diff = slack / cap;
            score -= 20.0 * (1.0 - diff).max(0.0);
            score -= (-diff * diff * 458.0).exp() * 20.2 * (1.0 - progress * 0.5);
            // Snug remainder after next item lands.
            if diff < 0.04 {
                score -= (0.04 - diff) * 26.0 * (0.6 + progress * 0.6);
            } else if diff > 0.16 {
                score += (diff - 0.16) * 8.0 * (0.5 + progress);
            }
            // Modular alignment: remainder divisible by next item invites refills.
            let frac = (slack % next.max(1.0)) / next.max(1.0);
            if frac < 0.08 {
                score -= 10.0 * (1.0 - progress * 0.5);
            }
        } else if pr > 0.0 {
            let dead_ratio = (next - pr) / cap;
            score += dead_ratio * 90.0 * (0.6 + progress * 0.6);
        }
    }

    // ---- Hard dead-floor: tiny residuals are nearly unusable ----
    let dead_floor = if next_item_size > 0 { (next_item_size.min(12) as f64).max(6.0) } else { 10.0 };
    if post_residual > 0 && pr < dead_floor && pr != next {
        score += 62.0 * (1.0 - progress * 0.3);
    } else if post_residual > 0 && post_residual < 20 && pr != next {
        score += 25.0;
    }

    // ---- Relative-to-mean coupling: favor tighter-than-average bins ----
    if pr > 0.0 && mean_residual > 0.0 {
        let waste = post_norm - mean_residual / cap;
        if waste > 0.0 {
            score += waste * 30.0 * (0.4 + progress * 0.6);
        } else {
            score -= (-waste) * 10.0;
        }
    }

    // ---- New-bin candidate decision (bin_residual == bin_capacity) ----
    if bin_residual == bin_capacity {
        let others = if fitting_bins_count > 0 { fitting_bins_count - 1 } else { 0 };
        let size_pull = fit_ratio * 14.0;
        if fitting_bins_count <= 2 && gap > 0.0 {
            score -= (18.0 + size_pull) * (1.0 - progress * 0.6);
        } else if others == 0 {
            score -= 5.0;
        } else {
            score += 20.0 + open_bins_count as f64 * (0.5 + 0.5 * progress);
        }
        // If the next item is nearly as big as this one, opening a fresh bin
        // wastes capacity; discourage it under mild pressure.
        if next > 0.0 && fitting_bins_count <= 3 && item_size as f64 >= next * 0.95 {
            score -= 5.5 * (1.0 - progress * 0.5);
        }
        if next > 0.0 && fitting_bins_count >= 1 && item_size as f64 + next > cap {
            score += 8.0 * (1.0 - progress * 0.4);
        }
        if fit_ratio > 0.5 && progress < 0.5 {
            score -= 6.0 * (1.0 - progress);
        }
        if next > 0.0 && item_size as f64 + next <= cap && fit_ratio > 0.35 {
            score -= 3.0 * (1.0 - progress);
        }
    }

    // Exact / near-exact fit bonuses.
    if pr == 0.0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 42.0;
    } else if post_residual <= 9 && pr != next {
        score -= 18.0 * (1.0 - progress * 0.4);
    } else if post_norm < 0.05 {
        score -= 10.2 * (1.0 - post_norm / 0.05);
    }

    // Sharp bonus for leaving a tiny gap (<12% of capacity).
    if gap > 0.0 && gap < 0.12 {
        score -= (0.12 - gap) * 48.0;
    } else if gap >= 0.12 && gap < 0.22 {
        if fitting_bins_count <= 3 {
            score += (gap - 0.12) * 18.0 * (0.5 + progress * 0.5);
        }
    }
    if gap >= 0.22 && gap < 0.30 && fitting_bins_count <= 2 {
        score += (gap - 0.22) * 22.0 * (0.6 + progress * 0.4);
    }
    // Next-item chain: leftover after placing next item nearly closes bin.
    if next > 0.0 && gap > 0.12 {
        let nxt_gap = ((gap * cap - next).max(0.0)) / cap;
        if nxt_gap < 0.06 {
            score -= 9.0 * (1.0 - nxt_gap / 0.06) * (0.5 + progress);
        }
    }

    // Reward large items filling bins deeply.
    score -= fit_ratio * fit_ratio * 6.0;

    // Congestion: when many bins compete for this item, penalize sloppy fits.
    if fitting_bins_count > 2 {
        score += gap * 6.5 * ((fitting_bins_count.min(12) as f64 - 2.0) / 10.0);
    }
    if open_bins_count > 8 {
        score += post_norm * 5.0 * ((open_bins_count.min(20) as f64 - 8.0) / 12.0);
    }

    // Late-stream consolidation: penalize moderately large residuals late.
    if progress > 0.7 && post_norm > 0.25 {
        score += (post_norm - 0.25) * 6.0 * (progress - 0.7) / 0.3;
    }

    // Last-chance bonus: prefer a bin that would otherwise be wasted.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 - fit_ratio);
    }
    if fitting_bins_count == 1 && gap > 0.0 && gap < 0.06 {
        score -= 7.0 * (1.0 - progress * 0.5);
    }

    // Deep fill bonus relative to actual residual.
    let fill_r = item_size as f64 / bin_residual.max(1) as f64;
    if fill_r > 0.90 && bin_residual != bin_capacity {
        score -= (fill_r - 0.90) * 18.0 * (0.6 + progress * 0.5);
    }

    // Dead-space guard: stranded small gap after next item.
    if next > 0.0 && pr > 0.0 {
        let after_next = (pr - next).max(0.0);
        let dead = after_next / cap;
        if dead > 0.0 && dead < 0.08 {
            let reusable = if after_next >= next { 1.0 } else { 0.0 };
            score += (0.08 - dead) * 16.0 * (1.0 - reusable * 0.5) * (0.5 + progress);
        }
        // Two-of-next bonus: room for next item twice.
        if pr >= next * 2.0 && pr < next * 2.0 + 8.0 {
            score -= 8.0 * (1.0 - progress * 0.4);
        }
    }

    // Mid-residual band: leftover in 10-20% range that next item cannot fit
    // into is likely to strand; penalize.
    if pr > 0.0 && post_norm >= 0.10 && post_norm < 0.20 && next > 0.0 && next > pr {
        score += (next - pr) / cap * 26.0 * (0.4 + progress * 0.8);
    }

    // Half-consumed bins late in the stream: discourage leaving a residual
    // smaller than half the current item (hard to refill).
    if pr > 0.0 && pr < item_size as f64 * 0.5 && progress > 0.3 {
        score += 4.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover: mod-10 residue classes of post_residual.
    let pr = post_residual;
    let harmonic = pr % 10;
    // Leftovers whose remainder is 0 align with the 10-multiple grid -> reusable.
    score += (harmonic as f64) * 0.6;

    // Dead-space penalty: tiny leftovers are wasted unless exactly 0.
    if pr > 0 && pr < 10 {
        score += 25.0;
    }

    // Reward tight fits (small positive post_residual).
    if pr <= 5 {
        score -= 20.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 60.0;
        } else if next_item_size <= pr {
            score -= (next_item_size as f64) * 0.4;
        } else {
            // next item cannot use this bin's leftover -> penalize proportional waste
            score += ((next_item_size - pr).min(20)) as f64 * 0.5;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // New-bin candidate handling: empty bin gets a neutral-ish baseline so it wins
    // only when existing bins would create bad dead space.
    if bin_residual == bin_capacity {
        score = 40.0 + (open_bins_count as f64) * 0.3 - (mean_residual * 0.05);
        if next_item_size > 0 && next_item_size >= 50 {
            score -= 10.0; // big next item: fresh bin more attractive
        }
    }

    // Late in the stream, prefer consolidating into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 8.0;
    score += (open_bins_count as f64) * 0.2;

    // Mean-residual divergence: bins far below mean residual are worse targets.
    let resid_f = bin_residual as f64;
    score += ((resid_f - mean_residual).abs()) * 0.15;

    // Integer-division threshold: post_residual in [25,50) is a "half-class" zone,
    // moderately reusable; penalize slightly less than [10,25).
    if pr >= 10 && pr < 25 {
        score += 12.0;
    } else if pr >= 25 && pr < 50 {
        score += 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let next = next_item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items.max(1) as f64 } else { 0.0 };
    let post_norm = pr / cap;
    let fit_ratio = item_size as f64 / cap;
    let gap = (bin_residual - item_size) as f64 / cap;
    let mut score = post_norm * post_norm * 50.0 + post_norm * 20.0;

    // ---- 2-step lookahead: shape score around the NEXT item ----
    if next > 0.0 {
        if pr == next {
            score -= 54.0;
        } else if pr > next {
            let slack = pr - next;
            let diff = slack / cap;
            score -= 20.0 * (1.0 - diff).max(0.0);
            score -= (-diff * diff * 450.0).exp() * 24.0 * (1.0 - progress * 0.5);
            if diff < 0.04 {
                score -= (0.04 - diff) * 30.0 * (0.6 + progress * 0.6);
            } else if diff > 0.16 {
                score += (diff - 0.16) * 8.0 * (0.5 + progress);
            }
        } else if pr > 0.0 {
            let dead_ratio = (next - pr) / cap;
            score += dead_ratio * 90.0 * (0.6 + progress * 0.6);
        }
    }

    // ---- Absolute dead-floor guard: tiny stranded remainders ----
    let dead_floor = if next_item_size > 0 { (next_item_size.min(12) as f64).max(6.0) } else { 10.0 };
    if post_residual > 0 && pr < dead_floor && pr != next {
        score += 62.0 * (1.0 - progress * 0.3);
    } else if post_residual > 0 && post_residual < 20 && pr != next {
        score += 25.0;
    }

    // ---- Relative-to-mean coupling (softened to reduce dead-space variance) ----
    if pr > 0.0 {
        let dev = (mean_residual - pr) / cap;
        if dev > 0.06 {
            score += (dev - 0.06) * 10.0 * (0.4 + progress);
        } else if dev < -0.10 {
            score += (-dev - 0.10) * 5.0 * (1.0 - progress);
        }
    }

    // ---- New-bin candidate decision ----
    if bin_residual == bin_capacity {
        let others = if fitting_bins_count > 0 { fitting_bins_count - 1 } else { 0 };
        let size_pull = fit_ratio * 14.0;
        if fitting_bins_count <= 2 && gap > 0.0 {
            score -= (18.0 + size_pull) * (1.0 - progress * 0.6);
        } else if others == 0 {
            score -= 5.0;
        } else {
            score += 20.0 + open_bins_count as f64 * (0.5 + 0.5 * progress);
        }
        if next > 0.0 && fitting_bins_count <= 3 && fit_ratio >= next * 0.95 / cap {
            score -= 5.5 * (1.0 - progress * 0.5);
        }
        if next > 0.0 && fitting_bins_count >= 1 && fit_ratio * cap + next > cap {
            score += 8.0 * (1.0 - progress * 0.4);
        }
        if next > 0.0 && fit_ratio * cap + next <= cap {
            let pair_left = (cap - fit_ratio * cap - next) / cap;
            if pair_left < 0.05 {
                score -= (0.05 - pair_left) * 42.0 * (0.5 + progress * 0.5);
            } else if fit_ratio > 0.35 {
                score -= 3.0 * (1.0 - progress);
            }
        }
        if fit_ratio > 0.5 && progress < 0.5 {
            score -= 6.0 * (1.0 - progress);
        }
        if progress > 0.85 && fit_ratio > 0.6 {
            score -= 4.0 * (progress - 0.85) * 20.0;
        }
        // Pair-closure pull: new bin attractive only when item+next nearly fill capacity.
        if next > 0.0 && fit_ratio * cap + next > cap * 0.94 && fitting_bins_count > 2 {
            score -= 6.0 * (1.0 - progress * 0.5);
        }
        // Resist opening bins late in the stream unless the item is huge.
        if progress > 0.6 && fit_ratio < 0.45 && others > 0 {
            score += 10.0 * (progress - 0.6) / 0.4;
        }
    }

    // Exact / near-exact fit bonuses.
    if pr == 0.0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 42.0;
    } else if post_residual <= 9 {
        score -= 18.0 * (1.0 - progress * 0.4);
    } else if post_norm < 0.02 && fitting_bins_count >= 4 {
        score -= 6.0 * (1.0 - progress);
    }

    // Sharp bonus for leaving a tiny gap (<12% of capacity).
    if gap > 0.0 && gap < 0.12 {
        score -= (0.12 - gap) * 48.0;
    } else if gap >= 0.12 && gap < 0.22 && next > 0.0 && pr > 0.0 && pr < next {
        score += (gap - 0.12) * 90.5 * (0.5 + progress);
    } else if gap >= 0.12 && gap < 0.22 && fitting_bins_count <= 3 {
        score += (gap - 0.12) * 18.0 * (0.5 + progress * 0.5);
    }
    if gap >= 0.22 && gap < 0.30 && fitting_bins_count <= 2 {
        score += (gap - 0.22) * 22.0 * (0.6 + progress * 0.4);
    }
    // Next-item chain: leftover after next item nearly closes bin.
    if next > 0.0 && gap > 0.12 {
        let nxt_gap = ((gap * cap - next).max(0.0)) / cap;
        if nxt_gap < 0.05 {
            score -= (0.05 - nxt_gap) * 40.0 * (0.5 + progress * 0.5);
        }
    }

    // Reward large items filling bins deeply.
    score -= fit_ratio * fit_ratio * 6.0;

    // Congestion: many competing bins => penalize sloppy fits.
    if fitting_bins_count > 2 {
        score += gap * 6.5 * ((fitting_bins_count.min(12) as f64 - 2.0) / 10.0);
    }
    if open_bins_count > 8 {
        score += post_norm * 5.0 * ((open_bins_count.min(20) as f64 - 8.0) / 12.0);
    }

    // Late-stream consolidation.
    if progress > 0.7 && post_norm > 0.25 {
        score += (post_norm - 0.25) * 6.0 * (progress - 0.7) / 0.3;
    }

    // Last-chance bonus: prefer a bin that would otherwise be wasted.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 - fit_ratio);
    }

    // Deep fill bonus.
    let fill_r = item_size as f64 / bin_residual.max(1) as f64;
    if fill_r > 0.90 && bin_residual != bin_capacity {
        score -= (fill_r - 0.90) * 18.0 * (0.6 + progress * 0.5);
    }

    // Waste-vs-mean term.
    if pr > 0.0 && mean_residual > 0.0 {
        let waste = post_norm - mean_residual / cap;
        if waste > 0.0 {
            score += waste * 30.0 * (0.4 + progress * 0.6);
        } else {
            score -= (-waste) * 10.0;
        }
    }

    // Penalize bins whose post-residual can never host the next item class.
    if pr > 0.0 && next > 0.0 && pr < next && post_norm > 0.03 {
        score += (next - pr) / cap * 20.0 * (0.5 + progress * 0.5);
    }

    // Reward bins that remain exactly reusable by the next item.
    if next > 0.0 && pr > 0.0 && (pr - next) / cap < 0.02 && pr >= next {
        score -= 6.0 * (1.0 - (pr - next) / cap / 0.02) * (0.5 + progress);
    }

    // Periodic divisibility bonus — post-residual is a near-multiple of next item.
    if next > 0.0 && pr > 0.0 && pr >= next {
        let frac = ((pr - next) % next.max(1.0)) / next.max(1.0);
        if frac < 0.08 {
            score -= 10.0 * (1.0 - progress * 0.5);
        }
    }

    // Double-fit bonus — post-residual hosts the next item twice with little slack.
    if next > 0.0 && pr >= next * 2.0 && pr < next * 2.0 + 8.0 {
        score -= 8.0 * (1.0 - progress * 0.4);
    }

    // Last-chance micro-gap bonus.
    if fitting_bins_count == 1 && gap > 0.0 && gap < 0.06 {
        score -= 7.0 * (1.0 - progress * 0.5);
    }

    // Dead-space penalty when few fitting bins and residual too small for next.
    if next > 0.0 && post_residual > 0 && post_residual < next_item_size && fitting_bins_count <= 2 {
        score += 18.0 * (1.0 - progress * 0.5);
    }

    // Chain-closure: residual after placing item can host next item with little slack.
    if next > 0.0 && pr >= next && fitting_bins_count > 1 {
        let chain = pr - next;
        let chain_ref = mean_residual.max(1.0) * 0.35;
        if chain < chain_ref {
            score -= 5.0 * (1.0 - chain / chain_ref) * (0.5 + progress * 0.5);
        }
    }

    // Mid-band residual vacuum: pull items into bins whose post-residual lands in
    // the 0.03–0.10 band only when the next item can still fit there later.
    if post_norm > 0.03 && post_norm < 0.10 {
        if next > 0.0 && pr >= next {
            score -= 4.0 * (1.0 - progress * 0.5);
        } else {
            score += 6.0 * (0.5 + progress * 0.5);
        }
    }

    // Combined: fine-grained residual fitting with lookahead anticipation —
    // when the item nearly consumes the residual and the leftover stays
    // reusable by the next item, strongly prefer this bin.
    if next > 0.0 && pr > 0.0 && pr >= next && fill_r > 0.85 {
        let reuse = (pr - next) / cap;
        if reuse < 0.06 {
            score -= (0.06 - reuse) * 30.0 * (0.5 + progress * 0.5);
        }
    }

    // Discourage leaving residuals in the awkward 0.10–0.18 band that
    // rarely hosts upcoming items but wastes capacity.
    if post_norm >= 0.10 && post_norm < 0.18 && next > 0.0 && pr < next {
        score += (0.18 - post_norm) * 14.0 * (0.4 + progress * 0.6);
    }

    // NEW coupling: when the post-residual is within one next-item of closing the
    // bin after the lookahead step, reward proportional to closeness — this
    // chains bins toward closure instead of leaving diffuse dead space.
    if next > 0.0 && pr > 0.0 && pr >= next {
        let two_step_left = pr - next;
        if two_step_left <= next && two_step_left / cap < 0.08 {
            score -= (0.08 - two_step_left / cap) * 22.0 * (0.6 + progress * 0.4);
        }
    }

    // NEW: penalize post-residuals that are dead for both this and the next item
    // class but larger than the dead floor — pure stranded capacity.
    if post_residual > 0 && next > 0.0 && pr < next && pr >= dead_floor {
        score += ((next - pr) / cap) * 14.0 * (1.0 - progress * 0.4);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (1.0 - post_residual as f64 / 10.0);
    }
    // Perfect fit reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance pressure: this is the only bin that fits -> strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, favor new bin when fit is poor.
    let pressure = open_bins_count as f64 / (1.0 + mean_residual / 20.0);
    score += 0.15 * pressure * (post_residual as f64 / bin_capacity as f64);

    // Lookahead: if next item fits into the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 8.0;
    }

    // New-bin candidate: prefer it when current bins would leave large waste or item is large.
    if bin_residual == bin_capacity {
        let waste_if_open = (bin_capacity - item_size) as f64;
        score = 25.0 + waste_if_open * 0.3
            + 2.0 * open_bins_count as f64
            - (if fitting_bins_count == 0 { 50.0 } else { 0.0 });
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 1.00;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is ideal
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches the next item exactly
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual > next_item_size {
            // next item fits here afterwards: mild reward proportional to tightness
            score -= 0.5 * (post_residual - next_item_size) as f64;
        } else {
            // next item cannot use the leftover: penalize dead space
            score += 0.3 * (next_item_size - post_residual) as f64;
        }
    }

    // Penalize residuals too small to ever be useful (below min item size)
    if post_residual > 0 && post_residual < 1 {
        score += 200.0;
    }
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // Relative to mean residual: prefer bins tighter than average
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 300.0;
    }

    // New empty bin candidate: penalize unless few alternatives or bad fits exist
    if bin_residual == bin_capacity {
        score += 150.0;
        if fitting_bins_count <= 1 {
            score -= 200.0;
        }
        if post_residual as f64 > mean_residual {
            score -= 50.0;
        }
    }

    // Late in stream, be more conservative about opening bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 100.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let post_norm = pr / cap;

    // Base: normalized post-residual (compaction core)
    let mut score = post_norm * post_norm * 50.0 + post_norm * 20.0;

    // Dead-space avoidance with progress-adaptive floor
    let dead_floor = if next_item_size > 0 { (next_item_size.min(12) as f64).max(6.0) } else { 10.0 };
    if post_residual > 0 && (post_residual as f64) < dead_floor {
        score += 62.0 * (1.0 - progress * 0.3);
    } else if post_residual > 12 && post_residual < 25 {
        score += (25.0 - pr) * 3.0;
    }

    // Reward tight fits
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 42.0;
    } else if post_residual <= 12 {
        score -= pr * 0.5;
    }

    // Lookahead: next item fits post_residual (Gaussian near-exact bonus)
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64 / cap;
        score -= (-slack * slack * 450.0).exp() * 24.0 * (1.0 - progress * 0.5);
        score -= 18.0;
    } else if next_item_size > 0 && post_residual > 0 && (post_residual as u32) < next_item_size {
        // post_residual too small for next item -> dead space amplified
        let dead_ratio = (next_item_size as f64 - pr) / cap;
        score += dead_ratio * 90.0 * (0.6 + progress * 0.6);
        if fitting_bins_count <= 2 {
            score += 18.0 * (1.0 - progress * 0.5);
        }
    }

    // Gap-based coupling on bin_residual - item_size
    let gap = (bin_residual - item_size) as f64 / cap;
    if gap > 0.0 && gap < 0.12 {
        score -= (0.12 - gap) * 48.0;
    } else if gap >= 0.12 && gap < 0.22 && fitting_bins_count <= 3 {
        score += (gap - 0.12) * 18.0 * (0.5 + progress * 0.5);
    } else if gap >= 0.22 && gap < 0.30 && fitting_bins_count <= 2 {
        score += (gap - 0.22) * 22.0 * (0.6 + progress * 0.4);
    }

    // Last-chance bin: strong consolidation bonus
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
        if gap > 0.0 && gap < 0.06 {
            score -= 7.0 * (1.0 - progress * 0.5);
        }
    }

    // Mean-residual waste coupling
    if post_residual > 0 && mean_residual > 0.0 {
        let waste = post_norm - (mean_residual / cap);
        if waste > 0.0 {
            score += waste * 30.0 * (0.4 + progress * 0.6);
        } else {
            score -= (-waste) * 10.0;
        }
    }

    // Open-bins pressure
    if bin_residual != bin_capacity {
        let pressure = open_bins_count as f64 * (0.15 + 0.25 * progress);
        score += pressure * 0.5;
        score += (mean_residual - bin_residual as f64) * 0.3;
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        let size_pull = (item_size as f64 / cap) * 14.0;
        if fitting_bins_count == 0 {
            score = 10.0 + size_pull * 0.5; // must open
        } else if fitting_bins_count <= 2 {
            score = 30.0 + 10.0 * progress - (18.0 + size_pull) * (1.0 - progress * 0.6);
        } else {
            score = 30.0 + 10.0 * progress + 20.0 + open_bins_count as f64 * (0.5 + 0.5 * progress);
        }
        // Poor fit everywhere -> opening is fine
        if fitting_bins_count >= 1 && (item_size as f64) > bin_residual as f64 * 0.9 {
            score -= 15.0;
        }
        // Reserve bins for huge next item
        if next_item_size > 0 && next_item_size >= 90 {
            score -= 10.0;
        }
        // Pairing check: item + next fits in fresh bin
        if next_item_size > 0 && (item_size as f64) + (next_item_size as f64) <= cap && (item_size as f64) / cap > 0.35 {
            score -= 3.0 * (1.0 - progress);
        }
        // Large items early: prefer fresh bins
        if (item_size as f64) > cap * 0.5 && progress < 0.5 {
            score -= 6.0 * (1.0 - progress);
        }
        if progress > 0.85 && (item_size as f64) / cap > 0.6 {
            score -= 4.0 * (progress - 0.85) * 20.0;
        }
        // Post-residual will be near-perfect slot for next item
        if next_item_size > 0 && post_residual > 0 {
            let second_slack = (pr - next_item_size as f64) / cap;
            if second_slack >= 0.0 && second_slack < 0.05 {
                score -= (0.05 - second_slack) * 40.0 * (0.5 + progress * 0.5);
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Time horizon: later in the stream -> be more conservative, prefer tight fits.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let urgency = 0.5 + progress; // in [0.5, 1.5]

    // Last-chance bin: strongly reward using it, scaled by urgency.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0 * urgency;
    }

    // Lookahead coupling (k=2): reward if next item fits in the post residual.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Perfect chain: item + next item exactly fills -> big bonus.
            if post_residual == next_item_size {
                score -= 45.0;
            } else {
                score -= 15.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
            }
        } else {
            // Next item won't fit here: penalize leaving a large awkward gap.
            let dead = post_residual as f64;
            score += 0.35 * dead * urgency;
        }
    }

    // Global state coupling: if many open bins with high mean residual,
    // discourage spreading; prefer filling existing bins.
    if open_bins_count > 0 {
        let spread = mean_residual / bin_capacity as f64;
        if bin_residual != bin_capacity {
            score += 8.0 * spread * (open_bins_count as f64).ln().max(1.0);
        } else {
            // New-bin candidate: only attractive when item is large or existing
            // residuals are small (poor fit prospects).
            let large_item_bonus = (item_size as f64 / bin_capacity as f64) * 30.0;
            score -= large_item_bonus + 10.0 * (1.0 - spread);
            // Penalize opening new bins early in the stream.
            score += 25.0 * (1.0 - progress);
        }
    }

    // Mild preference for tighter existing fits overall.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 10.0 * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
