pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let item = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer small post-residual, with a convex quadratic penalty
    // that grows super-linearly for larger wasted space.
    let mut score = pr + 0.9 * (pr / cap) * (pr / cap) * cap;

    // Smooth non-linear coupling of post-residual with stream progress:
    // early in the stream, tolerate larger residuals (bins can still be
    // filled by future items); late in the stream, penalize dead space harder.
    let progress_weight = 0.25 + 1.5 * progress * progress;
    score += progress_weight * pr;

    // Interaction: post-residual vs mean residual — placing into a bin
    // whose residual deviates from the mean is mildly penalized/rewarded
    // via a smooth cubic coupling.
    let dev = (pr - mean_residual) / cap;
    score += 2.0 * dev * dev * dev * cap;

    // Reward tight fits smoothly: sigmoid-like term on item/residual ratio.
    let fit_ratio = item / bin_residual.max(1) as f64;
    score -= 4.0 * fit_ratio * fit_ratio;

    // Last-chance bonus: if this is the only fitting bin, strongly reward
    // using it (smoothly scaled by post-residual waste).
    if fitting_bins_count == 1 {
        score -= 8.0 * (1.0 - pr / cap);
    }

    // Lookahead coupling: if the next item fits into the post-residual,
    // reward smoothly; otherwise penalize proportionally to the mismatch.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            score -= 3.0 * (nxt / cap);
        } else {
            score += 2.0 * ((nxt - pr) / cap) * ((nxt - pr) / cap) * cap;
        }
    }

    // Mild penalty for many open bins to discourage fragmentation,
    // smoothly normalized.
    score += 0.05 * open_bins_count as f64 * (pr / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
