pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space is worse when it falls into
    // "awkward" residue classes that few item sizes can fill.
    let cap_f = bin_capacity as f64;
    let post = post_residual as f64;

    // Fraction of capacity remaining after placement
    let frac = post / cap_f;
    // Harmonic class: which 1/8th of capacity does post_residual fall into
    let harmonic_class = (post as u32 * 8 / bin_capacity) as i32;

    // Penalize small nonzero post_residuals (wasted dead space) more than
    // large ones; but a post_residual that is exactly a common item size
    // (10..=80 multiples of 5, or exact 100-cap fractions) is fine.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual == 0 {
        score -= 12.0; // perfect fit
    }

    // Reward post_residuals that belong to "fillable" classes:
    // classes 0 (empty-ish, flexible) and mid classes divisible by 5/10
    if post_residual % 10 == 0 {
        score -= 6.0;
    } else if post_residual % 5 == 0 {
        score -= 3.0;
    } else {
        score += 4.0; // odd residue class, harder to fill
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size <= post_residual {
            // next item fits but leaves its own residue: partial reward
            let nxt = next_item_size as f64;
            let nxt_class = (nxt * 8.0 / cap_f) as i32;
            let _ = nxt_class;
            score -= 8.0 * (nxt / cap_f);
        } else {
            // next item won't fit here; penalize more if this bin is the only option
            score += 5.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate handling: empty bin should only win when open bins
    // have poor fits. Give the empty bin a mild penalty so tight fits win,
    // but reward it when mean residual across open bins is low.
    if bin_residual == bin_capacity {
        score += 3.0;
        score -= 10.0 * (1.0 - (mean_residual / cap_f).min(1.0));
    } else {
        // Prefer bins tighter than the mean residual (best-fit flavor)
        let diff = bin_residual as f64 - mean_residual;
        score += 0.05 * diff;
    }

    // Stream progression: early on, be conservative (favor flexibility);
    // later, be greedy about closing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 6.0 * progress * frac;

    // Slight penalty for accumulating too many open bins
    score += 0.02 * open_bins_count as f64;

    // Integer-division threshold on post_residual: bins leaving <= 20 space
    // are nearly closed; reward near-closure.
    if post_residual <= 20 && post_residual > 0 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
