pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that no item (1..=100) can ever use
    // are pure waste; small gaps (<=10) are nearly waste.
    if post_residual == 0 {
        score -= 40.0; // perfect fit is ideal
    } else if post_residual < 10 {
        score += 60.0; // unusable dead space
    } else if post_residual <= 20 {
        score += 25.0; // nearly dead space
    } else if post_residual <= 35 {
        score += 8.0;
    }

    // Tightness reward: fraction of the bin actually used by this placement.
    let tightness = item_size as f64 / bin_capacity as f64;
    score -= 20.0 * tightness;

    // Prefer bins whose residual is close to the item (best-fit flavor),
    // scaled by how much slack would remain.
    let waste_ratio = post_residual as f64 / bin_residual.max(1) as f64;
    score += 15.0 * waste_ratio;

    // Open-bin pressure: when many bins are open, avoid spreading;
    // when few are open, opening new bins is cheaper.
    let pressure = (open_bins_count as f64 / 8.0).min(3.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: acceptable early or when fits are scarce,
        // penalized when many bins are already open.
        score += 10.0 + 12.0 * pressure;
        if fitting_bins_count <= 1 {
            score -= 25.0; // last chance: new bin is fine
        }
    } else {
        // Reusing an open bin relieves pressure.
        score -= 6.0 * pressure;
        if fitting_bins_count == 1 {
            score -= 18.0; // last chance before opening a new bin
        }
    }

    // Lookahead: if the next item fits into the resulting residual, reward it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
            let leftover = post_residual - next_item_size;
            if leftover < 10 {
                score -= 6.0; // chain that ends in a perfect/usable fit
            }
        } else if post_residual < 10 {
            score += 5.0; // dead space blocks the future anyway
        }
    }

    // Late in the stream, close out bins aggressively (favor tighter fills).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - waste_ratio);

    // Slight nudge toward bins below mean residual (balance consolidation).
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let next = next_item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items.max(1) as f64 } else { 0.0 };
    let post_norm = pr / cap;
    let fit_ratio = item_size as f64 / cap;
    let gap = (bin_residual - item_size) as f64 / cap;
    let mut score = post_norm * post_norm * 52.0 + post_norm * 20.5;

    // Exact / near-exact fit bonuses (borrowed strength from best-known).
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 42.0;
    } else if post_residual <= 9 {
        score -= 18.0 * (1.0 - progress * 0.4);
    }

    // Tiny stranded residual floor: penalize residuals too small for small items.
    let dead_floor = if next_item_size > 0 { (next_item_size.min(12) as f64).max(6.0) } else { 10.0 };
    if post_residual > 0 && pr < dead_floor && pr != next {
        score += 62.0 * (1.0 - progress * 0.3);
    } else if post_residual > 0 && post_residual < 20 {
        score += 25.0;
    }

    // ---- 2-step lookahead around the NEXT item ----
    if next > 0.0 {
        if pr == next {
            score -= 45.0;
        } else if pr > next {
            let slack = pr - next;
            let diff = slack / cap;
            score -= (-diff * diff * 450.0).exp() * 24.0 * (1.0 - progress * 0.5);
            if diff < 0.04 {
                score -= (0.04 - diff) * 26.0 * (0.6 + progress * 0.6);
            } else if diff > 0.16 {
                score += (diff - 0.16) * 8.0 * (0.5 + progress);
            }
            // Snug remainder after next item lands (from best-known).
            let second_slack = diff;
            if second_slack >= 0.0 && second_slack < 0.05 {
                score -= (0.05 - second_slack) * 40.0 * (0.5 + progress * 0.5);
            }
        } else if pr > 0.0 {
            let dead_ratio = (next - pr) / cap;
            score += dead_ratio * 90.0 * (0.6 + progress * 0.6);
            if fitting_bins_count <= 2 {
                score += 18.0 * (1.0 - progress * 0.5);
            }
        }
        // Two-next-items chain bonus.
        if post_residual > 0 && pr >= next * 2.0 && pr < next * 2.0 + 8.0 {
            score -= 8.0 * (1.0 - progress * 0.4);
        }
    }

    // ---- Relative-to-mean coupling ----
    if post_residual > 0 && mean_residual > 0.0 {
        let waste = (pr - mean_residual) / cap;
        if waste > 0.0 {
            score += waste * 30.0 * (0.4 + progress * 0.6);
        } else {
            score -= (-waste) * 10.0;
        }
    }

    // ---- New-bin candidate decision ----
    if bin_residual == bin_capacity {
        let size_pull = fit_ratio * 14.0;
        if fitting_bins_count <= 2 {
            score -= (18.0 + size_pull) * (1.0 - progress * 0.6);
        } else {
            score += 20.0 + open_bins_count as f64 * (0.5 + 0.5 * progress);
        }
        if next > 0.0 && fitting_bins_count <= 3 && fit_ratio >= next / cap * 0.95 {
            score -= 5.5 * (1.0 - progress * 0.5);
        }
        if next > 0.0 && fit_ratio + next / cap > 1.0 {
            score += 8.0 * (1.0 - progress * 0.4);
        }
        if fit_ratio > 0.5 && progress < 0.5 {
            score -= 6.0 * (1.0 - progress);
        }
        if progress > 0.85 && fit_ratio > 0.6 {
            score -= 4.0 * (progress - 0.85) * 20.0;
        }
        if next > 0.0 && fit_ratio + next / cap <= 1.0 && fit_ratio > 0.35 {
            score -= 3.0 * (1.0 - progress);
        }
    }

    // Sharp bonus for leaving a tiny gap.
    if gap > 0.0 && gap < 0.12 {
        score -= (0.12 - gap) * 48.0;
        if fitting_bins_count == 1 && gap < 0.06 {
            score -= 7.0 * (1.0 - progress * 0.5);
        }
    } else if gap >= 0.12 && gap < 0.22 {
        if next > 0.0 && pr > 0.0 && pr < next {
            score += (gap - 0.12) * 90.5 * (0.5 + progress);
        } else if fitting_bins_count <= 3 {
            score += (gap - 0.12) * 18.0 * (0.5 + progress * 0.5);
        }
    }
    if gap >= 0.22 && gap < 0.30 && fitting_bins_count <= 2 {
        score += (gap - 0.22) * 22.0 * (0.6 + progress * 0.4);
    }

    // Next-item chain: leftover after next item nearly closes bin.
    if next > 0.0 && gap > 0.12 {
        let nxt_gap = ((gap * cap - next).max(0.0)) / cap;
        if nxt_gap < 0.06 {
            score -= 9.0 * (1.0 - nxt_gap / 0.06) * (0.5 + progress);
        }
    }

    // Reward large items filling bins deeply.
    score -= fit_ratio * fit_ratio * 6.0;

    // Congestion: penalize sloppy fits when many bins compete.
    if fitting_bins_count > 2 {
        score += gap * 6.5 * ((fitting_bins_count.min(12) as f64 - 2.0) / 10.0);
    }
    if open_bins_count > 8 {
        score += post_norm * 5.0 * ((open_bins_count.min(20) as f64 - 8.0) / 12.0);
    }

    // Late-stream consolidation.
    if progress > 0.7 && post_norm > 0.25 {
        score += (post_norm - 0.25) * 6.0 * (progress - 0.7) / 0.3;
    }

    // Last-chance bonus: prefer a bin that would otherwise be wasted.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 - fit_ratio);
    }

    // Deep fill bonus.
    let fill_r = item_size as f64 / bin_residual.max(1) as f64;
    if fill_r > 0.90 && bin_residual != bin_capacity {
        score -= (fill_r - 0.90) * 18.0 * (0.6 + progress * 0.5);
    }

    // Dead-space guard for small stranded after-next gaps.
    if next > 0.0 && pr > 0.0 {
        let after_next = (pr - next).max(0.0);
        let dead = after_next / cap;
        if dead > 0.0 && dead < 0.08 && after_next < next {
            score += (0.08 - dead) * 16.0 * (0.5 + progress);
        }
        // Modular chain fit: leftover divisible by next item.
        if pr >= next {
            let frac = ((pr - next) % next.max(1.0)) / next.max(1.0);
            if frac < 0.08 {
                score -= 10.0 * (1.0 - progress * 0.5);
            }
        }
    }

    // Mid-residual band stranding penalty.
    if pr > 0.0 && post_norm >= 0.10 && post_norm < 0.20 && next > 0.0 && next > pr {
        score += (next - pr) / cap * 26.0 * (0.4 + progress * 0.8);
    }

    // Half-consumed bins late in the stream.
    if pr > 0.0 && pr < item_size as f64 * 0.5 && progress > 0.3 {
        score += 4.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual
    // closely matches the next item's size (chained placement).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        let gap = (pr - nxt).abs();
        if pr >= nxt {
            // Next item fits here afterward: reward tight chains.
            score -= 18.0 * (1.0 - gap / bin_capacity as f64);
            // Perfect chain (post_residual == next_item_size): big bonus.
            if gap < 0.5 {
                score -= 12.0;
            }
        } else {
            // Next item won't fit after this placement; penalize
            // proportionally to how much it overshoots.
            score += 6.0 * (gap / 100.0).min(1.0);
        }
    }

    // Compare post_residual against mean residual: leaving this bin
    // far below mean residual creates an outlier dead-space bin.
    let pr = post_residual as f64;
    let dev = pr - mean_residual;
    score += 0.08 * dev.abs();
    // Slightly prefer keeping residuals near the mean.
    score -= 0.03 * dev;

    // Last-chance bin: if this is the only bin that fits, strongly
    // favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Penalize tiny unusable post-residuals (< 10) — dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 10.0;
    } else if post_residual == 0 {
