        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive
    // early in the stream or when no open bin fits well.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let pressure = if fitting_bins_count == 0 { 0.0 } else { 20.0 };
        score += pressure + 25.0 * (1.0 - progress);
    }

    // Mild preference for filling fuller bins when many are open.
    score -= 0.05 * (bin_residual - item_size) as f64 * (open_bins_count as f64 / (open_bins_count as f64 + 10.0));

    score
}

