    score -= 12.0 * (1.0 - post_residual as f64 / bin_capacity as f64).powi(3);

    // Penalize dead space that no typical small item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // Mild penalty when many alternatives exist, encouraging spreading.
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // Lookahead: prefer bins whose post_residual matches the next item well.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
