        if bin_residual as f64 - mean_residual > 20.0 && open_bins_count > 0 {
            score += 10.0; // existing bins have poor residuals, new bin ok-ish
        } else {
            score += 30.0; // default: prefer existing bins
        }
        if open_bins_count == 0 {
            score -= 100.0; // must open the first bin
