        let waste = post_norm - mean_residual / cap;
        if waste > 0.0 {
            score += waste * 30.0 * (0.4 + progress * 0.6);
        } else {
            score -= (-waste) * 10.0;
        }
    }

    if pr > 0.0 && next > 0.0 && pr < next && post_norm > 0.03 {
        score += (next - pr) / cap * 20.0 * (0.5 + progress * 0.5);
    }

    if next > 0.0 && pr > 0.0 && (pr - next) / cap < 0.02 && pr >= next {
        score -= 6.0 * (1.0 - (pr - next) / cap / 0.02) * (0.5 + progress);
    }

    if next > 0.0 && pr > 0.0 && pr >= next {
        let frac = ((pr - next) % next.max(1.0)) / next.max(1.0);
        if frac < 0.08 {
            score -= 10.0 * (1.0 - progress * 0.5);
        }
    }

    if next > 0.0 && pr >= next * 2.0 && pr < next * 2.0 + 8.0 {
        score -= 8.0 * (1.0 - progress * 0.4);
    }

    if fitting_bins_count == 1 && gap > 0.0 && gap < 0.06 {
        score -= 7.0 * (1.0 - progress * 0.5);
    }

    if next > 0.0 && post_residual > 0 && post_residual < next_item_size && fitting_bins_count <= 2 {
        score += 18.0 * (1.0 - progress * 0.5);
    }

    if next > 0.0 && pr >= next && fitting_bins_count > 1 {
        let chain = pr - next;
        let chain_ref = mean_residual.max(1.0) * 0.35;
        if chain < chain_ref {
            score -= 5.0 * (1.0 - chain / chain_ref) * (0.5 + progress * 0.5);
        }
    }

    if post_norm > 0.03 && post_norm < 0.10 {
        if next > 0.0 && pr >= next {
            score -= 4.0 * (1.0 - progress * 0.5);
        } else {
            score += 6.0 * (0.5 + progress * 0.5);
        }
    }

    if next > 0.0 && pr > 0.0 && pr >= next && fill_r > 0.85 {
        let reuse = (pr - next) / cap;
        if reuse < 0.06 {
            score -= (0.06 - reuse) * 30.0 * (0.5 + progress * 0.5);
        }
    }

    if post_norm >= 0.10 && post_norm < 0.18 && next > 0.0 && pr < next {
        score += (0.18 - post_norm) * 14.0 * (0.4 + progress * 0.6);
    }

    // Residual-consolidation (strengthened): near-exact multiples of next item.
    if next > 0.0 && pr >= next {
        let fits_ahead = (pr / next).floor();
        if fits_ahead >= 2.0 {
            let remainder = pr - fits_ahead * next;
            let rem_norm = remainder / cap;
            if rem_norm > 0.005 {
                score += rem_norm * 55.0 * (0.5 + progress * 0.5);
            } else {
                score -= 6.0 * (1.0 - progress * 0.4);
            }
        }
    }

    // COMBINED: two-item lookahead sweep — check whether residual after next item
    // can host a third item class-sized chunk, coupling fine residual fitting with
    // deeper anticipation to squeeze out mid-band dead space.
    if next > 0.0 && pr > next {
        let after_next = pr - next;
        let third = (after_next / next).floor();
        if third >= 1.0 {
            let leftover = after_next - third * next;
            let lo_norm = leftover / cap;
            if lo_norm < 0.02 {
                score -= (0.02 - lo_norm) * 22.0 * (0.6 + progress * 0.4);
            }
        } else {
            let stranded = after_next / cap;
            if stranded > 0.005 {
                score += stranded * 34.0 * (0.5 + progress * 0.5);
            }
        }
    }

    // Late-stream residual sweep.
    let remaining = if total_items > step_index { total_items - step_index } else { 1 };
    if remaining < 12 && post_residual > 0 {
        score += post_norm * 40.0;
    }

    // Tighten congestion penalty for sloppy fits when many bins compete.
    if fitting_bins_count >= 5 && gap > 0.25 {
        score += (gap - 0.25) * 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: dead space quantization.
    // Post-residuals in [0,9] are near-perfect fits; [10,30] are "harmonic" leftovers
    // that small future items (10..30) can still use; >30 is increasingly wasted.
    let pr = post_residual;
    if pr == 0 {
        score -= 25.0; // perfect close: best possible outcome
    } else if pr < 10 {
        score -= 18.0 - pr as f64; // tiny dead space, still rewarded
    } else if pr <= 30 {
        // harmonic zone: leftover matches the common small-item band
        score -= 6.0;
        // bonus if the next item exactly harmonizes with the leftover
        if next_item_size > 0 && next_item_size <= pr {
            score -= 4.0;
            if pr % next_item_size == 0 {
                score -= 3.0; // exact harmonic fill possible
            }
        }
    } else {
        // large leftover: penalize proportionally above the harmonic band
        score += (pr as f64 - 30.0) * 0.35;
        // modulo classes: leftover mod 10 tells how "alignable" it is with
        // the 10..80 integer item grid; aligned leftovers are easier to fill.
        let m = pr % 10;
        score += (5 - m) as f64 * 0.8; // m=0 aligned, m=9 worst
    }

    // Integer-division thresholds on item size classes (harmonic packing classes).
    let cls = item_size / 10; // 1..=8
    match cls {
        1 | 2 => score -= 2.0,  // small items: flexible, mild reward anywhere
        3 | 4 => score += 0.0,  // neutral
        5 | 6 => score += 3.0,  // mid items: prefer tight bins, penalize loose fits
        _ => score += 6.0,      // large items: strongly prefer tight fits
    }
    // Coupling: large items in a bin with big residual is fine, small items
    // in a nearly-full bin is fine; penalize the mismatch.
    let tightness = 1.0 - (bin_residual as f64) / cap;
    score += tightness * (cls as f64) * 0.5;

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 10.0;
    } else if fitting_bins_count > 3 {
        // many alternatives: be picky, demand better fit
        score += (fitting_bins_count as f64 - 3.0) * 0.5;
    }

    // New-bin candidate logic: an empty bin has huge residual; make it
    // attractive only when no open bin offers a good (harmonic) fit.
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score = cap * 0.9;
        // if the item is large, a fresh bin is often the right home
        if cls >= 6 {
            score -= 20.0;
        }
        // if few bins fit the item and existing residuals are large/misaligned,
        // opening a new bin becomes competitive
        if fitting_bins_count <= 1 {
            score -= 15.0;
        }
        if mean_residual < 25.0 {
            score -= 10.0; // open bins are nearly full anyway
        }
        // lookahead: if next item is small, a fresh bin preserves capacity
        if next_item_size > 0 && next_item_size <= 30 {
            score -= 8.0;
        }
    }

    // Mild stream-phase adaptation: early on, slightly prefer consolidation
    // into existing bins; late, accept tighter fits more readily.
    let phase = step_index as f64 / (total_items.max(1) as f64);
    score -= phase * 2.0;

    // Deviation from mean residual: prefer bins whose residual is close to
    // the mean (keeps the bin pool homogeneous and fillable).
    score += (bin_residual as f64 - mean_residual).abs() * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny leftovers are nearly useless.
    if post_residual > 0 {
        if post_residual < 10 {
            // Unusable dead space (below min item size 1..100 interface: small gaps)
            score += 60.0;
        } else if post_residual <= 20 {
            score += 25.0;
        } else if post_residual <= 35 {
            score += 8.0;
        }
    } else {
        // Perfect fill: strong reward
        score -= 150.0;
    }

    // Reward good tight fits relative to bin capacity.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 40.0 * fill_ratio;

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Open-bin pressure: when many bins are open, discourage spreading;
    // when few bins are open, opening new bins is cheaper.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (0.6 + 0.8 * progress);
    score += pressure * 0.5;

    // New-bin candidate handling: neutral-ish baseline, penalize slightly
    // unless existing bins would create bad dead space.
    if bin_residual == bin_capacity {
        score = 100.0 - 40.0 * fill_ratio + pressure * 0.3;
        // If the only fitting bin is bad, opening a new bin is attractive.
        if fitting_bins_count == 1 {
            let alt_post = bin_residual.saturating_sub(item_size);
            if alt_post < 10 {
                score -= 70.0;
            }
        }
    }

    // Lookahead: if next item can exactly fill this bin's post-residual, reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 90.0;
    } else if next_item_size > post_residual && post_residual > 0 {
        // Next item cannot use the leftover: dead space is certain for this bin's cycle
        score += 10.0;
    }

    // Prefer bins below mean residual (consolidating space).
    score += (mean_residual - bin_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
