pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post residual) nonlinearly.
    score -= 40.0 * (-post_residual as f64 / 15.0).exp();

    // Penalize leaving dead space that cannot fit the next item (lookahead).
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 0.35 * (next_item_size - post_residual) as f64;
        } else {
            // Reward bins that can still host the next item.
            score -= 0.15 * (post_residual - next_item_size).min(30) as f64;
        }
    } else {
        // Last item: prefer filling bins as fully as possible.
        score += 0.5 * post_residual as f64;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual < bin_capacity {
        score -= 8.0 + 0.05 * item_size as f64;
    }

    // Penalize opening new bins when many open bins exist with slack.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 5.0 + 10.0 * (1.0 - progress) + 0.5 * open_bins_count as f64;
        // But if mean residual is large and fragmented, a fresh bin may be fine.
        score -= 0.03 * mean_residual;
    }

    // Mild preference for bins tighter than average (good packing density).
    score += 0.05 * (mean_residual - bin_residual as f64);

    // Prefer using bins whose residual is close to the item (best-fit flavor),
    // scaled by stream progress.
    let diff = (bin_residual as f64 - item_size as f64).abs();
    score += 0.10 * diff * (1.0 - step_index as f64 / total_items.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap;

    // Base: prefer small post-residual, with smooth polynomial shaping
    let mut score = pr * (1.0 + 0.5 * x * x);

    // Non-linear coupling with stream progress: later in the stream, penalize
    // wasted residual more strongly (dead space hurts more near the end)
    let progress_weight = t * t * (3.0 - 2.0 * t); // smoothstep
    score += progress_weight * pr * pr / cap;

    // Coupling with mean residual: penalize bins whose post-residual deviates
    // from the fleet mean (keep residuals homogeneous for future fits)
    score += 0.3 * (pr as f64 - mean_residual).abs();

    // Last-chance bonus: if this is the only fitting bin, strongly favor it
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Lookahead coupling: reward if next item fits the post-residual
    if next_item_size > 0 {
        let fits_next = (post_residual >= next_item_size) as i32 as f64;
        let tightness = 1.0 - ((post_residual - next_item_size) as f64 / cap).abs();
        score -= fits_next * (10.0 + 20.0 * tightness * (1.0 - t));
    } else {
        // Last item: strongly prefer tightest fit
        score -= 25.0 * (1.0 - x);
    }

    // Mild penalty for leaving exactly awkward residuals via smooth oscillation
    score += 2.0 * (std::f64::consts::PI * x).sin() * x;

    // Slight preference for fewer open bins when residuals are large
    score += 0.05 * open_bins_count as f64 * x;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes: classify post_residual by capacity fraction (integer division).
    // Residuals in the lowest quarter are excellent (near-perfect fit).
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    let class = post_residual / quarter; // 0,1,2,3 harmonic class
    match class {
        0 => score -= 40.0,                                  // tiny residual: reward strongly
        1 => score -= 10.0,                                  // small residual
        2 => score += 5.0,                                   // half-empty: mild penalty
        _ => {}                                              // mostly empty bin used: neutral
    }

    // Modulo arithmetic on post_residual: residuals that divide capacity nicely
    // (multiples of small harmonics 10/20/25/50) pair well with common item sizes.
    let pr = post_residual as i64;
    let harmonic_bonus: f64 = if pr % 10 == 0 {
        -8.0
    } else if pr % 25 == 0 {
        -5.0
    } else if pr % 5 == 0 {
        -3.0
    } else {
        2.0
    };
    score += harmonic_bonus;

    // Lookahead coupling: does next item fit exactly into the post residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect two-item chain: extremely desirable
        } else if next_item_size < post_residual {
            let leftover = post_residual - next_item_size;
            // penalize chained placements that strand awkward dead space
            if leftover < quarter {
                score -= 15.0;
            } else if leftover > half {
                score += 8.0;
            }
        } else {
            // next item cannot follow into this bin; a large stranded residual is waste
            if post_residual > half {
                score += 12.0;
            }
        }
    } else {
        // last item: minimize final residual hard
        score += post_residual as f64 * 0.5;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive when
    // existing residuals are all poor fits for the item (large dead-space risk).
    if bin_residual == bin_capacity {
        let spread = (mean_residual - post_residual as f64).abs();
        let pressure = mean_residual / bin_capacity as f64; // how full open bins are on average
        // penalize new bin normally; reward it when open bins are nearly full/tight
        score += 30.0 - 45.0 * pressure - 10.0 * (spread / bin_capacity as f64);
        // early in the stream, keep bins open instead of proliferating
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 * (1.0 - progress);
    }

    // Slight preference to fill already-open bins as they approach capacity.
    if bin_residual < bin_capacity {
        let fill = 1.0 - (bin_residual as f64 / bin_capacity as f64);
        score -= 6.0 * fill;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post_residual as f64;

    // Perfect fit: strong reward (subtract).
    if post_residual == 0 {
        score -= 200.0;
    }

    // Dead-space class: residuals in (0, 12] are almost unusable.
    if post_residual > 0 && post_residual <= 12 {
        score += 25.0 * (13.0 - post_residual as f64);
    }

    // Harmonic divisibility rewards.
    if post_residual > 0 {
        let pr = post_residual;
        if pr % 50 == 0 { score -= 18.0; }
        else if pr % 25 == 0 { score -= 12.0; }
        else if pr % 20 == 0 { score -= 10.0; }
        else if pr % 10 == 0 { score -= 8.0; }
        else {
            score += (pr % 5) as f64 * 1.5;
        }
    }

    // Lookahead: next item fit quality in post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size < post_residual {
            let nxt_left = post_residual - next_item_size;
            if nxt_left % 10 == 0 {
                score -= 10.0;
            } else if nxt_left > 12 {
                score -= 4.0;
            } else {
                score += 6.0;
            }
            // Tight post-fit: near-exact pairing with next item.
            let slack = (post_residual - next_item_size) as f64 / cap;
            score -= (-slack * slack * 450.0).exp() * 20.0 * (1.0 - progress * 0.5);
            // Two-next anticipation: post_residual can host next item twice.
            if (post_residual as f64) >= (next_item_size as f64) * 2.0 {
                score -= 6.0 * (1.0 - progress * 0.4);
            }
        } else {
            // next item cannot use this leftover: wasted space penalty
            let dead_ratio = (next_item_size as f64 - post_residual as f64) / cap;
            score += 8.0 + dead_ratio * 70.0 * (0.6 + progress * 0.6);
            // Small dead leftover with few alternatives: extra penalty.
            if fitting_bins_count <= 2 {
                score += 18.0 * (1.0 - progress * 0.5);
            }
        }
    }

    // Tight-gap bonus: prefer bins where item nearly fills residual.
    let gap = (bin_residual - item_size) as f64 / cap;
    if gap > 0.0 && gap < 0.12 {
        score -= (0.12 - gap) * 48.0;
    } else if gap >= 0.12 && gap < 0.22 && fitting_bins_count <= 3 {
        score += (gap - 0.12) * 18.0 * (0.5 + progress * 0.5);
    } else if gap >= 0.22 && gap < 0.30 && fitting_bins_count <= 2 {
        score += (gap - 0.22) * 22.0 * (0.6 + progress * 0.4);
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let crowding = open_bins_count as f64 / 10.0;
        if fitting_bins_count <= 2 {
            // Sparse alternatives: opening is cheap, slightly favor larger items there.
            score = 30.0 + 20.0 * progress - (item_size as f64 / cap) * 12.0;
            if fitting_bins_count == 0 {
                score -= 100.0; // must open a bin
            }
        } else {
            score = 60.0 + 45.0 * progress - crowding.min(3.0) * 10.0;
        }
        // Large item early: worth a fresh bin to keep it isolated.
        if (item_size as f64) > cap * 0.5 && progress < 0.5 {
            score -= 6.0 * (1.0 - progress);
        }
        // If next item pairs with current item in a fresh bin, encourage opening.
        if next_item_size > 0 && (item_size as f64) + (next_item_size as f64) <= cap && (item_size as f64) / cap > 0.35 {
            score -= 3.0 * (1.0 - progress);
        }
        // Avoid fresh bin when current item cannot pair with next item there.
        if next_item_size > 0 && (item_size as f64) + (next_item_size as f64) > cap {
            score += 8.0 * (1.0 - progress * 0.4);
        }
        // Late stream, large item: keep fresh-bin preference.
        if progress > 0.85 && (item_size as f64) / cap > 0.6 {
            score -= 4.0 * (progress - 0.85) * 20.0;
        }
    }

    // Global pressure: high mean residual -> pack tight bins.
    score -= (mean_residual / cap) * 5.0;

    // Waste-relative pressure: penalize bins whose post-residual exceeds mean.
    if post_residual > 0 && mean_residual > 0.0 {
        let waste = (post_residual as f64 / cap) - (mean_residual / cap);
        if waste > 0.0 {
            score += waste * 30.0 * (0.4 + progress * 0.6);
        } else {
            score -= (-waste) * 10.0;
        }
    }

    // Near-perfect post fit reward: post_residual very small relative to capacity.
    if post_residual > 0 {
        let post_norm = post_residual as f64 / cap;
        if post_norm < 0.03 {
            score -= 10.0 * (1.0 - post_norm / 0.03) * (0.5 + progress * 0.5);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps are nearly unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // tiny sliver gap: strongly penalize
    } else if post_residual < 20 {
        score += 25.0;
    } else if post_residual < 35 {
        score += 8.0;
    }

    // Reward tight fits (post_residual small relative to item size).
    let fit_ratio = post_residual as f64 / (item_size.max(1) as f64);
    score -= 40.0 * (1.0 - fit_ratio.min(1.0));

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 70.0;
    }

    // Open-bin pressure: with many bins open, discourage spreading; prefer filling.
    let open_pressure = (open_bins_count as f64).ln().max(0.0);
    score += 6.0 * open_pressure * (post_residual as f64 / bin_capacity as f64);

    // Lookahead: if next item fits exactly in post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 10 {
        score -= 45.0;
    }
    // Penalize if next item cannot fit in post_residual (fragmentation risk).
    if next_item_size > post_residual && post_residual > 0 && post_residual < 15 {
        score += 15.0;
    }

    // New-bin candidate handling: only attractive when open bins are very fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = mean_residual / bin_capacity as f64;
        // Prefer new bin if mean residual is small (open bins nearly full).
        let new_bin_score = 55.0 - 80.0 * fragmentation.min(1.0);
        // Early in stream, opening bins is cheap; late, prefer consolidation.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let new_bin_score = new_bin_score + 20.0 * progress;
        score = new_bin_score;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fits are excellent: reward small post_residual strongly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Two-step lookahead: if the next item fits exactly into the post residual,
    // this placement creates a perfect chain — reward heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 30.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Next item cannot use this bin's leftover: penalize dead space.
        score += 0.6 * (post_residual as f64 - next_item_size as f64).abs();
    }

    // Prefer bins whose residual deviates favorably from the mean residual
    // (filling the emptiest-but-fitting bin keeps tight bins intact).
    score -= 0.3 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New empty bin candidate: only attractive when the item is large
    // or the fit in existing bins would be very poor.
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        let poor_fit = post_residual as f64 > 40.0;
        if fill_ratio > 0.6 || poor_fit {
            score -= 10.0 + 20.0 * fill_ratio;
        } else {
            score += 15.0; // discourage wasting a fresh bin on small items
        }
    }

    // Mild preference to consolidate into fewer bins early in the stream.
    score += 0.5 * open_bins_count as f64 * (1.0 - step_index as f64 / total_items.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize high post-residual more when it's dead space.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Lookahead: if the next item fits the post-residual exactly or well, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chain
        } else if next_item_size <= post_residual {
            let chain_fit = 1.0 - (post_residual - next_item_size) as f64 / (bin_capacity as f64);
            score -= 35.0 * chain_fit;
        } else {
            // Next item won't fit here; penalize leaving large unusable residue.
            let dead = (post_residual as f64) / (bin_capacity as f64);
            score += 25.0 * dead * dead;
        }
    } else {
        // Last item: prefer minimizing post residual only.
        score -= 20.0 * tightness;
    }

    // Last-chance bin: strongly favor using the only bin that fits, avoid opening new bins.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when residuals across open bins are tight
    // or the item is large and would leave awkward residue in existing bins.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mean_tight = 1.0 - (mean_residual / (bin_capacity as f64)).clamp(0.0, 1.0);
        // Open new bins early when open bins are loose; late in stream, prefer packing.
        let new_bin_bonus = 45.0 * (1.0 - progress) * (1.0 - mean_tight);
        score -= new_bin_bonus;
        // Penalize new bin if item is small (waste of capacity).
        score += (item_size as f64) * 0.4;
        // Penalize new bin when plenty of fitting bins exist.
        if fitting_bins_count > 1 {
            score += 50.0;
        }
    }

    // Mild preference for bins below mean residual (consolidate loose space).
    score += ((bin_residual as f64) - mean_residual) * 0.15;

    // Slight reward for filling larger fraction of the bin used.
    let fill = 1.0 - (bin_residual as f64) / (bin_capacity as f64);
    score -= 10.0 * fill;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let next = next_item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items.max(1) as f64 } else { 0.0 };
    let post_norm = pr / cap;
    let fit_ratio = item_size as f64 / cap;
    let gap = (bin_residual - item_size) as f64 / cap;
    let mut score = post_norm * post_norm * 50.0 + post_norm * 20.0;

    // ---- 2-step lookahead: shape score around the NEXT item ----
    if next > 0.0 {
        if pr == next {
            score -= 54.0;
        } else if pr > next {
            let slack = pr - next;
            let diff = slack / cap;
            score -= 20.0 * (1.0 - diff).max(0.0);
            score -= (-diff * diff * 450.0).exp() * 24.0 * (1.0 - progress * 0.5);
            if diff < 0.04 {
                score -= (0.04 - diff) * 30.0 * (0.6 + progress * 0.6);
            } else if diff > 0.16 {
                score += (diff - 0.16) * 8.0 * (0.5 + progress);
            }
        } else if pr > 0.0 {
            let dead_ratio = (next - pr) / cap;
            score += dead_ratio * 90.0 * (0.6 + progress * 0.6);
        }
    }

    // ---- Absolute dead-floor guard: tiny stranded remainders ----
    let dead_floor = if next_item_size > 0 { (next_item_size.min(12) as f64).max(6.0) } else { 10.0 };
    if post_residual > 0 && pr < dead_floor && pr != next {
        score += 62.0 * (1.0 - progress * 0.3);
    } else if post_residual > 0 && post_residual < 20 && pr != next {
        score += 25.0;
    }

    // ---- Relative-to-mean coupling (softened to reduce dead-space variance) ----
    if pr > 0.0 {
        let dev = (mean_residual - pr) / cap;
        if dev > 0.06 {
            score += (dev - 0.06) * 10.0 * (0.4 + progress);
        } else if dev < -0.10 {
            score += (-dev - 0.10) * 5.0 * (1.0 - progress);
        }
    }

    // ---- New-bin candidate decision ----
    if bin_residual == bin_capacity {
        let others = if fitting_bins_count > 0 { fitting_bins_count - 1 } else { 0 };
        let size_pull = fit_ratio * 14.0;
        if fitting_bins_count <= 2 && gap > 0.0 {
            score -= (18.0 + size_pull) * (1.0 - progress * 0.6);
        } else if others == 0 {
            score -= 5.0;
        } else {
            score += 20.0 + open_bins_count as f64 * (0.5 + 0.5 * progress);
        }
        if next > 0.0 && fitting_bins_count <= 3 && fit_ratio >= next * 0.95 / cap {
            score -= 5.5 * (1.0 - progress * 0.5);
        }
        if next > 0.0 && fitting_bins_count >= 1 && fit_ratio * cap + next > cap {
            score += 8.0 * (1.0 - progress * 0.4);
        }
        if next > 0.0 && fit_ratio * cap + next <= cap {
            let pair_left = (cap - fit_ratio * cap - next) / cap;
            if pair_left < 0.05 {
                score -= (0.05 - pair_left) * 42.0 * (0.5 + progress * 0.5);
            } else if fit_ratio > 0.35 {
                score -= 3.0 * (1.0 - progress);
            }
        }
        if fit_ratio > 0.5 && progress < 0.5 {
            score -= 6.0 * (1.0 - progress);
        }
        if progress > 0.85 && fit_ratio > 0.6 {
            score -= 4.0 * (progress - 0.85) * 20.0;
        }
        if next > 0.0 && fit_ratio * cap + next > cap * 0.94 && fitting_bins_count > 2 {
            score -= 6.0 * (1.0 - progress * 0.5);
        }
        if progress > 0.6 && fit_ratio < 0.45 && others > 0 {
            score += 10.0 * (progress - 0.6) / 0.4;
        }
        if next > 0.0 && others > 0 {
            let fresh_left = cap - fit_ratio * cap;
            if fresh_left >= next {
                let fresh_slack = (fresh_left - next) / cap;
                if fresh_slack < 0.03 {
                    score -= (0.03 - fresh_slack) * 26.0 * (0.5 + progress * 0.5);
                }
            }
        }
    }

    // Exact / near-exact fit bonuses.
    if pr == 0.0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 42.0;
    } else if post_residual <= 9 {
        score -= 18.0 * (1.0 - progress * 0.4);
    } else if post_norm < 0.02 && fitting_bins_count >= 4 {
        score -= 6.0 * (1.0 - progress);
    }

    // Sharp bonus for leaving a tiny gap (<12% of capacity).
    if gap > 0.0 && gap < 0.12 {
        score -= (0.12 - gap) * 48.0;
    } else if gap >= 0.12 && gap < 0.22 && next > 0.0 && pr > 0.0 && pr < next {
        score += (gap - 0.12) * 90.5 * (0.5 + progress);
    } else if gap >= 0.12 && gap < 0.22 && fitting_bins_count <= 3 {
        score += (gap - 0.12) * 18.0 * (0.5 + progress * 0.5);
    }
    if gap >= 0.22 && gap < 0.30 && fitting_bins_count <= 2 {
        score += (gap - 0.22) * 22.0 * (0.6 + progress * 0.4);
    }
    // Next-item chain: leftover after next item nearly closes bin.
    if next > 0.0 && gap > 0.12 {
        let nxt_gap = ((gap * cap - next).max(0.0)) / cap;
        if nxt_gap < 0.05 {
            score -= (0.05 - nxt_gap) * 40.0 * (0.5 + progress * 0.5);
        }
    }

    // Reward large items filling bins deeply.
    score -= fit_ratio * fit_ratio * 6.0;

    // Congestion: many competing bins => penalize sloppy fits.
    if fitting_bins_count > 2 {
        score += gap * 6.5 * ((fitting_bins_count.min(12) as f64 - 2.0) / 10.0);
    }
    if open_bins_count > 8 {
        score += post_norm * 5.0 * ((open_bins_count.min(20) as f64 - 8.0) / 12.0);
    }

    // Late-stream consolidation.
    if progress > 0.7 && post_norm > 0.25 {
        score += (post_norm - 0.25) * 6.0 * (progress - 0.7) / 0.3;
    }

    // Last-chance bonus: prefer a bin that would otherwise be wasted.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 - fit_ratio);
    }

    // Deep fill bonus.
    let fill_r = item_size as f64 / bin_residual.max(1) as f64;
    if fill_r > 0.90 && bin_residual != bin_capacity {
        score -= (fill_r - 0.90) * 18.0 * (0.6 + progress * 0.5);
    }

    // Waste-vs-mean term.
    if pr > 0.0 && mean_residual > 0.0 {
        let waste = post_norm - mean_residual / cap;
        if waste > 0.0 {
            score += waste * 30.0 * (0.4 + progress * 0.6);
        } else {
            score -= (-waste) * 10.0;
        }
    }

    // Penalize bins whose post-residual can never host the next item class.
    if pr > 0.0 && next > 0.0 && pr < next && post_norm > 0.03 {
        score += (next - pr) / cap * 20.0 * (0.5 + progress * 0.5);
    }

    // Reward bins that remain exactly reusable by the next item.
    if next > 0.0 && pr > 0.0 && (pr - next) / cap < 0.02 && pr >= next {
        score -= 6.0 * (1.0 - (pr - next) / cap / 0.02) * (0.5 + progress);
    }

    // Periodic divisibility bonus — post-residual is a near-multiple of next item.
    if next > 0.0 && pr > 0.0 && pr >= next {
        let frac = ((pr - next) % next.max(1.0)) / next.max(1.0);
        if frac < 0.08 {
            score -= 10.0 * (1.0 - progress * 0.5);
        }
    }

    // Double-fit bonus — post-residual hosts the next item twice with little slack.
    if next > 0.0 && pr >= next * 2.0 && pr < next * 2.0 + 8.0 {
        score -= 8.0 * (1.0 - progress * 0.4);
    }

    // Last-chance micro-gap bonus.
    if fitting_bins_count == 1 && gap > 0.0 && gap < 0.06 {
        score -= 7.0 * (1.0 - progress * 0.5);
    }

    // Dead-space penalty when few fitting bins and residual too small for next.
    if next > 0.0 && post_residual > 0 && post_residual < next_item_size && fitting_bins_count <= 2 {
        score += 18.0 * (1.0 - progress * 0.5);
    }

    // Chain-closure: residual after placing item can host next item with little slack.
    if next > 0.0 && pr >= next && fitting_bins_count > 1 {
        let chain = pr - next;
        let chain_ref = mean_residual.max(1.0) * 0.35;
        if chain < chain_ref {
            score -= 5.0 * (1.0 - chain / chain_ref) * (0.5 + progress * 0.5);
        }
    }

    // Mid-band residual vacuum.
    if post_norm > 0.03 && post_norm < 0.10 {
        if next > 0.0 && pr >= next {
            score -= 4.0 * (1.0 - progress * 0.5);
        } else {
            score += 6.0 * (0.5 + progress * 0.5);
        }
    }

    // Fine-grained residual fitting with lookahead — item consumes the residual's
    // useful portion and the leftover stays reusable by the next item.
    if next > 0.0 && pr > 0.0 && pr >= next && fill_r > 0.85 {
        let reuse = (pr - next) / cap;
        if reuse < 0.06 {
            score -= (0.06 - reuse) * 30.0 * (0.5 + progress * 0.5);
        }
    }

    // Discourage residuals in the awkward 0.10–0.18 band.
    if post_norm >= 0.10 && post_norm < 0.18 && next > 0.0 && pr < next {
        score += (0.18 - post_norm) * 14.0 * (0.4 + progress * 0.6);
    }

    // Residual-consolidation — prefer placements whose post-residual is a
    // near-exact multiple of the next item, scaled by how many multiples fit.
    if next > 0.0 && pr >= next {
        let fits_ahead = (pr / next).floor();
        if fits_ahead >= 2.0 {
            let remainder = pr - fits_ahead * next;
            let rem_norm = remainder / cap;
            if rem_norm > 0.005 {
                score += rem_norm * 55.0 * (0.5 + progress * 0.5);
            } else {
                score -= 4.0 * (1.0 - progress * 0.4);
            }
        }
    }

    // Late-stream residual sweep — when few items remain, strongly prefer
    // placements that leave near-zero residual even if the fit is loose.
    let remaining = if total_items > step_index { total_items - step_index } else { 1 };
    if remaining < 12 && post_residual > 0 {
        score += post_norm * 40.0;
    }

    // NEW: multi-step chain anticipation — combine fine-grained residual fitting
    // with lookahead: reward placements where the residual can host the next item
    // AND the resulting second-level leftover is still usable by a typical item
    // (approximated by mean_residual), tightening mid-size dead space.
    if next > 0.0 && pr >= next && mean_residual > 0.0 {
        let second_left = pr - next;
        if second_left >= mean_residual * 0.9 {
            score -= 5.0 * (1.0 - progress * 0.5);
        } else if second_left > 0.0 && second_left < mean_residual * 0.5 {
            score += 4.0 * (0.5 + progress * 0.5);
        }
    }

    // NEW: anti-fragmentation — penalize placements that leave a residual just
    // below the next item's size by a hair (worst kind of dead space).
    if next > 0.0 && pr > 0.0 && pr < next {
        let shortfall = (next - pr) / next.max(1.0);
        if shortfall < 0.15 {
            score += (0.15 - shortfall) * 35.0 * (0.6 + progress * 0.4);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Base: prefer small post-residual, with a non-linear (quadratic) penalty
    // so very small residuals are disproportionately favored.
    let mut score = post + 1.2 * (post / cap) * (post / cap) * cap;

    // Smooth stream-progress coupling: late in the stream, tighten bins more
    // aggressively (dead space matters more when the stream is ending).
    let progress_tightening = 1.0 + 0.8 * progress * progress;
    score *= progress_tightening;

    // Reward filling bins deeply relative to mean residual state.
    score -= 0.3 * (mean_residual - post).max(0.0);

    // Last-chance bin: strongly favor using it to avoid opening a new bin,
    // especially late in the stream (smooth interaction, no piecewise switch).
    if fitting_bins_count == 1 {
        score -= 15.0 + 20.0 * progress;
    }

    // Lookahead: penalize leaving a residual that is just barely too small
    // for the next item (near-miss dead space), reward residuals that can
    // still accommodate the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = post - nxt;
        if gap >= 0.0 {
            // next item still fits: mild reward, stronger the tighter it fits
            score -= 5.0 * (-gap / 20.0).exp();
        } else {
            // near-miss penalty: residual wasted just below next item size
            let miss = (-gap) as f64;
            if miss <= 10.0 {
                score += 6.0 * (1.0 - miss / 10.0);
            }
        }
    }

    // New-bin candidate (empty bin): make it unattractive unless it is the
    // only option or the current item would leave a very tight residual in
    // existing bins anyway. Scale reluctance with number of open bins.
    if bin_residual == bin_capacity {
        let reluctance = 10.0 + 2.0 * open_bins_count as f64 * (0.5 + 0.5 * progress);
        score += reluctance;
        // But allow new bin if item is large and would fit snugly (post ~ 0)
        score -= 12.0 * (1.0 - post / cap);
    }

    // Mild penalty for opening many bins relative to stream length.
    score += 0.02 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let next = next_item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items.max(1) as f64 } else { 0.0 };
    let post_norm = pr / cap;
    let fit_ratio = item_size as f64 / cap;
    let gap = (bin_residual - item_size) as f64 / cap;
    let mut score = post_norm * post_norm * 50.0 + post_norm * 20.0;

    // ---- 2-step lookahead with combined residual-fitting anticipation ----
    if next > 0.0 {
        if pr == next {
            score -= 54.0;
        } else if pr > next {
            let slack = pr - next;
            let diff = slack / cap;
            score -= 20.0 * (1.0 - diff).max(0.0);
            score -= (-diff * diff * 450.0).exp() * 24.0 * (1.0 - progress * 0.5);
            if diff < 0.04 {
                score -= (0.04 - diff) * 30.0 * (0.6 + progress * 0.6);
            } else if diff > 0.16 {
                score += (diff - 0.16) * 8.0 * (0.5 + progress);
            }
            // COMBINED: multi-step divisibility anticipation — post-residual
            // that hosts the next item k>=2 times with tiny leftover is gold.
            let fits_ahead = (pr / next).floor();
            if fits_ahead >= 2.0 {
                let remainder = pr - fits_ahead * next;
                let rem_norm = remainder / cap;
                if rem_norm < 0.004 {
                    score -= 7.0 * (1.0 - progress * 0.4);
                } else {
                    score += rem_norm * 55.0 * (0.5 + progress * 0.5);
                }
            }
        } else if pr > 0.0 {
            let dead_ratio = (next - pr) / cap;
            score += dead_ratio * 90.0 * (0.6 + progress * 0.6);
        }
    }

    // ---- Absolute dead-floor guard ----
    let dead_floor = if next_item_size > 0 { (next_item_size.min(12) as f64).max(6.0) } else { 10.0 };
    if post_residual > 0 && pr < dead_floor && pr != next {
        score += 62.0 * (1.0 - progress * 0.3);
    } else if post_residual > 0 && post_residual < 20 && pr != next {
        score += 25.0;
    }

    // ---- Relative-to-mean coupling ----
    if pr > 0.0 {
        let dev = (mean_residual - pr) / cap;
        if dev > 0.06 {
            score += (dev - 0.06) * 10.0 * (0.4 + progress);
        } else if dev < -0.10 {
            score += (-dev - 0.10) * 5.0 * (1.0 - progress);
        }
    }

    // ---- New-bin candidate decision ----
    if bin_residual == bin_capacity {
        let others = if fitting_bins_count > 0 { fitting_bins_count - 1 } else { 0 };
        let size_pull = fit_ratio * 14.0;
        if fitting_bins_count <= 2 && gap > 0.0 {
            score -= (18.0 + size_pull) * (1.0 - progress * 0.6);
        } else if others == 0 {
            score -= 5.0;
        } else {
            score += 20.0 + open_bins_count as f64 * (0.5 + 0.5 * progress);
        }
        if next > 0.0 && fitting_bins_count <= 3 && fit_ratio >= next * 0.95 / cap {
            score -= 5.5 * (1.0 - progress * 0.5);
        }
        if next > 0.0 && fitting_bins_count >= 1 && fit_ratio * cap + next > cap {
            score += 8.0 * (1.0 - progress * 0.4);
        }
        if next > 0.0 && fit_ratio * cap + next <= cap {
            let pair_left = (cap - fit_ratio * cap - next) / cap;
            if pair_left < 0.05 {
                score -= (0.05 - pair_left) * 42.0 * (0.5 + progress * 0.5);
            } else if fit_ratio > 0.35 {
                score -= 3.0 * (1.0 - progress);
            }
        }
        if fit_ratio > 0.5 && progress < 0.5 {
            score -= 6.0 * (1.0 - progress);
        }
        if progress > 0.85 && fit_ratio > 0.6 {
            score -= 4.0 * (progress - 0.85) * 20.0;
        }
        if next > 0.0 && fit_ratio * cap + next > cap * 0.94 && fitting_bins_count > 2 {
            score -= 6.0 * (1.0 - progress * 0.5);
        }
        if progress > 0.6 && fit_ratio < 0.45 && others > 0 {
            score += 10.0 * (progress - 0.6) / 0.4;
        }
        if next > 0.0 && others > 0 {
            let fresh_left = cap - fit_ratio * cap;
            if fresh_left >= next {
                let fresh_slack = (fresh_left - next) / cap;
                if fresh_slack < 0.03 {
                    score -= (0.03 - fresh_slack) * 26.0 * (0.5 + progress * 0.5);
                }
            }
        }
    }

    // Exact / near-exact fit bonuses.
    if pr == 0.0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 42.0;
    } else if post_residual <= 9 {
        score -= 18.0 * (1.0 - progress * 0.4);
    } else if post_norm < 0.02 && fitting_bins_count >= 4 {
        score -= 6.0 * (1.0 - progress);
    }

    // Sharp bonus for leaving a tiny gap (<12% of capacity).
    if gap > 0.0 && gap < 0.12 {
        score -= (0.12 - gap) * 48.0;
    } else if gap >= 0.12 && gap < 0.22 && next > 0.0 && pr > 0.0 && pr < next {
        score += (gap - 0.12) * 90.5 * (0.5 + progress);
    } else if gap >= 0.12 && gap < 0.22 && fitting_bins_count <= 3 {
        score += (gap - 0.12) * 18.0 * (0.5 + progress * 0.5);
    }
    if gap >= 0.22 && gap < 0.30 && fitting_bins_count <= 2 {
        score += (gap - 0.22) * 22.0 * (0.6 + progress * 0.4);
    }
    if next > 0.0 && gap > 0.12 {
        let nxt_gap = ((gap * cap - next).max(0.0)) / cap;
        if nxt_gap < 0.05 {
            score -= (0.05 - nxt_gap) * 40.0 * (0.5 + progress * 0.5);
        }
    }

    score -= fit_ratio * fit_ratio * 6.0;

    if fitting_bins_count > 2 {
        score += gap * 6.5 * ((fitting_bins_count.min(12) as f64 - 2.0) / 10.0);
    }
    if open_bins_count > 8 {
        score += post_norm * 5.0 * ((open_bins_count.min(20) as f64 - 8.0) / 12.0);
    }

    if progress > 0.7 && post_norm > 0.25 {
        score += (post_norm - 0.25) * 6.0 * (progress - 0.7) / 0.3;
    }

    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 - fit_ratio);
    }

    let fill_r = item_size as f64 / bin_residual.max(1) as f64;
    if fill_r > 0.90 && bin_residual != bin_capacity {
        score -= (fill_r - 0.90) * 18.0 * (0.6 + progress * 0.5);
    }

    if pr > 0.0 && mean_residual > 0.0 {
        let waste = post_norm - mean_residual / cap;
        if waste > 0.0 {
            score += waste * 30.0 * (0.4 + progress * 0.6);
        } else {
            score -= (-waste) * 10.0;
        }
    }

    if pr > 0.0 && next > 0.0 && pr < next && post_norm > 0.03 {
        score += (next - pr) / cap * 20.0 * (0.5 + progress * 0.5);
    }

    if next > 0.0 && pr > 0.0 && (pr - next) / cap < 0.02 && pr >= next {
        score -= 6.0 * (1.0 - (pr - next) / cap / 0.02) * (0.5 + progress);
    }

    if next > 0.0 && pr > 0.0 && pr >= next {
        let frac = ((pr - next) % next.max(1.0)) / next.max(1.0);
        if frac < 0.08 {
            score -= 10.0 * (1.0 - progress * 0.5);
        }
    }

    if next > 0.0 && pr >= next * 2.0 && pr < next * 2.0 + 8.0 {
        score -= 8.0 * (1.0 - progress * 0.4);
    }

    if fitting_bins_count == 1 && gap > 0.0 && gap < 0.06 {
        score -= 7.0 * (1.0 - progress * 0.5);
    }

    if next > 0.0 && post_residual > 0 && post_residual < next_item_size && fitting_bins_count <= 2 {
        score += 18.0 * (1.0 - progress * 0.5);
    }

    if next > 0.0 && pr >= next && fitting_bins_count > 1 {
        let chain = pr - next;
        let chain_ref = mean_residual.max(1.0) * 0.35;
        if chain < chain_ref {
            score -= 5.0 * (1.0 - chain / chain_ref) * (0.5 + progress * 0.5);
        }
    }

    if post_norm > 0.03 && post_norm < 0.10 {
        if next > 0.0 && pr >= next {
            score -= 4.0 * (1.0 - progress * 0.5);
        } else {
            score += 6.0 * (0.5 + progress * 0.5);
        }
    }

    // COMBINED: fine-grained residual fitting with lookahead — deep fills whose
    // post-residual still hosts the next item with near-zero slack.
    if next > 0.0 && pr > 0.0 && pr >= next && fill_r > 0.82 {
        let reuse = (pr - next) / cap;
        if reuse < 0.06 {
            score -= (0.06 - reuse) * 34.0 * (0.5 + progress * 0.5);
        }
    }

    if post_norm >= 0.10 && post_norm < 0.18 && next > 0.0 && pr < next {
        score += (0.18 - post_norm) * 14.0 * (0.4 + progress * 0.6);
    }

    // COMBINED: residual-consolidation tuned to avoid penalizing exact fits.
    if next > 0.0 && pr >= next {
        let fits_ahead = (pr / next).floor();
        if fits_ahead >= 2.0 {
            let remainder = pr - fits_ahead * next;
            let rem_norm = remainder / cap;
            if rem_norm > 0.005 {
                score += rem_norm * 55.0 * (0.5 + progress * 0.5);
            } else {
                score -= 4.0 * (1.0 - progress * 0.4);
            }
        }
    }

    // Late-stream residual sweep.
    let remaining = if total_items > step_index { total_items - step_index } else { 1 };
    if remaining < 12 && post_residual > 0 {
        score += post_norm * 40.0;
    }

    // NEW: mid-stream dead-space vacuum — penalize placements that strand a
    // residual which neither the next item nor any small multiple can consume,
    // but only while plenty of stream remains to matter.
    if remaining > 40 && next > 0.0 && pr > 0.0 && pr < next * 0.9 {
        score += (next - pr) / cap * 34.0 * (0.6 + progress * 0.4);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: prefer residuals that are multiples
    // of common item-size classes (e.g. 20, 25, 50) since future items are more
    // likely to fit exactly into them.
    let cap = bin_capacity as f64;
    let pr = post_residual;
    let mut bonus = 0.0;

    if pr == 0 {
        // Perfect fit: strongly reward closing the bin exactly.
        bonus -= 60.0;
    } else {
        // Modulo arithmetic on residual: residuals divisible by 5/10/20/25 are
        // more "usable" by future items drawn from coarse-grained distributions.
        if pr % 5 == 0 { bonus -= 4.0; }
        if pr % 10 == 0 { bonus -= 5.0; }
        if pr % 20 == 0 { bonus -= 6.0; }
        if pr % 25 == 0 { bonus -= 6.0; }
        if pr % 50 == 0 { bonus -= 8.0; }

        // Integer-division dead-space threshold: residuals below 10 are nearly
        // unusable dead space (min item is small but typical items are larger).
        if pr < 10 { bonus += 25.0; }
        else if pr < 20 { bonus += 12.0; }

        // Fractional capacity classes: residual in [0.25C, 0.5C) vs [0.5C, 0.75C)
        // behave differently. Mid-range residuals are flexible; tiny ones are not.
        let frac = pr as f64 / cap;
        if frac >= 0.5 { bonus -= 8.0; }
        else if frac >= 0.25 { bonus -= 3.0; }
        else { bonus += 5.0; }
    }
    score += bonus;

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // this placement chains perfectly — reward heavily.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 40.0;
        } else if pr >= next_item_size {
            // Next item fits: leftover after that hypothetical placement.
            let chain_left = pr - next_item_size;
            if chain_left % 10 == 0 { score -= 6.0; }
            if chain_left < 10 { score += 8.0; }
        } else {
            // Next item cannot fit here: penalize slightly, more if residual
            // is small and stranded.
            score += (next_item_size as f64 - pr as f64).min(30.0) * 0.3;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when open bins are crowded or the
    // item fits nowhere well. Penalize opening a new bin mildly by default.
    if bin_residual == bin_capacity {
        score += 15.0;
        if open_bins_count == 0 { score -= 15.0; }
        if fitting_bins_count == 0 { score -= 40.0; }
        if mean_residual < 10.0 && open_bins_count > 0 { score -= 25.0; }
    }

    // Stream progression: late in the stream, prefer packing tight into
    // existing bins rather than opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;
    score += open_bins_count as f64 * 0.5;

    // Prefer bins whose residual deviates from the mean in the "tight" direction
    // (use the fullest bin first, classic best-fit-like behavior).
    score += (bin_residual as f64 - mean_residual) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let post_norm = post_residual as f64 / cap;
    let mut score = post_norm * post_norm * 50.0 + post_norm * 20.0;

    // Perfect fit: strong reward (subtract).
    if post_residual == 0 {
        score -= 140.0;
    } else if post_residual <= 5 {
        score -= 42.0 * (1.0 - progress * 0.3);
    } else if post_residual <= 9 {
        score -= 18.0 * (1.0 - progress * 0.4);
    }

    // Dead-space class: residuals in (0, 12] are almost unusable.
    let dead_floor = if next_item_size > 0 { (next_item_size.min(12) as f64).max(6.0) } else { 12.0 };
    if post_residual > 0 && (post_residual as f64) < dead_floor {
        score += 62.0 * (1.0 - progress * 0.3);
    } else if post_residual > 0 && post_residual <= 20 {
        score += 25.0;
    }

    // Harmonic divisibility rewards.
    if post_residual > 0 {
        let pr = post_residual;
        if pr % 50 == 0 { score -= 18.0; }
        else if pr % 25 == 0 { score -= 12.0; }
        else if pr % 20 == 0 { score -= 10.0; }
        else if pr % 10 == 0 { score -= 8.0; }
        else {
            score += (pr % 5) as f64 * 1.5;
        }
    }

    // Lookahead: next item fit quality in post_residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        if next_item_size == post_residual {
            score -= 60.0;
        } else {
            let nxt_left = post_residual - next_item_size;
            if nxt_left % 10 == 0 {
                score -= 10.0;
            } else if nxt_left > 12 {
                score -= 4.0;
            } else {
                score += 6.0;
            }
            let slack = nxt_left as f64 / cap;
            score -= (-slack * slack * 450.0).exp() * 24.0 * (1.0 - progress * 0.5);
            // Fractional divisibility of remaining slack by next item.
            let frac = (nxt_left % next_item_size.max(1)) as f64 / next_item_size as f64;
            if frac < 0.08 {
                score -= 10.0 * (1.0 - progress * 0.5);
            }
        }
        // Two-of-next-item pairing.
        if (post_residual as f64) >= (next_item_size as f64) * 2.0
            && (post_residual as f64) < (next_item_size as f64) * 2.0 + 8.0 {
            score -= 8.0 * (1.0 - progress * 0.4);
        }
    } else if next_item_size > 0 {
        // next item cannot use this leftover: wasted space penalty
        let dead_ratio = (next_item_size as f64 - post_residual as f64) / cap;
        score += 8.0 + dead_ratio * 90.0 * (0.6 + progress * 0.6);
        if fitting_bins_count <= 2 {
            score += 18.0 * (1.0 - progress * 0.5);
        }
    }

    // Tight-gap bonus: prefer bins where item nearly fills residual.
    let gap = (bin_residual - item_size) as f64 / cap;
    if gap > 0.0 && gap < 0.12 {
        score -= (0.12 - gap) * 48.0;
        if fitting_bins_count == 1 && gap < 0.06 {
            score -= 7.0 * (1.0 - progress * 0.5);
        }
    } else if gap >= 0.12 && gap < 0.22 {
        if fitting_bins_count <= 3 {
            score += (gap - 0.12) * 18.0 * (0.5 + progress * 0.5);
        }
    } else if gap >= 0.22 && gap < 0.30 && fitting_bins_count <= 2 {
        score += (gap - 0.22) * 22.0 * (0.6 + progress * 0.4);
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let size_pull = (item_size as f64 / cap) * 14.0;
        if fitting_bins_count <= 2 {
            score -= (18.0 + size_pull) * (1.0 - progress * 0.6);
        } else {
            score += 20.0 + open_bins_count as f64 * (0.5 + 0.5 * progress);
        }
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a bin
        }
        // Next item close to current: fresh bin keeps pairing room.
        if next_item_size > 0 && fitting_bins_count <= 3 && (item_size as f64) >= next_item_size as f64 * 0.95 {
            score -= 5.5 * (1.0 - progress * 0.5);
        }
        // Next item won't fit with current in a fresh bin: discourage.
        if next_item_size > 0 && fitting_bins_count >= 1 && (item_size as f64) + (next_item_size as f64) > cap {
            score += 8.0 * (1.0 - progress * 0.4);
        }
        // Large item early: worth a fresh bin to keep it isolated.
        if (item_size as f64) > cap * 0.5 && progress < 0.5 {
            score -= 6.0 * (1.0 - progress);
        }
        if progress > 0.85 && (item_size as f64) / cap > 0.6 {
            score -= 4.0 * (progress - 0.85) * 20.0;
        }
        if next_item_size > 0 && (item_size as f64) + (next_item_size as f64) <= cap && (item_size as f64) / cap > 0.35 {
            score -= 3.0 * (1.0 - progress);
        }
    }

    // Global pressure: high mean residual -> pack tight bins.
    score -= (mean_residual / cap) * 5.0;

    // Waste-relative pressure: penalize bins whose post-residual exceeds mean.
    if post_residual > 0 && mean_residual > 0.0 {
        let waste = post_norm - (mean_residual / cap);
        if waste > 0.0 {
            score += waste * 30.0 * (0.4 + progress * 0.6);
        } else {
            score -= (-waste) * 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 1.15;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Dead-space penalty: residuals that are too small to hold even the
    // smallest plausible future item (<= 10) are pure waste.
    if post_residual < 10 && post_residual > 0 {
        score += 25.0;
    }
    // Residuals in the awkward band (10..=20) are hard to fill; penalize
    // proportionally with a nonlinear bump.
    if post_residual >= 10 && post_residual <= 20 {
        score += 12.0 * (1.0 - post / 20.0);
    }

    // Reward tight fits (small post_residual) super-linearly.
    score -= 30.0 * ((cap - post) / cap).powi(6);

    // Pressure from number of open bins: discourage spreading when many bins
    // are open, encourage consolidation.
    score += (open_bins_count as f64) * 1.5;

    // Prefer bins whose residual deviates from the mean in a fillable way.
    score += 0.3 * (mean_residual - post);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Lookahead: if the next item fits into the post residual, reward it.
    if next_item_size > 0 && (next_item_size as f64) <= post {
        score -= 10.0;
    } else if next_item_size > 0 && post > 0 {
        score += 5.0;
    }

    // New-bin candidate: make it moderately attractive only when the item
    // fits poorly in every open bin; otherwise keep it slightly worse.
    if bin_residual == bin_capacity {
        score += 8.0 - (fitting_bins_count as f64).min(5.0);
    }

    // Mild stream-progression term: later in the stream, favor closing gaps.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress * (post / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
