pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "small residue"
    // classes (0..=10) are near-perfect; bins leaving large awkward gaps are penalized.
    let pr = post_residual;
    let residue_class = pr % 20; // harmonic class width 20
    let class_penalty = match residue_class {
        0 => -8.0,               // perfect fill
        1..=5 => -3.0,           // near-perfect
        6..=10 => -1.0,          // acceptable
        11..=15 => 2.0,          // awkward gap
        _ => 4.0,                // worst dead-space class
    };
    score += class_penalty;

    // Integer-division thresholds: residual divisible by common small item sizes
    // (10, 20, 25, 50) makes leftover reusable by typical items.
    if pr > 0 {
        if pr % 10 == 0 { score -= 2.0; }
        if pr % 25 == 0 { score -= 1.5; }
        if pr % 50 == 0 { score -= 1.0; }
    }

    // Lookahead coupling: reward if next item fits exactly or near-exactly in post_residual.
    if next_item_size > 0 && next_item_size <= pr {
        let gap = pr - next_item_size;
        if gap == 0 {
            score -= 10.0;
        } else if gap <= 10 {
            score -= 4.0;
        } else if gap <= 20 {
            score -= 1.5;
        }
    } else if next_item_size > pr && next_item_size > 0 {
        // Next item won't fit here; leftover likely wasted unless tiny.
        if pr > 30 { score += 3.0; }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 6.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is terrible.
    if bin_residual == bin_capacity {
        let base = 12.0 + (mean_residual - pr as f64).abs();
        // Cheaper to open new bins early in stream or when few bins are open.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = base - 4.0 * (1.0 - progress) - 0.5 * open_bins_count as f64;
        // If item is large relative to capacity, new bin is natural.
        if item_size > bin_capacity / 2 { score -= 3.0; }
    }

    // Tight-fit reward: filling most of the bin now is excellent.
    let fill_frac = item_size as f64 / bin_capacity as f64;
    if fill_frac > 0.8 { score -= 3.0; }

    // Mild normalization against mean residual drift.
    score += 0.05 * (mean_residual - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
