pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold
    // typical future items are wasted. Penalize gaps in the "dead zone".
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // tiny unusable sliver
    } else if post_residual >= 10 && post_residual < 30 {
        score += 18.0; // marginal gap, often wasted
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 120.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    }

    // Reward bins whose residual tightly matches the item (post_residual small
    // relative to bin_residual) — good density.
    if bin_residual > 0 {
        let tightness = item_size as f64 / bin_residual as f64;
        score -= 25.0 * tightness;
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Lookahead: if the next item fits the post-residual, this placement is
    // doubly valuable; if not, the leftover is likely dead space.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 20.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            score += 12.0;
        }
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // (penalize the new-bin candidate and discourage spreading out).
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = 0.5 + 0.5 * progress;
    score += pressure * (open_bins_count as f64) * 2.0;

    // New-bin candidate: should only win when open bins are mostly full
    // (high mean residual) or when this placement would create dead space.
    if bin_residual == bin_capacity {
        let base = 55.0 + mean_residual * 0.9;
        score = if score < base { score } else { base };
        // Slight preference for new bins early when open bins are nearly full.
        score -= mean_residual * 0.15;
    }

    // Prefer bins below the mean residual (denser bins first).
    score += (bin_residual as f64 - mean_residual) * 0.25;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
