pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-exact fit (low post residual).
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 120.0;
    } else if post_residual <= 20 {
        score -= 60.0;
    }

    // Dead space: residual too small to ever fit another item (min size 1, but
    // typical small items ~10): penalize residuals in the awkward 1..10 band
    // relative to how much of the bin was consumed.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Aggressive 2-step lookahead: if the next item exactly fills the post
    // residual, this is a perfect chain — reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 180.0;
        } else if next_item_size <= post_residual {
            // Next item fits: reward proportional to how well it fills the remainder.
            let fill_ratio = next_item_size as f64 / post_residual as f64;
            score -= 60.0 * fill_ratio;
            if post_residual - next_item_size <= 5 {
                score -= 40.0; // leaves near-zero dead space after next item
            }
        } else {
            // Next item will NOT fit here: penalize if we still leave a big gap.
            if post_residual >= 10 {
                score += 15.0;
            }
            // If this bin is the only option and next item won't fit anyway,
            // slight bonus to use it now rather than open a new bin.
            if fitting_bins_count == 1 && bin_residual != bin_capacity {
                score -= 25.0;
            }
        }
    }

    // Prefer fuller bins relative to the mean residual across open bins.
    if (post_residual as f64) < mean_residual {
        score -= 10.0;
    } else {
        score += 5.0;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: an empty bin has huge residual; make it
    // attractive only when the current item is large (good initial fill) and
    // no good fit exists. Scale its base score so a fresh bin is competitive
    // for large items but loses for small ones.
    if bin_residual == bin_capacity {
        // Base for new bin ~ post_residual(=capacity) minus item-size incentive.
        score += 70.0 - item_size as f64;
        if item_size >= 70 {
            score -= 50.0; // large items start fresh bins happily
        }
    }

    // Late in the stream, consolidation matters more: prefer existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= 10.0 * progress;
    }

    // Mild preference to spread load when many bins are open (keeps residuals
    // flexible for future items).
    if open_bins_count > 8 && next_item_size > 0 && next_item_size > post_residual {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let post_norm = pr / cap;
    let mut score = post_norm * post_norm * 50.0 + post_norm * 20.0;

    // Dead-space avoidance (mutated thresholds from parent)
    let dead_floor = if next_item_size > 0 { (next_item_size.min(12) as f64).max(6.0) } else { 10.0 };
    if post_residual > 0 && (post_residual as f64) < dead_floor {
        score += 62.0 * (1.0 - progress * 0.3);
    } else if post_residual < 20 {
        score += 25.0;
    }

    // Tight-fit rewards
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 42.0;
    } else if post_residual <= 9 {
        score -= 18.0 * (1.0 - progress * 0.4);
    }

    // Lookahead: next item fits post_residual -> strong reward (Gaussian on slack)
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64 / cap;
        score -= (-slack * slack * 450.0).exp() * 24.0 * (1.0 - progress * 0.5);
    }

    // Gap-based awkwardness (borrowed from best)
    let gap = (bin_residual - item_size) as f64 / cap;
    if gap > 0.0 && gap < 0.12 {
        score -= (0.12 - gap) * 48.0;
    } else if gap >= 0.12 && gap < 0.22 {
        if fitting_bins_count <= 3 {
            score += (gap - 0.12) * 18.0 * (0.5 + progress * 0.5);
        }
    }
    if gap >= 0.22 && gap < 0.30 && fitting_bins_count <= 2 {
        score += (gap - 0.22) * 22.0 * (0.6 + progress * 0.4);
    }

    // Dead-space vs next item
    if next_item_size > 0 && pr > 0.0 && (pr as u32) < next_item_size && post_norm > 0.03 {
        let dead_ratio = (next_item_size as f64 - pr) / cap;
        score += dead_ratio * 90.0 * (0.6 + progress * 0.6);
    }

    // Mean-residual coupling (kept from parent, normalized)
    if post_residual > 0 && mean_residual > 0.0 {
        let waste = (post_residual as f64 / cap) - (mean_residual / cap);
        if waste > 0.0 {
            score += waste * 30.0 * (0.4 + progress * 0.6);
        } else {
            score -= (-waste) * 10.0;
        }
    }

    if next_item_size > 0 && post_residual > 0 && (post_residual as u32) < next_item_size && fitting_bins_count <= 2 {
        score += 18.0 * (1.0 - progress * 0.5);
    }

    // New-bin candidate handling (mutated from parent + best ideas)
    if bin_residual == bin_capacity {
        let size_pull = (item_size as f64 / cap) * 14.0;
        if fitting_bins_count <= 2 {
            score -= (18.0 + size_pull) * (1.0 - progress * 0.6);
        } else {
            score += 20.0 + open_bins_count as f64 * (0.5 + 0.5 * progress);
        }
        if next_item_size > 0 && fitting_bins_count <= 3 && (item_size as f64) >= next_item_size as f64 * 0.95 {
            score -= 5.5 * (1.0 - progress * 0.5);
        }
        if next_item_size > 0 && fitting_bins_count >= 1 {
            let nxt = next_item_size as f64;
            if (item_size as f64) + nxt > cap {
                score += 8.0 * (1.0 - progress * 0.4);
            }
        }
        if (item_size as f64) > cap * 0.5 && progress < 0.5 {
            score -= 6.0 * (1.0 - progress);
        }
        if progress > 0.85 && (item_size as f64) / cap > 0.6 {
            score -= 4.0 * (progress - 0.85) * 20.0;
        }
        if next_item_size > 0 && (item_size as f64) + (next_item_size as f64) <= cap && (item_size as f64) / cap > 0.35 {
            score -= 3.0 * (1.0 - progress);
        }
        if next_item_size > 0 && post_residual > 0 {
            let nxt = next_item_size as f64;
            let second_slack = (pr - nxt) / cap;
            if second_slack >= 0.0 && second_slack < 0.05 {
                score -= (0.05 - second_slack) * 40.0 * (0.5 + progress * 0.5);
            }
        }
        if post_residual > 0 && post_norm < 0.02 && fitting_bins_count >= 4 {
            score -= 6.0 * (1.0 - progress);
        }
        if next_item_size > 0 && post_residual > 0 {
            let nxt = next_item_size as f64;
            if (pr as u32) >= next_item_size {
                let frac = ((pr - nxt) % nxt.max(1.0)) / nxt.max(1.0);
                if frac < 0.08 {
                    score -= 10.0 * (1.0 - progress * 0.5);
                }
            }
        }
        if post_residual > 0 && next_item_size > 0 && (post_residual as f64) >= (next_item_size as f64) * 2.0 && (post_residual as f64) < (next_item_size as f64) * 2.0 + 8.0 {
            score -= 8.0 * (1.0 - progress * 0.4);
        }
    }

    // Last-chance bin (kept from parent)
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 - progress * 0.5);
        if gap > 0.0 && gap < 0.06 {
            score -= 7.0 * (1.0 - progress * 0.5);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize leaving awkward dead space (small but unusable-looking leftovers).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item exactly-ish.
    if next_item_size > 0 && post_residual >= next_item_size {
        let next_tight = next_item_size as f64 / post_residual as f64;
        score -= 8.0 * next_tight;
    } else if next_item_size > 0 && post_residual > 0 {
        // Dead space relative to the next item: penalize proportionally to progress.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 6.0 * (1.0 - progress) * (next_item_size as f64 - post_residual as f64).min(50.0) / 50.0;
    }

    // Last chance: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: only attractive when open bins are quite full
    // or the item fits poorly everywhere.
    if bin_residual == bin_capacity {
        let avg_fill = 1.0 - mean_residual / bin_capacity as f64;
        let penalty = 25.0 + 40.0 * avg_fill;
        score += penalty;
        // Early in the stream, opening bins is cheaper; later, prefer consolidation.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 * (1.0 - progress);
        // If next item is large, an empty bin gives flexibility.
        if next_item_size >= 60 {
            score -= 10.0;
        }
    }

    // Mild penalty when many bins are open: encourage closing bins out.
    score += 0.15 * open_bins_count as f64;

    // Deviation from mean residual: prefer bins that are fuller than average.
    score += 0.05 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
