pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residues divisible into common
    // item-size classes (10/20/25/50) are reusable "harmonic" dead space.
    let cap = bin_capacity as f64;
    let pr = post_residual;

    // Reward residuals that lie in reusable harmonic classes.
    let harmonic_bonus = if pr == 0 {
        -30.0 // perfect fit
    } else if pr % 10 == 0 && pr >= 10 {
        -12.0
    } else if pr % 25 == 0 {
        -8.0
    } else if pr % 5 == 0 {
        -4.0
    } else {
        6.0 // awkward residue class
    };
    score += harmonic_bonus;

    // Penalize residuals too small for the smallest plausible item (1..100 stream).
    if pr > 0 && pr < 10 {
        score += 15.0; // near-dead space
    }

    // Lookahead coupling: if next item fits exactly in post_residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 25.0;
        } else if next_item_size < pr {
            score -= (pr - next_item_size) as f64 * 0.3;
        } else {
            score += (next_item_size - pr) as f64 * 0.1;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when open bins are badly fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = mean_residual / cap;
        score += 10.0 - fragmentation * 25.0;
        if post_residual == bin_capacity {
            // fresh bin residual = capacity; mild penalty so it loses to good fits
            score += 5.0;
        }
    }

    // Late-stream consolidation: prefer tighter fills as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (pr as f64) * 0.15;

    // Prefer bins whose residual is far below the mean (tight bins).
    score += (mean_residual - bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
