pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where the item nearly fills the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    if fit_ratio > 0.85 {
        score -= 40.0 * (fit_ratio - 0.85) / 0.15;
    } else if fit_ratio > 0.6 {
        score -= 15.0 * (fit_ratio - 0.6) / 0.25;
    }

    // Penalize small unusable dead space: gaps that likely cannot host future items.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // tiny gap = wasted capacity
    } else if post_residual < 20 {
        score += 25.0;
    } else if post_residual < 35 {
        score += 8.0;
    }

    // Perfect fill is ideal.
    if post_residual == 0 {
        score -= 100.0;
    }

    // New-bin candidate: penalize opening a new bin, but less when the fit in
    // existing bins would be terrible (large post_residual) or this is the
    // last fitting bin and the gap created is small.
    if bin_residual == bin_capacity {
        score += 45.0 + 0.5 * open_bins_count as f64;
        if post_residual as f64 > mean_residual + 30.0 {
            score -= 30.0; // existing bins would be packed too tightly anyway
        }
        if fitting_bins_count == 1 && post_residual <= 10 {
            score -= 50.0; // last-chance bin with unusable gap: prefer new bin
        }
    }

    // Open-bin pressure: mild penalty scaling with number of open bins,
    // encouraging consolidation when many bins are active.
    score += 0.15 * open_bins_count as f64;

    // Lookahead: if the next item fits exactly in the post_residual, reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        let next_fit = (post_residual - next_item_size) as f64;
        if next_fit < 10.0 {
            score -= 20.0;
        }
    }

    // Late in the stream, prefer closing bins tightly (consolidation).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), scaled mildly.
    score = post_residual as f64 * 1.0;

    // Strongly reward exact/near-exact fits.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 100.0;
    }

    // Aggressive 2-step lookahead: reward when next item fits the post-residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0; // perfect chain
        } else if next_item_size <= post_residual {
            // chainable: reward proportional to how well next item fills remainder
            let fill = next_item_size as f64 / post_residual as f64;
            score -= 200.0 * fill;
        } else {
            // next item cannot chain: penalize large dead space
            let waste = (next_item_size - post_residual) as f64;
            score += 0.05 * waste;
        }
    }

    // Compare post_residual relative to mean residual across open bins.
    if post_residual as f64 > mean_residual {
        // creating above-average dead space is bad unless it enables chaining
        score += 0.3 * (post_residual as f64 - mean_residual);
    } else {
        score -= 0.3 * (mean_residual - post_residual as f64);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate: make it moderately attractive only when it enables
    // a clean fit for the next item too (lookahead-driven opening).
    if bin_residual == bin_capacity {
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // opening a new bin costs ~1 bin; only worth it if current best
            // placements would waste a lot (post_residual large relative to item)
            score = 100.0 + item_size as f64;
            if next_item_size as f64 >= 0.8 * bin_capacity as f64 {
                score -= 50.0; // next big item pairs well with fresh bin
            }
        } else {
            score = 150.0; // last item: prefer existing bins
        }
    }

    // Mild stream-progress pressure: late in the stream, consolidate.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 10.0 * progress * (open_bins_count as f64).sqrt();

    score
}

