pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (low post-residual relative to capacity).
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += fit_ratio * fit_ratio * 30.0;

    // Penalize bins whose residual is small but not zero (dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Perfect closure bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Last-chance bin: if this is the only fitting bin, prefer it to avoid a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if post_residual > 0 {
            score += 8.0; // stranded space for the next item
        }
        // Extra coupling: post-residual exactly matching next item size is ideal.
        if post_residual == next_item_size {
            score -= 20.0;
        }
    }

    // Global state coupling: many open bins with high mean residual -> discourage
    // spreading; prefer filling existing bins harder.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let openness = open_bins_count as f64;
    score += (openness / (openness + 5.0)) * 10.0 * (mean_residual / bin_capacity as f64);

    // Late in the stream, tighten packing (avoid opening new bins).
    score -= progress * 8.0;

    // Prefer bins with residual close to item_size (minimal waste placement).
    let gap = (bin_residual as i64 - item_size as i64).abs() as f64;
    score += gap * 0.3;

    // New-bin candidate handling: only attractive when no decent fit exists.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin.
        score += 35.0;
        // But if mean residual across open bins is too small for the item,
        // opening a new bin is reasonable.
        if mean_residual < item_size as f64 * 1.05 {
            score -= 30.0;
        }
        // If this is the last chance bin anyway, opening new is fine.
        if fitting_bins_count == 1 {
            score -= 15.0;
        }
        // Late stream: discourage new bins.
        score += progress * 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let next = next_item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items.max(1) as f64 } else { 0.0 };
    let post_norm = pr / cap;
    let fit_ratio = item_size as f64 / cap;
    let gap = (bin_residual - item_size) as f64 / cap;
    let mut score = post_norm * post_norm * 56.5 + post_norm * 21.8;

    // ---- Aggressive 2-step lookahead: shape score around the NEXT item ----
    if next > 0.0 {
        if pr == next {
            score -= 45.0;
        } else if pr > next {
            let slack = pr - next;
            let diff = slack / cap;
            score -= 20.0 * (1.0 - diff).max(0.0);
            score -= (-diff * diff * 458.0).exp() * 20.2 * (1.0 - progress * 0.5);
            if diff < 0.04 {
                score -= (0.04 - diff) * 26.0 * (0.6 + progress * 0.6);
            } else if diff > 0.16 {
                score += (diff - 0.16) * 8.0 * (0.5 + progress);
            }
        } else if pr > 0.0 {
            score += (next - pr) / cap * 30.5 * (1.0 - progress);
        }
    }

    // Penalize tiny unusable slivers unless they exactly match the next item.
    let dead_floor = if next_item_size > 0 { (next_item_size.min(12) as f64).max(6.0) } else { 10.0 };
    if pr > 0.0 && pr < dead_floor && pr != next {
        score += 62.0 * (1.0 - progress * 0.3);
    } else if pr > 0.0 && post_residual < 20 && pr != next {
        score += 25.0;
    }

    // Exact / near-exact fit bonuses (strong, borrowed from best).
    if pr == 0.0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 42.0;
    } else if post_norm < 0.05 {
        score -= 10.2 * (1.0 - post_norm / 0.05);
    }

    // ---- Relative-to-mean coupling: favor tighter-than-average bins ----
    if pr > 0.0 {
        let waste = (pr / cap) - (mean_residual / cap);
        if waste > 0.0 {
            score += waste * 30.0 * (0.4 + progress * 0.6);
        } else {
            score -= (-waste) * 10.0;
        }
    }

    // ---- New-bin candidate decision ----
    if bin_residual == bin_capacity {
        let others = if fitting_bins_count > 0 { fitting_bins_count - 1 } else { 0 };
        let size_pull = fit_ratio * 14.0;
        if fitting_bins_count <= 2 && gap > 0.0 {
            score -= (18.0 + size_pull) * (1.0 - progress * 0.6);
        } else if others == 0 {
            score -= 5.0;
        } else {
            score += 8.0 + 6.0 * (1.0 - progress) + open_bins_count as f64 * 0.4 * (0.5 + 0.5 * progress);
        }
        if next > 0.0 && fitting_bins_count <= 3 && item_size as f64 >= next * 0.95 {
            score -= 5.5 * (1.0 - progress * 0.5);
        }
        if next > 0.0 && item_size as f64 + next > cap {
            score += 8.0 * (1.0 - progress * 0.4);
        }
        if fit_ratio > 0.5 && progress < 0.5 {
            score -= 6.0 * (1.0 - progress);
        }
    }

    // Sharp bonus for leaving a tiny gap (<12% of capacity).
    if gap > 0.0 && gap < 0.12 {
        score -= (0.12 - gap) * 48.0;
    } else if gap >= 0.12 && gap < 0.22 {
        if fitting_bins_count <= 3 {
            score += (gap - 0.12) * 18.0 * (0.5 + progress * 0.5);
        }
        if next > 0.0 && pr > 0.0 && next > pr {
            score += (next - pr) / cap * 60.0 * (0.6 + progress * 0.6);
        }
    }
    if gap >= 0.22 && gap < 0.35 && fitting_bins_count <= 2 {
        score += (gap - 0.22) * 22.0 * (0.6 + progress * 0.4);
    }
    // Next-item chain: leftover after next item nearly closes bin.
    if next > 0.0 && gap > 0.12 {
        let nxt_gap = ((gap * cap - next).max(0.0)) / cap;
        if nxt_gap < 0.06 {
            score -= 9.0 * (1.0 - nxt_gap / 0.06) * (0.5 + progress);
        }
        let second_slack = (pr - next) / cap;
        if second_slack >= 0.0 && second_slack < 0.05 {
            score -= (0.05 - second_slack) * 40.0 * (0.5 + progress * 0.5);
        }
        if pr >= next {
            let frac = ((pr - next) % next.max(1.0)) / next.max(1.0);
            if frac < 0.08 {
                score -= 10.0 * (1.0 - progress * 0.5);
            }
        }
        if pr >= next * 2.0 && pr < next * 2.0 + 8.0 {
            score -= 8.0 * (1.0 - progress * 0.4);
        }
    }

    // Reward large items filling bins deeply.
    score -= fit_ratio * fit_ratio * 6.0;

    // Congestion: when many bins compete for this item, penalize sloppy fits.
    if fitting_bins_count > 2 {
        score += gap * 6.5 * ((fitting_bins_count.min(12) as f64 - 2.0) / 10.0);
    }
    if open_bins_count > 8 {
        score += post_norm * 5.0 * ((open_bins_count.min(20) as f64 - 8.0) / 12.0);
    }

    // Late-stream consolidation.
    if progress > 0.7 && post_norm > 0.25 {
        score += (post_norm - 0.25) * 6.0 * (progress - 0.7) / 0.3;
    }

    // Last-chance bonus: prefer a bin that would otherwise be wasted.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 - fit_ratio);
        if gap > 0.0 && gap < 0.06 {
            score -= 7.0 * (1.0 - progress * 0.5);
        }
    }

    // Deep fill bonus relative to actual residual.
    let fill_r = item_size as f64 / bin_residual.max(1) as f64;
    if fill_r > 0.90 && bin_residual != bin_capacity {
        score -= (fill_r - 0.90) * 18.0 * (0.6 + progress * 0.5);
    }

    // Dead-space guard: stranded small gap after next item.
    if next > 0.0 && pr > 0.0 && (post_residual as u32) < next_item_size && post_norm > 0.03 {
        let dead_ratio = (next - pr) / cap;
        score += dead_ratio * 90.0 * (0.6 + progress * 0.6);
        if fitting_bins_count <= 2 {
            score += 18.0 * (1.0 - progress * 0.5);
        }
    }

    // Mid-residual band penalty.
    if pr > 0.0 && post_norm >= 0.10 && post_norm < 0.20 && next > 0.0 && next > pr {
        score += (next - pr) / cap * 26.0 * (0.4 + progress * 0.8);
    }

    // Half-consumed bins late in the stream.
    if pr > 0.0 && pr < item_size as f64 * 0.5 && progress > 0.3 {
        score += 4.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_ratio = item_size as f64 / cap;
    let post_norm = post / cap;

    // Base: penalize wasted residual, non-linearly (dead space hurts quadratically).
    let mut score = post_norm * post_norm * cap;

    // Smooth coupling: value of residual depends on stream progress.
    // Early on, tight packing is cheap; late, preserve flexibility.
    let flexibility = post_norm * (1.0 - progress);
    score -= 12.0 * flexibility * flexibility * cap;

    // Reward near-perfect fits with smooth bell-shaped term around post_residual ~ 0.
    let tightness = (-post_norm * post_norm * 20.0).exp();
    score -= 18.0 * tightness * (1.0 + fit_ratio);

    // Last-chance bonus: strongly favor the only bin that fits.
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - post_norm);
    }

    // Lookahead: penalize if post-residual can't fit next item but another placement could.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if post as u32 >= next_item_size {
            score -= 6.0 * (nx / cap);
        } else {
            score += 8.0 * (nx / cap) * (1.0 - post_norm);
        }
    }

    // Mild pressure to consolidate when many bins are open.
    score += 2.0 * (open_bins_count as f64).ln().max(0.0) * (1.0 - fit_ratio);

    // Mean-residual coupling: prefer bins near (or below) mean to balance residuals.
    let dev = (post - mean_residual) / cap;
    score += 5.0 * dev * dev;

    // New-bin candidate: make empty bins attractive only when post-fit would be poor.
    if bin_residual == bin_capacity {
        score += 10.0 + 20.0 * fit_ratio * (1.0 - progress);
    }

    score
}

