pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: post_residual mod 10 buckets.
    // Residuals that are "harmonic" (multiples of 10, small classes) are reusable.
    let harmonic = (post_residual % 10) as f64;
    score += harmonic * 1.5;                    // penalize off-class leftovers
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 6.0;                           // reward class-aligned residual
    }

    // Integer-division threshold: does the leftover admit the next item?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // next item fits here: strong reward, scaled by how snugly it packs
            let snug = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= 12.0 + 10.0 * snug;
        } else {
            // leftover too small for lookahead: dead-space penalty grows
            let waste = (post_residual as f64) / bin_capacity as f64;
            score += 8.0 * waste;
        }
    }

    // Perfect-fit bonus: filling the bin exactly (or near-exactly) is ideal.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    } else if post_residual <= 15 {
        score -= 5.0;
    }

    // Last-chance bin: if this is the only fitting bin, prefer using it
    // over opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 10.0;
        if post_residual > 40 {
            score += 6.0;  // poor fit into sole bin; new bin may be better
        }
    }

    // New-bin candidate (empty bin): open a fresh bin only when the item is
    // large or existing residuals are badly fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = if open_bins_count > 0 { mean_residual / bin_capacity as f64 } else { 0.0 };
        // Favor new bin when item is big (little fits elsewhere) or residuals are high
        let big_item = item_size as f64 / bin_capacity as f64;
        score += 30.0;                       // base cost of opening a bin
        score -= 40.0 * big_item;            // big items justify fresh bins
        score -= 25.0 * fragmentation;       // fragmented open bins -> new bin attractive
        score -= 5.0 * progress;             // late in stream, consolidation matters less
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 8.0;                    // fresh bin can also host the lookahead item
        }
    }

    // Prefer tighter existing bins: residual closeness to item size is good.
    let tightness = (bin_residual - item_size) as f64 / bin_capacity as f64;
    score += 10.0 * tightness;

    // Mild penalty for spreading across many open bins.
    score += 0.4 * open_bins_count as f64;

    score
