        } else if post_residual >= next_item_size {
            score -= 5.0;
        } else {
            // Next item cannot use this bin's remainder: mild penalty for wasted capacity.
            score += (post_residual as f64) * 0.15;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: discourage spreading across many open bins.
    score += open_bins_count as f64 * 0.5;

    // Prefer bins with below-average residual (tighter bins) when they fit well.
    score -= (mean_residual - post_residual as f64) * 0.2;

    // New-bin candidate: make opening a fresh bin moderately attractive only when
    // the item is large relative to remaining open capacity; otherwise penalize it.
    if bin_residual == bin_capacity {
