        if gap == 0.0 {
            score -= 60.0;
        } else {
            score -= 40.0 * (-gap / 12.0).exp();
        }
    } else if next_item_size > 0 {
        // Next item cannot follow into this bin: penalize wasted pairing potential.
        score += 8.0;
    }

    // Penalize small dead space (unusable slivers) relative to capacity.
    let dead = post_residual as f64;
    if dead < 10.0 && dead > 0.0 {
        score += 25.0 * (1.0 - dead / 10.0);
    }

    // Compare residual against mean residual across open bins: prefer bins
    // that are tighter than average (consumes fuller bins first).
    score -= 0.5 * (mean_residual - dead);

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive
    // when existing fits are poor (large post_residual would be created anyway).
