        score += 15.0;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // A fresh bin can host both current and next item comfortably.
            if item_size + next_item_size <= bin_capacity {
                score -= 20.0;
            }
        }
        // Later in the stream, be more conservative about opening bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
