    let mut score = post_residual as f64;

    // Reward tight fits (low post-residual) more aggressively than linear.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 12.0 * fit_ratio * fit_ratio;

    // Penalize leaving dead space that cannot fit the next item's lookahead.
    if next_item_size > 0 && post_residual > 0 {
        if (next_item_size as f64) > post_residual as f64 {
            score += 0.6 * (next_item_size as f64 - post_residual as f64);
        } else {
            // Subtractive bonus: post-residual can host the next item.
            score -= 1.5;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 8.0;
    } else if fitting_bins_count > 1 {
        // Mild penalty when many bins compete: prefer spreading choices carefully.
        score += 0.4 * (fitting_bins_count as f64 - 1.0);
    }

    // Time-horizon modulation: early in stream, prefer compacting into fewer bins;
    // late in stream, allow new bins more freely since tail effects dominate less.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let new_bin_bias = 6.0 * (1.0 - progress);
    if bin_residual == bin_capacity {
        score += new_bin_bias;
        // New bin is attractive if item is large relative to capacity.
        score -= 10.0 * (item_size as f64 / bin_capacity as f64);
    } else {
        // Existing-bin bonus grows with progress.
        score -= 4.0 * progress;
    }

    // Global residual pressure: high mean residual means open bins are roomy;
    // prefer reusing them, penalize opening new bins.
    score += 0.05 * mean_residual * (open_bins_count as f64).ln().max(1.0) * 0.1;

    // Penalize very small leftover slivers (< 10 unusable dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 3.0;
    }

    // Perfect fit celebration.
    if post_residual == 0 {
        score -= 5.0;
