pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits, penalized smoothly by stream progress.
    let mut score = pr * (1.0 + 0.8 * progress * progress);

    // Non-linear polynomial coupling: squared + quartic residual terms.
    score += 6.0 * norm_pr * norm_pr * (1.0 + progress);
    score += 12.0 * norm_pr * norm_pr * norm_pr * norm_pr * (1.0 - 0.5 * progress);

    // Reward near-perfect fills (small dead space) more strongly late in the stream.
    let tightness = 1.0 - norm_pr;
    score -= 15.0 * tightness * tightness * tightness * (0.5 + progress);

    // Last-chance bonus: only bin that fits -> strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + progress);
    }

    // Penalize bins that are outliers vs. mean residual (smooth coupling).
    let dev = (pr - mean_residual) / cap;
