    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 8.0 * (next_item_size as f64 / cap);
    } else if next_item_size > 0 {
        score += 5.0 * (1.0 - progress);
    }

    // Mild penalty for spreading across many open bins.
    score += 0.4 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // New-bin candidate: keep it competitive only when residuals are all poor.
    if bin_residual == bin_capacity {
        score -= 10.0 * (1.0 - progress) * norm_pr.max(0.0).min(1.0);
        score += 3.0 * progress;
    }

    score
