pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residue mod 8 classes
    let class = post_residual % 8;
    let class_bonus: f64 = match class {
        0 => -30.0,                    // perfectly harmonic residual
        1 => 25.0,                     // worst dead space class
        2 => -15.0,
        3 => 10.0,
        4 => -8.0,
        5 => 5.0,
        6 => -4.0,
        _ => 2.0,
    };
    score += class_bonus;

    // Integer-division thresholds on post_residual
    if post_residual <= 5 {
        score -= 40.0;                 // near-perfect fill
    } else if post_residual <= 10 {
        score -= 20.0;
    } else if post_residual > bin_capacity / 2 {
        score += 12.0;                 // leaving more than half empty
    }

    // Next-item coupling: reward residuals that can host the lookahead item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 18.0;
        // harmonic pairing: post_residual - next_item_size small
        let pair_gap = post_residual - next_item_size;
        if pair_gap <= 10 {
            score -= 15.0;
        }
    } else if next_item_size > 0 {
        score += 10.0;                 // lookahead item cannot reuse this bin
    }

    // Last-chance bin: strongly prefer filling it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate penalty: only open new bin when item is huge relative to mean residual
    if bin_residual == bin_capacity {
        let tight = mean_residual < item_size as f64 * 0.5;
        if !tight {
            score += 45.0;
        } else {
            score += 5.0;
        }
    }

    // Stream progression: tighten tolerance late in the stream
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (mean_residual - post_residual as f64) * (0.3 + 0.4 * progress);

    // Modulo coupling with item size class
    let iclass = item_size % 4;
    if iclass == 0 && post_residual % 4 == 0 {
        score -= 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
