        }
    }

    // Mean residual coupling: prefer bins with below-average residual (tighter bins first).
    score -= (mean_residual - post_residual as f64) * 0.5;

    // New-bin candidate logic: empty bin gets a baseline score that must be beaten
    // by a genuinely good fit; it becomes attractive when residuals are fragmented.
    if bin_residual == bin_capacity {
        score = 45.0 + 1.5 * ob;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 5.0;
        }
    }

