    let fit_ratio = item_size as f64 / cap;
    let gap = (bin_residual - item_size) as f64 / cap;
    let mut score = post_norm * post_norm * 52.0 + post_norm * 20.5;

    // ---- Sliver guard calibrated to next item (borrowed + tuned) ----
    let dead_floor = if next_item_size > 0 { (next_item_size.min(12) as f64).max(6.0) } else { 10.0 };
    if post_residual > 0 && pr < dead_floor && pr != next {
        score += 55.0 * (1.0 - progress * 0.3);
    } else if post_residual > 0 && post_residual < 20 && pr != next {
        score += 22.0;
    }

    // ---- Aggressive 2-step lookahead around the NEXT item ----
    if next > 0.0 {
        if pr == next {
            score -= 48.0;
        } else if pr > next {
            let slack = pr - next;
            let diff = slack / cap;
            score -= 20.0 * (1.0 - diff).max(0.0);
            score -= (-diff * diff * 460.0).exp() * 24.0 * (1.0 - progress * 0.5);
            if diff < 0.04 {
                score -= (0.04 - diff) * 28.0 * (0.6 + progress * 0.6);
            } else if diff > 0.16 {
                score += (diff - 0.16) * 8.0 * (0.5 + progress);
            }
            // Reusability chain: remainder after next can hold next again.
            if slack >= next * 2.0 && slack < next * 2.0 + 8.0 {
                score -= 9.0 * (1.0 - progress * 0.4);
            }
        } else if pr > 0.0 {
            score += (next - pr) / cap * 90.0 * (0.6 + progress * 0.6);
        }
    }

    // ---- Exact / near-exact fit bonuses ----
    if pr == 0.0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    } else if post_residual <= 9 {
        score -= 18.0 * (1.0 - progress * 0.4);
    }

    // ---- Relative-to-mean coupling: favor tighter-than-average bins ----
    if post_residual > 0 && mean_residual > 0.0 {
        let waste = post_norm - mean_residual / cap;
        if waste > 0.0 {
            score += waste * 30.0 * (0.4 + progress * 0.6);
        } else {
            score -= (-waste) * 10.0;
        }
    }

    // ---- New-bin candidate decision ----
    if bin_residual == bin_capacity {
        let size_pull = fit_ratio * 14.0;
        if fitting_bins_count <= 2 && gap > 0.0 {
            score -= (18.0 + size_pull) * (1.0 - progress * 0.6);
        } else if fitting_bins_count == 0 {
            score -= 5.0;
        } else {
            score += 20.0 + open_bins_count as f64 * (0.5 + 0.5 * progress);
        }
        if next > 0.0 && fitting_bins_count <= 3 && fit_ratio >= next / cap * 0.95 {
            score -= 5.5 * (1.0 - progress * 0.5);
        }
        if next > 0.0 && fit_ratio + next / cap > 1.0 {
            score += 8.0 * (1.0 - progress * 0.4);
        }
        if fit_ratio > 0.5 && progress < 0.5 {
            score -= 6.0 * (1.0 - progress);
        }
        if progress > 0.85 && fit_ratio > 0.6 {
            score -= 4.0 * (progress - 0.85) * 20.0;
        }
    }

    // Sharp bonus for leaving a tiny gap (<12% of capacity).
    if gap > 0.0 && gap < 0.12 {
        score -= (0.12 - gap) * 48.0;
    } else if gap >= 0.12 && gap < 0.22 && fitting_bins_count <= 3 {
        score += (gap - 0.12) * 18.0 * (0.5 + progress * 0.5);
    }
    if gap >= 0.22 && gap < 0.30 && fitting_bins_count <= 2 {
        score += (gap - 0.22) * 22.0 * (0.6 + progress * 0.4);
    }

    // Next-item chain: leftover after next item nearly closes bin.
    if next > 0.0 && gap > 0.12 {
        let nxt_gap = ((gap * cap - next).max(0.0)) / cap;
        if nxt_gap < 0.06 {
            score -= 9.0 * (1.0 - nxt_gap / 0.06) * (0.5 + progress);
        }
    }

    // Reward large items filling bins deeply.
    score -= fit_ratio * fit_ratio * 6.0;

    // Congestion: penalize sloppy fits when many bins compete.
    if fitting_bins_count > 2 {
        score += gap * 6.5 * ((fitting_bins_count.min(12) as f64 - 2.0) / 10.0);
    }
    if open_bins_count > 8 {
        score += post_norm * 5.0 * ((open_bins_count.min(20) as f64 - 8.0) / 12.0);
    }

    // Late-stream consolidation.
    if progress > 0.7 && post_norm > 0.25 {
        score += (post_norm - 0.25) * 6.0 * (progress - 0.7) / 0.3;
    }

    // Last-chance bonus.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 - fit_ratio);
    }
    if fitting_bins_count == 1 && gap > 0.0 && gap < 0.06 {
        score -= 7.0 * (1.0 - progress * 0.5);
    }

    // Deep fill bonus.
    let fill_r = item_size as f64 / bin_residual.max(1) as f64;
    if fill_r > 0.90 && bin_residual != bin_capacity {
        score -= (fill_r - 0.90) * 18.0 * (0.6 + progress * 0.5);
    }

    // Dead-space guard: stranded gap the next item cannot reuse.
    if next > 0.0 && pr > 0.0 && (post_residual as u32) < next_item_size && post_norm > 0.03 {
        let dead_ratio = (next - pr) / cap;
        score += dead_ratio * 90.0 * (0.6 + progress * 0.6);
    }

    // Mid-residual band: leftover 10-20% that next item cannot fit.
    if pr > 0.0 && post_norm >= 0.10 && post_norm < 0.20 && next > pr {
        score += (next - pr) / cap * 26.0 * (0.4 + progress * 0.8);
    }

    // Half-consumed bins late in stream.
    if pr > 0.0 && pr < item_size as f64 * 0.5 && progress > 0.3 {
        score += 4.0 * (1.0 - progress);
    }

    // Second-fit snugness: after next lands, remainder nearly perfect.
    if next > 0.0 && pr > next {
        let second_slack = (pr - next) / cap;
        if second_slack < 0.05 {
            score -= (0.05 - second_slack) * 40.0 * (0.5 + progress * 0.5);
        }
    }

    // Modular chain: pr - next is near a multiple of next.
    if next > 0.0 && pr >= next {
        let frac = ((pr - next) % next.max(1.0)) / next.max(1.0);
        if frac < 0.08 {
            score -= 10.0 * (1.0 - progress * 0.5);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus: penalize large post_residual, especially when it matches next item exactly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0; // chain: next item fits perfectly here
        } else if post_residual > next_item_size {
            score -= 8.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            score += 0.5 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Dead space penalty: residual too small to fit anything useful later.
    if post_residual < 10 {
        score += 25.0;
    }

    // Last chance bonus: only bin that fits the item.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Relative to mean residual: prefer tighter-than-average bins.
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Penalize opening a new bin when decent fits exist (new-bin candidate has residual == capacity).
    if bin_residual == bin_capacity {
        score += 15.0 + 0.2 * open_bins_count as f64;
        // But allow new bin if item is large and would leave huge fragmentation elsewhere.
        if item_size > bin_capacity / 2 {
            score -= 10.0;
        }
    }

    // Late in stream: consolidate, prefer filling existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (bin_residual == bin_capacity) as u8 as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let post_norm = pr / cap;
    let mut score = post_norm * post_norm * 50.0 + post_norm * 20.0;

    // Perfect / near-perfect fit rewards.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 42.0;
    } else if post_residual <= 9 {
        score -= 18.0 * (1.0 - progress * 0.4);
    }

    // Dead-space class: residuals in (0, 12] are almost unusable.
    let dead_floor = if next_item_size > 0 { (next_item_size.min(12) as f64).max(6.0) } else { 10.0 };
    if post_residual > 0 && (post_residual as f64) < dead_floor {
        score += 62.0 * (1.0 - progress * 0.3);
    } else if post_residual < 20 {
        score += 25.0;
    }

    // Harmonic divisibility rewards.
    if post_residual > 0 {
        let p = post_residual;
        if p % 50 == 0 { score -= 18.0; }
        else if p % 25 == 0 { score -= 12.0; }
        else if p % 20 == 0 { score -= 10.0; }
        else if p % 10 == 0 { score -= 8.0; }
        else {
            score += (p % 5) as f64 * 1.5;
        }
    }

    // Lookahead: next item pairing quality in post_residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64 / cap;
        score -= (-slack * slack * 450.0).exp() * 24.0 * (1.0 - progress * 0.5);
        let nxt_left = post_residual - next_item_size;
        if nxt_left % 10 == 0 {
            score -= 10.0;
        } else if nxt_left > 12 {
            score -= 4.0;
        } else {
            score += 6.0;
        }
        // Near-multiple of next item: chain fits.
        let nxt = next_item_size as f64;
        let frac = ((pr - nxt) % nxt.max(1.0)) / nxt.max(1.0);
        if frac < 0.08 {
            score -= 10.0 * (1.0 - progress * 0.5);
        }
        // Two-of-next-item fits.
        if pr >= nxt * 2.0 && pr < nxt * 2.0 + 8.0 {
            score -= 8.0 * (1.0 - progress * 0.4);
        }
    } else if next_item_size > 0 && pr > 0.0 {
        // Next item cannot use this leftover: dead-space penalty.
        let dead_ratio = (next_item_size as f64 - pr) / cap;
        if post_norm > 0.03 {
            score += dead_ratio * 90.0 * (0.6 + progress * 0.6);
        }
        if fitting_bins_count <= 2 {
            score += 18.0 * (1.0 - progress * 0.5);
        }
    }

    // Tight-gap bonus: prefer bins where item nearly fills residual.
    let gap = (bin_residual - item_size) as f64 / cap;
    if gap > 0.0 && gap < 0.12 {
        score -= (0.12 - gap) * 48.0;
    } else if gap >= 0.12 && gap < 0.22 {
        if fitting_bins_count <= 3 {
            score += (gap - 0.12) * 18.0 * (0.5 + progress * 0.5);
        }
    } else if gap >= 0.22 && gap < 0.30 && fitting_bins_count <= 2 {
        score += (gap - 0.22) * 22.0 * (0.6 + progress * 0.4);
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }
    if fitting_bins_count == 1 && gap > 0.0 && gap < 0.06 {
        score -= 7.0 * (1.0 - progress * 0.5);
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let size_pull = (item_size as f64 / cap) * 14.0;
        if fitting_bins_count <= 2 {
            score -= (18.0 + size_pull) * (1.0 - progress * 0.6);
        } else {
            score += 20.0 + open_bins_count as f64 * (0.5 + 0.5 * progress);
        }
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a bin
        }
        if next_item_size > 0 && fitting_bins_count <= 3 && (item_size as f64) >= next_item_size as f64 * 0.95 {
            score -= 5.5 * (1.0 - progress * 0.5);
        }
        if next_item_size > 0 && fitting_bins_count >= 1 && (item_size as f64) + next_item_size as f64 > cap {
            score += 8.0 * (1.0 - progress * 0.4);
        }
        if (item_size as f64) > cap * 0.5 && progress < 0.5 {
            score -= 6.0 * (1.0 - progress);
        }
        if progress > 0.85 && (item_size as f64) / cap > 0.6 {
            score -= 4.0 * (progress - 0.85) * 20.0;
        }
        if next_item_size > 0 && (item_size as f64) + next_item_size as f64 <= cap && (item_size as f64) / cap > 0.35 {
            score -= 3.0 * (1.0 - progress);
        }
    }

    // Global pressure: high mean residual -> pack tight bins.
    score -= (mean_residual / cap) * 5.0;

    // Waste-relative pressure: penalize bins whose post-residual exceeds mean.
    if post_residual > 0 && mean_residual > 0.0 {
        let waste = post_norm - (mean_residual / cap);
        if waste > 0.0 {
            score += waste * 30.0 * (0.4 + progress * 0.6);
        } else {
            score -= (-waste) * 10.0;
        }
        // Very small post-residual with many open bins: keep it alive.
        if post_norm < 0.02 && fitting_bins_count >= 4 {
            score -= 6.0 * (1.0 - progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good, but dead space below
    // the smallest possible item (1) is pure waste. Penalize tiny unusable
    // residuals more sharply than mid-range ones.
    if post_residual > 0 {
        score += 12.0 * (1.0 - (post_residual as f64) / 10.0).max(0.0);
    } else {
        score -= 15.0; // perfect fit reward
    }

    // Lookahead coupling: if the next item fits exactly into the post
    // residual, strongly favor this bin.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        score += 0.6 * gap;
        if post_residual as i64 == next_item_size as i64 {
            score -= 20.0;
        }
        // If next item cannot fit in post residual but could fit in
        // bin_residual, placing here may be wasteful.
        if next_item_size as f64 > post_residual as f64 && next_item_size as f64 <= bin_residual as f64 {
            score += 8.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening
    // a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0 + 0.25 * item_size as f64;
    }

    // New-bin candidate handling: an empty bin has high post_residual, so
    // it naturally scores worse; add a mild dynamic bias that decreases as
    // the stream progresses (late in the stream, prefer packing into open
    // bins to avoid leaving many partially filled bins).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score += 6.0 - 10.0 * progress;
        // Prefer opening a new bin when existing bins are very full on average.
        score += 0.05 * (mean_residual - post_residual as f64).max(0.0);
    } else {
        // Mild preference for bins whose residual is below the mean
        // (pack fuller bins first, keep large-residual bins flexible).
        score += 0.08 * ((bin_residual as f64) - mean_residual).max(0.0);
    }

    // Many open bins: encourage consolidation into existing bins.
    score += 0.05 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Base: quadratic waste penalty on post-residual, coupled with stream progress.
    let mut score = pr * (1.0 + 0.8 * pr_norm) * (1.0 + 0.6 * progress);

    // Tight fits rewarded, scaled by progress (tight packing matters more later).
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 12.0 * tightness * tightness * (0.5 + progress);

    // Penalize creating dead space below the smallest plausible item, smoothly.
    let dead = (30.0 - pr).max(0.0);
    score += 0.9 * dead * dead / cap * (1.0 + progress);

    // Last-chance bin: strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - 0.5 * progress);
    }

    // Many open bins: prefer filling existing ones rather than spreading.
    score += 0.6 * open_bins_count as f64 * pr_norm;

    // Deviation from mean residual: prefer bins that keep residual distribution balanced.
    score += 0.35 * (pr - mean_residual).abs();

    // Lookahead: reward leaving room for the next item; penalize near-miss residuals.
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr >= ni {
            score -= 8.0 * (ni / cap) * (1.0 - progress);
        } else {
            score += 0.5 * (ni - pr) * (1.0 - progress);
        }
    }

    // New-bin candidate: only attractive when existing bins fit poorly.
    if bin_residual == bin_capacity {
        let poor_fit = if fitting_bins_count <= 1 { 1.0 } else { 0.0 };
        score = cap as f64 * (0.9 + 0.5 * progress) - 60.0 * poor_fit * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 0.92;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = 0.0;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "useful"
    // residue classes (multiples of small denominators) are rewarded.
    let cap = bin_capacity as f64;

    // Perfect fit -> strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Tiny dead space (unusable for typical items >= 1) -> penalize mildly.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Harmonic class reward: post_residual divisible by common small sizes
    // leaves room that future items can exactly tile.
    let pr = post_residual;
    if pr > 0 {
        if pr % 10 == 0 { score -= 8.0; }
        else if pr % 5 == 0 { score -= 4.0; }
        else if pr % 20 == 0 { score -= 10.0; }
        else { score += 3.0; }
    }

    // Integer-division threshold: post_residual in [50, cap/2) is a "half-class"
    // residual, very reusable; post_residual just below 50 is awkward.
    if pr >= bin_capacity / 2 {
        score -= 6.0;
    } else if pr >= 40 {
        score += 2.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly favor this bin (chained perfect fits).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            let chain_left = post_residual - next_item_size;
            if chain_left % 10 == 0 { score -= 12.0; }
            score -= (chain_left as f64) * 0.1;
        } else {
            // Next item cannot follow here; penalize slightly.
            score += 5.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new
    // bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate handling: an empty bin should only win when no open
    // bin offers a decent fit. Give it a baseline penalty that decays as the
    // stream progresses (late in stream, consolidation matters more).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = cap - progress * 10.0 + 25.0;
        if next_item_size > 0 && next_item_size <= post_residual && post_residual >= bin_capacity / 2 {
            score -= 20.0; // fresh bin supports a good two-item packing
        }
    }

    // Prefer tighter bins generally: scale by residual fraction.
    score += (bin_residual as f64 / cap) * 2.0;

    // Slight preference to balance open bins when many are open.
    score += (open_bins_count as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = 0.0;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    if post_residual == 0 {
        // Perfect fit is ideal: strong reward.
        score -= 50.0;
    }

    // Moderate gaps (10..20) are semi-unusable: mild penalty.
    if post_residual >= 10 && post_residual < 20 {
        score += 12.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, prefer tight fills.
    score += (open_bins_count as f64).ln().max(0.0) * 3.0;

    // Prefer bins below mean residual (tighter bins first).
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 40.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // dead space w.r.t. lookahead item
        score += 5.0;
    }

    // New-bin candidate: only attractive when current fit is bad (large post_residual).
    if bin_residual == bin_capacity {
        score += 15.0; // base reluctance to open new bins
        if post_residual > 40 {
            score -= 30.0; // poor fit elsewhere -> new bin is fine
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let post_norm = pr / cap;
    let fit_ratio = item_size as f64 / cap;
    let gap = (bin_residual - item_size) as f64 / cap;
    let mut score = post_norm * post_norm * 50.0 + post_norm * 20.0;

    // Smooth polynomial coupling of post_residual with stream progress.
    let progress_weight = 1.0 + progress * (1.0 - progress) * 4.0;
    score -= pr * pr / (cap * cap) * 40.0 * progress_weight;

    // Exact-fill and near-exact-fill bonuses.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 42.0;
    } else if post_residual <= 9 {
        score -= 18.0 * (1.0 - progress * 0.4);
    }

    // Dead-floor logic: tiny leftovers that likely can't fit anything useful.
    let dead_floor = if next_item_size > 0 { (next_item_size.min(12) as f64).max(6.0) } else { 10.0 };
    if post_residual > 0 && pr < dead_floor {
        score += 62.0 * (1.0 - progress * 0.3);
    } else if post_residual < 20 {
        score += 25.0;
    }

    // Reward bins whose leftover still accommodates the next item (gaussian slack).
    if next_item_size > 0 && pr >= next_item_size as f64 {
        let slack = (pr - next_item_size as f64) / cap;
        score -= (-slack * slack * 450.0).exp() * 24.0 * (1.0 - progress * 0.5);
    } else if next_item_size > 0 {
        // Penalize dead space that cannot fit the next item.
        let dead_ratio = (next_item_size as f64 - pr) / cap;
        score += dead_ratio * 90.0 * (0.6 + progress * 0.6);
    }

    // Tight-gap band: near-perfect fits get a strong bonus.
    if gap > 0.0 && gap < 0.12 {
        score -= (0.12 - gap) * 48.0;
        if fitting_bins_count == 1 && gap < 0.06 {
            score -= 7.0 * (1.0 - progress * 0.5);
        }
    } else if gap >= 0.12 && gap < 0.22 && fitting_bins_count <= 3 {
        score += (gap - 0.12) * 18.0 * (0.5 + progress * 0.5);
    } else if gap >= 0.22 && gap < 0.30 && fitting_bins_count <= 2 {
        score += (gap - 0.22) * 22.0 * (0.6 + progress * 0.4);
    }

    // Relative waste vs. mean residual across open bins.
    if post_residual > 0 && mean_residual > 0.0 {
        let waste = post_norm - (mean_residual / cap);
        if waste > 0.0 {
            score += waste * 30.0 * (0.4 + progress * 0.6);
        } else {
            score -= (-waste) * 10.0;
        }
    }

    // Last-chance bonus for the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 - fit_ratio);
    }

    // New-bin candidate: consolidate when many bins are open, open when few.
    if bin_residual == bin_capacity {
        let size_pull = fit_ratio * 14.0;
        if fitting_bins_count <= 2 {
            score -= (18.0 + size_pull) * (1.0 - progress * 0.6);
        } else {
            score += 20.0 + open_bins_count as f64 * (0.5 + 0.5 * progress);
        }
        if next_item_size > 0 && fitting_bins_count <= 3 && item_size as f64 >= next_item_size as f64 * 0.95 {
            score -= 5.5 * (1.0 - progress * 0.5);
        }
        if next_item_size > 0 && fitting_bins_count >= 1 && item_size as f64 + next_item_size as f64 > cap {
            score += 8.0 * (1.0 - progress * 0.4);
        }
        if fit_ratio > 0.5 && progress < 0.5 {
            score -= 6.0 * (1.0 - progress);
        }
        if progress > 0.85 && fit_ratio > 0.6 {
            score -= (progress - 0.85) * 80.0;
        }
        if next_item_size > 0 && item_size as f64 + next_item_size as f64 <= cap && fit_ratio > 0.35 {
            score -= 3.0 * (1.0 - progress);
        }
    }

    // Second-item slack band: leftover just above next item size is ideal.
    if next_item_size > 0 && post_residual > 0 {
        let second_slack = (pr - next_item_size as f64) / cap;
        if second_slack >= 0.0 && second_slack < 0.05 {
            score -= (0.05 - second_slack) * 40.0 * (0.5 + progress * 0.5);
        }
        // Harmonic-fit bonus: leftover nearly a multiple of next item.
        if pr >= next_item_size as f64 {
            let nxt = next_item_size.max(1) as f64;
            let frac = ((pr - nxt) % nxt) / nxt;
            if frac < 0.08 {
                score -= 10.0 * (1.0 - progress * 0.5);
            }
        }
        if pr >= next_item_size as f64 * 2.0 && pr < next_item_size as f64 * 2.0 + 8.0 {
            score -= 8.0 * (1.0 - progress * 0.4);
        }
    }

    // Reward high fill fraction smoothly.
    score -= fit_ratio * fit_ratio * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match of post_residual to next item
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect fit for next item: strong reward
        if post_residual == next_item_size {
            score -= 60.0;
        } else {
            // Proximity reward: closer post_residual to next_item_size is better
            score -= 30.0 / (1.0 + gap / 10.0);
            // Penalize post-residuals that are too small to ever be useful
            if post_residual < 10 && post_residual > 0 {
                score += 25.0;
            }
        }
    } else {
        // Last item: minimize waste directly
        score += (bin_residual - item_size) as f64 * 0.5;
    }

    // Compare against mean residual: placing into a large-residual bin is cheap,
    // placing into a tight bin wastes scarce space
    let tightness = (bin_residual as f64 - mean_residual).max(-100.0);
    score -= 0.3 * tightness;

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // New-bin candidate: penalize slightly so we only open when nothing fits well,
    // but reward it when current bins would leave large dead space
    if bin_residual == bin_capacity {
        score += 15.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 20.0; // fresh bin can also host the next item
        }
    }

    // Prefer denser packing late in the stream
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

