pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual close to zero is already favored by base term.
    // Penalize creating dead space that can't hold the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Next item fits here: strong bonus for leaving usable space.
            score -= 6.0 + 0.15 * next_item_size as f64;
        } else {
            // Dead space penalty scaled by wasted gap size.
            let gap = (post_residual as f64).max(0.0);
            score += 0.5 * gap;
        }
    }

    // Last chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Many open bins: encourage consolidation into existing bins.
    score -= 0.4 * open_bins_count as f64;

    // Bin residual relative to mean residual: prefer bins with smaller residual
    // (best-fit flavor) when this bin is tighter than average.
    let diff = mean_residual - bin_residual as f64;
    score -= 0.3 * diff;

    // Early in stream: be conservative, mild penalty for filling bins too fast.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 4.0 * (1.0 - progress) * (item_size as f64 / bin_capacity as f64);

    // New-bin candidate: only attractive when residual is full and item is large
    // or nothing fits well; otherwise penalize opening new bins.
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 / bin_capacity as f64;
        if fitting_bins_count == 0 {
            score -= 20.0; // must open new bin
        } else {
            score += 10.0 + 8.0 * (1.0 - large_item);
        }
    }

    // Slight preference for bins with high utilization already.
    score -= 0.05 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Non-linear coupling of post_residual with stream progress:
    // early on, small post-residuals are fine; later, penalize them more
    // (dead space hurts more as the stream matures).
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;
    let progress_coupling = pr_norm * pr_norm * (0.5 + progress);
    score += 20.0 * progress_coupling;

    // Reward tight fits with a smooth saturating term.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * fit_ratio * fit_ratio;

    // Smoothly penalize when this bin is the only fitting option (last chance):
    // strongly prefer using it rather than opening a new bin.
    if fitting_bins_count == 1 {
        score -= 8.0 * (1.0 - pr_norm);
    }

    // Lookahead: reward leaving room for the next item (smooth kernel).
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64) as f64;
        let kernel = (-gap.abs() / 25.0) * (-gap.abs() / 25.0);
        score -= 6.0 * kernel;
    }

    // Deviation from mean residual: prefer bins near the mean (smooth balance).
    let dev = (pr - mean_residual) / cap;
    score += 5.0 * dev * dev;

    // Mild new-bin aversion that grows with stream progress (consolidation).
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 4.0 + 10.0 * progress + 0.5 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues that are "dead" (small but
    // unusable) get heavily penalized. Dead space = post_residual in 1..=9.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (10 - post_residual) as f64;
    }

    // Perfect fit bonus: post_residual == 0 is ideal.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Harmonic classes on capacity fractions: post_residual that is a multiple
    // of common item sizes (10, 20, 25, 50) is reusable -> reward.
    let pr = post_residual;
    if pr % 10 == 0 {
        score -= 12.0;
    }
    if pr % 25 == 0 {
        score -= 6.0;
    }
    if pr % 50 == 0 {
        score -= 6.0;
    }

    // Lookahead coupling: reward if next item fits exactly into post_residual,
    // penalize if next item is close but does not fit (creates temptation but
    // forces a new bin anyway).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 55.0;
        } else if next_item_size < post_residual {
            let gap = post_residual - next_item_size;
            score -= 8.0 * (1.0 - gap as f64 / 100.0);
        } else {
            let over = next_item_size - post_residual;
            if over <= 10 {
                score += 10.0 + over as f64;
            }
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using
    // it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Penalize it mildly so we prefer packing into existing bins, but scale
    // with stream progress: late in the stream, consolidation matters more.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 25.0 + 20.0 * progress;
    }

    // Prefer bins tighter than the mean residual (best-fit flavor with mean
    // anchoring): a bin with residual below mean is more "loaded".
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += 3.0;
    }

    // Integer-division threshold: post_residual buckets by quarters of
    // capacity; smaller quarter buckets are worse (more fragmentation).
    let quarter = bin_capacity / 4;
    if post_residual < quarter {
        score += 8.0;
    } else if post_residual < 2 * quarter {
        score += 2.0;
    } else if post_residual < 3 * quarter {
        score -= 2.0;
    } else {
        score -= 4.0;
    }

    // Many open bins: encourage filling existing ones rather than spreading.
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let next = next_item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items.max(1) as f64 } else { 0.0 };
    let post_norm = pr / cap;
    let fit_ratio = item_size as f64 / cap;
    let gap = (bin_residual - item_size) as f64 / cap;
    let mut score = post_norm * post_norm * 50.0 + post_norm * 20.0;

    // ---- Sliver guard: calibrated dead floor from next-item size ----
    let dead_floor = if next_item_size > 0 { (next_item_size.min(12) as f64).max(6.0) } else { 10.0 };
    if post_residual > 0 && pr < dead_floor {
        score += 58.0 * (1.0 - progress * 0.3);
    } else if post_residual > 0 && post_residual < 20 {
        score += 22.0;
    }

    // ---- Aggressive 2-step lookahead ----
    if next > 0.0 {
        if pr == next {
            score -= 45.0;
        } else if pr > next {
            let slack = pr - next;
            let diff = slack / cap;
            score -= 20.0 * (1.0 - diff).max(0.0);
            score -= (-diff * diff * 450.0).exp() * 24.0 * (1.0 - progress * 0.5);
            if diff < 0.04 {
                score -= (0.04 - diff) * 26.0 * (0.6 + progress * 0.6);
            } else if diff > 0.16 {
                score += (diff - 0.16) * 8.0 * (0.5 + progress);
            }
            // Chain bonus: residual divisible by next item keeps filling later.
            let frac = (slack % next.max(1.0)) / next.max(1.0);
            if frac < 0.08 {
                score -= 10.0 * (1.0 - progress * 0.5);
            }
            let chain = (slack / next.max(1.0)) * next / cap;
            if chain > 0.5 {
                score -= (chain - 0.5) * 14.0 * (0.5 + progress * 0.5);
            }
        } else if pr > 0.0 {
            let dead_ratio = (next - pr) / cap;
            score += dead_ratio * 88.0 * (0.6 + progress * 0.6);
            if fitting_bins_count <= 2 {
                score += 14.0 * (1.0 - progress * 0.5);
            }
        }
    }

    // ---- Relative-to-mean coupling ----
    if pr > 0.0 && mean_residual > 0.0 {
        let waste = post_norm - mean_residual / cap;
        if waste > 0.0 {
            score += waste * 30.0 * (0.4 + progress * 0.6);
        } else {
            score -= (-waste) * 10.0;
        }
    }

    // ---- New-bin candidate decision ----
    if bin_residual == bin_capacity {
        let others = if fitting_bins_count > 0 { fitting_bins_count - 1 } else { 0 };
        let size_pull = fit_ratio * 14.0;
        if fitting_bins_count <= 2 && gap > 0.0 {
            score -= (18.0 + size_pull) * (1.0 - progress * 0.6);
        } else if others == 0 {
            score -= 5.0;
        } else {
            score += 20.0 + open_bins_count as f64 * (0.5 + 0.5 * progress);
        }
        if next > 0.0 && fitting_bins_count <= 3 && item_size as f64 >= next * 0.95 {
            score -= 5.5 * (1.0 - progress * 0.5);
        }
        if next > 0.0 && item_size as f64 + next > cap {
            score += 8.0 * (1.0 - progress * 0.4);
        }
        if item_size as f64 > cap * 0.5 && progress < 0.5 {
            score -= 6.0 * (1.0 - progress);
        }
        if next > 0.0 && item_size as f64 + next <= cap && fit_ratio > 0.35 {
            score -= 3.0 * (1.0 - progress);
        }
    }

    // Exact / near-exact fit bonuses.
    if pr == 0.0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 42.0;
    } else if post_residual <= 9 {
        score -= 18.0 * (1.0 - progress * 0.4);
    } else if post_norm < 0.04 {
        score -= (0.04 - post_norm) * 55.0 * (0.7 + progress * 0.3);
    }

    // Sharp bonus for leaving a tiny gap.
    if gap > 0.0 && gap < 0.12 {
        score -= (0.12 - gap) * 48.0;
        if fitting_bins_count == 1 && gap < 0.06 {
            score -= 7.0 * (1.0 - progress * 0.5);
        }
    } else if gap >= 0.12 && gap < 0.22 {
        if fitting_bins_count <= 3 {
            score += (gap - 0.12) * 18.0 * (0.5 + progress * 0.5);
        }
        if next > 0.0 && pr > 0.0 && pr < next {
            score += (gap - 0.10) * 60.0 * (0.5 + progress);
        }
    }
    if gap >= 0.22 && gap < 0.35 && progress > 0.55 {
        score += (gap - 0.22) * 45.5 * (progress - 0.55) * 2.0;
    }

    // Next-item chain: leftover after next item nearly closes bin.
    if next > 0.0 && gap > 0.12 {
        let nxt_gap = ((gap * cap - next).max(0.0)) / cap;
        if nxt_gap < 0.06 {
            score -= 9.0 * (1.0 - nxt_gap / 0.06) * (0.5 + progress);
        }
        if pr >= next {
            let two_fit = (pr - next) / cap;
            if two_fit < 0.02 && fitting_bins_count <= 2 {
                score -= 9.0 * (1.0 - progress * 0.4);
            }
        }
    }

    // Reward large items filling bins deeply.
    score -= fit_ratio * fit_ratio * 6.0;

    // Congestion penalty for sloppy fits.
    if fitting_bins_count > 2 {
        score += gap * 6.5 * ((fitting_bins_count.min(12) as f64 - 2.0) / 10.0);
    }
    if open_bins_count > 8 {
        score += post_norm * 5.0 * ((open_bins_count.min(20) as f64 - 8.0) / 12.0);
    }

    // Late-stream consolidation.
    if progress > 0.7 && post_norm > 0.25 {
        score += (post_norm - 0.25) * 6.0 * (progress - 0.7) / 0.3;
    }

    // Last-chance bonus.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 - fit_ratio);
    }

    // Deep fill bonus.
    let fill_r = item_size as f64 / bin_residual.max(1) as f64;
    if fill_r > 0.90 && bin_residual != bin_capacity {
        score -= (fill_r - 0.90) * 18.0 * (0.6 + progress * 0.5);
    }

    // Dead-space guard after next item.
    if next > 0.0 && pr > 0.0 {
        let after_next = (pr - next).max(0.0);
        let dead = after_next / cap;
        if dead > 0.0 && dead < 0.08 {
            let reusable = if after_next >= next { 1.0 } else { 0.0 };
            score += (0.08 - dead) * 16.0 * (1.0 - reusable * 0.5) * (0.5 + progress);
        }
    }

    // Two-next bonus: residual fits next item twice.
    if post_residual > 0 && next > 0.0 && pr >= next * 2.0 && pr < next * 2.0 + 8.0 {
        score -= 8.0 * (1.0 - progress * 0.4);
    }

    // Half-consumed bins late.
    if pr > 0.0 && pr < item_size as f64 * 0.5 && progress > 0.3 {
        score += 4.0 * (1.0 - progress);
    }

    score
}

