    let mut score = post_residual as f64;

    // Perfect fit: overwhelmingly reward.
    if post_residual == 0 {
        score -= 1000.0;
        return score;
    }

    // Strict dead-space avoidance: small unusable gaps are penalized hard.
    if post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 15.0;
    }

    // Lookahead (k=2): reward bins whose leftover can host the next item.
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        score -= 8.0;
    } else if next_item_size > 0 && post_residual > 0 && (next_item_size as u32) > post_residual {
        // leftover too small for the next item -> mild dead-space penalty
        score += 5.0;
    }

    // Last-chance pressure: if this is the only open bin that fits, strongly
    // prefer using it over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize so it only wins when all open fits are poor.
    if bin_residual == bin_capacity {
        score += 45.0;
        // Opening a new bin is more acceptable early in the stream.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 20.0 * (1.0 - progress);
    }

    // Mild pressure from number of open bins: consolidation preference.
    score += open_bins_count as f64 * 0.3;

    // Nudge toward bins below the mean residual (balance filling).
    score += (post_residual as f64 - mean_residual) * 0.1;

    score
}

