    let mut score = post_residual as f64;

    // Reward near-perfect fits: small post_residual is good, but avoid
    // leaving dead space that nothing can ever use.
    if post_residual == 0 {
        score -= 60.0; // perfect closure — always prioritize
    } else if post_residual < 10 {
        score -= 35.0; // nearly perfect: tiny unusable sliver
    } else {
        // Penalize dead space relative to the smallest possible item (1..100 interface)
        let min_item = 1.0f64;
        if (post_residual as f64) < min_item {
            score += 50.0;
        }
    }

    // Aggressive 2-step lookahead: if the next item fits exactly into the
    // post residual, this bin is a perfect 2-item chain.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 55.0;
        } else if next_item_size < post_residual {
            let two_step_waste = post_residual - next_item_size;
            score += two_step_waste as f64 * 0.8;
        } else {
            // Next item cannot follow here: the post residual becomes dead space
            // unless a future item fits. Penalize proportionally.
            score += (post_residual as f64) * 0.35;
        }
    }

    // Compare post_residual against mean residual: pushing this bin's residual
    // far below the mean concentrates waste; keeping residuals balanced is better.
    let pr = post_residual as f64;
    let dev = pr - mean_residual;
    if dev > 0.0 {
        score += dev * 0.25; // residual above mean: this bin stays reusable
    } else {
        score += dev * 0.10; // residual below mean: slight penalty for imbalance
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 + (item_size as f64) * 0.1;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // the item is large relative to capacity or no good fit exists.
    if bin_residual == bin_capacity {
        // Base preference against opening new bins while open bins can absorb.
        score += 25.0;
        if open_bins_count == 0 {
            score -= 100.0; // must open a bin
        } else if next_item_size > 0 && next_item_size >= item_size {
            // If the next item is bigger, opening a fresh bin now may waste
            // this bin's residual; slight reward for opening.
            score -= 8.0;
        }
        // Large items pack best into fresh bins.
        let fill = item_size as f64 / bin_capacity as f64;
        if fill > 0.7 {
            score -= 20.0 * (fill - 0.7);
        }
    }

    // Early in the stream, allow more bins to open for flexibility;
    // late in the stream, tighten packing aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 5.0;
    score += (open_bins_count as f64).ln().max(0.0) * 2.0;

    score
}

