    // Double-fit bonus.
    if next > 0.0 && pr >= next * 2.0 && pr < next * 2.0 + 8.0 {
        score -= 8.0 * (1.0 - progress * 0.4);
    }

    // Last-chance micro-gap bonus.
    if fitting_bins_count == 1 && gap > 0.0 && gap < 0.06 {
        score -= 7.0 * (1.0 - progress * 0.5);
    }

    // Dead-space penalty when few fitting bins and residual too small for next.
    if next > 0.0 && post_residual > 0 && post_residual < next_item_size && fitting_bins_count <= 2 {
        score += 18.0 * (1.0 - progress * 0.5);
    }

    // Chain-closure.
    if next > 0.0 && pr >= next && fitting_bins_count > 1 {
        let chain = pr - next;
        let chain_ref = mean_residual.max(1.0) * 0.35;
        if chain < chain_ref {
            score -= 5.0 * (1.0 - chain / chain_ref) * (0.5 + progress * 0.5);
        }
    }

    // Mid-band residual vacuum.
    if post_norm > 0.03 && post_norm < 0.10 {
        if next > 0.0 && pr >= next {
            score -= 4.0 * (1.0 - progress * 0.5);
        } else {
            score += 6.0 * (0.5 + progress * 0.5);
        }
    }

    // Fine-grained residual fitting with lookahead.
    if next > 0.0 && pr > 0.0 && pr >= next && fill_r > 0.85 {
        let reuse = (pr - next) / cap;
        if reuse < 0.06 {
            score -= (0.06 - reuse) * 30.0 * (0.5 + progress * 0.5);
        }
    }

    // Discourage residuals in the awkward 0.10–0.18 band.
    if post_norm >= 0.10 && post_norm < 0.18 && next > 0.0 && pr < next {
        score += (0.18 - post_norm) * 14.0 * (0.4 + progress * 0.6);
    }

    // Residual-consolidation with multi-fit lookahead.
    if next > 0.0 && pr >= next {
        let fits_ahead = (pr / next).floor();
        if fits_ahead >= 2.0 {
            let remainder = pr - fits_ahead * next;
            let rem_norm = remainder / cap;
            if rem_norm > 0.005 {
                score += rem_norm * 55.0 * (0.5 + progress * 0.5);
            } else {
                score -= 4.0 * (1.0 - progress * 0.4);
            }
            // Reward when the multi-fit chain consumes nearly all residual,
            // tightening mid-size gap exploitation.
            let chain_fill = (fits_ahead * next) / pr;
            if chain_fill > 0.95 {
                score -= (chain_fill - 0.95) * 60.0 * (0.5 + progress * 0.5);
            }
        }
    }

    // Late-stream residual sweep.
    let remaining = if total_items > step_index { total_items - step_index } else { 1 };
    if remaining < 12 && post_residual > 0 {
        score += post_norm * 40.0;
    }

    // Two-item lookahead: prefer bins whose post-residual after the next item
    // still fits the mean-residual class with minimal slack, reducing dead
    // space variance across the stream.
    if next > 0.0 && pr >= next && fitting_bins_count > 1 && remaining > 12 {
        let after = pr - next;
        let typical = mean_residual.max(1.0);
        if after >= typical {
            let slack = (after - typical) / cap;
            if slack < 0.02 {
                score -= (0.02 - slack) * 20.0 * (0.6 + progress * 0.4);
            }
        }
    }

    // NEW: chain-length exploitation — reward bins where the residual can host
    // exactly k next-items with near-zero remainder, even for k > 2, and
    // penalize one-extra-item overshoot that would strand a sliver.
    if next > 0.0 && pr >= next && remaining > 12 {
        let k = (pr / next).floor();
        let rem = pr - k * next;
        if k >= 1.0 && rem < 3.0 {
            score -= (3.0 - rem) * 4.0 * (0.5 + progress * 0.5);
        }
        // NEW: penalize residuals that are just barely too small for one more
        // next-item (dead-space magnet), scaled by stream length.
        let miss = next - rem;
        if rem > 0.0 && miss < 6.0 {
            score += (6.0 - miss) * 3.5 * (0.6 + progress * 0.4);
        }
    }

    // NEW: strengthen late-stream exact-closure pressure — as the stream ends,
    // prefer bins that will finish with near-zero residual.
    if remaining < 40 && pr > 0.0 && next > 0.0 && pr >= next {
        let after = pr - next;
        if after < 4.0 {
            score -= (4.0 - after) * 6.0 * (1.0 - remaining as f64 / 40.0);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 + progress) + norm_pr * (1.0 - progress) * 0.5;
    score += poly * cap * 0.6;

    // Perfect fit reward (smooth, no hard threshold)
    let perfect = (post_residual == 0) as i32 as f64;
    score -= perfect * 25.0 * (1.0 + progress);

    // Lookahead: penalize residual that cannot fit the next item (smooth quadratic gap)
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).max(0) as f64;
        let unusable = gap / cap;
        score += unusable * unusable * cap * 0.8;
        // Reward residual that exactly accommodates next item
        let next_fit = (post_residual == next_item_size) as i32 as f64;
        score -= next_fit * 10.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 * (1.0 + progress);
    }

    // New-bin candidate: make it less attractive as stream progresses unless residuals are tight
    if bin_residual == bin_capacity {
        let tightness = 1.0 - (mean_residual / cap).min(1.0);
        score += 20.0 * (0.5 + progress) * (0.5 + tightness);
    }

    // Mild penalty scaled by how far above mean residual this bin sits
    let dev = (pr - mean_residual) / cap;
    score += dev * dev * cap * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: divide capacity into 5 classes.
    let cap_f = bin_capacity as f64;
    let class = (post_residual * 5) / bin_capacity; // 0..4 integer class
    // Penalize larger classes nonlinearly (harmonic weighting).
    score += (class as f64) * (class as f64) * 3.0;

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Tiny dead space reward (residual below smallest item class).
    if post_residual < 10 && post_residual > 0 {
        score -= 50.0;
    }

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0;
        } else if next_item_size < post_residual {
            // Reward proportionally, more when the leftover after next item is small.
            let after_next = post_residual - next_item_size;
            let nclass = (after_next * 5) / bin_capacity;
            score -= 120.0 - (nclass as f64) * 25.0;
        } else {
            // Next item won't fit here: penalize if this bin would be left with awkward residue.
            score += 30.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: make it moderately attractive only when open bins are quite full
    // or the item fits poorly everywhere.
    if bin_residual == bin_capacity {
        let tight = mean_residual / cap_f;
        // New bins are cheap early / when residuals are low; expensive when many bins open.
        score = 60.0 + 50.0 * tight - (open_bins_count as f64).sqrt() * 2.0;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 10.0;
        }
    }

    // Coupling with mean residual: prefer bins below mean residual (tighter bins).
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Stream progression: late in the stream, consolidate harder.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 20.0 * (1.0 - post_residual as f64 / cap_f);

    // Harmonic modulo bonus: post_residual divisible by common item sizes (10/20/25/50)
    // is more reusable.
    if post_residual > 0 {
        if post_residual % 50 == 0 {
            score -= 40.0;
        } else if post_residual % 25 == 0 {
            score -= 25.0;
        } else if post_residual % 10 == 0 {
            score -= 15.0;
        } else if post_residual % 20 == 0 {
            score -= 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // later (below the minimum plausible item size) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual > 0 && post_residual < 20 {
        score += 25.0;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 100.0;
    }

    // Reward tight fits: fraction of bin used by this placement.
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 30.0 * tightness;

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly into the post residual,
    // reward this placement strongly.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 50.0;
    } else if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 10 {
        // Next item leaves dead space: mild penalty.
        score += 10.0;
    }

    // Open bins pressure: with many open bins, discourage spreading by
    // penalizing new bins and mildly favoring filling existing ones.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses / bins accumulate.
        score += 15.0 + 30.0 * progress + 2.0 * open_bins_count as f64;
        // But if no open bin can fit (this is the only "fitting" call),
        // the base penalty is offset by the last-chance logic above not applying.
    } else {
        score -= 1.5 * open_bins_count as f64;
    }

    // Prefer bins with residuals below the mean (consolidating fuller bins).
    score += 0.3 * (bin_residual as f64 - mean_residual).max(0.0);

    // Prefer placing into the emptiest suitable bin when many bins are open,
    // to consolidate small residuals into fewer bins.
    if open_bins_count > 3 && bin_residual >= item_size {
        score -= 0.2 * (bin_capacity - bin_residual) as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact / near-exact fit reward
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 3 {
        score -= 50.0 * (4.0 - post_residual as f64);
    }

    // 2-step lookahead: reward bins whose leftover can host the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 0.6 * (next_item_size as f64) - 0.3 * slack;
            if slack == 0.0 {
                score -= 40.0; // perfect chain fit
            }
        } else {
            // dead space relative to next item: penalize unusable remainder
            score += 0.8 * (post_residual as f64 - next_item_size as f64).abs().min(post_residual as f64);
            if post_residual < 10 {
                score += 30.0; // tiny useless sliver
            }
        }
    }

    // Relative to mean residual: prefer tighter-than-average bins
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when nothing fits well
    if bin_residual == bin_capacity {
        let scarcity = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        score += 80.0 - 90.0 * scarcity
            + 0.2 * open_bins_count as f64
            + 0.3 * (post_residual as f64 - next_item_size as f64);
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
    }

    // Late in stream: consolidate, avoid opening bins
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual != bin_capacity {
        score -= 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let next = next_item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items.max(1) as f64 } else { 0.0 };
    let post_norm = pr / cap;
    let fit_ratio = item_size as f64 / cap;
    let gap = (bin_residual - item_size) as f64 / cap;
    let mut score = post_norm * post_norm * 56.5 + post_norm * 21.8;

    // ---- Aggressive 2-step lookahead: shape score around the NEXT item ----
    if next > 0.0 {
        if pr == next {
            score -= 45.0;
        } else if pr > next {
            let slack = pr - next;
            let diff = slack / cap;
            score -= 20.0 * (1.0 - diff).max(0.0);
            score -= (-diff * diff * 458.0).exp() * 20.2 * (1.0 - progress * 0.5);
            if diff < 0.04 {
                score -= (0.04 - diff) * 26.0 * (0.6 + progress * 0.6);
            } else if diff > 0.16 {
                score += (diff - 0.16) * 8.0 * (0.5 + progress);
            }
        } else if pr > 0.0 {
            score += (next - pr) / cap * 30.5 * (1.0 - progress);
        }
    }

    // ---- Dead-floor guard (borrowed from best): tiny residuals below next item strand ----
    if post_residual > 0 {
        let dead_floor = if next_item_size > 0 { (next_item_size.min(12) as f64).max(6.0) } else { 10.0 };
        if pr < dead_floor && pr != next {
            score += 62.0 * (1.0 - progress * 0.3);
        } else if post_residual < 20 && pr != next {
            score += 25.0;
        }
    }

    // ---- Relative-to-mean coupling: favor tighter-than-average bins ----
    if pr > 0.0 {
        let waste = post_norm - mean_residual / cap;
        if waste > 0.0 {
            score += waste * 30.0 * (0.4 + progress * 0.6);
        } else {
            score -= (-waste) * 10.0;
        }
    }

    // ---- New-bin candidate decision ----
    if bin_residual == bin_capacity {
        let others = if fitting_bins_count > 0 { fitting_bins_count - 1 } else { 0 };
        let size_pull = fit_ratio * 14.0;
        if fitting_bins_count <= 2 && gap > 0.0 {
            score -= (18.0 + size_pull) * (1.0 - progress * 0.6);
        } else if others == 0 {
            score -= 5.0;
        } else {
            score += 8.0 + 6.0 * (1.0 - progress) + open_bins_count as f64 * 0.3;
        }
        if next > 0.0 && fitting_bins_count <= 3 && item_size as f64 >= next * 0.95 {
            score -= 5.5 * (1.0 - progress * 0.5);
        }
        if next > 0.0 && item_size as f64 + next > cap {
            score += 8.0 * (1.0 - progress * 0.4);
        }
        if next > 0.0 && item_size as f64 + next <= cap && fit_ratio > 0.35 {
            score -= 3.0 * (1.0 - progress);
        }
    }

    // Exact / near-exact fit bonuses.
    if pr == 0.0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 42.0;
    } else if post_norm < 0.05 {
        score -= 10.2 * (1.0 - post_norm / 0.05);
    }

    // Sharp bonus for leaving a tiny gap (<12% of capacity).
    if gap > 0.0 && gap < 0.12 {
        score -= (0.12 - gap) * 48.0;
    } else if gap >= 0.12 && gap < 0.22 && next > 0.0 && pr > 0.0 && pr < next {
        score += (gap - 0.10) * 90.5 * (0.5 + progress);
    }
    if gap >= 0.22 && gap < 0.35 && progress > 0.55 {
        score += (gap - 0.22) * 45.5 * (progress - 0.55) * 2.0;
    }
    // Next-item chain: leftover after next item nearly closes bin.
    if next > 0.0 && gap > 0.12 {
        let nxt_gap = ((gap * cap - next).max(0.0)) / cap;
        if nxt_gap < 0.06 {
            score -= 9.0 * (1.0 - nxt_gap / 0.06) * (0.5 + progress);
        }
    }

    // Reward large items filling bins deeply.
    score -= fit_ratio * fit_ratio * 6.0;

    // Congestion: when many bins compete for this item, penalize sloppy fits.
    if fitting_bins_count > 2 {
        score += gap * 6.5 * ((fitting_bins_count.min(12) as f64 - 2.0) / 10.0);
    }
    if open_bins_count > 8 {
        score += post_norm * 5.0 * ((open_bins_count.min(20) as f64 - 8.0) / 12.0);
    }

    // Late-stream consolidation.
    if progress > 0.7 && post_norm > 0.25 {
        score += (post_norm - 0.25) * 6.0 * (progress - 0.7) / 0.3;
    }

    // Last-chance bonus: prefer a bin that would otherwise be wasted.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 - fit_ratio);
    }

    // Deep fill bonus relative to actual residual.
    let fill_r = item_size as f64 / bin_residual.max(1) as f64;
    if fill_r > 0.90 && bin_residual != bin_capacity {
        score -= (fill_r - 0.90) * 18.0 * (0.6 + progress * 0.5);
    }

    // Dead-space guard after next item.
    if next > 0.0 && pr > 0.0 {
        let after_next = (pr - next).max(0.0);
        let dead = after_next / cap;
        if dead > 0.0 && dead < 0.08 {
            let reusable = if after_next >= next { 1.0 } else { 0.0 };
            score += (0.08 - dead) * 16.0 * (1.0 - reusable * 0.5) * (0.5 + progress);
        }
    }

    // Mid-residual band penalty when next item cannot fit.
    if pr > 0.0 && post_norm >= 0.10 && post_norm < 0.20 && next > 0.0 && next > pr {
        score += (next - pr) / cap * 26.0 * (0.4 + progress * 0.8);
    }

    // Half-consumed bins late in the stream.
    if pr > 0.0 && pr < item_size as f64 * 0.5 && progress > 0.3 {
        score += 4.0 * (1.0 - progress);
    }

    // Multi-item chain: residual divisible by next item is valuable.
    if next > 0.0 && post_residual > 0 && post_residual >= next_item_size {
        let frac = ((pr - next) % next.max(1.0)) / next.max(1.0);
        if frac < 0.08 {
            score -= 10.0 * (1.0 - progress * 0.5);
        }
        let chain = ((post_residual / next_item_size.max(1)) as f64) * next / cap;
        if chain > 0.5 {
            score -= (chain - 0.5) * 14.0 * (0.5 + progress * 0.5);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual near 0 is best.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 8.0 * tightness * tightness;

    // Penalize dead space that no plausible future item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable sliver
    }

    // Lookahead: if next item fits perfectly into post_residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = post_residual - next_item_size;
        if gap <= 5 {
            score -= 20.0;
        } else {
            score -= 6.0 * (1.0 - (gap as f64) / 40.0);
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        // next item cannot use leftover: penalize proportionally
        score += 4.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Global pressure: many open bins with high mean residual -> favor consolidation.
    let pressure = mean_residual / (bin_capacity as f64);
    if bin_residual < bin_capacity {
        score -= 5.0 * pressure * (open_bins_count as f64).ln().max(1.0);
    }

    // New-bin candidate handling: opening a new bin is only attractive when no
    // open bin fits well (post_residual here would be capacity - item_size).
    if bin_residual == bin_capacity {
        let waste_vs_mean = (bin_capacity as f64) - mean_residual;
        // penalize new bin more as stream progresses (less time to amortize)
        let horizon = step_index as f64 / (total_items.max(1) as f64);
        score += 30.0 + 40.0 * horizon + 0.3 * waste_vs_mean.max(0.0);
        // but if next item is huge and would be stranded, soften slightly
        if next_item_size > 70 {
            score -= 10.0;
        }
    }

    // Mild time-varying exploration term to break ties diversely.
    let phase = ((step_index as f64) * 0.37).sin();
    score += 1.5 * phase;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Non-linear penalty for large dead space: cubic in normalized post-residual
    let norm_pr = pr / cap;
    score += 40.0 * norm_pr * norm_pr * norm_pr;

    // Smooth coupling: penalty grows as stream progresses (waste hurts more later)
    score += 30.0 * norm_pr * norm_pr * progress;

    // Reward tight fits more strongly as stream advances (interaction term)
    score -= 25.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (0.5 + progress);

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0 + 40.0 * (1.0 - norm_pr);
    }

    // Penalize spreading across many open bins mildly; encourage consolidation
    score += 2.0 * open_bins_count as f64 * norm_pr;

    // Lookahead: if next item fits exactly into post_residual, reward heavily (smooth bump)
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            let gap = (pr - nx) / cap;
            score -= 35.0 * (1.0 - gap) * (1.0 - gap);
        } else {
            let gap = (nx - pr) / cap;
            score += 15.0 * gap * gap;
        }
    }

    // Prefer bins below mean residual slightly (use emptier space first, smooth coupling)
    score += 0.5 * (mean_residual - pr) * (1.0 + progress);

    // New-bin candidate: keep it attractive only early or when no good fit exists
    if bin_residual == bin_capacity {
        score += 45.0 - 30.0 * progress;
        if fitting_bins_count > 1 {
            score += 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
