pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // tiny dead space = wasted capacity
    } else if post_residual < 20 {
        score += 12.0;
    } else if post_residual == 0 {
        score -= 30.0; // perfect fit strongly rewarded
    }

    // Prefer bins whose residual matches the item size closely (tight fit).
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += tightness * 0.3;

    // Pressure from number of open bins: discourage opening extra bins when many are open.
    score += open_bins_count as f64 * 0.8;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item fits into post_residual, reward this placement.
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 10.0;
    } else if next_item_size > 0 && post_residual > 0 && (post_residual as u32) < next_item_size {
        score += 8.0; // blocking the next item is bad
    }

    // New-bin candidate: make it moderately attractive only when few bins are open
    // or the fit elsewhere would be poor.
    if bin_residual == bin_capacity {
        score -= 5.0;
        score += mean_residual * 0.1; // if open bins have lots of room, new bin less needed
    }

    // Slight progression bias: later in the stream, prefer consolidating into open bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * 0.2 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly favor bins where the next item exactly fills the post-residual (perfect 2-chain).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // next item fits too: reward tighter residual after the chain
            let chain_left = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - chain_left / bin_capacity as f64);
            score += 0.15 * chain_left;
        } else {
            // next item cannot follow: penalize proportionally to overshoot
            let over = (next_item_size - post_residual) as f64;
            score += 0.10 * over.min(40.0);
        }
    } else {
        // last item: prefer minimal final residual
        score += 0.5 * post_residual as f64;
    }

    // Compare post_residual against mean residual: creating large residuals above mean is wasteful.
    score += 0.30 * (post_residual as f64 - mean_residual).max(0.0);
    // Slight reward for landing below mean residual (tightening the fleet).
    score -= 0.10 * (mean_residual - post_residual as f64).max(0.0);

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin unless fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0 + 0.2 * item_size as f64;
    }

    // New-bin candidate: only attractive when current fit leaves big dead space or no real fit exists.
    if bin_residual == bin_capacity {
        let waste = post_residual as f64;
        if fitting_bins_count == 0 {
            score -= 100.0;
        } else if waste > 45.0 {
            score -= 10.0 + 0.2 * waste;
        } else {
            score += 30.0;
        }
    }

    // Late-stream tightening: as stream progresses, prioritize exactness more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 8.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Mild penalty when many bins are open: discourage spreading residual fragmentation.
    score += 0.05 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
