        score += (open_bins_count as f64).ln().max(0.0) * (3.0 + 2.0 * progress);
        // Very tiny post-residual in a crowded field: reward absorbing it.
        if post_residual > 0 && post_norm < 0.02 && fitting_bins_count >= 4 {
            score -= 6.0 * (1.0 - progress);
