    // New-bin candidate logic.
    if bin_residual == bin_capacity {
        let size_pull = (item_size as f64 / cap) * 14.0;
        if fitting_bins_count <= 2 {
            score -= (18.0 + size_pull) * (1.0 - progress * 0.6);
        } else {
            score += 20.0 + open_bins_count as f64 * (0.5 + 0.5 * progress);
        }
        if next_item_size > 0 && fitting_bins_count <= 3 && (item_size as f64) >= next_item_size as f64 * 0.95 {
            score -= 5.5 * (1.0 - progress * 0.5);
        }
        if next_item_size > 0 && fitting_bins_count >= 1 {
            let nxt = next_item_size as f64;
            if (item_size as f64) + nxt > cap {
                score += 8.0 * (1.0 - progress * 0.4);
            }
        }
        if (item_size as f64) > cap * 0.5 && progress < 0.5 {
            score -= 6.0 * (1.0 - progress);
        }
        if progress > 0.85 && (item_size as f64) / cap > 0.6 {
            score -= 4.0 * (progress - 0.85) * 20.0;
        }
        if next_item_size > 0 && (item_size as f64) + (next_item_size as f64) <= cap && (item_size as f64) / cap > 0.35 {
            score -= 3.0 * (1.0 - progress);
        }
        // Chain-fit bonus: post_residual divisible by next item.
        if next_item_size > 0 && post_residual > 0 {
            let nxt = next_item_size as f64;
            let second_slack = (pr - nxt) / cap;
            if second_slack >= 0.0 && second_slack < 0.05 {
                score -= (0.05 - second_slack) * 40.0 * (0.5 + progress * 0.5);
            }
        }
    }

    // Tiny residual with many fitting bins: keep it tight anyway.
    if post_residual > 0 && post_norm < 0.02 && fitting_bins_count >= 4 {
        score -= 6.0 * (1.0 - progress);
    }

    // Modular chain reward: post_residual holds k copies of next item.
    if next_item_size > 0 && post_residual > 0 && (post_residual as u32) >= next_item_size {
        let chain = ((post_residual / next_item_size.max(1)) as f64) * (next_item_size as f64) / cap;
        if chain > 0.5 {
            score -= (chain - 0.5) * 14.0 * (0.5 + progress * 0.5);
        }
    }

    // Two-copy lookahead: room for next item plus a small second gap.
    if next_item_size > 0 && post_residual > 0 && (post_residual as f64) >= (next_item_size as f64) * 2.0 && (post_residual as f64) < (next_item_size as f64) * 2.0 + 8.0 {
        score -= 8.0 * (1.0 - progress * 0.4);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits. Squared penalty on wasted space.
    score += (post_residual as f64 / bin_capacity as f64).powi(2) * 30.0;

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual < 10 {
        score -= 20.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead (k=2): reward if the next item fits exactly or well in the post-residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            score -= 15.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Next item cannot fit here; slight penalty for leaving medium dead space.
            if post_residual > 0 && post_residual < next_item_size {
                score += 5.0;
            }
        }
    }

    // Global state: when many bins are open, prefer consolidation into existing bins
    // (penalize new-bin candidates and loose fits).
    let openness = (open_bins_count as f64) / (open_bins_count as f64 + 5.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: attractive early or when fits are bad, costly later.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 25.0 * openness - 15.0 * (1.0 - progress);
        // If this bin is a new bin and no open bin is a great fit, encourage opening.
        if post_residual as f64 > mean_residual {
            score -= 10.0;
        }
    } else {
        // Existing bin: reward placing into bins with residuals close to the item (good density).
        let density = item_size as f64 / bin_residual.max(1) as f64;
        score -= density * 20.0 * openness;
    }

    // Mean-residual coupling: if this bin's residual is far below mean, it's a laggard bin —
    // prefer filling it to close it out.
    let resid_f = bin_residual as f64;
    if resid_f < mean_residual {
        score -= 8.0 * (mean_residual - resid_f) / bin_capacity as f64;
    } else {
        score += 4.0 * (resid_f - mean_residual) / bin_capacity as f64;
    }

    // Time horizon: late in the stream, be conservative — avoid creating small dead zones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * (post_residual as f64 / bin_capacity as f64) * 25.0;

    // Mild preference for bins that keep residuals out of the "awkward" 1..=9 range.
    if post_residual >= 1 && post_residual <= 9 {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
    score
