pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;

    // Base: prefer small post residual (tight packing), with non-linear sharpening
    let mut score = post * (1.0 + 0.5 * post / cap);

    // Reward high fill ratio quadratically (tight fits strongly favored)
    score -= 30.0 * fit_ratio * fit_ratio;

    // Non-linear coupling of post_residual with stream progress:
    // early on tolerate slack; late in stream penalize dead space more
    let slack_penalty = (post / cap).powi(3) * (20.0 + 60.0 * progress * progress);
    score += slack_penalty;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead: if next item fits exactly into post residual, reward heavily
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let gap = post - nxt;
            score -= 15.0 * (1.0 - gap / cap);
        } else {
            // next item won't fit here; slight penalty for leaving awkward residue
            score += 5.0 * (1.0 - post / cap);
        }
    }

    // New-bin candidate: neutral-ish score so it wins only over genuinely bad fits
    if bin_residual == bin_capacity {
        score = cap * 0.6 + 10.0 * (1.0 - progress);
        if fitting_bins_count == 1 {
            score += 30.0; // avoid opening new bin when an existing bin is last chance
        }
    }

    // Mild coupling with mean residual: prefer bins far below mean residual
    // (keeps larger residuals distributed for future items)
    score += 0.05 * (mean_residual - post).abs() * (1.0 - progress);

    // Small penalty for many open bins (encourages consolidation early)
    score += 0.2 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let post_norm = pr / cap;
    let mut score = post_norm * post_norm * 50.0 + post_norm * 20.0;

    // Dead-space avoidance: small unusable gaps heavily penalized, scaled by progress.
    let dead_floor = if next_item_size > 0 { (next_item_size.min(12) as f64).max(6.0) } else { 10.0 };
    if post_residual > 0 && (post_residual as f64) < dead_floor {
        score += 62.0 * (1.0 - progress * 0.3);
    } else if post_residual < 20 {
        score += 25.0;
    }

    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 42.0;
    } else if post_residual <= 9 {
        score -= 18.0 * (1.0 - progress * 0.4);
    }

    // Lookahead: reward if next item fits in post_residual, with exponential slack bonus.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64 / cap;
        score -= (-slack * slack * 450.0).exp() * 24.0 * (1.0 - progress * 0.5);
    }

    // Tight gap reward.
    let gap = (bin_residual - item_size) as f64 / cap;
    if gap > 0.0 && gap < 0.12 {
        score -= (0.12 - gap) * 48.0;
    } else if gap >= 0.12 && gap < 0.22 && fitting_bins_count <= 3 {
        score += (gap - 0.12) * 18.0 * (0.5 + progress * 0.5);
    }

    // Dead space w.r.t. lookahead item.
    if next_item_size > 0 && pr > 0.0 && (pr as u32) < next_item_size && post_norm > 0.03 {
        let dead_ratio = (next_item_size as f64 - pr) / cap;
        score += dead_ratio * 90.0 * (0.6 + progress * 0.6);
    }

    // Mean-residual waste comparison.
    if post_residual > 0 && mean_residual > 0.0 {
        let waste = post_norm - (mean_residual / cap);
        if waste > 0.0 {
            score += waste * 30.0 * (0.4 + progress * 0.6);
        } else {
            score -= (-waste) * 10.0;
        }
    }

    // Last-chance bin bonus.
    if fitting_bins_count == 1 && gap > 0.0 && gap < 0.06 {
        score -= 7.0 * (1.0 - progress * 0.5);
    }

    // New-bin candidate logic: open new bins when fit is poor or few alternatives exist.
    if bin_residual == bin_capacity {
        let size_pull = (item_size as f64 / cap) * 14.0;
        if fitting_bins_count <= 2 {
            score -= (18.0 + size_pull) * (1.0 - progress * 0.6);
        } else {
            score += 20.0 + open_bins_count as f64 * (0.5 + 0.5 * progress);
        }
        if next_item_size > 0 && fitting_bins_count <= 3 && (item_size as f64) >= next_item_size as f64 * 0.95 {
            score -= 5.5 * (1.0 - progress * 0.5);
        }
        if next_item_size > 0 && (item_size as f64) + (next_item_size as f64) > cap {
            score += 8.0 * (1.0 - progress * 0.4);
        }
        if (item_size as f64) > cap * 0.5 && progress < 0.5 {
            score -= 6.0 * (1.0 - progress);
        }
        if progress > 0.85 && (item_size as f64) / cap > 0.6 {
            score -= 4.0 * (progress - 0.85) * 20.0;
        }
        if next_item_size > 0 && (item_size as f64) + (next_item_size as f64) <= cap && (item_size as f64) / cap > 0.35 {
            score -= 3.0 * (1.0 - progress);
        }
    }

    // Second-fit slack: near-perfect slot for the next item after this one.
    if next_item_size > 0 && post_residual > 0 {
        let nxt = next_item_size as f64;
        let second_slack = (pr - nxt) / cap;
        if second_slack >= 0.0 && second_slack < 0.05 {
            score -= (0.05 - second_slack) * 40.0 * (0.5 + progress * 0.5);
        }
        if (pr as u32) >= next_item_size {
            let frac = ((pr - nxt) % nxt.max(1.0)) / nxt.max(1.0);
            if frac < 0.08 {
                score -= 10.0 * (1.0 - progress * 0.5);
            }
            let two_fit = (pr - nxt) / cap;
            if two_fit < 0.02 && fitting_bins_count <= 2 {
                score -= 9.0 * (1.0 - progress * 0.4);
            }
            let chain = ((post_residual / next_item_size.max(1)) as f64) * nxt / cap;
            if chain > 0.5 {
                score -= (chain - 0.5) * 14.0 * (0.5 + progress * 0.5);
            }
        }
    }

    // Tiny post-residual reward: nearly-full bins are attractive.
    if post_residual > 0 && post_norm < 0.04 {
        score -= (0.04 - post_norm) * 55.0 * (0.7 + progress * 0.3);
    }

    // Double next-item slot bonus.
    if post_residual > 0 && next_item_size > 0
        && (post_residual as f64) >= (next_item_size as f64) * 2.0
        && (post_residual as f64) < (next_item_size as f64) * 2.0 + 8.0 {
        score -= 8.0 * (1.0 - progress * 0.4);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: bins whose leftover falls into
    // "reusable" classes (multiples of common small item sizes) are favored.
    let pr = post_residual;
    if pr > 0 {
        let mut reusable = 0.0f64;
        for m in [10u32, 20, 25, 50] {
            if pr % m == 0 {
                reusable += 8.0;
            }
        }
        if pr <= 10 {
            reusable -= 6.0; // tiny dead space class
        }
        score -= reusable;
    }

    // Perfect fit: huge reward.
    if pr == 0 {
        score -= 1000.0;
    }

    // Penalize wasting a large residual on a small item (bad fill ratio).
    let fill = item_size as f64 / bin_residual as f64;
    score += (1.0 - fill) * 30.0;

    // Lookahead: if the next item fits exactly in the post-residual,
    // strongly favor this bin (chain fit).
    if next_item_size > 0 && pr >= next_item_size {
        if pr == next_item_size {
            score -= 60.0;
        } else {
            score -= 15.0;
        }
    } else if next_item_size > 0 && pr > 0 && pr < next_item_size {
        // leftover too small for the next item: dead-space penalty scaled by class
        score += (next_item_size - pr) as f64 * 0.8;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate logic: only attractive when no good open option exists.
    let is_new_bin = bin_residual == bin_capacity && bin_capacity > 0;
    if is_new_bin {
        // Base penalty so open bins usually win; relax as stream progresses
        // and when many bins are open with large mean residual (fragmentation).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let mut new_penalty = 55.0 - 25.0 * progress;
        if open_bins_count > 0 && mean_residual > 0.5 * cap {
            new_penalty -= 20.0; // open bins are fragmented; fresh bin fine
        }
        if next_item_size > 0 && item_size as f64 > 0.9 * cap {
            new_penalty -= 30.0; // huge item: keep big residual bins free
        }
        score += new_penalty.max(0.0);
        // Empty-bin residual is cap: normalize so it doesn't dominate via base term
        score -= (post_residual as f64 - cap) * 0.5;
    }

    // Mild pressure toward tighter bins as stream progresses.
    score += progress_frac(step_index, total_items) * (bin_residual as f64 / cap) * 5.0;

    score
}

#[inline]
fn progress_frac(step_index: usize, total_items: usize) -> f64 {
    if total_items == 0 { 0.0 } else { step_index as f64 / total_items as f64 }
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
