pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that can never fit the minimum
    // item (1..=100 unknown, assume small gaps < 10 are dead) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Perfect fit: strongly reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Tight fit bonus: item fills most of the bin's remaining space.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fill_ratio;

    // Penalize leaving a gap that exactly blocks the next item but wastes space.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // next item won't fit here; residual likely dead
        score += 8.0 * (1.0 - post_residual as f64 / next_item_size as f64);
    }
    // Reward leaving room for the lookahead item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0;
    }

    // Last-chance bin: if this is the only fitting bin, prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: discourage spreading across many bins when residuals
    // are already large; encourage consolidation.
    if bin_residual < bin_capacity {
        score += 0.15 * open_bins_count as f64;
        // Prefer bins with below-mean residual (denser bins).
        score += 0.3 * (mean_residual - bin_residual as f64);
    } else {
        // New-bin candidate: penalize mildly so it's chosen only when
        // all open bins are poor fits, but less when bins are crowded.
        score += 20.0 - 0.05 * open_bins_count as f64;
    }

    // Late in stream: tighten up, avoid opening new bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual < bin_capacity {
        score -= 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits (small post_residual relative to capacity)
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - fit_ratio) * 40.0;

    // Exact-fit bonus
    if post_residual == 0 {
        score -= 100.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches next_item_size
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= (1.0 - gap / bin_capacity as f64).max(0.0) * 30.0;
        // Perfect lookahead match
        if post_residual == next_item_size {
            score -= 25.0;
        }
        // Penalize leaving dead space smaller than the smallest plausible next item
        if post_residual > 0 && post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Compare against mean residual: prefer bins with residuals close to mean (balanced use)
    score += (bin_residual as f64 - mean_residual).abs() * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Penalize opening new bins as stream progresses
    if bin_residual == bin_capacity {
        score += 10.0 + 20.0 * (step_index as f64 / total_items.max(1) as f64);
    }

    // Slight preference for fuller bins when many bins are open
    score -= (bin_residual as f64 / bin_capacity as f64) * open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = bin_residual == bin_capacity;

    // Reward tight fits strongly (waste minimization).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize creating dead space that cannot fit typical future items.
    if post_residual > 0 {
        let dead = if next_item_size > 0 && post_residual < next_item_size { 1.0 } else { 0.0 };
        score += 8.0 * dead * (0.5 + 0.5 * (1.0 - progress));
    }

    // Lookahead coupling: if next item fits exactly in post_residual, reward heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        score -= 10.0 * (1.0 - gap as f64 / bin_capacity as f64);
    } else if next_item_size > 0 {
        score += 3.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 15.0;
    }

    // New-bin candidate: penalize by default, less so late in the stream or when
    // many bins are open (fragmentation) or mean residual is low.
    if is_new_bin {
        let mut open_penalty = 10.0;
        open_penalty -= 6.0 * progress;
        open_penalty += 0.15 * open_bins_count as f64;
        open_penalty += 0.05 * (mean_residual - item_size as f64).abs();
        if fitting_bins_count == 0 {
            open_penalty = -20.0; // no alternative: must open
        }
        // If next item is large and would fit a fresh bin, mildly favor opening.
        if next_item_size > 0 && next_item_size + item_size > bin_capacity {
            open_penalty -= 4.0;
        }
        score += open_penalty;
    }

    // Mild preference for balancing residuals across bins early on.
    score += 0.02 * (post_residual as f64 - mean_residual).abs() * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let next = next_item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items.max(1) as f64 } else { 0.0 };
    let post_norm = pr / cap;
    let fit_ratio = item_size as f64 / cap;
    let gap = (bin_residual - item_size) as f64 / cap;
    let mut score = post_norm * post_norm * 50.0 + post_norm * 20.0;

    // ---- 2-step lookahead: shape score around the NEXT item ----
    if next > 0.0 {
        if pr == next {
            score -= 54.0;
        } else if pr > next {
            let slack = pr - next;
            let diff = slack / cap;
            score -= 20.0 * (1.0 - diff).max(0.0);
            score -= (-diff * diff * 450.0).exp() * 24.0 * (1.0 - progress * 0.5);
            if diff < 0.04 {
                score -= (0.04 - diff) * 30.0 * (0.6 + progress * 0.6);
            } else if diff > 0.16 {
                score += (diff - 0.16) * 8.0 * (0.5 + progress);
            }
            // COMBINED: fine-grained residual fitting with lookahead anticipation —
            // reward when the post-residual after next item stays hostable by
            // typical small items (coupled to mean residual scale).
            let after_next = pr - next;
            let typical = mean_residual.max(1.0).min(cap * 0.25);
            if after_next > 0.0 && after_next < typical * 0.35 {
                score -= (typical * 0.35 - after_next) / cap * 22.0 * (0.5 + progress * 0.5);
            }
            // MUTATION: anticipate a second small item after next; reward when
            // the chain (item, next, next) exactly or near-exactly closes.
            if after_next >= next {
                let twice = after_next - next;
                let chain_norm = twice / cap;
                if chain_norm < 0.015 {
                    score -= (0.015 - chain_norm) * 36.0 * (0.5 + progress * 0.5);
                } else if twice < next {
                    score += (next - twice) / cap * 12.0 * (0.4 + progress * 0.6);
                }
            }
        } else if pr > 0.0 {
            let dead_ratio = (next - pr) / cap;
            score += dead_ratio * 90.0 * (0.6 + progress * 0.6);
        }
    }

    // ---- Absolute dead-floor guard: tiny stranded remainders ----
    let dead_floor = if next_item_size > 0 { (next_item_size.min(12) as f64).max(6.0) } else { 10.0 };
    if post_residual > 0 && pr < dead_floor && pr != next {
        score += 62.0 * (1.0 - progress * 0.3);
    } else if post_residual > 0 && post_residual < 20 && pr != next {
        score += 25.0;
    }

    // ---- Relative-to-mean coupling ----
    if pr > 0.0 {
        let dev = (mean_residual - pr) / cap;
        if dev > 0.06 {
            score += (dev - 0.06) * 10.0 * (0.4 + progress);
        } else if dev < -0.10 {
            score += (-dev - 0.10) * 5.0 * (1.0 - progress);
        }
    }

    // ---- New-bin candidate decision ----
    if bin_residual == bin_capacity {
        let others = if fitting_bins_count > 0 { fitting_bins_count - 1 } else { 0 };
        let size_pull = fit_ratio * 14.0;
        if fitting_bins_count <= 2 && gap > 0.0 {
            score -= (18.0 + size_pull) * (1.0 - progress * 0.6);
        } else if others == 0 {
            score -= 5.0;
        } else {
            score += 20.0 + open_bins_count as f64 * (0.5 + 0.5 * progress);
        }
        if next > 0.0 && fitting_bins_count <= 3 && fit_ratio >= next * 0.95 / cap {
            score -= 5.5 * (1.0 - progress * 0.5);
        }
        if next > 0.0 && fitting_bins_count >= 1 && fit_ratio * cap + next > cap {
            score += 8.0 * (1.0 - progress * 0.4);
        }
        if next > 0.0 && fit_ratio * cap + next <= cap {
            let pair_left = (cap - fit_ratio * cap - next) / cap;
            if pair_left < 0.05 {
                score -= (0.05 - pair_left) * 42.0 * (0.5 + progress * 0.5);
            } else if fit_ratio > 0.35 {
                score -= 3.0 * (1.0 - progress);
            }
        }
        if fit_ratio > 0.5 && progress < 0.5 {
            score -= 6.0 * (1.0 - progress);
        }
        if progress > 0.85 && fit_ratio > 0.6 {
            score -= 4.0 * (progress - 0.85) * 20.0;
        }
        if next > 0.0 && fit_ratio * cap + next > cap * 0.94 && fitting_bins_count > 2 {
            score -= 6.0 * (1.0 - progress * 0.5);
        }
        if progress > 0.6 && fit_ratio < 0.45 && others > 0 {
            score += 10.0 * (progress - 0.6) / 0.4;
        }
        if next > 0.0 && others > 0 {
            let fresh_left = cap - fit_ratio * cap;
            if fresh_left >= next {
                let fresh_slack = (fresh_left - next) / cap;
                if fresh_slack < 0.03 {
                    score -= (0.03 - fresh_slack) * 26.0 * (0.5 + progress * 0.5);
                }
            }
        }
        // COMBINED: only open a fresh bin when the residual chain (item, next,
        // and a third typical item) nearly fills capacity; otherwise resist.
        if next > 0.0 && others > 1 {
            let fresh_left = cap - fit_ratio * cap;
            if fresh_left >= next {
                let after = fresh_left - next;
                let typical = mean_residual.max(1.0).min(cap * 0.25);
                if after < typical {
                    score += (typical - after) / cap * 14.0 * (0.5 + progress * 0.5);
                }
            } else {
                score += 6.0 * (0.5 + progress * 0.5);
            }
        }
        // MUTATION: resist opening a fresh bin mid-stream when several open
        // bins already have roomy residuals that could absorb this item.
        if others >= 3 && progress > 0.25 && fit_ratio < 0.5 {
            score += (others.min(10) as f64 - 2.0) * 2.5 * (0.5 + progress * 0.5);
        }
    }

    // Exact / near-exact fit bonuses.
    if pr == 0.0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 42.0;
    } else if post_residual <= 9 {
        score -= 18.0 * (1.0 - progress * 0.4);
    } else if post_norm < 0.02 && fitting_bins_count >= 4 {
        score -= 6.0 * (1.0 - progress);
    }

    // Sharp bonus for leaving a tiny gap (<12% of capacity).
    if gap > 0.0 && gap < 0.12 {
        score -= (0.12 - gap) * 48.0;
    } else if gap >= 0.12 && gap < 0.22 && next > 0.0 && pr > 0.0 && pr < next {
        score += (gap - 0.12) * 90.5 * (0.5 + progress);
    } else if gap >= 0.12 && gap < 0.22 && fitting_bins_count <= 3 {
        score += (gap - 0.12) * 18.0 * (0.5 + progress * 0.5);
    }
    if gap >= 0.22 && gap < 0.30 && fitting_bins_count <= 2 {
        score += (gap - 0.22) * 22.0 * (0.6 + progress * 0.4);
    }
    if next > 0.0 && gap > 0.12 {
        let nxt_gap = ((gap * cap - next).max(0.0)) / cap;
        if nxt_gap < 0.05 {
            score -= (0.05 - nxt_gap) * 40.0 * (0.5 + progress * 0.5);
        }
    }

    // Reward large items filling bins deeply.
    score -= fit_ratio * fit_ratio * 6.0;

    // Congestion: many competing bins => penalize sloppy fits.
    if fitting_bins_count > 2 {
        score += gap * 6.5 * ((fitting_bins_count.min(12) as f64 - 2.0) / 10.0);
    }
    if open_bins_count > 8 {
        score += post_norm * 5.0 * ((open_bins_count.min(20) as f64 - 8.0) / 12.0);
    }

    // Late-stream consolidation.
    if progress > 0.7 && post_norm > 0.25 {
        score += (post_norm - 0.25) * 6.0 * (progress - 0.7) / 0.3;
    }

    // Last-chance bonus.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 - fit_ratio);
    }

    // Deep fill bonus.
    let fill_r = item_size as f64 / bin_residual.max(1) as f64;
    if fill_r > 0.90 && bin_residual != bin_capacity {
        score -= (fill_r - 0.90) * 18.0 * (0.6 + progress * 0.5);
    }

    // Waste-vs-mean term.
    if pr > 0.0 && mean_residual > 0.0 {
        let waste = post_norm - mean_residual / cap;
        if waste > 0.0 {
            score += waste * 30.0 * (0.4 + progress * 0.6);
        } else {
            score -= (-waste) * 10.0;
        }
    }

    // Penalize bins whose post-residual can never host the next item class.
    if pr > 0.0 && next > 0.0 && pr < next && post_norm > 0.03 {
        score += (next - pr) / cap * 20.0 * (0.5 + progress * 0.5);
    }

    // Reward bins that remain exactly reusable by the next item.
    if next > 0.0 && pr > 0.0 && (pr - next) / cap < 0.02 && pr >= next {
        score -= 6.0 * (1.0 - (pr - next) / cap / 0.02) * (0.5 + progress);
    }

    // Periodic divisibility bonus.
    if next > 0.0 && pr > 0.0 && pr >= next {
        let frac = ((pr - next) % next.max(1.0)) / next.max(1.0);
        if frac < 0.08 {
            score -= 10.0 * (1.0 - progress * 0.5);
        }
    }

    // Double-fit bonus.
    if next > 0.0 && pr >= next * 2.0 && pr < next * 2.0 + 8.0 {
        score -= 8.0 * (1.0 - progress * 0.4);
    }

    // Last-chance micro-gap bonus.
    if fitting_bins_count == 1 && gap > 0.0 && gap < 0.06 {
        score -= 7.0 * (1.0 - progress * 0.5);
    }

    // Dead-space penalty when few fitting bins and residual too small for next.
    if next > 0.0 && post_residual > 0 && post_residual < next_item_size && fitting_bins_count <= 2 {
        score += 18.0 * (1.0 - progress * 0.5);
    }

    // Chain-closure.
    if next > 0.0 && pr >= next && fitting_bins_count > 1 {
        let chain = pr - next;
        let chain_ref = mean_residual.max(1.0) * 0.35;
        if chain < chain_ref {
            score -= 5.0 * (1.0 - chain / chain_ref) * (0.5 + progress * 0.5);
        }
    }

    // Mid-band residual vacuum.
    if post_norm > 0.03 && post_norm < 0.10 {
        if next > 0.0 && pr >= next {
            score -= 4.0 * (1.0 - progress * 0.5);
        } else {
            score += 6.0 * (0.5 + progress * 0.5);
        }
    }

    // Fine-grained residual fitting with lookahead.
    if next > 0.0 && pr > 0.0 && pr >= next && fill_r > 0.85 {
        let reuse = (pr - next) / cap;
        if reuse < 0.06 {
            score -= (0.06 - reuse) * 30.0 * (0.5 + progress * 0.5);
        }
    }

    // Discourage residuals in the awkward 0.10–0.18 band.
    if post_norm >= 0.10 && post_norm < 0.18 && next > 0.0 && pr < next {
        score += (0.18 - post_norm) * 14.0 * (0.4 + progress * 0.6);
    }

    // Residual-consolidation with multi-fit lookahead.
    if next > 0.0 && pr >= next {
        let fits_ahead = (pr / next).floor();
        if fits_ahead >= 2.0 {
            let remainder = pr - fits_ahead * next;
            let rem_norm = remainder / cap;
            if rem_norm > 0.005 {
                score += rem_norm * 55.0 * (0.5 + progress * 0.5);
            } else {
                score -= 4.0 * (1.0 - progress * 0.4);
            }
            // COMBINED: reward when the multi-fit chain consumes nearly all
            // residual, tightening mid-size gap exploitation.
            let chain_fill = (fits_ahead * next) / pr;
            if chain_fill > 0.95 {
                score -= (chain_fill - 0.95) * 60.0 * (0.5 + progress * 0.5);
            }
        }
    }

    // Late-stream residual sweep.
    let remaining = if total_items > step_index { total_items - step_index } else { 1 };
    if remaining < 12 && post_residual > 0 {
        score += post_norm * 40.0;
    }

    // COMBINED: two-item lookahead — prefer bins whose post-residual after the
    // next item still fits the mean-residual class with minimal slack, reducing
    // dead space variance across the stream.
    if next > 0.0 && pr >= next && fitting_bins_count > 1 && remaining > 12 {
        let after = pr - next;
        let typical = mean_residual.max(1.0);
        if after >= typical {
            let slack = (after - typical) / cap;
            if slack < 0.02 {
                score -= (0.02 - slack) * 20.0 * (0.6 + progress * 0.4);
            }
        }
    }

    // MUTATION: dead-space variance control — penalize residuals in the
    // awkward band just below the next item size more sharply when many
    // fitting bins exist (we can afford to be picky).
    if next > 0.0 && pr > 0.0 && pr < next && fitting_bins_count >= 3 {
        score += (next - pr) / cap * 14.0 * (0.5 + progress * 0.5);
    }

    // MUTATION: reward closing residual to zero via multi-item chains when
    // the stream is long (compaction pressure).
    if next > 0.0 && pr >= next && remaining > 20 {
        let k = (pr / next).floor();
        let closed = pr - k * next;
        if closed == 0.0 {
            score -= 12.0 * (0.6 + progress * 0.4);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr as f64;
    // Quadratic dead-space penalty, stronger late in the stream
    score += 40.0 * norm_pr * norm_pr * (0.5 + progress);
    // Reward tight fits (small post residual) more as stream progresses
    score -= 30.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * progress;
    // Lookahead coupling: reward residual close to next item size
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        let gap = ((pr - ns) / cap).abs();
        score -= 20.0 * (1.0 - gap) * (1.0 - gap);
        // Penalize residual that cannot fit the next item
        if pr < ns {
            score += 12.0 * (ns - pr) / cap * (0.5 + progress);
        }
    }
    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - norm_pr);
    }
    // Mild pressure to consolidate when many bins are open
    let bins_pressure = open_bins_count as f64 / (open_bins_count as f64 + 10.0);
    score -= 8.0 * bins_pressure * (1.0 - norm_pr);
    // Mean-residual coupling: prefer bins below mean residual (denser bins)
    score += 5.0 * (pr - mean_residual) / cap;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 0.92;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: dead space that is a small
    // multiple of common item sizes is reusable, otherwise it is waste.
    let harmonic_penalty = if post_residual == 0 {
        -60.0 // perfect closure: strongly favored
    } else {
        let mut h = 0.0;
        // post_residual divisible by small harmonic bases => reusable slots
        for base in [10u32, 20, 25, 50] {
            if post_residual % base == 0 {
                h -= 8.0;
            }
        }
        // small unusable remainder is dead space
        if post_residual < 10 {
            h += 25.0;
        }
        h
    };
    score += harmonic_penalty;

    // Tight fit reward: fraction of bin consumed by this item
    let fill_frac = item_size as f64 / bin_capacity as f64;
    score -= 15.0 * fill_frac;

    // Prefer bins whose residual was already fragmented (near mean residual)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // post_residual too small for next item: dead space penalty scaled
            score += 8.0 * (1.0 - (next_item_size - post_residual) as f64 / bin_capacity as f64);
        }
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // this bin's fit is poor (large post_residual) or few bins fit the item.
    if bin_residual == bin_capacity {
        let poor_fit = post_residual as f64 / bin_capacity as f64;
        score += 30.0 - 25.0 * poor_fit;
        if fitting_bins_count == 0 {
            score -= 50.0; // no alternative: new bin mandatory
        }
        if fitting_bins_count == 1 {
            score += 20.0; // an existing bin is the last chance: prefer it
        }
    }

    // Late-stream consolidation: as stream progresses, avoid spreading
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 6.0 * progress * (open_bins_count as f64).ln().max(0.0) * (post_residual as f64 / bin_capacity as f64);

    // Modulo threshold on post_residual classes: multiples of 25 or 50 keep
    // future large items placeable
    if post_residual % 50 == 0 && post_residual > 0 {
        score -= 6.0;
    }
    if post_residual % 25 == 0 && post_residual % 50 != 0 && post_residual > 0 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps after placement.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }
    // Penalize moderately small gaps that are unlikely to fit future items.
    if post_residual >= 10 && post_residual < 20 {
        score += 15.0;
    }

    // Reward tight fits (low post_residual relative to bin capacity).
    score -= (bin_capacity - post_residual) as f64 * 0.3;

    // Open bins pressure: penalize selecting existing bins when many are open,
    // encouraging consolidation; but mild, so we still prefer filling existing bins.
    score += open_bins_count as f64 * 0.05;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, reward strongly.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 40.0;
    }
    // If next item fits into post_residual, mild reward.
    if next_item_size > 0 && next_item_size < post_residual {
        score -= 5.0;
    }
    // If next item cannot fit into post_residual, penalize creating dead space.
    if next_item_size > post_residual && post_residual < next_item_size.min(bin_capacity) {
        score += 8.0;
    }

    // New-bin candidate handling: make the empty bin mildly attractive only when
    // no good fit exists; otherwise keep it unattractive so existing bins are used.
    if bin_residual == bin_capacity {
        score += 10.0;
        // If the item fits poorly anywhere else (large post_residual elsewhere),
        // opening a new bin gives a perfect fit for future items.
        if post_residual == bin_capacity - item_size {
            score -= (bin_capacity - item_size) as f64 * 0.1;
        }
    }

    // Mean residual coupling: if this bin's residual is far above the mean,
    // it's a laggard bin; encourage filling it.
    let residual_f = bin_residual as f64;
    if residual_f > mean_residual + 20.0 {
        score -= 5.0;
    } else if residual_f < mean_residual - 20.0 {
        score += 5.0;
    }

    // Stream progression: late in the stream, be slightly more conservative
    // about opening new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += progress * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post_residual (tight fit).

    // Aggressive 2-step lookahead: reward bins whose post_residual
    // exactly or nearly matches the next item size.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 30.0 * (1.0 - gap / bin_capacity as f64).max(0.0);
        // Perfect lookahead match: strong bonus.
        if post_residual == next_item_size {
            score -= 20.0;
        }
        // If item won't fit after placement, that's fine (bin closes cleanly).
        if post_residual < next_item_size && post_residual > 0 {
            score += 5.0; // small dead space penalty
        }
    }

    // Penalize creating unusable tiny residual relative to mean residual.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Compare against mean residual: prefer bins already below-average
    // residual (denser bins) to keep large-residual bins flexible.
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate (bin_residual == bin_capacity): discourage unless
    // no good fit exists elsewhere.
    if bin_residual == bin_capacity {
        score += 40.0;
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
    }

    // Early in the stream, allow more liberal bin opening.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= progress * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = 0.0;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item fills most of the residual.
    let fit_ratio = if bin_residual > 0 { item_size as f64 / bin_residual as f64 } else { 1.0 };
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize creating dead space that is too small for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: reward bins whose post-residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // post-residual too small for next item: mild dead-space penalty scaled by waste
        score += 4.0 * (next_item_size as f64 - post_residual as f64).min(20.0) / 20.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0 * (1.0 - fit_ratio);
    }

    // New-bin candidate handling: penalize opening a fresh bin when open bins fit well,
    // reward it when the stream is early or open bins are fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 + 20.0 * (1.0 - progress);
        score += 2.0 * open_bins_count as f64;
        if mean_residual < item_size as f64 {
            score -= 10.0; // existing bins are tight; new bin is reasonable
        }
    }

    // Global fragmentation pressure: when mean residual is high, prefer using existing space.
    score -= 0.05 * mean_residual;

    // Mild preference for bins with residuals close to capacity (keep big holes open).
    score += 0.1 * (bin_capacity as f64 - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = 0.0;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual, with non-linear polynomial shaping in progress
    let mut score = pr;

    // Smooth polynomial coupling: early stream prefers small post_residual,
    // late stream tolerates larger residuals (waste less weight)
    let poly = norm_pr * norm_pr * (1.0 - progress) * 40.0
             - norm_pr * progress * 20.0;
    score += poly;

    // Dead-space penalty: residual too small for any plausible item (min size 1)
    let dead = if pr > 0.0 && pr < 10.0 {
        (10.0 - pr) * (10.0 - pr) * 0.8
    } else { 0.0 };
    score += dead;

    // Last-chance bonus: if this is the only fitting bin, strongly favor it
    if fitting_bins_count == 1 {
        score -= 25.0 + 15.0 * progress;
    }

    // Lookahead: reward if next item fits in post residual
    if next_item_size > 0 {
        if (next_item_size as f64) <= pr {
            score -= 12.0 * (1.0 - (next_item_size as f64) / cap);
        } else {
            score += 6.0;
        }
    }

    // Mean residual coupling: penalize bins deviating from mean (smooth quadratic)
    let dev = pr - mean_residual;
    score += 0.05 * dev * dev / (1.0 + progress);

    // Prefer reusing bins over opening new ones when many bins are open
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 30.0 + 5.0 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let next = next_item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items.max(1) as f64 } else { 0.0 };
    let post_norm = pr / cap;
    let fit_ratio = item_size as f64 / cap;
    let gap = (bin_residual - item_size) as f64 / cap;
    let mut score = post_norm * post_norm * 56.5 + post_norm * 21.8;

    // ---- Aggressive 2-step lookahead: shape score around the NEXT item ----
    if next > 0.0 {
        if pr == next {
            score -= 45.0;
        } else if pr > next {
            let slack = pr - next;
            let diff = slack / cap;
            score -= 20.0 * (1.0 - diff).max(0.0);
            score -= (-diff * diff * 458.0).exp() * 20.2 * (1.0 - progress * 0.5);
            if diff < 0.04 {
                score -= (0.04 - diff) * 26.0 * (0.6 + progress * 0.6);
            } else if diff > 0.16 {
                score += (diff - 0.16) * 8.0 * (0.5 + progress);
            }
        } else if pr > 0.0 {
            score += (next - pr) / cap * 30.5 * (1.0 - progress);
        }
    }

    // ---- Borrowed from best: hard dead-floor on small stranded residuals ----
    if post_residual > 0 {
        let dead_floor = if next_item_size > 0 { (next_item_size.min(12) as f64).max(6.0) } else { 10.0 };
        if pr < dead_floor && pr != next {
            score += 62.0 * (1.0 - progress * 0.3);
        } else if post_residual < 20 {
            score += 25.0;
        }
    }

    // Exact / near-exact fit bonuses (strengthened from best heuristic).
    if pr == 0.0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 42.0;
    } else if post_residual <= 9 {
        score -= 18.0 * (1.0 - progress * 0.4);
    } else if post_norm < 0.05 {
        score -= 10.2 * (1.0 - post_norm / 0.05);
    }

    // ---- Relative-to-mean coupling: favor tighter-than-average bins ----
    if pr > 0.0 && mean_residual > 0.0 {
        let waste = post_norm - mean_residual / cap;
        if waste > 0.0 {
            score += waste * 30.0 * (0.4 + progress * 0.6);
        } else {
            score -= (-waste) * 10.0;
        }
    }

    // ---- New-bin candidate decision ----
    if bin_residual == bin_capacity {
        let others = if fitting_bins_count > 0 { fitting_bins_count - 1 } else { 0 };
        let size_pull = fit_ratio * 14.0;
        if fitting_bins_count <= 2 && gap > 0.0 {
            score -= (18.0 + size_pull) * (1.0 - progress * 0.6);
        } else if others == 0 {
            score -= 5.0;
        } else {
            score += 20.0 + open_bins_count as f64 * (0.5 + 0.5 * progress);
        }
        if next > 0.0 && fitting_bins_count <= 3 && item_size as f64 >= next * 0.95 {
            score -= 5.5 * (1.0 - progress * 0.5);
        }
        if next > 0.0 && fitting_bins_count >= 1 && item_size as f64 + next > cap {
            score += 8.0 * (1.0 - progress * 0.4);
        }
        if fit_ratio > 0.5 && progress < 0.5 {
            score -= 6.0 * (1.0 - progress);
        }
        if progress > 0.85 && fit_ratio > 0.6 {
            score -= 4.0 * (progress - 0.85) * 20.0;
        }
    }

    // Sharp bonus for leaving a tiny gap (<12% of capacity).
    if gap > 0.0 && gap < 0.12 {
        score -= (0.12 - gap) * 48.0;
    } else if gap >= 0.12 && gap < 0.22 && fitting_bins_count <= 3 {
        score += (gap - 0.12) * 18.0 * (0.5 + progress * 0.5);
    }
    if gap >= 0.22 && gap < 0.35 && progress > 0.55 {
        score += (gap - 0.22) * 45.5 * (progress - 0.55) * 2.0;
    }
    // Next-item chain: leftover after next item nearly closes bin.
    if next > 0.0 && gap > 0.12 {
        let nxt_gap = ((gap * cap - next).max(0.0)) / cap;
        if nxt_gap < 0.06 {
            score -= 9.0 * (1.0 - nxt_gap / 0.06) * (0.5 + progress);
        }
    }

    // Reward large items filling bins deeply.
    score -= fit_ratio * fit_ratio * 6.0;

    // Congestion: when many bins compete for this item, penalize sloppy fits.
    if fitting_bins_count > 2 {
        score += gap * 6.5 * ((fitting_bins_count.min(12) as f64 - 2.0) / 10.0);
    }
    if open_bins_count > 8 {
        score += post_norm * 5.0 * ((open_bins_count.min(20) as f64 - 8.0) / 12.0);
    }

    // Late-stream consolidation: penalize moderately large residuals late.
    if progress > 0.7 && post_norm > 0.25 {
        score += (post_norm - 0.25) * 6.0 * (progress - 0.7) / 0.3;
    }

    // Last-chance bonus: prefer a bin that would otherwise be wasted.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 - fit_ratio);
        if gap > 0.0 && gap < 0.06 {
            score -= 7.0 * (1.0 - progress * 0.5);
        }
    }

    // Deep fill bonus relative to actual residual.
    let fill_r = item_size as f64 / bin_residual.max(1) as f64;
    if fill_r > 0.90 && bin_residual != bin_capacity {
        score -= (fill_r - 0.90) * 18.0 * (0.6 + progress * 0.5);
    }

    // Dead-space guard: stranded small remainder the next item cannot reuse.
    if next > 0.0 && pr > 0.0 {
        let after_next = (pr - next).max(0.0);
        let dead = after_next / cap;
        if dead > 0.0 && dead < 0.08 {
            let reusable = if after_next >= next { 1.0 } else { 0.0 };
            score += (0.08 - dead) * 16.0 * (1.0 - reusable * 0.5) * (0.5 + progress);
        }
    }

    // Mid-residual band: leftover in 10-20% range the next item cannot fit into.
    if pr > 0.0 && post_norm >= 0.10 && post_norm < 0.20 && next > 0.0 && next > pr {
        score += (next - pr) / cap * 26.0 * (0.4 + progress * 0.8);
    }

    // Half-consumed bins late in the stream.
    if pr > 0.0 && pr < item_size as f64 * 0.5 && progress > 0.3 {
        score += 4.0 * (1.0 - progress);
    }

    // Very tiny residual band bonus (borrowed from best).
    if pr > 0.0 && post_norm < 0.04 {
        score -= (0.04 - post_norm) * 55.0 * (0.7 + progress * 0.3);
    }

    // Two-next chain: residual fits next item leaving near-zero slack.
    if next > 0.0 && pr >= next {
        let two_fit = (pr - next) / cap;
        if two_fit < 0.02 && fitting_bins_count <= 2 {
            score -= 9.0 * (1.0 - progress * 0.4);
        }
        let frac = ((pr - next) % next.max(1.0)) / next.max(1.0);
        if frac < 0.08 {
            score -= 10.0 * (1.0 - progress * 0.5);
        }
    }

    // Residual just short of two next-items: near-perfect double fill.
    if next > 0.0 && pr >= next * 2.0 && pr < next * 2.0 + 8.0 {
        score -= 8.0 * (1.0 - progress * 0.4);
    }

    // Large chain coverage: residual absorbs many copies of next item.
    if next > 0.0 && pr >= next {
        let chain = ((post_residual / next_item_size.max(1)) as f64) * next / cap;
        if chain > 0.5 {
            score -= (chain - 0.5) * 14.0 * (0.5 + progress * 0.5);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: mod-10 buckets penalize awkward dead space
    let pr = post_residual as i64;
    let pr_mod = pr % 10;
    if pr > 0 {
        // dead space that is not a multiple of common item sizes is bad
        score += match pr_mod {
            0 => -8.0,          // perfectly divisible leftover
            1 | 2 | 3 => 6.0,   // tiny unusable slivers
            4 | 5 => 2.0,
            6 | 7 | 8 | 9 => 4.0,
            _ => 0.0,
        };
        // integer-division thresholds: post_residual / 10 class
        let decade = pr / 10;
        score += decade as f64 * 0.6; // larger leftover slightly penalized beyond base
    } else {
        score -= 15.0; // perfect fit is excellent
    }

    // Lookahead: does the next item fit into post_residual?
    if next_item_size > 0 {
        if (next_item_size as u32) <= post_residual {
            // next item fits here: reward, scaled by how tightly it fits
            let slack = post_residual - next_item_size;
            score -= 10.0 + (slack as f64).min(20.0) * -0.15;
        } else {
            // next item won't fit: leftover becomes dead space
            score += 8.0;
            // harmonic check: can next item fit a capacity-fraction residual?
            if post_residual >= bin_capacity / 4 {
                score -= 3.0;
            }
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Prefer fuller bins when many bins are open
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= fill_ratio * 12.0;

    // Coupling with mean residual: prefer bins below mean residual (fuller than average)
    score += (mean_residual - bin_residual as f64) * 0.05;

    // New-bin candidate handling: make empty bin attractive only when current fit is poor
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        let mut nb = 45.0;
        // cheaper to open new bin early in stream (more future items to amortize)
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        nb -= 20.0 * (1.0 - progress);
        // if item fits this bin with small residual, opening new bin is wasteful
        if item_size <= bin_residual {
            let would_leave = bin_residual - item_size;
            if would_leave <= 10 {
                nb += 60.0; // near-perfect fit here, never open new bin
            } else if would_leave <= 30 {
                nb += 25.0;
            }
        }
        // if no open bin exists besides this candidate, must open
        if open_bins_count == 0 {
            nb -= 100.0;
        }
        // if this is the only fitting bin and it's empty-ish... new bin is same thing
        score = score.max(score) ; // keep computed score
        score = nb + (score - score); // replace with new-bin evaluation
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest
    // plausible item (<= 10) are pure waste; penalize hard.
    if post_residual < 10 && post_residual > 0 {
        score += 60.0;
    }
    // Small-but-usable gaps are risky; taper penalty as gap shrinks.
    if post_residual >= 10 && post_residual < 25 {
        score += 18.0 * (25.0 - post_residual as f64) / 15.0;
    }

    // Reward tight fits (low post_residual relative to item).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fit_ratio;

    // Perfect fill is ideal.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: many open bins -> consolidate, avoid spreading.
    score += 2.0 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Lookahead: if next item fits exactly in the post_residual, big reward.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here; slightly penalize leaving big residual.
            score += 6.0;
        }
    }

    // New-bin candidate: keep it neutral-to-slightly-high so it only wins
    // when existing bins are genuinely bad; rises with stream progression.
    if bin_residual == bin_capacity {
        score += 15.0 + 10.0 * (step_index as f64 / total_items.max(1) as f64);
    }

    // Mild preference to fill bins with large residuals when mean is high.
    if (bin_residual as f64) > mean_residual {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect 2-step lookahead match: post_residual == next_item_size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 30.0;
    }
    // Reward post_residual slightly larger than next item (usable next step)
    else if next_item_size > 0 && post_residual > next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 15.0 * (1.0 - slack / bin_capacity as f64);
    }
    // Penalize dead space smaller than next item (unusable immediately)
    else if next_item_size > 0 && post_residual < next_item_size {
        let dead = (next_item_size - post_residual) as f64;
        score += 8.0 * (dead / 100.0).min(1.0);
    }

    // Reward tight fits relative to current residual
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 10.0 * fit_ratio;

    // Relative to mean residual: prefer consuming bins with above-average residual
    if mean_residual > 0.0 {
        score += 3.0 * ((bin_residual as f64 - mean_residual) / mean_residual);
    }

    // Last chance bin: strongly favor to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // Late in stream: prefer tighter packing overall
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.3 * progress;

    // New-bin candidate: make it attractive only when fit is poor
    if bin_residual == bin_capacity {
        score -= 5.0 - 10.0 * fit_ratio;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
    score
