pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let next = next_item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items.max(1) as f64 } else { 0.0 };
    let post_norm = pr / cap;
    let fit_ratio = item_size as f64 / cap;
    let gap = (bin_residual - item_size) as f64 / cap;
    let mut score = post_norm * post_norm * 50.0 + post_norm * 20.0;

    // ---- 2-step lookahead: shape score around the NEXT item ----
    if next > 0.0 {
        if pr == next {
            score -= 54.0;
        } else if pr > next {
            let slack = pr - next;
            let diff = slack / cap;
            score -= 20.0 * (1.0 - diff).max(0.0);
            score -= (-diff * diff * 450.0).exp() * 24.0 * (1.0 - progress * 0.5);
            if diff < 0.04 {
                score -= (0.04 - diff) * 30.0 * (0.6 + progress * 0.6);
            } else if diff > 0.16 {
                score += (diff - 0.16) * 8.0 * (0.5 + progress);
            }
            // Fine-grained residual fitting with lookahead anticipation:
            // reward when post-residual after next stays hostable by
            // typical small items (coupled to mean residual scale).
            let after_next = pr - next;
            let typical = mean_residual.max(1.0).min(cap * 0.25);
            if after_next > 0.0 && after_next < typical * 0.35 {
                score -= (typical * 0.35 - after_next) / cap * 22.0 * (0.5 + progress * 0.5);
            }
            // NEW: reward when after_next is an exact multiple of typical smalls.
            if after_next > 0.0 && typical > 0.0 {
                let mult = (after_next / typical).floor();
                if mult >= 1.0 {
                    let rem = after_next - mult * typical;
                    if rem < typical * 0.08 {
                        score -= 7.0 * (1.0 - progress * 0.4);
                    }
                }
            }
        } else if pr > 0.0 {
            let dead_ratio = (next - pr) / cap;
            score += dead_ratio * 90.0 * (0.6 + progress * 0.6);
        }
    }

    // ---- Absolute dead-floor guard: tiny stranded remainders ----
    let dead_floor = if next_item_size > 0 { (next_item_size.min(12) as f64).max(6.0) } else { 10.0 };
    if post_residual > 0 && pr < dead_floor && pr != next {
        score += 62.0 * (1.0 - progress * 0.3);
    } else if post_residual > 0 && post_residual < 20 && pr != next {
        score += 25.0;
    }

    // ---- Relative-to-mean coupling ----
    if pr > 0.0 {
        let dev = (mean_residual - pr) / cap;
        if dev > 0.06 {
            score += (dev - 0.06) * 10.0 * (0.4 + progress);
        } else if dev < -0.10 {
            score += (-dev - 0.10) * 5.0 * (1.0 - progress);
        }
    }

    // ---- New-bin candidate decision ----
    if bin_residual == bin_capacity {
        let others = if fitting_bins_count > 0 { fitting_bins_count - 1 } else { 0 };
        let size_pull = fit_ratio * 14.0;
        if fitting_bins_count <= 2 && gap > 0.0 {
            score -= (18.0 + size_pull) * (1.0 - progress * 0.6);
        } else if others == 0 {
            score -= 5.0;
        } else {
            score += 20.0 + open_bins_count as f64 * (0.5 + 0.5 * progress);
        }
        if next > 0.0 && fitting_bins_count <= 3 && fit_ratio >= next * 0.95 / cap {
            score -= 5.5 * (1.0 - progress * 0.5);
        }
        if next > 0.0 && fitting_bins_count >= 1 && fit_ratio * cap + next > cap {
            score += 8.0 * (1.0 - progress * 0.4);
        }
        if next > 0.0 && fit_ratio * cap + next <= cap {
            let pair_left = (cap - fit_ratio * cap - next) / cap;
            if pair_left < 0.05 {
                score -= (0.05 - pair_left) * 42.0 * (0.5 + progress * 0.5);
            } else if fit_ratio > 0.35 {
                score -= 3.0 * (1.0 - progress);
            }
        }
        if fit_ratio > 0.5 && progress < 0.5 {
            score -= 6.0 * (1.0 - progress);
        }
        if progress > 0.85 && fit_ratio > 0.6 {
            score -= 4.0 * (progress - 0.85) * 20.0;
        }
        if next > 0.0 && fit_ratio * cap + next > cap * 0.94 && fitting_bins_count > 2 {
            score -= 6.0 * (1.0 - progress * 0.5);
        }
        if progress > 0.6 && fit_ratio < 0.45 && others > 0 {
            score += 10.0 * (progress - 0.6) / 0.4;
        }
        if next > 0.0 && others > 0 {
            let fresh_left = cap - fit_ratio * cap;
            if fresh_left >= next {
                let fresh_slack = (fresh_left - next) / cap;
                if fresh_slack < 0.03 {
                    score -= (0.03 - fresh_slack) * 26.0 * (0.5 + progress * 0.5);
                }
            }
        }
        // Only open a fresh bin when the residual chain (item, next, and a
        // third typical item) nearly fills capacity; otherwise resist.
        if next > 0.0 && others > 1 {
            let fresh_left = cap - fit_ratio * cap;
            if fresh_left >= next {
                let after = fresh_left - next;
                let typical = mean_residual.max(1.0).min(cap * 0.25);
                if after < typical {
                    score += (typical - after) / cap * 14.0 * (0.5 + progress * 0.5);
                }
            } else {
                score += 6.0 * (0.5 + progress * 0.5);
            }
        }
        // NEW: resist opening a fresh bin late when many bins are already open.
        if progress > 0.75 && open_bins_count > 6 {
            score += (progress - 0.75) * 30.0 * ((open_bins_count.min(16) as f64 - 6.0) / 10.0);
        }
    }

    // Exact / near-exact fit bonuses.
    if pr == 0.0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 42.0;
    } else if post_residual <= 9 {
        score -= 18.0 * (1.0 - progress * 0.4);
    } else if post_norm < 0.02 && fitting_bins_count >= 4 {
        score -= 6.0 * (1.0 - progress);
    }

    // Sharp bonus for leaving a tiny gap (<12% of capacity).
    if gap > 0.0 && gap < 0.12 {
        score -= (0.12 - gap) * 48.0;
    } else if gap >= 0.12 && gap < 0.22 && next > 0.0 && pr > 0.0 && pr < next {
        score += (gap - 0.12) * 90.5 * (0.5 + progress);
    } else if gap >= 0.12 && gap < 0.22 && fitting_bins_count <= 3 {
        score += (gap - 0.12) * 18.0 * (0.5 + progress * 0.5);
    }
    if gap >= 0.22 && gap < 0.30 && fitting_bins_count <= 2 {
        score += (gap - 0.22) * 22.0 * (0.6 + progress * 0.4);
    }
    if next > 0.0 && gap > 0.12 {
        let nxt_gap = ((gap * cap - next).max(0.0)) / cap;
        if nxt_gap < 0.05 {
            score -= (0.05 - nxt_gap) * 40.0 * (0.5 + progress * 0.5);
        }
    }

    // Reward large items filling bins deeply.
    score -= fit_ratio * fit_ratio * 6.0;

    // Congestion: many competing bins => penalize sloppy fits.
    if fitting_bins_count > 2 {
        score += gap * 6.5 * ((fitting_bins_count.min(12) as f64 - 2.0) / 10.0);
    }
    if open_bins_count > 8 {
        score += post_norm * 5.0 * ((open_bins_count.min(20) as f64 - 8.0) / 12.0);
    }

    // Late-stream consolidation.
    if progress > 0.7 && post_norm > 0.25 {
        score += (post_norm - 0.25) * 6.0 * (progress - 0.7) / 0.3;
    }

    // Last-chance bonus.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 - fit_ratio);
    }

    // Deep fill bonus.
    let fill_r = item_size as f64 / bin_residual.max(1) as f64;
    if fill_r > 0.90 && bin_residual != bin_capacity {
        score -= (fill_r - 0.90) * 18.0 * (0.6 + progress * 0.5);
    }

    // Waste-vs-mean term.
    if pr > 0.0 && mean_residual > 0.0 {
        let waste = post_norm - mean_residual / cap;
        if waste > 0.0 {
            score += waste * 30.0 * (0.4 + progress * 0.6);
        } else {
            score -= (-waste) * 10.0;
        }
    }

    // Penalize bins whose post-residual can never host the next item class.
    if pr > 0.0 && next > 0.0 && pr < next && post_norm > 0.03 {
        score += (next - pr) / cap * 20.0 * (0.5 + progress * 0.5);
    }

    // Reward bins that remain exactly reusable by the next item.
    if next > 0.0 && pr > 0.0 && (pr - next) / cap < 0.02 && pr >= next {
        score -= 6.0 * (1.0 - (pr - next) / cap / 0.02) * (0.5 + progress);
    }

    // Periodic divisibility bonus.
    if next > 0.0 && pr > 0.0 && pr >= next {
        let frac = ((pr - next) % next.max(1.0)) / next.max(1.0);
        if frac < 0.08 {
            score -= 10.0 * (1.0 - progress * 0.5);
        }
    }

    // Double-fit bonus.
    if next > 0.0 && pr >= next * 2.0 && pr < next * 2.0 + 8.0 {
        score -= 8.0 * (1.0 - progress * 0.4);
    }

    // Last-chance micro-gap bonus.
    if fitting_bins_count == 1 && gap > 0.0 && gap < 0.06 {
        score -= 7.0 * (1.0 - progress * 0.5);
    }

    // Dead-space penalty when few fitting bins and residual too small for next.
    if next > 0.0 && post_residual > 0 && post_residual < next_item_size && fitting_bins_count <= 2 {
        score += 18.0 * (1.0 - progress * 0.5);
    }

    // Chain-closure.
    if next > 0.0 && pr >= next && fitting_bins_count > 1 {
        let chain = pr - next;
        let chain_ref = mean_residual.max(1.0) * 0.35;
        if chain < chain_ref {
            score -= 5.0 * (1.0 - chain / chain_ref) * (0.5 + progress * 0.5);
        }
    }

    // Mid-band residual vacuum.
    if post_norm > 0.03 && post_norm < 0.10 {
        if next > 0.0 && pr >= next {
            score -= 4.0 * (1.0 - progress * 0.5);
        } else {
            score += 6.0 * (0.5 + progress * 0.5);
        }
    }

    // Fine-grained residual fitting with lookahead.
    if next > 0.0 && pr > 0.0 && pr >= next && fill_r > 0.85 {
        let reuse = (pr - next) / cap;
        if reuse < 0.06 {
            score -= (0.06 - reuse) * 30.0 * (0.5 + progress * 0.5);
        }
    }

    // Discourage residuals in the awkward 0.10–0.18 band.
    if post_norm >= 0.10 && post_norm < 0.18 && next > 0.0 && pr < next {
        score += (0.18 - post_norm) * 14.0 * (0.4 + progress * 0.6);
    }

    // Residual-consolidation with multi-fit lookahead.
    if next > 0.0 && pr >= next {
        let fits_ahead = (pr / next).floor();
        if fits_ahead >= 2.0 {
            let remainder = pr - fits_ahead * next;
            let rem_norm = remainder / cap;
            if rem_norm > 0.005 {
                score += rem_norm * 55.0 * (0.5 + progress * 0.5);
            } else {
                score -= 4.0 * (1.0 - progress * 0.4);
            }
            // Reward when the multi-fit chain consumes nearly all residual.
            let chain_fill = (fits_ahead * next) / pr;
            if chain_fill > 0.95 {
                score -= (chain_fill - 0.95) * 60.0 * (0.5 + progress * 0.5);
            }
        }
    }

    // Late-stream residual sweep.
    let remaining = if total_items > step_index { total_items - step_index } else { 1 };
    if remaining < 12 && post_residual > 0 {
        score += post_norm * 40.0;
    }

    // Two-item lookahead: prefer bins whose post-residual after the next item
    // still fits the mean-residual class with minimal slack.
    if next > 0.0 && pr >= next && fitting_bins_count > 1 && remaining > 12 {
        let after = pr - next;
        let typical = mean_residual.max(1.0);
        if after >= typical {
            let slack = (after - typical) / cap;
            if slack < 0.02 {
                score -= (0.02 - slack) * 20.0 * (0.6 + progress * 0.4);
            }
        }
    }

    // NEW: dead-space variance reduction — penalize post-residuals that sit
    // between the next item and the mean-residual class (unhostable band).
    if next > 0.0 && pr > next && mean_residual > 0.0 {
        let after = pr - next;
        let typical = mean_residual.max(1.0);
        if after > typical * 1.6 && after < cap * 0.12 {
            score += (after - typical * 1.6) / cap * 16.0 * (0.5 + progress * 0.5);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item fills most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 60.0 * fill_ratio * fill_ratio;

    // Penalize leaving small-but-large-enough-to-waste residuals only if next item cannot use them.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward residuals that exactly or nearly fit the lookahead item.
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 / (1.0 + slack);
        } else {
            // Dead space relative to lookahead: penalize proportionally to wasted capacity.
            score += 0.5 * (next_item_size - post_residual).min(40) as f64;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: make it attractive only when existing bins fit poorly.
    if bin_residual == bin_capacity {
        // Base cost of consuming fresh capacity.
        score += 30.0;
        // If many bins are open with plenty of mean residual, discourage new bins.
        score += 2.0 * open_bins_count as f64 + 0.3 * mean_residual;
        // Late in the stream, consolidating is safer.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 * progress;
        // If next item is large, a fresh bin is actually valuable.
        if next_item_size > 50 {
            score -= 25.0;
        }
    } else {
        // Prefer bins whose residual is closest to the mean (balance preservation),
        // but only mildly, so tight fits dominate.
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * dev;
    }

    // Slight preference for filling older/more-open bins when many bins exist
    // (reduces fragmentation across the fleet).
    if open_bins_count > 3 && bin_residual < bin_capacity {
        score -= 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;

    // Smooth polynomial coupling of post_residual with stream progress
    let progress_poly = 0.5 + 0.5 * t * t; // later in stream -> tighter packing pressure
    let mut score = pr * progress_poly;

    // Non-linear reward for small post-residuals (tight fits), stronger later in stream
    let tightness = (1.0 - norm_pr).powi(3);
    score -= tightness * (20.0 + 40.0 * t) * (0.5 + 0.5 * norm_item);

    // Penalize dead space that no plausible next item can use
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt > pr {
            score += (nxt - pr) * (1.0 + t);
        } else {
            // reward bins whose residual still fits the lookahead item
            score -= 5.0 * (1.0 - (pr - nxt) / cap).powi(2);
        }
    }

    // Last-chance bonus: avoid opening a new bin when this is the only fitting bin
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * t;
    }

    // Mild penalty when bin diverges from mean residual (keep balance across bins)
    score += ((pr - mean_residual) / cap).abs() * 8.0 * (1.0 - t);

    // New-bin candidate: neutral-ish baseline, slightly discouraged early, more open late
    if bin_residual == bin_capacity {
        score += 10.0 - 20.0 * t;
        if fitting_bins_count >= 1 {
            score += 25.0;
        }
    }

    // Smooth non-linear open-bin pressure
    score += (open_bins_count as f64).ln() * (1.0 + norm_pr) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let next = next_item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items.max(1) as f64 } else { 0.0 };
    let post_norm = pr / cap;
    let fit_ratio = item_size as f64 / cap;
    let gap = (bin_residual - item_size) as f64 / cap;
    let mut score = post_norm * post_norm * 53.0 + post_norm * 21.0;

    // ---- Strong exact-fit ladder (borrowed from best heuristic) ----
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 42.0;
    } else if post_residual <= 9 {
        score -= 18.0 * (1.0 - progress * 0.4);
    } else if post_residual < 20 {
        score += 25.0;
    }

    // Dead floor: small residual that next item can't use is stranded.
    let dead_floor = if next_item_size > 0 { (next_item_size.min(12) as f64).max(6.0) } else { 10.0 };
    if post_residual > 0 && pr < dead_floor {
        score += 62.0 * (1.0 - progress * 0.3);
    }

    // ---- 2-step lookahead: snug remainder after next item lands ----
    if next > 0.0 && post_residual > 0 {
        if (post_residual as u32) >= next_item_size {
            let slack = (pr - next) / cap;
            score -= (-slack * slack * 450.0).exp() * 24.0 * (1.0 - progress * 0.5);
            if slack >= 0.0 && slack < 0.05 {
                score -= (0.05 - slack) * 40.0 * (0.5 + progress * 0.5);
            }
            // Chain: multiple next-item fits reduce residual efficiently.
            let chain = ((post_residual / next_item_size.max(1)) as f64) * next / cap;
            if chain > 0.5 {
                score -= (chain - 0.5) * 14.0 * (0.5 + progress * 0.5);
            }
        } else {
            let dead_ratio = (next - pr) / cap;
            score += dead_ratio * 90.0 * (0.6 + progress * 0.6);
            if fitting_bins_count <= 2 {
                score += 18.0 * (1.0 - progress * 0.5);
            }
        }
    }

    // ---- Mean-residual coupling ----
    if post_residual > 0 && mean_residual > 0.0 {
        let waste = post_norm - mean_residual / cap;
        if waste > 0.0 {
            score += waste * 30.0 * (0.4 + progress * 0.6);
        } else {
            score -= (-waste) * 10.0;
        }
    }

    // ---- New-bin candidate decision ----
    if bin_residual == bin_capacity {
        let size_pull = fit_ratio * 14.0;
        if fitting_bins_count <= 2 && gap > 0.0 {
            score -= (18.0 + size_pull) * (1.0 - progress * 0.6);
        } else {
            score += 20.0 + open_bins_count as f64 * (0.5 + 0.5 * progress);
        }
        if next > 0.0 && fitting_bins_count <= 3 && item_size as f64 >= next * 0.95 {
            score -= 5.5 * (1.0 - progress * 0.5);
        }
        if next > 0.0 && item_size as f64 + next > cap {
            score += 8.0 * (1.0 - progress * 0.4);
        }
        if fit_ratio > 0.5 && progress < 0.5 {
            score -= 6.0 * (1.0 - progress);
        }
        if progress > 0.85 && fit_ratio > 0.6 {
            score -= 4.0 * (progress - 0.85) * 20.0;
        }
        if next > 0.0 && item_size as f64 + next <= cap && fit_ratio > 0.35 {
            score -= 3.0 * (1.0 - progress);
        }
    }

    // ---- Tiny post-residual near-zero bonus ----
    if post_residual > 0 && post_norm < 0.04 {
        score -= (0.04 - post_norm) * 55.0 * (0.7 + progress * 0.3);
    }

    // Sharp bonus for leaving a tiny gap.
    if gap > 0.0 && gap < 0.12 {
        score -= (0.12 - gap) * 48.0;
        if fitting_bins_count == 1 && gap < 0.06 {
            score -= 7.0 * (1.0 - progress * 0.5);
        }
    } else if gap >= 0.12 && gap < 0.22 {
        if fitting_bins_count <= 3 {
            score += (gap - 0.12) * 18.0 * (0.5 + progress * 0.5);
        }
        if next > 0.0 && pr > 0.0 && pr < next {
            score += (gap - 0.10) * 40.0 * (0.5 + progress);
        }
    }
    if gap >= 0.22 && gap < 0.35 && progress > 0.55 {
        score += (gap - 0.22) * 45.5 * (progress - 0.55) * 2.0;
    }

    // Deep fill bonus relative to actual residual.
    let fill_r = item_size as f64 / bin_residual.max(1) as f64;
    if fill_r > 0.90 && bin_residual != bin_capacity {
        score -= (fill_r - 0.90) * 18.0 * (0.6 + progress * 0.5);
    }

    // Congestion: penalize sloppy fits when many bins compete.
    if fitting_bins_count > 2 {
        score += gap * 6.5 * ((fitting_bins_count.min(12) as f64 - 2.0) / 10.0);
    }
    if open_bins_count > 8 {
        score += post_norm * 5.0 * ((open_bins_count.min(20) as f64 - 8.0) / 12.0);
    }

    // Late-stream consolidation.
    if progress > 0.7 && post_norm > 0.25 {
        score += (post_norm - 0.25) * 6.0 * (progress - 0.7) / 0.3;
    }

    // Last-chance bonus: prefer a bin that would otherwise be wasted.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 - fit_ratio);
    }

    // Two next-items fit check.
    if next > 0.0 && post_residual > 0 && (post_residual as u32) >= next_item_size {
        let two_fit = (pr - next) / cap;
        if two_fit < 0.02 && fitting_bins_count <= 2 {
            score -= 9.0 * (1.0 - progress * 0.4);
        }
    }

    // Double next-item near-fit bonus.
    if post_residual > 0 && next > 0.0 && pr >= next * 2.0 && pr < next * 2.0 + 8.0 {
        score -= 8.0 * (1.0 - progress * 0.4);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues near "usable" sizes matter.
    // Treat capacity in quarters; residual in the lowest quarter is near-dead space.
    let quarter = bin_capacity / 4;
    if post_residual < quarter {
        // Dead space penalty, stronger the smaller the residual (wasted fraction).
        let waste = (quarter - post_residual) as f64 / quarter as f64;
        score += 12.0 * waste;
    }

    // Reward tight fits: post_residual small but not zero-dead.
    let frac = post_residual as f64 / bin_capacity as f64;
    score -= 8.0 * (1.0 - frac).min(1.0) * (1.0 - frac).min(1.0);

    // Modulo-class coupling: if post_residual can exactly fit the next item, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual >= next_item_size {
            // next item fits here too: bonus scaled by how close post_residual
            // is to a multiple-class of next_item_size.
            let m = post_residual % next_item_size.max(1);
            score -= 6.0 * (1.0 - m as f64 / next_item_size as f64);
        } else {
            // next item cannot use this residual: penalize proportionally.
            score += 4.0 * (next_item_size as f64 - post_residual as f64) / bin_capacity as f64;
        }
    }

    // Integer-division threshold classes on post_residual (harmonic bands).
    let band = post_residual / 10; // class of residual in decades
    match band {
        0 => score -= 3.0,   // nearly exact fit
        1 => score -= 1.5,   // small usable remainder
        2 | 3 => {}          // neutral mid bands
        4 => score += 1.0,   // half-full leftover: mediocre
        _ => score += 2.0,   // large leftover: weak use of the bin
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 1 {
        // Prefer bins that are harder to fill later: lower residual among competitors.
        score += 0.05 * (post_residual as f64 - mean_residual);
    }

    // New-bin candidate handling: opening a bin is costly early (few bins),
    // cheaper late in the stream when many bins exist.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 40.0 + 60.0 * (1.0 - progress);
        // If no open bin fits, new bin is the only option: make it competitive.
        if fitting_bins_count == 0 {
            score = 5.0;
        }
    }

    // Mild preference to consolidate into bins with low mean residual overall.
    score += 0.03 * (mean_residual - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 0.85;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that nothing can fill are heavily penalized.
    // A gap is "dead" if it's smaller than the smallest plausible item (assume ~1..=10).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 18.0 * (1.0 - post_residual as f64 / 20.0);
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last chance: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Pressure from number of open bins: discourage opening new bins when
    // many bins are already open, but allow it early or for large residuals.
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline cost plus open-bin pressure.
        score += 20.0 + 3.0 * open_bins_count as f64;
        // If item fits poorly in all open bins (few fitting bins), opening fresh
        // is more attractive.
        if fitting_bins_count <= 2 {
            score -= 15.0;
        }
        // If next item is large, a fresh bin preserves room for it.
        if next_item_size > item_size {
            score -= 10.0;
        }
    } else {
        // Placing into an existing bin reduces open-bin pressure slightly.
        score -= 0.5 * open_bins_count as f64;
    }

    // Prefer bins with residual close to mean (balanced packing) mildly.
    score += 0.15 * ((bin_residual as f64 - mean_residual).abs());

    // Lookahead: if the next item fits exactly in the post residual, reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 20.0;
    }
    // Penalize leaving a gap that next item cannot use but could have fit here.
    if next_item_size > post_residual && next_item_size <= bin_residual {
        score += 8.0;
    }

    // Late in stream: consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (bin_residual != bin_capacity) as i32 as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 0.84;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
