    let gap = (bin_residual - item_size) as f64 / cap;
    let mut score = post_norm * post_norm * 52.0 + post_norm * 20.0;

    // ---- Lookahead shaping around the NEXT item ----
    if next > 0.0 {
        if post_residual == next_item_size {
            score -= 48.0;
        } else if pr > next {
            let slack = pr - next;
            let diff = slack / cap;
            score -= 20.0 * (1.0 - diff).max(0.0);
            score -= (-diff * diff * 450.0).exp() * 22.0 * (1.0 - progress * 0.5);
