                score -= (0.05 - second_slack) * 40.0 * (0.5 + progress * 0.5);
            }
            let dead_after = pr - nxt;
            if dead_after > 0.0 && dead_after < nxt {
                let dr = dead_after / nxt;
                score += dr * dr * 12.0 * (0.5 + progress);
            }
            let two_fit = (pr - nxt) / cap;
            if two_fit < 0.02 && fitting_bins_count <= 2 {
                score -= 9.0 * (1.0 - progress * 0.4);
            }
            // Chain divisibility: residual holds multiple next-item copies
            let chain = ((post_residual / next_item_size.max(1)) as f64) * nxt / cap;
            if chain > 0.5 {
                score -= (chain - 0.5) * 14.0 * (0.5 + progress * 0.5);
            }
        }
        if pr >= nxt * 2.0 && pr < nxt * 2.0 + 8.0 {
            score -= 8.0 * (1.0 - progress * 0.4);
        }
    }

    // Very small residual with many open bins: attractive cleanup target
    if post_residual > 0 && post_norm < 0.02 && fitting_bins_count >= 4 {
        score -= 6.0 * (1.0 - progress);
    }
    if post_residual > 0 && post_norm < 0.04 {
        score -= (0.04 - post_norm) * 55.0 * (0.7 + progress * 0.3);
    }

    // Last-chance bin: avoid opening new bin
