pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong base preference for tight fits.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fit_ratio * fit_ratio;

    // Aggressive 2-step lookahead: reward when next item exactly fills post_residual.
    if next_item_size > 0 && post_residual > 0 {
        let diff = post_residual as i64 - next_item_size as i64;
        if diff == 0 {
            score -= 60.0; // perfect chain: next item seals this bin
        } else if diff > 0 && diff <= 10 {
            score -= 30.0; // near-perfect chain
        } else if diff < 0 {
            // next item won't fit here; penalize dead space proportional to gap
            score += (-diff) as f64 * 0.6;
        } else {
            score += diff as f64 * 0.15; // large leftover after chain
        }
    }

    // Relative to mean residual: prefer bins tighter than average.
    score += 0.5 * (post_residual as f64 - mean_residual).max(0.0);
    score -= 0.2 * (mean_residual - post_residual as f64).max(0.0);

    // Last-chance bin: strong bonus to use it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when item is large and no tight fit exists.
    if bin_residual == bin_capacity {
        let large = item_size as f64 / bin_capacity as f64;
        score += 20.0 - 30.0 * large;
        if fitting_bins_count > 0 {
            score += 15.0; // discourage opening when open bins fit
        }
    }

    // Late-stream consolidation: prefer filling bins nearly empty of residual.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * post_residual as f64 * 0.3;

    // Penalize tiny unusable residuals that waste capacity.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
