pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fits are valuable: reward small post_residual nonlinearly.
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tight * tight;

    // Penalize dead space: post_residual that is too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0; // sliver waste
    }

    // Lookahead coupling: if the next item fits exactly in post_residual, strongly favor.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            score -= 6.0 * (next_item_size as f64 / post_residual.max(1) as f64);
        } else {
            // next item cannot follow here; slight penalty proportional to overflow
            score += 2.0 * ((next_item_size as f64 - post_residual as f64) / bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly prefer using the only bin that fits, avoiding a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0;
    }

    // Crowding: many open bins -> prefer consolidating into existing bins.
    let crowding = open_bins_count as f64 / (1.0 + total_items as f64 * 0.05);
    score += crowding * (post_residual as f64 / bin_capacity as f64) * 4.0;

    // Mean residual context: if this bin's residual is far below mean, it is a laggard bin; use it.
    let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score -= 5.0 * dev;

    // New-bin candidate handling: empty bin gets a moderate default cost,
    // reduced late in the stream or when few bins fit.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 - 3.0 * progress;
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
        if next_item_size > 0 && next_item_size >= item_size && next_item_size <= bin_capacity {
            score -= 4.0; // fresh bin can host the lookahead too
        }
    }

    // Mild time-horizon term: early on, be slightly conservative with tight fits.
    score += (1.0 - progress) * (post_residual as f64 / bin_capacity as f64) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
