}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post-residual, with non-linear polynomial shaping
    let mut score = pr
        - 12.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * pr
        - 8.0 * norm_pr * (1.0 - norm_pr) * cap;

    // Perfect-fit reward, smoothly scaled by stream progress
    if post_residual == 0 {
        score -= 30.0 + 20.0 * progress;
    }

    // Penalize dead space that cannot fit typical future items, coupled with progress
    let dead = if pr > 0.0 { (pr / (pr + item_size as f64)).powf(2.0) } else { 0.0 };
    score += 15.0 * dead * (0.5 + progress);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead coupling: reward if next item fits the post-residual, penalize otherwise
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 10.0 * (1.0 - ((pr - nxt) / cap).powf(2.0));
        } else {
            score += 6.0 * (nxt - pr) / cap;
        }
    }

    // Slight pull toward bins near the mean residual, smoothed polynomially
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 5.0 * dev * dev;

    // Mild preference for tighter bins as open bin count grows
    score += (open_bins_count as f64).ln() * norm_pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
