pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify dead space by capacity fraction.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let frac = post / cap;

    // Class bins: 0 (perfect fit), 1 (small), 2 (medium), 3 (large usable)
    let class = if post_residual == 0 { 0 }
        else if post_residual <= 10 { 1 }
        else if post_residual <= 30 { 2 }
        else { 3 };
    score += match class { 0 => -50.0, 1 => 0.0, 2 => 5.0, _ => 12.0 };

    // Modulo arithmetic on post_residual: residuals divisible by small harmonics
    // (e.g. multiples of 10) are more likely to be filled by future items.
    let harmonic_bonus = if post_residual % 10 == 0 { 8.0 }
        else if post_residual % 5 == 0 { 4.0 }
        else { 0.0 };
    score -= harmonic_bonus;

    // Integer-division threshold: how many copies of next_item_size fit afterwards.
    if next_item_size > 0 && post_residual >= next_item_size {
        let k = post_residual / next_item_size;
        score -= (k.min(4) * 3) as f64;
    } else if next_item_size > 0 {
        // Next item cannot follow here: penalize if it would be stranded.
        score += 6.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    // or residuals across open bins are already large.
    if bin_residual == bin_capacity {
        let desperation = (mean_residual / cap).max(0.0).min(1.0);
        let pressure = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 40.0 - 30.0 * desperation - 10.0 * pressure;
        if fitting_bins_count == 0 { score -= 60.0; }
    }

    // Mild preference for tighter bins overall (relative to mean residual).
    score += ((bin_residual as f64 - mean_residual) * 0.15).max(-10.0).min(10.0);

    // Late-stream consolidation: favor filling existing bins as stream ends.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        score -= 8.0 * progress * (1.0 - frac);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let post_norm = pr / cap;

    // Base: minimize leftover, normalized
    let mut score = post_norm * post_norm * 50.0 + post_norm * 20.0;

    // Dead-space floor: residuals too small for typical items are wasted
    let dead_floor = if next_item_size > 0 { (next_item_size.min(12) as f64).max(6.0) } else { 10.0 };
    if post_residual > 0 && pr < dead_floor {
        score += 62.0 * (1.0 - progress * 0.3);
    } else if post_residual < 20 {
        score += 25.0;
    }

    // Reward exact / near-exact fills
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 42.0;
    } else if post_residual <= 9 {
        score -= 18.0 * (1.0 - progress * 0.4);
    }

    // Gaussian lookahead bonus when next item fits with tiny slack
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64 / cap;
        score -= (-slack * slack * 450.0).exp() * 24.0 * (1.0 - progress * 0.5);
    }

    // Tight gap reward on current fit
    let gap = (bin_residual - item_size) as f64 / cap;
    if gap > 0.0 && gap < 0.12 {
        score -= (0.12 - gap) * 48.0;
    } else if gap >= 0.12 && gap < 0.22 && fitting_bins_count <= 3 {
        score += (gap - 0.12) * 18.0 * (0.5 + progress * 0.5);
    }

    // Penalize leaving residual too small for the next item
    if next_item_size > 0 && pr > 0.0 && (pr as u32) < next_item_size && post_norm > 0.03 {
        let dead_ratio = (next_item_size as f64 - pr) / cap;
        score += dead_ratio * 90.0 * (0.6 + progress * 0.6);
    }

    // Relative waste vs mean residual of open bins
    if post_residual > 0 && mean_residual > 0.0 {
        let waste = post_norm - (mean_residual / cap);
        if waste > 0.0 {
            score += waste * 30.0 * (0.4 + progress * 0.6);
        } else {
            score -= (-waste) * 10.0;
        }
    }

    // Scarcity: last-chance bin gets strong preference
    if fitting_bins_count == 1 && gap > 0.0 {
        score -= 300.0 * (1.0 - progress * 0.4);
    }
    if next_item_size > 0 && post_residual > 0 && (pr as u32) < next_item_size && fitting_bins_count <= 2 {
        score += 18.0 * (1.0 - progress * 0.5);
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        let size_pull = (item_size as f64 / cap) * 14.0;
        if fitting_bins_count <= 2 {
            score -= (18.0 + size_pull) * (1.0 - progress * 0.6);
        } else {
            score += 20.0 + open_bins_count as f64 * (0.5 + 0.5 * progress);
        }
        if next_item_size > 0 && fitting_bins_count <= 3 && (item_size as f64) >= next_item_size as f64 * 0.95 {
            score -= 5.5 * (1.0 - progress * 0.5);
        }
        if next_item_size > 0 && fitting_bins_count >= 1 && (item_size as f64) + (next_item_size as f64) > cap {
            score += 8.0 * (1.0 - progress * 0.4);
        }
        if (item_size as f64) > cap * 0.5 && progress < 0.5 {
            score -= 6.0 * (1.0 - progress);
        }
        if progress > 0.85 && (item_size as f64) / cap > 0.6 {
            score -= 4.0 * (progress - 0.85) * 20.0;
        }
        if next_item_size > 0 && (item_size as f64) + (next_item_size as f64) <= cap && (item_size as f64) / cap > 0.35 {
            score -= 3.0 * (1.0 - progress);
        }
    }

    // Second-step slack: residual after placing next item should stay tight
    if next_item_size > 0 && post_residual > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let second_slack = (pr - nxt) / cap;
            if second_slack >= 0.0 && second_slack < 0.05 {
                score -= (0.05 - second_slack) * 40.0 * (0.5 + progress * 0.5);
            }
            let two_fit = second_slack;
            if two_fit < 0.02 && fitting_bins_count <= 2 {
                score -= 9.0 * (1.0 - progress * 0.4);
            }
            let dead_after = pr - nxt;
            if dead_after > 0.0 && dead_after < nxt {
                let dr = dead_after / nxt;
                score += dr * dr * 12.0 * (0.5 + progress);
            }
        }
    }

    // Near-zero residual with many open bins: still worth closing out
    if post_residual > 0 && post_norm < 0.02 {
        if fitting_bins_count >= 4 {
            score -= 6.0 * (1.0 - progress);
        }
        score -= (0.04 - post_norm.min(0.04)) * 55.0 * (0.7 + progress * 0.3);
    }

    // Divisibility chain: residual that fits several next-items is valuable
    if next_item_size > 0 && post_residual > 0 && (pr as u32) >= next_item_size {
        let nxt = next_item_size as f64;
        let frac = ((pr - nxt) % nxt.max(1.0)) / nxt.max(1.0);
        if frac < 0.08 {
            score -= 10.0 * (1.0 - progress * 0.5);
        }
        let chain = ((post_residual / next_item_size.max(1)) as f64) * nxt / cap;
        if chain > 0.5 {
            score -= (chain - 0.5) * 14.0 * (0.5 + progress * 0.5);
        }
    }
    if post_residual > 0 && next_item_size > 0 && pr >= (next_item_size as f64) * 2.0 && pr < (next_item_size as f64) * 2.0 + 8.0 {
        score -= 8.0 * (1.0 - progress * 0.4);
    }

    // Ultra-tight gap among competing bins
    if fitting_bins_count >= 2 && gap > 0.0 && gap < 0.04 && post_residual > 0 {
        score -= (0.04 - gap) * 30.0 * (1.0 - progress * 0.4);
    }

    // Mean-residual anchor: prefer residuals below mean when mean is large
    if next_item_size > 0 && mean_residual > 0.0 && post_residual > 0 && (pr as u32) >= next_item_size {
        let rel = mean_residual / cap;
        if rel > 0.25 && post_norm < rel {
            score -= (rel - post_norm) * 16.0 * (0.6 + progress * 0.5);
        }
    }

    // Early stream: keep residuals flexible
    score += pr * (1.0 - progress) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small for the smallest plausible item (<=8) are wasted.
    if post_residual > 0 && post_residual <= 8 {
        score += 60.0;
    } else if post_residual > 8 && post_residual < 15 {
        score += 25.0;
    }

    // Reward near-perfect fills.
    if post_residual == 0 {
        score -= 80.0;
    }

    // Lookahead: strongly reward bins whose post_residual fits the next item (chained packing).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0 + 0.25 * (next_item_size as f64);
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Prefer filling bins with small residual relative to the mean (consolidation).
    score -= 0.4 * (mean_residual - post_residual as f64);

    // Open-bin pressure: with many open bins, favor existing bins over opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.15 * (open_bins_count as f64) * (1.0 - progress);

    // New-bin candidate: penalize opening a fresh bin unless the current item is large
    // and no open bin offers a decent fit (encourage best-fit on existing bins).
    if bin_residual == bin_capacity {
        score += 20.0 + 0.5 * (open_bins_count as f64);
        if item_size >= 50 {
            score -= 35.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
