pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Reward near-exact fits (low post residual) more aggressively.
    let tightness = 1.0 - (post_residual as f64 / cap);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that is too small to be useful later (below min item size ~1..100 unknown, use small threshold).
    if post_residual > 0 && post_residual < 12 {
        score += 25.0;
    }

    // Last chance: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // Lookahead: if the next item fits into post_residual, reward this placement.
    if next_item_size > 0 {
        if (post_residual as u32) >= next_item_size {
            score -= 10.0;
            let next_tight = 1.0 - ((post_residual as f64 - next_item_size as f64) / cap);
            score -= 6.0 * next_tight;
        } else if (bin_residual as u32) >= next_item_size && post_residual > 0 {
            // placing here would strand the next item: mild penalty
            score += 4.0;
        }
    }

    // Prefer filling bins whose residual is already small relative to mean (consolidate).
    if mean_residual > 0.0 {
        let rel = bin_residual as f64 / mean_residual;
        if rel < 1.0 {
            score -= 5.0 * (1.0 - rel);
        } else {
            score += 3.0 * (rel - 1.0);
        }
    }

    // New-bin candidate handling: empty bin should only win when no open bin is decent.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin; shrinks late in stream or when many bins already open.
        let mut new_bin_cost = 20.0;
        new_bin_cost -= 8.0 * progress;
        if open_bins_count == 0 {
            new_bin_cost -= 40.0;
        }
        // If current bin would leave a large residual anyway, opening fresh is less bad.
        if post_residual as f64 > 0.5 * cap {
            new_bin_cost -= 10.0;
        }
        score += new_bin_cost;
    }

    // Slight preference for bins with larger residual when item is large (avoid fragmentation).
    if item_size as f64 > 0.6 * cap {
        score -= 0.05 * bin_residual as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
