pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let mut score = pr;

    // Smooth non-linear coupling: quadratic penalty on small-but-nonzero post residual
    // (dead space), scaled by stream progress.
    let dead = (norm_pr * (1.0 - norm_pr)).powi(2);
    score -= 8.0 * dead * cap * (0.5 + progress);

    // Reward tight fits (low post_residual) more strongly as stream advances.
    score -= (1.0 - norm_pr).powi(3) * (item_size as f64) * (0.4 + 0.6 * progress);

    // Penalize bins whose residual deviates from the mean residual (imbalance).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 3.0 * dev * dev * cap;

    // Lookahead: if next item fits into post_residual, reward this placement smoothly.
    if next_item_size > 0 {
        let fits = (pr - next_item_size as f64) / cap;
        if fits >= 0.0 {
            score -= 6.0 * (fits * (1.0 - fits)).max(0.0) * cap;
        } else {
            score += 2.0 * (-fits) * cap * (1.0 - progress);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 12.0 * (1.0 - norm_pr);
    }

    // Mild preference to fill existing bins rather than open new ones early.
    score -= (open_bins_count as f64).ln().max(0.0) * (1.0 - progress) * (item_size as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
