    // Reward large items filling bins deeply.
    score -= fit_ratio * fit_ratio * 6.0;

    // Congestion: when many bins compete for this item, penalize sloppy fits.
    if fitting_bins_count > 2 {
        score += gap * 6.5 * ((fitting_bins_count.min(12) as f64 - 2.0) / 10.0);
    }
    if open_bins_count > 8 {
        score += post_norm * 5.0 * ((open_bins_count.min(20) as f64 - 8.0) / 12.0);
    }

    // Late-stream consolidation: penalize moderately large residuals late.
    if progress > 0.7 && post_norm > 0.25 {
        score += (post_norm - 0.25) * 6.0 * (progress - 0.7) / 0.3;
    }

    // Last-chance bonus: prefer a bin that would otherwise be wasted.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 - fit_ratio);
    }

    // Deep fill bonus relative to actual residual.
    let fill_r = item_size as f64 / bin_residual.max(1) as f64;
    if fill_r > 0.90 && bin_residual != bin_capacity {
        score -= (fill_r - 0.90) * 18.0 * (0.6 + progress * 0.5);
    }

    // Dead-space guard: if the remainder after the next item would be a small
    // stranded gap that the next item cannot re-use, penalize it.
    if next > 0.0 && pr > 0.0 {
        let after_next = (pr - next).max(0.0);
        let dead = after_next / cap;
        if dead > 0.0 && dead < 0.08 {
            let reusable = if after_next >= next { 1.0 } else { 0.0 };
            score += (0.08 - dead) * 16.0 * (1.0 - reusable * 0.5) * (0.5 + progress);
        }
    }

    // Mid-residual band: leftover in 10-20% range that next item cannot fit
    // into is likely to strand; penalize.
    if pr > 0.0 && post_norm >= 0.10 && post_norm < 0.20 && next > 0.0 && next > pr {
        score += (next - pr) / cap * 26.0 * (0.4 + progress * 0.8);
    }

    // Half-consumed bins late in the stream: discourage leaving a residual
    // smaller than half the current item (hard to refill).
    if pr > 0.0 && pr < item_size as f64 * 0.5 && progress > 0.3 {
        score += 4.0 * (1.0 - progress);
    }

    // Chain bonus: residual can hold multiple copies of the next item.
    if next > 0.0 && post_residual > 0 && post_residual >= next_item_size {
        let chain = ((post_residual / next_item_size.max(1)) as f64) * next / cap;
        if chain > 0.5 {
            score -= (chain - 0.5) * 14.0 * (0.5 + progress * 0.5);
        }
    }

    // Two-fit bonus: current item + next item exactly fills this bin.
    if next > 0.0 && bin_residual != bin_capacity {
        let pair = item_size as f64 + next;
        if (pair - bin_residual as f64).abs() < 1.0 {
            score -= 14.0 * (1.0 - progress * 0.4);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post-residual: which quarter of the bin it falls into.
    let quarter = bin_capacity / 4;
    let class = post_residual / quarter;
    let class_penalty: [f64; 5] = [0.0, 8.0, 20.0, 45.0, 80.0];
    score += class_penalty[(class as usize).min(4)];

    // Exact-fit reward: post_residual divisible into small harmonic slots.
    if post_residual > 0 && post_residual % 10 == 0 {
        score -= 6.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Lookahead coupling: if next item fits the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let tight = (post_residual - next_item_size) as f64;
            score -= 25.0 - tight * 0.2;
        } else {
            // Post residual can't host next item: penalize proportionally to waste.
            let waste = post_residual as f64 / cap;
            score += waste * 15.0;
        }
    }

    // New-bin candidate handling: empty bin starts neutral, then adjusted.
    if bin_residual == bin_capacity {
        // Opening a new bin is fine when current bin residuals are fragmented.
        let frag = (mean_residual / cap).clamp(0.0, 1.0);
        score += 25.0 - frag * 20.0;
        if fitting_bins_count <= 1 {
            score -= 20.0; // no good alternative, new bin acceptable
        }
        // Early stream: prefer keeping bins open.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += (1.0 - progress) * 10.0;
    }

    // Prefer filling bins below mean residual (tighter bins first).
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // Many open bins: slight pressure to consolidate.
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps (<10) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64);
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 10 {
        score -= 15.0;
    }

    // Lookahead: if the next item fits the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // If next item barely misses the gap, slight penalty for stranding space.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 5.0;
    }

    // Last-chance bin: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.3 + 0.7 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportionally to open bins and mean residual.
        score += 20.0 + pressure * 4.0 + mean_residual * 0.5;
    } else {
        // Reward reusing existing bins, more when bins are plentiful.
        score -= pressure * 0.8;
        // Prefer filling bins with smaller residuals first.
        score += (bin_residual as f64 - mean_residual) * 0.15;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: exact match of post_residual with next item is ideal.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (post_residual as f64 - nxt).abs();
        if post_residual as u32 == next_item_size {
            score -= 60.0; // perfect two-item fill
        } else if post_residual as u32 > next_item_size {
            // next item still fits after this placement: mild reward, scaled by tightness
            score -= 8.0 * (1.0 - gap / (bin_capacity as f64));
        } else {
            // dead space the next item cannot use: penalize proportionally
            score += 0.5 * gap;
        }

        // If next item fits this bin's post_residual but ALSO fits other bins, slight preference
        if post_residual as u32 >= next_item_size && fitting_bins_count > 1 {
            score -= 3.0;
        }
    }

    // Reward tight fits: low post_residual relative to item size
    let tightness = post_residual as f64 / (item_size as f64 + 1.0);
    score -= 12.0 / (1.0 + tightness);

    // Penalize bins with residuals far above the mean (hoarding space) unless it's a great fit
    score += 0.15 * ((post_residual as f64) - mean_residual).abs();

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when few fitting bins or item is large
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 1.0 } else { 1.0 / fitting_bins_count as f64 };
        score = bin_capacity as f64 - 20.0 * pressure - 0.2 * item_size as f64;
        if next_item_size > 0 && next_item_size as f64 > 0.5 * bin_capacity as f64 {
            score -= 10.0; // big next item: fresh bin useful
        }
    }

    // Late in the stream: prefer consolidating into existing bins
    let progress = step_index as f64 / (total_items as f64 + 1.0);
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Many open bins: encourage filling them rather than spreading
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
