pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect-fit bonus: strongly reward zero post-residual.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Penalize small dead space that nothing (min item = 1) can reuse poorly.
        let dead = post_residual as f64;
        score += (dead / 10.0).powi(2) * 0.5;
    }

    // Lookahead: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0;
        } else if next_item_size <= post_residual {
            score -= 50.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Next item won't fit here; mildly penalize leaving large waste.
            score += 10.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 200.0;
    }

    // Tight-fit reward: favor bins where the item fills a large fraction of residual.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 80.0 * fill_ratio;

    // Global state coupling: when many bins are open, prefer consolidation
    // (avoid new bins); when mean residual is high, spread less aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize when open bins exist and are usable,
        // reward early when stream is nearly done and bins are crowded.
        let crowd = open_bins_count as f64;
        score += 150.0 + 30.0 * crowd - 100.0 * progress;
        // If mean residual across bins is large, opening a new bin is wasteful.
        score += 2.0 * mean_residual;
    } else {
        // Prefer bins with residual close to mean (balanced usage) slightly.
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.3 * dev;
        // Late in the stream, favor tighter packing into existing bins.
        score -= 40.0 * progress * fill_ratio;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
