pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;

    // Base: penalize leftover space, but the penalty weight grows over the stream
    // (late in the stream, dead space is more costly since fewer items remain to fill it).
    let mut score = post * (0.8 + 1.2 * progress * progress);

    // Non-linear coupling: a very small post_residual is a great fit; reward it
    // super-linearly. A mid-range residual is dead space; penalize it mildly.
    let tightness = (post / cap).clamp(0.0, 1.0);
    score -= 12.0 * (1.0 - tightness) * (1.0 - tightness);

    // Smooth interaction of post_residual with stream progress: later, prefer
    // near-exact fits even more strongly.
    score -= 8.0 * progress * (1.0 - tightness).powi(3);

    // Lookahead: if the next item fits the post_residual, reward this placement;
    // smooth cosine-shaped coupling rather than a hard threshold.
    if next_item_size > 0 && (next_item_size as f64) <= post {
        let slack = (post - next_item_size as f64) / cap;
        score -= 6.0 * (1.0 - progress) * (1.0 - slack) + 3.0;
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 {
        score -= 10.0 + 15.0 * progress;
    }

    // Mild penalty when many bins are open relative to stream progress
    // (encourage consolidation of scattered bins early).
    score += 0.5 * (open_bins_count as f64) * (1.0 - progress) * (1.0 - progress);

    // Deviation of this bin's residual from the mean: prefer bins that are
    // already partially filled (below-mean residual) when progress is high.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 3.0 * progress * dev * dev * dev.signum();

    // New-bin candidate: penalize opening a new bin unless the item fits poorly
    // everywhere; the penalty eases late in the stream for large items.
    if bin_residual == bin_capacity {
        let poor_fit = (item / cap).powi(2);
        score += 14.0 - 10.0 * progress * poor_fit;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: reward residuals that are "nice"
    // (small, or multiples of common small item sizes like 10, 20, 25, 50).
    let pr = post_residual;
    if pr > 0 {
        if pr % 10 == 0 {
            score -= 4.0; // residual in the decimal harmonic class: highly reusable
        }
        if pr % 20 == 0 {
            score -= 2.0;
        }
        if pr % 25 == 0 {
            score -= 2.5;
        }
        if pr % 50 == 0 {
            score -= 3.0;
        }
        // Small residuals are dead space; penalize the awkward middle band.
        if pr < 10 {
            score += (10 - pr) as f64 * 0.5; // tiny leftovers are nearly worthless
        } else if pr > 40 && pr < 60 {
            score += 3.0; // mid-band residual: hard to fill with typical items
        }
        // Integer-division threshold: residual that exactly admits a
        // half-capacity chunk is a prime follow-up slot.
        if pr / 25 >= 1 && pr % 25 == 0 {
            score -= 2.0;
        }
    } else {
        score -= 12.0; // perfect fit: strongly favored
    }

    // Lookahead coupling: if the next item fits the post-residual exactly or
    // within a harmonic class, reward this placement.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 10.0;
        } else if pr >= next_item_size {
            let rem2 = pr - next_item_size;
            if rem2 % 10 == 0 {
                score -= 3.0;
            }
            score -= 1.5; // next item fits at all
        } else {
            score += 2.0; // next item cannot follow here
        }
        // Harmonic pairing: item + next item summing to capacity multiples
        if item_size + next_item_size == bin_capacity {
            score -= 6.0;
        } else if (item_size + next_item_size) % 50 == 0 {
            score -= 3.0;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate handling: empty bin should only win when nothing fits
    // well. Penalize it relative to a decent fit, but allow it when the best
    // open fit would leave large dead space.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Base penalty keeps new bins from being opened carelessly.
        score += 15.0;
        // But if the item is large relative to capacity, opening fresh is fine.
        if (item_size as f64) > 0.5 * bin_capacity as f64 {
            score -= 6.0;
        }
        // Late in the stream, prefer consolidating into open bins.
        score += progress * 5.0;
        // Many open bins with high mean residual: reuse should win.
        if mean_residual > item_size as f64 {
            score += 4.0;
        }
    }

    // Crowding pressure: with few open bins, favor tighter packing (smaller
    // post-residual already does this); with many open bins, slight extra
    // penalty on large residuals to encourage closing them out.
    if open_bins_count > 4 && post_residual > 50 {
        score += 2.0;
    }

    // Mean-residual coupling: prefer bins whose residual is near the mean
    // (keeps residual distribution balanced and fillable).
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps after placement.
    // A residual that cannot fit the smallest plausible item is pure waste.
    let min_item = 1u32;
    if post_residual > 0 && post_residual < min_item {
        score += 1000.0;
    }
    // Graded penalty: residuals that fit nothing useful (too small for next item
    // or typical small items) are dead space; larger residuals stay useful.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 2.0;
    }
    // Small-gap penalty curve: gaps below ~20 are hard to fill later.
    if post_residual > 0 && post_residual < 20 {
        score += (20 - post_residual) as f64 * 3.0;
    }

    // Reward tight fits: near-perfect packing gets a strong bonus.
    if post_residual == 0 {
        score -= 50.0;
    } else {
        let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
        score -= tightness * 5.0;
    }

    // Open bins pressure: with many open bins, prefer filling existing ones
    // (penalize new-bin candidate and discourage spreading).
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (0.5 + progress);
    score += pressure * (post_residual as f64 / bin_capacity as f64);

    // Last-chance bin: strongly favor using the only bin that fits,
    // otherwise a new bin gets opened.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: make it unattractive unless existing bins are very full.
    if bin_residual == bin_capacity {
        let avg_fill = bin_capacity as f64 - mean_residual;
        let bins_are_full = mean_residual < item_size as f64 * 0.5;
        if !bins_are_full {
            score += 40.0 + avg_fill * 0.2;
        } else {
            score -= 10.0;
        }
    }

    // Lookahead: if the next item fits exactly in the post residual,
    // reward this placement (sets up a perfect follow-up).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    }
    // Penalize leaving a residual just below the next item size (dead zone).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // Mild mean-residual coupling: prefer bins whose residual is near the mean
    // (keeps residuals homogeneous and mergeable for future items).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
