pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let next = next_item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items.max(1) as f64 } else { 0.0 };
    let post_norm = pr / cap;
    let fit_ratio = item_size as f64 / cap;
    let gap = (bin_residual - item_size) as f64 / cap;
    let mut score = post_norm * post_norm * 50.0 + post_norm * 20.0;

    // ---- 2-step lookahead: shape score around the NEXT item ----
    if next > 0.0 {
        if pr == next {
            score -= 54.0;
        } else if pr > next {
            let slack = pr - next;
            let diff = slack / cap;
            score -= 20.0 * (1.0 - diff).max(0.0);
            score -= (-diff * diff * 450.0).exp() * 24.0 * (1.0 - progress * 0.5);
            if diff < 0.04 {
                score -= (0.04 - diff) * 30.0 * (0.6 + progress * 0.6);
            } else if diff > 0.16 {
                score += (diff - 0.16) * 8.0 * (0.5 + progress);
            }
            // Fine-grained residual fitting with lookahead anticipation:
            // reward when the post-residual after next item stays hostable by
            // typical small items (coupled to mean residual scale).
            let after_next = pr - next;
            let typical = mean_residual.max(1.0).min(cap * 0.25);
            if after_next > 0.0 && after_next < typical * 0.35 {
                score -= (typical * 0.35 - after_next) / cap * 24.0 * (0.5 + progress * 0.5);
            }
            // NEW: reward chains that leave a residual still reusable by the
            // mean-residual class with minimal slack (dead-space variance cut).
            if after_next >= typical {
                let slack2 = (after_next - typical) / cap;
                if slack2 < 0.02 {
                    score -= (0.02 - slack2) * 22.0 * (0.6 + progress * 0.4);
                }
            }
        } else if pr > 0.0 {
            let dead_ratio = (next - pr) / cap;
            score += dead_ratio * 90.0 * (0.6 + progress * 0.6);
        }
    }

    // ---- Absolute dead-floor guard: tiny stranded remainders ----
    let dead_floor = if next_item_size > 0 { (next_item_size.min(12) as f64).max(6.0) } else { 10.0 };
    if post_residual > 0 && pr < dead_floor && pr != next {
        score += 62.0 * (1.0 - progress * 0.3);
    } else if post_residual > 0 && post_residual < 20 && pr != next {
        score += 25.0;
    }

    // ---- Relative-to-mean coupling ----
    if pr > 0.0 {
        let dev = (mean_residual - pr) / cap;
        if dev > 0.06 {
            score += (dev - 0.06) * 10.0 * (0.4 + progress);
        } else if dev < -0.10 {
            score += (-dev - 0.10) * 5.0 * (1.0 - progress);
        }
    }

    // ---- New-bin candidate decision ----
    if bin_residual == bin_capacity {
        let others = if fitting_bins_count > 0 { fitting_bins_count - 1 } else { 0 };
        let size_pull = fit_ratio * 14.0;
        if fitting_bins_count <= 2 && gap > 0.0 {
            score -= (18.0 + size_pull) * (1.0 - progress * 0.6);
        } else if others == 0 {
            score -= 5.0;
        } else {
            score += 20.0 + open_bins_count as f64 * (0.5 + 0.5 * progress);
        }
        if next > 0.0 && fitting_bins_count <= 3 && fit_ratio >= next * 0.95 / cap {
            score -= 5.5 * (1.0 - progress * 0.5);
        }
        if next > 0.0 && fitting_bins_count >= 1 && fit_ratio * cap + next > cap {
            score += 8.0 * (1.0 - progress * 0.4);
        }
        if next > 0.0 && fit_ratio * cap + next <= cap {
            let pair_left = (cap - fit_ratio * cap - next) / cap;
            if pair_left < 0.05 {
                score -= (0.05 - pair_left) * 42.0 * (0.5 + progress * 0.5);
            } else if fit_ratio > 0.35 {
                score -= 3.0 * (1.0 - progress);
            }
        }
        if fit_ratio > 0.5 && progress < 0.5 {
            score -= 6.0 * (1.0 - progress);
        }
        if progress > 0.85 && fit_ratio > 0.6 {
            score -= 4.0 * (progress - 0.85) * 20.0;
        }
        if next > 0.0 && fit_ratio * cap + next > cap * 0.94 && fitting_bins_count > 2 {
            score -= 6.0 * (1.0 - progress * 0.5);
        }
        if progress > 0.6 && fit_ratio < 0.45 && others > 0 {
            score += 10.0 * (progress - 0.6) / 0.4;
        }
        if next > 0.0 && others > 0 {
            let fresh_left = cap - fit_ratio * cap;
            if fresh_left >= next {
                let fresh_slack = (fresh_left - next) / cap;
                if fresh_slack < 0.03 {
                    score -= (0.03 - fresh_slack) * 26.0 * (0.5 + progress * 0.5);
                }
            }
        }
        // Combined: only open a fresh bin when the residual chain (item, next,
        // and a third typical item) nearly fills capacity; otherwise resist.
        if next > 0.0 && others > 1 {
            let fresh_left = cap - fit_ratio * cap;
            if fresh_left >= next {
                let after = fresh_left - next;
                let typical = mean_residual.max(1.0).min(cap * 0.25);
                if after < typical {
                    score += (typical - after) / cap * 16.0 * (0.5 + progress * 0.5);
                }
            } else {
                score += 6.0 * (0.5 + progress * 0.5);
            }
        }
    }

    // Exact / near-exact fit bonuses.
    if pr == 0.0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 42.0;
    } else if post_residual <= 9 {
        score -= 18.0 * (1.0 - progress * 0.4);
    } else if post_norm < 0.02 && fitting_bins_count >= 4 {
        score -= 6.0 * (1.0 - progress);
    }

    // Sharp bonus for leaving a tiny gap (<12% of capacity).
    if gap > 0.0 && gap < 0.12 {
        score -= (0.12 - gap) * 48.0;
    } else if gap >= 0.12 && gap < 0.22 && next > 0.0 && pr > 0.0 && pr < next {
        score += (gap - 0.12) * 90.5 * (0.5 + progress);
    } else if gap >= 0.12 && gap < 0.22 && fitting_bins_count <= 3 {
        score += (gap - 0.12) * 18.0 * (0.5 + progress * 0.5);
    }
    if gap >= 0.22 && gap < 0.30 && fitting_bins_count <= 2 {
        score += (gap - 0.22) * 22.0 * (0.6 + progress * 0.4);
    }
    if next > 0.0 && gap > 0.12 {
        let nxt_gap = ((gap * cap - next).max(0.0)) / cap;
        if nxt_gap < 0.05 {
            score -= (0.05 - nxt_gap) * 40.0 * (0.5 + progress * 0.5);
        }
    }

    // Reward large items filling bins deeply.
    score -= fit_ratio * fit_ratio * 6.0;

    // Congestion: many competing bins => penalize sloppy fits.
    if fitting_bins_count > 2 {
        score += gap * 6.5 * ((fitting_bins_count.min(12) as f64 - 2.0) / 10.0);
    }
    if open_bins_count > 8 {
        score += post_norm * 5.0 * ((open_bins_count.min(20) as f64 - 8.0) / 12.0);
    }

    // Late-stream consolidation.
    if progress > 0.7 && post_norm > 0.25 {
        score += (post_norm - 0.25) * 6.0 * (progress - 0.7) / 0.3;
    }

    // Last-chance bonus.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 - fit_ratio);
    }

    // Deep fill bonus.
    let fill_r = item_size as f64 / bin_residual.max(1) as f64;
    if fill_r > 0.90 && bin_residual != bin_capacity {
        score -= (fill_r - 0.90) * 18.0 * (0.6 + progress * 0.5);
    }

    // Waste-vs-mean term.
    if pr > 0.0 && mean_residual > 0.0 {
        let waste = post_norm - mean_residual / cap;
        if waste > 0.0 {
            score += waste * 30.0 * (0.4 + progress * 0.6);
        } else {
            score -= (-waste) * 10.0;
        }
    }

    // Penalize bins whose post-residual can never host the next item class.
    if pr > 0.0 && next > 0.0 && pr < next && post_norm > 0.03 {
        score += (next - pr) / cap * 20.0 * (0.5 + progress * 0.5);
    }

    // Reward bins that remain exactly reusable by the next item.
    if next > 0.0 && pr > 0.0 && (pr - next) / cap < 0.02 && pr >= next {
        score -= 6.0 * (1.0 - (pr - next) / cap / 0.02) * (0.5 + progress);
    }

    // Periodic divisibility bonus.
    if next > 0.0 && pr > 0.0 && pr >= next {
        let frac = ((pr - next) % next.max(1.0)) / next.max(1.0);
        if frac < 0.08 {
            score -= 10.0 * (1.0 - progress * 0.5);
        }
    }

    // Double-fit bonus.
    if next > 0.0 && pr >= next * 2.0 && pr < next * 2.0 + 8.0 {
        score -= 8.0 * (1.0 - progress * 0.4);
    }

    // Last-chance micro-gap bonus.
    if fitting_bins_count == 1 && gap > 0.0 && gap < 0.06 {
        score -= 7.0 * (1.0 - progress * 0.5);
    }

    // Dead-space penalty when few fitting bins and residual too small for next.
    if next > 0.0 && post_residual > 0 && post_residual < next_item_size && fitting_bins_count <= 2 {
        score += 18.0 * (1.0 - progress * 0.5);
    }

    // Chain-closure.
    if next > 0.0 && pr >= next && fitting_bins_count > 1 {
        let chain = pr - next;
        let chain_ref = mean_residual.max(1.0) * 0.35;
        if chain < chain_ref {
            score -= 5.0 * (1.0 - chain / chain_ref) * (0.5 + progress * 0.5);
        }
    }

    // Mid-band residual vacuum.
    if post_norm > 0.03 && post_norm < 0.10 {
        if next > 0.0 && pr >= next {
            score -= 4.0 * (1.0 - progress * 0.5);
        } else {
            score += 6.0 * (0.5 + progress * 0.5);
        }
    }

    // Fine-grained residual fitting with lookahead.
    if next > 0.0 && pr > 0.0 && pr >= next && fill_r > 0.85 {
        let reuse = (pr - next) / cap;
        if reuse < 0.06 {
            score -= (0.06 - reuse) * 30.0 * (0.5 + progress * 0.5);
        }
    }

    // Discourage residuals in the awkward 0.10–0.18 band.
    if post_norm >= 0.10 && post_norm < 0.18 && next > 0.0 && pr < next {
        score += (0.18 - post_norm) * 14.0 * (0.4 + progress * 0.6);
    }

    // Residual-consolidation with multi-fit lookahead.
    if next > 0.0 && pr >= next {
        let fits_ahead = (pr / next).floor();
        if fits_ahead >= 2.0 {
            let remainder = pr - fits_ahead * next;
            let rem_norm = remainder / cap;
            if rem_norm > 0.005 {
                score += rem_norm * 55.0 * (0.5 + progress * 0.5);
            } else {
                score -= 4.0 * (1.0 - progress * 0.4);
            }
            // Reward when the multi-fit chain consumes nearly all residual.
            let chain_fill = (fits_ahead * next) / pr;
            if chain_fill > 0.95 {
                score -= (chain_fill - 0.95) * 60.0 * (0.5 + progress * 0.5);
            }
        }
    }

    // Late-stream residual sweep.
    let remaining = if total_items > step_index { total_items - step_index } else { 1 };
    if remaining < 12 && post_residual > 0 {
        score += post_norm * 40.0;
    }

    // Two-item lookahead: prefer bins whose post-residual after the next item
    // still fits the mean-residual class with minimal slack.
    if next > 0.0 && pr >= next && fitting_bins_count > 1 && remaining > 12 {
        let after = pr - next;
        let typical = mean_residual.max(1.0);
        if after >= typical {
            let slack = (after - typical) / cap;
            if slack < 0.02 {
                score -= (0.02 - slack) * 20.0 * (0.6 + progress * 0.4);
            }
        }
    }

    // NEW: two-item lookahead chain-fill — reward bins where item + next
    // nearly exhausts the residual, minimizing stranded dead space.
    if next > 0.0 && bin_residual != bin_capacity {
        let need = item_size as f64 + next;
        if need <= bin_residual as f64 {
            let chain_left = (bin_residual as f64 - need) / cap;
            if chain_left < 0.02 {
                score -= (0.02 - chain_left) * 34.0 * (0.6 + progress * 0.4);
            }
        }
    }

    // NEW: penalize leaving residuals just below the next-item size by a
    // small margin (near-miss dead space) more aggressively mid-stream.
    if next > 0.0 && post_residual > 0 && pr < next && next - pr <= 6.0 {
        score += (next - pr) * 3.5 * (0.5 + progress * 0.5);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect or near-perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 400.0;
    } else if post_residual <= 10 {
        score -= 150.0;
    }

    // Aggressive 2-step lookahead: reward bins where the next item fits the
    // post residual (chained packing), penalize near-miss dead space.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 900.0;
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            if slack <= 5.0 {
                score -= 300.0 - slack * 20.0;
            } else {
                // leftover after next item is wasted space; penalize proportionally
                score += slack * 0.8;
            }
        } else {
            // next item cannot fit here: post residual likely becomes dead space
            let dead = post_residual as f64;
            score += dead * 1.5;
        }
    }

    // Prefer bins whose residual is already below average (consolidate waste)
    score += (bin_residual as f64 - mean_residual) * 0.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 250.0;
    }

    // New-bin candidate handling: only open a new bin when current fit is bad
    if bin_residual == bin_capacity {
        // baseline for a fresh bin; make it attractive only if existing fits are poor
        score = 40.0 + (item_size as f64) * 0.3;
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 30.0; // new bin can host both items
        }
    }

    // Slight pressure to close out bins as stream progresses
    score += (step_index as f64 / total_items.max(1) as f64) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let next = next_item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items.max(1) as f64 } else { 0.0 };
    let post_norm = pr / cap;
    let fit_ratio = item_size as f64 / cap;
    let gap = (bin_residual - item_size) as f64 / cap;
    let mut score = post_norm * post_norm * 52.0 + post_norm * 21.0;

    // ---- Aggressive 2-step lookahead: shape score around the NEXT item ----
    if next > 0.0 {
        if pr == next {
            score -= 45.0;
        } else if pr > next {
            let slack = pr - next;
            let diff = slack / cap;
            score -= 20.0 * (1.0 - diff).max(0.0);
            score -= (-diff * diff * 455.0).exp() * 22.0 * (1.0 - progress * 0.5);
            if diff < 0.04 {
                score -= (0.04 - diff) * 26.0 * (0.6 + progress * 0.6);
            } else if diff > 0.16 {
                score += (diff - 0.16) * 8.0 * (0.5 + progress);
            }
        } else if pr > 0.0 {
            // Dead-space after placing item: next item cannot fit here.
            let dead_ratio = (next - pr) / cap;
            score += dead_ratio * 60.0 * (0.6 + progress * 0.6);
        }
    }

    // ---- Dead-floor guard on tiny stranded residuals ----
    let dead_floor = if next_item_size > 0 { (next_item_size.min(12) as f64).max(6.0) } else { 10.0 };
    if post_residual > 0 && pr < dead_floor && pr != next {
        score += 62.0 * (1.0 - progress * 0.3);
    } else if post_residual > 0 && post_residual < 20 && pr != next {
        score += 25.0;
    }

    // ---- Relative-to-mean coupling: favor tighter-than-average bins ----
    if post_residual > 0 && mean_residual > 0.0 {
        let waste = post_norm - mean_residual / cap;
        if waste > 0.0 {
            score += waste * 30.0 * (0.4 + progress * 0.6);
        } else {
            score -= (-waste) * 10.0;
        }
    }

    // ---- New-bin candidate decision ----
    if bin_residual == bin_capacity {
        let others = if fitting_bins_count > 0 { fitting_bins_count - 1 } else { 0 };
        let size_pull = fit_ratio * 14.0;
        if fitting_bins_count <= 2 && gap > 0.0 {
            score -= (18.0 + size_pull) * (1.0 - progress * 0.6);
        } else if others == 0 {
            score -= 5.0;
        } else {
            score += 20.0 + open_bins_count as f64 * (0.5 + 0.5 * progress);
        }
        if next > 0.0 && fitting_bins_count <= 3 && item_size as f64 >= next * 0.95 {
            score -= 5.5 * (1.0 - progress * 0.5);
        }
        if next > 0.0 && fitting_bins_count >= 1 && item_size as f64 + next > cap {
            score += 8.0 * (1.0 - progress * 0.4);
        }
        if fit_ratio > 0.5 && progress < 0.5 {
            score -= 6.0 * (1.0 - progress);
        }
        if progress > 0.85 && fit_ratio > 0.6 {
            score -= 4.0 * (progress - 0.85) * 20.0;
        }
        if next > 0.0 && item_size as f64 + next <= cap && fit_ratio > 0.35 {
            score -= 3.0 * (1.0 - progress);
        }
    }

    // Exact / near-exact fit bonuses.
    if pr == 0.0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 42.0;
    } else if post_residual <= 9 {
        score -= 18.0 * (1.0 - progress * 0.4);
    } else if post_norm < 0.05 {
        score -= 10.2 * (1.0 - post_norm / 0.05);
    }

    // Sharp bonus for leaving a tiny gap (<12% of capacity).
    if gap > 0.0 && gap < 0.12 {
        score -= (0.12 - gap) * 48.0;
    } else if gap >= 0.12 && gap < 0.22 {
        if fitting_bins_count <= 3 {
            score += (gap - 0.12) * 18.0 * (0.5 + progress * 0.5);
        } else if next > 0.0 && pr > 0.0 && pr < next {
            score += (gap - 0.10) * 90.5 * (0.5 + progress);
        }
    }
    if gap >= 0.22 && gap < 0.35 && progress > 0.55 {
        score += (gap - 0.22) * 45.5 * (progress - 0.55) * 2.0;
    }
    // Next-item chain: leftover after placing next item nearly closes bin.
    if next > 0.0 && gap > 0.12 {
        let nxt_gap = ((gap * cap - next).max(0.0)) / cap;
        if nxt_gap < 0.06 {
            score -= 9.0 * (1.0 - nxt_gap / 0.06) * (0.5 + progress);
        }
    }

    // Reward large items filling bins deeply.
    score -= fit_ratio * fit_ratio * 6.0;

    // Congestion: when many bins compete for this item, penalize sloppy fits.
    if fitting_bins_count > 2 {
        score += gap * 6.5 * ((fitting_bins_count.min(12) as f64 - 2.0) / 10.0);
    }
    if open_bins_count > 8 {
        score += post_norm * 5.0 * ((open_bins_count.min(20) as f64 - 8.0) / 12.0);
    }

    // Late-stream consolidation: penalize moderately large residuals late.
    if progress > 0.7 && post_norm > 0.25 {
        score += (post_norm - 0.25) * 6.0 * (progress - 0.7) / 0.3;
    }

    // Last-chance bonus: prefer a bin that would otherwise be wasted.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 - fit_ratio);
    }
    if fitting_bins_count == 1 && gap > 0.0 && gap < 0.06 {
        score -= 7.0 * (1.0 - progress * 0.5);
    }

    // Deep fill bonus relative to actual residual.
    let fill_r = item_size as f64 / bin_residual.max(1) as f64;
    if fill_r > 0.90 && bin_residual != bin_capacity {
        score -= (fill_r - 0.90) * 18.0 * (0.6 + progress * 0.5);
    }

    // Dead-space guard after the next item.
    if next > 0.0 && pr > 0.0 {
        let after_next = (pr - next).max(0.0);
        let dead = after_next / cap;
        if dead > 0.0 && dead < 0.08 {
            let reusable = if after_next >= next { 1.0 } else { 0.0 };
            score += (0.08 - dead) * 16.0 * (1.0 - reusable * 0.5) * (0.5 + progress);
        }
        if pr >= next {
            let dead_after = pr - next;
            if dead_after > 0.0 && dead_after < next {
                let dr = dead_after / next;
                score += dr * dr * 12.0 * (0.5 + progress);
            }
        }
    }

    // Mid-residual band penalty when next item cannot fit.
    if pr > 0.0 && post_norm >= 0.10 && post_norm < 0.20 && next > 0.0 && next > pr {
        score += (next - pr) / cap * 26.0 * (0.4 + progress * 0.8);
    }

    // Half-consumed bins late in the stream.
    if pr > 0.0 && pr < item_size as f64 * 0.5 && progress > 0.3 {
        score += 4.0 * (1.0 - progress);
    }

    // Near-perfect two-step chain: pr minus next leaves near-zero gap.
    if next > 0.0 && pr >= next && fitting_bins_count <= 2 {
        let two_fit = (pr - next) / cap;
        if two_fit < 0.02 {
            score -= 9.0 * (1.0 - progress * 0.4);
        }
    }

    // Chain multiplicity reward — residual can hold several next-items.
    if next > 0.0 && post_residual >= next_item_size {
        let chain = ((post_residual / next_item_size.max(1)) as f64) * next / cap;
        if chain > 0.5 {
            score -= (chain - 0.5) * 14.0 * (0.5 + progress * 0.5);
        }
        // Modular near-fit: leftover after one next-item is a near-multiple of next.
        let frac = ((pr - next) % next.max(1.0)) / next.max(1.0);
        if frac < 0.08 {
            score -= 10.0 * (1.0 - progress * 0.5);
        }
    }

    // Double-fit bonus — residual holds next item twice with small slack.
    if next > 0.0 && pr >= next * 2.0 && pr < next * 2.0 + 8.0 {
        score -= 8.0 * (1.0 - progress * 0.4);
    }

    // Tiny absolute residual bonus.
    if post_residual > 0 && post_norm > 0.0 && post_norm < 0.04 {
        score -= (0.04 - post_norm) * 55.0 * (0.7 + progress * 0.3);
    }

    // Very tight gap with competition.
    if fitting_bins_count >= 2 && gap > 0.0 && gap < 0.04 && post_residual > 0 {
        score -= (0.04 - gap) * 30.0 * (1.0 - progress * 0.4);
    }

    // Mean-residual lookahead coupling.
    if next > 0.0 && mean_residual > 0.0 && post_residual > 0 && pr >= next {
        let rel = mean_residual / cap;
        if rel > 0.25 && post_norm < rel {
            score -= (rel - post_norm) * 16.0 * (0.6 + progress * 0.5);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Exact fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Dead space penalty: post_residual too small for any plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead: if next item fits in post_residual, reward; otherwise penalize.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 8.0 * (next_item_size as f64 / bin_capacity as f64);
        } else {
            score += 6.0;
            // Extra penalty if the leftover can't fit the next item and next item is large.
            if next_item_size > bin_residual - post_residual {
                score += 4.0;
            }
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Time horizon: late in the stream, prefer closing bins tightly (avoid new bins).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses and when open bins fit fine.
        score += 30.0 + 25.0 * progress;
        if fitting_bins_count > 0 {
            score += 10.0 * (fitting_bins_count as f64).sqrt();
        }
    } else {
        // Existing bin: mild discount late in stream.
        score -= 5.0 * progress;
    }

    // Global state: many open bins -> prefer filling existing ones, discourage new bins.
    if open_bins_count > 3 {
        if bin_residual == bin_capacity {
            score += 2.0 * open_bins_count as f64;
        } else {
            score -= (open_bins_count as f64).ln() * 3.0;
        }
    }

    // Mean residual coupling: if this bin's residual is far below mean, it's a good filler.
    let dev = mean_residual - bin_residual as f64;
    score -= 0.15 * dev;

    // Prefer bins with residual close to item_size (minimal waste).
    let waste = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += 10.0 * waste * waste;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: penalize post_residual, but with non-linear coupling to stream progress.
    // Early on, tolerate larger residuals; late, demand tight fits.
    let mut score = pr * (1.0 + progress * progress * 1.5);

    // Smooth polynomial coupling: quadratic term in normalized post_residual
    // weighted by progress — dead space becomes quadratically worse over time.
    score += 40.0 * norm_pr * norm_pr * (0.3 + progress);

    // Interaction between post_residual and mean residual: prefer bins whose
    // post-residual deviates below the mean (consolidating space).
    let dev = (pr - mean_residual) / cap;
    score += 15.0 * dev * dev - 8.0 * dev;

    // Last-chance bonus: if this is the only fitting bin, strongly favor it.
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - norm_pr);
    }

    // Lookahead: reward if next item fits snugly into post_residual.
    if next_item_size > 0 {
        let gap = pr - next_item_size as f64;
        if gap >= 0.0 {
            score -= 12.0 * (1.0 - gap / cap);
        } else {
            score += 6.0 * (-gap / cap);
        }
    }

    // Slight preference for using existing bins vs opening new ones,
    // scaled by how many bins are already open.
    if bin_residual == bin_capacity {
        score += 5.0 + open_bins_count as f64 * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the leftover: classify post_residual into capacity fractions
    let frac = post_residual as f64 / cap; // 0..1
    // Dead-space penalty: leftovers in awkward classes (small but nonzero) are useless
    // classes: (0, 10), (10, 25), (25, 50), (50, 100)
    let class_penalty = if post_residual == 0 {
        -20.0 // perfect fit, excellent
    } else if post_residual < 10 {
        15.0 // tiny sliver, nearly dead space
    } else if post_residual < 25 {
        8.0
    } else if post_residual < 50 {
        2.0
    } else {
        0.0
    };
    score += class_penalty;

    // Modulo arithmetic on post_residual relative to common item classes
    // Items 1..100; favorable leftovers are multiples of common sizes
    let pr = post_residual;
    let modulo_bonus = if pr != 0 {
        let mut m = 0.0;
        if pr % 10 == 0 { m -= 4.0; }
        if pr % 20 == 0 { m -= 2.0; }
        if pr % 25 == 0 { m -= 2.0; }
        if pr % 50 == 0 { m -= 3.0; }
        m
    } else { 0.0 };
    score += modulo_bonus;

    // Lookahead: does the leftover fit the next item?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // leftover usable by next item: reward proportionally
            score -= 6.0 * (next_item_size as f64 / cap);
            // exact-ish match leftover == next item class
            if post_residual == next_item_size { score -= 8.0; }
        } else {
            // next item cannot use this leftover: penalize small leftovers more
            score += 5.0 * (1.0 - frac);
        }
    }

    // Last chance: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: prefer new bin only when all open fits are bad
    if bin_residual == bin_capacity {
        // neutral baseline: new bin has residual 100, raw score already 100
        // adjust based on how crowded open bins are
        if open_bins_count > 0 {
            let crowd = mean_residual / cap;
            // if mean residual is small, opening new bin is fine (lower its score)
            score -= 30.0 * crowd;
        } else {
            score -= 100.0; // must open first bin
        }
        // late in the stream, slight preference to consolidate
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * (1.0 - progress);
    }

    // Mild pressure to fill bins tightly as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress * (1.0 - frac);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let next = next_item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items.max(1) as f64 } else { 0.0 };
    let post_norm = pr / cap;
    let fit_ratio = item_size as f64 / cap;
    let gap = (bin_residual - item_size) as f64 / cap;
    let mut score = post_norm * post_norm * 52.0 + post_norm * 21.0;

    // ---- Strong dead-floor penalty (borrowed/combined): tiny leftover strands space ----
    let dead_floor = if next_item_size > 0 { (next_item_size.min(12) as f64).max(6.0) } else { 10.0 };
    if post_residual > 0 && pr < dead_floor && pr != next {
        score += 58.0 * (1.0 - progress * 0.3);
    } else if post_residual > 0 && post_residual < 20 && pr != next {
        score += 22.0;
    }

    // ---- Exact / near-exact closure rewards ----
    if post_residual == 0 {
        score -= 90.0;
    } else if post_residual <= 5 {
        score -= 38.0;
    } else if post_residual <= 9 {
        score -= 16.0 * (1.0 - progress * 0.4);
    } else if post_norm < 0.04 {
        score -= (0.04 - post_norm) * 50.0 * (0.7 + progress * 0.3);
    }

    // ---- 2-step lookahead around the NEXT item ----
    if next > 0.0 {
        if pr == next {
            score -= 45.0;
        } else if pr > next {
            let slack = (pr - next) / cap;
            score -= (-slack * slack * 450.0).exp() * 24.0 * (1.0 - progress * 0.5);
            if slack < 0.04 {
                score -= (0.04 - slack) * 28.0 * (0.6 + progress * 0.6);
            } else if slack > 0.16 {
                score += (slack - 0.16) * 9.0 * (0.5 + progress);
            }
            // Second-item chain: leftover divisible by next item is reusable.
            let nxt = next.max(1.0);
            let frac = ((pr - next) % nxt) / nxt;
            if frac < 0.08 {
                score -= 10.0 * (1.0 - progress * 0.5);
            }
        } else if pr > 0.0 {
            // Next item cannot use leftover: dead-space penalty scaled by shortfall.
            let dead_ratio = (next - pr) / cap;
            score += dead_ratio * 88.0 * (0.6 + progress * 0.6);
        }
    }

    // ---- Relative-to-mean coupling ----
    if post_residual > 0 && mean_residual > 0.0 {
        let waste = post_norm - mean_residual / cap;
        if waste > 0.0 {
            score += waste * 30.0 * (0.4 + progress * 0.6);
        } else {
            score -= (-waste) * 10.0;
        }
    }

    // ---- New-bin candidate decision ----
    if bin_residual == bin_capacity {
        let size_pull = fit_ratio * 14.0;
        if fitting_bins_count <= 2 && gap > 0.0 {
            score -= (18.0 + size_pull) * (1.0 - progress * 0.6);
        } else if fitting_bins_count == 0 {
            score -= 5.0;
        } else {
            score += 20.0 + open_bins_count as f64 * (0.5 + 0.5 * progress);
        }
        if next > 0.0 && fitting_bins_count <= 3 && fit_ratio >= next / cap * 0.95 {
            score -= 5.5 * (1.0 - progress * 0.5);
        }
        if next > 0.0 && fit_ratio + next / cap > 1.0 {
            score += 8.0 * (1.0 - progress * 0.4);
        }
        if fit_ratio > 0.5 && progress < 0.5 {
            score -= 6.0 * (1.0 - progress);
        }
        if progress > 0.85 && fit_ratio > 0.6 {
            score -= 4.0 * (progress - 0.85) * 20.0;
        }
    }

    // ---- Sharp bonus for tiny gap ----
    if gap > 0.0 && gap < 0.12 {
        score -= (0.12 - gap) * 48.0;
        if fitting_bins_count >= 2 && gap < 0.04 && post_residual > 0 {
            score -= (0.04 - gap) * 30.0 * (1.0 - progress * 0.4);
        }
    } else if gap >= 0.12 && gap < 0.22 {
        if fitting_bins_count <= 3 {
            score += (gap - 0.12) * 18.0 * (0.5 + progress * 0.5);
        }
        if next > 0.0 && pr > 0.0 && pr < next {
            score += (gap - 0.10) * 60.0 * (0.5 + progress);
        }
    } else if gap >= 0.22 && gap < 0.35 && progress > 0.55 {
        score += (gap - 0.22) * 45.0 * (progress - 0.55) * 2.0;
    }

    // ---- Next-item chain: leftover after next item nearly closes bin ----
    if next > 0.0 && gap > 0.12 {
        let nxt_gap = ((gap * cap - next).max(0.0)) / cap;
        if nxt_gap < 0.06 {
            score -= 9.0 * (1.0 - nxt_gap / 0.06) * (0.5 + progress);
        }
    }

    // ---- Reward large items filling deeply ----
    score -= fit_ratio * fit_ratio * 6.0;

    // ---- Congestion penalties ----
    if fitting_bins_count > 2 {
        score += gap * 6.5 * ((fitting_bins_count.min(12) as f64 - 2.0) / 10.0);
    }
    if open_bins_count > 8 {
        score += post_norm * 5.0 * ((open_bins_count.min(20) as f64 - 8.0) / 12.0);
    }

    // ---- Late-stream consolidation ----
    if progress > 0.7 && post_norm > 0.25 {
        score += (post_norm - 0.25) * 6.0 * (progress - 0.7) / 0.3;
    }

    // ---- Last-chance bonus ----
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 - fit_ratio);
        if gap > 0.0 && gap < 0.06 {
            score -= 7.0 * (1.0 - progress * 0.5);
        }
    }

    // ---- Deep fill bonus ----
    let fill_r = item_size as f64 / bin_residual.max(1) as f64;
    if fill_r > 0.90 && bin_residual != bin_capacity {
        score -= (fill_r - 0.90) * 18.0 * (0.6 + progress * 0.5);
    }

    // ---- Dead-space guard after next item ----
    if next > 0.0 && pr > 0.0 && pr >= next {
        let after_next = pr - next;
        let dead = after_next / cap;
        if dead > 0.0 && dead < 0.08 {
            let reusable = if after_next >= next { 1.0 } else { 0.0 };
            score += (0.08 - dead) * 16.0 * (1.0 - reusable * 0.5) * (0.5 + progress);
        }
        // Multi-item chain: residual fits two or more next items.
        if pr >= next * 2.0 && pr < next * 2.0 + 8.0 {
            score -= 8.0 * (1.0 - progress * 0.4);
        }
    }

    // ---- Mid-residual band penalty ----
    if pr > 0.0 && post_norm >= 0.10 && post_norm < 0.20 && next > 0.0 && next > pr {
        score += (next - pr) / cap * 26.0 * (0.4 + progress * 0.8);
    }

    // ---- Half-consumed bins late ----
    if pr > 0.0 && pr < item_size as f64 * 0.5 && progress > 0.3 && pr != next {
        score += 4.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to host
    // typical future items (1..=10) are pure waste; penalize them hard.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 12.0;
    } else if post_residual == 0 {
        // Perfect fill is the ideal outcome: strong reward.
        score -= 60.0;
    }

    // Reward tight fits: fraction of bin consumed by this placement.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 15.0;

    // Coupling with mean residual: prefer bins that are already emptier
    // than average when placing (keeps tight bins for small future items),
    // but only mildly so.
    score += (mean_residual - post_residual as f64) * 0.35;

    // Open-bin pressure: discourage spreading across many bins unless
    // the fit is excellent; encourages consolidation early.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (0.25 - 0.35 * fill_ratio);

    // Last-chance bin: if this is the only bin that fits, using it avoids
    // opening a new bin — strong reward.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual,
    // this placement sets up a perfect chain — reward heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        if post_residual == next_item_size {
            score -= 45.0;
        } else {
            score -= 8.0;
        }
    }
    // If the next item would be stranded by a tiny leftover, penalize.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual < 10 {
        score += 10.0;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Opening a new bin is justified when no good fit exists among
        // open bins or when open bins are crowded; otherwise penalize
        // slightly so consolidation is preferred.
        if fitting_bins_count == 0 {
            score -= 30.0;
        } else {
            // Only open a new bin if existing fits would leave dead space.
            score += 20.0 + post_residual as f64 * 0.2;
            if progress < 0.2 {
                score -= 5.0; // early on, a fresh bin is cheap
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // New-bin candidate: neutral-ish baseline, penalized slightly so we prefer
    // filling existing bins unless the fit is poor.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // New bin only wins if existing fits would leave big dead space;
        // give it a modest penalty that tight items can overcome.
        score += 15.0 + 0.05 * (open_bins_count as f64);
        // Late in the stream, prefer closing out: penalize new bins more.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 * progress;
        return score;
    }

    // Reward tight fits (small post_residual).
    score -= 6.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Aggressive 2-step lookahead: if next item exactly fills post_residual,
    // this is a perfect chain — reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            // Next item still fits: reward proportional to how much of the
            // post-residual it consumes.
            let fill = next_item_size as f64 / post_residual as f64;
            score -= 12.0 * fill;
        } else {
            // Next item cannot use this bin's remainder: penalize dead space,
            // scaled by how close the next item is to fitting (near-misses worst).
            let miss = (next_item_size - post_residual) as f64;
            let miss_ratio = miss / bin_capacity as f64;
            score += 8.0 * miss_ratio.min(1.0);
        }
    }

    // Compare post_residual to mean residual of open bins: leaving a residual
    // near the mean keeps the fleet homogeneous (good for future items).
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.08 * dev;

    // Last chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Small bonus for using bins when many are open (reduce fleet sprawl).
    score -= 0.3 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= 12.0 * tightness * tightness;

    // Penalize creating dead space that is too small for typical items.
    if post_residual > 0 {
        let dead = if post_residual < 10 { 1.0 } else { 0.0 };
        score += 8.0 * dead;
        // Mid-range residuals (too small for most items) are wasteful.
        if post_residual < 30 && post_residual > 0 {
            score += 0.15 * (30.0 - post_residual as f64);
        }
    }

    // Lookahead: reward if next item fits exactly into the post residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual >= next_item_size {
            score -= 6.0;
        } else {
            // Next item won't fit here; slight penalty for wasting residual.
            score += 0.05 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Prefer bins with low residual overall (fill emptier bins first).
    score += 0.10 * (bin_residual as f64 - mean_residual);

    // Late in the stream, be more conservative: prefer compact placements.
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    score += 5.0 * progress * (post_residual as f64 / cap);

    // When many bins are open, discourage opening new ones implicitly
    // (empty-bin candidate gets residual == capacity, naturally high score,
    // but add a small extra penalty scaled by open bins).
    if bin_residual == bin_capacity {
        score += 3.0 + 0.5 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr;

    // Non-linear coupling: residual fraction raised to a progress-dependent power.
    // Early in the stream, larger leftover space is tolerable (bins get refilled);
    // late in the stream, large dead space is heavily penalized.
    let rf = (pr / cap).clamp(0.0, 1.0);
    let exponent = 1.5 + 3.5 * progress;
    score += cap * rf.powf(exponent);

    // Smooth quadratic interaction: penalize wasted residual relative to mean open-bin residual.
    let excess = pr - mean_residual.max(0.0);
    score += 0.35 * excess * excess / cap;

    // Reward tight fits strongly (subtract when post_residual is small, non-linearly).
    score -= 12.0 * (1.0 - rf).powf(3.0) * (1.0 + progress);

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (smooth sigmoid-like weight).
    if fitting_bins_count <= 1 {
        score -= 25.0 + 20.0 * progress;
    }

    // Lookahead coupling: if the next item exactly fills this bin's post-residual,
    // reward heavily; if next item cannot fit the post-residual but fits a smaller
    // remainder elsewhere, mild penalty for blocking.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let match_term = 1.0 - ((pr - nxt).abs() / cap).clamp(0.0, 1.0);
        score -= 10.0 * match_term * match_term;
        if nxt > pr {
            score += 4.0 * progress;
        }
    }

    // Mild penalty when many bins are open and this placement leaves a mid-range residual
    // (fragmentation risk), via a smooth bump function centered at half capacity.
    let bump = 4.0 * rf * (1.0 - rf);
    score += open_bins_count as f64 * bump * 0.8;

    // New-bin candidate (empty bin): add a fixed opening cost so it only wins
    // when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        score += 18.0 + 15.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let next = next_item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items.max(1) as f64 } else { 0.0 };
    let post_norm = pr / cap;
    let fit_ratio = item_size as f64 / cap;
    let gap = (bin_residual - item_size) as f64 / cap;
    let mut score = post_norm * post_norm * 50.0 + post_norm * 20.0;

    // ---- 2-step lookahead: shape score around the NEXT item ----
    if next > 0.0 {
        if pr == next {
            score -= 54.0;
        } else if pr > next {
            let slack = pr - next;
            let diff = slack / cap;
            score -= 20.0 * (1.0 - diff).max(0.0);
            score -= (-diff * diff * 450.0).exp() * 24.0 * (1.0 - progress * 0.5);
            if diff < 0.04 {
                score -= (0.04 - diff) * 30.0 * (0.6 + progress * 0.6);
            } else if diff > 0.16 {
                score += (diff - 0.16) * 8.0 * (0.5 + progress);
            }
            // Fine-grained residual fitting with lookahead anticipation:
            // reward when the post-residual after next item stays hostable by
            // typical small items (coupled to mean residual scale).
            let after_next = pr - next;
            let typical = mean_residual.max(1.0).min(cap * 0.25);
            if after_next > 0.0 && after_next < typical * 0.35 {
                score -= (typical * 0.35 - after_next) / cap * 22.0 * (0.5 + progress * 0.5);
            }
            // NEW: reward chains that exactly tile the residual (item + k*next == residual)
            let k = (after_next / next).floor();
            if k >= 1.0 {
                let rem = after_next - k * next;
                if rem < 2.0 {
                    score -= (2.0 - rem) * 9.0 * (0.5 + progress * 0.5);
                }
            }
        } else if pr > 0.0 {
            let dead_ratio = (next - pr) / cap;
            score += dead_ratio * 90.0 * (0.6 + progress * 0.6);
            // NEW: stronger dead-space penalty when many bins compete (avoid
            // stranding residuals that can never host the next item).
            if fitting_bins_count > 3 {
                score += dead_ratio * 22.0 * ((fitting_bins_count.min(10) - 3) as f64) * (0.5 + progress * 0.5);
            }
        }
    }

    // ---- Absolute dead-floor guard: tiny stranded remainders ----
    let dead_floor = if next_item_size > 0 { (next_item_size.min(12) as f64).max(6.0) } else { 10.0 };
    if post_residual > 0 && pr < dead_floor && pr != next {
        score += 62.0 * (1.0 - progress * 0.3);
    } else if post_residual > 0 && post_residual < 20 && pr != next {
        score += 25.0;
    }

    // ---- Relative-to-mean coupling ----
    if pr > 0.0 {
        let dev = (mean_residual - pr) / cap;
        if dev > 0.06 {
            score += (dev - 0.06) * 10.0 * (0.4 + progress);
        } else if dev < -0.10 {
            score += (-dev - 0.10) * 5.0 * (1.0 - progress);
        }
    }

    // ---- New-bin candidate decision ----
    if bin_residual == bin_capacity {
        let others = if fitting_bins_count > 0 { fitting_bins_count - 1 } else { 0 };
        let size_pull = fit_ratio * 14.0;
        if fitting_bins_count <= 2 && gap > 0.0 {
            score -= (18.0 + size_pull) * (1.0 - progress * 0.6);
        } else if others == 0 {
            score -= 5.0;
        } else {
            score += 20.0 + open_bins_count as f64 * (0.5 + 0.5 * progress);
        }
        if next > 0.0 && fitting_bins_count <= 3 && fit_ratio >= next * 0.95 / cap {
            score -= 5.5 * (1.0 - progress * 0.5);
        }
        if next > 0.0 && fitting_bins_count >= 1 && fit_ratio * cap + next > cap {
            score += 8.0 * (1.0 - progress * 0.4);
        }
        if next > 0.0 && fit_ratio * cap + next <= cap {
            let pair_left = (cap - fit_ratio * cap - next) / cap;
            if pair_left < 0.05 {
                score -= (0.05 - pair_left) * 42.0 * (0.5 + progress * 0.5);
            } else if fit_ratio > 0.35 {
                score -= 3.0 * (1.0 - progress);
            }
        }
        if fit_ratio > 0.5 && progress < 0.5 {
            score -= 6.0 * (1.0 - progress);
        }
        if progress > 0.85 && fit_ratio > 0.6 {
            score -= 4.0 * (progress - 0.85) * 20.0;
        }
        if next > 0.0 && fit_ratio * cap + next > cap * 0.94 && fitting_bins_count > 2 {
            score -= 6.0 * (1.0 - progress * 0.5);
        }
        if progress > 0.6 && fit_ratio < 0.45 && others > 0 {
            score += 10.0 * (progress - 0.6) / 0.4;
        }
        if next > 0.0 && others > 0 {
            let fresh_left = cap - fit_ratio * cap;
            if fresh_left >= next {
                let fresh_slack = (fresh_left - next) / cap;
                if fresh_slack < 0.03 {
                    score -= (0.03 - fresh_slack) * 26.0 * (0.5 + progress * 0.5);
                }
            }
        }
        // Only open a fresh bin when the residual chain (item, next, and a
        // third typical item) nearly fills capacity; otherwise resist.
        if next > 0.0 && others > 1 {
            let fresh_left = cap - fit_ratio * cap;
            if fresh_left >= next {
                let after = fresh_left - next;
                let typical = mean_residual.max(1.0).min(cap * 0.25);
                if after < typical {
                    score += (typical - after) / cap * 14.0 * (0.5 + progress * 0.5);
                }
            } else {
                score += 6.0 * (0.5 + progress * 0.5);
            }
        }
        // NEW: resist opening a fresh bin mid-stream when open bins already
        // carry residuals that would be orphaned by the next item.
        if next > 0.0 && others > 0 && progress > 0.3 {
            let fresh_left = cap - fit_ratio * cap;
            if fresh_left > next * 1.6 {
                score += (fresh_left / cap) * 12.0 * (0.4 + progress * 0.6);
            }
        }
    }

    // Exact / near-exact fit bonuses.
    if pr == 0.0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 42.0;
    } else if post_residual <= 9 {
        score -= 18.0 * (1.0 - progress * 0.4);
    } else if post_norm < 0.02 && fitting_bins_count >= 4 {
        score -= 6.0 * (1.0 - progress);
    }

    // Sharp bonus for leaving a tiny gap (<12% of capacity).
    if gap > 0.0 && gap < 0.12 {
        score -= (0.12 - gap) * 48.0;
    } else if gap >= 0.12 && gap < 0.22 && next > 0.0 && pr > 0.0 && pr < next {
        score += (gap - 0.12) * 90.5 * (0.5 + progress);
    } else if gap >= 0.12 && gap < 0.22 && fitting_bins_count <= 3 {
        score += (gap - 0.12) * 18.0 * (0.5 + progress * 0.5);
    }
    if gap >= 0.22 && gap < 0.30 && fitting_bins_count <= 2 {
        score += (gap - 0.22) * 22.0 * (0.6 + progress * 0.4);
    }
    if next > 0.0 && gap > 0.12 {
        let nxt_gap = ((gap * cap - next).max(0.0)) / cap;
        if nxt_gap < 0.05 {
            score -= (0.05 - nxt_gap) * 40.0 * (0.5 + progress * 0.5);
        }
    }

    // Reward large items filling bins deeply.
    score -= fit_ratio * fit_ratio * 6.0;

    // Congestion: many competing bins => penalize sloppy fits.
    if fitting_bins_count > 2 {
        score += gap * 6.5 * ((fitting_bins_count.min(12) as f64 - 2.0) / 10.0);
    }
    if open_bins_count > 8 {
        score += post_norm * 5.0 * ((open_bins_count.min(20) as f64 - 8.0) / 12.0);
    }

    // Late-stream consolidation.
    if progress > 0.7 && post_norm > 0.25 {
        score += (post_norm - 0.25) * 6.0 * (progress - 0.7) / 0.3;
    }

    // Last-chance bonus.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 - fit_ratio);
    }

    // Deep fill bonus.
    let fill_r = item_size as f64 / bin_residual.max(1) as f64;
    if fill_r > 0.90 && bin_residual != bin_capacity {
        score -= (fill_r - 0.90) * 18.0 * (0.6 + progress * 0.5);
    }

    // Waste-vs-mean term.
    if pr > 0.0 && mean_residual > 0.0 {
        let waste = post_norm - mean_residual / cap;
        if waste > 0.0 {
            score += waste * 30.0 * (0.4 + progress * 0.6);
        } else {
            score -= (-waste) * 10.0;
        }
    }

    // Penalize bins whose post-residual can never host the next item class.
    if pr > 0.0 && next > 0.0 && pr < next && post_norm > 0.03 {
        score += (next - pr) / cap * 20.0 * (0.5 + progress * 0.5);
    }

    // Reward bins that remain exactly reusable by the next item.
    if next > 0.0 && pr > 0.0 && (pr - next) / cap < 0.02 && pr >= next {
        score -= 6.0 * (1.0 - (pr - next) / cap / 0.02) * (0.5 + progress);
    }

    // Periodic divisibility bonus.
    if next > 0.0 && pr > 0.0 && pr >= next {
        let frac = ((pr - next) % next.max(1.0)) / next.max(1.0);
        if frac < 0.08 {
            score -= 10.0 * (1.0 - progress * 0.5);
        }
    }

    // Double-fit bonus.
    if next > 0.0 && pr >= next * 2.0 && pr < next * 2.0 + 8.0 {
        score -= 8.0 * (1.0 - progress * 0.4);
    }

    // Last-chance micro-gap bonus.
    if fitting_bins_count == 1 && gap > 0.0 && gap < 0.06 {
        score -= 7.0 * (1.0 - progress * 0.5);
    }

    // Dead-space penalty when few fitting bins and residual too small for next.
    if next > 0.0 && post_residual > 0 && post_residual < next_item_size && fitting_bins_count <= 2 {
        score += 18.0 * (1.0 - progress * 0.5);
    }

    // Chain-closure.
    if next > 0.0 && pr >= next && fitting_bins_count > 1 {
        let chain = pr - next;
        let chain_ref = mean_residual.max(1.0) * 0.35;
        if chain < chain_ref {
            score -= 5.0 * (1.0 - chain / chain_ref) * (0.5 + progress * 0.5);
        }
    }

    // Mid-band residual vacuum.
    if post_norm > 0.03 && post_norm < 0.10 {
        if next > 0.0 && pr >= next {
            score -= 4.0 * (1.0 - progress * 0.5);
        } else {
            score += 6.0 * (0.5 + progress * 0.5);
        }
    }

    // Fine-grained residual fitting with lookahead.
    if next > 0.0 && pr > 0.0 && pr >= next && fill_r > 0.85 {
        let reuse = (pr - next) / cap;
        if reuse < 0.06 {
            score -= (0.06 - reuse) * 30.0 * (0.5 + progress * 0.5);
        }
    }

    // Discourage residuals in the awkward 0.10–0.18 band.
    if post_norm >= 0.10 && post_norm < 0.18 && next > 0.0 && pr < next {
        score += (0.18 - post_norm) * 14.0 * (0.4 + progress * 0.6);
    }

    // Residual-consolidation with multi-fit lookahead.
    if next > 0.0 && pr >= next {
        let fits_ahead = (pr / next).floor();
        if fits_ahead >= 2.0 {
            let remainder = pr - fits_ahead * next;
            let rem_norm = remainder / cap;
            if rem_norm > 0.005 {
                score += rem_norm * 55.0 * (0.5 + progress * 0.5);
            } else {
                score -= 4.0 * (1.0 - progress * 0.4);
            }
            // Reward when the multi-fit chain consumes nearly all residual.
            let chain_fill = (fits_ahead * next) / pr;
            if chain_fill > 0.95 {
                score -= (chain_fill - 0.95) * 60.0 * (0.5 + progress * 0.5);
            }
        }
    }

    // Late-stream residual sweep.
    let remaining = if total_items > step_index { total_items - step_index } else { 1 };
    if remaining < 12 && post_residual > 0 {
        score += post_norm * 40.0;
    }

    // Two-item lookahead: prefer bins whose post-residual after the next item
    // still fits the mean-residual class with minimal slack, reducing dead
    // space variance across the stream.
    if next > 0.0 && pr >= next && fitting_bins_count > 1 && remaining > 12 {
        let after = pr - next;
        let typical = mean_residual.max(1.0);
        if after >= typical {
            let slack = (after - typical) / cap;
            if slack < 0.02 {
                score -= (0.02 - slack) * 20.0 * (0.6 + progress * 0.4);
            }
        }
    }

    // NEW: dead-space variance reduction — penalize post-residuals sitting in
    // the stranded band between next-item size and the next usable class.
    if next > 0.0 && pr > 0.0 && pr >= next {
        let after = pr - next;
        if after > 0.0 && after < next * 0.5 && fitting_bins_count > 2 {
            score += (next * 0.5 - after) / next.max(1.0) * 8.0 * (0.5 + progress * 0.5);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: how "usable" is the leftover space
    // Classes defined by capacity fractions: 1/4, 1/2, 3/4 thresholds
    let cap_quarter = bin_capacity / 4;
    let cap_half = bin_capacity / 2;
    let cap_three_quarter = 3 * bin_capacity / 4;

    // Penalize residuals in "dead zones" (too small for typical items, but not zero)
    if post_residual > 0 && post_residual < cap_quarter {
        score += 12.0 * (cap_quarter - post_residual) as f64 / cap_quarter as f64;
    }

    // Reward residuals landing exactly on harmonic multiples (divisible classes)
    if post_residual % cap_quarter == 0 {
        score -= 6.0;
    } else if post_residual % 10 == 0 {
        score -= 2.0;
    }

    // Integer-division tier of post_residual relative to next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // This bin can also serve the next item: strong reward
            score -= 8.0;
            // Perfect chaining: post_residual exactly consumed by next item
            if post_residual == next_item_size {
                score -= 10.0;
            }
            // Harmonic pairing: next_item + item lands on half/quarter boundaries
            let combined = item_size + next_item_size;
            if bin_residual % cap_half == 0 && combined <= bin_residual {
                score -= 3.0;
            }
        } else {
            // Next item won't fit here: penalize proportional to waste potential
            score += 4.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize unless current bins have very poor fits
    if bin_residual == bin_capacity {
        score += 20.0;
        // Early in stream, opening bins is cheaper (more future items to fill them)
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - progress);
        // If mean residual across open bins is tiny, new bin is justified
        if mean_residual < cap_quarter as f64 {
            score -= 18.0;
        }
    }

    // Tight fit reward: item fills most of the bin
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 10.0 * fill_ratio;

    // Penalize leaving residual in awkward integer-division tier
    let tier = post_residual / cap_quarter;
    score += 2.0 * (3 - tier.min(3)) as f64;

    // Many open bins: prefer consolidating into existing ones
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = 0.0;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong penalty for small unusable gaps (dead space < 10 can never be filled
    // by any item; gaps 1..=9 are pure waste).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Penalize slightly larger awkward gaps too (10..=15 hard to fill exactly).
    if post_residual >= 10 && post_residual <= 15 {
        score += 12.0;
    }

    // Reward exact fits heavily.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Reward when this placement also leaves room for the lookahead item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }
    // Penalize if post_residual is nonzero but too small for the next item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 6.0;
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: prefer existing bins generally; only allow new bin
    // when open bins are crowded and current fit is poor.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, growing with number of open bins pressure.
        score = bin_capacity as f64 + 30.0;
        // If no bin fits well (large post_residual among others), opening new is ok.
        if fitting_bins_count == 0 || mean_residual < item_size as f64 * 0.5 {
            score -= 20.0;
        }
        // Late in the stream, avoid proliferating bins.
        if step_index as f64 / total_items as f64 > 0.8 {
            score += 15.0;
        }
    }

    // Open-bins pressure: mildly prefer filling existing bins when many are open.
    score += open_bins_count as f64 * 0.5;

    // Prefer bins with smaller residual relative to mean (tighter bins first).
    score += (bin_residual as f64 - mean_residual) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = 0.0;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // New-bin candidate: baseline score equal to capacity minus item (large residual left).
    // Make it attractive only when fits are poor; otherwise it should lose.
    let is_new_bin = bin_residual == bin_capacity;

    // Core objective: minimize post_residual (tight fit), with diminishing returns.
    score = (post_residual as f64).powf(0.85);

    // Aggressive 2-step lookahead: reward when post_residual exactly matches next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // perfect chaining: residual consumed by next item
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // reward proportional to how close next item comes to filling residual
            score -= 40.0 * (1.0 - slack / bin_capacity as f64).max(0.0);
        } else {
            // next item cannot use the residual; penalize large unusable leftovers
            let unusable = (next_item_size - post_residual) as f64;
            score += 0.25 * unusable;
        }
    } else {
        // last item: just minimize post residual strongly
        score -= 20.0;
    }

    // Penalize residuals that become dead space: below the minimum item size (1..100 unknown,
    // use a conservative small threshold) yet nonzero.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Relative-to-mean coupling: bins with residual well below mean are "almost full";
    // prefer filling them to close them out.
    let mean_gap = mean_residual - post_residual as f64;
    if mean_gap > 0.0 {
        score -= 0.15 * mean_gap;
    } else {
        score += 0.10 * (-mean_gap);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 35.0;
    }

    // New-bin candidate handling:
    if is_new_bin {
        // Opening a new bin is good when the item fits poorly everywhere:
        // i.e., post_residual here (capacity - item) is small only for big items.
        // Base penalty so it's chosen only when open-bin scores are worse.
        score += 30.0;
        // Big items leave little residual in a fresh bin; encourage opening for them
        // when they'd fragment an existing bin.
        if item_size >= 70 {
            score -= 25.0;
        }
        // Early in the stream, opening bins is cheap (many future items to fill them).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 20.0 * (1.0 - progress);
        // Few open bins relative to item size: fresh bin likely useful later.
        if open_bins_count < 4 {
            score -= 10.0;
        }
    }

    // Mild preference to spread load when many bins are open (keeps residuals balanced).
    if open_bins_count > 8 {
        score += 0.05 * ((post_residual as f64) - mean_residual).abs();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
