pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 500.0;
    } else {
        // Reward tight fits proportionally
        let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
        score -= 60.0 * tightness * tightness;
    }

    // Penalize dead space that no plausible item can fill
    if post_residual > 0 {
        let dead = (post_residual as f64 / 100.0).powi(2);
        score += 40.0 * dead;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 120.0;
    }

    // Lookahead: reward leaving room for the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // next item fits here: reward, scaled by how snugly
            let slack = (post_residual - next_item_size) as f64;
            score -= 90.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item won't fit here: penalize more if we created lots of unusable residue
            let gap = (next_item_size - post_residual) as f64;
            score += 0.5 * gap.min(80.0);
        }
    } else {
        // last item: just minimize residual
        score -= 30.0;
    }

    // Global state coupling: when many bins are open with high mean residual,
    // prefer consolidating into existing bins rather than opening new ones
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let consolidation = mean_residual / bin_capacity as f64;
    if bin_residual == bin_capacity {
        // new-bin candidate: penalize when open bins are underutilized
        score += 150.0 * (1.0 - consolidation) * (0.5 + 0.5 * progress);
        // reward new bin early in stream when few bins exist
        score -= 40.0 * (1.0 - progress) * (1.0 - open_bins_count.min(20) as f64 / 20.0);
    } else {
        // existing bin: reward when mean residual is high (bins are loose)
        score -= 30.0 * consolidation * (1.0 - progress);
    }

    // Mild penalty for very full system state to encourage efficiency late
    score += 10.0 * (open_bins_count as f64 / (total_items.max(1) as f64).sqrt()) * progress;

    // Small jitter-free deterministic tiebreaker based on residual exactness
    score += (bin_residual as f64 % 7.0) * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress in [0,1]
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Non-linear polynomial coupling of post_residual with progress.
    // Early on, larger residuals are tolerated; late, waste is punished harder.
    let pr = post_residual as f64;
    let pr_norm = pr / bin_capacity as f64;
    let poly = pr_norm * pr_norm * (0.5 + 2.0 * progress) + pr_norm * (1.0 - progress);
    score += 40.0 * poly;

    // Reward tight fits (small post_residual) with a smooth saturating term
    let tight = 1.0 - (pr / (bin_capacity as f64 * 0.5)).min(1.0);
    score -= 25.0 * tight * tight * (1.0 - 0.3 * progress);

    // Lookahead: if next item fits the post-residual exactly or well, reward this bin
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        let gap = (post_residual as f64 - next_item_size as f64) / bin_capacity as f64;
        score -= 15.0 * (1.0 - gap.min(1.0));
    } else if next_item_size > 0 {
        // Next item won't fit here: penalize leaving a residual just below next size
        let miss = (next_item_size as f64 - post_residual as f64) / bin_capacity as f64;
        score += 10.0 * (1.0 - miss.min(1.0)) * (1.0 - progress);
    }

    // Last-chance bin: strongly favor using it over opening a new bin
    if fitting_bins_count == 1 {
        score -= 30.0 * (1.0 + progress);
    }

    // New-bin candidate handling: make it attractive only when open bins fit poorly
    if bin_residual == bin_capacity {
        // New bin baseline: post_residual = capacity - item
        let new_pr = (bin_capacity - item_size) as f64 / bin_capacity as f64;
        score = 60.0 + 50.0 * new_pr * new_pr;
        // Encourage opening new bins early (many items remain), discourage late
        score -= 20.0 * (1.0 - progress) * (1.0 - progress);
        // Discourage opening when several bins already fit the item
        score += 8.0 * (fitting_bins_count as f64).sqrt();
        // If an existing bin would be a near-perfect fit, keep new bin less attractive
        if fitting_bins_count > 0 {
            score += 10.0;
        }
    }

    // Mild penalty relative to mean residual: avoid leaving outliers of waste
    score += 0.15 * (pr - mean_residual).abs();

    // Slight preference for bins with more existing content when many bins are open
    score -= 0.05 * (bin_residual - post_residual) as f64 / (open_bins_count.max(1) as f64).sqrt();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Perfect fit: dominant reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: classify leftover into usable bands.
    // Class 0: post_residual == 0 (perfect) handled above.
    // Class 1: tiny leftovers (1..=10) are near-dead space -> penalize extra.
    // Class 2: medium (11..=40) can host future small items.
    // Class 3: large (41..=99) still flexible.
    let pr = post_residual;
    if pr > 0 && pr <= 10 {
        score += 25.0; // near-dead space penalty
    } else if pr <= 40 {
        score -= 5.0;
    } else {
        score -= 12.0; // large residual is valuable
    }

    // Modulo arithmetic on post_residual relative to small item sizes:
    // leftover divisible by common small sizes (10, 20, 25, 50) is reusable.
    if pr > 0 {
        if pr % 10 == 0 { score -= 8.0; }
        if pr % 20 == 0 { score -= 4.0; }
        if pr % 25 == 0 { score -= 3.0; }
        if pr % 50 == 0 { score -= 3.0; }
    }

    // Lookahead coupling: reward if next item fits exactly into post_residual.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 900.0;
        } else if next_item_size <= pr {
            // next item fits: the tighter, the better
            score -= 30.0 * (next_item_size as f64 / pr.max(1) as f64);
        } else {
            // next item won't fit here: slight penalty proportional to gap
            score += 6.0 * ((next_item_size - pr) as f64 / cap_f);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: only attractive when current fit is poor.
    if bin_residual == bin_capacity {
        let fit_quality = post_residual as f64 / cap_f; // high post_residual = poor fit
        if post_residual > 0 && fit_quality > 0.55 {
            score -= 40.0 + 30.0 * fit_quality; // prefer fresh bin for bad fits
        } else {
            score += 80.0; // discourage opening new bins on decent fits
        }
    }

    // Tightness bonus: reward small post_residual generally (best-fit flavor),
    // scaled by stream progress (later items: consolidate more aggressively).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - post_residual as f64 / cap_f) * (10.0 + 10.0 * progress);

    // Slight preference for bins already below mean residual (balancing).
    score += 0.05 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let next = next_item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items.max(1) as f64 } else { 0.0 };
    let post_norm = pr / cap;
    let fit_ratio = item_size as f64 / cap;
    let gap = (bin_residual - item_size) as f64 / cap;
    let mut score = post_norm * post_norm * 50.0 + post_norm * 20.0;

    // ---- 2-step lookahead: shape score around the NEXT item ----
    if next > 0.0 {
        if pr == next {
            score -= 54.0;
        } else if pr > next {
            let slack = pr - next;
            let diff = slack / cap;
            score -= 20.0 * (1.0 - diff).max(0.0);
            score -= (-diff * diff * 450.0).exp() * 24.0 * (1.0 - progress * 0.5);
            if diff < 0.04 {
                score -= (0.04 - diff) * 30.0 * (0.6 + progress * 0.6);
            } else if diff > 0.16 {
                score += (diff - 0.16) * 8.0 * (0.5 + progress);
            }
            // COMBINED: fine-grained residual fitting with lookahead anticipation —
            // reward when the post-residual after next item stays hostable by
            // typical small items (coupled to mean residual scale).
            let after_next = pr - next;
            let typical = mean_residual.max(1.0).min(cap * 0.25);
            if after_next > 0.0 && after_next < typical * 0.35 {
                score -= (typical * 0.35 - after_next) / cap * 22.0 * (0.5 + progress * 0.5);
            }
            // NEW: multi-fit chain lookahead — how many future next-items fit
            let fits_ahead = (after_next / next).floor();
            if fits_ahead >= 1.0 {
                let remainder = after_next - fits_ahead * next;
                let rem_norm = remainder / cap;
                if rem_norm > 0.005 {
                    score += rem_norm * 55.0 * (0.5 + progress * 0.5);
                } else {
                    score -= 4.0 * (1.0 - progress * 0.4);
                }
                let chain_fill = (fits_ahead * next) / after_next.max(1.0);
                if chain_fill > 0.95 {
                    score -= (chain_fill - 0.95) * 60.0 * (0.5 + progress * 0.5);
                }
            }
        } else if pr > 0.0 {
            let dead_ratio = (next - pr) / cap;
            score += dead_ratio * 90.0 * (0.6 + progress * 0.6);
        }
    }

    // ---- Absolute dead-floor guard: tiny stranded remainders ----
    let dead_floor = if next_item_size > 0 { (next_item_size.min(12) as f64).max(6.0) } else { 10.0 };
    if post_residual > 0 && pr < dead_floor && pr != next {
        score += 62.0 * (1.0 - progress * 0.3);
    } else if post_residual > 0 && post_residual < 20 && pr != next {
        score += 25.0;
    }

    // ---- Relative-to-mean coupling ----
    if pr > 0.0 {
        let dev = (mean_residual - pr) / cap;
        if dev > 0.06 {
            score += (dev - 0.06) * 10.0 * (0.4 + progress);
        } else if dev < -0.10 {
            score += (-dev - 0.10) * 5.0 * (1.0 - progress);
        }
    }

    // ---- New-bin candidate decision ----
    if bin_residual == bin_capacity {
        let others = if fitting_bins_count > 0 { fitting_bins_count - 1 } else { 0 };
        let size_pull = fit_ratio * 14.0;
        if fitting_bins_count <= 2 && gap > 0.0 {
            score -= (18.0 + size_pull) * (1.0 - progress * 0.6);
        } else if others == 0 {
            score -= 5.0;
        } else {
            score += 20.0 + open_bins_count as f64 * (0.5 + 0.5 * progress);
        }
        if next > 0.0 && fitting_bins_count <= 3 && fit_ratio >= next * 0.95 / cap {
            score -= 5.5 * (1.0 - progress * 0.5);
        }
        if next > 0.0 && fitting_bins_count >= 1 && fit_ratio * cap + next > cap {
            score += 8.0 * (1.0 - progress * 0.4);
        }
        if next > 0.0 && fit_ratio * cap + next <= cap {
            let pair_left = (cap - fit_ratio * cap - next) / cap;
            if pair_left < 0.05 {
                score -= (0.05 - pair_left) * 42.0 * (0.5 + progress * 0.5);
            } else if fit_ratio > 0.35 {
                score -= 3.0 * (1.0 - progress);
            }
        }
        if fit_ratio > 0.5 && progress < 0.5 {
            score -= 6.0 * (1.0 - progress);
        }
        if progress > 0.85 && fit_ratio > 0.6 {
            score -= 4.0 * (progress - 0.85) * 20.0;
        }
        if next > 0.0 && fit_ratio * cap + next > cap * 0.94 && fitting_bins_count > 2 {
            score -= 6.0 * (1.0 - progress * 0.5);
        }
        if progress > 0.6 && fit_ratio < 0.45 && others > 0 {
            score += 10.0 * (progress - 0.6) / 0.4;
        }
        if next > 0.0 && others > 0 {
            let fresh_left = cap - fit_ratio * cap;
            if fresh_left >= next {
                let fresh_slack = (fresh_left - next) / cap;
                if fresh_slack < 0.03 {
                    score -= (0.03 - fresh_slack) * 26.0 * (0.5 + progress * 0.5);
                }
            }
        }
        // COMBINED: only open a fresh bin when the residual chain (item, next,
        // and a third typical item) nearly fills capacity; otherwise resist.
        if next > 0.0 && others > 1 {
            let fresh_left = cap - fit_ratio * cap;
            if fresh_left >= next {
                let after = fresh_left - next;
                let typical = mean_residual.max(1.0).min(cap * 0.25);
                if after < typical {
                    score += (typical - after) / cap * 14.0 * (0.5 + progress * 0.5);
                }
            } else {
                score += 6.0 * (0.5 + progress * 0.5);
            }
        }
    }

    // Exact / near-exact fit bonuses.
    if pr == 0.0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 42.0;
    } else if post_residual <= 9 {
        score -= 18.0 * (1.0 - progress * 0.4);
    } else if post_norm < 0.02 && fitting_bins_count >= 4 {
        score -= 6.0 * (1.0 - progress);
    }

    // Sharp bonus for leaving a tiny gap (<12% of capacity).
    if gap > 0.0 && gap < 0.12 {
        score -= (0.12 - gap) * 48.0;
    } else if gap >= 0.12 && gap < 0.22 && next > 0.0 && pr > 0.0 && pr < next {
        score += (gap - 0.12) * 90.5 * (0.5 + progress);
    } else if gap >= 0.12 && gap < 0.22 && fitting_bins_count <= 3 {
        score += (gap - 0.12) * 18.0 * (0.5 + progress * 0.5);
    }
    if gap >= 0.22 && gap < 0.30 && fitting_bins_count <= 2 {
        score += (gap - 0.22) * 22.0 * (0.6 + progress * 0.4);
    }
    if next > 0.0 && gap > 0.12 {
        let nxt_gap = ((gap * cap - next).max(0.0)) / cap;
        if nxt_gap < 0.05 {
            score -= (0.05 - nxt_gap) * 40.0 * (0.5 + progress * 0.5);
        }
    }
    // NEW: micro-gap bonus with two fitting bins (borrowed from best lineage).
    if fitting_bins_count >= 2 && gap > 0.0 && gap < 0.04 && post_residual > 0 {
        score -= (0.04 - gap) * 30.0 * (1.0 - progress * 0.4);
    }

    // Reward large items filling bins deeply.
    score -= fit_ratio * fit_ratio * 6.0;

    // Congestion: many competing bins => penalize sloppy fits.
    if fitting_bins_count > 2 {
        score += gap * 6.5 * ((fitting_bins_count.min(12) as f64 - 2.0) / 10.0);
    }
    if open_bins_count > 8 {
        score += post_norm * 5.0 * ((open_bins_count.min(20) as f64 - 8.0) / 12.0);
    }

    // Late-stream consolidation.
    if progress > 0.7 && post_norm > 0.25 {
        score += (post_norm - 0.25) * 6.0 * (progress - 0.7) / 0.3;
    }

    // Last-chance bonus.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 - fit_ratio);
    }

    // Deep fill bonus.
    let fill_r = item_size as f64 / bin_residual.max(1) as f64;
    if fill_r > 0.90 && bin_residual != bin_capacity {
        score -= (fill_r - 0.90) * 18.0 * (0.6 + progress * 0.5);
    }

    // Waste-vs-mean term.
    if pr > 0.0 && mean_residual > 0.0 {
        let waste = post_norm - mean_residual / cap;
        if waste > 0.0 {
            score += waste * 30.0 * (0.4 + progress * 0.6);
        } else {
            score -= (-waste) * 10.0;
        }
    }

    // Penalize bins whose post-residual can never host the next item class.
    if pr > 0.0 && next > 0.0 && pr < next && post_norm > 0.03 {
        score += (next - pr) / cap * 20.0 * (0.5 + progress * 0.5);
    }

    // Reward bins that remain exactly reusable by the next item.
    if next > 0.0 && pr > 0.0 && (pr - next) / cap < 0.02 && pr >= next {
        score -= 6.0 * (1.0 - (pr - next) / cap / 0.02) * (0.5 + progress);
    }

    // Periodic divisibility bonus.
    if next > 0.0 && pr > 0.0 && pr >= next {
        let frac = ((pr - next) % next.max(1.0)) / next.max(1.0);
        if frac < 0.08 {
            score -= 10.0 * (1.0 - progress * 0.5);
        }
    }

    // Double-fit bonus.
    if next > 0.0 && pr >= next * 2.0 && pr < next * 2.0 + 8.0 {
        score -= 8.0 * (1.0 - progress * 0.4);
    }

    // Last-chance micro-gap bonus.
    if fitting_bins_count == 1 && gap > 0.0 && gap < 0.06 {
        score -= 7.0 * (1.0 - progress * 0.5);
    }

    // Dead-space penalty when few fitting bins and residual too small for next.
    if next > 0.0 && post_residual > 0 && post_residual < next_item_size && fitting_bins_count <= 2 {
        score += 18.0 * (1.0 - progress * 0.5);
    }

    // Chain-closure.
    if next > 0.0 && pr >= next && fitting_bins_count > 1 {
        let chain = pr - next;
        let chain_ref = mean_residual.max(1.0) * 0.35;
        if chain < chain_ref {
            score -= 5.0 * (1.0 - chain / chain_ref) * (0.5 + progress * 0.5);
        }
    }

    // Mid-band residual vacuum.
    if post_norm > 0.03 && post_norm < 0.10 {
        if next > 0.0 && pr >= next {
            score -= 4.0 * (1.0 - progress * 0.5);
        } else {
            score += 6.0 * (0.5 + progress * 0.5);
        }
    }

    // Fine-grained residual fitting with lookahead.
    if next > 0.0 && pr > 0.0 && pr >= next && fill_r > 0.85 {
        let reuse = (pr - next) / cap;
        if reuse < 0.06 {
            score -= (0.06 - reuse) * 30.0 * (0.5 + progress * 0.5);
        }
    }

    // Discourage residuals in the awkward 0.10–0.18 band.
    if post_norm >= 0.10 && post_norm < 0.18 && next > 0.0 && pr < next {
        score += (0.18 - post_norm) * 14.0 * (0.4 + progress * 0.6);
    }

    // Residual-consolidation with multi-fit lookahead.
    if next > 0.0 && pr >= next {
        let fits_ahead = (pr / next).floor();
        if fits_ahead >= 2.0 {
            let remainder = pr - fits_ahead * next;
            let rem_norm = remainder / cap;
            if rem_norm > 0.005 {
                score += rem_norm * 55.0 * (0.5 + progress * 0.5);
            } else {
                score -= 4.0 * (1.0 - progress * 0.4);
            }
            // COMBINED: reward when the multi-fit chain consumes nearly all
            // residual, tightening mid-size gap exploitation.
            let chain_fill = (fits_ahead * next) / pr;
            if chain_fill > 0.95 {
                score -= (chain_fill - 0.95) * 60.0 * (0.5 + progress * 0.5);
            }
        }
    }

    // Late-stream residual sweep.
    let remaining = if total_items > step_index { total_items - step_index } else { 1 };
    if remaining < 12 && post_residual > 0 {
        score += post_norm * 40.0;
    }

    // COMBINED: two-item lookahead — prefer bins whose post-residual after the
    // next item still fits the mean-residual class with minimal slack, reducing
    // dead space variance across the stream.
    if next > 0.0 && pr >= next && fitting_bins_count > 1 && remaining > 12 {
        let after = pr - next;
        let typical = mean_residual.max(1.0);
        if after >= typical {
            let slack = (after - typical) / cap;
            if slack < 0.02 {
                score -= (0.02 - slack) * 20.0 * (0.6 + progress * 0.4);
            }
        }
    }

    // NEW: dead-after-next quadratic penalty (borrowed from best lineage).
    if next > 0.0 && pr >= next {
        let dead_after = pr - next;
        if dead_after > 0.0 && dead_after < next {
            let dr = dead_after / next;
            score += dr * dr * 12.0 * (0.5 + progress);
        }
    }

    // NEW: ultra-tiny post-residual vacuum (borrowed from best lineage).
    if post_residual > 0 && post_norm > 0.0 && post_norm < 0.04 {
        score -= (0.04 - post_norm) * 55.0 * (0.7 + progress * 0.3);
    }

    // NEW: chain-fill ratio reward (borrowed from best lineage).
    if next > 0.0 && post_residual > 0 && post_residual >= next_item_size {
        let chain = ((post_residual / next_item_size.max(1)) as f64) * next / cap;
        if chain > 0.5 {
            score -= (chain - 0.5) * 14.0 * (0.5 + progress * 0.5);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold the
    // minimum future item (1..=10) are "dead space". Penalize them hard.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 + (10 - post_residual) as f64 * 8.0;
    }

    // Perfect fit reward: exact zero residual is ideal.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Tightness reward: the smaller the post_residual relative to capacity,
    // the better the fill. Non-linear coupling on fill ratio.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 25.0 * fill_ratio * fill_ratio;

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins rather than opening new ones.
    score += 0.9 * open_bins_count as f64;

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New empty bin candidate: penalize so it only wins when open bins are
    // truly bad (heavy dead-space or no fitting bins). Scale pressure with
    // mean residual of open bins: if open bins have plenty of room, avoid
    // opening a new one.
    if bin_residual == bin_capacity {
        score += 30.0 + 0.35 * mean_residual;
        // If next item is large, a fresh bin may be valuable soon.
        score -= (next_item_size as f64) * 0.1;
    } else {
        // Reward bins whose residual can also host the lookahead item,
        // enabling a good double-fill.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 12.0;
        }
        // Penalize wasting a bin that could still fit a large next item on a
        // tiny item (poor lookahead compatibility).
        if next_item_size > 0 && post_residual < next_item_size && post_residual >= 1 {
            score += 5.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        }
    }

    // Early stream: be slightly more tolerant of spreading out; late stream:
    // pack tightly to close bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 6.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
