            score += 0.15 * post;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Penalize new-bin candidate (empty bin) mildly unless residual after placement is small
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let pressure = (post_residual as f64) <= 20.0;
        if pressure {
            score -= 5.0; // open a new bin only for a very tight fit
        } else {
            score += 12.0 + 0.2 * post;
        }
    }

    // Global state coupling: many open bins with high mean residual -> prefer filling existing bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let crowding = open_bins_count as f64 / (1.0 + mean_residual / cap.max(1.0));
    score += 0.05 * crowding * (1.0 - progress);

    // Penalize dead space that is too small for the smallest conceivable item
    if post_residual > 0 && post_residual < 5 {
        score += 20.0;
    }

    score
}

