        let nxt = next_item_size as f64;
        if pr >= nxt {
            let second_slack = (pr - nxt) / cap;
            if second_slack >= 0.0 && second_slack < 0.05 {
                score -= (0.05 - second_slack) * 40.0 * (0.5 + progress * 0.5);
            }
            let chain = ((post_residual / next_item_size.max(1)) as f64) * nxt / cap;
            if chain > 0.5 {
                score -= (chain - 0.5) * 14.0 * (0.5 + progress * 0.5);
            }
        } else if fitting_bins_count <= 2 {
            score += 18.0 * (1.0 - progress * 0.5);
        }
    }

    // Tiny post-residual with many open bins: mild reward to consolidate.
    if post_residual > 0 && post_norm < 0.02 && fitting_bins_count >= 4 {
        score -= 6.0 * (1.0 - progress);
    }

    // Near-multiple of next item: reserve space for repeat items.
    if next_item_size > 0 && post_residual > 0 && post_residual >= next_item_size {
        let frac = ((post_residual - next_item_size) % next_item_size.max(1)) as f64 / next_item_size.max(1) as f64;
        if frac < 0.08 {
            score -= 10.0 * (1.0 - progress * 0.5);
        }
    }

    // Two-of-next-item fit: reward when post_residual holds exactly two next items.
    if post_residual > 0 && next_item_size > 0 && pr >= (next_item_size as f64) * 2.0 && pr < (next_item_size as f64) * 2.0 + 8.0 {
        score -= 8.0 * (1.0 - progress * 0.4);
    }

    // Very tight gap bonus with few fitting bins.
    if fitting_bins_count >= 2 && bin_residual > item_size && ((bin_residual - item_size) as f64) / cap < 0.04 && post_residual > 0 {
        score -= 30.0 * (1.0 - progress * 0.4);
    }

    // Mean-residual lookahead coupling.
    if next_item_size > 0 && mean_residual > 0.0 && post_residual > 0 && post_residual >= next_item_size {
        let rel = mean_residual / cap;
        if rel > 0.25 && post_norm < rel {
            score -= (rel - post_norm) * 16.0 * (0.6 + progress * 0.5);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let poly = (1.0 - norm_pr).powi(3) * (0.5 + 2.0 * progress * progress);
    score += poly * cap * 0.25;

    // Smooth interaction: penalize large residuals late in the stream.
    score -= (progress * norm_pr * (1.0 - norm_pr)) * cap * 0.5;

    // Reward tight fits (small post_residual) more strongly as stream advances.
    score -= (1.0 - norm_pr).powi(2) * (1.0 + 3.0 * progress) * 5.0;

    // Lookahead: reward bins whose post_residual could host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 4.0 + 6.0 * progress;
    }

    // Last-chance bonus: strongly favor the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate handling: mildly penalize opening new bins early,
    // increasingly acceptable later.
    if bin_residual == bin_capacity {
        score += 12.0 - 10.0 * progress;
    }

    // Dead-space penalty: residuals too small for typical items are wasteful.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
