pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post_residual, scaled.
    score += (post_residual as f64) * 0.5;

    // Harmonic class of post_residual: exact-fit classes are golden.
    let cap = bin_capacity as f64;
    let pr = post_residual as u32;
    // Class 0: perfect fit
    if pr == 0 {
        score -= 1000.0;
    } else {
        // Fractional capacity classes: post_residual in (0,10] is dead space
        if pr <= 10 {
            score += 60.0;
        } else if pr <= 25 {
            score += 20.0;
        }
        // Harmonic classes via integer division: pr in {50..100} is "half-open" usable
        let half = (bin_capacity / 2) as u32;
        if pr >= half {
            score -= 40.0; // leaves room for typical mid-size items
        }
        // Modulo-class bonus: residual sharing a divisor class with common sizes
        if pr % 10 == 0 {
            score -= 15.0;
        } else if pr % 5 == 0 {
            score -= 7.0;
        }
    }

    // Lookahead: does next item fit into post_residual? Big reward.
    if next_item_size > 0 && next_item_size <= pr {
        // Exact lookahead fit is best
        if next_item_size == pr {
            score -= 500.0;
        } else {
            let slack = (pr - next_item_size) as f64;
            score -= 120.0 - slack * 1.5;
        }
    } else if next_item_size > 0 {
        // Next item won't fit here: penalize wasting large residual on a bad pairing
        score += 25.0;
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 80.0;
    }

    // New-bin candidate handling: keep new bins attractive only when open bins are fragmented
    if bin_residual == bin_capacity {
        let avg_frag = mean_residual / cap;
        // If existing bins are tight (small mean residual), opening fresh is fine
        score = 30.0 + avg_frag * 40.0 - (open_bins_count as f64).sqrt() * 2.0;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 20.0;
        }
    } else {
        // Prefer bins whose residual is close to item (tight packing)
        let tightness = (bin_residual - item_size) as f64 / cap;
        score += tightness * 30.0;
    }

    // Mild stream-progress term: consolidate more aggressively later
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to ever
    // accept the smallest plausible item are pure waste -> heavy penalty.
    let dead_threshold = 10.0f64; // smallest useful slot
    if (post_residual as f64) < dead_threshold {
        score += 25.0; // unusable sliver
    } else if post_residual <= 20 {
        score += 8.0; // nearly-dead gap: only tiny items can use it
    }

    // Reward near-perfect fits super-linearly.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Tightness coupling: fraction of bin consumed by this item.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 12.0 * fill_ratio;

    // Last-chance pressure: if this is the only bin that fits, strongly
    // prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // Open-bin pressure: discourage opening new bins when few bins are open,
    // encourage consolidation when many are open.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline slightly above a decent fit,
        // relaxed late in the stream when consolidation is cheap.
        score += 10.0 + 15.0 * (1.0 - progress) + 0.5 * open_bins_count as f64;
        // If no open bin fits well, opening is fine: handled by comparison.
    } else {
        score -= 0.3 * open_bins_count as f64;
    }

    // Lookahead: if next item fits into the post_residual, reward this placement.
    if next_item_size > 0 && (next_item_size as f64) <= post_residual as f64 {
        score -= 10.0;
    }
    // If next item is large and would not fit here anyway, mildly prefer
    // keeping residuals large for it.
    if next_item_size > post_residual as u32 && next_item_size > 50 {
        score += 3.0;
    }

    // Prefer bins whose residual is close to the mean (balanced packing).
    score += 0.15 * ((bin_residual as f64 - mean_residual).abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 1.18;
    score
