pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Lookahead: strongly reward when the next item fits perfectly or well in post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 1000.0; // perfect two-item closure
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 500.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot follow into this bin: penalize dead space
            let dead = post_residual as f64;
            let next_big = next_item_size as f64 > dead;
            if next_big {
                score += 0.5 * dead;
            }
        }
    }

    // Prefer bins whose residual deviates below the mean residual (tighter bins first).
    let dev = mean_residual - post_residual as f64;
    score += 0.3 * dev;

    // Last-chance bin: strong bonus to use it rather than open a new bin.
    if fitting_bins_count == 1 {
        score -= 250.0;
    }

    // Slight penalty for opening a brand-new bin when plenty of open bins can fit the item.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 40.0 + 20.0 * (1.0 - progress);
    }

    // Small tie-break toward larger post_residual fragmentation avoidance.
    score += 0.05 * (post_residual as f64 / bin_capacity as f64) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
