pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: reward residuals that are "clean"
    // fractions of capacity (multiples of 10, 20, 25, 50) which future items
    // (sizes 1..100) are statistically more likely to fill.
    let pr = post_residual;
    let mut class_bonus = 0.0;
    if pr % 50 == 0 { class_bonus += 12.0; }
    else if pr % 25 == 0 { class_bonus += 7.0; }
    else if pr % 20 == 0 { class_bonus += 5.0; }
    else if pr % 10 == 0 { class_bonus += 3.0; }
    else if pr % 5 == 0 { class_bonus += 1.0; }
    score -= class_bonus;

    // Perfect fit: zero residual is ideal.
    if pr == 0 { score -= 40.0; }

    // Dead-space penalty: small unusable residuals (1..=9) are wasted space.
    if pr > 0 && pr < 10 { score += 15.0; }

    // Lookahead coupling: reward residuals that can exactly hold the next item,
    // penalize residuals that almost-but-not-quite fit it.
    if next_item_size > 0 {
        if next_item_size == pr { score -= 20.0; }
        else if next_item_size < pr {
            let r2 = pr - next_item_size;
            if r2 % 10 == 0 { score -= 6.0; }
            if r2 < 10 { score += 4.0; }
        } else {
            // next item cannot fit here; mildly penalize this bin
            score += 5.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits,
    // avoiding a new bin opening.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate: penalize opening a new bin, more so when good
    // fitting bins exist and the stream is early (many future items to pack).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 + 25.0 * (1.0 - progress) + (fitting_bins_count as f64).min(5.0) * 3.0;
        // but if item is huge relative to mean residual, opening fresh is fine
        if item_size as f64 > mean_residual + 15.0 { score -= 20.0; }
    }

    // Tightness reward: the fuller the bin becomes, the better.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 10.0 * fill_ratio;

    // Spread across many open bins is bad; prefer consolidating when many bins open.
    score += (open_bins_count as f64).ln().max(0.0) * 2.0;

    // Mild tie-break toward bins with residual close to item size.
    score += (bin_residual as f64 - item_size as f64).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
