pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is ideal: strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Strict dead-space avoidance: any leftover gap smaller than the smallest
    // possible item (1) is impossible, but gaps below a "useful threshold"
    // relative to typical item sizes are nearly unusable. Penalize small
    // nonzero residuals harshly with a non-linear bump.
    if post_residual > 0 {
        let pr = post_residual as f64;
        if pr < 10.0 {
            // dead space zone: gap too small for most items
            score += (10.0 - pr) * 25.0;
        } else if pr < 25.0 {
            // marginal zone: moderately discouraged
            score += (25.0 - pr) * 4.0;
        }
        // Reward residuals that can host the lookahead item (chain packing).
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 30.0 + 0.5 * next_item_size as f64;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using
    // it over opening a new bin (unless post_residual is tiny dead space).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
        if post_residual > 0 && post_residual < 10 {
            score += 60.0; // still penalize creating dead space
        }
    }

    // New-bin candidate: reserve it for poor fits. A fresh bin has full
    // residual; make it attractive only when this placement would leave
    // unusable dead space in an existing bin.
    if bin_residual == bin_capacity {
        // baseline cost of opening a new bin
        score = bin_capacity as f64 * 0.9 + open_bins_count as f64 * 3.0;
        if post_residual >= 10 {
            score -= 20.0; // fresh bin keeps large usable space
        }
    }

    // Open-bin pressure: mildly discourage spreading across many bins.
    score += open_bins_count as f64 * 0.8;

    // Late in the stream, prefer tightening existing bins (fewer leftover bins).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += progress * mean_residual * 0.05;

    score
}

