pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward exact or near-exact fits.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Non-linear penalty for wasted space, amplified for small residuals.
        let pr = post_residual as f64;
        score += 40.0 * (pr / bin_capacity as f64).powf(2.5) * 100.0;
        // Bonus when the next item exactly matches the post residual (2-step lookahead).
        if next_item_size > 0 && next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 120.0 - 2.0 * slack;
        }
        // Penalize when next item fits but leaves awkward residue relative to mean residual.
        if next_item_size > 0 && next_item_size <= post_residual {
            let next_post = (post_residual - next_item_size) as f64;
            score += 0.3 * (next_post - mean_residual).abs();
        }
    }

    // Last-chance bin: reward using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 60.0;
    }

    // Penalize bins that are already crowded below mean residual (fragmentation risk).
    let res = bin_residual as f64;
    if res < mean_residual {
        score += 0.5 * (mean_residual - res);
    } else {
        score -= 0.2 * (res - mean_residual);
    }

    // Slight preference for consolidating into fewer bins when many are open.
    score += 0.05 * open_bins_count as f64;

    // Mild phase-dependent tuning: early stream favors tight packing.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 20.0 * (1.0 - progress) * (1.0 - post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: allow opening only when fit is poor.
    if bin_residual == bin_capacity {
        score += 150.0 - 0.5 * item_size as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
