pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let post_norm = pr / cap;
    let mut score = post_norm * post_norm * 50.0 + post_norm * 20.0;

    // Exact / near-exact fits strongly preferred.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 42.0;
    } else if post_residual <= 9 {
        score -= 18.0 * (1.0 - progress * 0.4);
    }

    // Dead-space floor: residuals too small for likely future items are waste.
    let dead_floor = if next_item_size > 0 { (next_item_size.min(12) as f64).max(6.0) } else { 10.0 };
    if post_residual > 0 && pr < dead_floor {
        score += 62.0 * (1.0 - progress * 0.3);
    } else if post_residual < 20 {
        score += 25.0;
    }

    // 2-step lookahead: reward leaving exactly room for the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64 / cap;
        score -= (-slack * slack * 450.0).exp() * 24.0 * (1.0 - progress * 0.5);
        // Reward multi-item chaining potential.
        let chain = ((post_residual / next_item_size.max(1)) as f64) * (next_item_size as f64) / cap;
        if chain > 0.5 {
            score -= (chain - 0.5) * 14.0 * (0.5 + progress * 0.5);
        }
    }

    // Tight gap bonus on pre-fit residual.
    let gap = (bin_residual - item_size) as f64 / cap;
    if gap > 0.0 && gap < 0.12 {
        score -= (0.12 - gap) * 48.0;
    } else if gap >= 0.12 && gap < 0.22 && fitting_bins_count <= 3 {
        score += (gap - 0.12) * 18.0 * (0.5 + progress * 0.5);
    }

    // Penalize leaving dead space the next item cannot use.
    if next_item_size > 0 && pr > 0.0 && (post_residual as u32) < next_item_size && post_norm > 0.03 {
        let dead_ratio = (next_item_size as f64 - pr) / cap;
        score += dead_ratio * 90.0 * (0.6 + progress * 0.6);
    }
    if next_item_size > 0 && post_residual > 0 && (post_residual as u32) < next_item_size && fitting_bins_count <= 2 {
        score += 18.0 * (1.0 - progress * 0.5);
    }

    // Mean-residual coupling: consolidate waste below the mean.
    if post_residual > 0 && mean_residual > 0.0 {
        let waste = post_norm - mean_residual / cap;
        if waste > 0.0 {
            score += waste * 30.0 * (0.4 + progress * 0.6);
        } else {
            score -= (-waste) * 10.0;
        }
        if next_item_size > 0 && (post_residual as u32) >= next_item_size {
            let rel = mean_residual / cap;
            if rel > 0.25 && post_norm < rel {
                score -= (rel - post_norm) * 16.0 * (0.6 + progress * 0.5);
            }
        }
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let size_pull = (item_size as f64 / cap) * 14.0;
        if fitting_bins_count <= 2 {
            score -= (18.0 + size_pull) * (1.0 - progress * 0.6);
        } else {
            score += 20.0 + open_bins_count as f64 * (0.5 + 0.5 * progress);
        }
        if next_item_size > 0 && fitting_bins_count <= 3 && (item_size as f64) >= next_item_size as f64 * 0.95 {
            score -= 5.5 * (1.0 - progress * 0.5);
        }
        if next_item_size > 0 && fitting_bins_count >= 1 && (item_size as f64) + (next_item_size as f64) > cap {
            score += 8.0 * (1.0 - progress * 0.4);
        }
        if (item_size as f64) > cap * 0.5 && progress < 0.5 {
            score -= 6.0 * (1.0 - progress);
        }
        if progress > 0.85 && (item_size as f64) / cap > 0.6 {
            score -= 4.0 * (progress - 0.85) * 20.0;
        }
        if next_item_size > 0 && (item_size as f64) + (next_item_size as f64) <= cap && (item_size as f64) / cap > 0.35 {
            score -= 3.0 * (1.0 - progress);
        }
    }

    // Micro-residual precision bonuses.
    if post_residual > 0 && post_norm > 0.0 && post_norm < 0.04 {
        score -= (0.04 - post_norm) * 55.0 * (0.7 + progress * 0.3);
    }
    if post_residual > 0 && post_norm < 0.02 && fitting_bins_count >= 4 {
        score -= 6.0 * (1.0 - progress);
    }

    // Second-item slack: reward room for next item plus a sliver.
    if next_item_size > 0 && post_residual > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let second_slack = (pr - nxt) / cap;
            if second_slack >= 0.0 && second_slack < 0.05 {
                score -= (0.05 - second_slack) * 40.0 * (0.5 + progress * 0.5);
            }
            if second_slack < 0.02 && fitting_bins_count <= 2 {
                score -= 9.0 * (1.0 - progress * 0.4);
            }
            let frac = ((pr - nxt) % nxt.max(1.0)) / nxt.max(1.0);
            if frac < 0.08 {
                score -= 10.0 * (1.0 - progress * 0.5);
            }
            let dead_after = pr - nxt;
            if dead_after > 0.0 && dead_after < nxt {
                let dr = dead_after / nxt;
                score += dr * dr * 12.0 * (0.5 + progress);
            }
        }
    }
    if post_residual > 0 && next_item_size > 0 && pr >= (next_item_size as f64) * 2.0 && pr < (next_item_size as f64) * 2.0 + 8.0 {
        score -= 8.0 * (1.0 - progress * 0.4);
    }

    // Last-chance bin: avoid opening a new bin for a decent fit.
    if fitting_bins_count == 1 && gap > 0.0 && gap < 0.06 {
        score -= 7.0 * (1.0 - progress * 0.5);
    }
    if fitting_bins_count == 1 {
        score -= 25.0;
        if pr <= 0.15 * cap {
            score -= 30.0;
        }
    }

    // Very tight fits among several candidates.
    if fitting_bins_count >= 2 && gap > 0.0 && gap < 0.04 && post_residual > 0 {
        score -= (0.04 - gap) * 30.0 * (1.0 - progress * 0.4);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;

    // Smooth non-linear polynomial coupling of post_residual with progress
    let pr_norm = pr / cap;
    let poly = pr_norm * pr_norm * (1.0 + 3.0 * progress) + pr_norm * (1.0 - progress);

    let mut score = pr + 40.0 * poly;

    // Reward tight fits smoothly (quadratic in fit_ratio)
    score -= 25.0 * fit_ratio * fit_ratio;

    // Penalize opening new bins more strongly late in the stream
    score += if bin_residual as f64 == cap { 10.0 + 60.0 * progress } else { 0.0 };

    // Last-chance bin bonus (smooth decay with fitting_bins_count)
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - progress);
    }

    // Lookahead: favor bins whose post_residual fits the next item
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 8.0;
    }

    // Mild pull toward bins near the mean residual (smooth coupling)
    score += 0.05 * (pr - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let next = next_item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items.max(1) as f64 } else { 0.0 };
    let post_norm = pr / cap;
    let fit_ratio = item_size as f64 / cap;
    let gap = (bin_residual - item_size) as f64 / cap;
    let mut score = post_norm * post_norm * 50.0 + post_norm * 20.0;

    // ---- 2-step lookahead: shape score around the NEXT item ----
    if next > 0.0 {
        if pr == next {
            score -= 54.0;
        } else if pr > next {
            let slack = pr - next;
            let diff = slack / cap;
            score -= 20.0 * (1.0 - diff).max(0.0);
            score -= (-diff * diff * 450.0).exp() * 24.0 * (1.0 - progress * 0.5);
            if diff < 0.04 {
                score -= (0.04 - diff) * 30.0 * (0.6 + progress * 0.6);
            } else if diff > 0.16 {
                score += (diff - 0.16) * 8.0 * (0.5 + progress);
            }
            // COMBINED: fine-grained residual fitting with lookahead anticipation —
            // reward when the post-residual after next item stays hostable by
            // typical small items (coupled to mean residual scale).
            let after_next = pr - next;
            let typical = mean_residual.max(1.0).min(cap * 0.25);
            if after_next > 0.0 && after_next < typical * 0.35 {
                score -= (typical * 0.35 - after_next) / cap * 22.0 * (0.5 + progress * 0.5);
            }
            // NEW: reward multi-fit chains that consume nearly all residual.
            let fits_ahead = (after_next / next).floor();
            if fits_ahead >= 2.0 {
                let chain_fill = (fits_ahead * next) / after_next;
                if chain_fill > 0.95 {
                    score -= (chain_fill - 0.95) * 60.0 * (0.5 + progress * 0.5);
                }
                let remainder = after_next - fits_ahead * next;
                let rem_norm = remainder / cap;
                if rem_norm > 0.005 {
                    score += rem_norm * 55.0 * (0.5 + progress * 0.5);
                }
            }
            // NEW: dead-after penalty when the leftover after next is a fraction
            // of next that nothing can use.
            let dead_after = after_next;
            if dead_after > 0.0 && dead_after < next {
                let dr = dead_after / next;
                score += dr * dr * 12.0 * (0.5 + progress);
            }
        } else if pr > 0.0 {
            let dead_ratio = (next - pr) / cap;
            score += dead_ratio * 90.0 * (0.6 + progress * 0.6);
