    }

    // COMBINED: two-item lookahead — prefer bins whose post-residual after the
    // next item still fits the mean-residual class with minimal slack, reducing
    // dead space variance across the stream.
    if next > 0.0 && pr >= next && fitting_bins_count > 1 && remaining > 12 {
        let after = pr - next;
        let typical = mean_residual.max(1.0);
        if after >= typical {
            let slack = (after - typical) / cap;
            if slack < 0.02 {
                score -= (0.02 - slack) * 20.0 * (0.6 + progress * 0.4);
            }
        }
    }

    // NEW (from best lineage): chain-fill bonus — post-residual that can host
    // many next-items fills more than half capacity with the next class.
    if next > 0.0 && post_residual > 0 && post_residual >= next_item_size {
        let chain = ((post_residual / next_item_size.max(1)) as f64) * next / cap;
        if chain > 0.5 {
            score -= (chain - 0.5) * 14.0 * (0.5 + progress * 0.5);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: reward tight fits (low post_residual), but heavily penalize
    // residual classes that are "dead" (too small for typical future items).
    if post_residual > 0 {
        // Harmonic class of post_residual: which capacity fraction band it lands in.
        let frac = post_residual as f64 / bin_capacity as f64;
        // Dead space: residual below ~10% is nearly unusable.
        if frac < 0.10 {
            score += 25.0 * (0.10 - frac) * bin_capacity as f64;
        } else if frac < 0.20 {
            score += 8.0;
        } else if frac < 0.35 {
            score += 2.0;
        } else if frac < 0.55 {
            score -= 3.0;
        } else {
            score -= 1.0;
        }
        // Modulo arithmetic: residuals that are multiples of common item-size
        // classes (divisible by 10 or 5) are more reusable.
        if post_residual % 10 == 0 {
            score -= 4.0;
        } else if post_residual % 5 == 0 {
            score -= 1.5;
        }
        // Integer-division threshold: post_residual can host at least one
        // average-sized item chunk (>= 20) or pair of small chunks.
        if post_residual / 20 >= 1 {
            score -= 3.0;
        }
        if post_residual / 10 >= 3 {
            score -= 1.0;
        }
    } else {
        // Perfect fill is the best outcome.
        score -= 40.0;
    }

    // Exact match with lookahead item: strongly reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual > next_item_size && post_residual - next_item_size <= 10 {
            score -= 8.0;
        } else if post_residual < next_item_size && post_residual >= 1 {
            // Residual that can't fit the known next item: dead for lookahead.
            score += 6.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid forcing a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // New-bin candidate handling: empty bin has large residual; make it
    // attractive only when the item fits poorly everywhere else.
    if bin_residual == bin_capacity {
        // Opening a new bin wastes the residual of all open bins; penalize
        // proportionally to how much space is being abandoned.
        let waste = mean_residual * open_bins_count as f64;
        score += 15.0 + waste * 0.05;
        // But late in the stream, prefer consolidating (fewer bins).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * (1.0 - progress);
        // If the current item nearly fills a fresh bin, opening is great.
        if item_size as f64 / bin_capacity as f64 > 0.8 {
            score -= 25.0;
        }
    }

    // Mild pressure against accumulating too many open bins.
    score += open_bins_count as f64 * 0.3;

    // Prefer bins whose residual is close to the item (minimize fragmentation).
    let tightness = (bin_residual - item_size) as f64 / bin_capacity as f64;
    score += tightness * 5.0;

    score
}

