    let fill_r = item_size as f64 / bin_residual.max(1) as f64;
    if fill_r > 0.90 && bin_residual != bin_capacity {
        score -= (fill_r - 0.90) * 18.0 * (0.6 + progress * 0.5);
    }

    // Waste-vs-mean term.
    if pr > 0.0 && mean_residual > 0.0 {
        let waste = post_norm - mean_residual / cap;
        if waste > 0.0 {
            score += waste * 30.0 * (0.4 + progress * 0.6);
        } else {
            score -= (-waste) * 10.0;
        }
    }

    // Penalize bins whose post-residual can never host the next item class.
    if pr > 0.0 && next > 0.0 && pr < next && post_norm > 0.03 {
        score += (next - pr) / cap * 20.0 * (0.5 + progress * 0.5);
    }

    // Reward bins that remain exactly reusable by the next item.
    if next > 0.0 && pr > 0.0 && (pr - next) / cap < 0.02 && pr >= next {
        score -= 6.0 * (1.0 - (pr - next) / cap / 0.02) * (0.5 + progress);
    }

    // Periodic divisibility bonus.
    if next > 0.0 && pr > 0.0 && pr >= next {
        let frac = ((pr - next) % next.max(1.0)) / next.max(1.0);
        if frac < 0.08 {
            score -= 10.0 * (1.0 - progress * 0.5);
        }
    }

    // Double-fit bonus.
    if next > 0.0 && pr >= next * 2.0 && pr < next * 2.0 + 8.0 {
        score -= 8.0 * (1.0 - progress * 0.4);
    }

    // Last-chance micro-gap bonus.
    if fitting_bins_count == 1 && gap > 0.0 && gap < 0.06 {
        score -= 7.0 * (1.0 - progress * 0.5);
    }

    // Dead-space penalty when few fitting bins and residual too small for next.
    if next > 0.0 && post_residual > 0 && post_residual < next_item_size && fitting_bins_count <= 2 {
        score += 18.0 * (1.0 - progress * 0.5);
    }

    // Chain-closure.
    if next > 0.0 && pr >= next && fitting_bins_count > 1 {
        let chain = pr - next;
        let chain_ref = mean_residual.max(1.0) * 0.35;
        if chain < chain_ref {
            score -= 5.0 * (1.0 - chain / chain_ref) * (0.5 + progress * 0.5);
        }
    }

    // Mid-band residual vacuum.
    if post_norm > 0.03 && post_norm < 0.10 {
        if next > 0.0 && pr >= next {
            score -= 4.0 * (1.0 - progress * 0.5);
        } else {
            score += 6.0 * (0.5 + progress * 0.5);
        }
    }

    // Fine-grained residual fitting with lookahead.
    if next > 0.0 && pr > 0.0 && pr >= next && fill_r > 0.85 {
        let reuse = (pr - next) / cap;
        if reuse < 0.06 {
            score -= (0.06 - reuse) * 30.0 * (0.5 + progress * 0.5);
        }
    }

    // Discourage residuals in the awkward 0.10–0.18 band.
    if post_norm >= 0.10 && post_norm < 0.18 && next > 0.0 && pr < next {
        score += (0.18 - post_norm) * 14.0 * (0.4 + progress * 0.6);
    }

    // Residual-consolidation with multi-fit lookahead.
    if next > 0.0 && pr >= next {
        let fits_ahead = (pr / next).floor();
        if fits_ahead >= 2.0 {
            let remainder = pr - fits_ahead * next;
            let rem_norm = remainder / cap;
            if rem_norm > 0.005 {
                score += rem_norm * 55.0 * (0.5 + progress * 0.5);
            } else {
                score -= 4.0 * (1.0 - progress * 0.4);
            }
            // COMBINED: reward when the multi-fit chain consumes nearly all
            // residual, tightening mid-size gap exploitation.
            let chain_fill = (fits_ahead * next) / pr;
            if chain_fill > 0.95 {
                score -= (chain_fill - 0.95) * 60.0 * (0.5 + progress * 0.5);
            }
        }
    }

    // Late-stream residual sweep.
    let remaining = if total_items > step_index { total_items - step_index } else { 1 };
    if remaining < 12 && post_residual > 0 {
        score += post_norm * 40.0;
    }

    // COMBINED: two-item lookahead — prefer bins whose post-residual after the
    // next item still fits the mean-residual class with minimal slack, reducing
    // dead space variance across the stream.
    if next > 0.0 && pr >= next && fitting_bins_count > 1 && remaining > 12 {
        let after = pr - next;
        let typical = mean_residual.max(1.0);
        if after >= typical {
            let slack = (after - typical) / cap;
            if slack < 0.02 {
                score -= (0.02 - slack) * 20.0 * (0.6 + progress * 0.4);
            }
        }
    }

    // MUTATION: dead-after-next quadratic penalty (from best lineage) —
    // quantify unusable remainder left after hosting the next item.
    if next > 0.0 && post_residual > 0 && pr >= next {
        let dead_after = pr - next;
        if dead_after > 0.0 && dead_after < next {
            let dr = dead_after / next;
            score += dr * dr * 12.0 * (0.5 + progress);
        }
    }

    // MUTATION: near-perfect micro-gap with competition — squeeze into bins
    // that leave <4% gap when at least one alternative exists.
    if fitting_bins_count >= 2 && gap > 0.0 && gap < 0.04 && post_residual > 0 {
        score -= (0.04 - gap) * 30.0 * (1.0 - progress * 0.4);
    }

    // MUTATION: mean-anchored residual targeting — when mean residual is large
    // and this placement lands below it, reward keeping residuals compact.
    if next > 0.0 && mean_residual > 0.0 && post_residual > 0 && pr >= next {
        let rel = mean_residual / cap;
        if rel > 0.25 && post_norm < rel {
            score -= (rel - post_norm) * 16.0 * (0.6 + progress * 0.5);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Strict dead-space avoidance ---
    // Gaps that are too small to hold even the smallest plausible item (<= 10,
    // or <= next_item_size when lookahead suggests it) are "dead" space.
    let min_useful = if next_item_size > 0 && next_item_size <= bin_capacity {
        next_item_size.min(10)
    } else {
        10
    };
    if post_residual > 0 && post_residual < min_useful {
        // Hard penalty: unusable sliver of capacity.
        score += 40.0 + (min_useful - post_residual) as f64 * 3.0;
    } else if post_residual > 0 && post_residual < 25 {
        // Soft penalty: small gaps are risky under unknown distributions.
        score += (25 - post_residual) as f64 * 1.5;
    }

    // --- Reward tight fits (best-fit amplification) ---
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 12.0;

    // --- Perfect-fit bonus ---
    if post_residual == 0 {
        score -= 30.0;
    }

    // --- Open-bin pressure: discourage spreading across many bins ---
    score += open_bins_count as f64 * 0.35;

    // --- Last-chance bin: strongly favor using the only bin that fits ---
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when:
        //  - no open bin fits well (post_residual here is huge anyway), or
        //  - mean residual across open bins is already small (fragmented bins).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0
            + mean_residual * 0.4      // high mean residual => existing bins usable, penalize new bin
            - (1.0 - progress) * 5.0;  // early stream: slightly more willing to open
        // If this new bin would leave a small dead gap too, penalize extra.
        if post_residual > 0 && post_residual < min_useful {
            score += 30.0;
        }
    } else {
        // Existing-bin alignment: prefer bins whose residual is close to item size.
        let waste = (bin_residual - item_size) as f64;
        score += (waste / bin_capacity as f64) * 8.0;
    }

    // --- Lookahead coupling: if next item could use the post_residual, reward it ---
    if next_item_size > 0 && post_residual >= next_item_size && post_residual > 0 {
        score -= 10.0;
    }

    // --- Mean-residual coupling: penalize bins far below mean residual (odd bins) ---
    score += (mean_residual - bin_residual as f64).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = 0.0;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-exact fits (post_residual close to 0).
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        score -= 40.0 * (-(post_residual as f64) / 15.0).exp();
    }

    // Dead space penalty: residual too small for the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Aggressive 2-step lookahead: strongly reward when next item fits perfectly
    // into the post-residual; penalize when post-residual is "almost" fitting
    // (wasted opportunity).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 60.0 * (-slack / 12.0).exp();
        } else {
            let overshoot = (next_item_size - post_residual) as f64;
            // Post-residual that nearly fits the next item is tempting dead space.
            score += 20.0 * (-(overshoot / 10.0).max(-6.0)).exp();
        }
    }

    // Compare against mean residual: prefer bins tighter than average.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: only attractive when no good fit exists elsewhere
    // (i.e., item leaves a large post_residual in any open bin, or nothing fits well).
    if bin_residual == bin_capacity {
        let waste = (bin_capacity - item_size) as f64;
        score += 120.0;
        // Dampen the penalty when the item is large (fills a fresh bin well).
        score -= 0.8 * item_size as f64;
        // If lookahead shows next item pairs with the remainder, opening is fine.
        if next_item_size > 0 && (next_item_size as i64 - waste as i64).abs() <= 5 {
            score -= 200.0;
        }
        // Late in the stream, avoid proliferating bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 80.0 * progress;
        // Many open bins already: discourage opening yet another.
        score += 5.0 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: quadratic bonus for small post-residual.
    let tight = (post_residual as f64 / bin_capacity as f64).powi(3);
    score -= 40.0 * (1.0 - tight);

    // Penalize leaving residual that is "awkward": too small for typical next items.
    if post_residual > 0 && post_residual < next_item_size && next_item_size > 0 {
        score += 6.0 + 0.15 * (next_item_size - post_residual) as f64;
    }

    // Lookahead: reward bins whose post-residual exactly accommodates the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > next_item_size {
        score -= 2.0 * (post_residual - next_item_size) as f64 / bin_capacity as f64;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Crowd penalty: with many open bins, prefer consolidating into fuller bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let crowd = open_bins_count as f64 / (1.0 + mean_residual / bin_capacity as f64);
    score += 0.02 * crowd * (1.0 + progress);

    // Deviation from mean residual: prefer bins whose residual is close to item fit point.
    let dev = (bin_residual as f64 - item_size as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // New-bin candidate handling: only attractive when item is large, few alternatives,
    // or stream is early (hedging for future items).
    if bin_residual == bin_capacity {
        let new_bin_base = 30.0
            + 0.3 * item_size as f64
            + 2.0 * open_bins_count as f64 * (1.0 - progress);
        let hedge = if next_item_size > post_residual && post_residual < 20 {
            0.0
        } else {
            8.0
        };
        score = new_bin_base + hedge - 20.0 * (1.0 - progress);
        if fitting_bins_count == 0 {
            score -= 40.0; // forced new bin anyway
        }
        if item_size > 70 {
            score -= 15.0; // big items pair well with fresh capacity
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let norm_post = post / cap;
    let poly = norm_post * norm_post * (1.0 + 3.0 * progress) - norm_post * (1.0 - progress);

    // Base: prefer tight fits (small post_residual), weighted more as stream progresses
    let mut score = post * (1.0 + 2.0 * progress * progress) + 40.0 * poly;

    // Penalize dead space that cannot fit the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post < nxt {
            score += 12.0 * (nxt - post) * (0.5 + progress);
        } else {
            score -= 6.0 * (1.0 - (nxt / (post + 1.0)).min(1.0)) * (1.0 - progress);
        }
    }

    // Last-chance bin bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * progress;
    }

    // Penalize opening new bins when many open bins remain usable
    if bin_residual == bin_capacity {
        score += 30.0 + 10.0 * (open_bins_count as f64).sqrt() - 15.0 * progress;
    }

    // Mild attraction toward bins deviating from mean residual (consolidation)
    score += 0.15 * (post - mean_residual).abs();

    // Small reward for filling large items into larger residuals
    score -= 0.05 * item * (1.0 - norm_post);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues modulo common capacity fractions.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Penalize post_residuals in "dead zones": small, unusable slivers
    // (residual < smallest plausible item) are wasted space.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Modulo-10 class: residual divisible by 10 is more reusable by
    // typical item sizes; reward such harmonics.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 8.0;
    }
    if post_residual % 25 == 0 && post_residual > 0 {
        score -= 6.0;
    }
    if post_residual % 50 == 0 && post_residual > 0 {
        score -= 4.0;
    }

    // Integer-division thresholds: classify post_residual into bands.
    let band = post_residual / 10; // 0..10 bands
    score += (band as f64) * 0.5;  // slight preference to leave larger residuals

    // Perfect fits are gold.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual,
    // strongly reward this placement.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            // next fits, but leaves another residual: mild reward scaled by tightness
            let tight = 1.0 - ((post_residual - next_item_size) as f64) / cap;
            score -= 6.0 + 10.0 * tight;
        } else {
            // next item cannot use this bin's residual; penalize large leftovers
            score += 3.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: make empty bins attractive only when
    // open bins would create bad fits (large post_residual mismatch).
    if bin_residual == bin_capacity {
        // baseline for a fresh bin: moderate score
        score = 55.0;
        // cheaper to open a new bin late in the stream when many bins are open
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 10.0 * progress;
        // if next item is large, a fresh bin is more valuable
        if next_item_size > bin_capacity / 2 {
            score -= 8.0;
        }
        // if next item fits perfectly in a fresh bin alongside current item
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 12.0;
        }
    }

    // Coupling with mean residual: prefer bins whose residual is below the
    // mean (tighter bins) to consolidate space.
    score += 0.15 * (mean_residual - pr).max(-50.0).min(50.0);

    // Mild penalty for spreading across too many open bins.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let next = next_item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items.max(1) as f64 } else { 0.0 };
    let post_norm = pr / cap;
    let fit_ratio = item_size as f64 / cap;
    let gap = (bin_residual - item_size) as f64 / cap;
    let mut score = post_norm * post_norm * 50.0 + post_norm * 20.0;

    // ---- 2-step lookahead: shape score around the NEXT item ----
    if next > 0.0 {
        if pr == next {
            score -= 54.0;
        } else if pr > next {
            let slack = pr - next;
            let diff = slack / cap;
            score -= 20.0 * (1.0 - diff).max(0.0);
            score -= (-diff * diff * 450.0).exp() * 24.0 * (1.0 - progress * 0.5);
            if diff < 0.04 {
                score -= (0.04 - diff) * 30.0 * (0.6 + progress * 0.6);
            } else if diff > 0.16 {
                score += (diff - 0.16) * 8.0 * (0.5 + progress);
            }
            // COMBINED: fine-grained residual fitting with lookahead anticipation —
            // reward when the post-residual after next item stays hostable by
            // typical small items (coupled to mean residual scale).
            let after_next = pr - next;
            let typical = mean_residual.max(1.0).min(cap * 0.25);
            if after_next > 0.0 && after_next < typical * 0.35 {
                score -= (typical * 0.35 - after_next) / cap * 26.0 * (0.5 + progress * 0.5);
            }
            // NEW: reward near-total consumption of residual by next item.
            let consumed = next / pr;
            if consumed > 0.92 {
                score -= (consumed - 0.92) * 45.0 * (0.5 + progress * 0.5);
            }
        } else if pr > 0.0 {
            let dead_ratio = (next - pr) / cap;
            score += dead_ratio * 90.0 * (0.6 + progress * 0.6);
        }
    }

    // ---- Absolute dead-floor guard: tiny stranded remainders ----
    let dead_floor = if next_item_size > 0 { (next_item_size.min(12) as f64).max(6.0) } else { 10.0 };
    if post_residual > 0 && pr < dead_floor && pr != next {
        score += 62.0 * (1.0 - progress * 0.3);
    } else if post_residual > 0 && post_residual < 20 && pr != next {
        score += 25.0;
    }

    // ---- Relative-to-mean coupling ----
    if pr > 0.0 {
        let dev = (mean_residual - pr) / cap;
        if dev > 0.06 {
            score += (dev - 0.06) * 10.0 * (0.4 + progress);
        } else if dev < -0.10 {
            score += (-dev - 0.10) * 5.0 * (1.0 - progress);
        }
    }

    // ---- New-bin candidate decision ----
    if bin_residual == bin_capacity {
        let others = if fitting_bins_count > 0 { fitting_bins_count - 1 } else { 0 };
        let size_pull = fit_ratio * 14.0;
        if fitting_bins_count <= 2 && gap > 0.0 {
            score -= (18.0 + size_pull) * (1.0 - progress * 0.6);
        } else if others == 0 {
            score -= 5.0;
        } else {
            score += 20.0 + open_bins_count as f64 * (0.5 + 0.5 * progress);
        }
        if next > 0.0 && fitting_bins_count <= 3 && fit_ratio >= next * 0.95 / cap {
            score -= 5.5 * (1.0 - progress * 0.5);
        }
        if next > 0.0 && fitting_bins_count >= 1 && fit_ratio * cap + next > cap {
            score += 8.0 * (1.0 - progress * 0.4);
        }
        if next > 0.0 && fit_ratio * cap + next <= cap {
            let pair_left = (cap - fit_ratio * cap - next) / cap;
            if pair_left < 0.05 {
                score -= (0.05 - pair_left) * 42.0 * (0.5 + progress * 0.5);
            } else if fit_ratio > 0.35 {
                score -= 3.0 * (1.0 - progress);
            }
        }
        if fit_ratio > 0.5 && progress < 0.5 {
            score -= 6.0 * (1.0 - progress);
        }
        if progress > 0.85 && fit_ratio > 0.6 {
            score -= 4.0 * (progress - 0.85) * 20.0;
        }
        if next > 0.0 && fit_ratio * cap + next > cap * 0.94 && fitting_bins_count > 2 {
            score -= 6.0 * (1.0 - progress * 0.5);
        }
        if progress > 0.6 && fit_ratio < 0.45 && others > 0 {
            score += 10.0 * (progress - 0.6) / 0.4;
        }
        if next > 0.0 && others > 0 {
            let fresh_left = cap - fit_ratio * cap;
            if fresh_left >= next {
                let fresh_slack = (fresh_left - next) / cap;
                if fresh_slack < 0.03 {
                    score -= (0.03 - fresh_slack) * 26.0 * (0.5 + progress * 0.5);
                }
            }
        }
        // COMBINED: only open a fresh bin when the residual chain (item, next,
        // and a third typical item) nearly fills capacity; otherwise resist.
        if next > 0.0 && others > 1 {
            let fresh_left = cap - fit_ratio * cap;
            if fresh_left >= next {
                let after = fresh_left - next;
                let typical = mean_residual.max(1.0).min(cap * 0.25);
                if after < typical {
                    score += (typical - after) / cap * 14.0 * (0.5 + progress * 0.5);
                }
            } else {
                score += 6.0 * (0.5 + progress * 0.5);
            }
        }
    }

    // Exact / near-exact fit bonuses.
    if pr == 0.0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 42.0;
    } else if post_residual <= 9 {
        score -= 18.0 * (1.0 - progress * 0.4);
    } else if post_norm < 0.02 && fitting_bins_count >= 4 {
        score -= 6.0 * (1.0 - progress);
    }
    // Borrowed: strong pull toward vanishing post-residuals.
    if post_residual > 0 && post_norm < 0.04 {
        score -= (0.04 - post_norm) * 55.0 * (0.7 + progress * 0.3);
    }

    // Sharp bonus for leaving a tiny gap (<12% of capacity).
    if gap > 0.0 && gap < 0.12 {
        score -= (0.12 - gap) * 48.0;
    } else if gap >= 0.12 && gap < 0.22 && next > 0.0 && pr > 0.0 && pr < next {
        score += (gap - 0.12) * 90.5 * (0.5 + progress);
    } else if gap >= 0.12 && gap < 0.22 && fitting_bins_count <= 3 {
        score += (gap - 0.12) * 18.0 * (0.5 + progress * 0.5);
    }
    if gap >= 0.22 && gap < 0.30 && fitting_bins_count <= 2 {
        score += (gap - 0.22) * 22.0 * (0.6 + progress * 0.4);
    }
    if next > 0.0 && gap > 0.12 {
        let nxt_gap = ((gap * cap - next).max(0.0)) / cap;
        if nxt_gap < 0.05 {
            score -= (0.05 - nxt_gap) * 40.0 * (0.5 + progress * 0.5);
        }
    }

    // Reward large items filling bins deeply.
    score -= fit_ratio * fit_ratio * 6.0;

    // Congestion: many competing bins => penalize sloppy fits.
    if fitting_bins_count > 2 {
        score += gap * 6.5 * ((fitting_bins_count.min(12) as f64 - 2.0) / 10.0);
    }
    if open_bins_count > 8 {
        score += post_norm * 5.0 * ((open_bins_count.min(20) as f64 - 8.0) / 12.0);
    }

    // Late-stream consolidation.
    if progress > 0.7 && post_norm > 0.25 {
        score += (post_norm - 0.25) * 6.0 * (progress - 0.7) / 0.3;
    }

    // Last-chance bonus.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 - fit_ratio);
    }

    // Deep fill bonus.
    let fill_r = item_size as f64 / bin_residual.max(1) as f64;
    if fill_r > 0.90 && bin_residual != bin_capacity {
        score -= (fill_r - 0.90) * 18.0 * (0.6 + progress * 0.5);
    }

    // Waste-vs-mean term.
    if pr > 0.0 && mean_residual > 0.0 {
        let waste = post_norm - mean_residual / cap;
        if waste > 0.0 {
            score += waste * 30.0 * (0.4 + progress * 0.6);
        } else {
            score -= (-waste) * 10.0;
        }
    }

    // Penalize bins whose post-residual can never host the next item class.
    if pr > 0.0 && next > 0.0 && pr < next && post_norm > 0.03 {
        score += (next - pr) / cap * 20.0 * (0.5 + progress * 0.5);
    }

    // Reward bins that remain exactly reusable by the next item.
    if next > 0.0 && pr > 0.0 && (pr - next) / cap < 0.02 && pr >= next {
        score -= 6.0 * (1.0 - (pr - next) / cap / 0.02) * (0.5 + progress);
    }

    // Periodic divisibility bonus.
    if next > 0.0 && pr > 0.0 && pr >= next {
        let frac = ((pr - next) % next.max(1.0)) / next.max(1.0);
        if frac < 0.08 {
            score -= 10.0 * (1.0 - progress * 0.5);
        }
    }

    // Double-fit bonus.
    if next > 0.0 && pr >= next * 2.0 && pr < next * 2.0 + 8.0 {
        score -= 8.0 * (1.0 - progress * 0.4);
    }

    // Last-chance micro-gap bonus.
    if fitting_bins_count == 1 && gap > 0.0 && gap < 0.06 {
        score -= 7.0 * (1.0 - progress * 0.5);
    }

    // Dead-space penalty when few fitting bins and residual too small for next.
    if next > 0.0 && post_residual > 0 && post_residual < next_item_size && fitting_bins_count <= 2 {
        score += 18.0 * (1.0 - progress * 0.5);
    }

    // Chain-closure.
    if next > 0.0 && pr >= next && fitting_bins_count > 1 {
        let chain = pr - next;
        let chain_ref = mean_residual.max(1.0) * 0.35;
        if chain < chain_ref {
            score -= 5.0 * (1.0 - chain / chain_ref) * (0.5 + progress * 0.5);
        }
    }

    // Mid-band residual vacuum.
    if post_norm > 0.03 && post_norm < 0.10 {
        if next > 0.0 && pr >= next {
            score -= 4.0 * (1.0 - progress * 0.5);
        } else {
            score += 6.0 * (0.5 + progress * 0.5);
        }
    }

    // Fine-grained residual fitting with lookahead.
    if next > 0.0 && pr > 0.0 && pr >= next && fill_r > 0.85 {
        let reuse = (pr - next) / cap;
        if reuse < 0.06 {
            score -= (0.06 - reuse) * 30.0 * (0.5 + progress * 0.5);
        }
    }

    // Discourage residuals in the awkward 0.10–0.18 band.
    if post_norm >= 0.10 && post_norm < 0.18 && next > 0.0 && pr < next {
        score += (0.18 - post_norm) * 14.0 * (0.4 + progress * 0.6);
    }

    // Residual-consolidation with multi-fit lookahead.
    if next > 0.0 && pr >= next {
        let fits_ahead = (pr / next).floor();
        if fits_ahead >= 2.0 {
            let remainder = pr - fits_ahead * next;
            let rem_norm = remainder / cap;
            if rem_norm > 0.005 {
                score += rem_norm * 55.0 * (0.5 + progress * 0.5);
            } else {
                score -= 4.0 * (1.0 - progress * 0.4);
            }
            // COMBINED: reward when the multi-fit chain consumes nearly all
            // residual, tightening mid-size gap exploitation.
            let chain_fill = (fits_ahead * next) / pr;
            if chain_fill > 0.95 {
                score -= (chain_fill - 0.95) * 60.0 * (0.5 + progress * 0.5);
            }
        }
    }

    // Late-stream residual sweep.
    let remaining = if total_items > step_index { total_items - step_index } else { 1 };
    if remaining < 12 && post_residual > 0 {
        score += post_norm * 40.0;
    }

    // COMBINED: two-item lookahead — prefer bins whose post-residual after the
    // next item still fits the mean-residual class with minimal slack, reducing
    // dead space variance across the stream.
    if next > 0.0 && pr >= next && fitting_bins_count > 1 && remaining > 12 {
        let after = pr - next;
        let typical = mean_residual.max(1.0);
        if after >= typical {
            let slack = (after - typical) / cap;
            if slack < 0.02 {
                score -= (0.02 - slack) * 20.0 * (0.6 + progress * 0.4);
            }
        }
    }

    // NEW: dead-after-next quadratic penalty (borrowed idea) to reduce
    // stranded slivers after the next item lands.
    if next > 0.0 && pr > 0.0 && pr >= next {
        let dead_after = pr - next;
        if dead_after > 0.0 && dead_after < next {
            let dr = dead_after / next;
            score += dr * dr * 12.0 * (0.5 + progress);
        }
    }

    // NEW: micro-gap bonus when few fitting bins compete.
    if fitting_bins_count >= 2 && gap > 0.0 && gap < 0.04 && post_residual > 0 {
        score -= (0.04 - gap) * 30.0 * (1.0 - progress * 0.4);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 200.0;
    } else {
        // Reward tight fits proportionally (smaller post_residual relative to item).
        let tightness = item_size as f64 / bin_residual.max(1) as f64;
        score -= 40.0 * tightness;
    }

    // Penalize bins whose residual is far below mean (fragmented bins).
    score += 0.5 * (mean_residual - bin_residual as f64).max(0.0);

    // Open-bin pressure: discourage spreading across many bins unless fit is good.
    if fitting_bins_count > 1 {
        score += 2.0 * open_bins_count as f64;
    }

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate logic: only attractive if no open bin fits well
    // (i.e., called on empty bin with large item or bad fits elsewhere).
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, softened when item is large.
        score += 30.0;
        score -= 0.3 * item_size as f64;
        // If the next item could use the leftover of this bin after placement,
        // opening a fresh bin is more attractive.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 50.0;
        }
        // Late in the stream, avoid opening extra bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 40.0 * progress;
    }

    // Lookahead: favor bins whose post_residual matches the next item size.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
