pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual equals next item size -> huge reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }
    // Next item fits exactly into current residual (item placed leaves room for it directly).
    if next_item_size > 0 && bin_residual == next_item_size {
        score -= 500.0;
    }

    // Penalize small dead space (< 10) that no item can use.
    if post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 15.0;
    }

    // Reward tight fits relative to mean residual.
    let pr = post_residual as f64;
    if pr < mean_residual {
        score -= (mean_residual - pr).min(60.0) * 0.5;
    } else {
        score += (pr - mean_residual).min(60.0) * 0.3;
    }

    // Last-chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate: penalize opening a new bin unless all open bins leave large waste.
    if bin_residual == bin_capacity {
        let waste_elsewhere = if fitting_bins_count > 0 {
            (bin_residual as f64 - item_size as f64) // residual after placing in new bin
        } else {
            0.0
        };
        score += 80.0;
        if next_item_size > 0 && waste_elsewhere < next_item_size as f64 {
            score -= 30.0; // fresh bin still leaves a usable slot for lookahead item
        }
        if open_bins_count == 0 {
            score -= 200.0; // no alternative: must open
        }
    }

    // Slight preference for filling bins as stream progresses.
    score += (step_index as f64 / (total_items.max(1) as f64)) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
