pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong best-fit core: prefer minimal post-residual.
    score += post_residual as f64 * 0.02;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Penalize small dead space that nothing can fill (items >= 1, so any residual is usable,
    // but very small residuals (< smallest plausible item) are dead weight).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward if next item fits into the post-residual exactly or well.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0; // chained perfect fit
        } else if next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.5;
        } else {
            // next item won't fit here; slight penalty proportional to overflow gap
            score += (next_item_size - post_residual) as f64 * 0.05;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate handling: only attractive when existing fits are poor.
    if bin_residual == bin_capacity {
        // Base penalty so open bins are preferred unless they leave bad residuals.
        score += 120.0;
        // Early in the stream, opening bins is cheap and useful (builds a pool of residuals).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 60.0;
        // If many open bins already, discourage more.
        score += open_bins_count as f64 * 3.0;
    }

    // Prefer bins whose residual is close to the mean (keep residuals homogeneous),
    // unless a tight fit is available.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.1;

    // Mild preference for fuller bins overall.
    score -= (bin_capacity - bin_residual) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
