pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 - progress) + norm_pr * progress * (1.0 - progress * progress);
    score += 8.0 * poly * cap;

    // Reward tight fits more strongly as stream progresses
    let tightness = 1.0 - norm_pr;
    score -= 6.0 * tightness * tightness * (0.5 + progress);

    // Last-chance bonus: avoid opening a new bin when this is the only fitting bin
    if fitting_bins_count == 1 {
        score -= 12.0 + 10.0 * progress;
    }

    // Lookahead: reward residual that can host the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            let slack = (pr - nx) / cap;
            score -= 4.0 * (1.0 - slack) * (1.0 - progress * 0.5);
        } else {
            score += 3.0 * (nx - pr) / cap * cap;
        }
    }

    // Penalize bins far from mean residual (imbalance), smoothed by progress
    let dev = (pr as f64 - mean_residual) / cap;
    score += 2.0 * dev * dev * (1.0 - progress);

    // Mild penalty for many open bins, encouraging consolidation early
    score += open_bins_count as f64 * progress * 0.05;

    // New-bin candidate: penalize slightly so it only wins when fits are bad
    if bin_residual == bin_capacity {
        score += 10.0 - 6.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
